CREATE OR REPLACE FUNCTION "api"."advance_consulta"("p_consulta_id" bigint, "p_line_nos" integer[], "p_target_stage" "text", "p_workflow_note" "text" DEFAULT NULL::"text", "p_consultation_scheduled_for" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_consultation_starts_at" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_consultation_ends_at" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_consultation_timezone" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'api'
    AS $$
DECLARE
  v_caller_uid uuid := auth.uid();
  v_ctx record;
  v_actor_role text;
  v_current_stage text;
  v_heterogeneous_count int;
  v_effective_tz text;
  v_updated int;
  v_trimmed_note text;
BEGIN
  IF v_caller_uid IS NULL THEN
    RAISE EXCEPTION 'not_authenticated' USING ERRCODE = '28000';
  END IF;

  IF p_consulta_id IS NULL THEN
    RAISE EXCEPTION 'not_found: p_consulta_id manquant' USING ERRCODE = 'P0001';
  END IF;

  IF p_line_nos IS NULL OR cardinality(p_line_nos) = 0 THEN
    RAISE EXCEPTION 'not_found: p_line_nos vide' USING ERRCODE = 'P0001';
  END IF;

  IF p_target_stage IS NULL OR p_target_stage = '' THEN
    RAISE EXCEPTION 'invalid_stage: p_target_stage manquant' USING ERRCODE = '42501';
  END IF;

  -- ============================================================
  -- B6 (15/05/2026) : note obligatoire pour annulation biblio
  -- ============================================================
  -- Doctrine politique : toute annulation par la biblio doit laisser
  -- une trace ecrite >= 5 chars (compromis pratique vs symbolique).
  -- Voir spec v2.1 §6.2 et §8.1.
  -- 
  -- Place ici (debut de bloc) pour fail-fast : avant tout SELECT cher
  -- (fn_get_consulta_context, etc.), on rejette les appels invalides.
  -- ============================================================
  IF p_target_stage = 'cancelada_biblioteca' THEN
    v_trimmed_note := trim(coalesce(p_workflow_note, ''));
    IF length(v_trimmed_note) < 5 THEN
      RAISE EXCEPTION 'cancel_note_required: a note workflow de pelo menos 5 caracteres e obrigatoria para anulacao pela biblioteca'
        USING ERRCODE = 'P0001',
              HINT = 'Indique brevemente o motivo da anulacao (ex: livro indisponivel, doublee com outro pedido, etc.)';
    END IF;
  END IF;

  SELECT * INTO v_ctx FROM public.fn_get_consulta_context(p_consulta_id);
  IF v_ctx.library_id IS NULL THEN
    RAISE EXCEPTION 'not_found: consulta % nao encontrada', p_consulta_id
      USING ERRCODE = 'P0001';
  END IF;

  -- F.2 v0.3 : la resolution du role retourne 'leitor' / 'librarian' /
  -- 'coordenador' / NULL (le role 'administrador' a ete supprime en F.1).
  v_actor_role := public.fn_resolve_caller_role_for_library(v_ctx.library_id);

  SELECT workflow_stage
    INTO v_current_stage
  FROM public.consulta_item_workflow_v2
  WHERE consulta_id = p_consulta_id
    AND line_no = p_line_nos[1];

  IF v_current_stage IS NULL THEN
    RAISE EXCEPTION 'not_found: linha % da consulta % nao encontrada',
      p_line_nos[1], p_consulta_id
      USING ERRCODE = 'P0001';
  END IF;

  SELECT count(*)
    INTO v_heterogeneous_count
  FROM public.consulta_item_workflow_v2
  WHERE consulta_id = p_consulta_id
    AND line_no = ANY(p_line_nos)
    AND workflow_stage IS DISTINCT FROM v_current_stage;

  IF v_heterogeneous_count > 0 THEN
    RAISE EXCEPTION 'invalid_stage: linhas com etapas heterogeneas (esperado %, % linhas diferentes)',
      v_current_stage, v_heterogeneous_count
      USING ERRCODE = '42501';
  END IF;

  IF NOT public.fn_check_consulta_transition(v_current_stage, p_target_stage, v_actor_role) THEN
    RAISE EXCEPTION 'invalid_stage: transicao % -> % nao permitida para %',
      v_current_stage, p_target_stage, COALESCE(v_actor_role, '(null)')
      USING ERRCODE = '42501';
  END IF;

  IF p_target_stage = 'consulta_agendada' AND p_consultation_starts_at IS NOT NULL THEN
    v_effective_tz := COALESCE(
      p_consultation_timezone,
      (SELECT consultation_timezone FROM public.library_service_state
        WHERE library_id = v_ctx.library_id),
      'UTC'
    );

    IF p_consultation_ends_at IS NULL THEN
      RAISE EXCEPTION 'schedule_missing: p_consultation_ends_at obrigatorio com p_consultation_starts_at'
        USING ERRCODE = 'P0001';
    END IF;

    v_updated := public.fn_v2_set_consulta_linhas_workflow_slot(
      p_consulta_id,
      p_line_nos,
      p_target_stage,
      p_workflow_note,
      to_char(p_consultation_starts_at AT TIME ZONE v_effective_tz, 'YYYY-MM-DD'),
      to_char(p_consultation_starts_at AT TIME ZONE v_effective_tz, 'HH24:MI'),
      to_char(p_consultation_ends_at   AT TIME ZONE v_effective_tz, 'HH24:MI'),
      v_effective_tz
    );

  ELSIF p_target_stage = 'consulta_agendada' AND p_consultation_scheduled_for IS NULL THEN
    RAISE EXCEPTION 'schedule_missing: p_consultation_scheduled_for ou p_consultation_starts_at obrigatorio'
      USING ERRCODE = 'P0001';

  ELSE
    v_updated := public.fn_v2_set_consulta_linhas_workflow(
      p_consulta_id,
      p_line_nos,
      p_target_stage,
      p_workflow_note,
      p_consultation_scheduled_for
    );
  END IF;

  RETURN jsonb_build_object('ok', true, 'updated_count', v_updated);
END;
$$;


ALTER FUNCTION "api"."advance_consulta"("p_consulta_id" bigint, "p_line_nos" integer[], "p_target_stage" "text", "p_workflow_note" "text", "p_consultation_scheduled_for" timestamp with time zone, "p_consultation_starts_at" timestamp with time zone, "p_consultation_ends_at" timestamp with time zone, "p_consultation_timezone" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "api"."advance_consulta"("p_consulta_id" bigint, "p_line_nos" integer[], "p_target_stage" "text", "p_workflow_note" "text", "p_consultation_scheduled_for" timestamp with time zone, "p_consultation_starts_at" timestamp with time zone, "p_consultation_ends_at" timestamp with time zone, "p_consultation_timezone" "text") IS 'Wrapper de transition workflow consulta (SECURITY INVOKER). Verifie role, transition autorisee, invariants schedule_missing et cancel_note_required. Cf. spec consultas v2.1 §6.2, §6.4 (R1 invariant schedule_missing), §6.2 et §8.1 (B6 note obligatoire annulation biblio, fix 15/05/2026).';



CREATE OR REPLACE FUNCTION "api"."advance_reservation"("p_reserva_id" bigint, "p_line_no" integer, "p_target_stage" "text", "p_options" "jsonb" DEFAULT '{}'::"jsonb") RETURNS integer
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'api'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_library_id uuid;
  v_current_stage text;
  v_actor_role text;
  v_note text;
  v_pickup timestamptz;
  v_n integer;
  v_proposed_by_arg text;
  v_clear_reply boolean;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'auth_required' USING ERRCODE = '42501';
  END IF;

  IF p_target_stage IN ('retirada_efetivada', 'liberada_para_circulacao', 'expirada') THEN
    RAISE EXCEPTION 'target_stage_has_dedicated_rpc'
      USING ERRCODE = '22023',
            HINT = format(
              'cible %s non autorisée via api.advance_reservation. Utilise api.confirm_pickup_v1 (retirada_efetivada) ; les autres sont automatiques (cron/trigger).',
              p_target_stage
            );
  END IF;

  IF p_target_stage = 'retirada_agendada' THEN
    RAISE EXCEPTION 'target_stage_has_dedicated_rpc'
      USING ERRCODE = '22023',
            HINT = 'cible retirada_agendada non autorisée via advance_reservation. Le seul chemin légitime est la confirmation mutuelle (api.fn_confirm_pickup_slot_as_library ou as_reader) depuis retirada_a_combinar. Utilise api.fn_propose_pickup_slot_as_library pour ouvrir une négociation.';
  END IF;

  IF p_target_stage = 're-retirada_agendada' THEN
    RAISE EXCEPTION 'target_stage_deprecated'
      USING ERRCODE = '22023',
            HINT = 'cible re-retirada_agendada dépréciée par le refactor v3. Utilise retirada_a_combinar pour la négociation symétrique.';
  END IF;

  SELECT r.library_id, riw.workflow_stage
    INTO v_library_id, v_current_stage
  FROM public.reservas_v2 r
  JOIN public.reserva_item_workflow_v2 riw ON riw.reserva_id = r.id
  WHERE r.id = p_reserva_id AND riw.line_no = p_line_no;

  IF v_library_id IS NULL THEN
    RAISE EXCEPTION 'reserva_line_not_found' USING ERRCODE = '02000';
  END IF;

  v_actor_role := public.fn_resolve_caller_role_for_library(v_library_id);
  IF v_actor_role IS NULL THEN
    RAISE EXCEPTION 'not_staff_of_this_library' USING ERRCODE = '42501';
  END IF;

  IF NOT public.fn_check_workflow_transition(v_current_stage, p_target_stage, v_actor_role) THEN
    RAISE EXCEPTION 'transition_not_allowed'
      USING ERRCODE = '22023',
            HINT = format(
              'transition %s → %s refusée pour rôle %s',
              v_current_stage, p_target_stage, v_actor_role
            );
  END IF;

  v_note := p_options->>'note';
  v_pickup := CASE
    WHEN p_options ? 'pickup_scheduled_for'
      THEN (p_options->>'pickup_scheduled_for')::timestamptz
    ELSE NULL
  END;

  IF p_target_stage IN ('retirada_a_combinar') AND v_pickup IS NULL THEN
    RAISE EXCEPTION 'pickup_scheduled_for_required'
      USING ERRCODE = '22023',
            HINT = format(
              'cible %s requiert p_options->>''pickup_scheduled_for'' (timestamptz). Même approximatif, indique un créneau initial pour ouvrir la négociation.',
              p_target_stage
            );
  END IF;

  -- Refactor paquet6 fix-up 2026-05-09 : déterminer les valeurs des nouveaux
  -- paramètres du helper selon le stage cible.
  IF p_target_stage = 'retirada_a_combinar' THEN
    -- Ouverture (ou relance) de la négociation par la biblio
    v_proposed_by_arg := 'biblio';
    v_clear_reply := true;
  ELSE
    -- Toute autre cible : la négociation est close → forcer NULL
    v_proposed_by_arg := '__CLEAR__';
    v_clear_reply := true;
  END IF;

  v_n := public.fn_v2_set_reserva_linhas_workflow(
    p_reserva_id,
    ARRAY[p_line_no],
    p_target_stage,
    v_note,
    v_pickup,
    v_proposed_by_arg,
    v_clear_reply
  );

  RETURN v_n;
END;
$$;


ALTER FUNCTION "api"."advance_reservation"("p_reserva_id" bigint, "p_line_no" integer, "p_target_stage" "text", "p_options" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "api"."advance_reservation"("p_reserva_id" bigint, "p_line_no" integer, "p_target_stage" "text", "p_options" "jsonb") IS 'Fait progresser une ligne de réservation vers un stage cible. Réservé au staff. Refactor v3 (2026-05-09) : retirada_agendada non accessible (passer par fn_confirm_*), re-retirada_agendada déprécié. Cible retirada_a_combinar set automatiquement pickup_proposed_by = ''biblio''. Cibles exclues : retirada_efetivada (api.confirm_pickup_v1), liberada_para_circulacao (trigger auto), expirada (cron). Spec refactor v3.';



CREATE OR REPLACE FUNCTION "api"."attach_exemplar"("p_book_id" bigint, "p_tombo" "text" DEFAULT NULL::"text", "p_circulation_policy" "text" DEFAULT NULL::"text", "p_visibility" "text" DEFAULT NULL::"text", "p_acquisition_mode" "text" DEFAULT NULL::"text", "p_acquisition_date" "date" DEFAULT NULL::"date", "p_provenance_note" "text" DEFAULT NULL::"text", "p_source_library" "text" DEFAULT NULL::"text") RETURNS bigint
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_uid          uuid := auth.uid();
  v_library_id   uuid;
  v_role         text;
  v_bib_ref      text;
  v_pol          text := nullif(btrim(lower(coalesce(p_circulation_policy, ''))), '');
  v_vis          text := nullif(btrim(lower(coalesce(p_visibility, ''))), '');
  v_holding_id   bigint;
  v_draft_id     bigint;
  v_exemplar_id  bigint;
begin
  -- auth
  if v_uid is null then
    raise exception 'auth_required'
      using errcode = '28000', hint = 'Authentification obrigatoria.';
  end if;

  -- biblio courante = membership actif principal ; doit etre staff
  select ulm.library_id, ulm.role
    into v_library_id, v_role
  from public.user_library_memberships ulm
  where ulm.user_id = v_uid
    and ulm.status = 'active'
    and ulm.is_primary = true
  limit 1;

  if v_library_id is null then
    raise exception 'library_not_identified'
      using errcode = 'P0001',
            hint = 'Nenhuma biblioteca ativa/principal encontrada para o usuario atual.';
  end if;

  if v_role not in ('librarian', 'coordenador') then
    raise exception 'not_staff_of_this_library'
      using errcode = '42501',
            hint = 'Esta acao esta reservada a equipe da biblioteca.';
  end if;

  -- garde-fous d'enum (laisse passer null = defaut/seed)
  if v_pol is not null and v_pol not in ('emprestavel', 'consulta', 'ambos') then
    raise exception 'invalid_circulation_policy: %', p_circulation_policy
      using errcode = '22023',
            hint = 'Padrao de circulacao invalido (emprestavel|consulta|ambos).';
  end if;
  if v_vis is not null and v_vis not in ('public', 'staff_only') then
    raise exception 'invalid_visibility: %', p_visibility
      using errcode = '22023',
            hint = 'Visibilidade invalida (public|staff_only).';
  end if;

  -- notice cible : doit exister (notice publiee, partagee reseau)
  select b.bib_ref into v_bib_ref
  from public.books b
  where b.id = p_book_id;

  if not found then
    raise exception 'book_not_found: %', p_book_id
      using errcode = 'P0001',
            hint = format('Ficha %s nao encontrada.', p_book_id);
  end if;

  -- get-or-create du holding local (Camada 2) pour (notice, biblio courante)
  insert into public.book_holdings (book_id, library_id)
  values (p_book_id, v_library_id)
  on conflict (book_id, library_id) do update
    set updated_at = now()
  returning id into v_holding_id;

  -- brouillon d'exemplaire deja resolu sur le holding ; attributs optionnels.
  -- circulation_policy null => publish_exemplar_draft seede depuis la notice (P1.2).
  insert into public.exemplar_drafts (
    action, status,
    target_library_id, target_holding_id, target_bib_ref,
    tombo,
    circulation_policy, visibility,
    acquisition_mode, acquisition_date, provenance_note, source_library,
    created_by, updated_by
  )
  values (
    'create', 'ready',
    v_library_id, v_holding_id, v_bib_ref,
    nullif(btrim(coalesce(p_tombo, '')), ''),
    v_pol,
    coalesce(v_vis, 'public'),
    nullif(btrim(coalesce(p_acquisition_mode, '')), ''),
    p_acquisition_date,
    nullif(btrim(coalesce(p_provenance_note, '')), ''),
    nullif(btrim(coalesce(p_source_library, '')), ''),
    v_uid, v_uid
  )
  returning id into v_draft_id;

  -- publication -> cree l'exemplaire (seed P1.2) et renvoie son id
  v_exemplar_id := public.publish_exemplar_draft(v_draft_id);

  -- le holding vient peut-etre d'etre cree (0/0) : recalcul des compteurs
  perform public.fn_v2_recompute_holdings_availability(array[v_holding_id]::bigint[], null);

  return v_exemplar_id;
end;
$$;


ALTER FUNCTION "api"."attach_exemplar"("p_book_id" bigint, "p_tombo" "text", "p_circulation_policy" "text", "p_visibility" "text", "p_acquisition_mode" "text", "p_acquisition_date" "date", "p_provenance_note" "text", "p_source_library" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "api"."attach_exemplar"("p_book_id" bigint, "p_tombo" "text", "p_circulation_policy" "text", "p_visibility" "text", "p_acquisition_mode" "text", "p_acquisition_date" "date", "p_provenance_note" "text", "p_source_library" "text") IS 'P1.3b (spec-exemplaires-circulation 7.1) : rattache un exemplaire a une notice partagee pour la biblioteca courante. Get-or-create du book_holding local + exemplar_draft + publish_exemplar_draft (seed P1.2). SECURITY DEFINER, controle staff interne. Retour : id du nouvel exemplaire.';



CREATE OR REPLACE FUNCTION "api"."author_subjects_v1"("p_author_id" bigint) RETURNS TABLE("subject_id" bigint, "slug" "text", "label_i18n" "jsonb", "count" integer)
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
  SELECT s.id, s.slug, s.label_i18n, count(*)::int
  FROM public.author_books_public abp
  JOIN public.book_subjects bs ON bs.book_id = abp.book_id
  JOIN public.subjects s ON s.id = bs.subject_id
  WHERE abp.author_id = p_author_id
  GROUP BY s.id, s.slug, s.label_i18n
  ORDER BY count(*) DESC, (s.label_i18n->>'pt-BR')
  LIMIT 20;
$$;


ALTER FUNCTION "api"."author_subjects_v1"("p_author_id" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "api"."cancel_consulta_as_reader"("p_consulta_id" bigint, "p_line_nos" integer[], "p_notes" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'api'
    AS $$
DECLARE
  v_caller_uid uuid := auth.uid();
  v_ctx record;
  v_updated int;
BEGIN
  IF v_caller_uid IS NULL THEN
    RAISE EXCEPTION 'not_authenticated' USING ERRCODE = '28000';
  END IF;

  IF p_consulta_id IS NULL THEN
    RAISE EXCEPTION 'not_found: p_consulta_id manquant' USING ERRCODE = 'P0001';
  END IF;

  IF p_line_nos IS NULL OR cardinality(p_line_nos) = 0 THEN
    RAISE EXCEPTION 'not_found: p_line_nos vide' USING ERRCODE = 'P0001';
  END IF;

  SELECT * INTO v_ctx FROM public.fn_get_consulta_context(p_consulta_id);
  IF v_ctx.library_id IS NULL THEN
    RAISE EXCEPTION 'not_found: consulta % nao encontrada', p_consulta_id
      USING ERRCODE = 'P0001';
  END IF;

  -- Ownership strict : invariant §11.1 #3 (eviter regression bug paquet 20 v2)
  IF v_ctx.leitor_user_id <> v_caller_uid THEN
    RAISE EXCEPTION 'not_owner: voce so pode cancelar suas proprias consultas'
      USING ERRCODE = '42501';
  END IF;

  v_updated := public.fn_v2_cancel_consulta_linhas_as_leitor(
    p_consulta_id, p_line_nos, p_notes
  );

  RETURN jsonb_build_object('ok', true, 'cancelled_count', v_updated);
END;
$$;


ALTER FUNCTION "api"."cancel_consulta_as_reader"("p_consulta_id" bigint, "p_line_nos" integer[], "p_notes" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "api"."cancel_consulta_as_reader"("p_consulta_id" bigint, "p_line_nos" integer[], "p_notes" "text") IS 'Wrapper api.* SECURITY INVOKER pour l''annulation par le lecteur (spec §6.4). Ownership check explicite. Retour : jsonb {ok, cancelled_count}.';



CREATE OR REPLACE FUNCTION "api"."cancel_my_reservation"("p_reserva_id" bigint) RETURNS integer
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'api'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_owner uuid;
  v_lines record;
  v_eligible_lines integer[];
  v_total_lines integer;
  v_blocked_count integer;
  v_n integer;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'auth_required' USING ERRCODE = '42501';
  END IF;

  -- Vérifier ownership
  SELECT user_id INTO v_owner
  FROM public.reservas_v2
  WHERE id = p_reserva_id;

  IF v_owner IS NULL THEN
    RAISE EXCEPTION 'reserva_not_found' USING ERRCODE = '02000';
  END IF;

  IF v_owner <> v_uid THEN
    RAISE EXCEPTION 'not_your_reserva' USING ERRCODE = '42501';
  END IF;

  -- Tester chaque ligne via le helper (option B : tout-ou-rien)
  v_total_lines := 0;
  v_blocked_count := 0;
  v_eligible_lines := ARRAY[]::integer[];

  FOR v_lines IN
    SELECT line_no, workflow_stage
    FROM public.reserva_item_workflow_v2
    WHERE reserva_id = p_reserva_id
  LOOP
    v_total_lines := v_total_lines + 1;
    IF public.fn_check_workflow_transition(
      v_lines.workflow_stage, 'cancelada_leitor', 'lecteur'
    ) THEN
      v_eligible_lines := array_append(v_eligible_lines, v_lines.line_no);
    ELSE
      v_blocked_count := v_blocked_count + 1;
    END IF;
  END LOOP;

  IF v_total_lines = 0 THEN
    RAISE EXCEPTION 'reserva_has_no_lines' USING ERRCODE = '02000';
  END IF;

  IF v_blocked_count > 0 THEN
    RAISE EXCEPTION 'cancel_blocked_by_stage'
      USING ERRCODE = '22023',
            HINT = format(
              'reserva %s : %s ligne(s) sur %s ne peuvent plus être annulées (état trop avancé)',
              p_reserva_id, v_blocked_count, v_total_lines
            );
  END IF;

  -- Délégation à fn_v2_*
  v_n := public.fn_v2_cancel_reserva_linhas_as_leitor(
    p_reserva_id, v_eligible_lines, NULL
  );
  RETURN v_n;
END;
$$;


ALTER FUNCTION "api"."cancel_my_reservation"("p_reserva_id" bigint) OWNER TO "postgres";


COMMENT ON FUNCTION "api"."cancel_my_reservation"("p_reserva_id" bigint) IS 'Annule toutes les lignes d''une réservation par son auteur·rice. Tout-ou-rien : si une seule ligne ne peut plus être annulée (stage trop avancé), l''opération échoue entièrement. Retourne le nombre de lignes annulées.';



CREATE OR REPLACE FUNCTION "api"."cancel_reservation_as_library"("p_reserva_id" bigint, "p_line_no" integer, "p_reason" "text" DEFAULT NULL::"text") RETURNS integer
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'api'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_library_id uuid;
  v_current_stage text;
  v_actor_role text;
  v_reason_required boolean;
  v_n integer;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'auth_required' USING ERRCODE = '42501';
  END IF;

  -- Lire contexte
  SELECT r.library_id, riw.workflow_stage
    INTO v_library_id, v_current_stage
  FROM public.reservas_v2 r
  JOIN public.reserva_item_workflow_v2 riw ON riw.reserva_id = r.id
  WHERE r.id = p_reserva_id AND riw.line_no = p_line_no;

  IF v_library_id IS NULL THEN
    RAISE EXCEPTION 'reserva_line_not_found' USING ERRCODE = '02000';
  END IF;

  -- Résoudre rôle
  v_actor_role := public.fn_resolve_caller_role_for_library(v_library_id);
  IF v_actor_role IS NULL THEN
    RAISE EXCEPTION 'not_staff_of_this_library' USING ERRCODE = '42501';
  END IF;

  -- Exclusion explicite des librarians (message clair plutôt que transition_not_allowed)
  IF v_actor_role = 'librarian' THEN
    RAISE EXCEPTION 'coordenador_required'
      USING ERRCODE = '42501',
            HINT = 'L''annulation d''une réservation par la biblio est une décision politique réservée aux coordenadores et administradores.';
  END IF;

  -- Raison conditionnelle : obligatoire si la biblio s'est déjà engagée
  -- avec un retrait planifié (stages où le lecteur attend une rencontre)
  v_reason_required := v_current_stage IN (
    'retirada_agendada',
    're-retirada_agendada',
    'retirada_a_combinar',
    'pronta_para_retirada'
  );

  IF v_reason_required AND (p_reason IS NULL OR length(btrim(p_reason)) < 5) THEN
    RAISE EXCEPTION 'reason_required_min_5_chars'
      USING ERRCODE = '22023',
            HINT = format(
              'À ce stade (%s), un retrait a été planifié avec le lecteur·rice. Une raison d''au moins 5 caractères est requise par respect.',
              v_current_stage
            );
  END IF;

  -- Validation matrice
  IF NOT public.fn_check_workflow_transition(v_current_stage, 'cancelada_biblioteca', v_actor_role) THEN
    RAISE EXCEPTION 'transition_not_allowed'
      USING ERRCODE = '22023',
            HINT = format(
              'cancelada_biblioteca refusée depuis %s pour rôle %s',
              v_current_stage, v_actor_role
            );
  END IF;

  -- Délégation : fn_v2_* fait l'annulation
  v_n := public.fn_v2_cancel_reserva_linhas_as_biblioteca(
    p_reserva_id, ARRAY[p_line_no], CASE WHEN p_reason IS NOT NULL THEN btrim(p_reason) ELSE NULL END
  );

  -- Note : le trigger trg_auto_liberate_after_no_show déclenchera ensuite
  -- automatiquement la bascule vers liberada_para_circulacao avec
  -- final_reason = 'cancelled_by_library'.

  RETURN v_n;
END;
$$;


ALTER FUNCTION "api"."cancel_reservation_as_library"("p_reserva_id" bigint, "p_line_no" integer, "p_reason" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "api"."cancel_reservation_as_library"("p_reserva_id" bigint, "p_line_no" integer, "p_reason" "text") IS 'Annule une ligne de réservation au nom de la bibliothèque (transition vers cancelada_biblioteca). Réservé aux coordenadores/administradores (pas aux librarians). Raison obligatoire ≥ 5 caractères si la biblio s''est déjà engagée avec le lecteur (stages retirada_agendada/re-retirada_agendada/retirada_a_combinar/pronta_para_retirada). Optionnelle pour solicitada/em_preparacao. Le trigger trg_auto_liberate_after_no_show déclenchera ensuite la bascule automatique vers liberada_para_circulacao avec final_reason=cancelled_by_library.';



CREATE OR REPLACE FUNCTION "api"."catalog_facets_v1"("p_filters" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public', 'pg_catalog'
    AS $_$
WITH params AS (
  SELECT
    NULLIF(btrim(p_filters->>'q'), '')          AS q,
    NULLIF(btrim(p_filters->>'author_id'), '')  AS author_id,
    NULLIF(btrim(p_filters->>'alpha'), '')      AS alpha,
    NULLIF(btrim(p_filters->>'publisher'), '')  AS publisher,
    NULLIF(btrim(p_filters->>'year_from'), '')::int AS year_from,
    NULLIF(btrim(p_filters->>'year_to'), '')::int   AS year_to,
    NULLIF(btrim(p_filters->>'library'), '')    AS library,
    NULLIF(btrim(p_filters->>'cdd'), '')        AS cdd,
    NULLIF(btrim(p_filters->>'language'), '')   AS language,
    NULLIF(btrim(p_filters->>'material'), '')   AS material,
    NULLIF(btrim(p_filters->>'collection'), '') AS collection,
    NULLIF(btrim(p_filters->>'place'), '')      AS place,
    NULLIF(btrim(p_filters->>'subject'), '')    AS subject
),
src AS (
  SELECT
    c.book_id, c.cdd, c.author_chips, c.ano,
    (
      (p.q IS NULL OR (c.titulo ILIKE '%'||p.q||'%' OR c.autor ILIKE '%'||p.q||'%'
        OR c.editora ILIKE '%'||p.q||'%' OR c.bib_ref ILIKE '%'||p.q||'%'
        OR c.cdd ILIKE '%'||p.q||'%' OR c.assuntos ILIKE '%'||p.q||'%'
        OR c.subtitulo ILIKE '%'||p.q||'%' OR c.isbn ILIKE '%'||p.q||'%'))
      AND (p.publisher IS NULL OR c.editora ILIKE '%'||p.publisher||'%')
      AND (p.library IS NULL OR c.library_slug = p.library)
      AND (p.material IS NULL OR c.tipo_material = p.material)
      AND (p.language IS NULL OR c.idioma ILIKE '%'||p.language||'%')
      AND (p.collection IS NULL OR c.colecao ILIKE '%'||p.collection||'%')
      AND (p.place IS NULL OR c.local_publicacao ILIKE '%'||p.place||'%')
    ) AS pc,
    ( (p.author_id IS NULL OR c.author_id::text = p.author_id)
      AND (p.alpha IS NULL OR c.autor ILIKE p.alpha||'%') ) AS pa,
    ( (p.year_from IS NULL OR (c.ano ~ '^\d{4}$' AND c.ano::int >= p.year_from))
      AND (p.year_to IS NULL OR (c.ano ~ '^\d{4}$' AND c.ano::int <= p.year_to)) ) AS py,
    ( p.cdd IS NULL OR c.cdd ILIKE p.cdd||'%' ) AS pcd,
    -- predicat sujet (exclu de la facette sujets)
    ( p.subject IS NULL OR EXISTS (
        SELECT 1 FROM public.book_subjects bs JOIN public.subjects s ON s.id = bs.subject_id
        WHERE bs.book_id = c.book_id AND s.slug = p.subject) ) AS psub
  FROM api.catalog_list_anon_v1 c CROSS JOIN params p
)
SELECT jsonb_build_object(
  'cdd', COALESCE((SELECT jsonb_agg(x) FROM (
      SELECT left(cdd, 3) AS code, count(*)::int AS count
      FROM src WHERE pc AND pa AND py AND psub AND cdd IS NOT NULL AND btrim(cdd) <> ''
      GROUP BY left(cdd, 3) ORDER BY 2 DESC, 1 LIMIT 40) x), '[]'::jsonb),
  'decade', COALESCE((SELECT jsonb_agg(x) FROM (
      SELECT (left(ano, 3)||'0') AS decade, count(*)::int AS count
      FROM src WHERE pc AND pa AND pcd AND psub AND ano ~ '^\d{4}$'
      GROUP BY left(ano, 3) ORDER BY 1 DESC LIMIT 30) x), '[]'::jsonb),
  'author', COALESCE((SELECT jsonb_agg(x) FROM (
      SELECT ch->>'label' AS label, max(ch->>'author_id') AS author_id, count(*)::int AS count
      FROM src, jsonb_array_elements(
             CASE jsonb_typeof(author_chips) WHEN 'array' THEN author_chips ELSE '[]'::jsonb END) ch
      WHERE pc AND pcd AND py AND psub AND ch->>'label' IS NOT NULL
      GROUP BY ch->>'label' HAVING count(*) >= 2 ORDER BY 3 DESC, 1 LIMIT 15) x), '[]'::jsonb),
  'subjects', COALESCE((SELECT jsonb_agg(x) FROM (
      SELECT s.id AS subject_id, s.slug, s.label_i18n, count(*)::int AS count
      FROM src
      JOIN public.book_subjects bs ON bs.book_id = src.book_id
      JOIN public.subjects s ON s.id = bs.subject_id
      WHERE src.pc AND src.pa AND src.py AND src.pcd   -- exclut psub (expand)
      GROUP BY s.id, s.slug, s.label_i18n
      ORDER BY count(*) DESC, (s.label_i18n->>'pt-BR') LIMIT 20) x), '[]'::jsonb)
);
$_$;


ALTER FUNCTION "api"."catalog_facets_v1"("p_filters" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "api"."clear_loan_return_schedule"("p_emprestimo_id" bigint, "p_line_nos" integer[]) RETURNS TABLE("ok" boolean, "message" "text", "return_scheduled_for" timestamp with time zone)
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'api'
    AS $$
DECLARE
  v_caller_uid uuid := auth.uid();
  v_ctx record;
  v_actor_role text;
BEGIN
  IF v_caller_uid IS NULL THEN
    RAISE EXCEPTION 'auth_required' USING ERRCODE = '28000', HINT = 'Authentification obrigatoria.';
  END IF;

  IF p_line_nos IS NULL OR array_length(p_line_nos, 1) = 0 THEN
    RAISE EXCEPTION 'line_required' USING ERRCODE = 'P0001', HINT = 'Pelo menos uma linha deve ser indicada.';
  END IF;

  SELECT * INTO v_ctx FROM public.fn_get_loan_context(p_emprestimo_id);

  IF v_ctx.library_id IS NULL THEN
    RAISE EXCEPTION 'loan_not_found' USING ERRCODE = 'P0001', HINT = format('Emprestimo %s nao encontrado.', p_emprestimo_id);
  END IF;

  v_actor_role := public.fn_resolve_caller_role_for_library(v_ctx.library_id);

  IF v_actor_role = 'leitor' AND v_ctx.leitor_user_id <> v_caller_uid THEN
    RAISE EXCEPTION 'not_your_loan' USING ERRCODE = '42501', HINT = 'Voce so pode cancelar o agendamento dos seus proprios emprestimos.';
  END IF;

  IF NOT public.fn_check_loan_action('clear_return_schedule', v_ctx.status_global, v_actor_role) THEN
    RAISE EXCEPTION 'loan_action_not_allowed' USING ERRCODE = '42501', HINT = format('Acao nao autorizada (%s/%s) sobre emprestimo %s.', v_actor_role, v_ctx.status_global, p_emprestimo_id);
  END IF;

  RETURN QUERY
  SELECT * FROM public.fn_v2_clear_emprestimo_return_schedule(
    p_emprestimo_id := p_emprestimo_id,
    p_line_nos := p_line_nos,
    p_actor_role := v_actor_role
  );
END;
$$;


