COMMENT ON FUNCTION "api"."clear_loan_return_schedule"("p_emprestimo_id" bigint, "p_line_nos" integer[]) IS 'Paquet 19 (10/05/2026) : wrapper de fn_v2_clear_emprestimo_return_schedule.
Annulation d''un agendamento de retour.';



CREATE OR REPLACE FUNCTION "api"."confirm_pickup_slot"("p_reserva_id" bigint, "p_line_no" integer) RETURNS integer
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'api'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_owner uuid;
  v_current_stage text;
  v_n integer;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'auth_required' USING ERRCODE = '42501';
  END IF;

  -- Vérifier ownership + récupérer current_stage
  SELECT r.user_id, riw.workflow_stage
    INTO v_owner, v_current_stage
  FROM public.reservas_v2 r
  JOIN public.reserva_item_workflow_v2 riw ON riw.reserva_id = r.id
  WHERE r.id = p_reserva_id AND riw.line_no = p_line_no;

  IF v_owner IS NULL THEN
    RAISE EXCEPTION 'reserva_line_not_found' USING ERRCODE = '02000';
  END IF;

  IF v_owner <> v_uid THEN
    RAISE EXCEPTION 'not_your_reserva' USING ERRCODE = '42501';
  END IF;

  -- Pickup_reply_status indépendant du workflow_stage (cf. spec §4),
  -- mais réponse seulement valide pour stages de retrait
  IF v_current_stage NOT IN ('retirada_agendada', 're-retirada_agendada', 'retirada_a_combinar') THEN
    RAISE EXCEPTION 'pickup_reply_not_applicable_in_stage'
      USING ERRCODE = '22023',
            HINT = format('stage actuel = %s, attendu retirada_agendada|re-retirada_agendada|retirada_a_combinar', v_current_stage);
  END IF;

  v_n := public.fn_v2_set_reserva_linhas_pickup_reply(
    p_reserva_id, ARRAY[p_line_no], 'confirmado_leitor', NULL
  );
  RETURN v_n;
END;
$$;


ALTER FUNCTION "api"."confirm_pickup_slot"("p_reserva_id" bigint, "p_line_no" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "api"."confirm_pickup_slot"("p_reserva_id" bigint, "p_line_no" integer) IS 'Confirme le créneau de retrait proposé par la biblio (pickup_reply_status = confirmado_leitor). Réservé au lecteur·rice propriétaire. Valide uniquement si workflow_stage IN (retirada_agendada, re-retirada_agendada, retirada_a_combinar).';



CREATE OR REPLACE FUNCTION "api"."confirm_pickup_v1"("p_reserva_id" bigint, "p_line_no" integer, "p_loan_options" "jsonb" DEFAULT '{}'::"jsonb") RETURNS bigint
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'api'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_library_id uuid;
  v_current_stage text;
  v_actor_role text;
  v_due_at date;
  v_note text;
  v_loan_id bigint;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'auth_required' USING ERRCODE = '42501';
  END IF;

  -- Lire contexte
  SELECT r.library_id, riw.workflow_stage
    INTO v_library_id, v_current_stage
  FROM public.reservas_v2 r
  JOIN public.reserva_item_workflow_v2 riw ON riw.reserva_id = r.id
  WHERE r.id = p_reserva_id AND riw.line_no = p_line_no;

  IF v_library_id IS NULL THEN
    RAISE EXCEPTION 'reserva_line_not_found' USING ERRCODE = '02000';
  END IF;

  -- Résoudre rôle (staff requis)
  v_actor_role := public.fn_resolve_caller_role_for_library(v_library_id);
  IF v_actor_role IS NULL THEN
    RAISE EXCEPTION 'not_staff_of_this_library' USING ERRCODE = '42501';
  END IF;

  -- Validation stricte du stage actuel : UNIQUEMENT pronta_para_retirada
  -- (la spec demande explicitement cette restriction pour la conversion atomique)
  IF v_current_stage <> 'pronta_para_retirada' THEN
    RAISE EXCEPTION 'pickup_only_from_pronta_para_retirada'
      USING ERRCODE = '22023',
            HINT = format(
              'stage actuel = %s, attendu pronta_para_retirada. Utilise api.advance_reservation pour les transitions intermédiaires.',
              v_current_stage
            );
  END IF;

  -- Sanity check via le helper de matrice (devrait toujours passer ici)
  IF NOT public.fn_check_workflow_transition(v_current_stage, 'retirada_efetivada', v_actor_role) THEN
    RAISE EXCEPTION 'transition_not_allowed'
      USING ERRCODE = '22023',
            HINT = format(
              'transition %s → retirada_efetivada refusée pour rôle %s (incohérence helper, à investiguer)',
              v_current_stage, v_actor_role
            );
  END IF;

  -- Extraire les options
  v_due_at := CASE
    WHEN p_loan_options ? 'due_at'
      THEN (p_loan_options->>'due_at')::date
    ELSE NULL
  END;
  v_note := p_loan_options->>'note';

  -- Délégation : fn_v2_* fait la transaction atomique
  -- (lève fn_is_loan_blocked_by_dues si cotisation bloquante)
  v_loan_id := public.fn_v2_convert_reserva_linhas_to_emprestimo(
    p_reserva_id, ARRAY[p_line_no], v_due_at, v_note
  );

  RETURN v_loan_id;
END;
$$;


ALTER FUNCTION "api"."confirm_pickup_v1"("p_reserva_id" bigint, "p_line_no" integer, "p_loan_options" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "api"."confirm_pickup_v1"("p_reserva_id" bigint, "p_line_no" integer, "p_loan_options" "jsonb") IS 'Convertit atomiquement une ligne de réservation en emprunt (transition pronta_para_retirada → retirada_efetivada). Réservé au staff de la biblio. Restriction stricte : seul le stage pronta_para_retirada autorise cette opération. La fonction sous-jacente vérifie automatiquement le statut de cotisation et calcule due_at via la politique de circulation de la biblio (sauf si fourni dans p_loan_options). Retourne le loan_id (bigint) du nouvel emprunt. p_loan_options : {"due_at": "YYYY-MM-DD", "note": "..."}.';



CREATE OR REPLACE FUNCTION "api"."create_consulta_local"("p_user_id" "uuid", "p_holding_ids" bigint[], "p_expires_at" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_notes" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'api'
    AS $$
DECLARE
  v_caller_uid uuid := auth.uid();
  v_first_holding_id bigint;
  v_library_id uuid;
  v_actor_role text;
  v_consulta_id bigint;
BEGIN
  IF v_caller_uid IS NULL THEN
    RAISE EXCEPTION 'not_authenticated' USING ERRCODE = '28000';
  END IF;

  IF p_user_id IS NULL THEN
    RAISE EXCEPTION 'not_found: p_user_id manquant' USING ERRCODE = 'P0001';
  END IF;

  IF p_holding_ids IS NULL OR cardinality(p_holding_ids) = 0 THEN
    RAISE EXCEPTION 'not_found: nenhum holding informado' USING ERRCODE = 'P0001';
  END IF;

  SELECT h
    INTO v_first_holding_id
  FROM unnest(p_holding_ids) AS h
  WHERE h IS NOT NULL
  LIMIT 1;

  IF v_first_holding_id IS NULL THEN
    RAISE EXCEPTION 'not_found: nenhum holding valido informado' USING ERRCODE = 'P0001';
  END IF;

  IF p_user_id <> v_caller_uid THEN
    SELECT library_id
      INTO v_library_id
    FROM public.book_holdings
    WHERE id = v_first_holding_id;

    IF v_library_id IS NULL THEN
      RAISE EXCEPTION 'not_found: holding % nao encontrado', v_first_holding_id
        USING ERRCODE = 'P0001';
    END IF;

    v_actor_role := public.fn_resolve_caller_role_for_library(v_library_id);

    -- F.2 v0.3 : retrait 'administrador' (role local supprime en F.1)
    IF v_actor_role NOT IN ('librarian', 'coordenador') THEN
      RAISE EXCEPTION 'not_authorized: criacao para outro leitor requer papel de staff'
        USING ERRCODE = '42501';
    END IF;
  END IF;

  v_consulta_id := public.fn_v2_create_consulta_local_by_holdings(
    p_user_id, p_holding_ids, p_expires_at, p_notes
  );

  RETURN jsonb_build_object('ok', true, 'consulta_id', v_consulta_id);
END;
$$;


ALTER FUNCTION "api"."create_consulta_local"("p_user_id" "uuid", "p_holding_ids" bigint[], "p_expires_at" timestamp with time zone, "p_notes" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "api"."create_consulta_local"("p_user_id" "uuid", "p_holding_ids" bigint[], "p_expires_at" timestamp with time zone, "p_notes" "text") IS 'Wrapper api.* SECURITY INVOKER de fn_v2_create_consulta_local_by_holdings (spec §6.1). Acces : lecteur pour soi-meme, staff pour un autre. Retour : jsonb {ok, consulta_id}.';



CREATE OR REPLACE FUNCTION "api"."create_loan_at_counter"("p_user_id" "uuid", "p_holding_ids" bigint[], "p_due_at" "date" DEFAULT NULL::"date", "p_notes" "text" DEFAULT NULL::"text") RETURNS TABLE("ok" boolean, "emprestimo_id" bigint, "due_at" "date", "message" "text")
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'api'
    AS $$
DECLARE
  v_caller_uid uuid := auth.uid();
  v_library_id uuid;
  v_actor_role text;
BEGIN
  IF v_caller_uid IS NULL THEN
    RAISE EXCEPTION 'auth_required' USING ERRCODE = '28000', HINT = 'Authentification obrigatoria.';
  END IF;

  -- Resoudre la bibliotheque active du bibliothecaire via my_access
  -- (la fonction DEFINER fn_v2_create_emprestimo_by_holdings le refait
  -- elle-meme, mais on resout ici pour la validation de role).
  SELECT ma.library_id INTO v_library_id
  FROM public.my_access ma
  LIMIT 1;

  IF v_library_id IS NULL THEN
    RAISE EXCEPTION 'library_not_identified' USING ERRCODE = 'P0001', HINT = 'Biblioteca ativa nao identificada.';
  END IF;

  -- Resoudre le role + verifier action autorisee
  v_actor_role := public.fn_resolve_caller_role_for_library(v_library_id);

  IF NOT public.fn_check_loan_action('create_loan_at_counter', NULL, v_actor_role) THEN
    RAISE EXCEPTION 'loan_action_not_allowed' USING ERRCODE = '42501', HINT = format('Acao nao autorizada para o seu papel (%s).', v_actor_role);
  END IF;

  -- Invoquer la fn DEFINER existante
  RETURN QUERY
  SELECT * FROM public.fn_v2_create_emprestimo_by_holdings(
    p_user_id := p_user_id,
    p_holding_ids := p_holding_ids,
    p_due_at := p_due_at,
    p_notes := p_notes
  );
END;
$$;


ALTER FUNCTION "api"."create_loan_at_counter"("p_user_id" "uuid", "p_holding_ids" bigint[], "p_due_at" "date", "p_notes" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "api"."create_loan_at_counter"("p_user_id" "uuid", "p_holding_ids" bigint[], "p_due_at" "date", "p_notes" "text") IS 'Paquet 19 (10/05/2026) : wrapper de fn_v2_create_emprestimo_by_holdings.
Appele depuis /painel par les bibliothecaires pour creer un emprunt
au comptoir.';



CREATE OR REPLACE FUNCTION "api"."dismiss_consulta_cancelled"("p_consulta_id" bigint, "p_line_nos" integer[], "p_note" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'api'
    AS $$
DECLARE
  v_caller_uid uuid := auth.uid();
  v_ctx record;
  v_updated int;
BEGIN
  IF v_caller_uid IS NULL THEN
    RAISE EXCEPTION 'not_authenticated' USING ERRCODE = '28000';
  END IF;

  IF p_consulta_id IS NULL THEN
    RAISE EXCEPTION 'not_found: p_consulta_id manquant' USING ERRCODE = 'P0001';
  END IF;

  IF p_line_nos IS NULL OR cardinality(p_line_nos) = 0 THEN
    RAISE EXCEPTION 'not_found: p_line_nos vide' USING ERRCODE = 'P0001';
  END IF;

  SELECT * INTO v_ctx FROM public.fn_get_consulta_context(p_consulta_id);
  IF v_ctx.library_id IS NULL THEN
    RAISE EXCEPTION 'not_found: consulta % nao encontrada', p_consulta_id
      USING ERRCODE = 'P0001';
  END IF;

  -- Ownership strict
  IF v_ctx.leitor_user_id <> v_caller_uid THEN
    RAISE EXCEPTION 'not_owner: voce so pode fechar suas proprias consultas'
      USING ERRCODE = '42501';
  END IF;

  v_updated := public.fn_v2_dismiss_consulta_cancelled_as_leitor(
    p_consulta_id, p_line_nos, p_note
  );

  RETURN jsonb_build_object('ok', true, 'dismissed_count', v_updated);
END;
$$;


