CREATE OR REPLACE FUNCTION "api"."fn_confirm_pickup_slot_as_library"("p_reserva_id" bigint, "p_line_no" integer) RETURNS integer
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'api'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_library_id uuid;
  v_current_stage text;
  v_proposed_by text;
  v_pickup_at timestamptz;
  v_actor_role text;
  v_audit_note text;
  v_n integer;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'auth_required' USING ERRCODE = '42501';
  END IF;

  SELECT
    r.library_id,
    riw.workflow_stage,
    riw.pickup_proposed_by,
    riw.pickup_scheduled_for
  INTO
    v_library_id,
    v_current_stage,
    v_proposed_by,
    v_pickup_at
  FROM public.reservas_v2 r
  JOIN public.reserva_item_workflow_v2 riw ON riw.reserva_id = r.id
  WHERE r.id = p_reserva_id AND riw.line_no = p_line_no;

  IF v_library_id IS NULL THEN
    RAISE EXCEPTION 'reserva_line_not_found' USING ERRCODE = '02000';
  END IF;

  v_actor_role := public.fn_resolve_caller_role_for_library(v_library_id);
  IF v_actor_role IS NULL THEN
    RAISE EXCEPTION 'not_staff_of_this_library' USING ERRCODE = '42501';
  END IF;

  IF v_current_stage <> 'retirada_a_combinar' THEN
    RAISE EXCEPTION 'pickup_confirmation_not_applicable_in_stage'
      USING ERRCODE = '22023',
            HINT = format(
              'stage actuel = %s. La confirmation n''est valide que depuis retirada_a_combinar (négociation active).',
              v_current_stage
            );
  END IF;

  IF v_proposed_by IS NULL THEN
    RAISE EXCEPTION 'pickup_no_active_proposal'
      USING ERRCODE = '22023',
            HINT = 'aucune proposition active à confirmer (pickup_proposed_by IS NULL).';
  END IF;

  IF v_proposed_by <> 'leitor' THEN
    RAISE EXCEPTION 'pickup_confirmation_wrong_proposer'
      USING ERRCODE = '22023',
            HINT = format(
              'pickup_proposed_by = %s. La biblio ne peut confirmer que les contre-propositions du lecteur·rice (pickup_proposed_by = ''leitor''). Si tu veux re-proposer un autre créneau, utilise fn_propose_pickup_slot_as_library.',
              v_proposed_by
            );
  END IF;

  IF NOT public.fn_check_workflow_transition(v_current_stage, 'retirada_agendada', v_actor_role) THEN
    RAISE EXCEPTION 'transition_not_allowed'
      USING ERRCODE = '22023',
            HINT = format(
              'transition %s → retirada_agendada refusée pour rôle %s (incohérence helper, à investiguer)',
              v_current_stage, v_actor_role
            );
  END IF;

  v_audit_note := format(
    '[autoconf-by-library] %s — créneau verrouillé (retirada_agendada) après contre-proposition lecteur·rice (créneau: %s)',
    to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS"Z"'),
    COALESCE(to_char(v_pickup_at AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS"Z"'), 'NULL')
  );

  -- Refactor paquet6 fix-up 2026-05-09 : appel UNIQUE au helper avec
  -- p_pickup_proposed_by='__CLEAR__' (clôture négo) et p_clear_pickup_reply=true.
  v_n := public.fn_v2_set_reserva_linhas_workflow(
    p_reserva_id,
    ARRAY[p_line_no],
    'retirada_agendada',
    v_audit_note,
    v_pickup_at,
    '__CLEAR__',  -- p_pickup_proposed_by → NULL
    true          -- p_clear_pickup_reply
  );

  RETURN v_n;
END;
$$;


ALTER FUNCTION "api"."fn_confirm_pickup_slot_as_library"("p_reserva_id" bigint, "p_line_no" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "api"."fn_confirm_pickup_slot_as_library"("p_reserva_id" bigint, "p_line_no" integer) IS 'La biblio (librarian/coordenador) accepte le créneau contre-proposé par le lecteur·rice. Refactor v3 (2026-05-09) : source = retirada_a_combinar, cible = retirada_agendada (créneau verrouillé). Réservé au staff. Précondition pickup_proposed_by = ''leitor''. Effet : transition vers retirada_agendada, pickup_proposed_by = NULL, note d''audit machine-parseable. Reset des champs legacy pickup_reply_*. Spec refactor v3.';



CREATE OR REPLACE FUNCTION "api"."fn_confirm_pickup_slot_as_reader"("p_reserva_id" bigint, "p_line_no" integer) RETURNS integer
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'api'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_owner uuid;
  v_current_stage text;
  v_proposed_by text;
  v_pickup_at timestamptz;
  v_audit_note text;
  v_n integer;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'auth_required' USING ERRCODE = '42501';
  END IF;

  SELECT
    r.user_id,
    riw.workflow_stage,
    riw.pickup_proposed_by,
    riw.pickup_scheduled_for
  INTO
    v_owner,
    v_current_stage,
    v_proposed_by,
    v_pickup_at
  FROM public.reservas_v2 r
  JOIN public.reserva_item_workflow_v2 riw ON riw.reserva_id = r.id
  WHERE r.id = p_reserva_id AND riw.line_no = p_line_no;

  IF v_owner IS NULL THEN
    RAISE EXCEPTION 'reserva_line_not_found' USING ERRCODE = '02000';
  END IF;

  IF v_owner <> v_uid THEN
    RAISE EXCEPTION 'not_your_reserva' USING ERRCODE = '42501';
  END IF;

  IF v_current_stage <> 'retirada_a_combinar' THEN
    RAISE EXCEPTION 'pickup_confirmation_not_applicable_in_stage'
      USING ERRCODE = '22023',
            HINT = format(
              'stage actuel = %s. La confirmation n''est valide que depuis retirada_a_combinar (négociation active).',
              v_current_stage
            );
  END IF;

  IF v_proposed_by IS NULL THEN
    RAISE EXCEPTION 'pickup_no_active_proposal'
      USING ERRCODE = '22023',
            HINT = 'aucune proposition active à confirmer (pickup_proposed_by IS NULL).';
  END IF;

  IF v_proposed_by <> 'biblio' THEN
    RAISE EXCEPTION 'pickup_confirmation_wrong_proposer'
      USING ERRCODE = '22023',
            HINT = format(
              'pickup_proposed_by = %s. Tu ne peux confirmer que les créneaux proposés par la biblio (pickup_proposed_by = ''biblio''). Si tu veux contre-proposer un autre créneau, utilise fn_propose_pickup_slot_as_reader.',
              v_proposed_by
            );
  END IF;

  IF NOT public.fn_check_workflow_transition(v_current_stage, 'retirada_agendada', 'lecteur') THEN
    RAISE EXCEPTION 'transition_not_allowed'
      USING ERRCODE = '22023',
            HINT = format(
              'transition %s → retirada_agendada refusée pour lecteur (incohérence helper, à investiguer)',
              v_current_stage
            );
  END IF;

  v_audit_note := format(
    '[autoconf-by-reader] %s — créneau verrouillé (retirada_agendada) après proposition biblio (créneau: %s)',
    to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS"Z"'),
    COALESCE(to_char(v_pickup_at AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS"Z"'), 'NULL')
  );

  -- Refactor paquet6 fix-up 2026-05-09 : appel UNIQUE au helper avec
  -- p_pickup_proposed_by='__CLEAR__' (clôture négo) et p_clear_pickup_reply=true.
  v_n := public.fn_v2_set_reserva_linhas_workflow(
    p_reserva_id,
    ARRAY[p_line_no],
    'retirada_agendada',
    v_audit_note,
    v_pickup_at,
    '__CLEAR__',  -- p_pickup_proposed_by → NULL
    true          -- p_clear_pickup_reply
  );

  RETURN v_n;
END;
$$;


ALTER FUNCTION "api"."fn_confirm_pickup_slot_as_reader"("p_reserva_id" bigint, "p_line_no" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "api"."fn_confirm_pickup_slot_as_reader"("p_reserva_id" bigint, "p_line_no" integer) IS 'Le lecteur·rice accepte le créneau proposé par la biblio. Refactor v3 (2026-05-09) : source = retirada_a_combinar, cible = retirada_agendada (créneau verrouillé). Réservé au lecteur·rice propriétaire. Précondition pickup_proposed_by = ''biblio''. Effet : transition vers retirada_agendada, pickup_proposed_by = NULL, note d''audit machine-parseable. Reset des champs legacy pickup_reply_*. Spec refactor v3.';



CREATE OR REPLACE FUNCTION "api"."fn_my_memberships_status"() RETURNS TABLE("library_id" "uuid", "library_slug" "text", "library_name" "text", "role" "text", "status" "text", "is_primary" boolean, "physically_validated" boolean, "is_restricted" boolean, "restricted_reason" "text", "local_reader_number" "text", "membership_enabled" boolean, "dues_status" "text", "dues_blocking" boolean, "days_until_expiry" integer)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
  SELECT
    m.library_id,
    l.slug,
    COALESCE(l.short_name, l.name),
    m.role,
    m.status,
    m.is_primary,
    (m.physically_validated_at IS NOT NULL),
    m.is_restricted,
    m.restricted_reason,
    m.local_reader_number,
    COALESCE(l.membership_enabled, false),
    am.dues_status,
    public.fn_is_loan_blocked_by_dues(m.user_id, m.library_id),
    am.days_until_expiry::integer
  FROM public.user_library_memberships m
  JOIN public.libraries l ON l.id = m.library_id
  LEFT JOIN public.v_active_memberships am
    ON am.user_id = m.user_id AND am.library_id = m.library_id
  WHERE m.user_id = auth.uid()
    AND m.status <> 'removed'
  ORDER BY m.is_primary DESC, l.name;
$$;


ALTER FUNCTION "api"."fn_my_memberships_status"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "api"."fn_propose_pickup_slot_as_library"("p_reserva_id" bigint, "p_line_no" integer, "p_pickup_at" timestamp with time zone, "p_note" "text" DEFAULT NULL::"text") RETURNS integer
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'api'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_library_id uuid;
  v_current_stage text;
  v_actor_role text;
  v_n integer;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'auth_required' USING ERRCODE = '42501';
  END IF;

  IF p_pickup_at IS NULL THEN
    RAISE EXCEPTION 'pickup_scheduled_for_required'
      USING ERRCODE = '22023',
            HINT = 'p_pickup_at (timestamptz) est obligatoire pour une proposition de créneau';
  END IF;

  IF p_pickup_at < now() THEN
    RAISE EXCEPTION 'pickup_scheduled_for_in_past'
      USING ERRCODE = '22023',
            HINT = 'le créneau proposé doit être dans le futur';
  END IF;

  SELECT r.library_id, riw.workflow_stage
    INTO v_library_id, v_current_stage
  FROM public.reservas_v2 r
  JOIN public.reserva_item_workflow_v2 riw ON riw.reserva_id = r.id
  WHERE r.id = p_reserva_id AND riw.line_no = p_line_no;

  IF v_library_id IS NULL THEN
    RAISE EXCEPTION 'reserva_line_not_found' USING ERRCODE = '02000';
  END IF;

  v_actor_role := public.fn_resolve_caller_role_for_library(v_library_id);
  IF v_actor_role IS NULL THEN
    RAISE EXCEPTION 'not_staff_of_this_library' USING ERRCODE = '42501';
  END IF;

  IF v_current_stage NOT IN ('solicitada', 'em_preparacao', 'retirada_a_combinar') THEN
    RAISE EXCEPTION 'pickup_proposal_not_applicable_in_stage'
      USING ERRCODE = '22023',
            HINT = format(
              'stage actuel = %s. Les propositions de créneau sont valides depuis solicitada, em_preparacao ou retirada_a_combinar.',
              v_current_stage
            );
  END IF;

  IF NOT public.fn_check_workflow_transition(v_current_stage, 'retirada_a_combinar', v_actor_role) THEN
    RAISE EXCEPTION 'transition_not_allowed'
      USING ERRCODE = '22023',
            HINT = format(
              'transition %s → retirada_a_combinar refusée pour rôle %s',
              v_current_stage, v_actor_role
            );
  END IF;

  -- Refactor paquet6 fix-up 2026-05-09 : appel UNIQUE au helper avec
  -- p_pickup_proposed_by='biblio' et p_clear_pickup_reply=true.
  -- Plus de 2e UPDATE manuel → plus de doublon webhook.
  v_n := public.fn_v2_set_reserva_linhas_workflow(
    p_reserva_id,
    ARRAY[p_line_no],
    'retirada_a_combinar',
    p_note,
    p_pickup_at,
    'biblio',     -- p_pickup_proposed_by
    true          -- p_clear_pickup_reply
  );

  RETURN v_n;
END;
$$;


ALTER FUNCTION "api"."fn_propose_pickup_slot_as_library"("p_reserva_id" bigint, "p_line_no" integer, "p_pickup_at" timestamp with time zone, "p_note" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "api"."fn_propose_pickup_slot_as_library"("p_reserva_id" bigint, "p_line_no" integer, "p_pickup_at" timestamp with time zone, "p_note" "text") IS 'Propose ou re-propose un créneau de retrait au lecteur·rice. Réservé au staff (librarian/coordenador) de la biblio. Refactor v3 (2026-05-09) : cible toujours retirada_a_combinar (stage central de négo). Met pickup_proposed_by = ''biblio'' et reset des éventuelles réponses précédentes. Le compteur d''itérations n''est PAS incrémenté ici (semantique B). Spec refactor v3.';



CREATE OR REPLACE FUNCTION "api"."fn_propose_pickup_slot_as_reader"("p_reserva_id" bigint, "p_line_no" integer, "p_pickup_at" timestamp with time zone, "p_note" "text" DEFAULT NULL::"text") RETURNS integer
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'api'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_owner uuid;
  v_library_id uuid;
  v_current_stage text;
  v_iteration_count int;
  v_allow_counter boolean;
  v_n integer;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'auth_required' USING ERRCODE = '42501';
  END IF;

  IF p_pickup_at IS NULL THEN
    RAISE EXCEPTION 'pickup_scheduled_for_required'
      USING ERRCODE = '22023',
            HINT = 'p_pickup_at (timestamptz) est obligatoire pour une contre-proposition';
  END IF;

  IF p_pickup_at < now() THEN
    RAISE EXCEPTION 'pickup_scheduled_for_in_past'
      USING ERRCODE = '22023',
            HINT = 'le créneau proposé doit être dans le futur';
  END IF;

  SELECT
    r.user_id,
    r.library_id,
    riw.workflow_stage,
    riw.negotiation_iteration_count,
    lnp.reservation_allow_reader_counter_proposal
  INTO
    v_owner,
    v_library_id,
    v_current_stage,
    v_iteration_count,
    v_allow_counter
  FROM public.reservas_v2 r
  JOIN public.reserva_item_workflow_v2 riw ON riw.reserva_id = r.id
  LEFT JOIN public.library_notification_policies lnp ON lnp.library_id = r.library_id
  WHERE r.id = p_reserva_id AND riw.line_no = p_line_no;

  IF v_owner IS NULL THEN
    RAISE EXCEPTION 'reserva_line_not_found' USING ERRCODE = '02000';
  END IF;

  IF v_owner <> v_uid THEN
    RAISE EXCEPTION 'not_your_reserva' USING ERRCODE = '42501';
  END IF;

  IF v_current_stage <> 'retirada_a_combinar' THEN
    RAISE EXCEPTION 'pickup_counter_proposal_not_applicable_in_stage'
      USING ERRCODE = '22023',
            HINT = format(
              'stage actuel = %s. La contre-proposition n''est valide que pendant la négociation active (retirada_a_combinar).',
              v_current_stage
            );
  END IF;

  IF v_allow_counter IS NOT NULL AND v_allow_counter = false THEN
    RAISE EXCEPTION 'pickup_counter_proposal_disabled_by_library'
      USING ERRCODE = '42501',
            HINT = 'Cette bibliothèque n''accepte pas les contre-propositions de créneau. Tu peux confirmer le créneau proposé ou annuler ta réservation.';
  END IF;

  IF v_iteration_count >= 3 THEN
    RAISE EXCEPTION 'pickup_negotiation_max_iterations_reached'
      USING ERRCODE = '22023',
            HINT = 'La négociation a atteint sa limite de 3 contre-propositions. Pour finaliser, contacte directement la biblio par téléphone, mail ou de visu.';
  END IF;

  IF NOT public.fn_check_workflow_transition(v_current_stage, 'retirada_a_combinar', 'lecteur') THEN
    RAISE EXCEPTION 'transition_not_allowed'
      USING ERRCODE = '22023',
            HINT = format(
              'transition %s → retirada_a_combinar refusée pour lecteur (incohérence helper, à investiguer)',
              v_current_stage
            );
  END IF;

  -- Refactor paquet6 fix-up 2026-05-09 : appel UNIQUE au helper avec
  -- p_pickup_proposed_by='leitor' et p_clear_pickup_reply=true.
  -- Le trigger BEFORE fn_increment_negotiation_counter incrémente
  -- automatiquement le compteur sur ce seul UPDATE (1 fois, pas 2).
  v_n := public.fn_v2_set_reserva_linhas_workflow(
    p_reserva_id,
    ARRAY[p_line_no],
    'retirada_a_combinar',
    p_note,
    p_pickup_at,
    'leitor',     -- p_pickup_proposed_by
    true          -- p_clear_pickup_reply
  );

  RETURN v_n;
END;
$$;


ALTER FUNCTION "api"."fn_propose_pickup_slot_as_reader"("p_reserva_id" bigint, "p_line_no" integer, "p_pickup_at" timestamp with time zone, "p_note" "text") OWNER TO "postgres";


