CREATE OR REPLACE FUNCTION "api"."fn_set_library_theme_active"("p_library_id" "uuid", "p_active" boolean) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF NOT public.user_can_engage_library(p_library_id) THEN
    RAISE EXCEPTION 'not authorized for library %', p_library_id USING ERRCODE = '42501';
  END IF;

  UPDATE public.libraries
     SET theme_slug = CASE WHEN p_active THEN slug ELSE NULL END
   WHERE id = p_library_id;
END;
$$;


ALTER FUNCTION "api"."fn_set_library_theme_active"("p_library_id" "uuid", "p_active" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "api"."freeze_account"("p_user_id" "uuid", "p_reason" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
BEGIN
  IF v_uid IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'not_authenticated');
  END IF;

  -- Gel global = acte exceptionnel reserve aux admins reseau
  IF NOT public.fn_caller_is_network_admin() THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'not_authorized');
  END IF;

  IF p_reason IS NULL OR length(btrim(p_reason)) < 5 THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'reason_required');
  END IF;

  UPDATE public.profiles
  SET is_restricted = true,
      restricted_reason = btrim(p_reason),
      restricted_since = now(),
      restricted_by = v_uid
  WHERE id = p_user_id;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'profile_not_found');
  END IF;

  PERFORM public.fn_dispatch_notify_event('member_frozen_global', 1,
    jsonb_build_object('user_id', p_user_id::text, 'reason', btrim(p_reason), 'at', now()::text));

  RETURN jsonb_build_object('ok', true, 'user_id', p_user_id);
END;
$$;


ALTER FUNCTION "api"."freeze_account"("p_user_id" "uuid", "p_reason" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "api"."freeze_account"("p_user_id" "uuid", "p_reason" "text") IS 'EA-10 : gel GLOBAL exceptionnel d''un compte (securite reseau). Admin reseau seulement. Raison obligatoire. Trace restricted_by + restricted_since. Chantier D.';



CREATE OR REPLACE FUNCTION "api"."generate_my_reader_card"("p_library_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions'
    AS $$
DECLARE
  v_uid        uuid := auth.uid();
  v_membership public.user_library_memberships%ROWTYPE;
  v_cards_on   boolean;
  v_slug       text;
  v_token      text;
  v_token_id   uuid;
BEGIN
  IF v_uid IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'not_authenticated');
  END IF;

  -- Appartenance active a cette bibliotheque, QUEL QUE SOIT le role.
  -- (Lecture A 28/05 : reader, librarian, coordenador peuvent tous generer
  -- leur carte. Le staff emprunte aussi ; pas de hierarchie sur la carte.)
  SELECT * INTO v_membership
  FROM public.user_library_memberships
  WHERE user_id = v_uid AND library_id = p_library_id
    AND status = 'active'
  LIMIT 1;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'not_a_member');
  END IF;

  -- Capacite activee cote biblio ?
  SELECT reader_cards_enabled, slug INTO v_cards_on, v_slug
  FROM public.libraries WHERE id = p_library_id;
  IF NOT COALESCE(v_cards_on, false) THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'cards_disabled');
  END IF;

  -- Revoquer le jeton actif precedent (regeneration)
  UPDATE public.reader_card_tokens
  SET status = 'revoked', revoked_at = now(), revoked_reason = 'regenerated'
  WHERE membership_id = v_membership.id AND status = 'active';

  -- Generer le jeton opaque en clair (20 bytes = 40 hex) puis stocker son hash.
  v_token := lower(encode(gen_random_bytes(20), 'hex'));

  INSERT INTO public.reader_card_tokens
    (membership_id, user_id, library_id, token_hash, status)
  VALUES
    (v_membership.id, v_uid, p_library_id, public.fn_hash_claim_token(v_token), 'active')
  RETURNING id INTO v_token_id;

  RETURN jsonb_build_object(
    'ok', true,
    'token', v_token,
    'token_id', v_token_id,
    'library_slug', v_slug
  );
END;
$$;


ALTER FUNCTION "api"."generate_my_reader_card"("p_library_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "api"."generate_my_reader_card"("p_library_id" "uuid") IS 'Genere (ou regenere) la carte-lecteur du membre authentifie pour p_library_id. Tout membre actif (reader/librarian/coordenador), pas seulement reader (Lecture A 28/05). Revoque le jeton actif precedent. Stocke le HASH du jeton, retourne le clair une seule fois. Retour {ok, token, token_id, library_slug}.';



CREATE OR REPLACE FUNCTION "api"."get_batch_loan_projection"("p_library_id" "uuid", "p_user_id" "uuid" DEFAULT NULL::"uuid", "p_book_ids" bigint[] DEFAULT NULL::bigint[], "p_holding_ids" bigint[] DEFAULT NULL::bigint[], "p_quantity" integer DEFAULT NULL::integer, "p_as_of_date" "date" DEFAULT NULL::"date") RETURNS TABLE("quantity" integer, "due_date" "date", "loan_allowed" boolean, "consultation_only" boolean, "policy_set_id" bigint, "rule_id" bigint, "rule_label" "text", "explanation" "text")
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'api', 'auth', 'pg_temp'
    AS $$
  with q as (
    select greatest(
      coalesce(
        p_quantity,
        nullif(cardinality(coalesce(p_holding_ids, '{}'::bigint[])), 0),
        nullif(cardinality(coalesce(p_book_ids, '{}'::bigint[])), 0),
        1
      ),
      1
    ) as resolved_quantity
  )
  select
    q.resolved_quantity as quantity,
    r.resolved_due_date as due_date,
    r.loan_allowed,
    r.consultation_only,
    r.policy_set_id,
    r.rule_id,
    r.rule_label,
    r.explanation
  from q
  cross join lateral api.resolve_circulation_rule(
    p_library_id := p_library_id,
    p_mode := 'loan',
    p_user_id := p_user_id,
    p_book_id := (
      case
        when cardinality(coalesce(p_book_ids, '{}'::bigint[])) >= 1 then p_book_ids[1]
        else null
      end
    ),
    p_holding_id := (
      case
        when cardinality(coalesce(p_holding_ids, '{}'::bigint[])) >= 1 then p_holding_ids[1]
        else null
      end
    ),
    p_quantity := q.resolved_quantity,
    p_as_of_date := p_as_of_date,
    p_current_due_date := null,
    p_renewals_used := 0
  ) r;
$$;


