CREATE OR REPLACE FUNCTION "api"."get_due_date_for_loan"("p_library_id" "uuid", "p_user_id" "uuid" DEFAULT NULL::"uuid", "p_book_id" bigint DEFAULT NULL::bigint, "p_holding_id" bigint DEFAULT NULL::bigint, "p_quantity" integer DEFAULT 1, "p_as_of_date" "date" DEFAULT NULL::"date") RETURNS TABLE("due_date" "date", "loan_allowed" boolean, "consultation_only" boolean, "policy_set_id" bigint, "rule_id" bigint, "rule_label" "text", "explanation" "text")
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'api', 'auth', 'pg_temp'
    AS $$
declare
  v_dues_blocked boolean := false;
  v_dues_status text;
  v_dues_message text;
begin
  if p_user_id is not null then
    v_dues_blocked := public.fn_is_loan_blocked_by_dues(p_user_id, p_library_id);

    if v_dues_blocked then
      select dues_status into v_dues_status
      from public.v_active_memberships
      where user_id = p_user_id and library_id = p_library_id;

      v_dues_message := case v_dues_status
        when 'never_paid' then 'Contribuição obrigatória não registrada.'
        when 'expired'   then 'Contribuição vencida.'
        else                  'Contribuição obrigatória não está em dia.'
      end;

      return query
      select
        null::date as due_date,
        false      as loan_allowed,
        false      as consultation_only,
        null::bigint as policy_set_id,
        null::bigint as rule_id,
        'dues_blocked'::text as rule_label,
        v_dues_message as explanation;
      return;
    end if;
  end if;

  return query
  select
    r.resolved_due_date as due_date,
    r.loan_allowed,
    r.consultation_only,
    r.policy_set_id,
    r.rule_id,
    r.rule_label,
    r.explanation
  from api.resolve_circulation_rule(
    p_library_id := p_library_id,
    p_mode := 'loan',
    p_user_id := p_user_id,
    p_book_id := p_book_id,
    p_holding_id := p_holding_id,
    p_quantity := p_quantity,
    p_as_of_date := p_as_of_date,
    p_current_due_date := null,
    p_renewals_used := 0
  ) r;
end;
$$;


ALTER FUNCTION "api"."get_due_date_for_loan"("p_library_id" "uuid", "p_user_id" "uuid", "p_book_id" bigint, "p_holding_id" bigint, "p_quantity" integer, "p_as_of_date" "date") OWNER TO "postgres";


COMMENT ON FUNCTION "api"."get_due_date_for_loan"("p_library_id" "uuid", "p_user_id" "uuid", "p_book_id" bigint, "p_holding_id" bigint, "p_quantity" integer, "p_as_of_date" "date") IS 'Wrapper stable pour obtenir la date de retorno prevista de um empréstimo.';



CREATE OR REPLACE FUNCTION "api"."get_future_availability"("p_library_id" "uuid", "p_book_id" bigint DEFAULT NULL::bigint, "p_holding_id" bigint DEFAULT NULL::bigint) RETURNS TABLE("library_id" "uuid", "book_id" bigint, "holding_id" bigint, "holding_count" integer, "exemplares_total" integer, "available_count" integer, "next_due_at" "date", "next_pickup_scheduled_for" timestamp with time zone, "next_reservation_block_until" "date", "projected_next_available_on" "date", "status_hint" "text")
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'api', 'auth', 'pg_temp'
    AS $$
declare
  v_book_id bigint := p_book_id;
  v_holding_id bigint := p_holding_id;
begin
  if p_library_id is null then
    raise exception 'Biblioteca obrigatória para calcular disponibilidade futura.';
  end if;

  if v_holding_id is null and v_book_id is null then
    raise exception 'Informe um book_id ou um holding_id.';
  end if;

  if v_book_id is null and v_holding_id is not null then
    select h.book_id
      into v_book_id
    from public.book_holdings h
    where h.id = v_holding_id
      and h.library_id = p_library_id
    limit 1;
  end if;

  return query
  with service_ctx as (
    select
      p_library_id as library_id,
      coalesce(nullif(btrim(s.consultation_timezone), ''), 'America/Belem') as library_timezone
    from public.library_service_state s
    where s.library_id = p_library_id

    union all

    select
      p_library_id as library_id,
      'America/Belem'::text as library_timezone
    where not exists (
      select 1
      from public.library_service_state s
      where s.library_id = p_library_id
    )
  ),
  target_holdings as (
    select
      h.id,
      h.book_id,
      coalesce(h.exemplares_total, 0)::int as exemplares_total,
      coalesce(h.available_count, 0)::int as available_count
    from public.book_holdings h
    where h.library_id = p_library_id
      and (
        (v_holding_id is not null and h.id = v_holding_id)
        or (v_holding_id is null and h.book_id = v_book_id)
      )
  ),
  open_loans as (
    select
      e.holding_id,
      min(coalesce(i.extended_until, i.due_at)) as next_due_at
    from public.emprestimo_itens_v2 i
    join public.exemplares e
      on e.id = i.item_id
    where i.item_status = 'aberto'
      and e.holding_id in (select th.id from target_holdings th)
    group by e.holding_id
  ),
  reservation_quantities as (
    select
      rl.reserva_id,
      count(*) filter (where rl.item_status = 'ativa')::int as active_line_count
    from public.reserva_linhas_v2 rl
    join public.reservas_v2 r
      on r.id = rl.reserva_id
     and r.library_id = p_library_id
    where rl.item_status = 'ativa'
    group by rl.reserva_id
  ),
  reservation_projection_rows as (
    select
      rl.holding_id,
      w.pickup_scheduled_for,
      case
        when w.pickup_scheduled_for is null then null::date
        when rr.loan_days is null then null::date
        else ((w.pickup_scheduled_for at time zone sc.library_timezone)::date + rr.loan_days)
      end as projected_block_until
    from public.reserva_linhas_v2 rl
    join public.reservas_v2 r
      on r.id = rl.reserva_id
     and r.library_id = p_library_id
    left join public.reserva_item_workflow_v2 w
      on w.reserva_id = rl.reserva_id
     and w.line_no = rl.line_no
    left join reservation_quantities rq
      on rq.reserva_id = rl.reserva_id
    cross join service_ctx sc
    left join lateral api.resolve_circulation_rule(
      p_library_id := p_library_id,
      p_mode := 'loan',
      p_user_id := r.user_id,
      p_book_id := rl.book_id,
      p_holding_id := rl.holding_id,
      p_quantity := greatest(coalesce(rq.active_line_count, 1), 1),
      p_as_of_date := case
        when w.pickup_scheduled_for is null then null::date
        else (w.pickup_scheduled_for at time zone sc.library_timezone)::date
      end,
      p_current_due_date := null,
      p_renewals_used := 0
    ) rr
      on w.pickup_scheduled_for is not null
    where rl.item_status = 'ativa'
      and rl.holding_id in (select th.id from target_holdings th)
  ),
  active_reservations as (
    select
      rpr.holding_id,
      min(rpr.pickup_scheduled_for) filter (where rpr.pickup_scheduled_for is not null) as next_pickup_scheduled_for,
      min(rpr.projected_block_until) filter (where rpr.projected_block_until is not null) as next_reservation_block_until
    from reservation_projection_rows rpr
    group by rpr.holding_id
  ),
  aggregated as (
    select
      p_library_id as library_id,
      v_book_id as book_id,
      v_holding_id as holding_id,
      count(*)::int as holding_count,
      coalesce(sum(th.exemplares_total), 0)::int as exemplares_total,
      coalesce(sum(th.available_count), 0)::int as available_count,
      min(ol.next_due_at) as next_due_at,
      min(ar.next_pickup_scheduled_for) as next_pickup_scheduled_for,
      min(ar.next_reservation_block_until) as next_reservation_block_until
    from target_holdings th
    left join open_loans ol
      on ol.holding_id = th.id
    left join active_reservations ar
      on ar.holding_id = th.id
  )
  select
    a.library_id,
    a.book_id,
    a.holding_id,
    a.holding_count,
    a.exemplares_total,
    a.available_count,
    a.next_due_at,
    a.next_pickup_scheduled_for,
    a.next_reservation_block_until,
    case
      when a.available_count > 0 then null::date
      when a.next_due_at is null then a.next_reservation_block_until
      when a.next_reservation_block_until is null then a.next_due_at
      else least(a.next_due_at, a.next_reservation_block_until)
    end as projected_next_available_on,
    case
      when a.holding_count = 0 then 'indisponivel_para_a_biblioteca'
      when a.available_count > 0 then 'disponivel'
      else 'indisponivel_no_momento'
    end as status_hint
  from aggregated a;
end;
$$;


