COMMENT ON FUNCTION "api"."get_future_availability"("p_library_id" "uuid", "p_book_id" bigint, "p_holding_id" bigint) IS 'Disponibilidade futura alignée sur la politique active de circulação. La quantidade usada para projetar o bloqueio de uma reserva considera agora a reserva ativa completa na biblioteca.';



CREATE OR REPLACE FUNCTION "api"."get_library_circulation_policy_rules_ui"("p_policy_set_id" bigint) RETURNS TABLE("id" bigint, "policy_set_id" bigint, "library_id" "uuid", "library_slug" "text", "library_name" "text", "policy_label" "text", "priority" integer, "is_active" boolean, "rule_label" "text", "circulation_mode" "text", "material_scope" "text", "reader_scope" "text", "quantity_min" integer, "quantity_max" integer, "loan_allowed" boolean, "reservation_allowed" boolean, "consultation_allowed" boolean, "consultation_only" boolean, "renewable" boolean, "renewal_max_count" integer, "renewal_days" integer, "loan_days" integer, "manual_review_required" boolean, "non_extendable_reason" "text", "exception_code" "text", "public_note" "text", "internal_note" "text", "applies_when" "jsonb", "metadata" "jsonb", "created_at" timestamp with time zone, "updated_at" timestamp with time zone)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'api', 'pg_temp'
    AS $$
declare
  v_set public.library_circulation_policy_sets%rowtype;
begin
  select *
    into v_set
  from public.library_circulation_policy_sets s
  where s.id = p_policy_set_id;

  if v_set.id is null then
    raise exception 'Conjunto de regras não encontrado: %', p_policy_set_id;
  end if;

  perform public.resolve_managed_library_id(v_set.library_id);

  return query
  select
    r.id,
    r.policy_set_id,
    s.library_id,
    l.slug,
    l.name,
    s.label,
    r.priority,
    r.is_active,
    r.rule_label,
    r.circulation_mode,
    r.material_scope,
    r.reader_scope,
    r.quantity_min,
    r.quantity_max,
    r.loan_allowed,
    r.reservation_allowed,
    r.consultation_allowed,
    r.consultation_only,
    r.renewable,
    r.renewal_max_count,
    r.renewal_days,
    r.loan_days,
    r.manual_review_required,
    r.non_extendable_reason,
    r.exception_code,
    r.public_note,
    r.internal_note,
    r.applies_when,
    r.metadata,
    r.created_at,
    r.updated_at
  from public.library_circulation_policy_rules r
  join public.library_circulation_policy_sets s
    on s.id = r.policy_set_id
  join public.libraries l
    on l.id = s.library_id
  where r.policy_set_id = p_policy_set_id
  order by r.priority, r.id;
end;
$$;


