CREATE OR REPLACE FUNCTION "api"."get_library_circulation_policy_sets_ui"("p_library_id" "uuid" DEFAULT NULL::"uuid") RETURNS TABLE("id" bigint, "library_id" "uuid", "library_slug" "text", "library_name" "text", "regulation_document_id" bigint, "regulation_doc_kind" "text", "regulation_version_label" "text", "label" "text", "status" "text", "is_active" boolean, "config_version" integer, "effective_from" "date", "effective_until" "date", "activation_note" "text", "scope_note" "text", "metadata" "jsonb", "rule_count" bigint, "active_rule_count" bigint, "created_at" timestamp with time zone, "updated_at" timestamp with time zone, "activated_at" timestamp with time zone)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'api', 'pg_temp'
    AS $$
declare
  v_library_id uuid;
begin
  v_library_id := public.resolve_managed_library_id(p_library_id);

  return query
  select
    s.id,
    s.library_id,
    l.slug,
    l.name,
    s.regulation_document_id,
    d.doc_kind,
    d.version_label,
    s.label,
    s.status,
    s.is_active,
    s.config_version,
    s.effective_from,
    s.effective_until,
    s.activation_note,
    s.scope_note,
    s.metadata,
    coalesce(rc.rule_count, 0) as rule_count,
    coalesce(rc.active_rule_count, 0) as active_rule_count,
    s.created_at,
    s.updated_at,
    s.activated_at
  from public.library_circulation_policy_sets s
  join public.libraries l
    on l.id = s.library_id
  left join public.library_regulation_documents d
    on d.id = s.regulation_document_id
  left join lateral (
    select
      count(*)::bigint as rule_count,
      count(*) filter (where r.is_active)::bigint as active_rule_count
    from public.library_circulation_policy_rules r
    where r.policy_set_id = s.id
  ) rc on true
  where s.library_id = v_library_id
  order by s.is_active desc, s.activated_at desc nulls last, s.updated_at desc, s.id desc;
end;
$$;


ALTER FUNCTION "api"."get_library_circulation_policy_sets_ui"("p_library_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "api"."get_library_institutional_workspace"("p_library_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'api', 'pg_temp'
    AS $$
declare
  v_library_id uuid;
  v_library public.libraries%rowtype;
  v_service public.library_service_state%rowtype;
  v_contact public.library_contact_profiles%rowtype;
  v_governance public.library_document_governance%rowtype;
  v_notification_ctx jsonb := '{}'::jsonb;
  v_theme_ctx jsonb := '{}'::jsonb;
  v_active_reg jsonb := 'null'::jsonb;
  v_active_policy jsonb := 'null'::jsonb;
  v_reg_docs jsonb := '[]'::jsonb;
  v_policy_sets jsonb := '[]'::jsonb;
begin
  v_library_id := public.resolve_managed_library_id(p_library_id);

  select * into v_library
  from public.libraries l
  where l.id = v_library_id;

  select * into v_service
  from public.library_service_state s
  where s.library_id = v_library_id;

  select * into v_contact
  from public.library_contact_profiles c
  where c.library_id = v_library_id;

  select * into v_governance
  from public.library_document_governance g
  where g.library_id = v_library_id;

  begin
    v_notification_ctx := coalesce(public.get_library_notification_context(v_library_id), '{}'::jsonb);
  exception when others then
    v_notification_ctx := '{}'::jsonb;
  end;

  begin
    v_theme_ctx := coalesce(public.get_library_theme_config_by_library_id(v_library_id), '{}'::jsonb);
  exception when others then
    v_theme_ctx := '{}'::jsonb;
  end;

  select coalesce(to_jsonb(x), 'null'::jsonb)
    into v_active_reg
  from (
    select *
    from api.get_library_regulation_documents_ui(v_library_id)
    where is_active = true
    order by updated_at desc, id desc
    limit 1
  ) x;

  select coalesce(jsonb_agg(to_jsonb(x) order by x.doc_kind, x.is_active desc, x.updated_at desc, x.id desc), '[]'::jsonb)
    into v_reg_docs
  from api.get_library_regulation_documents_ui(v_library_id) x;

  select coalesce(to_jsonb(x), 'null'::jsonb)
    into v_active_policy
  from (
    select *
    from api.get_library_circulation_policy_sets_ui(v_library_id)
    where is_active = true
    order by activated_at desc nulls last, updated_at desc, id desc
    limit 1
  ) x;

  select coalesce(jsonb_agg(to_jsonb(x) order by x.is_active desc, x.activated_at desc nulls last, x.updated_at desc, x.id desc), '[]'::jsonb)
    into v_policy_sets
  from api.get_library_circulation_policy_sets_ui(v_library_id) x;

  return jsonb_build_object(
    'library', jsonb_build_object(
      'id', v_library.id,
      'slug', v_library.slug,
      'name', v_library.name,
      'short_name', v_library.short_name,
      'city', v_library.city,
      'state', v_library.state,
      'country', v_library.country,
      'is_active', v_library.is_active
    ),
    'service_state', coalesce(to_jsonb(v_service), '{}'::jsonb),
    'contact_profile', coalesce(to_jsonb(v_contact), '{}'::jsonb),
    'document_governance', coalesce(v_governance.config, '{}'::jsonb),
    'notification_context', coalesce(v_notification_ctx, '{}'::jsonb),
    'theme_config', coalesce(v_theme_ctx, '{}'::jsonb),
    'active_regulation_document', coalesce(v_active_reg, 'null'::jsonb),
    'regulation_documents', coalesce(v_reg_docs, '[]'::jsonb),
    'active_policy_set', coalesce(v_active_policy, 'null'::jsonb),
    'policy_sets', coalesce(v_policy_sets, '[]'::jsonb)
  );
end;
$$;


