COMMENT ON FUNCTION "api"."mark_loan_return_missed"("p_emprestimo_id" bigint, "p_line_nos" integer[]) IS 'Paquet 19 (10/05/2026) : wrapper de fn_v2_mark_emprestimo_return_missed.
Marquer un retour comme non realise par la biblio.';



CREATE OR REPLACE FUNCTION "api"."mark_no_show"("p_reserva_id" bigint, "p_line_no" integer) RETURNS integer
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'api'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_library_id uuid;
  v_current_stage text;
  v_actor_role text;
  v_n integer;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'auth_required' USING ERRCODE = '42501';
  END IF;

  -- Lire contexte
  SELECT r.library_id, riw.workflow_stage
    INTO v_library_id, v_current_stage
  FROM public.reservas_v2 r
  JOIN public.reserva_item_workflow_v2 riw ON riw.reserva_id = r.id
  WHERE r.id = p_reserva_id AND riw.line_no = p_line_no;

  IF v_library_id IS NULL THEN
    RAISE EXCEPTION 'reserva_line_not_found' USING ERRCODE = '02000';
  END IF;

  -- Résoudre rôle
  v_actor_role := public.fn_resolve_caller_role_for_library(v_library_id);
  IF v_actor_role IS NULL THEN
    RAISE EXCEPTION 'not_staff_of_this_library' USING ERRCODE = '42501';
  END IF;

  -- Validation matrice (helper accepte 'retirada_no_show' depuis pronta/agendada/re-agendada)
  IF NOT public.fn_check_workflow_transition(v_current_stage, 'retirada_no_show', v_actor_role) THEN
    RAISE EXCEPTION 'transition_not_allowed'
      USING ERRCODE = '22023',
            HINT = format(
              'no-show non autorisé depuis %s pour rôle %s',
              v_current_stage, v_actor_role
            );
  END IF;

  v_n := public.fn_v2_set_reserva_linhas_workflow(
    p_reserva_id, ARRAY[p_line_no], 'retirada_no_show', NULL, NULL
  );

  -- Note : le trigger trg_auto_liberate_after_no_show déclenchera ensuite
  -- automatiquement la bascule vers liberada_para_circulacao avec
  -- final_reason = 'no_show'.

  RETURN v_n;
END;
$$;


ALTER FUNCTION "api"."mark_no_show"("p_reserva_id" bigint, "p_line_no" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "api"."mark_no_show"("p_reserva_id" bigint, "p_line_no" integer) IS 'Marque manuellement une ligne de réservation comme no-show (lecteur·rice non venu·e). Réservé au staff. Le trigger trg_auto_liberate_after_no_show déclenchera ensuite automatiquement la bascule vers liberada_para_circulacao avec final_reason=no_show. Raccourci de api.advance_reservation(..., target=retirada_no_show).';



CREATE OR REPLACE FUNCTION "api"."refuse_pickup_slot"("p_reserva_id" bigint, "p_line_no" integer, "p_reason" "text") RETURNS integer
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'api'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_owner uuid;
  v_current_stage text;
  v_n integer;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'auth_required' USING ERRCODE = '42501';
  END IF;

  -- Validation paramètre p_reason (obligatoire, ≥ 5 caractères trim)
  IF p_reason IS NULL OR length(btrim(p_reason)) < 5 THEN
    RAISE EXCEPTION 'reason_required_min_5_chars'
      USING ERRCODE = '22023',
            HINT = 'Pour refuser un créneau, indique une raison d''au moins 5 caractères (ex : indisponibilité, autre lieu préféré, etc.)';
  END IF;

  -- Vérifier ownership + récupérer current_stage
  SELECT r.user_id, riw.workflow_stage
    INTO v_owner, v_current_stage
  FROM public.reservas_v2 r
  JOIN public.reserva_item_workflow_v2 riw ON riw.reserva_id = r.id
  WHERE r.id = p_reserva_id AND riw.line_no = p_line_no;

  IF v_owner IS NULL THEN
    RAISE EXCEPTION 'reserva_line_not_found' USING ERRCODE = '02000';
  END IF;

  IF v_owner <> v_uid THEN
    RAISE EXCEPTION 'not_your_reserva' USING ERRCODE = '42501';
  END IF;

  IF v_current_stage NOT IN ('retirada_agendada', 're-retirada_agendada', 'retirada_a_combinar') THEN
    RAISE EXCEPTION 'pickup_reply_not_applicable_in_stage'
      USING ERRCODE = '22023',
            HINT = format('stage actuel = %s, attendu retirada_agendada|re-retirada_agendada|retirada_a_combinar', v_current_stage);
  END IF;

  v_n := public.fn_v2_set_reserva_linhas_pickup_reply(
    p_reserva_id, ARRAY[p_line_no], 'recusado_leitor', btrim(p_reason)
  );
  RETURN v_n;
END;
$$;


ALTER FUNCTION "api"."refuse_pickup_slot"("p_reserva_id" bigint, "p_line_no" integer, "p_reason" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "api"."refuse_pickup_slot"("p_reserva_id" bigint, "p_line_no" integer, "p_reason" "text") IS 'Refuse le créneau de retrait proposé par la biblio (pickup_reply_status = recusado_leitor). Raison obligatoire ≥ 5 caractères. Réservé au lecteur·rice propriétaire. Valide uniquement si workflow_stage IN (retirada_agendada, re-retirada_agendada, retirada_a_combinar).';



CREATE OR REPLACE FUNCTION "api"."renew_my_loan"("p_emprestimo_id" bigint) RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'api'
    AS $$
DECLARE
  v_caller_uid uuid := auth.uid();
  v_ctx record;
  v_actor_role text;
BEGIN
  IF v_caller_uid IS NULL THEN
    RAISE EXCEPTION 'auth_required' USING ERRCODE = '28000', HINT = 'Authentification obrigatoria.';
  END IF;

  SELECT * INTO v_ctx FROM public.fn_get_loan_context(p_emprestimo_id);

  IF v_ctx.library_id IS NULL THEN
    RAISE EXCEPTION 'loan_not_found' USING ERRCODE = 'P0001', HINT = format('Emprestimo %s nao encontrado.', p_emprestimo_id);
  END IF;

  -- Verification ownership avant role : un lecteur ne peut renouveler
  -- qu'un emprunt qui lui appartient.
  IF v_ctx.leitor_user_id <> v_caller_uid THEN
    RAISE EXCEPTION 'not_your_loan' USING ERRCODE = '42501', HINT = 'Voce so pode renovar seus proprios emprestimos.';
  END IF;

  v_actor_role := public.fn_resolve_caller_role_for_library(v_ctx.library_id);

  IF NOT public.fn_check_loan_action('renew_as_reader', v_ctx.status_global, v_actor_role) THEN
    RAISE EXCEPTION 'loan_action_not_allowed' USING ERRCODE = '42501', HINT = format('Acao nao autorizada (%s/%s) sobre emprestimo %s.', v_actor_role, v_ctx.status_global, p_emprestimo_id);
  END IF;

  RETURN public.fn_renew_my_loan(p_emprestimo_id := p_emprestimo_id);
END;
$$;


ALTER FUNCTION "api"."renew_my_loan"("p_emprestimo_id" bigint) OWNER TO "postgres";


COMMENT ON FUNCTION "api"."renew_my_loan"("p_emprestimo_id" bigint) IS 'Paquet 19 (10/05/2026) : wrapper de fn_renew_my_loan.
Renouvellement d''un emprunt par le lecteur lui-meme. Verifie ownership.';



CREATE OR REPLACE FUNCTION "api"."renew_my_loan_item"("p_emprestimo_id" bigint, "p_line_no" integer) RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'api'
    AS $$
DECLARE
  v_caller_uid uuid := auth.uid();
  v_ctx record;
  v_actor_role text;
BEGIN
  IF v_caller_uid IS NULL THEN
    RAISE EXCEPTION 'auth_required' USING ERRCODE = '28000', HINT = 'Authentification obrigatoria.';
  END IF;

  SELECT * INTO v_ctx FROM public.fn_get_loan_context(p_emprestimo_id);

  IF v_ctx.library_id IS NULL THEN
    RAISE EXCEPTION 'loan_not_found' USING ERRCODE = 'P0001', HINT = format('Emprestimo %s nao encontrado.', p_emprestimo_id);
  END IF;

  -- Ownership : un lecteur ne renouvelle que ses propres emprunts.
  IF v_ctx.leitor_user_id <> v_caller_uid THEN
    RAISE EXCEPTION 'not_your_loan' USING ERRCODE = '42501', HINT = 'Voce so pode renovar seus proprios emprestimos.';
  END IF;

  v_actor_role := public.fn_resolve_caller_role_for_library(v_ctx.library_id);

  IF NOT public.fn_check_loan_action('renew_as_reader', v_ctx.status_global, v_actor_role) THEN
    RAISE EXCEPTION 'loan_action_not_allowed' USING ERRCODE = '42501', HINT = format('Acao nao autorizada (%s/%s) sobre emprestimo %s.', v_actor_role, v_ctx.status_global, p_emprestimo_id);
  END IF;

  RETURN public.fn_renew_my_loan_item(p_emprestimo_id := p_emprestimo_id, p_line_no := p_line_no);
END;
$$;


ALTER FUNCTION "api"."renew_my_loan_item"("p_emprestimo_id" bigint, "p_line_no" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "api"."reply_consulta_schedule"("p_consulta_id" bigint, "p_line_nos" integer[], "p_reply" "text", "p_note" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'api'
    AS $$
DECLARE
  v_caller_uid uuid := auth.uid();
  v_ctx record;
  v_current_stage text;
  v_heterogeneous_count int;
  v_updated int;
BEGIN
  IF v_caller_uid IS NULL THEN
    RAISE EXCEPTION 'not_authenticated' USING ERRCODE = '28000';
  END IF;

  IF p_consulta_id IS NULL THEN
    RAISE EXCEPTION 'not_found: p_consulta_id manquant' USING ERRCODE = 'P0001';
  END IF;

  IF p_line_nos IS NULL OR cardinality(p_line_nos) = 0 THEN
    RAISE EXCEPTION 'not_found: p_line_nos vide' USING ERRCODE = 'P0001';
  END IF;

  IF p_reply NOT IN ('confirmado_leitor', 'recusado_leitor') THEN
    RAISE EXCEPTION 'invalid_stage: reply % invalido (esperado confirmado_leitor ou recusado_leitor)', p_reply
      USING ERRCODE = 'P0001';
  END IF;

  -- Lookup contexte
  SELECT * INTO v_ctx FROM public.fn_get_consulta_context(p_consulta_id);
  IF v_ctx.library_id IS NULL THEN
    RAISE EXCEPTION 'not_found: consulta % nao encontrada', p_consulta_id
      USING ERRCODE = 'P0001';
  END IF;

  -- Ownership : seul le proprietaire peut repondre
  IF v_ctx.leitor_user_id <> v_caller_uid THEN
    RAISE EXCEPTION 'not_owner: voce so pode responder sobre suas consultas'
      USING ERRCODE = '42501';
  END IF;

  -- Hardening (d) : verifier que toutes les lignes sont a consulta_agendada
  SELECT workflow_stage
    INTO v_current_stage
  FROM public.consulta_item_workflow_v2
  WHERE consulta_id = p_consulta_id
    AND line_no = p_line_nos[1];

  IF v_current_stage IS NULL THEN
    RAISE EXCEPTION 'not_found: linha % nao encontrada', p_line_nos[1]
      USING ERRCODE = 'P0001';
  END IF;

  IF v_current_stage <> 'consulta_agendada' THEN
    RAISE EXCEPTION 'invalid_stage: reposta ao agendamento so e possivel em consulta_agendada (atual: %)',
      v_current_stage
      USING ERRCODE = '42501';
  END IF;

  SELECT count(*)
    INTO v_heterogeneous_count
  FROM public.consulta_item_workflow_v2
  WHERE consulta_id = p_consulta_id
    AND line_no = ANY(p_line_nos)
    AND workflow_stage IS DISTINCT FROM 'consulta_agendada';

  IF v_heterogeneous_count > 0 THEN
    RAISE EXCEPTION 'invalid_stage: linhas com etapas heterogeneas (% linhas fora de consulta_agendada)',
      v_heterogeneous_count
      USING ERRCODE = '42501';
  END IF;

  -- Delegation a la fn DEFINER
  v_updated := public.fn_v2_set_consulta_linhas_schedule_reply(
    p_consulta_id, p_line_nos, p_reply, p_note
  );

  RETURN jsonb_build_object('ok', true, 'updated_count', v_updated);
END;
$$;


ALTER FUNCTION "api"."reply_consulta_schedule"("p_consulta_id" bigint, "p_line_nos" integer[], "p_reply" "text", "p_note" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "api"."reply_consulta_schedule"("p_consulta_id" bigint, "p_line_nos" integer[], "p_reply" "text", "p_note" "text") IS 'Wrapper api.* SECURITY INVOKER pour la reponse du lecteur a un creneau propose (spec §6.3). Ownership check + verification stage courant = consulta_agendada. Retour : jsonb {ok, updated_count}.';



CREATE OR REPLACE FUNCTION "api"."request_membership"("p_library_id" "uuid") RETURNS TABLE("ok" boolean, "membership_id" "uuid", "status" "text", "message" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_user uuid := auth.uid();
  v_lib  record;
  v_existing record;
  v_total integer;
  v_validated integer;
  v_is_primary boolean;
  v_id uuid;
BEGIN
  IF v_user IS NULL THEN
    RAISE EXCEPTION 'Autenticação obrigatória.';
  END IF;

  SELECT l.id, l.is_active, l.accepts_public_signup, COALESCE(l.short_name, l.name) AS name
    INTO v_lib
  FROM public.libraries l WHERE l.id = p_library_id;

  IF NOT FOUND OR NOT v_lib.is_active THEN
    RAISE EXCEPTION 'Biblioteca indisponível.'
      USING errcode = 'P0001', hint = 'error.membership.library_unavailable';
  END IF;
  IF NOT COALESCE(v_lib.accepts_public_signup, false) THEN
    RAISE EXCEPTION 'Esta biblioteca não aceita inscrições públicas no momento.'
      USING errcode = 'P0001', hint = 'error.membership.no_public_signup';
  END IF;

  SELECT m.id, m.status INTO v_existing
  FROM public.user_library_memberships m
  WHERE m.user_id = v_user AND m.library_id = p_library_id AND m.role = 'reader'
  LIMIT 1;

  IF v_existing.id IS NOT NULL AND v_existing.status IN
     ('active', 'pending_validation', 'pending_removal', 'suspended', 'left_with_pending_circulation') THEN
    RETURN QUERY SELECT false, v_existing.id, v_existing.status,
      'Você já tem uma associação com esta biblioteca.'::text;
    RETURN;
  END IF;

  SELECT count(*) FILTER (WHERE m.status <> 'removed'),
         count(*) FILTER (WHERE m.status = 'active')
    INTO v_total, v_validated
  FROM public.user_library_memberships m WHERE m.user_id = v_user;

  IF v_total > 0 AND v_validated = 0 THEN
    RAISE EXCEPTION 'Valide ao menos uma associação existente antes de solicitar uma nova.'
      USING errcode = 'P0001', hint = 'error.membership.beta1_guard';
  END IF;

  v_is_primary := (v_total = 0);

  IF v_existing.id IS NOT NULL THEN
    UPDATE public.user_library_memberships
      SET status = 'pending_validation', is_primary = v_is_primary, updated_at = now()
      WHERE id = v_existing.id;
    v_id := v_existing.id;
  ELSE
    INSERT INTO public.user_library_memberships
      (user_id, library_id, role, status, is_primary, created_at, updated_at)
    VALUES (v_user, p_library_id, 'reader', 'pending_validation', v_is_primary, now(), now())
    RETURNING id INTO v_id;
  END IF;

  -- VALID-C3 : prévenir la biblio qu'une demande attend validation (best-effort).
  BEGIN
    PERFORM public.fn_dispatch_notify_event(
      'membership_validation_requested',
      1,
      jsonb_build_object(
        'user_id', v_user::text,
        'library_id', p_library_id::text,
        'membership_id', v_id::text
      )
    );
  EXCEPTION WHEN OTHERS THEN
    RAISE WARNING 'membership_validation_requested dispatch failed for membership %: %', v_id, SQLERRM;
  END;

  RETURN QUERY SELECT true, v_id, 'pending_validation'::text,
    format('Solicitação enviada a %s. Aguardando validação da equipe.', v_lib.name);
END $$;


ALTER FUNCTION "api"."request_membership"("p_library_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "api"."resolve_circulation_rule"("p_library_id" "uuid", "p_mode" "text", "p_user_id" "uuid" DEFAULT NULL::"uuid", "p_book_id" bigint DEFAULT NULL::bigint, "p_holding_id" bigint DEFAULT NULL::bigint, "p_quantity" integer DEFAULT 1, "p_as_of_date" "date" DEFAULT NULL::"date", "p_current_due_date" "date" DEFAULT NULL::"date", "p_renewals_used" integer DEFAULT 0) RETURNS TABLE("library_id" "uuid", "policy_set_id" bigint, "policy_set_label" "text", "policy_set_status" "text", "rule_id" bigint, "rule_label" "text", "matched" boolean, "mode" "text", "material_scope" "text", "reader_scope" "text", "quantity" integer, "service_mode" "text", "allows_new_reservations" boolean, "allows_new_loans" boolean, "item_loanable" boolean, "loan_allowed" boolean, "reservation_allowed" boolean, "consultation_allowed" boolean, "consultation_only" boolean, "manual_review_required" boolean, "renewable" boolean, "renewal_max_count" integer, "renewals_used" integer, "renewals_remaining" integer, "loan_days" integer, "renewal_days" integer, "resolved_due_date" "date", "resolved_due_date_after_renewal" "date", "public_note" "text", "internal_note" "text", "exception_code" "text", "non_extendable_reason" "text", "explanation" "text")
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'api', 'auth', 'pg_temp'
    AS $$
declare
  v_caller_uid uuid := auth.uid();
  v_is_anon boolean := (v_caller_uid is null);
  v_user_id uuid;

  v_mode text := lower(coalesce(trim(p_mode), ''));
  v_quantity integer := greatest(coalesce(p_quantity, 1), 1);
  v_as_of_date date := coalesce(p_as_of_date, current_date);
  v_current_due_date date := p_current_due_date;
  v_renewals_used integer := greatest(coalesce(p_renewals_used, 0), 0);

  v_policy_set public.library_circulation_policy_sets%rowtype;
  v_rule public.library_circulation_policy_rules%rowtype;

  v_service public.library_service_state%rowtype;
  v_book public.books%rowtype;
  v_holding record;

  v_material_scope text := 'any';
  v_reader_scope text := 'non_member';
  v_item_loanable boolean := true;

  v_effective_loan_allowed boolean := false;
  v_effective_reservation_allowed boolean := false;
  v_effective_consultation_allowed boolean := false;
  v_effective_consultation_only boolean := false;
  v_effective_renewable boolean := false;
  v_renewals_remaining integer := 0;
  v_resolved_due_date date := null;
  v_resolved_due_date_after_renewal date := null;
  v_explanation text := '';
begin
  -- 1. VALIDATION DE BASE
  if p_library_id is null then
    raise exception 'Biblioteca obrigatória para resolver a regra de circulação.';
  end if;

  if v_mode not in ('loan', 'renewal', 'reservation', 'local_consultation') then
    raise exception 'Modo de circulação inválido: %', p_mode;
  end if;

  -- 2. CONTRÔLE DE VISIBILITÉ POUR LES APPELS ANON
  -- Les anon n'accèdent qu'aux bibliothèques visibility_level = 'public'.
  if v_is_anon and not exists (
    select 1
    from public.libraries
    where id = p_library_id
      and is_active = true
      and visibility_level = 'public'
  ) then
    raise exception 'Biblioteca não disponível.'
      using errcode = 'P0002';
  end if;

  -- 3. RÉSOLUTION SÉCURISÉE DE v_user_id
  v_user_id := case
    when v_is_anon then null
    when v_caller_uid = p_user_id then p_user_id
    when public.user_has_library_staff_role(v_caller_uid, p_library_id)
      then coalesce(p_user_id, v_caller_uid)
    else v_caller_uid
  end;

  -- 4. RÉSOLUTION DU POLICY SET ACTIF
  select *
    into v_policy_set
  from public.library_circulation_policy_sets s
  where s.library_id = p_library_id
    and s.is_active = true
    and s.status = 'active'
    and (s.effective_from is null or s.effective_from <= v_as_of_date)
    and (s.effective_until is null or s.effective_until >= v_as_of_date)
  order by s.activated_at desc nulls last, s.updated_at desc, s.id desc
  limit 1;

  if v_policy_set.id is null then
    return query
    select
      p_library_id,
      null::bigint, null::text, null::text, null::bigint, null::text,
      false, v_mode, 'any'::text,
      public.circulation_reader_scope(v_user_id, p_library_id),
      v_quantity, 'funcionamento_normal'::text,
      true, true, true, false, false, false, false, false, false,
      null::integer, v_renewals_used, 0, null::integer, null::integer,
      null::date, null::date,
      null::text, null::text, null::text, null::text,
      'Nenhum conjunto ativo de regras de circulação foi encontrado para esta biblioteca.';
    return;
  end if;

  -- 5. RÉSOLUTION DU SERVICE STATE
  select *
    into v_service
  from public.library_service_state s
  where s.library_id = p_library_id
  limit 1;

  if v_service.library_id is null then
    v_service.library_id := p_library_id;
    v_service.service_mode := 'funcionamento_normal';
    v_service.allows_new_reservations := true;
    v_service.allows_new_loans := true;
  end if;

  -- 6. RÉSOLUTION DU LIVRE / HOLDING
  if p_holding_id is not null then
    select
      h.id, h.book_id,
      coalesce(h.loanable, b.loanable, true) as holding_loanable
    into v_holding
    from public.book_holdings h
    left join public.books b on b.id = h.book_id
    where h.id = p_holding_id and h.library_id = p_library_id
    limit 1;

    if v_holding.id is not null then
      if v_holding.book_id is not null then
        select * into v_book
        from public.books b
        where b.id = v_holding.book_id
        limit 1;
      end if;
      v_item_loanable := coalesce(v_holding.holding_loanable, true);
    end if;
  end if;

  if v_book.id is null and p_book_id is not null then
    select * into v_book
    from public.books b
    where b.id = p_book_id
    limit 1;
    if v_book.id is not null then
      v_item_loanable := coalesce(v_book.loanable, true);
    end if;
  end if;

  if v_book.id is not null then
    v_material_scope := public.circulation_material_scope_from_tipo_material(v_book.tipo_material);
  else
    v_material_scope := 'any';
  end if;

  v_reader_scope := public.circulation_reader_scope(v_user_id, p_library_id);

  -- 7. RÉSOLUTION DE LA RÈGLE
  select r.*
    into v_rule
  from public.library_circulation_policy_rules r
  where r.policy_set_id = v_policy_set.id
    and r.is_active = true
    and r.circulation_mode = v_mode
    and r.material_scope in ('any', v_material_scope)
    and r.reader_scope in ('any', v_reader_scope)
    and r.quantity_min <= v_quantity
    and (r.quantity_max is null or r.quantity_max >= v_quantity)
  order by
    r.priority asc,
    case when r.material_scope = v_material_scope then 0 else 1 end,
    case when r.reader_scope = v_reader_scope then 0 else 1 end,
    case
      when r.quantity_max is null then 999999
      else greatest(r.quantity_max - r.quantity_min, 0)
    end asc,
    r.id asc
  limit 1;

  if v_rule.id is null then
    return query
    select
      p_library_id,
      v_policy_set.id, v_policy_set.label, v_policy_set.status,
      null::bigint, null::text, false,
      v_mode, v_material_scope, v_reader_scope, v_quantity,
      coalesce(v_service.service_mode, 'funcionamento_normal'),
      coalesce(v_service.allows_new_reservations, true),
      coalesce(v_service.allows_new_loans, true),
      coalesce(v_item_loanable, true),
      false, false, false, false, false, false,
      null::integer, v_renewals_used, 0, null::integer, null::integer,
      null::date, null::date,
      null::text, null::text, null::text, null::text,
      'Nenhuma regra ativa correspondeu ao modo, ao tipo de material, ao perfil de leitor(a/e) e à quantidade informada.';
    return;
  end if;

  -- 8. CALCULS EFFECTIFS
  v_effective_consultation_only :=
    coalesce(v_rule.consultation_only, false)
    or (v_mode in ('loan', 'reservation') and coalesce(v_item_loanable, true) = false);

  v_effective_loan_allowed :=
    coalesce(v_rule.loan_allowed, false)
    and not v_effective_consultation_only
    and coalesce(v_item_loanable, true)
    and coalesce(v_service.service_mode, 'funcionamento_normal') <> 'pausada'
    and coalesce(v_service.service_mode, 'funcionamento_normal') <> 'somente_consulta'
    and coalesce(v_service.allows_new_loans, true);

  v_effective_reservation_allowed :=
    coalesce(v_rule.reservation_allowed, false)
    and not v_effective_consultation_only
    and coalesce(v_item_loanable, true)
    and coalesce(v_service.service_mode, 'funcionamento_normal') <> 'pausada'
    and coalesce(v_service.service_mode, 'funcionamento_normal') <> 'somente_consulta'
    and coalesce(v_service.allows_new_reservations, true);

  v_effective_consultation_allowed :=
    coalesce(v_rule.consultation_allowed, false)
    and coalesce(v_service.service_mode, 'funcionamento_normal') <> 'pausada'
    and coalesce(v_service.allows_new_reservations, true);

  v_effective_renewable :=
    coalesce(v_rule.renewable, false)
    and (
      v_rule.renewal_max_count is null
      or greatest(v_rule.renewal_max_count - v_renewals_used, 0) > 0
    );

  v_renewals_remaining :=
    case
      when coalesce(v_rule.renewable, false) is false then 0
      when v_rule.renewal_max_count is null then null
      else greatest(v_rule.renewal_max_count - v_renewals_used, 0)
    end;

  if v_mode = 'loan' and v_effective_loan_allowed and v_rule.loan_days is not null then
    v_resolved_due_date := v_as_of_date + v_rule.loan_days;
  end if;

  if v_mode = 'renewal' and v_effective_renewable and v_rule.renewal_days is not null then
    v_resolved_due_date_after_renewal := coalesce(v_current_due_date, v_as_of_date) + v_rule.renewal_days;
  end if;

  -- 9. EXPLICATION TEXTUELLE
  if coalesce(v_service.service_mode, 'funcionamento_normal') = 'pausada' then
    v_explanation := 'A biblioteca está com o serviço pausado no momento.';
  elsif v_mode in ('loan', 'reservation')
        and coalesce(v_service.service_mode, 'funcionamento_normal') = 'somente_consulta' then
    v_explanation := 'A biblioteca está em modo somente consulta para este tipo de circulação.';
  elsif v_mode = 'loan' and coalesce(v_service.allows_new_loans, true) = false then
    v_explanation := 'Novos empréstimos estão desativados para esta biblioteca.';
  elsif v_mode in ('reservation', 'local_consultation')
        and coalesce(v_service.allows_new_reservations, true) = false then
    v_explanation := 'Reservas e consultas públicas estão fechadas para esta biblioteca.';
  elsif v_mode in ('loan', 'reservation') and coalesce(v_item_loanable, true) = false then
    v_explanation := 'O item está marcado para consulta local, sem empréstimo externo.';
  elsif v_effective_consultation_only then
    v_explanation := 'A regra resolvida limita este caso à consulta local.';
  elsif coalesce(v_rule.manual_review_required, false) then
    v_explanation := 'A regra resolvida exige análise manual da biblioteca.';
  else
    v_explanation := 'Regra resolvida a partir do conjunto ativo de circulação da biblioteca.';
  end if;

  -- 10. RETOUR FINAL
  return query
  select
    p_library_id,
    v_policy_set.id, v_policy_set.label, v_policy_set.status,
    v_rule.id, v_rule.rule_label, true,
    v_mode, v_material_scope, v_reader_scope, v_quantity,
    coalesce(v_service.service_mode, 'funcionamento_normal'),
    coalesce(v_service.allows_new_reservations, true),
    coalesce(v_service.allows_new_loans, true),
    coalesce(v_item_loanable, true),
    v_effective_loan_allowed,
    v_effective_reservation_allowed,
    v_effective_consultation_allowed,
    v_effective_consultation_only,
    coalesce(v_rule.manual_review_required, false),
    v_effective_renewable,
    v_rule.renewal_max_count,
    v_renewals_used, v_renewals_remaining,
    v_rule.loan_days, v_rule.renewal_days,
    v_resolved_due_date, v_resolved_due_date_after_renewal,
    v_rule.public_note,
    case when v_is_anon then null else v_rule.internal_note end,
    case when v_is_anon then null else v_rule.exception_code end,
    v_rule.non_extendable_reason,
    v_explanation;
end;
$$;


ALTER FUNCTION "api"."resolve_circulation_rule"("p_library_id" "uuid", "p_mode" "text", "p_user_id" "uuid", "p_book_id" bigint, "p_holding_id" bigint, "p_quantity" integer, "p_as_of_date" "date", "p_current_due_date" "date", "p_renewals_used" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "api"."resolve_circulation_rule"("p_library_id" "uuid", "p_mode" "text", "p_user_id" "uuid", "p_book_id" bigint, "p_holding_id" bigint, "p_quantity" integer, "p_as_of_date" "date", "p_current_due_date" "date", "p_renewals_used" integer) IS 'SECURITY DEFINER intentional: o OPAC público precisa exibir regras de circulação para visitantes anônimos/as. Três proteções aplicadas para callers anônimos: (1) bibliotecas com visibility_level <> public levantam exceção; (2) p_user_id é ignorado para impedir enumeração de membros; (3) internal_note e exception_code são retornados como null. Para callers autenticados/as: p_user_id só é honrado se for o próprio caller, ou se o caller for staff (librarian/coordenador/administrador) da biblioteca em questão.';



CREATE OR REPLACE FUNCTION "api"."resolve_reader_card"("p_token" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions'
    AS $$
DECLARE
  v_uid  uuid := auth.uid();
  v_hash text;
  v_tok  public.reader_card_tokens%ROWTYPE;
  v_prof public.profiles%ROWTYPE;
BEGIN
  IF v_uid IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'not_authenticated');
  END IF;

  IF COALESCE(btrim(p_token), '') = '' THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'invalid_token');
  END IF;

  v_hash := public.fn_hash_claim_token(lower(btrim(p_token)));

  SELECT * INTO v_tok
  FROM public.reader_card_tokens
  WHERE token_hash = v_hash AND status = 'active'
  LIMIT 1;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'token_not_found');
  END IF;

  -- Autorisation : staff actif (librarian|coordenador) de la biblio du jeton.
  -- On ne divulgue rien si l'appelant n'a pas ce droit.
  IF NOT EXISTS (
    SELECT 1
    FROM public.user_library_memberships m
    WHERE m.user_id = v_uid
      AND m.library_id = v_tok.library_id
      AND m.status = 'active'
      AND m.role IN ('librarian', 'coordenador')
  ) THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'not_staff_of_library');
  END IF;

  -- Resolution de l'identite (le staff de la bonne biblio y a droit)
  SELECT * INTO v_prof FROM public.profiles WHERE id = v_tok.user_id;

  RETURN jsonb_build_object(
    'ok',             true,
    'reader_user_id', v_tok.user_id,
    'membership_id',  v_tok.membership_id,
    'library_id',     v_tok.library_id,
    'public_id',      v_prof.public_id,
    'display_name',   NULLIF(btrim(COALESCE(v_prof.first_name, '') || ' ' || COALESCE(v_prof.last_name, '')), ''),
    'is_restricted',  COALESCE(v_prof.is_restricted, false)
  );
END;
$$;


ALTER FUNCTION "api"."resolve_reader_card"("p_token" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "api"."restrict_member"("p_user_id" "uuid", "p_library_id" "uuid", "p_reason" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_membership_id uuid;
BEGIN
  IF v_uid IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'not_authenticated');
  END IF;

  -- Habilitation : staff de cette biblio
  IF NOT public.user_can_act_as_staff_on_library(p_library_id) THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'not_authorized');
  END IF;

  -- Raison obligatoire (horizontalite : un acte sensible se motive)
  IF p_reason IS NULL OR length(btrim(p_reason)) < 5 THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'reason_required');
  END IF;

  -- Appartenance active du membre cible a cette biblio
  SELECT id INTO v_membership_id
  FROM public.user_library_memberships
  WHERE user_id = p_user_id AND library_id = p_library_id AND status = 'active'
  LIMIT 1;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'not_a_member');
  END IF;

  UPDATE public.user_library_memberships
  SET is_restricted = true,
      restricted_reason = btrim(p_reason),
      restricted_by = v_uid,
      restricted_at = now()
  WHERE id = v_membership_id;

  PERFORM public.fn_dispatch_notify_event('member_restricted_local', 1,
    jsonb_build_object('user_id', p_user_id::text, 'library_id', p_library_id::text,
                       'reason', btrim(p_reason), 'at', now()::text));

  RETURN jsonb_build_object('ok', true, 'membership_id', v_membership_id);
END;
$$;


ALTER FUNCTION "api"."restrict_member"("p_user_id" "uuid", "p_library_id" "uuid", "p_reason" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "api"."restrict_member"("p_user_id" "uuid", "p_library_id" "uuid", "p_reason" "text") IS 'EA-10 : restriction LOCALE d''un membre dans une biblio. Staff local ou admin reseau. Raison obligatoire >= 5 car. Trace restricted_by + restricted_at. Chantier D #PAINEL, 28/05/2026.';



CREATE OR REPLACE FUNCTION "api"."return_loan_partial"("p_emprestimo_id" bigint, "p_line_nos" integer[], "p_notes" "text" DEFAULT NULL::"text") RETURNS integer
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'api'
    AS $$
DECLARE
  v_caller_uid uuid := auth.uid();
  v_ctx record;
  v_actor_role text;
BEGIN
  IF v_caller_uid IS NULL THEN
    RAISE EXCEPTION 'auth_required' USING ERRCODE = '28000', HINT = 'Authentification obrigatoria.';
  END IF;

  IF p_line_nos IS NULL OR array_length(p_line_nos, 1) = 0 THEN
    RAISE EXCEPTION 'line_required' USING ERRCODE = 'P0001', HINT = 'Pelo menos uma linha deve ser indicada.';
  END IF;

  SELECT * INTO v_ctx FROM public.fn_get_loan_context(p_emprestimo_id);

  IF v_ctx.library_id IS NULL THEN
    RAISE EXCEPTION 'loan_not_found' USING ERRCODE = 'P0001', HINT = format('Emprestimo %s nao encontrado.', p_emprestimo_id);
  END IF;

  v_actor_role := public.fn_resolve_caller_role_for_library(v_ctx.library_id);

  IF NOT public.fn_check_loan_action('return_partial', v_ctx.status_global, v_actor_role) THEN
    RAISE EXCEPTION 'loan_action_not_allowed' USING ERRCODE = '42501', HINT = format('Acao nao autorizada (%s/%s) sobre emprestimo %s.', v_actor_role, v_ctx.status_global, p_emprestimo_id);
  END IF;

  RETURN public.fn_v2_return_emprestimo_linhas(
    p_emprestimo_id := p_emprestimo_id,
    p_line_nos := p_line_nos,
    p_notes := p_notes
  );
END;
$$;


