Planification d''un retour, par le lecteur (ses emprunts) ou la biblio.';



CREATE OR REPLACE FUNCTION "api"."search_catalog_v1"("q" "text") RETURNS TABLE("kind" "text", "id" bigint, "label" "text", "sublabel" "text", "rank" real, "filter_value" "text")
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'api', 'extensions'
    AS $$
DECLARE
  v_q_norm text;
  v_tokens text[];
  v_token_count int;
  v_is_member boolean;
BEGIN
  IF q IS NULL OR length(trim(q)) < 4 THEN
    RETURN;
  END IF;
  
  v_q_norm := public.f_normalize_search(trim(q));
  
  v_tokens := array(
    SELECT t 
    FROM unnest(regexp_split_to_array(v_q_norm, '\s+')) AS t 
    WHERE length(t) >= 3
  );
  v_token_count := COALESCE(array_length(v_tokens, 1), 0);
  
  IF v_token_count = 0 THEN
    v_tokens := ARRAY[v_q_norm];
    v_token_count := 1;
  END IF;
  
  v_is_member := (
    auth.uid() IS NOT NULL 
    AND EXISTS (
      SELECT 1 FROM public.user_library_memberships ulm
      WHERE ulm.user_id = auth.uid() 
        AND ulm.status = 'active'
    )
  );
  
  RETURN QUERY
  WITH 
  alias_candidates AS (
    SELECT 
      ana.author_id,
      ana.alias_norm,
      ana.match_kind,
      (
        SELECT count(*)::int
        FROM unnest(v_tokens) AS tok
        WHERE ana.alias_norm ~ ('(^|\s)' || tok)
      ) AS tokens_matched,
      similarity(ana.alias_norm, v_q_norm) AS sim,
      ana.alias_norm LIKE v_q_norm || '%' AS prefix_full
    FROM public.author_name_aliases ana
    WHERE ana.is_active = true
      AND (
        ana.alias_norm % v_q_norm
        OR ana.alias_norm LIKE v_q_norm || '%'
        OR EXISTS (
          SELECT 1 FROM unnest(v_tokens) AS tok 
          WHERE ana.alias_norm ~ ('(^|\s)' || tok)
        )
      )
  ),
  authors_canonical_candidates AS (
    SELECT 
      a.id AS author_id,
      GREATEST(
        (SELECT count(*)::int FROM unnest(v_tokens) AS tok 
         WHERE public.f_normalize_search(a.preferred_name) ~ ('(^|\s)' || tok)),
        (SELECT count(*)::int FROM unnest(v_tokens) AS tok 
         WHERE public.f_normalize_search(COALESCE(a.sort_name, '')) ~ ('(^|\s)' || tok))
      ) AS tokens_matched,
      GREATEST(
        similarity(public.f_normalize_search(a.preferred_name), v_q_norm),
        similarity(public.f_normalize_search(COALESCE(a.sort_name, '')), v_q_norm)
      ) AS sim,
      (public.f_normalize_search(a.preferred_name) LIKE v_q_norm || '%')
        OR (public.f_normalize_search(COALESCE(a.sort_name, '')) LIKE v_q_norm || '%') AS prefix_full
    FROM public.authors a
    WHERE 
      public.f_normalize_search(a.preferred_name) % v_q_norm
      OR public.f_normalize_search(COALESCE(a.sort_name, '')) % v_q_norm
      OR public.f_normalize_search(a.preferred_name) LIKE v_q_norm || '%'
      OR public.f_normalize_search(COALESCE(a.sort_name, '')) LIKE v_q_norm || '%'
      OR EXISTS (
        SELECT 1 FROM unnest(v_tokens) AS tok 
        WHERE public.f_normalize_search(a.preferred_name) ~ ('(^|\s)' || tok)
           OR public.f_normalize_search(COALESCE(a.sort_name, '')) ~ ('(^|\s)' || tok)
      )
  ),
  authors_merged AS (
    SELECT 
      author_id,
      MAX(tokens_matched) AS tokens_matched,
      MAX(sim) AS sim,
      bool_or(prefix_full) AS prefix_full,
      MAX(canonical_bonus) AS canonical_bonus,
      MAX(seed_malus) AS seed_malus
    FROM (
      SELECT 
        author_id, tokens_matched, sim, prefix_full,
        CASE WHEN match_kind LIKE 'canonical%' THEN 0.1 ELSE 0.0 END AS canonical_bonus,
        CASE WHEN match_kind LIKE 'catalog_seed%' THEN -0.05 ELSE 0.0 END AS seed_malus
      FROM alias_candidates
      UNION ALL
      SELECT 
        author_id, tokens_matched, sim, prefix_full,
        0.1 AS canonical_bonus,
        0.0 AS seed_malus
      FROM authors_canonical_candidates
    ) merged
    GROUP BY author_id
  ),
  authors_scored AS (
    SELECT 
      am.author_id,
      a.preferred_name,
      a.sort_name,  -- NOUVEAU
      (
        CASE WHEN am.prefix_full THEN 10.0 ELSE 0.0 END
        + CASE WHEN am.tokens_matched = v_token_count THEN 1.0 ELSE 0.0 END
        + (am.sim / 4.0)
        + am.canonical_bonus
        + am.seed_malus
      )::real AS final_rank,
      am.prefix_full
    FROM authors_merged am
    JOIN public.authors a ON a.id = am.author_id
    WHERE 
      EXISTS (
        SELECT 1 
        FROM public.book_authors ba
        WHERE ba.author_id = am.author_id
          AND (
            EXISTS (
              SELECT 1 FROM public.mv_books_catalog_list_v1 m
              WHERE m.book_id = ba.book_id
            )
            OR (v_is_member AND EXISTS (
              SELECT 1 FROM public.mv_books_catalog_list_network_v1 m
              WHERE m.book_id = ba.book_id
            ))
          )
      )
      AND (am.prefix_full OR am.tokens_matched = v_token_count OR am.sim >= 0.3)
  ),
  book_candidates AS (
    SELECT 
      m.book_id,
      m.titulo,
      m.author_display,
      m.library_name,
      (
        SELECT count(*)::int 
        FROM unnest(v_tokens) AS tok
        WHERE public.f_normalize_search(m.titulo) ~ ('(^|\s)' || tok)
      ) AS tokens_matched,
      similarity(public.f_normalize_search(m.titulo), v_q_norm) AS sim,
      public.f_normalize_search(m.titulo) LIKE v_q_norm || '%' AS prefix_full
    FROM (
      SELECT book_id, titulo, author_display, library_name 
        FROM public.mv_books_catalog_list_v1 
        WHERE NOT v_is_member
      UNION ALL
      SELECT book_id, titulo, author_display, library_name 
        FROM public.mv_books_catalog_list_network_v1 
        WHERE v_is_member
    ) m
    WHERE 
      public.f_normalize_search(m.titulo) % v_q_norm
      OR public.f_normalize_search(m.titulo) LIKE v_q_norm || '%'
      OR EXISTS (
        SELECT 1 FROM unnest(v_tokens) AS tok 
        WHERE public.f_normalize_search(m.titulo) ~ ('(^|\s)' || tok)
      )
  ),
  books_scored AS (
    SELECT 
      bc.book_id,
      bc.titulo,
      bc.author_display,
      bc.library_name,
      (
        CASE WHEN bc.prefix_full THEN 10.0 ELSE 0.0 END
        + CASE WHEN bc.tokens_matched = v_token_count THEN 1.0 ELSE 0.0 END
        + (bc.sim / 4.0)
      )::real AS final_rank,
      bc.prefix_full
    FROM book_candidates bc
    WHERE bc.prefix_full OR bc.tokens_matched = v_token_count OR bc.sim >= 0.3
  ),
  category_flags AS (
    SELECT 
      EXISTS (SELECT 1 FROM authors_scored WHERE prefix_full) AS authors_have_prefix,
      EXISTS (SELECT 1 FROM books_scored WHERE prefix_full) AS books_have_prefix
  ),
  authors_filtered AS (
    SELECT a.author_id, a.preferred_name, a.sort_name, a.final_rank
    FROM authors_scored a, category_flags cf
    WHERE NOT cf.authors_have_prefix OR a.prefix_full
  ),
  books_filtered AS (
    SELECT b.book_id, b.titulo, b.author_display, b.library_name, b.final_rank
    FROM books_scored b, category_flags cf
    WHERE NOT cf.books_have_prefix OR b.prefix_full
  ),
  all_results AS (
    SELECT 
      'author'::text AS kind,
      author_id AS id,
      preferred_name AS label,
      'Autor/a'::text AS sublabel,
      final_rank AS rank,
      -- NOUVEAU : valeur de filtre = sort_name (forme NOM, Prénom qui matche la colonne autor)
      COALESCE(sort_name, preferred_name) AS filter_value
    FROM authors_filtered
    UNION ALL
    SELECT 
      'book'::text AS kind,
      book_id AS id,
      titulo AS label,
      COALESCE(NULLIF(author_display, ''), '—') 
        || COALESCE(' — ' || library_name, '') AS sublabel,
      final_rank AS rank,
      NULL::text AS filter_value  -- non utilisé pour les livres
    FROM books_filtered
  )
  SELECT * FROM all_results
  ORDER BY rank DESC, label ASC
  LIMIT 10;
END;
$$;


ALTER FUNCTION "api"."search_catalog_v1"("q" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "api"."search_catalog_v1"("q" "text") IS 'Recherche full-text dans le catalogue (anon + authenticated). Utilise pg_trgm (similarity, opérateur %). search_path inclut extensions depuis paquet L.7 (2026-05-12) suite au déplacement de pg_trgm hors de public.';



CREATE OR REPLACE FUNCTION "api"."search_subjects"("p_query" "text", "p_limit" integer DEFAULT 12) RETURNS TABLE("id" bigint, "slug" "text", "label_i18n" "jsonb", "parent_id" bigint, "parent_label" "jsonb")
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
  SELECT s.id, s.slug, s.label_i18n, s.parent_id, p.label_i18n
  FROM public.subjects s LEFT JOIN public.subjects p ON p.id = s.parent_id
  WHERE NULLIF(btrim(p_query), '') IS NOT NULL AND (
    s.slug ILIKE '%'||btrim(p_query)||'%'
    OR EXISTS (SELECT 1 FROM jsonb_each_text(s.label_i18n) kv
               WHERE f_normalize_search(kv.value) LIKE '%'||f_normalize_search(btrim(p_query))||'%')
  )
  ORDER BY (s.label_i18n->>'pt-BR'), s.slug
  LIMIT LEAST(COALESCE(p_limit, 12), 50);
$$;


ALTER FUNCTION "api"."search_subjects"("p_query" "text", "p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "api"."send_message_to_reader"("p_library_id" "uuid", "p_reader_id" "uuid", "p_subject" "text", "p_body" "text") RETURNS bigint
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_body text := btrim(coalesce(p_body, ''));
  v_recent int;
  v_id bigint;
BEGIN
  IF char_length(v_body) < 1 THEN
    RAISE EXCEPTION 'empty_body' USING errcode = '22023';
  END IF;
  IF char_length(v_body) > 4000 THEN
    RAISE EXCEPTION 'body_too_long' USING errcode = '22023';
  END IF;

  -- Garde-fou large anti-boucle (pas un anti-spam strict : le staff est de confiance).
  SELECT count(*) INTO v_recent
  FROM public.reader_library_messages
  WHERE sender_id = auth.uid()
    AND recipient_id = p_reader_id
    AND direction = 'library'
    AND created_at > now() - interval '24 hours';

  IF v_recent >= 30 THEN
    RAISE EXCEPTION 'rate_limited' USING errcode = '53400';
  END IF;

  INSERT INTO public.reader_library_messages (library_id, sender_id, recipient_id, direction, subject, body)
  VALUES (p_library_id, auth.uid(), p_reader_id, 'library', NULLIF(btrim(coalesce(p_subject,'')), ''), v_body)
  RETURNING id INTO v_id;

  RETURN v_id;
END;
$$;


ALTER FUNCTION "api"."send_message_to_reader"("p_library_id" "uuid", "p_reader_id" "uuid", "p_subject" "text", "p_body" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "api"."set_reader_message_inbox_state"("p_message_id" bigint, "p_action" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_lib uuid;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'not_authenticated';
  END IF;

  SELECT library_id INTO v_lib
    FROM public.reader_library_messages
    WHERE id = p_message_id;
  IF v_lib IS NULL THEN
    RAISE EXCEPTION 'message_not_found';
  END IF;

  IF NOT public.user_has_library_staff_role(v_uid, v_lib) THEN
    RAISE EXCEPTION 'not_staff';
  END IF;

  IF p_action = 'archive' THEN
    UPDATE public.reader_library_messages
       SET staff_archived_at = now(), staff_archived_by = v_uid
     WHERE id = p_message_id;
  ELSIF p_action = 'unarchive' THEN
    UPDATE public.reader_library_messages
       SET staff_archived_at = NULL, staff_archived_by = NULL
     WHERE id = p_message_id;
  ELSIF p_action = 'delete' THEN
    UPDATE public.reader_library_messages
       SET deleted_at = now(), deleted_by = v_uid
     WHERE id = p_message_id;
  ELSE
    RAISE EXCEPTION 'invalid_action';
  END IF;
END;
$$;


ALTER FUNCTION "api"."set_reader_message_inbox_state"("p_message_id" bigint, "p_action" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "api"."similar_authors"("p_author_id" bigint) RETURNS TABLE("author_id" bigint, "label" "text", "score" integer, "shared_count" integer)
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
WITH tgt_books AS (
  SELECT DISTINCT abp.book_id FROM public.author_books_public abp WHERE abp.author_id = p_author_id
),
tgt_cdd AS (
  SELECT DISTINCT left(c.cdd, 3) AS cdd3
  FROM api.catalog_list_anon_v1 c JOIN tgt_books tb ON tb.book_id = c.book_id
  WHERE c.cdd IS NOT NULL AND btrim(c.cdd) <> ''
),
coauth AS (
  SELECT DISTINCT abp.author_id AS aid
  FROM public.author_books_public abp JOIN tgt_books tb ON tb.book_id = abp.book_id
  WHERE abp.author_id <> p_author_id AND abp.author_id IS NOT NULL
),
cand AS (
  SELECT abp.author_id AS aid, max(COALESCE(abp.preferred_name, abp.author_name)) AS label,
    -- Score : base CDD uniquement (inchange)
    count(DISTINCT abp.book_id) FILTER (WHERE left(c.cdd, 3) IN (SELECT cdd3 FROM tgt_cdd))::int AS shared_cdd_books,
    -- Compteur affiche : union CDD communes + co-signatures (fix)
    count(DISTINCT abp.book_id) FILTER (
      WHERE left(c.cdd, 3) IN (SELECT cdd3 FROM tgt_cdd)
         OR abp.book_id IN (SELECT book_id FROM tgt_books)
    )::int AS shared_all
  FROM public.author_books_public abp JOIN api.catalog_list_anon_v1 c ON c.book_id = abp.book_id
  WHERE abp.author_id <> p_author_id AND abp.author_id IS NOT NULL
  GROUP BY abp.author_id
)
SELECT aid AS author_id, label,
  (shared_cdd_books * 2 + CASE WHEN aid IN (SELECT aid FROM coauth) THEN 5 ELSE 0 END)::int AS score,
  shared_all AS shared_count
FROM cand
WHERE shared_all > 0 OR aid IN (SELECT aid FROM coauth)
ORDER BY score DESC, label
LIMIT 10;
$$;


ALTER FUNCTION "api"."similar_authors"("p_author_id" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "api"."similar_books"("p_book_id" bigint) RETURNS TABLE("book_id" bigint, "titulo" "text", "subtitulo" "text", "author_label" "text", "ano" "text", "editora" "text", "cover_object_path" "text", "bib_ref" "text", "score" integer)
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
WITH tgt AS (
  SELECT c.book_id AS bid,
         NULLIF(btrim(c.cdd), '') AS full_cdd,
         left(c.cdd, 3) AS cdd3,
         NULLIF(btrim(c.colecao), '') AS col,
    (SELECT array_agg(lower(btrim(ch->>'label')))
       FROM jsonb_array_elements(CASE jsonb_typeof(c.author_chips) WHEN 'array' THEN c.author_chips ELSE '[]'::jsonb END) ch
      WHERE btrim(ch->>'label') <> '') AS authors
  FROM api.catalog_list_anon_v1 c WHERE c.book_id = p_book_id LIMIT 1
),
tgt_subjects AS (
  SELECT array_agg(subject_id) AS sids
  FROM public.book_subjects WHERE book_id = p_book_id
),
scored AS (
  SELECT c.book_id, c.titulo, c.subtitulo, COALESCE(c.author_display, c.autor) AS author_label,
         c.ano, c.editora, c.cover_object_path, c.bib_ref,
    ( -- Auteur·ice partagé·e : 5 points
      (CASE WHEN t.authors IS NOT NULL AND EXISTS (
          SELECT 1 FROM jsonb_array_elements(CASE jsonb_typeof(c.author_chips) WHEN 'array' THEN c.author_chips ELSE '[]'::jsonb END) ch
          WHERE lower(btrim(ch->>'label')) = ANY(t.authors)) THEN 5 ELSE 0 END)
      -- Sujets partagés : 2 points PAR sujet en commun
      + COALESCE((SELECT 2 * count(*)
          FROM public.book_subjects bs
          WHERE bs.book_id = c.book_id
            AND ts.sids IS NOT NULL
            AND bs.subject_id = ANY(ts.sids)
        ), 0)
      -- Même division CDD (3 premiers caractères) : 2 points
      + (CASE WHEN t.cdd3 IS NOT NULL AND left(c.cdd, 3) = t.cdd3 THEN 2 ELSE 0 END)
      -- Bonus CDD exact : +1 point si CDD identique au complet
      + (CASE WHEN t.full_cdd IS NOT NULL AND btrim(c.cdd) = t.full_cdd THEN 1 ELSE 0 END)
      -- Même collection : 1 point
      + (CASE WHEN t.col IS NOT NULL AND NULLIF(btrim(c.colecao), '') = t.col THEN 1 ELSE 0 END)
    )::int AS score
  FROM api.catalog_list_anon_v1 c
  CROSS JOIN tgt t
  CROSS JOIN tgt_subjects ts
  WHERE c.book_id <> t.bid
)
SELECT book_id, titulo, subtitulo, author_label, ano, editora, cover_object_path, bib_ref, score
FROM scored WHERE score > 0
ORDER BY score DESC, ano DESC NULLS LAST, titulo
LIMIT 16;
$$;


ALTER FUNCTION "api"."similar_books"("p_book_id" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "api"."unfreeze_account"("p_user_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
BEGIN
  IF v_uid IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'not_authenticated');
  END IF;
  IF NOT public.fn_caller_is_network_admin() THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'not_authorized');
  END IF;

  UPDATE public.profiles
  SET is_restricted = false,
      restricted_reason = NULL,
      restricted_since = NULL,
      restricted_by = NULL
  WHERE id = p_user_id;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'profile_not_found');
  END IF;

  PERFORM public.fn_dispatch_notify_event('member_unfrozen_global', 1,
    jsonb_build_object('user_id', p_user_id::text, 'at', now()::text));

  RETURN jsonb_build_object('ok', true, 'user_id', p_user_id);
END;
$$;


ALTER FUNCTION "api"."unfreeze_account"("p_user_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "api"."unfreeze_account"("p_user_id" "uuid") IS 'EA-10 : leve un gel global. Admin reseau seulement. Chantier D.';



CREATE OR REPLACE FUNCTION "api"."unrestrict_member"("p_user_id" "uuid", "p_library_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_membership_id uuid;
BEGIN
  IF v_uid IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'not_authenticated');
  END IF;
  IF NOT public.user_can_act_as_staff_on_library(p_library_id) THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'not_authorized');
  END IF;

  SELECT id INTO v_membership_id
  FROM public.user_library_memberships
  WHERE user_id = p_user_id AND library_id = p_library_id AND status = 'active'
  LIMIT 1;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'not_a_member');
  END IF;

  UPDATE public.user_library_memberships
  SET is_restricted = false,
      restricted_reason = NULL,
      restricted_by = NULL,
      restricted_at = NULL
  WHERE id = v_membership_id;

  PERFORM public.fn_dispatch_notify_event('member_unrestricted_local', 1,
    jsonb_build_object('user_id', p_user_id::text, 'library_id', p_library_id::text, 'at', now()::text));

  RETURN jsonb_build_object('ok', true, 'membership_id', v_membership_id);
END;
$$;


ALTER FUNCTION "api"."unrestrict_member"("p_user_id" "uuid", "p_library_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "api"."unrestrict_member"("p_user_id" "uuid", "p_library_id" "uuid") IS 'EA-10 : leve une restriction LOCALE. Staff local ou admin reseau. Chantier D.';



CREATE OR REPLACE FUNCTION "api"."validate_membership"("p_membership_id" "uuid", "p_local_reader_number" "text" DEFAULT NULL::"text", "p_note" "text" DEFAULT NULL::"text") RETURNS TABLE("ok" boolean, "message" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_caller uuid := auth.uid();
  v_m record;
BEGIN
  IF v_caller IS NULL THEN
    RAISE EXCEPTION 'Autenticação obrigatória.';
  END IF;

  SELECT m.id, m.user_id, m.library_id, m.status INTO v_m
  FROM public.user_library_memberships m WHERE m.id = p_membership_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Associação não encontrada.';
  END IF;

  -- Staff actif (librarian/coordenador) de CETTE biblio.
  IF NOT EXISTS (
    SELECT 1 FROM public.user_library_memberships s
    WHERE s.user_id = v_caller AND s.library_id = v_m.library_id
      AND s.role IN ('librarian', 'coordenador') AND s.status = 'active'
  ) THEN
    RAISE EXCEPTION 'Acesso de equipe obrigatório nesta biblioteca.'
      USING errcode = 'P0001', hint = 'error.staff_required';
  END IF;

  IF v_m.status <> 'pending_validation' THEN
    RAISE EXCEPTION 'Esta associação não está pendente de validação.'
      USING errcode = 'P0001', hint = 'error.membership.not_pending';
  END IF;

  UPDATE public.user_library_memberships
    SET status = 'active',
        physically_validated_at = now(),
        physically_validated_by_user_id = v_caller,
        physical_validation_note = p_note,
        local_reader_number = COALESCE(p_local_reader_number, local_reader_number),
        updated_at = now()
    WHERE id = p_membership_id;

  INSERT INTO public.membership_validation_log
    (membership_id, user_id, library_id, action, performed_by_user_id, local_reader_number, note)
  VALUES
    (p_membership_id, v_m.user_id, v_m.library_id, 'validated', v_caller, p_local_reader_number, p_note);

  -- P4b : notifier la lectrice (e-mail « inscription confirmée »). Best-effort —
  -- on ne fait pas échouer la validation si le dispatch lève (la notif est
  -- secondaire). fn_dispatch_notify_event poste en async via pg_net.
  BEGIN
    PERFORM public.fn_dispatch_notify_event(
      'validation_confirmed',
      1,
      jsonb_build_object(
        'user_id', v_m.user_id::text,
        'library_id', v_m.library_id::text,
        'membership_id', p_membership_id::text
      )
    );
  EXCEPTION WHEN OTHERS THEN
    RAISE WARNING 'validation_confirmed dispatch failed for membership %: %', p_membership_id, SQLERRM;
  END;

  RETURN QUERY SELECT true, 'Associação validada.'::text;
END $$;


ALTER FUNCTION "api"."validate_membership"("p_membership_id" "uuid", "p_local_reader_number" "text", "p_note" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "ingest"."fn_apply_duplicate_signal_to_match_candidate"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'ingest', 'public', 'pg_temp'
    AS $$
declare
  v_year_equal boolean;
  v_year_conflict boolean;
  v_publisher_match boolean;
  v_place_match boolean;

  v_partner_author_label text;
  v_candidate_author text;
  v_responsibility_match_mode text;
begin
  v_year_equal :=
    nullif(coalesce(new.details->>'year_equal', ''), '')::boolean;

  v_year_conflict :=
    nullif(coalesce(new.details->>'year_conflict', ''), '')::boolean;

  v_publisher_match :=
    nullif(coalesce(new.details->>'publisher_match', ''), '')::boolean;

  v_place_match :=
    nullif(coalesce(new.details->>'place_match', ''), '')::boolean;

  select coalesce(
           nullif(trim(sr.responsibility_statement), ''),
           ingest.fn_format_partner_authors(sr.authors)
         )
    into v_partner_author_label
  from ingest.partner_catalog_staging_rows sr
  where sr.id = new.staging_row_id;

  v_candidate_author := nullif(trim(coalesce(new.details->>'author', '')), '');

  v_responsibility_match_mode :=
    ingest.fn_classify_responsibility_match(
      v_partner_author_label,
      v_candidate_author
    );

  new.details :=
    coalesce(new.details, '{}'::jsonb)
    || jsonb_build_object(
         'duplicate_signal',
         ingest.fn_classify_duplicate_signal(
           new.match_method,
           v_year_equal,
           v_year_conflict,
           v_publisher_match,
           v_place_match
         ),
         'responsibility_match',
         case
           when v_responsibility_match_mode = 'none' then false
           else true
         end,
         'responsibility_match_mode',
         v_responsibility_match_mode
       );

  return new;
end;
$$;


ALTER FUNCTION "ingest"."fn_apply_duplicate_signal_to_match_candidate"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "ingest"."fn_bulk_create_book_drafts_from_run"("p_run_id" bigint, "p_match_statuses" "text"[] DEFAULT NULL::"text"[], "p_editorial_decisions" "text"[] DEFAULT ARRAY['accept_new'::"text", 'accept_duplicate'::"text"], "p_batch_name" "text" DEFAULT NULL::"text", "p_batch_notes" "text" DEFAULT NULL::"text", "p_created_by" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'ingest', 'public', 'auth'
    AS $$
declare
  v_match_statuses text[];
  v_editorial_decisions text[];
  v_row_ids bigint[];
  v_selected_count integer := 0;
  v_result jsonb;
begin
  select coalesce(array_agg(lower(trim(x))), '{}'::text[])
    into v_match_statuses
  from unnest(coalesce(p_match_statuses, '{}'::text[])) as t(x)
  where nullif(trim(x), '') is not null;

  select coalesce(array_agg(lower(trim(x))), '{}'::text[])
    into v_editorial_decisions
  from unnest(coalesce(p_editorial_decisions, '{}'::text[])) as t(x)
  where nullif(trim(x), '') is not null;

  select coalesce(array_agg(sr.id order by sr.row_no, sr.id), '{}'::bigint[])
    into v_row_ids
  from ingest.partner_catalog_staging_rows sr
  where sr.run_id = p_run_id
    and sr.created_book_draft_id is null
    and (
      coalesce(array_length(v_match_statuses, 1), 0) = 0
      or lower(sr.match_status) = any(v_match_statuses)
    )
    and (
      coalesce(array_length(v_editorial_decisions, 1), 0) = 0
      or lower(sr.editorial_decision) = any(v_editorial_decisions)
    )
    and (
      (sr.match_status = 'new_record' and sr.editorial_decision = 'accept_new')
      or
      (sr.match_status in ('matched_book', 'matched_draft', 'possible_duplicate', 'manual_decision')
       and sr.editorial_decision = 'accept_duplicate')
    );

  v_selected_count := coalesce(array_length(v_row_ids, 1), 0);

  if v_selected_count = 0 then
    return jsonb_build_object(
      'run_id', p_run_id,
      'selected_count', 0,
      'message', 'Nenhuma linha elegível para criação em lote'
    );
  end if;

  v_result := ingest.fn_create_book_drafts_from_import_rows(
    p_run_id := p_run_id,
    p_row_ids := v_row_ids,
    p_batch_name := p_batch_name,
    p_batch_notes := p_batch_notes,
    p_created_by := p_created_by
  );

  return v_result || jsonb_build_object(
    'selected_count', v_selected_count,
    'selected_row_ids', to_jsonb(v_row_ids)
  );
end;
$$;


ALTER FUNCTION "ingest"."fn_bulk_create_book_drafts_from_run"("p_run_id" bigint, "p_match_statuses" "text"[], "p_editorial_decisions" "text"[], "p_batch_name" "text", "p_batch_notes" "text", "p_created_by" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "ingest"."fn_bulk_set_partner_catalog_editorial_decision"("p_run_id" bigint, "p_editorial_decision" "text", "p_match_statuses" "text"[] DEFAULT NULL::"text"[], "p_current_editorial_decisions" "text"[] DEFAULT ARRAY['pending'::"text"], "p_editorial_note" "text" DEFAULT NULL::"text", "p_decided_by" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'ingest', 'public', 'auth'
    AS $$
declare
  v_decision text;
  v_actor uuid;
  v_match_statuses text[];
  v_current_decisions text[];
  v_target_count integer := 0;
  v_converted_blocked_count integer := 0;
  v_incompatible_blocked_count integer := 0;
  v_updated_count integer := 0;
  v_refresh jsonb;
begin
  v_decision := lower(trim(p_editorial_decision));
  v_actor := coalesce(p_decided_by, auth.uid());

  if v_decision not in ('pending', 'accept_new', 'accept_duplicate', 'reject') then
    raise exception 'editorial_decision invalide : %', p_editorial_decision;
  end if;

  select coalesce(array_agg(lower(trim(x))), '{}'::text[])
    into v_match_statuses
  from unnest(coalesce(p_match_statuses, '{}'::text[])) as t(x)
  where nullif(trim(x), '') is not null;

  select coalesce(array_agg(lower(trim(x))), '{}'::text[])
    into v_current_decisions
  from unnest(coalesce(p_current_editorial_decisions, '{}'::text[])) as t(x)
  where nullif(trim(x), '') is not null;

  with target_rows as (
    select sr.*
    from ingest.partner_catalog_staging_rows sr
    where sr.run_id = p_run_id
      and (
        coalesce(array_length(v_match_statuses, 1), 0) = 0
        or lower(sr.match_status) = any(v_match_statuses)
      )
      and (
        coalesce(array_length(v_current_decisions, 1), 0) = 0
        or lower(sr.editorial_decision) = any(v_current_decisions)
      )
  )
  select count(*)::integer
    into v_target_count
  from target_rows;

  with target_rows as (
    select sr.*
    from ingest.partner_catalog_staging_rows sr
    where sr.run_id = p_run_id
      and (
        coalesce(array_length(v_match_statuses, 1), 0) = 0
        or lower(sr.match_status) = any(v_match_statuses)
      )
      and (
        coalesce(array_length(v_current_decisions, 1), 0) = 0
        or lower(sr.editorial_decision) = any(v_current_decisions)
      )
  )
  select count(*)::integer
    into v_converted_blocked_count
  from target_rows
  where created_book_draft_id is not null;

  with target_rows as (
    select sr.*
    from ingest.partner_catalog_staging_rows sr
    where sr.run_id = p_run_id
      and (
        coalesce(array_length(v_match_statuses, 1), 0) = 0
        or lower(sr.match_status) = any(v_match_statuses)
      )
      and (
        coalesce(array_length(v_current_decisions, 1), 0) = 0
        or lower(sr.editorial_decision) = any(v_current_decisions)
      )
  )
  select count(*)::integer
    into v_incompatible_blocked_count
  from target_rows
  where created_book_draft_id is null
    and not ingest.fn_is_editorial_decision_compatible(match_status, v_decision);

  with target_rows as (
    select sr.id
    from ingest.partner_catalog_staging_rows sr
    where sr.run_id = p_run_id
      and (
        coalesce(array_length(v_match_statuses, 1), 0) = 0
        or lower(sr.match_status) = any(v_match_statuses)
      )
      and (
        coalesce(array_length(v_current_decisions, 1), 0) = 0
        or lower(sr.editorial_decision) = any(v_current_decisions)
      )
      and sr.created_book_draft_id is null
      and ingest.fn_is_editorial_decision_compatible(sr.match_status, v_decision)
  )
  update ingest.partner_catalog_staging_rows sr
     set editorial_decision = v_decision,
         editorial_note = nullif(trim(p_editorial_note), ''),
         editorial_decided_at = now(),
         editorial_decided_by = v_actor,
         review_status = case
           when v_decision in ('accept_new', 'accept_duplicate') then 'approved'
           when v_decision = 'reject' then 'rejected'
           else 'pending'
         end,
         selected_for_draft = case
           when v_decision in ('accept_new', 'accept_duplicate') then true
           else false
         end
  from target_rows tr
  where sr.id = tr.id;

  get diagnostics v_updated_count = row_count;

  v_refresh := ingest.fn_refresh_partner_catalog_run_counters(p_run_id);

  return jsonb_build_object(
    'run_id', p_run_id,
    'editorial_decision', v_decision,
    'target_rows', v_target_count,
    'updated_rows', v_updated_count,
    'blocked_already_converted', v_converted_blocked_count,
    'blocked_incompatible', v_incompatible_blocked_count,
    'run', v_refresh
  );
end;
$$;


ALTER FUNCTION "ingest"."fn_bulk_set_partner_catalog_editorial_decision"("p_run_id" bigint, "p_editorial_decision" "text", "p_match_statuses" "text"[], "p_current_editorial_decisions" "text"[], "p_editorial_note" "text", "p_decided_by" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "ingest"."fn_classify_duplicate_signal"("p_match_method" "text", "p_year_equal" boolean, "p_year_conflict" boolean, "p_publisher_match" boolean, "p_place_match" boolean) RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO 'ingest', 'public', 'pg_temp'
    AS $$
  select case
    when p_match_method in ('isbn_exact', 'issn_exact')
      then 'strong_duplicate'

    when p_match_method = 'title_author_year'
         and coalesce(p_publisher_match, false)
      then 'strong_duplicate'

    when p_match_method = 'title_author'
         and coalesce(p_year_conflict, false)
         and not coalesce(p_publisher_match, false)
      then 'possible_other_edition'

    when p_match_method in ('title_author_year', 'title_author')
      then 'weak_duplicate'

    else null
  end;
$$;


ALTER FUNCTION "ingest"."fn_classify_duplicate_signal"("p_match_method" "text", "p_year_equal" boolean, "p_year_conflict" boolean, "p_publisher_match" boolean, "p_place_match" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "ingest"."fn_classify_responsibility_match"("p_partner_value" "text", "p_candidate_value" "text") RETURNS "text"
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO 'ingest', 'public', 'pg_temp'
    AS $$
declare
  v_partner_raw text := nullif(trim(coalesce(p_partner_value, '')), '');
  v_candidate_raw text := nullif(trim(coalesce(p_candidate_value, '')), '');
  v_partner_norm text;
  v_candidate_norm text;
  v_partner_init text;
  v_candidate_init text;
begin
  if v_partner_raw is null or v_candidate_raw is null then
    return 'none';
  end if;

  if lower(v_partner_raw) = lower(v_candidate_raw) then
    return 'exact';
  end if;

  v_partner_norm := ingest.fn_match_normalize_responsibility(v_partner_raw);
  v_candidate_norm := ingest.fn_match_normalize_responsibility(v_candidate_raw);

  if v_partner_norm is null or v_candidate_norm is null then
    return 'none';
  end if;

  if v_partner_norm = v_candidate_norm then
    return 'normalized';
  end if;

  v_partner_init := ingest.fn_match_responsibility_initialism(v_partner_norm);
  v_candidate_init := ingest.fn_match_responsibility_initialism(v_candidate_norm);

  if v_partner_norm = v_candidate_init
     or v_candidate_norm = v_partner_init
     or (v_partner_init is not null and v_candidate_init is not null and v_partner_init = v_candidate_init)
  then
    return 'acronym';
  end if;

  if length(v_partner_norm) >= 6 and position(v_partner_norm in v_candidate_norm) > 0 then
    return 'partial';
  end if;

  if length(v_candidate_norm) >= 6 and position(v_candidate_norm in v_partner_norm) > 0 then
    return 'partial';
  end if;

  return 'none';
end;
$$;


ALTER FUNCTION "ingest"."fn_classify_responsibility_match"("p_partner_value" "text", "p_candidate_value" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "ingest"."fn_create_book_drafts_from_import_rows"("p_run_id" bigint, "p_row_ids" bigint[] DEFAULT NULL::bigint[], "p_batch_name" "text" DEFAULT NULL::"text", "p_batch_notes" "text" DEFAULT NULL::"text", "p_created_by" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'ingest', 'public', 'auth'
    AS $$
declare
  v_actor uuid;
  v_partner_name text;
  v_relation_status text;
  v_original_filename text;
  v_detected_format text;
  v_batch_id bigint;
  v_batch_name text;
  v_batch_notes text;
  v_created_count integer := 0;
  v_requested_count integer := 0;
  v_draft_id bigint;
  v_refresh jsonb;
  v_collection_hint text;
  v_local_classification_hint text;
  v_provenance_note text;
  rec record;
begin
  v_actor := coalesce(p_created_by, auth.uid());

  select s.partner_name, s.relation_status, r.original_filename, r.detected_format
    into v_partner_name, v_relation_status, v_original_filename, v_detected_format
  from ingest.partner_catalog_import_runs r
  join ingest.partner_catalog_sources s on s.id = r.source_id
  where r.id = p_run_id;

  if not found then
    raise exception 'import_run % introuvable', p_run_id;
  end if;

  if coalesce(array_length(p_row_ids, 1), 0) > 0 then
    select count(*)::integer
      into v_requested_count
    from ingest.partner_catalog_staging_rows sr
    where sr.run_id = p_run_id
      and sr.id = any(p_row_ids)
      and sr.created_book_draft_id is null
      and (
        (sr.match_status = 'new_record' and sr.editorial_decision = 'accept_new')
        or
        (sr.match_status in ('matched_book', 'matched_draft', 'possible_duplicate', 'manual_decision')
         and sr.editorial_decision = 'accept_duplicate')
      );
  else
    select count(*)::integer
      into v_requested_count
    from ingest.partner_catalog_staging_rows sr
    where sr.run_id = p_run_id
      and sr.created_book_draft_id is null
      and sr.selected_for_draft = true
      and sr.review_status = 'approved'
      and (
        (sr.match_status = 'new_record' and sr.editorial_decision = 'accept_new')
        or
        (sr.match_status in ('matched_book', 'matched_draft', 'possible_duplicate', 'manual_decision')
         and sr.editorial_decision = 'accept_duplicate')
      );
  end if;

  if v_requested_count = 0 then
    raise exception 'Aucune ligne autorisée à convertir pour le run %', p_run_id;
  end if;

  v_batch_name := coalesce(
    nullif(trim(p_batch_name), ''),
    format(
      'Import parceiro #%s — %s — %s',
      p_run_id,
      left(coalesce(v_partner_name, 'parceiro sem nome'), 80),
      to_char(now() at time zone 'UTC', 'YYYY-MM-DD HH24:MI UTC')
    )
  );

  v_batch_notes := coalesce(
    nullif(trim(p_batch_notes), ''),
    format(
      'Lote criado a partir do import run %s (%s, formato %s).',
      p_run_id,
      coalesce(v_original_filename, 'arquivo sem nome'),
      coalesce(v_detected_format, 'unknown')
    )
  );

  insert into public.catalog_batches (name, notes, created_by)
  values (v_batch_name, v_batch_notes, v_actor)
  returning id into v_batch_id;

  for rec in
    select sr.*, r.original_filename, r.detected_format, s.partner_name, s.relation_status, s.source_kind
    from ingest.partner_catalog_staging_rows sr
    join ingest.partner_catalog_import_runs r on r.id = sr.run_id
    join ingest.partner_catalog_sources s on s.id = r.source_id
    where sr.run_id = p_run_id
      and sr.created_book_draft_id is null
      and not exists (
        select 1 from ingest.partner_catalog_row_to_draft rd where rd.staging_row_id = sr.id
      )
      and (
        (coalesce(array_length(p_row_ids, 1), 0) > 0 and sr.id = any(p_row_ids))
        or
        (coalesce(array_length(p_row_ids, 1), 0) = 0 and sr.selected_for_draft = true and sr.review_status = 'approved')
      )
      and (
        (sr.match_status = 'new_record' and sr.editorial_decision = 'accept_new')
        or
        (sr.match_status in ('matched_book', 'matched_draft', 'possible_duplicate', 'manual_decision')
         and sr.editorial_decision = 'accept_duplicate')
      )
    order by sr.row_no, sr.id
  loop
    v_collection_hint := ingest.fn_partner_catalog_extract_collection_hint(rec.normalized_payload, rec.raw_payload);
    v_local_classification_hint := ingest.fn_partner_catalog_extract_local_classification_hint(rec.normalized_payload, rec.raw_payload);

    v_provenance_note := format(
      'Importado de catálogo parceiro "%s" (%s, run %s, linha %s, formato bruto %s, relação %s, decisão %s).',
      rec.partner_name,
      coalesce(rec.original_filename, 'arquivo sem nome'),
      rec.run_id,
      rec.row_no,
      coalesce(rec.detected_format, 'unknown'),
      coalesce(rec.relation_status, 'sem_status'),
      coalesce(rec.editorial_decision, 'pending')
    );

    if v_local_classification_hint is not null then
      v_provenance_note := v_provenance_note || format(' Sinal local da parceira preservado: %s.', v_local_classification_hint);
    end if;

    insert into public.book_drafts (
      batch_id,
      action,
      status,
      titulo,
      subtitulo,
      autor,
      edicao,
      local_publicacao,
      editora,
      ano,
      isbn,
      issn,
      idioma,
      tipo_material,
      cdd,
      colecao,
      marc_json,
      created_by,
      updated_by,
      acquisition_mode,
      partner_source,
      source_record_id,
      import_format,
      import_method,
      provenance_note,
      mutualization_status,
      source_label,
      notas
    ) values (
      v_batch_id,
      'create',
      'draft',
      nullif(trim(rec.title), ''),
      nullif(trim(rec.subtitle), ''),
      coalesce(nullif(trim(rec.responsibility_statement), ''), ingest.fn_format_partner_authors(rec.authors)),
      nullif(trim(rec.edition_statement), ''),
      nullif(trim(rec.place_of_publication), ''),
      nullif(trim(rec.publisher), ''),
      nullif(trim(rec.publication_year), ''),
      nullif(trim(rec.isbn), ''),
      nullif(trim(rec.issn), ''),
      nullif(trim(rec.language), ''),
      coalesce(nullif(trim(rec.item_type), ''), 'Livro'),
      null,
      case
        when v_collection_hint is null then null
        when lower(coalesce(rec.item_type, '')) ~ '(periodic|journal|article|boletim|periodico|periódico)' then null
        when lower(regexp_replace(coalesce(v_collection_hint, ''), '\s+', ' ', 'g')) = lower(regexp_replace(coalesce(rec.title, ''), '\s+', ' ', 'g')) then null
        else v_collection_hint
      end,
      coalesce(rec.normalized_payload, '{}'::jsonb)
        || jsonb_build_object(
             'ingest',
             jsonb_build_object(
               'run_id', rec.run_id,
               'staging_row_id', rec.id,
               'row_no', rec.row_no,
               'source_file_id', rec.source_file_id,
               'partner_name', rec.partner_name,
               'relation_status', rec.relation_status,
               'original_filename', rec.original_filename,
               'detected_format', rec.detected_format,
               'raw_payload', coalesce(rec.raw_payload, '{}'::jsonb),
               'authors', coalesce(rec.authors, '[]'::jsonb),
               'subjects', coalesce(rec.subjects, '[]'::jsonb),
               'editorial_decision', rec.editorial_decision,
               'editorial_note', rec.editorial_note,
               'derived_collection_hint', v_collection_hint,
               'derived_local_classification_hint', v_local_classification_hint
             )
           ),
      v_actor,
      v_actor,
      null,
      rec.partner_name,                              -- partner_source (rigueur source)
      coalesce(nullif(trim(rec.external_key), ''), rec.id::text),
      rec.detected_format,                           -- import_format (rigueur source)
      coalesce(rec.source_kind, 'partner_catalog'),  -- import_method (rigueur source)
      v_provenance_note,
      null,
      coalesce(rec.original_filename, rec.partner_name),
      concat_ws(
        ' ',
        case
          when rec.subjects is not null
           and jsonb_typeof(rec.subjects) = 'array'
           and jsonb_array_length(rec.subjects) > 0
          then 'Assuntos importados: '
               || array_to_string(array(select jsonb_array_elements_text(rec.subjects)), '; ')
          else null
        end,
        case
          when v_local_classification_hint is not null
          then format('Classificação / cote local preservada da parceira: %s.', v_local_classification_hint)
          else null
        end
      )
    ) returning id into v_draft_id;

    insert into ingest.partner_catalog_row_to_draft (staging_row_id, run_id, draft_id, batch_id, created_by)
    values (rec.id, rec.run_id, v_draft_id, v_batch_id, v_actor);

    update ingest.partner_catalog_staging_rows
       set created_book_draft_id = v_draft_id,
           review_status = 'draft_created',
           selected_for_draft = false
     where id = rec.id;

    v_created_count := v_created_count + 1;
  end loop;

  if v_created_count = 0 then
    delete from public.catalog_batches where id = v_batch_id;
    raise exception 'Aucun rascunho créé pour le run %', p_run_id;
  end if;

  v_refresh := ingest.fn_refresh_partner_catalog_run_counters(p_run_id);

  return jsonb_build_object(
    'run_id', p_run_id,
    'batch_id', v_batch_id,
    'batch_name', v_batch_name,
    'requested_rows', v_requested_count,
    'created_drafts', v_created_count,
    'run', v_refresh
  );
end;
$$;


ALTER FUNCTION "ingest"."fn_create_book_drafts_from_import_rows"("p_run_id" bigint, "p_row_ids" bigint[], "p_batch_name" "text", "p_batch_notes" "text", "p_created_by" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "ingest"."fn_create_book_drafts_from_import_rows"("p_run_id" bigint, "p_row_ids" bigint[], "p_batch_name" "text", "p_batch_notes" "text", "p_created_by" "uuid") IS 'S3 : conserve prudemment les indices de collection/série et de cote locale dans les rascunhos issus d’imports partenaires, sans surinterpréter CN comme une CDD.';



CREATE OR REPLACE FUNCTION "ingest"."fn_create_partner_catalog_import"("p_source_id" bigint, "p_storage_path" "text", "p_original_filename" "text", "p_bucket_id" "text" DEFAULT 'catalogos_parceiros_raw'::"text", "p_mime_type" "text" DEFAULT NULL::"text", "p_size_bytes" bigint DEFAULT NULL::bigint, "p_sha256" "text" DEFAULT NULL::"text", "p_detected_format" "text" DEFAULT 'unknown'::"text", "p_requested_by" "uuid" DEFAULT NULL::"uuid") RETURNS bigint
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'ingest', 'public', 'auth'
    AS $$
declare
  v_source ingest.partner_catalog_sources%rowtype;
  v_existing_run_id bigint;
  v_new_run_id bigint;
  v_actor uuid;
begin
  select *
    into v_source
  from ingest.partner_catalog_sources
  where id = p_source_id;

  if not found then
    raise exception 'partner_catalog_source % introuvable', p_source_id;
  end if;

  if coalesce(v_source.import_enabled, false) is not true then
    raise exception 'La source % n''autorise pas encore les imports', p_source_id;
  end if;

  if p_sha256 is not null then
    select r.id
      into v_existing_run_id
    from ingest.partner_catalog_import_runs r
    where r.source_id = p_source_id
      and r.sha256 = p_sha256
    order by r.id desc
    limit 1;

    if v_existing_run_id is not null then
      return v_existing_run_id;
    end if;
  end if;

  v_actor := coalesce(p_requested_by, auth.uid());

  insert into ingest.partner_catalog_import_runs (
    source_id,
    requested_by,
    bucket_id,
    storage_path,
    original_filename,
    mime_type,
    size_bytes,
    sha256,
    detected_format,
    run_status,
    parser_version
  ) values (
    p_source_id,
    v_actor,
    coalesce(nullif(trim(p_bucket_id), ''), 'catalogos_parceiros_raw'),
    p_storage_path,
    p_original_filename,
    p_mime_type,
    p_size_bytes,
    p_sha256,
    coalesce(nullif(lower(trim(p_detected_format)), ''), 'unknown'),
    'uploaded',
    'v1'
  )
  returning id into v_new_run_id;

  return v_new_run_id;
end;
$$;


ALTER FUNCTION "ingest"."fn_create_partner_catalog_import"("p_source_id" bigint, "p_storage_path" "text", "p_original_filename" "text", "p_bucket_id" "text", "p_mime_type" "text", "p_size_bytes" bigint, "p_sha256" "text", "p_detected_format" "text", "p_requested_by" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "ingest"."fn_create_partner_catalog_import"("p_source_id" bigint, "p_storage_path" "text", "p_original_filename" "text", "p_bucket_id" "text", "p_mime_type" "text", "p_size_bytes" bigint, "p_sha256" "text", "p_detected_format" "text", "p_requested_by" "uuid") IS 'Creates a partner import run in status "uploaded" only. S4 decision: dispatch remains an explicit second step; no automatic post-create dispatch is introduced here.';



CREATE OR REPLACE FUNCTION "ingest"."fn_dispatch_partner_catalog_import"("p_run_id" bigint, "p_force_reparse" boolean DEFAULT false) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'ingest', 'public', 'auth'
    AS $$
declare
  v_run ingest.partner_catalog_import_runs%rowtype;
  v_secret text;
  v_request_id bigint;
  v_body jsonb;
  v_log_id bigint;
  v_function_url text := 'https://uflwmikiyjfnikiphtcp.supabase.co/functions/v1/process-partner-catalog-import';
begin
  select *
    into v_run
  from ingest.partner_catalog_import_runs
  where id = p_run_id;

  if not found then
    raise exception 'Run % introuvable', p_run_id;
  end if;

  select ds.decrypted_secret
    into v_secret
  from vault.decrypted_secrets ds
  where ds.name = 'ANARBIB_PARTNER_IMPORT_SECRET'
  order by ds.created_at desc
  limit 1;

  if coalesce(v_secret, '') = '' then
    raise exception 'Secret ANARBIB_PARTNER_IMPORT_SECRET introuvable dans vault.decrypted_secrets';
  end if;

  v_body := jsonb_build_object(
    'run_id', p_run_id,
    'force_reparse', p_force_reparse
  );

  insert into ingest.partner_catalog_import_dispatch_log (
    run_id,
    force_reparse,
    request_body,
    requested_by,
    dispatch_status
  )
  values (
    p_run_id,
    p_force_reparse,
    v_body,
    auth.uid(),
    'queued'
  )
  returning id into v_log_id;

  v_request_id := net.http_post(
    url := v_function_url,
    headers := jsonb_build_object(
      'Content-Type', 'application/json',
      'x-import-secret', v_secret
    ),
    body := v_body,
    timeout_milliseconds := 60000
  );

  update ingest.partner_catalog_import_dispatch_log
     set request_id = v_request_id,
         dispatch_status = 'sent'
   where id = v_log_id;

  return jsonb_build_object(
    'ok', true,
    'run_id', p_run_id,
    'dispatch_log_id', v_log_id,
    'request_id', v_request_id,
    'force_reparse', p_force_reparse,
    'function_url', v_function_url
  );
exception
  when others then
    if v_log_id is not null then
      update ingest.partner_catalog_import_dispatch_log
         set dispatch_status = 'failed',
             error_text = sqlerrm
       where id = v_log_id;
    end if;
    raise;
end;
$$;


ALTER FUNCTION "ingest"."fn_dispatch_partner_catalog_import"("p_run_id" bigint, "p_force_reparse" boolean) OWNER TO "postgres";


COMMENT ON FUNCTION "ingest"."fn_dispatch_partner_catalog_import"("p_run_id" bigint, "p_force_reparse" boolean) IS 'Explicit backend dispatch of process-partner-catalog-import via pg_net. S4 decision: dispatch remains manual/explicit and is not chained automatically after import_run creation.';



CREATE OR REPLACE FUNCTION "ingest"."fn_extract_year4"("p_text" "text") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO 'ingest', 'public', 'pg_temp'
    AS $$
  select substring(coalesce(p_text, '') from '([12][0-9]{3})');
$$;


ALTER FUNCTION "ingest"."fn_extract_year4"("p_text" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "ingest"."fn_format_partner_authors"("p_authors" "jsonb") RETURNS "text"
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO 'ingest', 'public', 'pg_temp'
    AS $$
declare
  v_result text;
begin
  if p_authors is null or jsonb_typeof(p_authors) <> 'array' or jsonb_array_length(p_authors) = 0 then
    return null;
  end if;

  select string_agg(
           nullif(
             trim(
               coalesce(
                 a->>'display',
                 concat_ws(', ',
                   nullif(a->>'family', ''),
                   nullif(a->>'given', '')
                 )
               )
             ),
             ''
           ),
           '; ' order by ord
         )
    into v_result
  from jsonb_array_elements(p_authors) with ordinality as t(a, ord);

  return nullif(trim(v_result), '');
end;
$$;


ALTER FUNCTION "ingest"."fn_format_partner_authors"("p_authors" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "ingest"."fn_is_editorial_decision_compatible"("p_match_status" "text", "p_editorial_decision" "text") RETURNS boolean
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO 'ingest', 'public', 'pg_temp'
    AS $$
  select case lower(coalesce(trim(p_editorial_decision), ''))
    when 'pending' then true
    when 'reject' then true
    when 'accept_new' then lower(coalesce(trim(p_match_status), '')) = 'new_record'
    when 'accept_duplicate' then lower(coalesce(trim(p_match_status), '')) in (
      'matched_book',
      'matched_draft',
      'possible_duplicate',
      'manual_decision'
    )
    else false
  end;
$$;


ALTER FUNCTION "ingest"."fn_is_editorial_decision_compatible"("p_match_status" "text", "p_editorial_decision" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "ingest"."fn_match_normalize_publisher"("p_text" "text") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO 'ingest', 'public', 'pg_temp'
    AS $$
  with norm as (
    select ingest.fn_match_normalize_text(p_text) as t
  )
  select nullif(
    trim(
      regexp_replace(
        coalesce(t, ''),
        '^(?:(?:les|las|los|le|la)\s+)?(?:editora|editorial|edicoes|edições|edition|édition|editions|éditions|editor|editeur|éditeur|editeurs|éditeurs)\s+(?:(?:do|da|de|du|des|del|dos|das)\s+)?',
        '',
        'g'
      )
    ),
    ''
  )
  from norm;
$$;


ALTER FUNCTION "ingest"."fn_match_normalize_publisher"("p_text" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "ingest"."fn_match_normalize_responsibility"("p_value" "text") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO 'ingest', 'public', 'pg_temp'
    AS $_$
  with base as (
    select ingest.fn_match_normalize_text(coalesce(p_value, '')) as v
  ),
  cleaned as (
    select regexp_replace(
             v,
             '(^| )(org|orgs|organizador|organizadora|organizadores|organizadoras|organizacao|organizacoes|coord|coords|coordenador|coordenadora|coordenadores|coordenadoras|coordenacao|ed|eds|editor|editora|editores|editoras)( |$)',
             ' ',
             'g'
           ) as v
    from base
  )
  select nullif(trim(regexp_replace(v, '\s+', ' ', 'g')), '')
  from cleaned;
$_$;


ALTER FUNCTION "ingest"."fn_match_normalize_responsibility"("p_value" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "ingest"."fn_match_normalize_text"("p_text" "text") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO 'ingest', 'public', 'pg_temp'
    AS $$
  select nullif(
    trim(
      regexp_replace(
        regexp_replace(
          lower(coalesce(p_text, '')),
          '[^[:alnum:]]+',
          ' ',
          'g'
        ),
        '\s+',
        ' ',
        'g'
      )
    ),
    ''
  );
$$;


ALTER FUNCTION "ingest"."fn_match_normalize_text"("p_text" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "ingest"."fn_match_partner_catalog_row"("p_staging_row_id" bigint) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'ingest', 'public', 'auth'
    SET "statement_timeout" TO '0'
    AS $$
declare
  rec ingest.partner_catalog_staging_rows%rowtype;
  v_author_label text;
  v_title_norm text;
  v_author_norm text;
  v_year_norm text;
  v_isbn_norm text;
  v_issn_norm text;
  v_publisher_norm text;
  v_place_norm text;

  v_top_candidate_type text;
  v_top_candidate_id bigint;
  v_top_match_method text;
  v_top_match_score numeric(5,2);

  v_match_status text := 'new_record';
  v_proposed_book_id bigint := null;
  v_proposed_book_draft_id bigint := null;
begin
  select *
    into rec
  from ingest.partner_catalog_staging_rows
  where id = p_staging_row_id;

  if not found then
    raise exception 'staging_row % introuvable', p_staging_row_id;
  end if;

  v_author_label := coalesce(
    nullif(trim(rec.responsibility_statement), ''),
    ingest.fn_format_partner_authors(rec.authors)
  );

  v_title_norm     := ingest.fn_match_normalize_text(rec.title);
  v_author_norm    := ingest.fn_match_normalize_text(v_author_label);
