            else false
          end,
          case
            when v_publisher_norm is not null
             and ingest.fn_match_normalize_publisher(d.editora) = v_publisher_norm
            then true
            else false
          end,
          case
            when v_place_norm is not null
             and ingest.fn_match_normalize_text(d.local_publicacao) = v_place_norm
            then true
            else false
          end
        )
    )
  from public.book_drafts d
  where v_title_norm is not null
    and v_author_norm is not null
    and ingest.fn_match_normalize_text(d.titulo) = v_title_norm
    and ingest.fn_match_normalize_text(d.autor) = v_author_norm
  on conflict do nothing;

  -- -------------------------------------------------------
  -- CHOIX DU MEILLEUR CANDIDAT
  -- -------------------------------------------------------
  select
    mc.candidate_type,
    mc.candidate_id,
    mc.match_method,
    mc.match_score
  into
    v_top_candidate_type,
    v_top_candidate_id,
    v_top_match_method,
    v_top_match_score
  from ingest.partner_catalog_match_candidates mc
  where mc.staging_row_id = p_staging_row_id
  order by
    mc.match_score desc,
    case mc.candidate_type
      when 'book' then 0
      when 'book_draft' then 1
      else 9
    end,
    mc.id
  limit 1;

  if v_top_candidate_id is null then
    v_match_status := 'new_record';
  elsif v_top_match_method in ('isbn_exact', 'issn_exact') and v_top_candidate_type = 'book' then
    v_match_status := 'matched_book';
    v_proposed_book_id := v_top_candidate_id;
  elsif v_top_match_method in ('isbn_exact', 'issn_exact') and v_top_candidate_type = 'book_draft' then
    v_match_status := 'matched_draft';
    v_proposed_book_draft_id := v_top_candidate_id;
  elsif v_top_candidate_type = 'book' then
    v_match_status := 'possible_duplicate';
    v_proposed_book_id := v_top_candidate_id;
  elsif v_top_candidate_type = 'book_draft' then
    v_match_status := 'possible_duplicate';
    v_proposed_book_draft_id := v_top_candidate_id;
  else
    v_match_status := 'manual_decision';
  end if;

  update ingest.partner_catalog_staging_rows
     set match_status = v_match_status,
         proposed_book_id = v_proposed_book_id,
         proposed_book_draft_id = v_proposed_book_draft_id
   where id = p_staging_row_id;

  return jsonb_build_object(
    'staging_row_id', p_staging_row_id,
    'match_status', v_match_status,
    'top_candidate_type', v_top_candidate_type,
    'top_candidate_id', v_top_candidate_id,
    'top_match_method', v_top_match_method,
    'top_match_score', v_top_match_score
  );
end;
$$;


ALTER FUNCTION "ingest"."fn_match_partner_catalog_row"("p_staging_row_id" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "ingest"."fn_match_partner_catalog_run"("p_run_id" bigint, "p_row_ids" bigint[] DEFAULT NULL::bigint[]) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'ingest', 'public', 'auth'
    SET "statement_timeout" TO '0'
    AS $$
declare
  v_row_count integer := 0;
  v_matched_count integer := 0;
  v_refresh jsonb;
  rec record;
begin
  if not exists (
    select 1
    from ingest.partner_catalog_import_runs
    where id = p_run_id
  ) then
    raise exception 'import_run % introuvable', p_run_id;
  end if;

  update ingest.partner_catalog_import_runs
     set run_status = case
       when run_status = 'drafts_created' then run_status
       else 'matching'
     end
   where id = p_run_id;

  for rec in
    select sr.id
    from ingest.partner_catalog_staging_rows sr
    where sr.run_id = p_run_id
      and (
        coalesce(array_length(p_row_ids, 1), 0) = 0
        or sr.id = any(p_row_ids)
      )
    order by sr.row_no, sr.id
  loop
    v_row_count := v_row_count + 1;
    perform ingest.fn_match_partner_catalog_row(rec.id);
    v_matched_count := v_matched_count + 1;
  end loop;

  v_refresh := ingest.fn_refresh_partner_catalog_run_counters(p_run_id);

  return jsonb_build_object(
    'run_id', p_run_id,
    'requested_rows', v_row_count,
    'matched_rows', v_matched_count,
    'run', v_refresh
  );
end;
$$;


ALTER FUNCTION "ingest"."fn_match_partner_catalog_run"("p_run_id" bigint, "p_row_ids" bigint[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "ingest"."fn_match_responsibility_initialism"("p_value" "text") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO 'ingest', 'public', 'pg_temp'
    AS $$
  with norm as (
    select ingest.fn_match_normalize_responsibility(p_value) as v
  ),
  tokens as (
    select token, ord
    from norm,
         unnest(regexp_split_to_array(coalesce(v, ''), '\s+')) with ordinality as t(token, ord)
  ),
  filtered as (
    select token, ord
    from tokens
    where token <> ''
      and token not in ('de', 'do', 'da', 'dos', 'das', 'e')
  )
  select nullif(string_agg(left(token, 1), '' order by ord), '')
  from filtered;
$$;


ALTER FUNCTION "ingest"."fn_match_responsibility_initialism"("p_value" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "ingest"."fn_normalize_isxn"("p_text" "text") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO 'ingest', 'public', 'pg_temp'
    AS $$
  select nullif(
    upper(regexp_replace(coalesce(p_text, ''), '[^0-9A-Za-z]+', '', 'g')),
    ''
  );
$$;


