CREATE OR REPLACE FUNCTION "ingest"."fn_partner_catalog_extract_collection_hint"("p_normalized_payload" "jsonb", "p_raw_payload" "jsonb") RETURNS "text"
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO 'ingest', 'public', 'pg_temp'
    AS $$
declare
  v_value text;
begin
  v_value := nullif(btrim(coalesce(
    p_normalized_payload #>> '{collection,title}',
    p_normalized_payload #>> '{collection,label}',
    p_normalized_payload #>> '{series,title}',
    p_normalized_payload #>> '{series,label}',
    p_normalized_payload ->> 'collection',
    p_normalized_payload ->> 'series',
    p_normalized_payload ->> 'series_statement',
    p_normalized_payload #>> '{host,title}',
    p_normalized_payload #>> '{host,main_title}',
    p_raw_payload #>> '{ris,T2}',
    p_raw_payload #>> '{ris_tags,T2,0}',
    p_raw_payload #>> '{ris_tags,T2}',
    p_raw_payload #>> '{tags,T2,0}',
    p_raw_payload #>> '{tags,T2}',
    p_raw_payload #>> '{fields,T2}',
    p_raw_payload #>> '{fields,secondary_title}',
    p_raw_payload ->> 'T2',
    p_raw_payload #>> '{series,title}',
    p_raw_payload #>> '{collection,title}',
    p_raw_payload ->> 'series',
    p_raw_payload ->> 'collection'
  )), '');

  if v_value is null then
    return null;
  end if;

  if lower(v_value) in ('n/a', 'na', 'null', 'undefined', 'sem coleção', 'sem serie', 'sem série') then
    return null;
  end if;

  return v_value;
end;
$$;


ALTER FUNCTION "ingest"."fn_partner_catalog_extract_collection_hint"("p_normalized_payload" "jsonb", "p_raw_payload" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "ingest"."fn_partner_catalog_extract_collection_hint"("p_normalized_payload" "jsonb", "p_raw_payload" "jsonb") IS 'S3 : extrait prudemment un indice de collection / série depuis les payloads normalisés ou bruts (incluant RIS/T2) sans imposer d’interprétation métier trop agressive.';



