CREATE OR REPLACE FUNCTION "ingest"."fn_refresh_partner_catalog_run_counters"("p_run_id" bigint) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'ingest', 'public', 'auth'
    SET "statement_timeout" TO '0'
    AS $$
declare
  v_imported_rows integer := 0;
  v_selected_rows integer := 0;
  v_created_drafts integer := 0;
  v_run_status text;
begin
  if not exists (
    select 1
    from ingest.partner_catalog_import_runs
    where id = p_run_id
  ) then
    raise exception 'import_run % introuvable', p_run_id;
  end if;

  select
    count(*)::integer,
    count(*) filter (where selected_for_draft = true)::integer,
    count(*) filter (where created_book_draft_id is not null)::integer
  into
    v_imported_rows,
    v_selected_rows,
    v_created_drafts
  from ingest.partner_catalog_staging_rows
  where run_id = p_run_id;

  update ingest.partner_catalog_import_runs r
     set imported_rows = v_imported_rows,
         selected_rows = v_selected_rows,
         created_drafts = v_created_drafts,
         run_status = case
           when v_created_drafts > 0 then 'drafts_created'
           when r.run_status in ('uploaded', 'queued', 'processing', 'parsed', 'matching')
                and v_imported_rows > 0
             then 'ready_for_review'
           else r.run_status
         end
   where r.id = p_run_id
   returning r.run_status into v_run_status;

  return jsonb_build_object(
    'run_id', p_run_id,
    'imported_rows', v_imported_rows,
    'selected_rows', v_selected_rows,
    'created_drafts', v_created_drafts,
    'run_status', v_run_status
  );
end;
$$;


ALTER FUNCTION "ingest"."fn_refresh_partner_catalog_run_counters"("p_run_id" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "ingest"."fn_set_partner_catalog_editorial_decision"("p_run_id" bigint, "p_row_ids" bigint[], "p_editorial_decision" "text", "p_editorial_note" "text" DEFAULT NULL::"text", "p_decided_by" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'ingest', 'public', 'auth'
    AS $$
declare
  v_decision text;
  v_actor uuid;
  v_updated_count integer := 0;
  v_blocked_count integer := 0;
  v_incompatible_count integer := 0;
  v_refresh jsonb;
begin
  if coalesce(array_length(p_row_ids, 1), 0) = 0 then
    raise exception 'Aucune ligne fournie';
  end if;

  v_decision := lower(trim(p_editorial_decision));
  v_actor := coalesce(p_decided_by, auth.uid());

  if v_decision not in ('pending', 'accept_new', 'accept_duplicate', 'reject') then
    raise exception 'editorial_decision invalide : %', p_editorial_decision;
  end if;

  select count(*)::integer
    into v_blocked_count
  from ingest.partner_catalog_staging_rows sr
  where sr.run_id = p_run_id
    and sr.id = any(p_row_ids)
    and sr.created_book_draft_id is not null;

  if v_blocked_count > 0 then
    raise exception 'Au moins une ligne a déjà été convertie en rascunho ; décision éditoriale verrouillée';
  end if;

  select count(*)::integer
    into v_incompatible_count
  from ingest.partner_catalog_staging_rows sr
  where sr.run_id = p_run_id
    and sr.id = any(p_row_ids)
    and not ingest.fn_is_editorial_decision_compatible(sr.match_status, v_decision);

  if v_incompatible_count > 0 then
    raise exception 'Décision éditoriale % incompatible avec au moins une ligne sélectionnée', v_decision;
  end if;

  update ingest.partner_catalog_staging_rows sr
     set editorial_decision = v_decision,
         editorial_note = nullif(trim(p_editorial_note), ''),
         editorial_decided_at = now(),
         editorial_decided_by = v_actor,
         review_status = case
           when v_decision in ('accept_new', 'accept_duplicate') then 'approved'
           when v_decision = 'reject' then 'rejected'
           else 'pending'
         end,
         selected_for_draft = case
           when v_decision in ('accept_new', 'accept_duplicate') then true
           else false
         end
   where sr.run_id = p_run_id
     and sr.id = any(p_row_ids);

  get diagnostics v_updated_count = row_count;

  v_refresh := ingest.fn_refresh_partner_catalog_run_counters(p_run_id);

  return jsonb_build_object(
    'run_id', p_run_id,
    'updated_rows', v_updated_count,
    'editorial_decision', v_decision,
    'run', v_refresh
  );
end;
$$;


ALTER FUNCTION "ingest"."fn_set_partner_catalog_editorial_decision"("p_run_id" bigint, "p_row_ids" bigint[], "p_editorial_decision" "text", "p_editorial_note" "text", "p_decided_by" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "ingest"."fn_set_partner_catalog_rows_review"("p_run_id" bigint, "p_row_ids" bigint[], "p_review_status" "text", "p_selected_for_draft" boolean DEFAULT NULL::boolean, "p_match_status" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'ingest', 'public', 'auth'
    AS $$
declare
  v_review_status text;
  v_match_status text;
  v_updated_count integer := 0;
  v_refresh jsonb;
begin
  if coalesce(array_length(p_row_ids, 1), 0) = 0 then
    raise exception 'Aucune ligne fournie';
  end if;

  v_review_status := lower(trim(p_review_status));

  if v_review_status not in ('pending', 'approved', 'rejected') then
    raise exception 'review_status invalide : %', p_review_status;
  end if;

  if p_match_status is not null then
    v_match_status := lower(trim(p_match_status));

    if v_match_status not in (
      'unreviewed',
      'new_record',
      'possible_duplicate',
      'matched_book',
      'matched_draft',
      'manual_decision'
    ) then
      raise exception 'match_status invalide : %', p_match_status;
    end if;
  else
    v_match_status := null;
  end if;

  update ingest.partner_catalog_staging_rows sr
     set review_status = v_review_status,
         selected_for_draft = case
           when p_selected_for_draft is not null then p_selected_for_draft
           when v_review_status = 'approved' then true
           when v_review_status = 'rejected' then false
           else sr.selected_for_draft
         end,
         match_status = coalesce(v_match_status, sr.match_status)
   where sr.run_id = p_run_id
     and sr.id = any(p_row_ids);

  get diagnostics v_updated_count = row_count;

  v_refresh := ingest.fn_refresh_partner_catalog_run_counters(p_run_id);

  return jsonb_build_object(
    'run_id', p_run_id,
    'updated_rows', v_updated_count,
    'review_status', v_review_status,
    'match_status', v_match_status,
    'run', v_refresh
  );
end;
$$;


ALTER FUNCTION "ingest"."fn_set_partner_catalog_rows_review"("p_run_id" bigint, "p_row_ids" bigint[], "p_review_status" "text", "p_selected_for_draft" boolean, "p_match_status" "text") OWNER TO "postgres";


