CREATE OR REPLACE FUNCTION "public"."_anarbib_safe_date"("p_text" "text") RETURNS "date"
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO 'public', 'pg_temp'
    AS $_$
declare
  v_text text := nullif(btrim(p_text), '');
begin
  if v_text is null then
    return null;
  end if;
  if v_text ~ '^\d{4}-\d{2}-\d{2}$' then
    return v_text::date;
  end if;
  return null;
exception
  when others then
    return null;
end;
$_$;


