    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'auth', 'pg_temp'
    AS $$
declare
  v_row record;
  v_count integer := 0;
begin
  for v_row in
    select id
    from public.painel_internal_tasks
    where exists (
      select 1
      from unnest(coalesce(tags, '{}'::text[])) tag
      where lower(tag) like 'convite:%'
    )
  loop
    perform public.sync_task_invites_from_task(v_row.id);
    v_count := v_count + 1;
  end loop;

  return jsonb_build_object('ok', true, 'tasks_processed', v_count);
end;
$$;


