    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public', 'auth', 'pg_temp'
    AS $$
  select coalesce(
    public.can_manage_document_requests_for_library(p_requester_library_id)
    or public.can_manage_document_requests_for_library(p_target_library_id),
    false
  );
