    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public', 'auth', 'pg_temp'
    AS $$
  select (
    p_requester_library_id is not null
    and p_target_library_id is not null
    and p_requester_library_id <> p_target_library_id
    and public.can_manage_document_requests_for_library(p_requester_library_id)
    and exists (
      select 1
      from public.libraries l
      where l.id = p_target_library_id
        and l.is_active = true
    )
  );
$$;


