CREATE OR REPLACE FUNCTION "public"."can_manage_library_circulation_policies"("p_library_id" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public', 'auth', 'pg_temp'
    AS $$
  SELECT EXISTS (
