    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v text;
begin
  v := nullif(btrim(coalesce(p_obj ->> p_key, '')), '');
  if v is null then
    return null;
  end if;
  begin
    return v::date;
  exception when others then
    return null;
  end;
end;
$$;


