    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
  select case coalesce(trim(lower(p_status)), '')
    when 'identificada' then 10
    when 'contatada' then 20
    when 'em_discussao' then 30
    when 'acordo_parcial' then 40
    when 'acordo_tecnico' then 50
    when 'importacao_autorizada' then 60
    when 'mutualizacao_autorizada' then 70
    else 0
  end;
$$;


