CREATE OR REPLACE VIEW "public"."catalog_partners_policy_flags_v2" WITH ("security_invoker"='true') AS
 SELECT "id",
    "slug",
    "display_name",
    "base_url",
    "software_family",
    "software_confidence",
    "country_code",
    "notes",
    "relationship_status",
    "public"."catalog_partner_relationship_rank"("relationship_status") AS "relationship_rank",
    "public"."catalog_partner_can_compare"("relationship_status") AS "compare_allowed",
    "public"."catalog_partner_can_import"("relationship_status") AS "import_allowed",
    "public"."catalog_partner_can_mutualize"("relationship_status") AS "mutualize_allowed",
    "relationship_notes",
    "first_contact_at",
    "last_contact_at",
    "technical_probe_last_at",
        CASE
            WHEN "public"."catalog_partner_can_mutualize"("relationship_status") THEN 'Mutualização autorizada.'::"text"
            WHEN "public"."catalog_partner_can_import"("relationship_status") THEN 'Importação autorizada, sem mutualização automática.'::"text"
            WHEN "public"."catalog_partner_can_compare"("relationship_status") THEN 'Comparação técnica autorizada, sem importação.'::"text"
            ELSE 'Só relação, documentação e teste técnico. Sem comparação ativa nem importação.'::"text"
        END AS "policy_summary"
   FROM "public"."catalog_partners" "p";


ALTER VIEW "public"."catalog_partners_policy_flags_v2" OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."catalog_partner_require_compare_authorized"("p_slug" "text") RETURNS "public"."catalog_partners_policy_flags_v2"
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO ''
    AS $$
declare
  v_row public.catalog_partners_policy_flags_v2%rowtype;
begin
  select * into v_row
  from public.catalog_partners_policy_flags_v2
  where slug = trim(p_slug)
  limit 1;

  if not found then
    raise exception 'Parceira não encontrada para slug=%', p_slug;
  end if;

  if not v_row.compare_allowed then
    raise exception 'Comparação ainda não autorizada para a parceira % (situação relacional atual: %).', v_row.slug, v_row.relationship_status;
  end if;

  return v_row;
end;
$$;


