CREATE OR REPLACE FUNCTION "public"."circulation_reader_scope"("p_user_id" "uuid", "p_library_id" "uuid") RETURNS "text"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'auth', 'pg_temp'
    AS $$
declare
  v_profile public.profiles%rowtype;
begin
  if p_user_id is null then
    return 'non_member';
  end if;

  select *
    into v_profile
  from public.profiles p
  where p.id = p_user_id
  limit 1;

  if coalesce(v_profile.is_restricted, false) is true then
    return 'restricted';
  end if;

  -- F.2 v0.3 : Staff local (bibliothécaire, coordinateur·rice) partagent
  -- le même scope de circulation : ils peuvent emprunter sans les
  -- restrictions appliquées aux membres simples.
  if exists (
    select 1
    from public.user_library_memberships ulm
    where ulm.user_id = p_user_id
      and ulm.library_id = p_library_id
      and ulm.status = 'active'
      and lower(coalesce(ulm.role, '')) in (
        'librarian',
        'coordenador'
      )
  ) then
    return 'librarian';
  end if;

  if exists (
    select 1
    from public.user_library_memberships ulm
    where ulm.user_id = p_user_id
      and ulm.library_id = p_library_id
      and ulm.status = 'active'
  ) then
    return 'local_member';
  end if;

  if exists (
    select 1
    from public.user_library_memberships ulm
    join public.libraries l
      on l.id = ulm.library_id
    where ulm.user_id = p_user_id
      and ulm.status = 'active'
      and l.is_active = true
  ) then
    return 'network_member';
  end if;

  return 'non_member';
end;
$$;


ALTER FUNCTION "public"."circulation_reader_scope"("p_user_id" "uuid", "p_library_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."circulation_reader_scope"("p_user_id" "uuid", "p_library_id" "uuid") IS 'Résout la portée de lectorat pour le moteur de circulação : local_member, network_member, non_member, librarian ou restricted.';



CREATE OR REPLACE FUNCTION "public"."confirm_author_book_link"("p_author_id" bigint, "p_contributor_id" bigint) RETURNS bigint
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_book_id bigint;
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM public.user_library_memberships m
    WHERE m.user_id = auth.uid()
      AND m.role = ANY (ARRAY['librarian'::text, 'coordenador'::text])
  ) THEN
    RAISE EXCEPTION 'Acesso restrito ao staff de catalogacao.';
  END IF;

  UPDATE public.book_contributors
  SET author_id = p_author_id
  WHERE id = p_contributor_id AND author_id IS NULL
  RETURNING book_id INTO v_book_id;

  IF v_book_id IS NULL THEN
    RAISE EXCEPTION 'Contribuinte % inexistente ou ja vinculado.', p_contributor_id;
  END IF;

  RETURN v_book_id;
END;
$$;


ALTER FUNCTION "public"."confirm_author_book_link"("p_author_id" bigint, "p_contributor_id" bigint) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."confirm_author_book_link"("p_author_id" bigint, "p_contributor_id" bigint) IS 'Rattache un contribuinte a une autorite (validation humaine). Paquet liaison autorites du 05/06/2026.';



CREATE OR REPLACE FUNCTION "public"."copy_book_catalog_context_to_draft"("p_book_id" bigint, "p_book_draft_id" bigint) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
begin
  insert into public.book_draft_catalog_context (
    book_draft_id,
    acquisition_mode_code,
    acquisition_date,
    acquisition_source_label,
    acquisition_batch_label,
    owner_library_id,
    owner_library_label,
    holder_library_id,
    holder_library_label,
    mutualization_status_code,
    source_partner_code,
    source_system_code,
    source_record_id,
    source_record_url,
    source_format_code,
    import_method_code,
    imported_at,
    last_synced_at,
    provenance_note,
    review_status_code,
    confidence_level_code
  )
  select
    p_book_draft_id,
    c.acquisition_mode_code,
    c.acquisition_date,
    c.acquisition_source_label,
    c.acquisition_batch_label,
    c.owner_library_id,
    c.owner_library_label,
    c.holder_library_id,
    c.holder_library_label,
    c.mutualization_status_code,
    c.source_partner_code,
    c.source_system_code,
    c.source_record_id,
    c.source_record_url,
    c.source_format_code,
    c.import_method_code,
    c.imported_at,
    c.last_synced_at,
    c.provenance_note,
    c.review_status_code,
    c.confidence_level_code
  from public.book_catalog_context c
  where c.book_id = p_book_id
  on conflict (book_draft_id) do update
  set acquisition_mode_code     = excluded.acquisition_mode_code,
      acquisition_date          = excluded.acquisition_date,
      acquisition_source_label  = excluded.acquisition_source_label,
      acquisition_batch_label   = excluded.acquisition_batch_label,
      owner_library_id          = excluded.owner_library_id,
      owner_library_label       = excluded.owner_library_label,
      holder_library_id         = excluded.holder_library_id,
      holder_library_label      = excluded.holder_library_label,
      mutualization_status_code = excluded.mutualization_status_code,
      source_partner_code       = excluded.source_partner_code,
      source_system_code        = excluded.source_system_code,
      source_record_id          = excluded.source_record_id,
      source_record_url         = excluded.source_record_url,
      source_format_code        = excluded.source_format_code,
      import_method_code        = excluded.import_method_code,
      imported_at               = excluded.imported_at,
      last_synced_at            = excluded.last_synced_at,
      provenance_note           = excluded.provenance_note,
      review_status_code        = excluded.review_status_code,
      confidence_level_code     = excluded.confidence_level_code,
      updated_at                = now();
end;
$$;


ALTER FUNCTION "public"."copy_book_catalog_context_to_draft"("p_book_id" bigint, "p_book_draft_id" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."copy_book_digital_resources_to_draft"("p_book_id" bigint, "p_book_draft_id" bigint) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
begin
  delete from public.book_draft_digital_resources
  where book_draft_id = p_book_draft_id;

  insert into public.book_draft_digital_resources (
    book_draft_id,
    resource_type,
    usage_type,
    access_scope,
    status,
    is_active,
    storage_bucket,
    storage_path,
    mime_type,
    language_code,
    source_name,
    source_url,
    attribution_text,
    rights_status,
    is_primary,
    bibliographic_match_validated,
    label,
    notes,
    metadata,
    activated_at,
    retired_at
  )
  select
    p_book_draft_id,
    r.resource_type,
    r.usage_type,
    r.access_scope,
    case when r.status = 'active' then 'draft' else r.status end,
    r.is_active,
    r.storage_bucket,
    r.storage_path,
    r.mime_type,
    r.language_code,
    r.source_name,
    r.source_url,
    r.attribution_text,
    r.rights_status,
    r.is_primary,
    r.bibliographic_match_validated,
    r.label,
    r.notes,
    r.metadata,
    r.activated_at,
    r.retired_at
  from public.book_digital_resources r
  where r.book_id = p_book_id;
end;
$$;


ALTER FUNCTION "public"."copy_book_digital_resources_to_draft"("p_book_id" bigint, "p_book_draft_id" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_author_draft_from_author"("p_author_id" bigint, "p_batch_id" bigint DEFAULT NULL::bigint) RETURNS bigint
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_id bigint;
begin
  insert into public.author_drafts (
    published_author_id, batch_id, action, status,
    preferred_name, sort_name, biography, birth_year, death_year, country,
    source_kind, source_label, source_url, viaf_id, isni, wikidata_id,
    variant_forms, photo_object_path, notes, structured_meta,
    created_by, updated_by
  )
  select
    a.id, p_batch_id, 'update', 'draft',
    a.preferred_name, a.sort_name, a.biography, a.birth_year, a.death_year, a.country,
    a.source_kind, a.source_label, a.source_url, a.viaf_id, a.isni, a.wikidata_id,
    a.variant_forms, a.photo_object_path, a.notes,
    coalesce(a.structured_meta, '{}'::jsonb),
    auth.uid(), auth.uid()
  from public.authors a
  where a.id = p_author_id
  returning id into v_id;

  if v_id is null then
    raise exception 'Autor nao encontrado: %', p_author_id;
  end if;

  return v_id;
end;
$$;


