CREATE TABLE IF NOT EXISTS "public"."document_permission_requests" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "requester_library_id" "uuid" NOT NULL,
    "target_library_id" "uuid" NOT NULL,
    "requested_action" "text" NOT NULL,
    "object_type" "text" DEFAULT 'outro'::"text" NOT NULL,
    "object_ref" "text",
    "message" "text" NOT NULL,
    "status" "text" DEFAULT 'pending'::"text" NOT NULL,
    "response_note" "text",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "created_by" "uuid" DEFAULT "auth"."uid"(),
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_by" "uuid" DEFAULT "auth"."uid"(),
    "decided_at" timestamp with time zone,
    "decided_by" "uuid",
    CONSTRAINT "document_permission_requests_action_chk" CHECK (("length"(TRIM(BOTH FROM "requested_action")) > 0)),
    CONSTRAINT "document_permission_requests_diff_libraries_chk" CHECK (("requester_library_id" <> "target_library_id")),
    CONSTRAINT "document_permission_requests_message_chk" CHECK (("length"(TRIM(BOTH FROM "message")) > 0)),
    CONSTRAINT "document_permission_requests_status_chk" CHECK (("status" = ANY (ARRAY['pending'::"text", 'accepted'::"text", 'refused'::"text", 'cancelled'::"text", 'expired'::"text"])))
);


ALTER TABLE "public"."document_permission_requests" OWNER TO "postgres";


COMMENT ON TABLE "public"."document_permission_requests" IS 'Demandes de permission sur documents privés. Anon SELECT révoqué le 2026-04-26 (palier 4).';



COMMENT ON COLUMN "public"."document_permission_requests"."requested_action" IS 'Ação pedida pela biblioteca solicitante: edição de notice, proposta de correção, criação de cópia local, vínculo de recurso digital, mutualização ou outra.';



COMMENT ON COLUMN "public"."document_permission_requests"."object_ref" IS 'Referência livre do objeto em jogo: bib_ref, id, URL de rascunho, identificador de lote, nota curta ou outro marcador útil.';



CREATE OR REPLACE FUNCTION "public"."create_document_permission_request"("p_requester_library_id" "uuid", "p_target_library_id" "uuid", "p_request" "jsonb") RETURNS "public"."document_permission_requests"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_row public.document_permission_requests;
begin
  if p_requester_library_id is null then
    raise exception 'Biblioteca solicitante ausente.';
  end if;
  if p_target_library_id is null then
    raise exception 'Biblioteca destinatária ausente.';
  end if;
  if p_requester_library_id = p_target_library_id then
    raise exception 'A solicitação precisa apontar para outra biblioteca.';
  end if;
  if not public.user_can_manage_library(p_requester_library_id) then
    raise exception 'Sem permissão para enviar solicitação em nome desta biblioteca.';
  end if;

  insert into public.document_permission_requests (
    requester_library_id,
    target_library_id,
    requested_action,
    object_type,
    object_ref,
    message,
    status,
    created_by,
    updated_by
  )
  values (
    p_requester_library_id,
    p_target_library_id,
    coalesce(nullif(trim(p_request->>'requested_action'), ''), 'outra'),
    coalesce(nullif(trim(p_request->>'object_type'), ''), 'outro'),
    nullif(trim(p_request->>'object_ref'), ''),
    coalesce(nullif(trim(p_request->>'message'), ''), ''),
    'pending',
    auth.uid(),
    auth.uid()
  )
  returning * into v_row;

  if coalesce(v_row.message, '') = '' then
    raise exception 'Escreve uma mensagem curta explicando o pedido.';
  end if;

  return v_row;
end;
$$;


ALTER FUNCTION "public"."create_document_permission_request"("p_requester_library_id" "uuid", "p_target_library_id" "uuid", "p_request" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_exemplar_draft_from_exemplar"("p_exemplar_id" bigint, "p_batch_id" bigint DEFAULT NULL::bigint) RETURNS bigint
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_id bigint;
begin
  insert into public.exemplar_drafts (
    published_exemplar_id,
    batch_id,
    action,
    status,
    label_status,
    target_bib_ref,
    target_library_id,
    target_holding_id,
    tombo,
    shelf_location,
    label_title_override,
    label_author_override,
    label_cdd_override,
    label_note,
    notes,
    acquisition_mode,
    acquisition_date,
    provenance_note,
    source_library,
    created_by,
    updated_by
  )
  select
    e.id,
    p_batch_id,
    'update',
    'draft',
    'pending',
    coalesce(
      nullif(trim(h.local_bib_ref), ''),
      rb.local_bib_ref,
      b_holding.bib_ref,
      b_legacy.bib_ref,
      e.bib_ref
    ) as target_bib_ref,
    e.library_id as target_library_id,
    coalesce(e.holding_id, rb.holding_id) as target_holding_id,
    e.tombo,
    e.shelf_location,
    e.label_title_override,
    e.label_author_override,
    e.label_cdd_override,
    e.label_note,
    e.notes,
    e.acquisition_mode,
    e.acquisition_date,
    e.provenance_note,
    e.source_library,
    auth.uid(),
    auth.uid()
  from public.exemplares e
  left join public.book_holdings h
    on h.id = e.holding_id
  left join public.books b_holding
    on b_holding.id = h.book_id
  left join lateral public.resolve_library_holding_bridge(e.library_id, e.bib_ref) rb
    on e.holding_id is null
  left join public.books b_legacy
    on e.holding_id is null
   and rb.holding_id is null
   and b_legacy.bib_ref = e.bib_ref
  where e.id = p_exemplar_id
  returning id into v_id;

  if v_id is null then
    raise exception 'Exemplar não encontrado: %', p_exemplar_id;
  end if;

  perform public.sync_exemplar_draft_holdings_bridge(v_id);

  return v_id;
end;
$$;


ALTER FUNCTION "public"."create_exemplar_draft_from_exemplar"("p_exemplar_id" bigint, "p_batch_id" bigint) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."create_exemplar_draft_from_exemplar"("p_exemplar_id" bigint, "p_batch_id" bigint) IS 'Passe 42 backend phase 2: le brouillon d exemplar embarque désormais aussi la bibliothèque locale et le holding canonique quand ils sont résolubles.';



CREATE OR REPLACE FUNCTION "public"."decide_document_permission_request"("p_request_id" "uuid", "p_decision" "text", "p_response_note" "text" DEFAULT NULL::"text") RETURNS "public"."document_permission_requests"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_row public.document_permission_requests;
  v_decision text := lower(trim(coalesce(p_decision, '')));
begin
  if v_decision not in ('accepted','refused') then
    raise exception 'Decisão inválida. Usa accepted ou refused.';
  end if;

  select *
    into v_row
  from public.document_permission_requests
  where id = p_request_id
  limit 1;

  if v_row.id is null then
    raise exception 'Solicitação interbibliotecas não encontrada.';
  end if;

  if not public.user_can_manage_library(v_row.target_library_id) then
    raise exception 'Sem permissão para responder por esta biblioteca.';
  end if;

  update public.document_permission_requests
     set status = v_decision,
         response_note = nullif(trim(coalesce(p_response_note, '')), ''),
         decided_at = timezone('utc', now()),
         decided_by = auth.uid(),
         updated_at = timezone('utc', now()),
         updated_by = auth.uid()
   where id = p_request_id
     and status = 'pending'
  returning *
    into v_row;

  if v_row.id is null then
    raise exception 'Esta solicitação já não está pendente.';
  end if;

  return v_row;
end;
$$;


ALTER FUNCTION "public"."decide_document_permission_request"("p_request_id" "uuid", "p_decision" "text", "p_response_note" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."delete_library_circulation_policy_rule"("p_rule_id" bigint) RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'auth', 'pg_temp'
    AS $$
declare
  v_rule public.library_circulation_policy_rules%rowtype;
  v_set public.library_circulation_policy_sets%rowtype;
begin
  if auth.uid() is null then
    raise exception 'authentication required';
  end if;

  select *
    into v_rule
  from public.library_circulation_policy_rules r
  where r.id = p_rule_id;

  if v_rule.id is null then
    return false;
  end if;

  select *
    into v_set
  from public.library_circulation_policy_sets s
  where s.id = v_rule.policy_set_id;

  if v_set.id is null then
    return false;
  end if;

  if not public.can_manage_library_circulation_policies(v_set.library_id) then
    raise exception 'permission denied for library_circulation_policy_rules';
  end if;

  delete from public.library_circulation_policy_rules
  where id = p_rule_id;

  return true;
end;
$$;


ALTER FUNCTION "public"."delete_library_circulation_policy_rule"("p_rule_id" bigint) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."delete_library_circulation_policy_rule"("p_rule_id" bigint) IS 'Supprime une règle atomique de circulation après contrôle d appartenance à la bibliothèque gérée.';



CREATE OR REPLACE FUNCTION "public"."discard_author"("p_author_id" bigint) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_uid   uuid := auth.uid();
  v_label text;
  v_snap  jsonb;
begin
  if v_uid is null then
    raise exception 'Não autenticado.'
      using errcode = '28000', hint = 'catalog_discard_unauthenticated';
  end if;
  if not exists (
    select 1 from public.user_library_memberships m
    where m.user_id = v_uid and m.role in ('librarian','coordenador') and m.status = 'active'
  ) then
    raise exception 'Apenas bibliotecárias e coordenadoras podem descartar fichas do catálogo.'
      using errcode = '42501', hint = 'catalog_discard_forbidden';
  end if;

  select preferred_name, to_jsonb(a) into v_label, v_snap from public.authors a where id = p_author_id;
  if not found then
    raise exception 'Autoridade não encontrada (ID %).', p_author_id
      using errcode = 'P0002', hint = 'catalog_discard_not_found';
  end if;

  if exists (select 1 from public.book_authors where author_id = p_author_id) then
    raise exception 'Esta autoridade está vinculada a um ou mais documentos. Desvincule-a primeiro.'
      using errcode = 'P0001', hint = 'catalog_discard_author_linked';
  end if;

  insert into public.catalog_audit_log (actor_id, action, entity_type, entity_id, label, details)
  values (v_uid, 'discard', 'author', p_author_id, v_label,
          jsonb_build_object('via', 'CatalogPanel', 'snapshot', v_snap));

  delete from public.authors where id = p_author_id;
end;
$$;


ALTER FUNCTION "public"."discard_author"("p_author_id" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."discard_book"("p_book_id" bigint) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_uid   uuid := auth.uid();
  v_label text;
  v_snap  jsonb;
begin
  if v_uid is null then
    raise exception 'Não autenticado.'
      using errcode = '28000', hint = 'catalog_discard_unauthenticated';
  end if;
  if not exists (
    select 1 from public.user_library_memberships m
    where m.user_id = v_uid and m.role in ('librarian','coordenador') and m.status = 'active'
  ) then
    raise exception 'Apenas bibliotecárias e coordenadoras podem descartar fichas do catálogo.'
      using errcode = '42501', hint = 'catalog_discard_forbidden';
  end if;

  select titulo, to_jsonb(b) into v_label, v_snap from public.books b where id = p_book_id;
  if not found then
    raise exception 'Documento não encontrado (ID %).', p_book_id
      using errcode = 'P0002', hint = 'catalog_discard_not_found';
  end if;

  if exists (select 1 from public.book_holdings where book_id = p_book_id) then
    raise exception 'Este documento possui acervo (exemplares em uma ou mais bibliotecas). Descarte os exemplares primeiro.'
      using errcode = 'P0001', hint = 'catalog_discard_has_holdings';
  end if;
  if exists (select 1 from public.emprestimo_itens_v2 where book_id = p_book_id) then
    raise exception 'Este documento tem histórico de empréstimo e não pode ser apagado.'
      using errcode = 'P0001', hint = 'catalog_discard_has_loans';
  end if;

  delete from public.user_wishlist where book_id = p_book_id;

  insert into public.catalog_audit_log (actor_id, action, entity_type, entity_id, label, details)
  values (v_uid, 'discard', 'book', p_book_id, v_label,
          jsonb_build_object('via', 'CatalogPanel', 'snapshot', v_snap));

  delete from public.books where id = p_book_id;
end;
$$;


ALTER FUNCTION "public"."discard_book"("p_book_id" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."discard_exemplar"("p_exemplar_id" bigint) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_uid   uuid := auth.uid();
  v_lib   uuid;
  v_label text;
  v_snap  jsonb;
begin
  if v_uid is null then
    raise exception 'Não autenticado.'
      using errcode = '28000', hint = 'catalog_discard_unauthenticated';
  end if;

  select library_id, coalesce(tombo, bib_ref), to_jsonb(e)
    into v_lib, v_label, v_snap
  from public.exemplares e where id = p_exemplar_id;
  if not found then
    raise exception 'Exemplar não encontrado (ID %).', p_exemplar_id
      using errcode = 'P0002', hint = 'catalog_discard_not_found';
  end if;

  if v_lib is not null then
    if not public.user_can_manage_library(v_lib) then
      raise exception 'Você não tem permissão para descartar exemplares desta biblioteca.'
        using errcode = '42501', hint = 'catalog_discard_forbidden';
    end if;
  else
    if not exists (
      select 1 from public.user_library_memberships m
      where m.user_id = v_uid and m.role in ('librarian','coordenador') and m.status = 'active'
    ) then
      raise exception 'Apenas bibliotecárias e coordenadoras podem descartar exemplares.'
        using errcode = '42501', hint = 'catalog_discard_forbidden';
    end if;
  end if;

  if exists (select 1 from public.consulta_linhas_v2        where item_id = p_exemplar_id)
     or exists (select 1 from public.emprestimo_itens_v2       where item_id = p_exemplar_id)
     or exists (select 1 from public.interlibrary_loan_items_v2 where item_id = p_exemplar_id) then
    raise exception 'Este exemplar tem histórico de circulação (consulta, empréstimo ou PEB) e não pode ser apagado.'
      using errcode = 'P0001', hint = 'catalog_discard_exemplar_in_circulation';
  end if;

  insert into public.catalog_audit_log (actor_id, action, entity_type, entity_id, library_id, label, details)
  values (v_uid, 'discard', 'exemplar', p_exemplar_id, v_lib, v_label,
          jsonb_build_object('via', 'CatalogPanel', 'snapshot', v_snap));

  delete from public.exemplares where id = p_exemplar_id;
end;
$$;


ALTER FUNCTION "public"."discard_exemplar"("p_exemplar_id" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."dispatch_task_invitation_outbox"("p_limit" integer DEFAULT 50) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'vault', 'extensions', 'pg_temp'
    AS $$
declare
  v_url text;
  v_secret text;
  v_row record;
  v_ctx jsonb;
  v_task_alerts_enabled boolean;
  v_request_id bigint;
  v_processed integer := 0;
  v_sent integer := 0;
  v_failed integer := 0;
  v_skipped integer := 0;
begin
  select ds.decrypted_secret
    into v_url
  from vault.decrypted_secrets ds
  where ds.name = 'ANARBIB_TASK_INVITE_FUNCTION_URL'
  order by ds.created_at desc
  limit 1;

  select ds.decrypted_secret
    into v_secret
  from vault.decrypted_secrets ds
  where ds.name = 'ANARBIB_TASK_INVITE_SECRET'
  order by ds.created_at desc
  limit 1;

  if coalesce(v_url, '') = '' then
    raise exception 'Secret ANARBIB_TASK_INVITE_FUNCTION_URL ausente no vault';
  end if;

  if coalesce(v_secret, '') = '' then
    raise exception 'Secret ANARBIB_TASK_INVITE_SECRET ausente no vault';
  end if;

  for v_row in
    select
      o.id as outbox_id,
      o.invite_id,
      o.task_id,
      o.library_id,
      o.recipient_email,
      i.invite_status,
      t.title,
      t.description,
      t.priority,
      t.status as task_status,
      t.owner,
      t.due_date,
      t.tags,
      t.created_at
    from public.painel_internal_task_invitation_outbox o
    join public.painel_internal_task_invites i
      on i.id = o.invite_id
    join public.painel_internal_tasks t
      on t.id = o.task_id
    where o.dispatch_status = 'queued'
    order by o.id
    limit greatest(coalesce(p_limit, 50), 1)
    for update of o skip locked
  loop
    v_processed := v_processed + 1;

    begin
      if v_row.invite_status = 'cancelled' then
        update public.painel_internal_task_invitation_outbox
           set dispatch_status = 'skipped',
               last_error = 'Invite cancelled before dispatch',
               updated_at = now()
         where id = v_row.outbox_id;
        v_skipped := v_skipped + 1;
        continue;
      end if;

      select coalesce(p.task_alerts_enabled, true)
        into v_task_alerts_enabled
      from public.library_notification_policies p
      where p.library_id = v_row.library_id;

      if coalesce(v_task_alerts_enabled, true) = false then
        update public.painel_internal_task_invitation_outbox
           set dispatch_status = 'skipped',
               last_error = 'Task alerts disabled for this library',
               updated_at = now()
         where id = v_row.outbox_id;
        v_skipped := v_skipped + 1;
        continue;
      end if;

      select to_jsonb(v)
        into v_ctx
      from public.v_library_notification_context v
      where v.library_id = v_row.library_id;

      v_request_id := net.http_post(
        url := v_url,
        headers := jsonb_build_object(
          'Content-Type', 'application/json',
          'x-task-invite-secret', v_secret
        ),
        body := jsonb_build_object(
          'kind', 'task_invitation',
          'invite_id', v_row.invite_id,
          'task_id', v_row.task_id,
          'library_id', v_row.library_id,
          'recipient_email', v_row.recipient_email,
          'task', jsonb_build_object(
            'title', v_row.title,
            'description', v_row.description,
            'priority', v_row.priority,
            'status', v_row.task_status,
            'owner', v_row.owner,
            'due_date', v_row.due_date,
            'tags', v_row.tags,
            'created_at', v_row.created_at
          ),
          'notification_context', coalesce(v_ctx, '{}'::jsonb)
        ),
        timeout_milliseconds := 60000
      );

      update public.painel_internal_task_invitation_outbox
         set dispatch_status = 'sent',
             request_id = v_request_id,
             attempts = attempts + 1,
             sent_at = now(),
             updated_at = now()
       where id = v_row.outbox_id;

      update public.painel_internal_task_invites
         set invite_status = 'sent',
             first_sent_at = coalesce(first_sent_at, now()),
             last_sent_at = now(),
             last_error = null,
             updated_at = now()
       where id = v_row.invite_id;

      v_sent := v_sent + 1;

    exception
      when others then
        update public.painel_internal_task_invitation_outbox
           set dispatch_status = 'failed',
               attempts = attempts + 1,
               last_error = sqlerrm,
               updated_at = now()
         where id = v_row.outbox_id;

        update public.painel_internal_task_invites
           set invite_status = case when invite_status = 'sent' then invite_status else 'failed' end,
               last_error = sqlerrm,
               updated_at = now()
         where id = v_row.invite_id;

        v_failed := v_failed + 1;
    end;
  end loop;

  return jsonb_build_object(
    'ok', true,
    'processed', v_processed,
    'sent', v_sent,
    'failed', v_failed,
    'skipped', v_skipped
  );
end;
$$;


ALTER FUNCTION "public"."dispatch_task_invitation_outbox"("p_limit" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."dispatch_task_invitation_outbox"("p_limit" integer) IS 'Despacha a fila de convites de tarefas via pg_net para uma Edge Function mail.';



CREATE OR REPLACE FUNCTION "public"."dispatch_task_notification_outbox"("p_limit" integer DEFAULT 50) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'vault', 'extensions', 'pg_temp'
    AS $$
declare
  v_url text;
  v_secret text;
  v_row record;
  v_ctx jsonb;
  v_task_alerts_enabled boolean;
  v_request_id bigint;
  v_processed integer := 0;
  v_sent integer := 0;
  v_failed integer := 0;
  v_skipped integer := 0;
begin
  select ds.decrypted_secret
    into v_url
  from vault.decrypted_secrets ds
  where ds.name = 'ANARBIB_TASK_INVITE_FUNCTION_URL'
  order by ds.created_at desc
  limit 1;

  select ds.decrypted_secret
    into v_secret
  from vault.decrypted_secrets ds
  where ds.name = 'ANARBIB_TASK_INVITE_SECRET'
  order by ds.created_at desc
  limit 1;

  if coalesce(v_url, '') = '' then
    raise exception 'Secret ANARBIB_TASK_INVITE_FUNCTION_URL ausente no vault';
  end if;

  if coalesce(v_secret, '') = '' then
    raise exception 'Secret ANARBIB_TASK_INVITE_SECRET ausente no vault';
  end if;

  for v_row in
    select
      o.id as outbox_id,
      o.task_id,
      o.library_id,
      o.recipient_role,
      o.recipient_email,
      o.event_kind,
      o.event_at,
      o.changed_fields,
      t.title,
      t.description,
      t.priority,
      t.status as task_status,
      t.owner,
      t.owner_user_id,
      t.due_date,
      t.tags,
      t.created_at,
      t.updated_at
    from public.painel_internal_task_notification_outbox o
    join public.painel_internal_tasks t
      on t.id = o.task_id
    where o.dispatch_status = 'queued'
    order by o.id
    limit greatest(coalesce(p_limit, 50), 1)
    for update of o skip locked
  loop
    v_processed := v_processed + 1;

    begin
      if coalesce(btrim(v_row.recipient_email), '') = '' then
        update public.painel_internal_task_notification_outbox
           set dispatch_status = 'skipped',
               last_error = 'Recipient email missing',
               updated_at = now()
         where id = v_row.outbox_id;
        v_skipped := v_skipped + 1;
        continue;
      end if;

      select coalesce(p.task_alerts_enabled, true)
        into v_task_alerts_enabled
      from public.library_notification_policies p
      where p.library_id = v_row.library_id;

      if coalesce(v_task_alerts_enabled, true) = false then
        update public.painel_internal_task_notification_outbox
           set dispatch_status = 'skipped',
               last_error = 'Task alerts disabled for this library',
               updated_at = now()
         where id = v_row.outbox_id;
        v_skipped := v_skipped + 1;
        continue;
      end if;

      select to_jsonb(v)
        into v_ctx
      from public.v_library_notification_context v
      where v.library_id = v_row.library_id;

      v_request_id := net.http_post(
        url := v_url,
        headers := jsonb_build_object(
          'Content-Type', 'application/json',
          'x-task-invite-secret', v_secret
        ),
        body := jsonb_build_object(
          'kind', case when v_row.recipient_role = 'library' then 'task_library_notice' else 'task_owner_notice' end,
          'task_notify_id', v_row.outbox_id,
          'task_id', v_row.task_id,
          'library_id', v_row.library_id,
          'recipient_role', v_row.recipient_role,
          'recipient_email', v_row.recipient_email,
          'event_kind', v_row.event_kind,
          'event_at', v_row.event_at,
          'changed_fields', to_jsonb(coalesce(v_row.changed_fields, '{}'::text[])),
          'task', jsonb_build_object(
            'title', v_row.title,
            'description', v_row.description,
            'priority', v_row.priority,
            'status', v_row.task_status,
            'owner', v_row.owner,
            'owner_user_id', v_row.owner_user_id,
            'due_date', v_row.due_date,
            'tags', v_row.tags,
            'created_at', v_row.created_at,
            'updated_at', v_row.updated_at
          ),
          'notification_context', coalesce(v_ctx, '{}'::jsonb)
        ),
        timeout_milliseconds := 60000
      );

      update public.painel_internal_task_notification_outbox
         set dispatch_status = 'sent',
             request_id = v_request_id,
             attempts = attempts + 1,
             sent_at = now(),
             last_error = null,
             updated_at = now()
       where id = v_row.outbox_id;

      v_sent := v_sent + 1;
    exception
      when others then
        update public.painel_internal_task_notification_outbox
           set dispatch_status = 'failed',
               attempts = attempts + 1,
               last_error = sqlerrm,
               updated_at = now()
         where id = v_row.outbox_id;
        v_failed := v_failed + 1;
    end;
  end loop;

  return jsonb_build_object(
    'ok', true,
    'processed', v_processed,
    'sent', v_sent,
    'failed', v_failed,
    'skipped', v_skipped
  );
end;
$$;


