CREATE OR REPLACE FUNCTION "public"."enqueue_task_level_notifications_from_task"("p_task_id" "uuid", "p_event_kind" "text", "p_changed_fields" "text"[] DEFAULT NULL::"text"[]) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'auth', 'pg_temp'
    AS $$
declare
  v_task public.painel_internal_tasks%rowtype;
  v_event_at timestamptz;
  v_organizer_email text;
  v_library_email text;
  v_changed_fields text[] := '{}';
  v_queued integer := 0;
begin
  select *
    into v_task
  from public.painel_internal_tasks
  where id = p_task_id;

  if not found then
    raise exception 'Tarefa não encontrada: %', p_task_id;
  end if;

  if p_event_kind not in ('task_created', 'task_updated') then
    raise exception 'Evento task-level inválido: %', p_event_kind;
  end if;

  v_event_at := coalesce(v_task.updated_at, v_task.created_at, now());
  v_changed_fields := coalesce(
    array(
      select distinct lower(btrim(x))
      from unnest(coalesce(p_changed_fields, '{}'::text[])) as x
      where coalesce(btrim(x), '') <> ''
      order by 1
    ),
    '{}'::text[]
  );

  if p_event_kind = 'task_updated' and coalesce(array_length(v_changed_fields, 1), 0) = 0 then
    return jsonb_build_object(
      'ok', true,
      'task_id', v_task.id,
      'event_kind', p_event_kind,
      'queued', 0,
      'reason', 'no_significant_changes'
    );
  end if;

  select lower(btrim(p.email))
    into v_organizer_email
  from public.profiles p
  where p.id = v_task.owner_user_id
    and coalesce(btrim(p.email), '') <> ''
  limit 1;

  select lower(btrim(v.admin_notification_email))
    into v_library_email
  from public.v_library_notification_context v
  where v.library_id = v_task.library_id
    and coalesce(btrim(v.admin_notification_email), '') <> ''
  limit 1;

  if coalesce(v_organizer_email, '') <> '' then
    insert into public.painel_internal_task_notification_outbox (
      task_id,
      library_id,
      recipient_role,
      recipient_email,
      event_kind,
      event_at,
      changed_fields,
      request_body,
      dispatch_status
    )
    values (
      v_task.id,
      v_task.library_id,
      'organizer',
      v_organizer_email,
      p_event_kind,
      v_event_at,
      v_changed_fields,
      jsonb_build_object(
        'kind', 'task_owner_notice',
        'task_id', v_task.id,
        'library_id', v_task.library_id,
        'recipient_role', 'organizer',
        'recipient_email', v_organizer_email,
        'event_kind', p_event_kind,
        'changed_fields', to_jsonb(v_changed_fields)
      ),
      'queued'
    )
    on conflict on constraint painel_internal_task_notification_outbox_event_key do nothing;

    if found then
      v_queued := v_queued + 1;
    end if;
  end if;

  if coalesce(v_library_email, '') <> ''
     and lower(v_library_email) <> lower(coalesce(v_organizer_email, '')) then
    insert into public.painel_internal_task_notification_outbox (
      task_id,
      library_id,
      recipient_role,
      recipient_email,
      event_kind,
      event_at,
      changed_fields,
      request_body,
      dispatch_status
    )
    values (
      v_task.id,
      v_task.library_id,
      'library',
      v_library_email,
      p_event_kind,
      v_event_at,
      v_changed_fields,
      jsonb_build_object(
        'kind', 'task_library_notice',
        'task_id', v_task.id,
        'library_id', v_task.library_id,
        'recipient_role', 'library',
        'recipient_email', v_library_email,
        'event_kind', p_event_kind,
        'changed_fields', to_jsonb(v_changed_fields)
      ),
      'queued'
    )
    on conflict on constraint painel_internal_task_notification_outbox_event_key do nothing;

    if found then
      v_queued := v_queued + 1;
    end if;
  end if;

  return jsonb_build_object(
    'ok', true,
    'task_id', v_task.id,
    'event_kind', p_event_kind,
    'queued', v_queued,
    'changed_fields', v_changed_fields,
    'organizer_email', v_organizer_email,
    'library_email', case when lower(coalesce(v_library_email, '')) = lower(coalesce(v_organizer_email, '')) then null else v_library_email end
  );
end;
$$;


