CREATE OR REPLACE FUNCTION "public"."fn_archive_notification"("p_notification_id" bigint) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_user_id uuid := auth.uid();
  v_rows int;
BEGIN
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'auth required' USING HINT = 'fn_archive_notification: no authenticated user in context';
  END IF;

  UPDATE public.user_notifications
     SET archived_at = now()
   WHERE id = p_notification_id
     AND user_id = v_user_id
     AND archived_at IS NULL;

  GET DIAGNOSTICS v_rows = ROW_COUNT;
  IF v_rows = 0 THEN
    RAISE EXCEPTION 'notification % not found, not owned, or already archived for user %',
      p_notification_id, v_user_id
      USING HINT = 'fn_archive_notification: vérifier que la notification appartient à auth.uid() et n''est pas déjà archivée';
  END IF;
END;
$$;


ALTER FUNCTION "public"."fn_archive_notification"("p_notification_id" bigint) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."fn_archive_notification"("p_notification_id" bigint) IS 'Chantier #CL.6 (31/05/2026). Archive une notification appartenant à auth.uid(). SECURITY DEFINER + REVOKE/GRANT doctrine v2. Échoue si la notification n''existe pas, n''appartient pas à l''utilisateur courant, ou est déjà archivée.';



CREATE OR REPLACE FUNCTION "public"."fn_auto_hide_consulta_linha_on_close"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_disable    boolean;
  v_user_id    uuid;
  v_library_id uuid;
BEGIN
  SELECT c.user_id, c.library_id INTO v_user_id, v_library_id
    FROM public.consultas_locais_v2 c WHERE c.id = NEW.consulta_id;

  SELECT disable_retention INTO v_disable
    FROM public.user_history_retention_preferences
   WHERE user_id = v_user_id AND library_id = v_library_id AND domain = 'consultations';

  IF v_disable IS TRUE THEN
    NEW.is_hidden_by_user := true;
    NEW.hidden_at := now();
  END IF;
  RETURN NEW;
END;
$$;


