CREATE OR REPLACE FUNCTION "public"."fn_book_restricted_digital_state"("p_bib_ref" "text") RETURNS TABLE("bib_ref" "text", "book_id" bigint, "book_exists" boolean, "has_restricted_digital_resource" boolean, "resource_type" "text", "usage_type" "text", "resource_status" "text", "file_exists" boolean, "user_account_active" boolean, "can_show_access_button" boolean)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_book_id bigint;
  v_resource_type text := '';
  v_usage_type text := '';
  v_resource_status text := '';
  v_storage_bucket text := '';
  v_storage_path text := '';
  v_user_active boolean := false;
begin
  select b.id
    into v_book_id
  from public.books b
  where b.bib_ref = p_bib_ref
  order by b.id desc
  limit 1;

  v_user_active := public.fn_current_user_conta_ativa();

  if v_book_id is not null then
    select
      coalesce(r.resource_type, ''),
      coalesce(r.usage_type, ''),
      coalesce(r.status, ''),
      coalesce(r.storage_bucket, ''),
      coalesce(r.storage_path, '')
      into v_resource_type, v_usage_type, v_resource_status, v_storage_bucket, v_storage_path
    from public.book_digital_resources r
    where r.book_id = v_book_id
      and r.access_scope = 'conta_ativa'
      and r.status = 'active'
      and coalesce(r.is_active, false) = true
    order by
      case when coalesce(r.is_primary, false) then 0 else 1 end,
      r.updated_at desc nulls last,
      r.id desc
    limit 1;
  end if;

  return query
  select
    p_bib_ref,
    v_book_id,
    (v_book_id is not null),
    (v_resource_type <> ''),
    nullif(v_resource_type, ''),
    nullif(v_usage_type, ''),
    nullif(v_resource_status, ''),
    (v_storage_bucket <> '' and v_storage_path <> ''),
    v_user_active,
    ((v_resource_type <> '') and v_user_active);
end;
$$;


ALTER FUNCTION "public"."fn_book_restricted_digital_state"("p_bib_ref" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."fn_book_restricted_digital_state"("p_bib_ref" "text") IS 'AnarBib V3: état générique des ressources numériques restritas (pas seulement PDF) pour un bib_ref donné.';



CREATE OR REPLACE FUNCTION "public"."fn_book_restricted_pdf_state"("p_bib_ref" "text") RETURNS TABLE("bib_ref" "text", "book_id" bigint, "book_exists" boolean, "has_reading_resource" boolean, "resource_status" "text", "file_exists" boolean, "user_account_active" boolean, "can_show_read_button" boolean)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'auth', 'storage', 'pg_temp'
    AS $$
declare
  v_book_id bigint := null;
  v_book_ref text := null;

  v_user_active boolean := false;

  v_has_resource boolean := false;
  v_resource_id bigint := null;
  v_resource_status text := null;
  v_resource_is_active boolean := false;
  v_resource_access_scope text := '';
  v_storage_bucket text := null;
  v_storage_path text := null;

  v_file_exists boolean := false;
begin
  /*
    1) Résolution canonique par la surface publique v2
       => notice commune books / détail holdings-first
  */
  select
    coalesce(v.book_id, v.id)::bigint,
    v.bib_ref::text
  into
    v_book_id,
    v_book_ref
  from public.v_book_detail_public_v2 v
  where trim(coalesce(v.bib_ref, '')) = trim(coalesce(p_bib_ref, ''))
  limit 1;

  /*
    2) Fallback compat strict par local_bib_ref
       => seulement si la référence locale pointe vers un seul book_id distinct
       => évite les faux positifs en cas d’ambiguïté multi-bibliothèque
  */
  if v_book_id is null then
    with matched_holdings as (
      select h.book_id
      from public.book_holdings h
      where trim(coalesce(h.local_bib_ref, '')) = trim(coalesce(p_bib_ref, ''))
      group by h.book_id
    )
    select
      b.id::bigint,
      b.bib_ref::text
    into
      v_book_id,
      v_book_ref
    from matched_holdings mh
    join public.books b
      on b.id = mh.book_id
    where (select count(*) from matched_holdings) = 1
    limit 1;
  end if;

  v_user_active := public.fn_current_user_conta_ativa();

  if v_book_id is not null then
    select
      r.id,
      r.status::text,
      coalesce(r.is_active, false),
      coalesce(r.access_scope, ''),
      r.storage_bucket,
      r.storage_path
    into
      v_resource_id,
      v_resource_status,
      v_resource_is_active,
      v_resource_access_scope,
      v_storage_bucket,
      v_storage_path
    from public.book_digital_resources r
    where r.book_id::bigint = v_book_id
      and r.resource_type = 'pdf_restrito'
      and r.usage_type = 'leitura_online'
      and r.access_scope = 'conta_ativa'
    order by
      case
        when r.status = 'active' and coalesce(r.is_active, false) = true then 0
        else 1
      end,
      coalesce(r.updated_at, r.created_at) desc,
      r.id desc
    limit 1;

    if v_resource_id is not null then
      v_has_resource := true;

      if v_storage_bucket is not null
         and v_storage_path is not null then
        select exists (
          select 1
          from storage.objects so
          where so.bucket_id = v_storage_bucket
            and so.name = v_storage_path
        )
        into v_file_exists;
      end if;
    end if;
  end if;

  bib_ref := trim(coalesce(v_book_ref, p_bib_ref));
  book_id := v_book_id;
  book_exists := (v_book_id is not null);
  has_reading_resource := v_has_resource;
  resource_status := v_resource_status;
  file_exists := coalesce(v_file_exists, false);
  user_account_active := coalesce(v_user_active, false);
  can_show_read_button := (
    book_exists
    and has_reading_resource
    and resource_status = 'active'
    and v_resource_is_active = true
    and v_resource_access_scope = 'conta_ativa'
    and file_exists
    and user_account_active
  );

  return next;
end;
$$;


