CREATE OR REPLACE FUNCTION "public"."fn_bulk_create_book_drafts_from_run"("p_run_id" bigint, "p_batch_id" bigint, "p_created_by" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'ingest', 'auth'
    AS $$
declare
  v_actor uuid;
  v_partner_name text;
  v_relation_status text;
  v_original_filename text;
  v_detected_format text;
  v_batch_name text;
  v_batch_status text;
  v_requested_count integer := 0;
  v_created_count integer := 0;
  v_draft_id bigint;
  v_draft_ids bigint[] := '{}';
  v_refresh jsonb;
  v_collection_hint text;
  v_local_classification_hint text;
  v_provenance_note text;
  rec record;
begin
  v_actor := coalesce(p_created_by, auth.uid());

  select b.name, b.status into v_batch_name, v_batch_status
  from public.catalog_batches b
  where b.id = p_batch_id;

  if not found then
    raise exception 'Lote % introuvable pour la création des rascunhos.', p_batch_id;
  end if;

  if coalesce(v_batch_status, '') <> 'open' then
    raise exception 'O lote % não está aberto para receber rascunhos.', p_batch_id;
  end if;

  select s.partner_name, s.relation_status, r.original_filename, r.detected_format
    into v_partner_name, v_relation_status, v_original_filename, v_detected_format
  from ingest.partner_catalog_import_runs r
  join ingest.partner_catalog_sources s on s.id = r.source_id
  where r.id = p_run_id;

  if not found then
    raise exception 'import_run % introuvable', p_run_id;
  end if;

  select count(*)::integer
    into v_requested_count
  from ingest.partner_catalog_staging_rows sr
  where sr.run_id = p_run_id
    and sr.created_book_draft_id is null
    and not exists (
      select 1 from ingest.partner_catalog_row_to_draft rd where rd.staging_row_id = sr.id
    )
    and (
      (sr.match_status = 'new_record' and sr.editorial_decision = 'accept_new')
      or
      (sr.match_status in ('matched_book', 'matched_draft', 'possible_duplicate', 'manual_decision')
       and sr.editorial_decision = 'accept_duplicate')
    );

  if v_requested_count = 0 then
    raise exception 'Ainda não há linhas autorizadas para virar rascunho normal neste tratamento (%).', p_run_id;
  end if;

  for rec in
    select sr.*, r.original_filename, r.detected_format, s.partner_name, s.relation_status
    from ingest.partner_catalog_staging_rows sr
    join ingest.partner_catalog_import_runs r on r.id = sr.run_id
    join ingest.partner_catalog_sources s on s.id = r.source_id
    where sr.run_id = p_run_id
      and sr.created_book_draft_id is null
      and not exists (
        select 1 from ingest.partner_catalog_row_to_draft rd where rd.staging_row_id = sr.id
      )
      and (
        (sr.match_status = 'new_record' and sr.editorial_decision = 'accept_new')
        or
        (sr.match_status in ('matched_book', 'matched_draft', 'possible_duplicate', 'manual_decision')
         and sr.editorial_decision = 'accept_duplicate')
      )
    order by sr.row_no, sr.id
  loop
    v_collection_hint := ingest.fn_partner_catalog_extract_collection_hint(rec.normalized_payload, rec.raw_payload);
    v_local_classification_hint := ingest.fn_partner_catalog_extract_local_classification_hint(rec.normalized_payload, rec.raw_payload);

    v_provenance_note := format(
      'Importado de catálogo parceiro "%s" (%s, run %s, linha %s, formato bruto %s, relação %s, decisão %s).',
      rec.partner_name,
      coalesce(rec.original_filename, 'arquivo sem nome'),
      rec.run_id,
      rec.row_no,
      coalesce(rec.detected_format, 'unknown'),
      coalesce(rec.relation_status, 'sem_status'),
      coalesce(rec.editorial_decision, 'pending')
    );

    if v_local_classification_hint is not null then
      v_provenance_note := v_provenance_note || format(' Sinal local da parceira preservado: %s.', v_local_classification_hint);
    end if;

    insert into public.book_drafts (
      batch_id,
      action,
      status,
      titulo,
      subtitulo,
      autor,
      edicao,
      local_publicacao,
      editora,
      ano,
      isbn,
      issn,
      idioma,
      tipo_material,
      cdd,
      colecao,
      marc_json,
      created_by,
      updated_by,
      acquisition_mode,
      partner_source,
      source_record_id,
      import_format,
      import_method,
      provenance_note,
      mutualization_status,
      source_label,
      notas
    ) values (
      p_batch_id,
      'create',
      'draft',
      nullif(trim(rec.title), ''),
      nullif(trim(rec.subtitle), ''),
      coalesce(nullif(trim(rec.responsibility_statement), ''), ingest.fn_format_partner_authors(rec.authors)),
      nullif(trim(rec.edition_statement), ''),
      nullif(trim(rec.place_of_publication), ''),
      nullif(trim(rec.publisher), ''),
      nullif(trim(rec.publication_year), ''),
      nullif(trim(rec.isbn), ''),
      nullif(trim(rec.issn), ''),
      nullif(trim(rec.language), ''),
      coalesce(nullif(trim(rec.item_type), ''), 'Livro'),
      null,
      case
        when v_collection_hint is null then null
        when lower(coalesce(rec.item_type, '')) ~ '(periodic|journal|article|boletim|periodico|periódico)' then null
        when lower(regexp_replace(coalesce(v_collection_hint, ''), '\s+', ' ', 'g')) = lower(regexp_replace(coalesce(rec.title, ''), '\s+', ' ', 'g')) then null
        else v_collection_hint
      end,
      coalesce(rec.normalized_payload, '{}'::jsonb)
        || jsonb_build_object(
             'ingest',
             jsonb_build_object(
               'run_id', rec.run_id,
               'staging_row_id', rec.id,
               'row_no', rec.row_no,
               'source_file_id', rec.source_file_id,
               'partner_name', rec.partner_name,
               'relation_status', rec.relation_status,
               'original_filename', rec.original_filename,
               'detected_format', rec.detected_format,
               'raw_payload', coalesce(rec.raw_payload, '{}'::jsonb),
               'authors', coalesce(rec.authors, '[]'::jsonb),
               'subjects', coalesce(rec.subjects, '[]'::jsonb),
               'editorial_decision', rec.editorial_decision,
               'editorial_note', rec.editorial_note,
               'derived_collection_hint', v_collection_hint,
               'derived_local_classification_hint', v_local_classification_hint
             )
           ),
      v_actor,
      v_actor,
      null,
      null,
      coalesce(nullif(trim(rec.external_key), ''), rec.id::text),
      null,
      null,
      v_provenance_note,
      null,
      coalesce(rec.original_filename, rec.partner_name),
      concat_ws(
        ' ',
        case
          when rec.subjects is not null
           and jsonb_typeof(rec.subjects) = 'array'
           and jsonb_array_length(rec.subjects) > 0
          then 'Assuntos importados: '
               || array_to_string(array(select jsonb_array_elements_text(rec.subjects)), '; ')
          else null
        end,
        case
          when v_local_classification_hint is not null
          then format('Classificação / cote local preservada da parceira: %s.', v_local_classification_hint)
          else null
        end
      )
    ) returning id into v_draft_id;

    v_draft_ids := array_append(v_draft_ids, v_draft_id);

    insert into ingest.partner_catalog_row_to_draft (staging_row_id, run_id, draft_id, batch_id, created_by)
    values (rec.id, rec.run_id, v_draft_id, p_batch_id, v_actor);

    update ingest.partner_catalog_staging_rows
       set created_book_draft_id = v_draft_id,
           review_status = 'draft_created',
           selected_for_draft = false
     where id = rec.id;

    v_created_count := v_created_count + 1;
  end loop;

  v_refresh := ingest.fn_refresh_partner_catalog_run_counters(p_run_id);

  return jsonb_build_object(
    'run_id', p_run_id,
    'batch_id', p_batch_id,
    'batch_name', v_batch_name,
    'requested_rows', v_requested_count,
    'created_drafts', v_created_count,
    'draft_ids', coalesce(to_jsonb(v_draft_ids), '[]'::jsonb),
    'run', v_refresh
  );
end;
$$;


ALTER FUNCTION "public"."fn_bulk_create_book_drafts_from_run"("p_run_id" bigint, "p_batch_id" bigint, "p_created_by" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."fn_bulk_create_book_drafts_from_run"("p_run_id" bigint, "p_batch_id" bigint, "p_created_by" "uuid") IS 'S3 : wrapper S2 raffiné pour conserver prudemment les indices de collection/série et de cote locale lors de la conversion run -> lote -> rascunhos.';



CREATE OR REPLACE FUNCTION "public"."fn_bulk_set_partner_catalog_editorial_decision"("p_row_ids" bigint[], "p_editorial_decision" "text", "p_reviewed_by" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'ingest', 'auth'
    AS $$
declare
  v_row_ids bigint[] := '{}';
  v_run_id bigint;
  v_distinct_runs integer := 0;
  v_matched_rows integer := 0;
  v_result jsonb;
begin
  select coalesce(array_agg(distinct x order by x), '{}'::bigint[])
    into v_row_ids
  from unnest(coalesce(p_row_ids, '{}'::bigint[])) as t(x)
  where x is not null and x > 0;

  if coalesce(array_length(v_row_ids, 1), 0) = 0 then
    raise exception 'Nenhuma linha elegível foi recebida para decisão editorial em lote.';
  end if;

  select count(distinct sr.run_id)::integer,
         min(sr.run_id),
         count(*)::integer
    into v_distinct_runs, v_run_id, v_matched_rows
  from ingest.partner_catalog_staging_rows sr
  where sr.id = any(v_row_ids);

  if coalesce(v_matched_rows, 0) <> coalesce(array_length(v_row_ids, 1), 0) then
    raise exception 'Uma ou mais linhas selecionadas não existem mais nesta superfície.';
  end if;

  if coalesce(v_distinct_runs, 0) <> 1 or v_run_id is null then
    raise exception 'As linhas selecionadas devem pertencer a um único tratamento parceiro.';
  end if;

  v_result := ingest.fn_set_partner_catalog_editorial_decision(
    p_run_id := v_run_id,
    p_row_ids := v_row_ids,
    p_editorial_decision := p_editorial_decision,
    p_editorial_note := null,
    p_decided_by := coalesce(p_reviewed_by, auth.uid())
  );

  return coalesce(v_result, '{}'::jsonb)
    || jsonb_build_object(
         'row_count', coalesce(array_length(v_row_ids, 1), 0),
         'rows_passed', coalesce(array_length(v_row_ids, 1), 0),
         'run_id', v_run_id
       );
end;
$$;


ALTER FUNCTION "public"."fn_bulk_set_partner_catalog_editorial_decision"("p_row_ids" bigint[], "p_editorial_decision" "text", "p_reviewed_by" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."fn_bulk_set_partner_catalog_editorial_decision"("p_row_ids" bigint[], "p_editorial_decision" "text", "p_reviewed_by" "uuid") IS 'Wrapper S2 pour le front de revue partenaire : accepte p_row_ids + decisão + reviewer, résout le run_id, puis délègue au backend ingest canonique.';



CREATE OR REPLACE FUNCTION "public"."fn_caller_is_administrador"() RETURNS boolean
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'auth', 'pg_temp'
    AS $$
BEGIN
    RAISE EXCEPTION 'deprecated: fn_caller_is_administrador is deprecated. Use fn_caller_is_network_admin (v0.3) for network admin checks, or query user_library_memberships directly for local administrador role checks.'
        USING ERRCODE = '0A000';  -- feature_not_supported
END;
$$;


