COMMENT ON FUNCTION "public"."fn_caller_is_administrador"() IS 'D.8 — DEPRECATED v0.3. Remplacée par fn_caller_is_network_admin pour la doctrine admin réseau. Le rôle local administrador dans user_library_memberships sera supprimé au paquet F.';



CREATE OR REPLACE FUNCTION "public"."fn_caller_is_network_admin"() RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'auth', 'pg_temp'
    AS $$
    SELECT EXISTS (
        SELECT 1 FROM public.network_administrators
        WHERE user_id = auth.uid() AND status = 'active'
    );
$$;


