COMMENT ON FUNCTION "public"."fn_caller_is_network_admin"() IS 'Retourne TRUE si l''appelant courant est un administrateur réseau actif. Remplace fn_caller_is_administrador() (qui reste opérationnel pendant la coexistence du paquet B).';



CREATE OR REPLACE FUNCTION "public"."fn_can_engage_library_for_storage"("p_library_id" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
    SELECT
        EXISTS (
            SELECT 1 FROM public.network_administrators
            WHERE user_id = auth.uid() AND status = 'active'
        )
        OR
        EXISTS (
            SELECT 1 FROM public.user_library_memberships m
            WHERE m.user_id = auth.uid()
              AND m.library_id = p_library_id
              AND m.status = 'active'
              AND m.role = 'coordenador'
        );
$$;


