CREATE OR REPLACE FUNCTION "public"."fn_cancel_library_profile_change"("p_proposal_id" "uuid", "p_motivation" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_caller_id  uuid := auth.uid();
  v_proposal   public.library_profile_proposals%ROWTYPE;
BEGIN
  -- ===== Garde-fou 1 : authentification =====
  IF v_caller_id IS NULL THEN
    RAISE EXCEPTION 'CANCEL_AUTH_REQUIRED : authentification requise'
      USING ERRCODE = 'insufficient_privilege',
            HINT    = 'error.profile_change.auth_required';
  END IF;

  -- ===== Garde-fou 2 : motivation substantielle (>= 5 chars) =====
  IF p_motivation IS NULL OR length(trim(p_motivation)) < 5 THEN
    RAISE EXCEPTION 'CANCEL_MOTIVATION_TOO_SHORT : la motivation doit faire au moins 5 caracteres'
      USING ERRCODE = 'check_violation',
            HINT    = 'error.profile_change.motivation_too_short';
  END IF;

  -- ===== Lecture proposal avec lock =====
  SELECT * INTO v_proposal
  FROM public.library_profile_proposals
  WHERE id = p_proposal_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'CANCEL_PROPOSAL_NOT_FOUND : proposition introuvable (%)', p_proposal_id
      USING ERRCODE = 'no_data_found',
            HINT    = 'error.profile_change.proposal_not_found';
  END IF;

  -- ===== Garde-fou 3 : caller est le proposeur original (doctrine D4) =====
  IF v_proposal.proposed_by <> v_caller_id THEN
    RAISE EXCEPTION 'CANCEL_NOT_PROPOSER : seule la personne ayant propose peut annuler'
      USING ERRCODE = 'insufficient_privilege',
            HINT    = 'error.profile_change.not_proposer';
  END IF;

  -- ===== Garde-fou 4 : proposal status='open' =====
  IF v_proposal.status <> 'open' THEN
    RAISE EXCEPTION 'CANCEL_PROPOSAL_NOT_OPEN : la proposition n''est pas annulable (status=%)', v_proposal.status
      USING ERRCODE = 'invalid_parameter_value',
            HINT    = 'error.profile_change.proposal_not_open';
  END IF;

  -- ===== UPDATE proposal status='cancelled' =====
  UPDATE public.library_profile_proposals
  SET status               = 'cancelled',
      cancelled_at         = now(),
      cancelled_by         = v_caller_id,
      cancelled_motivation = trim(p_motivation)
  WHERE id = p_proposal_id;

  RETURN jsonb_build_object(
    'proposal_id',  p_proposal_id,
    'cancelled_at', now(),
    'cancelled_by', v_caller_id
  );
END;
$$;


ALTER FUNCTION "public"."fn_cancel_library_profile_change"("p_proposal_id" "uuid", "p_motivation" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."fn_cancel_library_profile_change"("p_proposal_id" "uuid", "p_motivation" "text") IS 'B.3 RPC : annule une proposition (doctrine D4 : proposeur uniquement, tant que status=open, motivation obligatoire).';



CREATE OR REPLACE FUNCTION "public"."fn_check_consulta_transition"("p_from" "text", "p_to" "text", "p_actor_role" "text") RETURNS boolean
    LANGUAGE "sql" IMMUTABLE PARALLEL SAFE
    SET "search_path" TO 'public'
    AS $$
WITH normalized AS (
  SELECT
    p_from        AS f,
    p_to          AS t,
    p_actor_role  AS r
)
SELECT CASE
  WHEN f IS NULL OR t IS NULL OR r IS NULL THEN false
  WHEN f = '' OR t = '' OR r = '' THEN false

  WHEN f IN (
    'consulta_realizada',
    'cancelada_leitor',
    'cancelada_biblioteca',
    'expirada'
  ) THEN false

  -- F.2 v0.3 : retrait 'administrador' (4 occurrences)
  WHEN f = 'nao_compareceu' AND t = 'cancelada_biblioteca'
       AND r IN ('librarian', 'coordenador') THEN true
  WHEN f = 'nao_compareceu' THEN false

  WHEN r = 'leitor' AND t = 'cancelada_leitor' AND f IN (
    'solicitada',
    'em_preparacao',
    'consulta_agendada'
  ) THEN true

  WHEN r = 'leitor' THEN false

  WHEN r = 'system' AND t = 'expirada' AND f IN (
    'solicitada',
    'em_preparacao',
    'consulta_agendada'
  ) THEN true
  WHEN r = 'system' THEN false

  WHEN f = 'solicitada' AND t IN (
    'em_preparacao',
    'cancelada_biblioteca'
  ) AND r IN ('librarian', 'coordenador') THEN true

  WHEN f = 'em_preparacao' AND t IN (
    'consulta_agendada',
    'cancelada_biblioteca'
  ) AND r IN ('librarian', 'coordenador') THEN true

  WHEN f = 'consulta_agendada' AND t IN (
    'consulta_agendada',
    'consulta_realizada',
    'nao_compareceu',
    'cancelada_biblioteca'
  ) AND r IN ('librarian', 'coordenador') THEN true

  ELSE false
END
FROM normalized;
$$;


ALTER FUNCTION "public"."fn_check_consulta_transition"("p_from" "text", "p_to" "text", "p_actor_role" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."fn_check_consulta_transition"("p_from" "text", "p_to" "text", "p_actor_role" "text") IS 'Helper matrice de transitions du workflow consultations locales (spec-flux-consultations §5.2). Pattern decalque de fn_check_workflow_transition (reservations). Raisonne sur les 8 workflow_stages de consulta_item_workflow_v2. Fail-closed sur NULL ou valeurs vides. Roles : leitor / librarian / coordenador / administrador / system.';



CREATE OR REPLACE FUNCTION "public"."fn_check_loan_action"("p_action" "text", "p_current_status" "text", "p_actor_role" "text") RETURNS boolean
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_action text := lower(trim(coalesce(p_action, '')));
  v_status text := lower(trim(coalesce(p_current_status, '')));
  v_role text := lower(trim(coalesce(p_actor_role, '')));
  -- F.2 v0.3 : retrait 'administrador' (role local supprime)
  v_is_library boolean := v_role IN ('librarian', 'coordenador');
  v_is_reader boolean := v_role = 'leitor';
  v_is_system boolean := v_role = 'system';
  v_active_status boolean := v_status IN ('aberto', 'parcialmente_devolvido');
BEGIN
  IF v_action = '' OR v_role = '' THEN
    RETURN false;
  END IF;

  CASE v_action
    WHEN 'create_loan_at_counter' THEN
      RETURN v_is_library;

    WHEN 'return_total', 'return_partial', 'extend_as_library', 'mark_return_missed' THEN
      RETURN v_is_library AND v_active_status;

    WHEN 'renew_as_reader' THEN
      RETURN (v_is_reader OR v_is_library) AND v_active_status;

    WHEN 'schedule_return', 'clear_return_schedule' THEN
      RETURN (v_is_library OR v_is_reader) AND v_active_status;

    WHEN 'mark_return_missed_by_system' THEN
      RETURN v_is_system AND v_active_status;

    ELSE
      RETURN false;
  END CASE;
END;
$$;


ALTER FUNCTION "public"."fn_check_loan_action"("p_action" "text", "p_current_status" "text", "p_actor_role" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."fn_check_loan_action"("p_action" "text", "p_current_status" "text", "p_actor_role" "text") IS 'Paquet 19 v2 (11/05/2026) : matrice action x acteur x statut pour les emprunts.
Equivalent emprunts du fn_check_workflow_transition pour les reservations.
Fix v2 : renew_as_reader autorise pour les staff aussi (ownership verifiee
dans le wrapper api.renew_my_loan).
Actions : create_loan_at_counter, return_total, return_partial,
extend_as_library, renew_as_reader, schedule_return, clear_return_schedule,
mark_return_missed, mark_return_missed_by_system.
Statuts : aberto, parcialmente_devolvido (actifs) ou null (creation).
Roles : leitor, librarian, coordenador, administrador, system.';



CREATE OR REPLACE FUNCTION "public"."fn_check_unarchive_eligibility"("p_table_name" "text", "p_record_id" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_grace_days int := 90;
  v_library_id uuid;
  v_archived_at timestamptz;
  v_archive_reason text;
  v_due_at date;
  v_age_days int;
  v_record_bigint bigint;
  v_record_uuid uuid;
BEGIN
  IF p_table_name NOT IN ('emprestimos_v2','reservas_v2','consultas_locais_v2','interlibrary_loans_v2','membership_payments') THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'invalid_table_name');
  END IF;

  -- Cast du p_record_id selon la table cible
  BEGIN
    IF p_table_name IN ('emprestimos_v2','reservas_v2','consultas_locais_v2','interlibrary_loans_v2') THEN
      v_record_bigint := p_record_id::bigint;
    ELSE
      v_record_uuid := p_record_id::uuid;
    END IF;
  EXCEPTION WHEN invalid_text_representation THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'invalid_record_id_format');
  END;

  -- Recuperer library_id + archived_at + due_at selon la table
  IF p_table_name = 'emprestimos_v2' THEN
    SELECT library_id, archived_at, archive_reason, due_at
      INTO v_library_id, v_archived_at, v_archive_reason, v_due_at
      FROM public.emprestimos_v2 WHERE id = v_record_bigint;
  ELSIF p_table_name = 'reservas_v2' THEN
    SELECT library_id, archived_at, archive_reason, NULL::date
      INTO v_library_id, v_archived_at, v_archive_reason, v_due_at
      FROM public.reservas_v2 WHERE id = v_record_bigint;
  ELSIF p_table_name = 'consultas_locais_v2' THEN
    SELECT library_id, archived_at, archive_reason, NULL::date
      INTO v_library_id, v_archived_at, v_archive_reason, v_due_at
      FROM public.consultas_locais_v2 WHERE id = v_record_bigint;
  ELSIF p_table_name = 'interlibrary_loans_v2' THEN
    SELECT lender_library_id, archived_at, archive_reason, due_date
      INTO v_library_id, v_archived_at, v_archive_reason, v_due_at
      FROM public.interlibrary_loans_v2 WHERE id = v_record_bigint;
  ELSIF p_table_name = 'membership_payments' THEN
    SELECT library_id, archived_at, archive_reason, NULL::date
      INTO v_library_id, v_archived_at, v_archive_reason, v_due_at
      FROM public.membership_payments WHERE id = v_record_uuid;
  END IF;

  IF v_library_id IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'record_not_found');
  END IF;

  IF v_archived_at IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'not_archived', 'library_id', v_library_id);
  END IF;

  IF NOT EXISTS (
    SELECT 1 FROM public.libraries WHERE id = v_library_id AND circulation_mode <> 'off'
  ) THEN
    RETURN jsonb_build_object(
      'ok', false, 'reason', 'library_still_off', 'library_id', v_library_id
    );
  END IF;

  IF v_due_at IS NOT NULL THEN
    v_age_days := (current_date - v_due_at)::int;
    IF v_age_days > v_grace_days THEN
      RETURN jsonb_build_object(
        'ok', false, 'reason', 'too_old', 'library_id', v_library_id,
        'age_days', v_age_days, 'grace_days', v_grace_days
      );
    END IF;
  END IF;

  RETURN jsonb_build_object(
    'ok', true, 'library_id', v_library_id,
    'archived_at', v_archived_at, 'archive_reason', v_archive_reason,
    'age_days', COALESCE(v_age_days, 0)
  );
END;
$$;


ALTER FUNCTION "public"."fn_check_unarchive_eligibility"("p_table_name" "text", "p_record_id" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_check_workflow_transition"("p_from" "text", "p_to" "text", "p_actor_role" "text") RETURNS boolean
    LANGUAGE "sql" IMMUTABLE PARALLEL SAFE
    SET "search_path" TO 'public'
    AS $$
WITH normalized AS (
  SELECT
    CASE WHEN p_from = 'nao_retirada' THEN 'retirada_no_show'
         ELSE p_from END AS f,
    CASE WHEN p_to = 'nao_retirada' THEN 'retirada_no_show'
         ELSE p_to END AS t,
    p_actor_role AS r
)
SELECT CASE
  -- ===== Garde-fou paramètres =====
  WHEN f IS NULL OR t IS NULL OR r IS NULL THEN false

  -- ===== États terminaux : aucune transition humaine sortante =====
  WHEN f IN (
    'retirada_efetivada',
    'cancelada_leitor',
    'cancelada_biblioteca',
    'expirada',
    'liberada_para_circulacao'
  ) THEN false

  -- ===== retirada_no_show : terminal côté API =====
  WHEN f = 'retirada_no_show' THEN false

  -- ===== re-retirada_agendada DÉPRÉCIÉ (paquet 5a) : aucune transition =====
  -- Conservé dans le code uniquement pour ne pas casser les éventuelles résas
  -- historiques. À supprimer définitivement au paquet 7 de polish.
  WHEN f = 're-retirada_agendada' THEN false
  WHEN t = 're-retirada_agendada' THEN false

  -- ===== Lecteur·rice : annulation à tout moment avant retirada_efetivada =====
  WHEN r = 'lecteur' AND t = 'cancelada_leitor' AND f IN (
    'solicitada',
    'em_preparacao',
    'retirada_a_combinar',
    'retirada_agendada',
    'pronta_para_retirada'
  ) THEN true

  -- ===== Lecteur·rice : contre-proposition de créneau (négo dans a_combinar) =====
  -- Le lecteur peut contre-proposer en restant dans retirada_a_combinar.
  -- Conditions dynamiques (flag biblio, compteur < 3) vérifiées par le wrapper.
  WHEN r = 'lecteur' AND t = 'retirada_a_combinar' AND f = 'retirada_a_combinar' THEN true

  -- ===== Lecteur·rice : confirmation du créneau biblio =====
  -- La confirmation depuis retirada_a_combinar mène à retirada_agendada
  -- (créneau verrouillé, négociation close). Précondition pickup_proposed_by
  -- = 'biblio' vérifiée par api.fn_confirm_pickup_slot_as_reader.
  WHEN r = 'lecteur' AND t = 'retirada_agendada' AND f = 'retirada_a_combinar' THEN true

  -- ===== Lecteur·rice : aucune autre transition autorisée =====
  WHEN r = 'lecteur' THEN false

  -- ===== Coordenador : annulation biblio à toute étape non-terminale =====
  WHEN r = 'coordenador' AND t = 'cancelada_biblioteca' AND f IN (
    'solicitada',
    'em_preparacao',
    'retirada_a_combinar',
    'retirada_agendada',
    'pronta_para_retirada'
  ) THEN true

  -- ===== System (cron, trigger) : transitions automatiques =====
  WHEN r = 'system' AND t = 'expirada' AND f = 'solicitada' THEN true
  -- Spec v3 : timeout global négociation expire seulement em_preparacao et
  -- retirada_a_combinar (PAS retirada_agendada qui est verrouillé).
  WHEN r = 'system' AND t = 'expirada' AND f IN (
    'em_preparacao',
    'retirada_a_combinar'
  ) THEN true
  WHEN r = 'system' AND t = 'retirada_no_show' AND f IN (
    'pronta_para_retirada',
    'retirada_agendada'
  ) THEN true
  WHEN r = 'system' THEN false

  -- ===== Librarian/coordenador : transitions opérationnelles =====

  -- Depuis solicitada (Q1 : retirada_agendada direct interdit)
  WHEN f = 'solicitada' AND t IN (
    'em_preparacao',
    'retirada_a_combinar'
  ) AND r IN ('librarian', 'coordenador') THEN true

  -- Depuis em_preparacao (Q1 : retirada_agendada direct interdit)
  WHEN f = 'em_preparacao' AND t IN (
    'retirada_a_combinar'
  ) AND r IN ('librarian', 'coordenador') THEN true

  -- Depuis retirada_a_combinar (stage central de négociation)
  -- Le staff peut re-proposer (boucle a_combinar → a_combinar) ou conclure
  -- (a_combinar → retirada_agendada via fn_confirm_pickup_slot_as_library).
  -- Pronta_para_retirada ATTEINT seulement après retirada_agendada.
  WHEN f = 'retirada_a_combinar' AND t IN (
    'retirada_a_combinar',
    'retirada_agendada'
  ) AND r IN ('librarian', 'coordenador') THEN true

  -- Depuis retirada_agendada (stage verrouillé, on prépare pour le retrait)
  WHEN f = 'retirada_agendada' AND t IN (
    'pronta_para_retirada'
  ) AND r IN ('librarian', 'coordenador') THEN true

  -- Depuis pronta_para_retirada
  WHEN f = 'pronta_para_retirada' AND t IN (
    'retirada_efetivada',
    'retirada_no_show'
  ) AND r IN ('librarian', 'coordenador') THEN true

  -- ===== Tout le reste = refusé =====
  ELSE false
END
FROM normalized;
$$;


ALTER FUNCTION "public"."fn_check_workflow_transition"("p_from" "text", "p_to" "text", "p_actor_role" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."fn_check_workflow_transition"("p_from" "text", "p_to" "text", "p_actor_role" "text") IS 'Source de vérité de la matrice de transitions du workflow réservation v3 (refactor sémantique 2026-05-09). retirada_a_combinar est le stage central de négociation symétrique. retirada_agendada est le stage d''aboutissement (créneau verrouillé). Le chemin direct solicitada/em_preparacao → retirada_agendada est interdit (Q1). re-retirada_agendada est déprécié (Q3) : aucune transition entrante ni sortante. Le rôle ''lecteur'' peut contre-proposer (a_combinar → a_combinar) ET confirmer (a_combinar → retirada_agendada). Les wrappers api.* font des sanity checks redondants en défense en profondeur.';



CREATE OR REPLACE FUNCTION "public"."fn_circulation_concurrent_max"("p_library_id" "uuid", "p_mode" "text") RETURNS integer
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
  SELECT CASE p_mode
           WHEN 'loan'               THEN s.max_concurrent_loans
           WHEN 'reservation'        THEN s.max_concurrent_reservations
           WHEN 'local_consultation' THEN s.max_concurrent_consultations
         END
  FROM public.library_circulation_policy_sets s
  WHERE s.library_id = p_library_id AND s.is_active = true
  ORDER BY s.id DESC
  LIMIT 1;
$$;


ALTER FUNCTION "public"."fn_circulation_concurrent_max"("p_library_id" "uuid", "p_mode" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_classify_transition"("p_axis" "text", "p_old_value" "text", "p_new_value" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_transition_type   int;
  v_governance        text;
BEGIN
  -- Garde-fou 1 : valeurs identiques
  IF p_old_value = p_new_value THEN
    RAISE EXCEPTION 'CLASSIFY_TRANSITION_SAME_VALUE : la valeur cible (%) est identique a la valeur courante', p_new_value
      USING ERRCODE = 'check_violation',
            HINT    = 'error.profile_change.same_value';
  END IF;

  -- Garde-fou 2 : axe connu
  IF p_axis NOT IN ('catalog_mode', 'circulation_mode', 'network_mode', 'governance_mode') THEN
    RAISE EXCEPTION 'CLASSIFY_TRANSITION_UNKNOWN_AXIS : axe inconnu (%)', p_axis
      USING ERRCODE = 'check_violation',
            HINT    = 'error.profile_change.unknown_axis';
  END IF;

  -- ============================================================
  -- Matrice de classification
  -- ============================================================

  -- ---------- catalog_mode ----------
  IF p_axis = 'catalog_mode' THEN
    IF    p_old_value = 'local_only'        AND p_new_value = 'network_published' THEN v_transition_type := 1;
    ELSIF p_old_value = 'network_published' AND p_new_value = 'local_only'         THEN v_transition_type := 3;
    ELSE
      RAISE EXCEPTION 'CLASSIFY_TRANSITION_INVALID_VALUES : catalog_mode invalide (%, %)', p_old_value, p_new_value
        USING ERRCODE = 'check_violation',
              HINT    = 'error.profile_change.invalid_values';
    END IF;

  -- ---------- circulation_mode ----------
  ELSIF p_axis = 'circulation_mode' THEN
    IF    p_old_value = 'off'       AND p_new_value = 'informal'  THEN v_transition_type := 1;
    ELSIF p_old_value = 'off'       AND p_new_value = 'full_sigb' THEN v_transition_type := 1;
    ELSIF p_old_value = 'informal'  AND p_new_value = 'full_sigb' THEN v_transition_type := 1;
    ELSIF p_old_value = 'full_sigb' AND p_new_value = 'informal'  THEN v_transition_type := 4;  -- archivage prets formels
    ELSIF p_old_value = 'informal'  AND p_new_value = 'off'       THEN v_transition_type := 3;  -- rien a archiver
    ELSIF p_old_value = 'full_sigb' AND p_new_value = 'off'       THEN v_transition_type := 4;  -- cessation totale
    ELSE
      RAISE EXCEPTION 'CLASSIFY_TRANSITION_INVALID_VALUES : circulation_mode invalide (%, %)', p_old_value, p_new_value
        USING ERRCODE = 'check_violation',
              HINT    = 'error.profile_change.invalid_values';
    END IF;

  -- ---------- network_mode ----------
  ELSIF p_axis = 'network_mode' THEN
    IF    p_old_value = 'isolated'  AND p_new_value = 'observer'  THEN v_transition_type := 1;
    ELSIF p_old_value = 'isolated'  AND p_new_value = 'federated' THEN v_transition_type := 1;
    ELSIF p_old_value = 'observer'  AND p_new_value = 'federated' THEN v_transition_type := 1;
    ELSIF p_old_value = 'federated' AND p_new_value = 'observer'  THEN v_transition_type := 3;
    ELSIF p_old_value = 'observer'  AND p_new_value = 'isolated'  THEN v_transition_type := 3;
    ELSIF p_old_value = 'federated' AND p_new_value = 'isolated'  THEN v_transition_type := 3;
    ELSE
      RAISE EXCEPTION 'CLASSIFY_TRANSITION_INVALID_VALUES : network_mode invalide (%, %)', p_old_value, p_new_value
        USING ERRCODE = 'check_violation',
              HINT    = 'error.profile_change.invalid_values';
    END IF;

  -- ---------- governance_mode ----------
  ELSIF p_axis = 'governance_mode' THEN
    IF    p_old_value = 'informal'        AND p_new_value = 'staff_roles'     THEN v_transition_type := 1;
    ELSIF p_old_value = 'informal'        AND p_new_value = 'full_governance' THEN v_transition_type := 1;
    ELSIF p_old_value = 'staff_roles'     AND p_new_value = 'full_governance' THEN v_transition_type := 1;
    ELSIF p_old_value = 'full_governance' AND p_new_value = 'staff_roles'     THEN v_transition_type := 2;  -- recul doux
    ELSIF p_old_value = 'staff_roles'     AND p_new_value = 'informal'        THEN v_transition_type := 4;  -- perte audits
    ELSIF p_old_value = 'full_governance' AND p_new_value = 'informal'        THEN v_transition_type := 4;  -- perte votes+audits
    ELSE
      RAISE EXCEPTION 'CLASSIFY_TRANSITION_INVALID_VALUES : governance_mode invalide (%, %)', p_old_value, p_new_value
        USING ERRCODE = 'check_violation',
              HINT    = 'error.profile_change.invalid_values';
    END IF;
  END IF;

  -- ============================================================
  -- Mapping type -> gouvernance requise
  -- ============================================================
  v_governance := CASE v_transition_type
    WHEN 1 THEN 'direct'
    WHEN 2 THEN 'majority'
    WHEN 3 THEN 'unanimous'
    WHEN 4 THEN 'unanimous_extended'
  END;

  RETURN jsonb_build_object(
    'transition_type', v_transition_type,
    'governance_required', v_governance
  );
END;
$$;


ALTER FUNCTION "public"."fn_classify_transition"("p_axis" "text", "p_old_value" "text", "p_new_value" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."fn_classify_transition"("p_axis" "text", "p_old_value" "text", "p_new_value" "text") IS 'B.2 : classifie une transition (axe, ancien, nouveau) en {transition_type, governance_required}. Encode la matrice politique de la spec v0.3 §9.1. Voir docs/decisions/CHANTIER_doctrine_transitions_profils_2026-05-17.md pour le raisonnement politique complet.';



CREATE OR REPLACE FUNCTION "public"."fn_compute_membership_validity"("p_rule_id" "uuid", "p_paid_at" timestamp with time zone DEFAULT "now"()) RETURNS TABLE("valid_from" "date", "valid_until" "date")
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_period_type public.membership_period_type;
  v_period_anchor public.membership_period_anchor;
  v_paid_date date := p_paid_at::date;
  v_from date := v_paid_date;
  v_until date;
BEGIN
  SELECT period_type, period_anchor
    INTO v_period_type, v_period_anchor
  FROM public.library_membership_rules
  WHERE id = p_rule_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Regra de contribuição não encontrada: %', p_rule_id;
  END IF;

  -- Calcul de valid_until selon period_type × period_anchor
  v_until := CASE
    WHEN v_period_type = 'lifetime' THEN NULL
    WHEN v_period_type = 'none'     THEN NULL
    WHEN v_period_anchor = 'calendar' THEN
      CASE v_period_type
        WHEN 'annual'    THEN make_date(extract(year from v_paid_date)::int, 12, 31)
        WHEN 'monthly'   THEN (date_trunc('month', v_paid_date) + interval '1 month - 1 day')::date
        WHEN 'quarterly' THEN (date_trunc('quarter', v_paid_date) + interval '3 months - 1 day')::date
      END
    -- 'rolling' : N période(s) à partir de la date de paiement
    WHEN v_period_anchor = 'rolling' THEN
      CASE v_period_type
        WHEN 'annual'    THEN v_paid_date + interval '1 year' - interval '1 day'
        WHEN 'monthly'   THEN v_paid_date + interval '1 month' - interval '1 day'
        WHEN 'quarterly' THEN v_paid_date + interval '3 months' - interval '1 day'
      END
  END::date;

  RETURN QUERY SELECT v_from, v_until;
END $$;


ALTER FUNCTION "public"."fn_compute_membership_validity"("p_rule_id" "uuid", "p_paid_at" timestamp with time zone) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."fn_compute_membership_validity"("p_rule_id" "uuid", "p_paid_at" timestamp with time zone) IS 'Calcule valid_from et valid_until pour un paiement, selon period_type × period_anchor de la règle.';



CREATE TABLE IF NOT EXISTS "public"."library_request_claims" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "user_id" "uuid" NOT NULL,
    "email_snapshot" "text" NOT NULL,
    "claim_token_hash" "text" NOT NULL,
    "claim_purpose" "text" DEFAULT 'library_request'::"text" NOT NULL,
    "expires_at" timestamp with time zone NOT NULL,
    "used_at" timestamp with time zone,
    "used_by_request_id" "uuid",
    "metadata" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "created_by_user_id" "uuid",
    CONSTRAINT "library_request_claims_email_chk" CHECK ((POSITION(('@'::"text") IN ("email_snapshot")) > 1)),
    CONSTRAINT "library_request_claims_expires_chk" CHECK (("expires_at" > "created_at")),
    CONSTRAINT "library_request_claims_hash_chk" CHECK ((NULLIF("btrim"("claim_token_hash"), ''::"text") IS NOT NULL)),
    CONSTRAINT "library_request_claims_purpose_chk" CHECK (("claim_purpose" = 'library_request'::"text")),
    CONSTRAINT "library_request_claims_used_at_chk" CHECK ((("used_at" IS NULL) OR ("used_at" >= "created_at")))
);


ALTER TABLE "public"."library_request_claims" OWNER TO "postgres";


COMMENT ON TABLE "public"."library_request_claims" IS 'Claims à usage limité pour ouvrir le parcours de sollicitation institutionnelle sans détourner le login global.';



COMMENT ON COLUMN "public"."library_request_claims"."claim_token_hash" IS 'Hash SHA-256 du token opaque envoyé par e-mail. Le token brut n’est jamais stocké.';



COMMENT ON COLUMN "public"."library_request_claims"."claim_purpose" IS 'Usage métier du claim. Pour ce chantier: library_request.';



COMMENT ON COLUMN "public"."library_request_claims"."used_by_request_id" IS 'Solicitação institutionnelle créée à partir de ce claim, une fois consommé.';



CREATE OR REPLACE FUNCTION "public"."fn_consume_library_request_claim"("p_claim_token" "text", "p_request_id" "uuid" DEFAULT NULL::"uuid") RETURNS "public"."library_request_claims"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions'
    AS $$
declare
  v_row public.library_request_claims;
begin
  if nullif(btrim(coalesce(p_claim_token, '')), '') is null then
    raise exception 'Link inválido.' using errcode = '23514';
  end if;

  update public.library_request_claims c
  set
    used_at = now(),
    used_by_request_id = coalesce(p_request_id, c.used_by_request_id)
  where c.claim_token_hash = public.fn_hash_claim_token(btrim(p_claim_token))
    and c.claim_purpose = 'library_request'
    and c.used_at is null
    and c.expires_at > now()
  returning c.* into v_row;

  if not found then
    raise exception 'Este link não é mais válido. Solicite um novo acesso.'
      using errcode = '42501';
  end if;

  return v_row;
end;
$$;


ALTER FUNCTION "public"."fn_consume_library_request_claim"("p_claim_token" "text", "p_request_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."fn_consume_library_request_claim"("p_claim_token" "text", "p_request_id" "uuid") IS 'SECURITY DEFINER intentional: consomme un claim token après utilisation, en marquant used_at et used_by_request_id. Filtrage par hash SHA-256. Vérifie l''expiration et la non-utilisation préalable.';



CREATE OR REPLACE FUNCTION "public"."fn_cron_collective_removal_execute"() RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'auth', 'pg_temp'
    AS $$
DECLARE
    v_executed_count integer := 0;
    v_proposal record;
BEGIN
    FOR v_proposal IN
        SELECT id, proposed_user_id, proposed_by
        FROM public.network_admin_collective_removal_proposals
        WHERE status = 'unanimous'
          AND pending_removal_until IS NOT NULL
          AND pending_removal_until <= now()
        FOR UPDATE
    LOOP
        UPDATE public.network_administrators
            SET status = 'removed',
                removed_at = now()
            WHERE user_id = v_proposal.proposed_user_id;
        
        UPDATE public.network_admin_collective_removal_proposals
            SET status = 'executed',
                executed_at = now()
            WHERE id = v_proposal.id;
        
        INSERT INTO public.network_administrator_audit
            (user_id, event_type, actor_user_id, target_user_id, metadata)
        VALUES (
            v_proposal.proposed_user_id,
            'collective_removal_executed',
            NULL,
            v_proposal.proposed_user_id,
            jsonb_build_object(
                'proposal_id', v_proposal.id,
                'executed_by', 'cron'
            )
        );
        
        -- 1 seul INSERT outbox
        PERFORM public.fn_network_notify_event(
            'network.collective_removal_executed',
            jsonb_build_object(
                'proposal_id', v_proposal.id,
                'proposed_user_id', v_proposal.proposed_user_id,
                'proposed_by', v_proposal.proposed_by
            )
        );
        
        v_executed_count := v_executed_count + 1;
    END LOOP;

    -- Expirer les propositions ouvertes au-delà de expires_at
    UPDATE public.network_admin_collective_removal_proposals
        SET status = 'expired'
        WHERE status = 'open'
          AND expires_at <= now();

    RETURN v_executed_count;
END;
$$;


ALTER FUNCTION "public"."fn_cron_collective_removal_execute"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."fn_cron_collective_removal_execute"() IS 'D.6.c — Cron quotidien : exécute les retraits dont la carence 7j est expirée, expire les propositions au-delà des 60j.';



CREATE OR REPLACE FUNCTION "public"."fn_cron_cooptation_send_reminders"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'auth', 'pg_temp'
    AS $$
DECLARE
    v_proposal record;
    v_pending_voters jsonb;
    v_outbox_id bigint;
    v_j14_count integer := 0;
    v_j25_count integer := 0;
    v_now timestamptz := now();
BEGIN
    -- =========================================================================
    -- Passe J+14 : propositions créées entre J-15 et J-14
    -- =========================================================================
    FOR v_proposal IN
        SELECT id, proposed_user_id, proposed_by, proposed_at, expires_at
        FROM public.network_administrator_cooptation_proposals
        WHERE status = 'open'
          AND proposed_at >= v_now - interval '15 days'
          AND proposed_at <  v_now - interval '14 days'
    LOOP
        -- Calculer la liste des admins actifs n'ayant pas voté (hors proposé)
        -- C'est cette liste qui sera consommée par l'Edge Function pour le fan-out.
        SELECT COALESCE(jsonb_agg(na.user_id), '[]'::jsonb) INTO v_pending_voters
        FROM public.network_administrators na
        WHERE na.status = 'active'
          AND na.user_id <> v_proposal.proposed_user_id
          AND NOT EXISTS (
              SELECT 1 FROM public.network_administrator_cooptation_votes v
              WHERE v.proposal_id = v_proposal.id
                AND v.voter_user_id = na.user_id
          );

        -- Si la liste est vide (tous ont voté), on saute (la proposition devrait
        -- déjà avoir basculé en autre statut, mais on est prudent)
        IF v_pending_voters = '[]'::jsonb THEN
            CONTINUE;
        END IF;

        -- INSERT outbox : un seul event par proposition, l'Edge Function
        -- résout le fan-out depuis pending_voters[]
        SELECT public.fn_network_notify_event(
            'network.cooptation_reminder',
            jsonb_build_object(
                'proposal_id', v_proposal.id,
                'proposed_user_id', v_proposal.proposed_user_id,
                'proposed_by', v_proposal.proposed_by,
                'proposed_at', v_proposal.proposed_at,
                'expires_at', v_proposal.expires_at,
                'reminder_kind', 'j14',
                'pending_voters', v_pending_voters
            )
        ) INTO v_outbox_id;

        -- Audit
        INSERT INTO public.network_administrator_audit
            (user_id, event_type, actor_user_id, target_user_id, metadata)
        VALUES (
            v_proposal.proposed_user_id,
            'cooptation_reminder_sent',
            NULL,  -- exécution cron, pas d'actor utilisateur
            v_proposal.proposed_user_id,
            jsonb_build_object(
                'proposal_id', v_proposal.id,
                'reminder_kind', 'j14',
                'pending_voters_count', jsonb_array_length(v_pending_voters),
                'outbox_id', v_outbox_id
            )
        );

        v_j14_count := v_j14_count + 1;
    END LOOP;

    -- =========================================================================
    -- Passe J+25 : propositions créées entre J-26 et J-25
    -- =========================================================================
    FOR v_proposal IN
        SELECT id, proposed_user_id, proposed_by, proposed_at, expires_at
        FROM public.network_administrator_cooptation_proposals
        WHERE status = 'open'
          AND proposed_at >= v_now - interval '26 days'
          AND proposed_at <  v_now - interval '25 days'
    LOOP
        SELECT COALESCE(jsonb_agg(na.user_id), '[]'::jsonb) INTO v_pending_voters
        FROM public.network_administrators na
        WHERE na.status = 'active'
          AND na.user_id <> v_proposal.proposed_user_id
          AND NOT EXISTS (
              SELECT 1 FROM public.network_administrator_cooptation_votes v
              WHERE v.proposal_id = v_proposal.id
                AND v.voter_user_id = na.user_id
          );

        IF v_pending_voters = '[]'::jsonb THEN
            CONTINUE;
        END IF;

        SELECT public.fn_network_notify_event(
            'network.cooptation_reminder',
            jsonb_build_object(
                'proposal_id', v_proposal.id,
                'proposed_user_id', v_proposal.proposed_user_id,
                'proposed_by', v_proposal.proposed_by,
                'proposed_at', v_proposal.proposed_at,
                'expires_at', v_proposal.expires_at,
                'reminder_kind', 'j25',
                'pending_voters', v_pending_voters
            )
        ) INTO v_outbox_id;

        INSERT INTO public.network_administrator_audit
            (user_id, event_type, actor_user_id, target_user_id, metadata)
        VALUES (
            v_proposal.proposed_user_id,
            'cooptation_reminder_sent',
            NULL,
            v_proposal.proposed_user_id,
            jsonb_build_object(
                'proposal_id', v_proposal.id,
                'reminder_kind', 'j25',
                'pending_voters_count', jsonb_array_length(v_pending_voters),
                'outbox_id', v_outbox_id
            )
        );

        v_j25_count := v_j25_count + 1;
    END LOOP;

    RETURN jsonb_build_object(
        'j14_sent', v_j14_count,
        'j25_sent', v_j25_count,
        'run_at', v_now
    );
END;
$$;


ALTER FUNCTION "public"."fn_cron_cooptation_send_reminders"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."fn_cron_cooptation_send_reminders"() IS 'D.7 — Cron quotidien : envoie rappels J+14 et J+25 aux admins n''ayant pas voté sur les propositions de cooptation ouvertes. Détection stricte : fenêtre 24h. Event unique network.cooptation_reminder avec payload->>''reminder_kind''.';



CREATE OR REPLACE FUNCTION "public"."fn_cron_notify_cross_library_digest"() RETURNS bigint
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'vault', 'extensions', 'pg_temp'
    AS $_$
DECLARE
    v_url     text;
    v_secret  text;
    v_req_id  bigint;
    v_week    record;
BEGIN
    -- URL de l'Edge Function cible
    v_url := regexp_replace(
        public.fn_internal_get_vault_secret('SUPABASE_URL'),
        '/+$', ''
    ) || '/functions/v1/notify-cross-library-digest';
    
    -- Secret pour authentifier le webhook côté Edge Function
    -- Le secret doit être créé dans le vault avec le nom 
    -- WEBHOOK_SECRET_NOTIFY_CROSS_LIBRARY_DIGEST avant activation du cron.
    v_secret := public.fn_internal_get_vault_secret('WEBHOOK_SECRET_NOTIFY_CROSS_LIBRARY_DIGEST');
    
    -- Semaine ISO précédente (pour le digest hebdo)
    SELECT * INTO v_week FROM public.fn_internal_previous_iso_week();
    
    -- HTTP POST vers l'Edge Function
    v_req_id := net.http_post(
        url := v_url,
        headers := jsonb_build_object(
            'Content-Type', 'application/json',
            'x-webhook-secret', v_secret
        ),
        body := jsonb_build_object(
            'source', 'pg_cron',
            'job', 'anarbib-notify-cross-library-digest-weekly',
            'scheduled_at', now(),
            'week_start', to_char(v_week.week_start, 'YYYY-MM-DD'),
            'week_end',   to_char(v_week.week_end,   'YYYY-MM-DD'),
            'tz', 'UTC'
        ),
        timeout_milliseconds := 60000
    );
    
    RETURN v_req_id;
END;
$_$;


ALTER FUNCTION "public"."fn_cron_notify_cross_library_digest"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."fn_cron_notify_cross_library_digest"() IS 'Trigger un net.http_post vers l''Edge Function notify-cross-library-digest. Appelée par le job pg_cron anarbib-notify-cross-library-digest-weekly chaque lundi à 8h30. L''Edge Function lira la table network_admin_cross_library_actions_log pour la semaine ISO précédente et enverra un digest mail aux coordenadores actifs de chaque biblio concernée, avec marqueur pour les actions déjà notifiées immédiatement (Q6). Paquet C.5c (11/05/2026).';



