CREATE OR REPLACE FUNCTION "public"."fn_cron_peb_detect_overdue"() RETURNS TABLE("processed_count" integer, "error_count" integer, "details" "jsonb")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_row record;
  v_processed integer := 0;
  v_errors integer := 0;
  v_errors_details jsonb := '[]'::jsonb;
  v_total int;
  v_settled int;
  v_target text;
begin
  -- ─── ALLER : PEB echus a basculer vers 'atrasado' ───────────────────────
  -- Eligibles : emprestado ou parcialmente_devolvido, due_date depassee.
  for v_row in
    select id, status_global, due_date
    from public.interlibrary_loans_v2
    where status_global in ('emprestado', 'parcialmente_devolvido')
      and due_date is not null
      and due_date < current_date
      and archived_at is null
  loop
    begin
      update public.interlibrary_loans_v2
      set status_global = 'atrasado',
          updated_at = timezone('utc', now())
      where id = v_row.id;
      v_processed := v_processed + 1;
    exception when others then
      v_errors := v_errors + 1;
      v_errors_details := v_errors_details || jsonb_build_object(
        'loan_id', v_row.id, 'direction', 'aller',
        'from', v_row.status_global, 'sqlstate', sqlstate, 'message', sqlerrm
      );
    end;
  end loop;

  -- ─── RETOUR : PEB 'atrasado' prolonges, a sortir du retard ──────────────
  -- Un PEB atrasado dont la due_date est repassee dans le futur (ou a NULL)
  -- a ete prolonge : on le sort du retard. Statut cible DEDUIT des
  -- exemplaires (option A) — meme comptage que fn_peb_consolidate_loan_status.
  for v_row in
    select id, due_date
    from public.interlibrary_loans_v2
    where status_global = 'atrasado'
      and (due_date is null or due_date >= current_date)
      and archived_at is null
  loop
    begin
      -- Comptage des exemplaires : combien au total, combien regles.
      --   regle = devolvido | perdido | danificado | cancelado
      select count(*),
             count(*) filter (where item_status in
               ('devolvido','perdido','danificado','cancelado'))
      into v_total, v_settled
      from public.interlibrary_loan_items_v2
      where interlibrary_loan_id = v_row.id;

      -- Statut de retour : si une partie est deja reglee -> partiel ;
      -- sinon -> emprestado. (Si tout etait regle le PEB ne serait pas
      -- 'atrasado' mais 'devolvido' : ce cas n'arrive pas ici.)
      if v_total > 0 and v_settled > 0 then
        v_target := 'parcialmente_devolvido';
      else
        v_target := 'emprestado';
      end if;

      update public.interlibrary_loans_v2
      set status_global = v_target,
          updated_at = timezone('utc', now())
      where id = v_row.id;
      v_processed := v_processed + 1;
    exception when others then
      v_errors := v_errors + 1;
      v_errors_details := v_errors_details || jsonb_build_object(
        'loan_id', v_row.id, 'direction', 'retour',
        'sqlstate', sqlstate, 'message', sqlerrm
      );
    end;
  end loop;

  processed_count := v_processed;
  error_count := v_errors;
  details := jsonb_build_object('run_at', timezone('utc', now()), 'errors', v_errors_details);
  return next;
end;
$$;


ALTER FUNCTION "public"."fn_cron_peb_detect_overdue"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_cron_reconcile_task_dispatch"("p_limit" integer DEFAULT 500) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_notif_failed integer := 0;
  v_notif_ok     integer := 0;
  v_inv_failed   integer := 0;
  v_inv_ok       integer := 0;
begin
  -- --- OUTBOX NOTIFICATIONS : echecs (non-2xx, status null, timeout) -> failed
  update public.painel_internal_task_notification_outbox o
     set dispatch_status = 'failed',
         last_error = left('HTTP ' || coalesce(r.status_code::text, '(sem status)')
                      || case when r.timed_out then ' [timeout]' else '' end
                      || ' :: ' || coalesce(nullif(btrim(r.content), ''), r.error_msg, ''), 500),
         reconciled_at = now(),
         updated_at = now()
    from net._http_response r
   where r.id = o.request_id
     and o.dispatch_status = 'sent'
     and o.request_id is not null
     and o.reconciled_at is null
     and (r.status_code is null or r.status_code < 200 or r.status_code >= 300);
  get diagnostics v_notif_failed = row_count;

  -- --- OUTBOX NOTIFICATIONS : 2xx confirmes -> estampille reconciled_at
  update public.painel_internal_task_notification_outbox o
     set reconciled_at = now(),
         updated_at = now()
    from net._http_response r
   where r.id = o.request_id
     and o.dispatch_status = 'sent'
     and o.request_id is not null
     and o.reconciled_at is null
     and r.status_code between 200 and 299;
  get diagnostics v_notif_ok = row_count;

  -- --- OUTBOX INVITATIONS : echecs -> failed, avec miroir sur la table invites
  with failed as (
    update public.painel_internal_task_invitation_outbox o
       set dispatch_status = 'failed',
           last_error = left('HTTP ' || coalesce(r.status_code::text, '(sem status)')
                        || case when r.timed_out then ' [timeout]' else '' end
                        || ' :: ' || coalesce(nullif(btrim(r.content), ''), r.error_msg, ''), 500),
           reconciled_at = now(),
           updated_at = now()
      from net._http_response r
     where r.id = o.request_id
       and o.dispatch_status = 'sent'
       and o.request_id is not null
       and o.reconciled_at is null
       and (r.status_code is null or r.status_code < 200 or r.status_code >= 300)
    returning o.invite_id, o.last_error
  ),
  mirror as (
    update public.painel_internal_task_invites i
       set invite_status = 'failed',
           last_error = failed.last_error,
           updated_at = now()
      from failed
     where i.id = failed.invite_id
       and i.invite_status = 'sent'
    returning 1
  )
  select count(*) into v_inv_failed from failed;

  -- --- OUTBOX INVITATIONS : 2xx confirmes -> estampille reconciled_at
  update public.painel_internal_task_invitation_outbox o
     set reconciled_at = now(),
         updated_at = now()
    from net._http_response r
   where r.id = o.request_id
     and o.dispatch_status = 'sent'
     and o.request_id is not null
     and o.reconciled_at is null
     and r.status_code between 200 and 299;
  get diagnostics v_inv_ok = row_count;

  return jsonb_build_object(
    'ok', true,
    'notif_failed', v_notif_failed,
    'notif_confirmed', v_notif_ok,
    'invite_failed', v_inv_failed,
    'invite_confirmed', v_inv_ok
  );
end;
$$;


ALTER FUNCTION "public"."fn_cron_reconcile_task_dispatch"("p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_cron_tasks_detect_stale_recurrence"() RETURNS TABLE("flagged_count" integer, "cleared_count" integer, "run_at" timestamp with time zone)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_flagged integer := 0;
  v_cleared integer := 0;
begin
  -- ─── POSE du drapeau ────────────────────────────────────────────────────
  -- Occurrence recurrente, non achevee, due_date depassee de plus de 7 jours,
  -- pas encore signalee.
  update public.painel_internal_tasks
  set recurrence_stale_flagged_at = timezone('utc', now())
  where recurrence_rule_id is not null
    and status in ('pendente', 'em_andamento')
    and due_date is not null
    and due_date < current_date - 7
    and recurrence_stale_flagged_at is null;
  get diagnostics v_flagged = row_count;

  -- ─── RETRAIT du drapeau ─────────────────────────────────────────────────
  -- Une tache signalee qui n'est plus en souffrance : achevee/annulee, ou
  -- due_date repoussee, ou plus rattachee a une serie. Retour a la normale.
  update public.painel_internal_tasks
  set recurrence_stale_flagged_at = null
  where recurrence_stale_flagged_at is not null
    and (
      recurrence_rule_id is null
      or status not in ('pendente', 'em_andamento')
      or due_date is null
      or due_date >= current_date - 7
    );
  get diagnostics v_cleared = row_count;

  flagged_count := v_flagged;
  cleared_count := v_cleared;
  run_at := timezone('utc', now());
  return next;
end;
$$;


ALTER FUNCTION "public"."fn_cron_tasks_detect_stale_recurrence"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_cron_team_inactive_cleanup"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_membership record;
  v_processed_warn30 integer := 0;
  v_processed_warn7 integer := 0;
  v_processed_completed integer := 0;
  v_errors integer := 0;
  v_audit_id uuid;
  v_results jsonb := '[]'::jsonb;
  v_already_warned boolean;
BEGIN
  -- Boucle sur les memberships staff actifs avec leur dernière activité
  FOR v_membership IN
    SELECT m.id, m.user_id, m.library_id, m.role, m.status, m.created_at,
           GREATEST(
             COALESCE(u.last_sign_in_at, m.created_at),
             m.created_at
           ) AS last_active_at
    FROM public.user_library_memberships m
    JOIN auth.users u ON u.id = m.user_id
    WHERE m.role IN ('librarian', 'coordenador')
      AND m.status = 'active'
    ORDER BY m.id
  LOOP
    BEGIN
      -- Calcul du nombre de jours d'inactivité
      DECLARE
        v_days_inactive integer;
      BEGIN
        v_days_inactive := EXTRACT(DAY FROM now() - v_membership.last_active_at)::integer;

        -- Cas 1 : 270 jours (9 mois) → passage en inactif
        IF v_days_inactive >= 270 THEN
          UPDATE public.user_library_memberships
          SET status = 'inactive', updated_at = now()
          WHERE id = v_membership.id;

          INSERT INTO public.library_membership_audit
            (library_id, target_user_id, actor_user_id,
             action, role, status_before, status_after, reason, metadata)
          VALUES
            (v_membership.library_id, v_membership.user_id, NULL,
             'inactive_auto', v_membership.role, 'active', 'inactive',
             format('Cron : %s dias sem conexão (>= 270)', v_days_inactive),
             jsonb_build_object(
               'cron_job', 'fn_cron_team_inactive_cleanup',
               'cron_run_at', now(),
               'days_inactive', v_days_inactive,
               'last_active_at', v_membership.last_active_at
             ))
          RETURNING id INTO v_audit_id;

          INSERT INTO public.team_notification_outbox (event, payload)
          VALUES (
            'team.inactive_auto',
            jsonb_build_object(
              'library_id', v_membership.library_id,
              'target_user_id', v_membership.user_id,
              'actor_user_id', NULL,
              'audit_id', v_audit_id,
              'role', v_membership.role
            )
          );

          v_processed_completed := v_processed_completed + 1;
          v_results := v_results || jsonb_build_object(
            'membership_id', v_membership.id,
            'action', 'inactive_auto',
            'days_inactive', v_days_inactive
          );

        -- Cas 2 : 263 jours → warning 7d (anti-doublon : pas déjà warned 7d)
        ELSIF v_days_inactive >= 263 THEN
          SELECT EXISTS (
            SELECT 1 FROM public.library_membership_audit
            WHERE target_user_id = v_membership.user_id
              AND library_id = v_membership.library_id
              AND action = 'inactive_warning_7d'
              AND created_at >= now() - interval '14 days'
          ) INTO v_already_warned;

          IF NOT v_already_warned THEN
            INSERT INTO public.library_membership_audit
              (library_id, target_user_id, actor_user_id,
               action, role, status_before, status_after, reason, metadata)
            VALUES
              (v_membership.library_id, v_membership.user_id, NULL,
               'inactive_warning_7d', v_membership.role, 'active', 'active',
               format('Cron : %s dias sem conexão (>= 263)', v_days_inactive),
               jsonb_build_object(
                 'cron_job', 'fn_cron_team_inactive_cleanup',
                 'cron_run_at', now(),
                 'days_inactive', v_days_inactive,
                 'last_active_at', v_membership.last_active_at,
                 'deadline', now() + interval '7 days'
               ))
            RETURNING id INTO v_audit_id;

            INSERT INTO public.team_notification_outbox (event, payload)
            VALUES (
              'team.inactive_warning_7d',
              jsonb_build_object(
                'library_id', v_membership.library_id,
                'target_user_id', v_membership.user_id,
                'actor_user_id', NULL,
                'audit_id', v_audit_id,
                'role', v_membership.role,
                'deadline', (now() + interval '7 days')::text
              )
            );

            v_processed_warn7 := v_processed_warn7 + 1;
            v_results := v_results || jsonb_build_object(
              'membership_id', v_membership.id,
              'action', 'inactive_warning_7d',
              'days_inactive', v_days_inactive
            );
          END IF;

        -- Cas 3 : 240 jours → warning 30d (anti-doublon : pas déjà warned 30d)
        ELSIF v_days_inactive >= 240 THEN
          SELECT EXISTS (
            SELECT 1 FROM public.library_membership_audit
            WHERE target_user_id = v_membership.user_id
              AND library_id = v_membership.library_id
              AND action = 'inactive_warning_30d'
              AND created_at >= now() - interval '60 days'
          ) INTO v_already_warned;

          IF NOT v_already_warned THEN
            INSERT INTO public.library_membership_audit
              (library_id, target_user_id, actor_user_id,
               action, role, status_before, status_after, reason, metadata)
            VALUES
              (v_membership.library_id, v_membership.user_id, NULL,
               'inactive_warning_30d', v_membership.role, 'active', 'active',
               format('Cron : %s dias sem conexão (>= 240)', v_days_inactive),
               jsonb_build_object(
                 'cron_job', 'fn_cron_team_inactive_cleanup',
                 'cron_run_at', now(),
                 'days_inactive', v_days_inactive,
                 'last_active_at', v_membership.last_active_at,
                 'deadline', now() + interval '30 days'
               ))
            RETURNING id INTO v_audit_id;

            INSERT INTO public.team_notification_outbox (event, payload)
            VALUES (
              'team.inactive_warning_30d',
              jsonb_build_object(
                'library_id', v_membership.library_id,
                'target_user_id', v_membership.user_id,
                'actor_user_id', NULL,
                'audit_id', v_audit_id,
                'role', v_membership.role,
                'deadline', (now() + interval '30 days')::text
              )
            );

            v_processed_warn30 := v_processed_warn30 + 1;
            v_results := v_results || jsonb_build_object(
              'membership_id', v_membership.id,
              'action', 'inactive_warning_30d',
              'days_inactive', v_days_inactive
            );
          END IF;
        END IF;
      END;

    EXCEPTION WHEN OTHERS THEN
      v_errors := v_errors + 1;
      v_results := v_results || jsonb_build_object(
        'membership_id', v_membership.id,
        'status', 'error',
        'sqlerrm', SQLERRM,
        'sqlstate', SQLSTATE
      );
    END;
  END LOOP;

  RETURN jsonb_build_object(
    'cron_job', 'fn_cron_team_inactive_cleanup',
    'run_at', now(),
    'processed_warn30', v_processed_warn30,
    'processed_warn7', v_processed_warn7,
    'processed_completed', v_processed_completed,
    'errors', v_errors,
    'results', v_results
  );
END;
$$;


ALTER FUNCTION "public"."fn_cron_team_inactive_cleanup"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."fn_cron_team_inactive_cleanup"() IS 'Lot 4 : pilote le cycle de vie inactivité des memberships staff. Quotidien. 3 seuils : 240j (warning 30d), 263j (warning 7d), 270j (passage inactif). Anti-doublons via library_membership_audit.';



CREATE OR REPLACE FUNCTION "public"."fn_cron_team_pending_removal_complete"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_membership record;
  v_processed integer := 0;
  v_errors integer := 0;
  v_audit_id uuid;
  v_actor_id uuid;
  v_results jsonb := '[]'::jsonb;
  v_lower_role text;
  v_lower_existing record;
BEGIN
  -- Boucle sur les memberships dont la carence a expiré.
  -- IMPORTANT : on cherche status='pending_removal' (posé par
  -- fn_team_request_remove_member), PAS 'active'.
  FOR v_membership IN
    SELECT m.id, m.user_id, m.library_id, m.role, m.status,
           m.pending_removal_until, m.pending_removal_requested_by
    FROM public.user_library_memberships m
    WHERE m.pending_removal_until IS NOT NULL
      AND m.pending_removal_until <= now()
      AND m.status = 'pending_removal'        -- ← CORRIGÉ : était 'active'
      AND m.role IN ('librarian', 'coordenador')
    ORDER BY m.pending_removal_until ASC
  LOOP
    BEGIN
      v_actor_id := v_membership.pending_removal_requested_by;

      -- 1. Clôturer le membership dont le retrait a été demandé
      UPDATE public.user_library_memberships
      SET status = 'removed',
          pending_removal_until = NULL,
          pending_removal_requested_by = NULL,
          updated_at = now()
      WHERE id = v_membership.id;

      -- 2. Audit de la clôture
      INSERT INTO public.library_membership_audit
        (library_id, target_user_id, actor_user_id,
         action, role, status_before, status_after, reason, metadata)
      VALUES
        (v_membership.library_id, v_membership.user_id, v_actor_id,
         'removal_completed', v_membership.role, 'pending_removal', 'removed',  -- ← CORRIGÉ : status_before était 'active'
         'Cron : prazo de 7 dias expirou sem anulação',
         jsonb_build_object(
           'cron_job', 'fn_cron_team_pending_removal_complete',
           'cron_run_at', now(),
           'pending_removal_until', v_membership.pending_removal_until
         ))
      RETURNING id INTO v_audit_id;

      -- 2.bis NOUVEAU (doctrine rôle exclusif) : rétrograder d'un cran.
      -- Le retrait d'un rôle staff n'exclut pas la personne : elle redescend
      -- au cran inférieur (coordenador -> librarian ; librarian -> reader).
      -- Réactiver le membership inférieur s'il existe (en 'removed' depuis
      -- la promotion), sinon le créer.
      IF v_membership.role = 'coordenador' THEN
        v_lower_role := 'librarian';
      ELSE
        v_lower_role := 'reader';
      END IF;

      SELECT * INTO v_lower_existing
      FROM public.user_library_memberships
      WHERE user_id = v_membership.user_id
        AND library_id = v_membership.library_id
        AND role = v_lower_role;

      IF FOUND THEN
        -- Réactiver seulement si pas déjà active (idempotence défensive)
        IF v_lower_existing.status <> 'active' THEN
          UPDATE public.user_library_memberships
          SET status = 'active',
              pending_removal_until = NULL,
              pending_removal_requested_by = NULL,
              updated_at = now()
          WHERE id = v_lower_existing.id;
        END IF;
      ELSE
        INSERT INTO public.user_library_memberships
          (user_id, library_id, role, status)
        VALUES
          (v_membership.user_id, v_membership.library_id, v_lower_role, 'active');
      END IF;

      -- 2.ter Audit de la rétrogradation (réactivation du cran inférieur)
      INSERT INTO public.library_membership_audit
        (library_id, target_user_id, actor_user_id,
         action, role, status_before, status_after, reason, metadata)
      VALUES
        (v_membership.library_id, v_membership.user_id, v_actor_id,
         CASE WHEN v_lower_role = 'librarian'
              THEN 'promoted_to_librarian'
              ELSE 'removal_completed' END,
         v_lower_role,
         COALESCE(v_lower_existing.status, NULL), 'active',
         'Rétrogradation d''un cran suite à retrait du rôle ' || v_membership.role,
         jsonb_build_object(
           'cron_job', 'fn_cron_team_pending_removal_complete',
           'demotion_from', v_membership.role,
           'demotion_to', v_lower_role,
           'removal_audit_id', v_audit_id
         ));

      -- 3. Outbox event team.removal_completed
      INSERT INTO public.team_notification_outbox (event, payload)
      VALUES (
        'team.removal_completed',
        jsonb_build_object(
          'library_id', v_membership.library_id,
          'target_user_id', v_membership.user_id,
          'actor_user_id', v_actor_id,
          'audit_id', v_audit_id,
          'role', v_membership.role,
          'demoted_to', v_lower_role
        )
      );

      v_processed := v_processed + 1;
      v_results := v_results || jsonb_build_object(
        'membership_id', v_membership.id,
        'user_id', v_membership.user_id,
        'library_id', v_membership.library_id,
        'role', v_membership.role,
        'demoted_to', v_lower_role,
        'status', 'completed'
      );

    EXCEPTION WHEN OTHERS THEN
      v_errors := v_errors + 1;
      v_results := v_results || jsonb_build_object(
        'membership_id', v_membership.id,
        'status', 'error',
        'sqlerrm', SQLERRM,
        'sqlstate', SQLSTATE
      );
    END;
  END LOOP;

  RETURN jsonb_build_object(
    'cron_job', 'fn_cron_team_pending_removal_complete',
    'run_at', now(),
    'processed', v_processed,
    'errors', v_errors,
    'results', v_results
  );
END;
$$;


ALTER FUNCTION "public"."fn_cron_team_pending_removal_complete"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."fn_cron_team_pending_removal_complete"() IS 'Lot 4 : finalise les retiradas dont la carence de 7 jours a expiré. Appelé horairement par pg_cron. Insère library_membership_audit + team_notification_outbox.';



