CREATE OR REPLACE FUNCTION "public"."fn_delete_all_my_history"("p_library_id" "uuid", "p_domain" "text") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_uid   uuid := auth.uid();
  v_count integer;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'not_authenticated' USING HINT = 'history.error.not_authenticated';
  END IF;

  IF p_domain = 'loans' THEN
    DELETE FROM public.emprestimos_v2
     WHERE user_id = v_uid
       AND library_id = p_library_id
       AND status_global = 'encerrado';
    GET DIAGNOSTICS v_count = ROW_COUNT;

  ELSIF p_domain = 'reservations' THEN
    DELETE FROM public.reserva_linhas_v2 rl
      USING public.reservas_v2 r
     WHERE rl.reserva_id = r.id
       AND r.user_id = v_uid
       AND r.library_id = p_library_id
       AND rl.item_status IN ('cancelada_leitor','cancelada_biblioteca','convertida_em_emprestimo','expirada','liberada_para_circulacao');
    GET DIAGNOSTICS v_count = ROW_COUNT;

    -- Nettoyage racines orphelines de cette lectrice/biblio
    DELETE FROM public.reservas_v2 r
     WHERE r.user_id = v_uid
       AND r.library_id = p_library_id
       AND NOT EXISTS (SELECT 1 FROM public.reserva_linhas_v2 rl WHERE rl.reserva_id = r.id);

  ELSIF p_domain = 'consultations' THEN
    DELETE FROM public.consulta_linhas_v2 cl
      USING public.consultas_locais_v2 c
     WHERE cl.consulta_id = c.id
       AND c.user_id = v_uid
       AND c.library_id = p_library_id
       AND cl.item_status IN ('consultada','cancelada_leitor','cancelada_biblioteca','expirada');
    GET DIAGNOSTICS v_count = ROW_COUNT;

    DELETE FROM public.consultas_locais_v2 c
     WHERE c.user_id = v_uid
       AND c.library_id = p_library_id
       AND NOT EXISTS (SELECT 1 FROM public.consulta_linhas_v2 cl WHERE cl.consulta_id = c.id);

  ELSE
    RAISE EXCEPTION 'invalid_domain' USING HINT = 'history.error.invalid_domain';
  END IF;

  RETURN v_count;
END;
$$;


ALTER FUNCTION "public"."fn_delete_all_my_history"("p_library_id" "uuid", "p_domain" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_delete_history_item"("p_domain" "text", "p_record_id" bigint) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_uid        uuid := auth.uid();
  v_reserva_id  bigint;
  v_consulta_id bigint;
  v_count      integer;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'not_authenticated' USING HINT = 'history.error.not_authenticated';
  END IF;

  IF p_domain = 'loans' THEN
    -- DELETE direct sur la racine ; cascade sur emprestimo_itens_v2 + loan_midpoint_message_log
    DELETE FROM public.emprestimos_v2
     WHERE id = p_record_id
       AND user_id = v_uid
       AND status_global = 'encerrado';
    GET DIAGNOSTICS v_count = ROW_COUNT;

  ELSIF p_domain = 'reservations' THEN
    -- Vérifier ownership + état terminal, capturer la racine
    SELECT rl.reserva_id INTO v_reserva_id
      FROM public.reserva_linhas_v2 rl
      JOIN public.reservas_v2 r ON r.id = rl.reserva_id
     WHERE rl.id = p_record_id
       AND r.user_id = v_uid
       AND rl.item_status IN ('cancelada_leitor','cancelada_biblioteca','convertida_em_emprestimo','expirada','liberada_para_circulacao');

    IF v_reserva_id IS NULL THEN
      RAISE EXCEPTION 'item_not_found_or_not_terminal' USING HINT = 'history.error.not_found_or_active';
    END IF;

    DELETE FROM public.reserva_linhas_v2 WHERE id = p_record_id;  -- cascade workflow
    GET DIAGNOSTICS v_count = ROW_COUNT;

    -- Nettoyage racine orpheline (option ii)
    IF NOT EXISTS (SELECT 1 FROM public.reserva_linhas_v2 WHERE reserva_id = v_reserva_id) THEN
      DELETE FROM public.reservas_v2 WHERE id = v_reserva_id;
    END IF;

  ELSIF p_domain = 'consultations' THEN
    SELECT cl.consulta_id INTO v_consulta_id
      FROM public.consulta_linhas_v2 cl
      JOIN public.consultas_locais_v2 c ON c.id = cl.consulta_id
     WHERE cl.id = p_record_id
       AND c.user_id = v_uid
       AND cl.item_status IN ('consultada','cancelada_leitor','cancelada_biblioteca','expirada');

    IF v_consulta_id IS NULL THEN
      RAISE EXCEPTION 'item_not_found_or_not_terminal' USING HINT = 'history.error.not_found_or_active';
    END IF;

    DELETE FROM public.consulta_linhas_v2 WHERE id = p_record_id;  -- cascade workflow
    GET DIAGNOSTICS v_count = ROW_COUNT;

    IF NOT EXISTS (SELECT 1 FROM public.consulta_linhas_v2 WHERE consulta_id = v_consulta_id) THEN
      DELETE FROM public.consultas_locais_v2 WHERE id = v_consulta_id;
    END IF;

  ELSE
    RAISE EXCEPTION 'invalid_domain' USING HINT = 'history.error.invalid_domain';
  END IF;

  IF v_count = 0 THEN
    RAISE EXCEPTION 'item_not_found_or_not_terminal' USING HINT = 'history.error.not_found_or_active';
  END IF;
END;
$$;


ALTER FUNCTION "public"."fn_delete_history_item"("p_domain" "text", "p_record_id" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_delete_my_account"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_user_id uuid := auth.uid();
  v_open_loans int;
  v_active_reservations int;
  v_result jsonb;
BEGIN
  IF v_user_id IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'error', 'Nenhum usuário autenticado.');
  END IF;

  -- Check for open loans (items with status 'aberto')
  SELECT count(*) INTO v_open_loans
  FROM emprestimos_v2 e
  JOIN emprestimo_itens_v2 ei ON ei.emprestimo_id = e.id
  WHERE e.user_id = v_user_id AND ei.item_status = 'aberto';

  IF v_open_loans > 0 THEN
    RETURN jsonb_build_object(
      'ok', false,
      'error', 'Você tem ' || v_open_loans || ' empréstimo(s) em aberto. Devolva todos os itens antes de excluir sua conta.',
      'open_loans', v_open_loans
    );
  END IF;

  -- Cancel active reservations
  SELECT count(*) INTO v_active_reservations
  FROM reservas_v2 WHERE user_id = v_user_id AND status_global NOT IN ('cancelada', 'concluida', 'expirada');

  UPDATE reservas_v2 
  SET status_global = 'cancelada'
  WHERE user_id = v_user_id AND status_global NOT IN ('cancelada', 'concluida', 'expirada');

  -- Remove task invites
  DELETE FROM painel_internal_task_invites WHERE created_by = v_user_id;

  -- Nullify references in tasks (don't delete tasks, just remove user refs)
  UPDATE painel_internal_tasks SET owner_user_id = NULL WHERE owner_user_id = v_user_id;
  UPDATE painel_internal_tasks SET created_by = NULL WHERE created_by = v_user_id;
  UPDATE painel_internal_tasks SET updated_by = NULL WHERE updated_by = v_user_id;

  -- Nullify references in reservation workflow
  UPDATE reserva_item_workflow_v2 SET updated_by = NULL WHERE updated_by = v_user_id;

  -- Nullify references in loan items
  UPDATE emprestimo_itens_v2 SET return_scheduled_by = NULL WHERE return_scheduled_by = v_user_id;

  -- Delete loan midpoint messages
  DELETE FROM loan_midpoint_message_log WHERE user_id = v_user_id;

  -- Delete memberships
  DELETE FROM user_library_memberships WHERE user_id = v_user_id;

  -- Delete profile
  DELETE FROM profiles WHERE id = v_user_id;

  -- Delete the auth user (requires SECURITY DEFINER + service role)
  DELETE FROM auth.users WHERE id = v_user_id;

  RETURN jsonb_build_object(
    'ok', true,
    'cancelled_reservations', v_active_reservations,
    'message', 'Conta excluída com sucesso.'
  );
END;
$$;


ALTER FUNCTION "public"."fn_delete_my_account"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."fn_delete_my_account"() IS 'Allows authenticated users to permanently delete their own account. Blocks if open loans exist. Cancels active reservations. Removes profile, memberships and auth record.';



CREATE OR REPLACE FUNCTION "public"."fn_detect_no_show_reservations"() RETURNS TABLE("processed_count" integer, "error_count" integer, "details" "jsonb")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_row record;
  v_processed integer := 0;
  v_errors integer := 0;
  v_errors_details jsonb := '[]'::jsonb;
BEGIN
  -- Itérer sur les pickups dépassés
  -- (stages éligibles : pronta_para_retirada, retirada_agendada, re-retirada_agendada)
  FOR v_row IN
    SELECT
      riw.id,
      riw.reserva_id,
      riw.line_no,
      riw.workflow_stage,
      riw.pickup_scheduled_for,
      r.library_id,
      lnp.reservation_no_show_timeout_hours AS timeout_hours
    FROM public.reserva_item_workflow_v2 riw
    JOIN public.reservas_v2 r ON r.id = riw.reserva_id
    JOIN public.library_notification_policies lnp ON lnp.library_id = r.library_id
    WHERE riw.workflow_stage IN ('pronta_para_retirada', 'retirada_agendada', 're-retirada_agendada')
      AND riw.pickup_scheduled_for IS NOT NULL
      AND riw.pickup_scheduled_for < now() - make_interval(hours => lnp.reservation_no_show_timeout_hours)
  LOOP
    BEGIN
      -- Sanity check matrice
      IF NOT public.fn_check_workflow_transition(v_row.workflow_stage, 'retirada_no_show', 'system') THEN
        RAISE EXCEPTION 'helper_refused_transition';
      END IF;

      UPDATE public.reserva_item_workflow_v2
      SET workflow_stage = 'retirada_no_show',
          workflow_note = format(
            'No-show automatique par cron (pickup prévu: %s, timeout: %sh)',
            v_row.pickup_scheduled_for::text, v_row.timeout_hours
          ),
          updated_at = now()
      WHERE id = v_row.id;

      -- Note : le trigger trg_auto_liberate_after_no_show déclenchera ensuite
      -- automatiquement la bascule vers liberada_para_circulacao
      -- avec final_reason = 'no_show'.

      v_processed := v_processed + 1;
    EXCEPTION
      WHEN OTHERS THEN
        v_errors := v_errors + 1;
        v_errors_details := v_errors_details || jsonb_build_object(
          'reserva_id', v_row.reserva_id,
          'line_no', v_row.line_no,
          'sqlstate', SQLSTATE,
          'message', SQLERRM
        );
    END;
  END LOOP;

  processed_count := v_processed;
  error_count := v_errors;
  details := jsonb_build_object(
    'run_at', now(),
    'errors', v_errors_details
  );
  RETURN NEXT;
END;
$$;


ALTER FUNCTION "public"."fn_detect_no_show_reservations"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."fn_detect_no_show_reservations"() IS 'Job cron : marque retirada_no_show les réservations en stage pronta_para_retirada/retirada_agendada/re-retirada_agendada dont pickup_scheduled_for + reservation_no_show_timeout_hours est dépassé. Le trigger trg_auto_liberate_after_no_show cascade ensuite vers liberada_para_circulacao avec final_reason=no_show. Retourne (processed_count, error_count, details jsonb).';



CREATE OR REPLACE FUNCTION "public"."fn_dispatch_notify_event"("p_event" "text", "p_record_id" bigint, "p_extra" "jsonb" DEFAULT '{}'::"jsonb") RETURNS bigint
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'net', 'vault'
    AS $_$
DECLARE
  v_url text;
  v_secret text;
  v_request_id bigint;
BEGIN
  SELECT ds.decrypted_secret INTO v_url
  FROM vault.decrypted_secrets ds
  WHERE ds.name = 'SUPABASE_URL'
  ORDER BY ds.created_at DESC LIMIT 1;

  SELECT ds.decrypted_secret INTO v_secret
  FROM vault.decrypted_secrets ds
  WHERE ds.name = 'WEBHOOK_SECRET_NOTIFY_EVENT'
  ORDER BY ds.created_at DESC LIMIT 1;

  IF coalesce(v_url, '') = '' THEN
    RAISE WARNING 'Secret SUPABASE_URL absent — notification % ignorée', p_event;
    RETURN NULL;
  END IF;

  IF coalesce(v_secret, '') = '' THEN
    RAISE WARNING 'Secret WEBHOOK_SECRET_NOTIFY_EVENT absent — notification % ignorée', p_event;
    RETURN NULL;
  END IF;

  v_request_id := net.http_post(
    url := regexp_replace(v_url, '/+$', '') || '/functions/v1/notify-event',
    headers := jsonb_build_object(
      'Content-Type', 'application/json',
      'x-webhook-secret', v_secret
    ),
    body := jsonb_build_object(
      'event', p_event,
      'record_id', p_record_id
    ) || p_extra,
    timeout_milliseconds := 30000
  );

  RETURN v_request_id;
EXCEPTION
  WHEN OTHERS THEN
    RAISE WARNING 'fn_dispatch_notify_event(%, %): %', p_event, p_record_id, SQLERRM;
    RETURN NULL;
END;
$_$;


ALTER FUNCTION "public"."fn_dispatch_notify_event"("p_event" "text", "p_record_id" bigint, "p_extra" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_dispatch_rgpd_warning"("p_notification_id" bigint, "p_event" "text") RETURNS bigint
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'net', 'vault'
    AS $_$
DECLARE
  v_url text;
  v_secret text;
  v_request_id bigint;
BEGIN
  -- Lookup secrets vault (même pattern que fn_dispatch_notify_event)
  SELECT ds.decrypted_secret INTO v_url
  FROM vault.decrypted_secrets ds
  WHERE ds.name = 'SUPABASE_URL'
  ORDER BY ds.created_at DESC
  LIMIT 1;

  SELECT ds.decrypted_secret INTO v_secret
  FROM vault.decrypted_secrets ds
  WHERE ds.name = 'WEBHOOK_SECRET_NOTIFY_EVENT'
  ORDER BY ds.created_at DESC
  LIMIT 1;

  IF COALESCE(v_url, '') = '' THEN
    RAISE WARNING 'Secret SUPABASE_URL absent — notification RGPD % ignorée', p_event;
    RETURN NULL;
  END IF;

  IF COALESCE(v_secret, '') = '' THEN
    RAISE WARNING 'Secret WEBHOOK_SECRET_NOTIFY_EVENT absent — notification RGPD % ignorée', p_event;
    RETURN NULL;
  END IF;

  -- Dispatch vers l'EF notify-event.
  -- record_id = id de la ligne user_notifications créée juste avant ;
  -- l'EF handler (phase 2) lira cette ligne pour reconstruire le contexte
  -- (user_id, library_id, category) et construire le mail.
  v_request_id := net.http_post(
    url := regexp_replace(v_url, '/+$', '') || '/functions/v1/notify-event',
    headers := jsonb_build_object(
      'Content-Type', 'application/json',
      'x-webhook-secret', v_secret
    ),
    body := jsonb_build_object(
      'event', p_event,
      'record_id', p_notification_id
    ),
    timeout_milliseconds := 30000
  );

  RETURN v_request_id;
EXCEPTION
  WHEN OTHERS THEN
    -- Pattern fail-soft identique à fn_dispatch_notify_event :
    -- on logge mais on ne fait pas planter le caller (qui doit pouvoir
    -- continuer ses INSERT in-app pour les autres lectrices).
    RAISE WARNING 'fn_dispatch_rgpd_warning(%, %): %', p_notification_id, p_event, SQLERRM;
    RETURN NULL;
END;
$_$;


ALTER FUNCTION "public"."fn_dispatch_rgpd_warning"("p_notification_id" bigint, "p_event" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."fn_dispatch_rgpd_warning"("p_notification_id" bigint, "p_event" "text") IS 'Spec §7.1 (31/05/2026). Wrapper net.http_post vers notify-event pour les préavis RGPD de purge. Pattern identique à fn_dispatch_circulation_notify_event. record_id = user_notifications.id (lookup côté EF pour reconstruire le contexte). Phase 1/2 : SQL prêt, handler EF côté _shared/domain/rgpd.ts à créer en phase 2.';



CREATE OR REPLACE FUNCTION "public"."fn_enforce_circulation_limit"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_mode  text;
  v_max   integer;
  v_count integer;
BEGIN
  IF NEW.user_id IS NULL OR NEW.library_id IS NULL THEN
    RETURN NEW;
  END IF;

  v_mode := CASE TG_TABLE_NAME
              WHEN 'emprestimos_v2'     THEN 'loan'
              WHEN 'reservas_v2'        THEN 'reservation'
              WHEN 'consultas_locais_v2' THEN 'local_consultation'
            END;
  IF v_mode IS NULL THEN
    RETURN NEW;
  END IF;

  v_max := public.fn_circulation_concurrent_max(NEW.library_id, v_mode);
  IF v_max IS NULL THEN
    RETURN NEW;  -- aucun plafond configuré = illimité
  END IF;

  IF TG_TABLE_NAME = 'emprestimos_v2' THEN
    SELECT count(*) INTO v_count FROM public.emprestimos_v2
     WHERE user_id = NEW.user_id AND library_id = NEW.library_id
       AND status_global IN ('aberto', 'parcialmente_devolvido')
       AND archived_at IS NULL;
  ELSIF TG_TABLE_NAME = 'reservas_v2' THEN
    SELECT count(*) INTO v_count FROM public.reservas_v2
     WHERE user_id = NEW.user_id AND library_id = NEW.library_id
       AND status_global IN ('ativa', 'parcialmente_encerrada')
       AND archived_at IS NULL;
  ELSE
    SELECT count(*) INTO v_count FROM public.consultas_locais_v2
     WHERE user_id = NEW.user_id AND library_id = NEW.library_id
       AND status_global IN ('ativa', 'parcialmente_encerrada')
       AND archived_at IS NULL;
  END IF;

  IF v_count >= v_max THEN
    RAISE EXCEPTION 'Limite de circulação simultânea atingido nesta biblioteca.'
      USING errcode = 'P0001', hint = 'error.circulation.limit_reached';
  END IF;

  RETURN NEW;
END $$;


ALTER FUNCTION "public"."fn_enforce_circulation_limit"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_enforce_local_reader_identity_uniqueness"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_model text;
BEGIN
  -- Pas d'identité, ou statut « mort » (départ définitif) : identité libre,
  -- rien à vérifier (CARD-LOCAL-6).
  IF NEW.local_reader_number IS NULL
     OR NEW.status IN ('removed', 'terminated') THEN
    RETURN NEW;
  END IF;

  -- Modèle d'identité de la biblio : l'unicité ne s'applique qu'aux modèles
  -- NUMÉRIQUES ; levée en mode 'name' (homonymes) et 'none' (CARD-LOCAL-UNIQ).
  SELECT l.reader_identity_model INTO v_model
    FROM public.libraries l
   WHERE l.id = NEW.library_id;

  IF v_model IS DISTINCT FROM 'free_number'
     AND v_model IS DISTINCT FROM 'sequenced_number' THEN
    RETURN NEW;
  END IF;

  -- Collision : même identité, même biblio, sur une appartenance VIVANTE,
  -- autre que la ligne courante.
  IF EXISTS (
    SELECT 1
      FROM public.user_library_memberships m
     WHERE m.library_id = NEW.library_id
       AND m.local_reader_number = NEW.local_reader_number
       AND m.status NOT IN ('removed', 'terminated')
       AND m.id <> NEW.id
  ) THEN
    RAISE EXCEPTION 'Identité lecteur·rice déjà attribuée dans cette bibliothèque'
      USING ERRCODE = 'unique_violation',
            HINT    = 'reader_identity_already_taken';
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."fn_enforce_local_reader_identity_uniqueness"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."fn_enforce_local_reader_identity_uniqueness"() IS 'Unicité conditionnelle de local_reader_number (CARD-LOCAL-UNIQ/§27). Remplace l''index ux_ulm_local_reader_number : impose l''unicité par biblio uniquement pour les modèles numériques et les statuts vivants (≠ removed/terminated). Lot 0, 11/06/2026.';



CREATE OR REPLACE FUNCTION "public"."fn_enforce_membership_circulation_gate"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_block text;
BEGIN
  v_block := public.fn_membership_can_engage_circulation(NEW.user_id, NEW.library_id);

  IF v_block = 'no_active_membership' THEN
    RAISE EXCEPTION 'Este(a) leitor(a) não é membro ativo desta biblioteca.'
      USING errcode = 'P0001', hint = 'error.membership.not_active';
  ELSIF v_block = 'restricted' THEN
    RAISE EXCEPTION 'Este(a) leitor(a) está com restrição nesta biblioteca.'
      USING errcode = 'P0001', hint = 'error.membership.restricted';
  ELSIF v_block = 'dues' THEN
    -- Filet : les RPC lèvent déjà la cotisation en 1er avec un message détaillé.
    RAISE EXCEPTION 'Contribuição obrigatória não está em dia para este(a) leitor(a).'
      USING errcode = 'P0001', hint = 'error.membership.dues';
  END IF;

  RETURN NEW;
END $$;


ALTER FUNCTION "public"."fn_enforce_membership_circulation_gate"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_enqueue_document_permission_request_notification"("p_request_id" "uuid", "p_event_type" "text", "p_event_key" "text" DEFAULT NULL::"text", "p_triggered_by_user_id" "uuid" DEFAULT NULL::"uuid") RETURNS bigint
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'vault', 'extensions', 'pg_temp'
    AS $_$
declare
  v_url_base text;
  v_url text;
  v_secret text;
  v_effective_key text;
  v_queue_row_id bigint;
  v_pg_request_id bigint;
begin
  if p_request_id is null then
    raise exception 'Solicitação interbibliotecas ausente.'
      using errcode = '23514';
  end if;

  if coalesce(btrim(p_event_type), '') not in (
    'document_permission_request_created',
    'document_permission_request_accepted',
    'document_permission_request_refused'
  ) then
    raise exception 'Tipo de evento inválido para notificação.'
      using errcode = '23514';
  end if;

  if not exists (
    select 1
    from public.document_permission_requests dpr
    where dpr.id = p_request_id
  ) then
    raise exception 'Solicitação interbibliotecas não encontrada para notificação.'
      using errcode = 'P0002';
  end if;

  v_effective_key := nullif(btrim(coalesce(p_event_key, '')), '');
  if v_effective_key is null then
    v_effective_key := p_event_type;
  end if;

  insert into public.document_permission_request_notification_events (
    request_id,
    event_type,
    event_key,
    status_snapshot,
    response_note_snapshot,
    triggered_by_user_id
  )
  select
    dpr.id,
    p_event_type,
    v_effective_key,
    dpr.status,
    dpr.response_note,
    p_triggered_by_user_id
  from public.document_permission_requests dpr
  where dpr.id = p_request_id
  on conflict (request_id, event_key) do nothing
  returning id into v_queue_row_id;

  if v_queue_row_id is null then
    return null;
  end if;

  select ds.decrypted_secret
    into v_url_base
  from vault.decrypted_secrets ds
  where ds.name = 'SUPABASE_URL'
  order by ds.created_at desc
  limit 1;

  if coalesce(v_url_base, '') = '' then
    raise exception 'Secret SUPABASE_URL introuvable dans vault.decrypted_secrets.';
  end if;

  select ds.decrypted_secret
    into v_secret
  from vault.decrypted_secrets ds
  where ds.name = 'WEBHOOK_SECRET_NOTIFY_DOCUMENT_PERMISSION_REQUEST'
  order by ds.created_at desc
  limit 1;

  if coalesce(v_secret, '') = '' then
    raise exception 'Secret WEBHOOK_SECRET_NOTIFY_DOCUMENT_PERMISSION_REQUEST introuvable dans vault.decrypted_secrets.';
  end if;

  v_url := regexp_replace(v_url_base, '/+$', '') || '/functions/v1/notify-document-permission-request';

  v_pg_request_id := net.http_post(
    url := v_url,
    headers := jsonb_build_object(
      'Content-Type', 'application/json',
      'x-webhook-secret', v_secret
    ),
    body := jsonb_build_object(
      'request_id', p_request_id,
      'event_type', p_event_type
    ),
    timeout_milliseconds := 60000
  );

  update public.document_permission_request_notification_events
     set pgnet_request_id = v_pg_request_id
   where id = v_queue_row_id;

  return v_pg_request_id;
end;
$_$;


ALTER FUNCTION "public"."fn_enqueue_document_permission_request_notification"("p_request_id" "uuid", "p_event_type" "text", "p_event_key" "text", "p_triggered_by_user_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."fn_enqueue_document_permission_request_notification"("p_request_id" "uuid", "p_event_type" "text", "p_event_key" "text", "p_triggered_by_user_id" "uuid") IS 'Enfile un événement e-mail pour document_permission_requests et déclenche la Edge Function notify-document-permission-request via pg_net.';



CREATE OR REPLACE FUNCTION "public"."fn_enqueue_emprestimo_interbibliotecas_notification"("p_loan_id" bigint, "p_event_type" "text", "p_event_key" "text" DEFAULT NULL::"text", "p_triggered_by_user_id" "uuid" DEFAULT "auth"."uid"()) RETURNS bigint
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_event_id bigint;
  v_status_snapshot text;
  v_event_key text;
begin
  if p_loan_id is null then
    raise exception 'loan_id ausente.';
  end if;

  if nullif(trim(coalesce(p_event_type, '')), '') is null then
    raise exception 'event_type ausente.';
  end if;

  select h.status_global
    into v_status_snapshot
  from public.interlibrary_loans_v2 h
  where h.id = p_loan_id;

  if v_status_snapshot is null then
    raise exception 'Empréstimo interbibliotecas % não encontrado.', p_loan_id;
  end if;

  v_event_key := coalesce(
    nullif(trim(coalesce(p_event_key, '')), ''),
    trim(p_event_type)
  );

  insert into public.interlibrary_loan_notification_events (
    interlibrary_loan_id,
    event_type,
    event_key,
    status_snapshot,
    payload_snapshot,
    triggered_by_user_id,
    created_at
  )
  values (
    p_loan_id,
    trim(p_event_type),
    v_event_key,
    v_status_snapshot,
    jsonb_build_object(
      'loan_id', p_loan_id,
      'event_type', trim(p_event_type),
      'status_global', v_status_snapshot
    ),
    p_triggered_by_user_id,
    timezone('utc', now())
  )
  on conflict (interlibrary_loan_id, event_key) do nothing
  returning id into v_event_id;

  if v_event_id is null then
    select e.id
      into v_event_id
    from public.interlibrary_loan_notification_events e
    where e.interlibrary_loan_id = p_loan_id
      and e.event_key = v_event_key
    limit 1;
  end if;

  return v_event_id;
end;
$$;


ALTER FUNCTION "public"."fn_enqueue_emprestimo_interbibliotecas_notification"("p_loan_id" bigint, "p_event_type" "text", "p_event_key" "text", "p_triggered_by_user_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_enqueue_library_request_notification"("p_request_id" "uuid", "p_event_type" "text", "p_event_key" "text" DEFAULT NULL::"text", "p_triggered_by_user_id" "uuid" DEFAULT "auth"."uid"()) RETURNS bigint
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions', 'vault'
    AS $$
declare
  v_secret text;
  v_effective_key text;
  v_queue_row_id bigint;
  v_pg_request_id bigint;
  v_url text := 'https://uflwmikiyjfnikiphtcp.supabase.co/functions/v1/notify-library-request';
begin
  if p_request_id is null then
    raise exception 'request_id ausente para notificação de solicitação.'
      using errcode = '23514';
  end if;

  if p_event_type not in (
    'library_request_created',
    'library_request_in_analysis',
    'library_request_more_info',
    'library_request_approved',
    'library_request_refused'
  ) then
    raise exception 'Tipo de evento inválido para solicitação institucional: %', p_event_type
      using errcode = '23514';
  end if;

  if not exists (
    select 1
    from public.library_requests lr
    where lr.id = p_request_id
  ) then
    raise exception 'Solicitação institucional não encontrada para notificação.'
      using errcode = 'P0002';
  end if;

  v_effective_key := nullif(btrim(coalesce(p_event_key, '')), '');
  if v_effective_key is null then
    v_effective_key := p_event_type;
  end if;

  insert into public.library_request_notification_events (
    request_id,
    event_type,
    event_key,
    request_status_snapshot,
    review_notes_snapshot,
    triggered_by_user_id
  )
  select
    lr.id,
    p_event_type,
    v_effective_key,
    lr.request_status,
    lr.review_notes,
    p_triggered_by_user_id
  from public.library_requests lr
  where lr.id = p_request_id
  on conflict (request_id, event_key) do nothing
  returning id into v_queue_row_id;

  if v_queue_row_id is null then
    return null;
  end if;

  select ds.decrypted_secret
    into v_secret
  from vault.decrypted_secrets ds
  where ds.name = 'WEBHOOK_SECRET_NOTIFY_LIBRARY_REQUEST'
  order by ds.created_at desc
  limit 1;

  if coalesce(v_secret, '') = '' then
    raise exception 'Secret WEBHOOK_SECRET_NOTIFY_LIBRARY_REQUEST introuvable dans vault.decrypted_secrets.';
  end if;

  v_pg_request_id := net.http_post(
    url := v_url,
    headers := jsonb_build_object(
      'Content-Type', 'application/json',
      'x-webhook-secret', v_secret
    ),
    body := jsonb_build_object(
      'request_id', p_request_id,
      'event_type', p_event_type
    ),
    timeout_milliseconds := 60000
  );

  update public.library_request_notification_events
     set pgnet_request_id = v_pg_request_id
   where id = v_queue_row_id;

  return v_pg_request_id;
end;
$$;


ALTER FUNCTION "public"."fn_enqueue_library_request_notification"("p_request_id" "uuid", "p_event_type" "text", "p_event_key" "text", "p_triggered_by_user_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."fn_enqueue_library_request_notification"("p_request_id" "uuid", "p_event_type" "text", "p_event_key" "text", "p_triggered_by_user_id" "uuid") IS 'Enfile un événement e-mail pour une sollicitation institutionnelle et déclenche la Edge Function notify-library-request via pg_net.';



CREATE OR REPLACE FUNCTION "public"."fn_ensure_current_user_profile"() RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'auth', 'pg_temp'
    AS $$
declare
  v_uid uuid := auth.uid();
begin
  if v_uid is null then
    return false;
  end if;

  insert into public.profiles (id, is_restricted, must_change_password)
  values (v_uid, false, false)
  on conflict (id) do nothing;

  return true;
end;
$$;


ALTER FUNCTION "public"."fn_ensure_current_user_profile"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_ensure_library_theme"("p_library_id" "uuid") RETURNS TABLE("out_library_slug" "text", "out_theme_slug" "text", "out_manifest_path" "text", "out_is_active" boolean, "out_created" boolean)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_slug text;
  v_name text;
  v_existing public.library_themes%ROWTYPE;
  v_created boolean := false;
BEGIN
  IF NOT user_can_engage_library(p_library_id) THEN
    RAISE EXCEPTION 'not authorized for library %', p_library_id
      USING ERRCODE = '42501';
  END IF;

  SELECT l.slug, COALESCE(l.short_name, l.name)
    INTO v_slug, v_name
  FROM public.libraries l
  WHERE l.id = p_library_id;

  IF v_slug IS NULL THEN
    RAISE EXCEPTION 'library % not found or has no slug', p_library_id
      USING ERRCODE = 'P0002';
  END IF;

  SELECT * INTO v_existing
  FROM public.library_themes lt
  WHERE lt.library_slug = v_slug
  LIMIT 1;

  IF v_existing.id IS NULL THEN
    INSERT INTO public.library_themes
      (library_slug, library_name, theme_slug, manifest_path, is_active)
    VALUES
      (v_slug, v_name, v_slug, 'themes/' || v_slug || '/manifest.json', true);
    v_created := true;
  ELSE
    UPDATE public.library_themes lt
       SET library_name = v_name,
           updated_at = now()
     WHERE lt.id = v_existing.id
       AND COALESCE(lt.library_name, '') <> v_name;
  END IF;

  RETURN QUERY
    SELECT lt.library_slug, lt.theme_slug, lt.manifest_path, lt.is_active, v_created
    FROM public.library_themes lt
    WHERE lt.library_slug = v_slug;
END;
$$;


ALTER FUNCTION "public"."fn_ensure_library_theme"("p_library_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_exchange_save_followup"("p_request_id" "uuid", "p_followup_patch" "jsonb") RETURNS "public"."document_permission_requests"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_row public.document_permission_requests;
  v_ref jsonb;
  v_current_followup jsonb;
  v_next_followup jsonb;
BEGIN
  IF p_request_id IS NULL THEN
    RAISE EXCEPTION 'fn_exchange_save_followup: identifiant de proposition manquant.';
  END IF;

  -- Lecture de la ligne. La RLS SELECT borne deja l'acces aux deux parties.
  SELECT * INTO v_row
  FROM public.document_permission_requests
  WHERE id = p_request_id
  LIMIT 1;

  IF v_row.id IS NULL THEN
    RAISE EXCEPTION 'fn_exchange_save_followup: proposition de troca introuvable.';
  END IF;

  -- Le suivi ne concerne que les trocas, et seulement quand elles sont acceptees.
  IF lower(coalesce(v_row.object_type, '')) <> 'interlibrary_exchange' THEN
    RAISE EXCEPTION 'fn_exchange_save_followup: cette proposition n''est pas une troca.';
  END IF;
  IF lower(coalesce(v_row.status, '')) <> 'accepted' THEN
    RAISE EXCEPTION 'fn_exchange_save_followup: le suivi n''est possible que pour une troca aceita.';
  END IF;

  -- object_ref courant (peut etre une chaine JSON ou deja un jsonb selon
  -- l'historique des ecritures ; on tolere les deux).
  BEGIN
    v_ref := CASE
      WHEN v_row.object_ref IS NULL OR btrim(v_row.object_ref) = '' THEN '{}'::jsonb
      ELSE v_row.object_ref::jsonb
    END;
  EXCEPTION WHEN others THEN
    -- object_ref non parseable : on repart d'un objet vide plutot que d'echouer.
    v_ref := '{}'::jsonb;
  END;

  -- Merge du patch dans execution_followup, en preservant le reste de l'object_ref.
  v_current_followup := coalesce(v_ref->'execution_followup', '{}'::jsonb);
  IF jsonb_typeof(v_current_followup) <> 'object' THEN
    v_current_followup := '{}'::jsonb;
  END IF;
  IF jsonb_typeof(coalesce(p_followup_patch, '{}'::jsonb)) <> 'object' THEN
    RAISE EXCEPTION 'fn_exchange_save_followup: le patch de suivi doit etre un objet JSON.';
  END IF;

  v_next_followup := v_current_followup
    || coalesce(p_followup_patch, '{}'::jsonb)
    || jsonb_build_object('updated_at', to_char(timezone('utc', now()), 'YYYY-MM-DD"T"HH24:MI:SS"Z"'));

  v_ref := v_ref || jsonb_build_object('execution_followup', v_next_followup);

  -- Ecriture. La RLS UPDATE (USING + WITH CHECK) s'applique : si l'appelant
  -- ne gere aucune des deux bibliotheques, l'UPDATE ne touche aucune ligne.
  UPDATE public.document_permission_requests
     SET object_ref = v_ref::text,
         updated_at = timezone('utc', now()),
         updated_by = auth.uid()
   WHERE id = p_request_id
  RETURNING * INTO v_row;

  IF v_row.id IS NULL THEN
    RAISE EXCEPTION 'fn_exchange_save_followup: ecriture refusee (permissions insuffisantes pour cette troca).';
  END IF;

  RETURN v_row;
END;
$$;


ALTER FUNCTION "public"."fn_exchange_save_followup"("p_request_id" "uuid", "p_followup_patch" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_execute_due_profile_proposals"() RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_proposal      record;
  v_count_success int := 0;
  v_count_fail    int := 0;
  v_result        jsonb;
BEGIN
  RAISE NOTICE '[fn_execute_due_profile_proposals] start at %', now();

  FOR v_proposal IN
    SELECT id, library_id, axis, governance_required, grace_period_until
    FROM public.library_profile_proposals
    WHERE status IN ('accepted_unanimous', 'accepted_majority')
      AND grace_period_until IS NOT NULL
      AND grace_period_until <= now()
    ORDER BY grace_period_until
    FOR UPDATE SKIP LOCKED  -- skip les propositions deja lockees (concurrence vote/execute manuel)
  LOOP
    BEGIN
      -- Appel du RPC B.3 dans sa propre savepoint pour isolation
      -- auth.uid() sera NULL ici (contexte cron postgres) -> fn_execute_*
      -- reconnait cet appel systeme et impute l'execution au proposeur original.
      v_result := public.fn_execute_library_profile_change(v_proposal.id);

      v_count_success := v_count_success + 1;
      RAISE NOTICE '[fn_execute_due_profile_proposals] executed proposal % (library=%, axis=%, gov=%, grace_ended=%)',
        v_proposal.id, v_proposal.library_id, v_proposal.axis,
        v_proposal.governance_required, v_proposal.grace_period_until;

    EXCEPTION WHEN OTHERS THEN
      -- Une execution en erreur ne doit pas bloquer le batch
      v_count_fail := v_count_fail + 1;
      RAISE WARNING '[fn_execute_due_profile_proposals] FAIL on proposal % : % (%)',
        v_proposal.id, SQLERRM, SQLSTATE;
    END;
  END LOOP;

  RAISE NOTICE '[fn_execute_due_profile_proposals] done at %, % success, % failed',
    now(), v_count_success, v_count_fail;

  RETURN v_count_success;
END;
$$;


ALTER FUNCTION "public"."fn_execute_due_profile_proposals"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."fn_execute_due_profile_proposals"() IS 'B.4 cron : execute les propositions accepted_* dont grace_period_until <= now(). Toutes les 15 min. Filet de securite de fn_vote (doctrine D3 hybride). Returns count success.';



CREATE OR REPLACE FUNCTION "public"."fn_execute_library_profile_change"("p_proposal_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_caller_id     uuid := auth.uid();
  v_proposal      public.library_profile_proposals%ROWTYPE;
  v_is_staff      boolean := false;
  v_is_system     boolean := false;
  v_archive_result jsonb := NULL;
  -- Paquet G (20/05/2026)
  v_new_template  text;
  v_lib           public.libraries%ROWTYPE;
BEGIN
  SELECT * INTO v_proposal
  FROM public.library_profile_proposals
  WHERE id = p_proposal_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'EXECUTE_PROPOSAL_NOT_FOUND : proposition introuvable (%)', p_proposal_id
      USING ERRCODE = 'no_data_found',
            HINT    = 'error.profile_change.proposal_not_found';
  END IF;

  v_is_system := (v_caller_id IS NULL);

  IF NOT v_is_system THEN
    v_is_staff := EXISTS (
      SELECT 1 FROM public.user_library_memberships
      WHERE library_id = v_proposal.library_id
        AND user_id    = v_caller_id
        AND status     = 'active'
        AND role IN ('librarian', 'coordenador')
    );

    IF NOT v_is_staff THEN
      RAISE EXCEPTION 'EXECUTE_NOT_AUTHORIZED : caller n''est ni staff de la biblio ni systeme cron'
        USING ERRCODE = 'insufficient_privilege',
              HINT    = 'error.profile_change.not_authorized';
    END IF;
  END IF;

  IF v_proposal.status NOT IN ('accepted_unanimous', 'accepted_majority') THEN
    RAISE EXCEPTION 'EXECUTE_PROPOSAL_NOT_ACCEPTED : proposition pas executable (status=%)', v_proposal.status
      USING ERRCODE = 'invalid_parameter_value',
            HINT    = 'error.profile_change.not_accepted';
  END IF;

  IF v_proposal.grace_period_until IS NULL OR v_proposal.grace_period_until > now() THEN
    RAISE EXCEPTION 'EXECUTE_GRACE_PERIOD_ACTIVE : carence active jusqu''a %', v_proposal.grace_period_until
      USING ERRCODE = 'invalid_parameter_value',
            HINT    = 'error.profile_change.grace_period_active';
  END IF;

  INSERT INTO public.library_profile_history (
    library_id, axis, old_value, new_value, changed_by, changed_at, motivation
  )
  VALUES (
    v_proposal.library_id,
    v_proposal.axis,
    v_proposal.old_value,
    v_proposal.new_value,
    COALESCE(v_caller_id, v_proposal.proposed_by),
    now(),
    'Transition type ' || v_proposal.transition_type ||
    ' (' || v_proposal.governance_required || ') : ' || v_proposal.motivation
  );

  -- Update de l'axe modifie
  IF    v_proposal.axis = 'catalog_mode'     THEN UPDATE public.libraries SET catalog_mode     = v_proposal.new_value WHERE id = v_proposal.library_id;
  ELSIF v_proposal.axis = 'circulation_mode' THEN UPDATE public.libraries SET circulation_mode = v_proposal.new_value WHERE id = v_proposal.library_id;
  ELSIF v_proposal.axis = 'network_mode'     THEN UPDATE public.libraries SET network_mode     = v_proposal.new_value WHERE id = v_proposal.library_id;
  ELSIF v_proposal.axis = 'governance_mode'  THEN UPDATE public.libraries SET governance_mode  = v_proposal.new_value WHERE id = v_proposal.library_id;
  END IF;

  -- Paquet G : recalculer profile_template_chosen base sur le nouveau quadruplet
  SELECT * INTO v_lib FROM public.libraries WHERE id = v_proposal.library_id;

  v_new_template := CASE
    -- Profil A : local_only + off + isolated + informal
    WHEN v_lib.catalog_mode = 'local_only'
     AND v_lib.circulation_mode = 'off'
     AND v_lib.network_mode = 'isolated'
     AND v_lib.governance_mode = 'informal' THEN 'A'
    -- Profil B : local_only + informal + isolated + informal
    WHEN v_lib.catalog_mode = 'local_only'
     AND v_lib.circulation_mode = 'informal'
     AND v_lib.network_mode = 'isolated'
     AND v_lib.governance_mode = 'informal' THEN 'B'
    -- Profil C : network_published + informal + observer + staff_roles
    WHEN v_lib.catalog_mode = 'network_published'
     AND v_lib.circulation_mode = 'informal'
     AND v_lib.network_mode = 'observer'
     AND v_lib.governance_mode = 'staff_roles' THEN 'C'
    -- Profil D : network_published + full_sigb + federated + full_governance
    WHEN v_lib.catalog_mode = 'network_published'
     AND v_lib.circulation_mode = 'full_sigb'
     AND v_lib.network_mode = 'federated'
     AND v_lib.governance_mode = 'full_governance' THEN 'D'
    -- Sinon : custom (configuration personnalisee)
    ELSE 'custom'
  END;

  -- Mise a jour du template (puisque le quadruplet vient de changer,
  -- on considere que le choix est desormais conscient et formalise)
  UPDATE public.libraries
     SET profile_template_chosen = v_new_template
   WHERE id = v_proposal.library_id;

  -- Archivages cascade (logique inchangee)
  IF v_proposal.axis = 'circulation_mode' AND v_proposal.new_value = 'off' THEN
    v_archive_result := public.fn_archive_library_circulation(
      v_proposal.library_id, p_proposal_id
    );
  END IF;

  IF v_proposal.axis = 'circulation_mode'
     AND v_proposal.old_value = 'full_sigb'
     AND v_proposal.new_value = 'informal' THEN
    v_archive_result := public.fn_archive_library_cotisations(
      v_proposal.library_id, p_proposal_id
    );
  END IF;

  -- Cloture proposal
  UPDATE public.library_profile_proposals
  SET status       = 'completed',
      completed_at = now()
  WHERE id = p_proposal_id;

  UPDATE public.library_profile_grace_locks
  SET released_at = now()
  WHERE proposal_id = p_proposal_id
    AND released_at IS NULL;

  RETURN jsonb_build_object(
    'proposal_id',          p_proposal_id,
    'library_id',           v_proposal.library_id,
    'axis',                 v_proposal.axis,
    'old_value',            v_proposal.old_value,
    'new_value',            v_proposal.new_value,
    'completed_at',         now(),
    'executed_by_caller',   COALESCE(v_caller_id::text, 'system_cron'),
    'archive_result',       v_archive_result,
    -- Paquet G : retourner le nouveau template
    'new_template_chosen',  v_new_template
  );
END;
$$;


ALTER FUNCTION "public"."fn_execute_library_profile_change"("p_proposal_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."fn_execute_library_profile_change"("p_proposal_id" "uuid") IS 'B.3 RPC : execute une proposition acceptee dont la carence est echue. Doctrine #141.2.E (narrative avant etat) : INSERT history -> UPDATE libraries -> UPDATE proposal -> UPDATE grace_lock.';



CREATE OR REPLACE FUNCTION "public"."fn_expire_negotiation_timeout"() RETURNS TABLE("processed_count" integer, "error_count" integer, "details" "jsonb")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_row record;
  v_processed integer := 0;
  v_errors integer := 0;
  v_errors_details jsonb := '[]'::jsonb;
BEGIN
  FOR v_row IN
    SELECT
      riw.id,
      riw.reserva_id,
      riw.line_no,
      riw.workflow_stage,
      r.created_at AS reserva_created_at,
      r.library_id,
      lnp.reservation_negotiation_timeout_days AS timeout_days,
      now() - r.created_at AS age
    FROM public.reserva_item_workflow_v2 riw
    JOIN public.reservas_v2 r ON r.id = riw.reserva_id
    JOIN public.library_notification_policies lnp ON lnp.library_id = r.library_id
    WHERE riw.workflow_stage IN (
            -- Refactor v3 : retirada_agendada et re-retirada_agendada retirés
            'em_preparacao',
            'retirada_a_combinar'
          )
      AND r.created_at < now() - make_interval(days => lnp.reservation_negotiation_timeout_days)
  LOOP
    BEGIN
      IF NOT public.fn_check_workflow_transition(v_row.workflow_stage, 'expirada', 'system') THEN
        RAISE EXCEPTION 'helper_refused_transition';
      END IF;

      UPDATE public.reserva_item_workflow_v2
      SET workflow_stage = 'expirada',
          workflow_note = format(
            'Négociation expirée automatiquement par cron (timeout: %s jours, âge: %s, stage précédent: %s)',
            v_row.timeout_days, v_row.age::text, v_row.workflow_stage
          ),
          updated_at = now()
      WHERE id = v_row.id;

      v_processed := v_processed + 1;
    EXCEPTION
      WHEN OTHERS THEN
        v_errors := v_errors + 1;
        v_errors_details := v_errors_details || jsonb_build_object(
          'reserva_id', v_row.reserva_id,
          'line_no', v_row.line_no,
          'workflow_stage', v_row.workflow_stage,
          'sqlstate', SQLSTATE,
          'message', SQLERRM
        );
    END;
  END LOOP;

  processed_count := v_processed;
  error_count := v_errors;
  details := jsonb_build_object(
    'run_at', now(),
    'errors', v_errors_details
  );
  RETURN NEXT;
END;
$$;


ALTER FUNCTION "public"."fn_expire_negotiation_timeout"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."fn_expire_negotiation_timeout"() IS 'Job cron : expire les réservations en stages de négociation (em_preparacao, retirada_a_combinar) dont l''âge depuis reservas_v2.created_at dépasse library_notification_policies.reservation_negotiation_timeout_days (default 21j). Refactor v3 (2026-05-09) : retirada_agendada retiré du périmètre (créneau verrouillé = pas de timeout, géré par retirada_no_show), re-retirada_agendada retiré (déprécié). Spec refactor v3.';



CREATE OR REPLACE FUNCTION "public"."fn_expire_overdue_profile_proposals"() RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_proposal record;
  v_count    int := 0;
BEGIN
  RAISE NOTICE '[fn_expire_overdue_profile_proposals] start at %', now();

  FOR v_proposal IN
    SELECT id, library_id, axis, proposed_at, expires_at
    FROM public.library_profile_proposals
    WHERE status = 'open'
      AND expires_at <= now()
    ORDER BY expires_at
    FOR UPDATE SKIP LOCKED  -- skip les propositions deja lockees par un vote en cours
  LOOP
    BEGIN
      UPDATE public.library_profile_proposals
      SET status = 'expired'
      WHERE id = v_proposal.id;

      v_count := v_count + 1;
      RAISE NOTICE '[fn_expire_overdue_profile_proposals] expired proposal % (library=%, axis=%, expires_at=%)',
        v_proposal.id, v_proposal.library_id, v_proposal.axis, v_proposal.expires_at;

    EXCEPTION WHEN OTHERS THEN
      -- Une expiration en erreur ne doit pas bloquer les autres
      RAISE WARNING '[fn_expire_overdue_profile_proposals] FAIL on proposal % : % (%)',
        v_proposal.id, SQLERRM, SQLSTATE;
    END;
  END LOOP;

  RAISE NOTICE '[fn_expire_overdue_profile_proposals] done at %, % propositions expired',
    now(), v_count;

  RETURN v_count;
END;
$$;


ALTER FUNCTION "public"."fn_expire_overdue_profile_proposals"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."fn_expire_overdue_profile_proposals"() IS 'B.4 cron : marque expired les propositions open dont expires_at <= now(). Daily 03:00 UTC. Returns count.';



CREATE OR REPLACE FUNCTION "public"."fn_expire_solicitada_reservations"() RETURNS TABLE("processed_count" integer, "error_count" integer, "details" "jsonb")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_row record;
  v_processed integer := 0;
  v_errors integer := 0;
  v_errors_details jsonb := '[]'::jsonb;
BEGIN
  FOR v_row IN
    SELECT
      riw.id,
      riw.reserva_id,
      riw.line_no,
      riw.workflow_stage,
      r.created_at AS reserva_created_at,
      r.library_id,
      lnp.reservation_solicitada_timeout_days AS timeout_days,
      now() - r.created_at AS age
    FROM public.reserva_item_workflow_v2 riw
    JOIN public.reservas_v2 r ON r.id = riw.reserva_id
    JOIN public.library_notification_policies lnp ON lnp.library_id = r.library_id
    WHERE riw.workflow_stage = 'solicitada'
      AND r.created_at < now() - make_interval(days => lnp.reservation_solicitada_timeout_days)
  LOOP
    BEGIN
      IF NOT public.fn_check_workflow_transition('solicitada', 'expirada', 'system') THEN
        RAISE EXCEPTION 'helper_refused_transition';
      END IF;

      UPDATE public.reserva_item_workflow_v2
      SET workflow_stage = 'expirada',
          workflow_note = format(
            'Expirée automatiquement par cron (timeout: %s jours, âge: %s)',
            v_row.timeout_days, v_row.age::text
          ),
          updated_at = now()
      WHERE id = v_row.id;

      v_processed := v_processed + 1;
    EXCEPTION
      WHEN OTHERS THEN
        v_errors := v_errors + 1;
        v_errors_details := v_errors_details || jsonb_build_object(
          'reserva_id', v_row.reserva_id,
          'line_no', v_row.line_no,
          'sqlstate', SQLSTATE,
          'message', SQLERRM
        );
    END;
  END LOOP;

  processed_count := v_processed;
  error_count := v_errors;
  details := jsonb_build_object(
    'run_at', now(),
    'errors', v_errors_details
  );
  RETURN NEXT;
END;
$$;


ALTER FUNCTION "public"."fn_expire_solicitada_reservations"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."fn_expire_solicitada_reservations"() IS 'Job cron : expire les réservations en stage solicitada dont l''âge dépasse library_notification_policies.reservation_solicitada_timeout_days. Tourne en SECURITY DEFINER avec sanity check via fn_check_workflow_transition(actor=''system''). Try/catch par ligne pour résilience. Retourne (processed_count, error_count, details jsonb).';



CREATE OR REPLACE FUNCTION "public"."fn_export_catalog_lote"("p_library_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'auth'
    AS $$
DECLARE
  v_authorized boolean;
  v_records    jsonb;
BEGIN
  IF p_library_id IS NULL THEN
    RAISE EXCEPTION 'library_id obrigatorio.';
  END IF;

  -- IMP-14 : reservé au coordenador de la bibliothèque (ou à l'admin réseau).
  SELECT (
    EXISTS (
      SELECT 1 FROM public.user_library_memberships m
      WHERE m.user_id   = auth.uid()
        AND m.library_id = p_library_id
        AND m.status     = 'active'
        AND m.role       = 'coordenador'
    )
    OR public.fn_caller_is_network_admin()
  ) INTO v_authorized;

  IF NOT v_authorized THEN
    RAISE EXCEPTION 'Acesso restrito ao coordenador da biblioteca.';
  END IF;

  -- Catalogue scopé biblio via book_holdings. Notices normalisées (forme
  -- serialize.ts) ; auteur·rices ordonné·es par book_authors.ord ; sujets
  -- éclatés en tableau depuis le champ texte (subjects sinon assuntos).
  SELECT coalesce(jsonb_agg(rec ORDER BY rec_id), '[]'::jsonb)
    INTO v_records
    FROM (
      SELECT
        b.id AS rec_id,
        jsonb_build_object(
          'id',             b.id,
          'bibRef',         b.bib_ref,
          'title',          b.titulo,
          'subtitle',       b.subtitulo,
          'authors', coalesce((
            SELECT jsonb_agg(
                     jsonb_build_object('name', a.preferred_name, 'role', ba.role, 'ord', ba.ord)
                     ORDER BY ba.ord
                   )
              FROM public.book_authors ba
              JOIN public.authors a ON a.id = ba.author_id
             WHERE ba.book_id = b.id
          ), '[]'::jsonb),
          'responsibility', b.autor,
          'publisher',      b.editora,
          'year',           b.ano,
          'place',          b.local_publicacao,
          'edition',        b.edicao,
          'isbn',           b.isbn,
          'issn',           b.issn,
          'language',       b.idioma,
          'pages',          b.paginas,
          'cdd',            b.cdd,
          'subjects',
            CASE
              WHEN coalesce(b.subjects, b.assuntos) IS NULL
                OR btrim(coalesce(b.subjects, b.assuntos)) = '' THEN '[]'::jsonb
              ELSE to_jsonb(regexp_split_to_array(btrim(coalesce(b.subjects, b.assuntos)), '\s*[;,]\s*'))
            END,
          'collection',     b.colecao,
          'materialType',   b.tipo_material,
          'notes',          b.notas
        ) AS rec
        FROM public.books b
       WHERE EXISTS (
         SELECT 1 FROM public.book_holdings h
          WHERE h.book_id = b.id AND h.library_id = p_library_id
       )
    ) sub;

  RETURN jsonb_build_object(
    'ok',         true,
    'library_id', p_library_id,
    'count',      jsonb_array_length(v_records),
    'records',    v_records
  );
END;
$$;


ALTER FUNCTION "public"."fn_export_catalog_lote"("p_library_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."fn_export_catalog_lote"("p_library_id" "uuid") IS 'Lot 5 (IMP-13) — Export de lote : retourne le catalogue normalise (JSON) d''une bibliotheque. Reserve au coordenador de la biblio (IMP-14) ou admin reseau. La serialisation CSV/MARCXML/JSON + livraison fichier vivent dans l''EF export-catalog-lote.';



CREATE OR REPLACE FUNCTION "public"."fn_export_my_data"() RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_user_id uuid := auth.uid();
  v_result jsonb;
BEGIN
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Authentication required to export personal data.'
      USING ERRCODE = '42501';
  END IF;

  v_result := jsonb_build_object(
    -- Métadonnées de l'export
    'exported_at', to_jsonb(now()),
    'export_format_version', '1.0',
    'rgpd_notice', 'Cet export contient l''ensemble de vos donnees personnelles tel que stocke par AnarBib (article 20 RGPD / article 18 LGPD). Les donnees techniques internes (clefs primaires, references de cache) sont incluses pour completude. Email de contact pour toute question : contato@anarbib.org',

    -- Identité du user (depuis profiles uniquement, pas auth.users)
    -- Note RGPD : auth_created_at et last_sign_in_at sont des metadonnees
    -- techniques de session non considerees comme donnees personnelles au
    -- sens article 20. L'email et la date de creation sont dans profiles.
    'user', jsonb_build_object(
      'id', v_user_id
    ),

    -- Profil
    'profile', (
      SELECT to_jsonb(p) - 'id'  -- on enlève l'id qui est déjà dans user
      FROM profiles p
      WHERE p.id = v_user_id
    ),

    -- Memberships dans les biblios (avec infos de la biblio jointes)
    'memberships', COALESCE((
      SELECT jsonb_agg(jsonb_build_object(
        'membership_id', m.id,
        'library', jsonb_build_object(
          'id', l.id,
          'slug', l.slug,
          'name', l.name,
          'short_name', l.short_name,
          'city', l.city,
          'country', l.country
        ),
        'role', m.role,
        'is_primary', m.is_primary,
        'status', m.status,
        'is_restricted', m.is_restricted,
        'restricted_reason', m.restricted_reason,
        'history_enabled', m.history_enabled,
        'created_at', m.created_at,
        'updated_at', m.updated_at
      ) ORDER BY m.is_primary DESC, m.created_at)
      FROM user_library_memberships m
      JOIN libraries l ON l.id = m.library_id
      WHERE m.user_id = v_user_id
    ), '[]'::jsonb),

    -- Paiements de cotisation
    'membership_payments', COALESCE((
      SELECT jsonb_agg(to_jsonb(mp) ORDER BY mp.paid_at DESC)
      FROM membership_payments mp
      WHERE mp.user_id = v_user_id
    ), '[]'::jsonb),

    -- Emprunts (avec items détaillés)
    'loans', COALESCE((
      SELECT jsonb_agg(jsonb_build_object(
        'loan_id', e.id,
        'library_id', e.library_id,
        'status_global', e.status_global,
        'due_at', e.due_at,
        'extended_once', e.extended_once,
        'extended_at', e.extended_at,
        'notes', e.notes,
        'created_at', e.created_at,
        'updated_at', e.updated_at,
        'items', COALESCE((
          SELECT jsonb_agg(jsonb_build_object(
            'line_no', ei.line_no,
            'item_status', ei.item_status,
            'bib_ref', ei.bib_ref,
            'titulo', ei.titulo_cache,
            'autor', ei.autor_cache,
            'editora', ei.editora_cache,
            'ano', ei.ano_cache,
            'rotulo', ei.rotulo_cache,
            'due_at', ei.due_at,
            'extended_until', ei.extended_until,
            'extension_note', ei.extension_note,
            'returned_at', ei.returned_at,
            'return_completed_at', ei.return_completed_at,
            'return_scheduled_for', ei.return_scheduled_for,
            'notes', ei.notes,
            'created_at', ei.created_at
          ) ORDER BY ei.line_no)
          FROM emprestimo_itens_v2 ei
          WHERE ei.emprestimo_id = e.id
        ), '[]'::jsonb)
      ) ORDER BY e.created_at DESC)
      FROM emprestimos_v2 e
      WHERE e.user_id = v_user_id
    ), '[]'::jsonb),

    -- Réservations (avec lignes et workflow détaillés)
    'reservations', COALESCE((
      SELECT jsonb_agg(jsonb_build_object(
        'reservation_id', r.id,
        'library_id', r.library_id,
        'status_global', r.status_global,
        'notes', r.notes,
        'created_at', r.created_at,
        'updated_at', r.updated_at,
        'lines', COALESCE((
          SELECT jsonb_agg(jsonb_build_object(
            'line_no', rl.line_no,
            'item_status', rl.item_status,
            'bib_ref', rl.bib_ref,
            'titulo', rl.titulo_cache,
            'autor', rl.autor_cache,
            'editora', rl.editora_cache,
            'ano', rl.ano_cache,
            'rotulo', rl.rotulo_cache,
            'expires_at', rl.expires_at,
            'cancelled_at', rl.cancelled_at,
            'converted_at', rl.converted_at,
            'expired_at', rl.expired_at,
            'notes', rl.notes,
            'created_at', rl.created_at,
            'workflow', (
              SELECT jsonb_build_object(
                'workflow_stage', rw.workflow_stage,
                'workflow_note', rw.workflow_note,
                'pickup_scheduled_for', rw.pickup_scheduled_for,
                'pickup_reply_status', rw.pickup_reply_status,
                'pickup_reply_note', rw.pickup_reply_note,
                'pickup_reply_at', rw.pickup_reply_at,
                'updated_at', rw.updated_at
              )
              FROM reserva_item_workflow_v2 rw
              WHERE rw.reserva_id = rl.reserva_id AND rw.line_no = rl.line_no
            )
          ) ORDER BY rl.line_no)
          FROM reserva_linhas_v2 rl
          WHERE rl.reserva_id = r.id
        ), '[]'::jsonb)
      ) ORDER BY r.created_at DESC)
      FROM reservas_v2 r
      WHERE r.user_id = v_user_id
    ), '[]'::jsonb),

    -- Consultations sur place
    'consultations', COALESCE((
      SELECT jsonb_agg(jsonb_build_object(
        'consultation_id', c.id,
        'library_id', c.library_id,
        'status_global', c.status_global,
        'notes', c.notes,
        'created_at', c.created_at,
        'updated_at', c.updated_at,
        'lines', COALESCE((
          SELECT jsonb_agg(jsonb_build_object(
            'line_no', cl.line_no,
            'item_status', cl.item_status,
            'bib_ref', cl.bib_ref,
            'titulo', cl.titulo_cache,
            'autor', cl.autor_cache,
            'editora', cl.editora_cache,
            'ano', cl.ano_cache,
            'expires_at', cl.expires_at,
            'cancelled_at', cl.cancelled_at,
            'consulted_at', cl.consulted_at,
            'expired_at', cl.expired_at,
            'dismissed_by_reader_at', cl.dismissed_by_reader_at,
            'notes', cl.notes,
            'created_at', cl.created_at
          ) ORDER BY cl.line_no)
          FROM consulta_linhas_v2 cl
          WHERE cl.consulta_id = c.id
        ), '[]'::jsonb)
      ) ORDER BY c.created_at DESC)
      FROM consultas_locais_v2 c
      WHERE c.user_id = v_user_id
    ), '[]'::jsonb),

    -- Notifications reçues
    'notifications', COALESCE((
      SELECT jsonb_agg(to_jsonb(n) ORDER BY n.created_at DESC)
      FROM user_notifications n
      WHERE n.user_id = v_user_id
    ), '[]'::jsonb),

    -- Wishlist
    'wishlist', COALESCE((
      SELECT jsonb_agg(jsonb_build_object(
        'wishlist_id', w.id,
        'library_id', w.library_id,
        'book_id', w.book_id,
        'note', w.note,
        'created_at', w.created_at
      ) ORDER BY w.created_at DESC)
      FROM user_wishlist w
      WHERE w.user_id = v_user_id
    ), '[]'::jsonb)
  );

  RETURN v_result;
END;
$$;


ALTER FUNCTION "public"."fn_export_my_data"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_format_holding_refs"("p_holding_ids" bigint[]) RETURNS "text"
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
  -- Pour chaque holding_id en entree, retourne :
  --   1. le local_bib_ref du holding s'il existe (priorite)
  --   2. sinon le bib_ref du livre via la jointure books
  --   3. sinon l'id brut (fallback ultime, ne devrait jamais arriver)
  -- Resultat concatene par ', ' dans l'ordre d'entree.
  SELECT string_agg(
    COALESCE(NULLIF(TRIM(h.local_bib_ref), ''), b.bib_ref, x.holding_id::text),
    ', '
    ORDER BY x.ord
  )
  FROM unnest(COALESCE(p_holding_ids, '{}'::bigint[])) WITH ORDINALITY AS x(holding_id, ord)
  LEFT JOIN public.book_holdings h ON h.id = x.holding_id
  LEFT JOIN public.books b ON b.id = h.book_id;
$$;


ALTER FUNCTION "public"."fn_format_holding_refs"("p_holding_ids" bigint[]) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."fn_format_holding_refs"("p_holding_ids" bigint[]) IS 'Paquet 15 (10/05/2026) : helper qui transforme un array de holding_id
en string lisible (bib_refs) pour les messages d''erreur des fonctions
de creation d''emprunts/reservations. Pre-requis : le bib_ref priorise
local_bib_ref puis books.bib_ref ; fallback sur l''id si rien n''est
disponible.';



