CREATE OR REPLACE FUNCTION "public"."fn_get_retention_policy"("p_library_id" "uuid") RETURNS "jsonb"
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
  SELECT jsonb_build_object(
    'library_id', l.id,
    -- Valeurs effectives (override OU défaut AnarBib)
    'retention_loans_days', COALESCE(p.retention_loans_days, 730),         -- 24 mois
    'retention_reservations_days', COALESCE(p.retention_reservations_days, 365),  -- 12 mois
    'retention_consultations_days', COALESCE(p.retention_consultations_days, 365),-- 12 mois
    'retention_notifications_days', COALESCE(p.retention_notifications_days, 90), -- 90 jours
    -- Indicateurs : la biblio a-t-elle un override sur chaque catégorie ?
    'overrides', jsonb_build_object(
      'loans', p.retention_loans_days IS NOT NULL,
      'reservations', p.retention_reservations_days IS NOT NULL,
      'consultations', p.retention_consultations_days IS NOT NULL,
      'notifications', p.retention_notifications_days IS NOT NULL
    ),
    'notes', p.notes,
    'updated_at', p.updated_at,
    'has_custom_policy', p.library_id IS NOT NULL
  )
  FROM public.libraries l
  LEFT JOIN public.library_retention_policies p ON p.library_id = l.id
  WHERE l.id = p_library_id;
$$;


