CREATE OR REPLACE FUNCTION "public"."fn_hide_history_item"("p_domain" "text", "p_record_id" bigint) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_uid   uuid := auth.uid();
  v_count integer;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'not_authenticated' USING HINT = 'history.error.not_authenticated';
  END IF;

  IF p_domain = 'loans' THEN
    UPDATE public.emprestimos_v2
       SET is_hidden_by_user = true, hidden_at = now()
     WHERE id = p_record_id
       AND user_id = v_uid
       AND status_global = 'encerrado';
    GET DIAGNOSTICS v_count = ROW_COUNT;

  ELSIF p_domain = 'reservations' THEN
    UPDATE public.reserva_linhas_v2 rl
       SET is_hidden_by_user = true, hidden_at = now()
      FROM public.reservas_v2 r
     WHERE rl.id = p_record_id
       AND rl.reserva_id = r.id
       AND r.user_id = v_uid
       AND rl.item_status IN ('cancelada_leitor','cancelada_biblioteca','convertida_em_emprestimo','expirada','liberada_para_circulacao');
    GET DIAGNOSTICS v_count = ROW_COUNT;

  ELSIF p_domain = 'consultations' THEN
    UPDATE public.consulta_linhas_v2 cl
       SET is_hidden_by_user = true, hidden_at = now()
      FROM public.consultas_locais_v2 c
     WHERE cl.id = p_record_id
       AND cl.consulta_id = c.id
       AND c.user_id = v_uid
       AND cl.item_status IN ('consultada','cancelada_leitor','cancelada_biblioteca','expirada');
    GET DIAGNOSTICS v_count = ROW_COUNT;

  ELSE
    RAISE EXCEPTION 'invalid_domain' USING HINT = 'history.error.invalid_domain';
  END IF;

  IF v_count = 0 THEN
    RAISE EXCEPTION 'item_not_found_or_not_terminal' USING HINT = 'history.error.not_found_or_active';
  END IF;
END;
$$;


ALTER FUNCTION "public"."fn_hide_history_item"("p_domain" "text", "p_record_id" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_import_create"("p_source_id" bigint, "p_storage_path" "text", "p_original_filename" "text", "p_bucket_id" "text" DEFAULT 'catalogos_parceiros_raw'::"text", "p_mime_type" "text" DEFAULT NULL::"text", "p_size_bytes" bigint DEFAULT NULL::bigint, "p_sha256" "text" DEFAULT NULL::"text", "p_detected_format" "text" DEFAULT 'unknown'::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'ingest', 'auth'
    AS $$
DECLARE
  v_actor public.my_access%rowtype;
  v_source_library_id uuid;
  v_run_id bigint;
BEGIN
  SELECT * INTO v_actor FROM public.my_access LIMIT 1;
  IF v_actor.library_id IS NULL
     OR NOT coalesce(v_actor.can_access_painel, false) THEN
    RAISE EXCEPTION 'Acesso bibliotecario obrigatorio.';
  END IF;
  IF v_actor.role IS DISTINCT FROM 'coordenador' AND NOT public.fn_caller_is_network_admin() THEN
    RAISE EXCEPTION 'Acesso restrito ao coordenador da biblioteca.';
  END IF;

  SELECT s.library_id INTO v_source_library_id
  FROM ingest.partner_catalog_sources s
  WHERE s.id = p_source_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Source % introuvable', p_source_id;
  END IF;

  IF v_source_library_id IS DISTINCT FROM v_actor.library_id THEN
    RAISE EXCEPTION 'Source % nao pertence a esta biblioteca', p_source_id;
  END IF;

  v_run_id := ingest.fn_create_partner_catalog_import(
    p_source_id         := p_source_id,
    p_storage_path      := p_storage_path,
    p_original_filename := p_original_filename,
    p_bucket_id         := p_bucket_id,
    p_mime_type         := p_mime_type,
    p_size_bytes        := p_size_bytes,
    p_sha256            := p_sha256,
    p_detected_format   := p_detected_format,
    p_requested_by      := v_actor.user_id
  );

  UPDATE ingest.partner_catalog_import_runs
  SET library_id = v_actor.library_id
  WHERE id = v_run_id AND library_id IS NULL;

  RETURN jsonb_build_object(
    'ok',         true,
    'run_id',     v_run_id,
    'library_id', v_actor.library_id
  );
END;
$$;


ALTER FUNCTION "public"."fn_import_create"("p_source_id" bigint, "p_storage_path" "text", "p_original_filename" "text", "p_bucket_id" "text", "p_mime_type" "text", "p_size_bytes" bigint, "p_sha256" "text", "p_detected_format" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_import_dispatch"("p_run_id" bigint, "p_force_reparse" boolean DEFAULT false) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'ingest', 'auth'
    AS $$
DECLARE
  v_actor public.my_access%rowtype;
  v_run_library_id uuid;
BEGIN
  SELECT * INTO v_actor FROM public.my_access LIMIT 1;
  IF v_actor.library_id IS NULL
     OR NOT coalesce(v_actor.can_access_painel, false) THEN
    RAISE EXCEPTION 'Acesso bibliotecario obrigatorio.';
  END IF;
  IF v_actor.role IS DISTINCT FROM 'coordenador' AND NOT public.fn_caller_is_network_admin() THEN
    RAISE EXCEPTION 'Acesso restrito ao coordenador da biblioteca.';
  END IF;

  SELECT r.library_id INTO v_run_library_id
  FROM ingest.partner_catalog_import_runs r
  WHERE r.id = p_run_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Run % introuvable', p_run_id;
  END IF;

  IF v_run_library_id IS DISTINCT FROM v_actor.library_id THEN
    RAISE EXCEPTION 'Run % nao pertence a esta biblioteca', p_run_id;
  END IF;

  RETURN ingest.fn_dispatch_partner_catalog_import(
    p_run_id       := p_run_id,
    p_force_reparse := p_force_reparse
  );
END;
$$;


ALTER FUNCTION "public"."fn_import_dispatch"("p_run_id" bigint, "p_force_reparse" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_import_harvest_oai"("p_source_id" bigint, "p_max_lots" integer DEFAULT NULL::integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'ingest', 'auth'
    AS $$
DECLARE
  v_actor      public.my_access%rowtype;
  v_source     record;
  v_state      record;
  v_run_id     bigint;
  v_max        integer;
BEGIN
  -- 1. Contrôle d'accès
  SELECT * INTO v_actor FROM public.my_access LIMIT 1;
  IF v_actor.library_id IS NULL
     OR NOT coalesce(v_actor.can_access_painel, false) THEN
    RAISE EXCEPTION 'Acesso bibliotecario obrigatorio.';
  END IF;
  IF v_actor.role IS DISTINCT FROM 'coordenador' AND NOT public.fn_caller_is_network_admin() THEN
    RAISE EXCEPTION 'Acesso restrito ao coordenador da biblioteca.';
  END IF;

  -- 2. Vérifier la source
  SELECT * INTO v_source
    FROM ingest.partner_catalog_sources
   WHERE id = p_source_id AND source_kind = 'oai_pmh';
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Source OAI-PMH % introuvable.', p_source_id;
  END IF;

  -- Vérifier appartenance (sauf admin réseau)
  IF NOT public.fn_caller_is_network_admin()
     AND v_source.library_id IS DISTINCT FROM v_actor.library_id THEN
    RAISE EXCEPTION 'Source % nao pertence a esta biblioteca.', p_source_id;
  END IF;

  -- 3. Vérifier l'état
  SELECT * INTO v_state
    FROM ingest.oai_harvest_state
   WHERE source_id = p_source_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Etat de moissonnage introuvable pour source %.', p_source_id;
  END IF;

  IF v_state.harvest_status = 'in_progress' THEN
    RAISE EXCEPTION 'Moissonnage deja en cours pour source %.', p_source_id;
  END IF;

  v_max := coalesce(p_max_lots, v_state.lots_per_cycle);

  -- 4. Créer un run
  INSERT INTO ingest.partner_catalog_import_runs
    (source_id, library_id, detected_format, run_status,
     original_filename, requested_by, imported_rows)
  VALUES
    (p_source_id, v_source.library_id, 'oai_pmh', 'pending',
     'oai-harvest-' || current_date::text, v_actor.user_id, 0)
  RETURNING id INTO v_run_id;

  -- 5. Marquer l'état en cours
  UPDATE ingest.oai_harvest_state
     SET harvest_status            = 'in_progress',
         last_run_id               = v_run_id,
         lots_completed_this_cycle = 0,
         last_error                = NULL
   WHERE source_id = p_source_id;

  -- 6. TODO Lot 3b : appel pg_net vers l'EF harvest-oai-pmh
  --    Pour l'instant on retourne l'info du run créé.
  --    L'EF mettra à jour le run et le state après parsing.

  RETURN jsonb_build_object(
    'ok',        true,
    'run_id',    v_run_id,
    'source_id', p_source_id,
    'max_lots',  v_max,
    'endpoint',  v_source.oai_endpoint_url,
    'prefix',    v_source.oai_metadata_prefix,
    'from_date', v_state.last_harvest_at,
    'note',      'Edge Function harvest-oai-pmh pas encore deployee (Lot 3b). Run cree en attente.'
  );
END;
$$;


ALTER FUNCTION "public"."fn_import_harvest_oai"("p_source_id" bigint, "p_max_lots" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."fn_import_harvest_oai"("p_source_id" bigint, "p_max_lots" integer) IS 'Lot 3a — Déclenche un moissonnage OAI-PMH pour une source donnée. Crée un run + marque le state in_progress. Lot 3b branchera l''EF.';



CREATE OR REPLACE FUNCTION "public"."fn_import_ingest_candidate"("p_candidate" "jsonb", "p_source_id" bigint DEFAULT NULL::bigint) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'ingest', 'auth'
    AS $$
DECLARE
  v_actor   public.my_access%rowtype;
  v_src_id  bigint;
  v_run_id  bigint;
  v_row_id  bigint;
  v_today   date := current_date;
  v_row_no  integer;
BEGIN
  -- ── 1. Contrôle d'accès ────────────────────────────────
  SELECT * INTO v_actor FROM public.my_access LIMIT 1;
  IF v_actor.library_id IS NULL
     OR NOT coalesce(v_actor.can_access_painel, false) THEN
    RAISE EXCEPTION 'Acesso bibliotecario obrigatorio.';
  END IF;
  IF v_actor.role IS DISTINCT FROM 'coordenador' AND NOT public.fn_caller_is_network_admin() THEN
    RAISE EXCEPTION 'Acesso restrito ao coordenador da biblioteca.';
  END IF;

  -- ── 2. Résolution de la source ─────────────────────────
  IF p_source_id IS NOT NULL THEN
    IF NOT EXISTS (
      SELECT 1 FROM ingest.partner_catalog_sources
      WHERE id = p_source_id AND library_id = v_actor.library_id
    ) THEN
      RAISE EXCEPTION 'Source % nao pertence a esta biblioteca', p_source_id;
    END IF;
    v_src_id := p_source_id;
  ELSE
    SELECT id INTO v_src_id
      FROM ingest.partner_catalog_sources
     WHERE library_id = v_actor.library_id
       AND source_kind = 'institutional_lookup'
     LIMIT 1;

    IF v_src_id IS NULL THEN
      INSERT INTO ingest.partner_catalog_sources
        (partner_name, library_id, source_kind, import_enabled)
      VALUES
        ('Recherche institutionnelle', v_actor.library_id,
         'institutional_lookup', true)
      RETURNING id INTO v_src_id;
    END IF;
  END IF;

  -- ── 3. Run journalier de type lookup ───────────────────
  SELECT id INTO v_run_id
    FROM ingest.partner_catalog_import_runs
   WHERE source_id   = v_src_id
     AND library_id  = v_actor.library_id
     AND detected_format = 'lookup'
     AND created_at::date = v_today
     AND run_status NOT IN ('drafts_created', 'failed')
   ORDER BY id DESC
   LIMIT 1;

  IF v_run_id IS NULL THEN
    INSERT INTO ingest.partner_catalog_import_runs
      (source_id, library_id, detected_format, run_status,
       original_filename, requested_by, imported_rows)
    VALUES
      (v_src_id, v_actor.library_id, 'lookup', 'ready_for_review',
       'lookup-' || v_today::text, v_actor.user_id, 0)
    RETURNING id INTO v_run_id;
  END IF;

  -- ── 4. Insertion du candidat comme staging_row ─────────
  SELECT coalesce(max(row_no), 0) + 1 INTO v_row_no
    FROM ingest.partner_catalog_staging_rows
   WHERE run_id = v_run_id;

  INSERT INTO ingest.partner_catalog_staging_rows (
    run_id,
    row_no,
    external_key,
    item_type,
    title,
    subtitle,
    responsibility_statement,
    authors,
    publisher,
    place_of_publication,
    publication_year,
    edition_statement,
    language,
    isbn,
    issn,
    subjects,
    raw_payload,
    normalized_payload,
    parse_status,
    match_status,
    review_status,
    confidence
  ) VALUES (
    v_run_id,
    v_row_no,
    p_candidate->>'source_record_id',
    'lookup',
    p_candidate->>'title',
    p_candidate->>'subtitle',
    p_candidate->>'responsibility_statement',
    CASE WHEN p_candidate->'contributors' IS NOT NULL
         THEN p_candidate->'contributors'
         ELSE '[]'::jsonb END,
    p_candidate->>'publisher',
    p_candidate->>'place',
    p_candidate->>'year',
    p_candidate->>'edition',
    p_candidate->>'language',
    p_candidate->'isbn'->>0,
    p_candidate->'issn'->>0,
    CASE WHEN p_candidate->'subjects' IS NOT NULL
         THEN p_candidate->'subjects'
         ELSE '[]'::jsonb END,
    p_candidate,
    jsonb_build_object(
      'title',                    p_candidate->>'title',
      'subtitle',                 p_candidate->>'subtitle',
      'responsibility_statement', p_candidate->>'responsibility_statement',
      'authors',                  coalesce(p_candidate->'contributors', '[]'::jsonb),
      'publisher',                p_candidate->>'publisher',
      'place_of_publication',     p_candidate->>'place',
      'publication_year',         p_candidate->>'year',
      'isbn',                     p_candidate->'isbn'->>0,
      'issn',                     p_candidate->'issn'->>0,
      'subjects',                 coalesce(p_candidate->'subjects', '[]'::jsonb),
      'source',                   p_candidate->>'source',
      'source_url',               p_candidate->>'source_url',
      'raw_format',               p_candidate->>'raw_format',
      'parser_version',           'lookup_v1'
    ),
    'parsed',
    'pre_matched',
    'pending',
    coalesce((p_candidate->>'confidence')::numeric, 0)
  ) RETURNING id INTO v_row_id;

  -- ── 5. Mise à jour des compteurs du run ────────────────
  UPDATE ingest.partner_catalog_import_runs
     SET imported_rows = coalesce(imported_rows, 0) + 1
   WHERE id = v_run_id;

  RETURN jsonb_build_object(
    'ok',     true,
    'run_id', v_run_id,
    'row_id', v_row_id,
    'source', p_candidate->>'source'
  );
END;
$$;


