CREATE OR REPLACE FUNCTION "public"."fn_import_register_deposit_source"("p_partner_name" "text", "p_notes" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'ingest', 'auth'
    AS $$
DECLARE
  v_actor     public.my_access%rowtype;
  v_source_id bigint;
BEGIN
  SELECT * INTO v_actor FROM public.my_access LIMIT 1;
  IF v_actor.library_id IS NULL
     OR NOT coalesce(v_actor.can_access_painel, false) THEN
    RAISE EXCEPTION 'Acesso bibliotecario obrigatorio.';
  END IF;
  IF v_actor.role IS DISTINCT FROM 'coordenador' AND NOT public.fn_caller_is_network_admin() THEN
    RAISE EXCEPTION 'Acesso restrito ao coordenador da biblioteca.';
  END IF;

  -- Cherche une source existante avec le même nom et kind
  SELECT id INTO v_source_id
    FROM ingest.partner_catalog_sources
   WHERE library_id  = v_actor.library_id
     AND source_kind = 'partner_deposit'
     AND partner_name = p_partner_name
   LIMIT 1;

  IF v_source_id IS NOT NULL THEN
    RETURN jsonb_build_object(
      'ok', true, 'source_id', v_source_id, 'created', false
    );
  END IF;

  INSERT INTO ingest.partner_catalog_sources
    (partner_name, library_id, relation_status, source_kind,
     import_enabled, notes)
  VALUES
    (p_partner_name, v_actor.library_id, 'active', 'partner_deposit',
     true, p_notes)
  RETURNING id INTO v_source_id;

  RETURN jsonb_build_object(
    'ok', true, 'source_id', v_source_id, 'created', true
  );
END;
$$;


ALTER FUNCTION "public"."fn_import_register_deposit_source"("p_partner_name" "text", "p_notes" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."fn_import_register_deposit_source"("p_partner_name" "text", "p_notes" "text") IS 'Lot 2b — Enregistre une source de type partner_deposit pour la bibliothèque active. Idempotent : retourne la source existante si le nom correspond.';



CREATE OR REPLACE FUNCTION "public"."fn_import_register_oai_source"("p_partner_name" "text", "p_oai_endpoint_url" "text", "p_library_id" "uuid", "p_oai_metadata_prefix" "text" DEFAULT 'marcxml'::"text", "p_oai_set" "text" DEFAULT NULL::"text", "p_lots_per_cycle" integer DEFAULT 5, "p_notes" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'ingest', 'auth'
    AS $$
DECLARE
  v_source_id  bigint;
  v_state_id   bigint;
BEGIN
  -- Admin réseau obligatoire
  IF NOT public.fn_caller_is_network_admin() THEN
    RAISE EXCEPTION 'Acesso restrito a administradores de rede.';
  END IF;

  -- Validation
  IF p_oai_endpoint_url IS NULL OR trim(p_oai_endpoint_url) = '' THEN
    RAISE EXCEPTION 'oai_endpoint_url obrigatorio.';
  END IF;

  IF p_library_id IS NULL THEN
    RAISE EXCEPTION 'library_id obrigatorio.';
  END IF;

  -- Cherche une source OAI existante avec le même endpoint pour la même biblio
  SELECT id INTO v_source_id
    FROM ingest.partner_catalog_sources
   WHERE library_id       = p_library_id
     AND source_kind      = 'oai_pmh'
     AND oai_endpoint_url = trim(p_oai_endpoint_url)
   LIMIT 1;

  IF v_source_id IS NOT NULL THEN
    -- Met à jour les paramètres si la source existe déjà
    UPDATE ingest.partner_catalog_sources
       SET oai_metadata_prefix = coalesce(p_oai_metadata_prefix, oai_metadata_prefix),
           oai_set             = p_oai_set,
           notes               = coalesce(p_notes, notes),
           partner_name        = coalesce(p_partner_name, partner_name),
           updated_at          = now()
     WHERE id = v_source_id;

    -- Met à jour lots_per_cycle sur le state
    UPDATE ingest.oai_harvest_state
       SET lots_per_cycle = coalesce(p_lots_per_cycle, lots_per_cycle)
     WHERE source_id = v_source_id;

    RETURN jsonb_build_object(
      'ok', true, 'source_id', v_source_id, 'created', false
    );
  END IF;

  -- Crée la source
  INSERT INTO ingest.partner_catalog_sources
    (partner_name, library_id, relation_status, source_kind,
     import_enabled, oai_endpoint_url, oai_metadata_prefix, oai_set, notes)
  VALUES
    (p_partner_name, p_library_id, 'active', 'oai_pmh',
     true, trim(p_oai_endpoint_url), coalesce(p_oai_metadata_prefix, 'marcxml'),
     p_oai_set, p_notes)
  RETURNING id INTO v_source_id;

  -- Crée la ligne harvest_state associée
  INSERT INTO ingest.oai_harvest_state (source_id, lots_per_cycle)
  VALUES (v_source_id, coalesce(p_lots_per_cycle, 5))
  RETURNING id INTO v_state_id;

  RETURN jsonb_build_object(
    'ok', true, 'source_id', v_source_id, 'state_id', v_state_id, 'created', true
  );
END;
$$;


ALTER FUNCTION "public"."fn_import_register_oai_source"("p_partner_name" "text", "p_oai_endpoint_url" "text", "p_library_id" "uuid", "p_oai_metadata_prefix" "text", "p_oai_set" "text", "p_lots_per_cycle" integer, "p_notes" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."fn_import_register_oai_source"("p_partner_name" "text", "p_oai_endpoint_url" "text", "p_library_id" "uuid", "p_oai_metadata_prefix" "text", "p_oai_set" "text", "p_lots_per_cycle" integer, "p_notes" "text") IS 'Lot 3a — Enregistre une source OAI-PMH + initialise son état de moissonnage. Réservé aux admins réseau. Idempotent : met à jour si l''endpoint existe déjà.';



CREATE OR REPLACE FUNCTION "public"."fn_import_set_editorial"("p_run_id" bigint, "p_row_ids" bigint[], "p_editorial_decision" "text", "p_editorial_note" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'ingest', 'auth'
    AS $$
DECLARE
  v_actor public.my_access%rowtype;
  v_run_library_id uuid;
BEGIN
  SELECT * INTO v_actor FROM public.my_access LIMIT 1;
  IF v_actor.library_id IS NULL
     OR NOT coalesce(v_actor.can_access_painel, false) THEN
    RAISE EXCEPTION 'Acesso bibliotecario obrigatorio.';
  END IF;
  IF v_actor.role IS DISTINCT FROM 'coordenador' AND NOT public.fn_caller_is_network_admin() THEN
    RAISE EXCEPTION 'Acesso restrito ao coordenador da biblioteca.';
  END IF;

  SELECT r.library_id INTO v_run_library_id
  FROM ingest.partner_catalog_import_runs r
  WHERE r.id = p_run_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Run % introuvable', p_run_id;
  END IF;

  IF v_run_library_id IS DISTINCT FROM v_actor.library_id THEN
    RAISE EXCEPTION 'Run % nao pertence a esta biblioteca', p_run_id;
  END IF;

  RETURN ingest.fn_set_partner_catalog_editorial_decision(
    p_run_id             := p_run_id,
    p_row_ids            := p_row_ids,
    p_editorial_decision := p_editorial_decision,
    p_editorial_note     := p_editorial_note,
    p_decided_by         := v_actor.user_id
  );
END;
$$;


