CREATE OR REPLACE FUNCTION "public"."fn_increment_negotiation_counter"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
BEGIN
  -- Détection : passage à pickup_proposed_by = 'leitor'
  -- (NULL → leitor, biblio → leitor, ou même leitor → leitor en cas de re-proposition)
  IF NEW.pickup_proposed_by = 'leitor'
     AND (OLD.pickup_proposed_by IS DISTINCT FROM NEW.pickup_proposed_by
          OR OLD.pickup_scheduled_for IS DISTINCT FROM NEW.pickup_scheduled_for) THEN

    -- Garde-fou : ne pas dépasser 3 (la contrainte CHECK rejetterait sinon)
    IF NEW.negotiation_iteration_count >= 3 THEN
      RAISE EXCEPTION 'pickup_negotiation_max_iterations_reached'
        USING ERRCODE = '22023',
              HINT = 'Garde-fou trigger : compteur d''itérations déjà à 3, contre-proposition refusée. Cette erreur ne devrait pas remonter en pratique car la RPC fn_propose_pickup_slot_as_reader vérifie aussi.';
    END IF;

    NEW.negotiation_iteration_count := COALESCE(OLD.negotiation_iteration_count, 0) + 1;
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."fn_increment_negotiation_counter"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."fn_increment_negotiation_counter"() IS 'Trigger BEFORE UPDATE qui incrémente negotiation_iteration_count quand pickup_proposed_by passe à ''leitor'' (= contre-proposition du lecteur). Semantique B (validée CCLA) : seules les contre-propositions lecteur comptent, pas les propositions/relances biblio. Garde-fou : RAISE si dépassement de 3. Spec v2 § 4.';



CREATE OR REPLACE FUNCTION "public"."fn_internal_get_vault_secret"("p_name" "text") RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'vault', 'extensions', 'pg_temp'
    AS $$
declare
  v_value text;
begin
  select ds.decrypted_secret
    into v_value
  from vault.decrypted_secrets ds
  where ds.name = p_name
  order by ds.created_at desc
  limit 1;

  if coalesce(btrim(v_value), '') = '' then
    raise exception 'Secret % introuvable ou vide dans vault.decrypted_secrets.', p_name;
  end if;

  return btrim(v_value);
end;
$$;


