COMMENT ON FUNCTION "public"."fn_is_cross_library_action"("p_library_id" "uuid") IS 'Retourne TRUE si l''appelant est admin réseau actif ET n''est pas staff local de la biblio passée en paramètre. Utile pour les RPC qui veulent déclencher un comportement différent en cas d''action transverse (par exemple, notifier le staff local). Paquet C.5b (11/05/2026).';



CREATE OR REPLACE FUNCTION "public"."fn_is_loan_blocked_by_dues"("p_user_id" "uuid", "p_library_id" "uuid") RETURNS boolean
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_enabled boolean;
  v_dues_status text;
  v_rule_required boolean;
BEGIN
  SELECT membership_enabled INTO v_enabled
  FROM public.libraries WHERE id = p_library_id;

  IF NOT COALESCE(v_enabled, false) THEN
    RETURN false;
  END IF;

  SELECT dues_status INTO v_dues_status
  FROM public.v_active_memberships
  WHERE user_id = p_user_id AND library_id = p_library_id;

  IF v_dues_status IS NULL OR v_dues_status IN ('up_to_date', 'lifetime', 'not_applicable') THEN
    RETURN false;
  END IF;

  SELECT EXISTS (
    SELECT 1 FROM public.library_membership_rules
    WHERE library_id = p_library_id
      AND is_active = true
      AND is_required = true
  ) INTO v_rule_required;

  RETURN COALESCE(v_rule_required, false);
END $$;


