CREATE TABLE IF NOT EXISTS "public"."library_partnerships" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "library_id" "uuid" NOT NULL,
    "partner_library_id" "uuid",
    "partner_catalog_id" bigint,
    "notes" "text",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "created_by" "uuid",
    "status" "text" DEFAULT 'declared'::"text" NOT NULL,
    "proposed_by" "uuid",
    "proposed_at" timestamp with time zone,
    "responded_by" "uuid",
    "responded_at" timestamp with time zone,
    "broken_by" "uuid",
    "broken_at" timestamp with time zone,
    "broken_reason" "text",
    "config_version" integer DEFAULT 1 NOT NULL,
    CONSTRAINT "library_partnerships_lifecycle_biblio_chk" CHECK ((("status" = 'declared'::"text") OR ("partner_library_id" IS NOT NULL))),
    CONSTRAINT "library_partnerships_no_self_chk" CHECK (("partner_library_id" IS DISTINCT FROM "library_id")),
    CONSTRAINT "library_partnerships_one_target_chk" CHECK (("num_nonnulls"("partner_library_id", "partner_catalog_id") = 1)),
    CONSTRAINT "library_partnerships_status_chk" CHECK (("status" = ANY (ARRAY['declared'::"text", 'proposed'::"text", 'active'::"text", 'refused'::"text", 'broken'::"text"])))
);


ALTER TABLE "public"."library_partnerships" OWNER TO "postgres";


COMMENT ON TABLE "public"."library_partnerships" IS 'Partenaires de correspondance declares par chaque bibliotheque. Une ligne = une declaration unilaterale. La cible est soit une bibliotheque AnarBib federee (partner_library_id), soit un collectif de l''annuaire catalog_partners (partner_catalog_id), exclusivement. Cf. CHANTIER_partenaires_correspondance_2026-05-24.';



COMMENT ON COLUMN "public"."library_partnerships"."library_id" IS 'Bibliotheque qui declare la correspondance (proprietaire de la ligne).';



COMMENT ON COLUMN "public"."library_partnerships"."partner_library_id" IS 'Cible si le partenaire est une autre bibliotheque AnarBib. Exclusif avec partner_catalog_id.';



COMMENT ON COLUMN "public"."library_partnerships"."partner_catalog_id" IS 'Cible si le partenaire est un collectif de catalog_partners. Exclusif avec partner_library_id.';



COMMENT ON COLUMN "public"."library_partnerships"."notes" IS 'Note de contexte libre, facultative.';



COMMENT ON COLUMN "public"."library_partnerships"."status" IS 'Cycle de vie du partenariat stabilisé (PARTNER-D7) : declared (déclaration #PARTNERS, défaut, seul état permis pour un catalog_partner) | proposed | active | refused | broken. Activation bilatérale, rupture unilatérale.';



COMMENT ON COLUMN "public"."library_partnerships"."config_version" IS 'Version de la configuration de droits (PARTNER-D8) : incrémentée à chaque AJOUT de droit, invalide le consentement lectrice (re-sollicitation vers le haut).';



CREATE OR REPLACE FUNCTION "public"."fn_library_partnership_add"("p_library_id" "uuid", "p_partner_library_id" "uuid" DEFAULT NULL::"uuid", "p_partner_catalog_id" bigint DEFAULT NULL::bigint, "p_notes" "text" DEFAULT NULL::"text") RETURNS "public"."library_partnerships"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'auth', 'pg_temp'
    AS $$
DECLARE
    v_row public.library_partnerships;
BEGIN
    -- Droit : seul le staff de coordination peut declarer un partenaire
    IF NOT public.user_can_engage_library(p_library_id) THEN
        RAISE EXCEPTION 'forbidden: caller cannot engage library %', p_library_id
            USING ERRCODE = '42501';
    END IF;

    -- Exactement une cible
    IF num_nonnulls(p_partner_library_id, p_partner_catalog_id) <> 1 THEN
        RAISE EXCEPTION 'invalid_target: exactly one of partner_library_id / partner_catalog_id required'
            USING ERRCODE = '22023';
    END IF;

    -- Pas d'auto-reference
    IF p_partner_library_id IS NOT NULL AND p_partner_library_id = p_library_id THEN
        RAISE EXCEPTION 'invalid_target: a library cannot be its own partner'
            USING ERRCODE = '22023';
    END IF;

    -- Cible existante
    IF p_partner_library_id IS NOT NULL
       AND NOT EXISTS (SELECT 1 FROM public.libraries WHERE id = p_partner_library_id) THEN
        RAISE EXCEPTION 'not_found: partner library % does not exist', p_partner_library_id
            USING ERRCODE = '23503';
    END IF;
    IF p_partner_catalog_id IS NOT NULL
       AND NOT EXISTS (SELECT 1 FROM public.catalog_partners WHERE id = p_partner_catalog_id) THEN
        RAISE EXCEPTION 'not_found: catalog partner % does not exist', p_partner_catalog_id
            USING ERRCODE = '23503';
    END IF;

    -- Pas de doublon (message clair plutot que violation d'index brute)
    IF p_partner_library_id IS NOT NULL
       AND EXISTS (SELECT 1 FROM public.library_partnerships
                   WHERE library_id = p_library_id
                     AND partner_library_id = p_partner_library_id) THEN
        RAISE EXCEPTION 'duplicate: partnership already declared'
            USING ERRCODE = '23505';
    END IF;
    IF p_partner_catalog_id IS NOT NULL
       AND EXISTS (SELECT 1 FROM public.library_partnerships
                   WHERE library_id = p_library_id
                     AND partner_catalog_id = p_partner_catalog_id) THEN
        RAISE EXCEPTION 'duplicate: partnership already declared'
            USING ERRCODE = '23505';
    END IF;

    INSERT INTO public.library_partnerships
        (library_id, partner_library_id, partner_catalog_id, notes, created_by)
    VALUES
        (p_library_id, p_partner_library_id, p_partner_catalog_id,
         NULLIF(btrim(p_notes), ''), auth.uid())
    RETURNING * INTO v_row;

    RETURN v_row;
END;
$$;


ALTER FUNCTION "public"."fn_library_partnership_add"("p_library_id" "uuid", "p_partner_library_id" "uuid", "p_partner_catalog_id" bigint, "p_notes" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."fn_library_partnership_add"("p_library_id" "uuid", "p_partner_library_id" "uuid", "p_partner_catalog_id" bigint, "p_notes" "text") IS 'Declare un partenaire de correspondance pour une bibliotheque. Validation metier complete (droits, cible unique, existence, anti-doublon). Doctrine RPC v3.';



CREATE OR REPLACE FUNCTION "public"."fn_library_partnership_remove"("p_partnership_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'auth', 'pg_temp'
    AS $$
DECLARE
    v_library_id uuid;
BEGIN
    SELECT library_id INTO v_library_id
    FROM public.library_partnerships
    WHERE id = p_partnership_id;

    IF v_library_id IS NULL THEN
        RAISE EXCEPTION 'not_found: partnership % does not exist', p_partnership_id
            USING ERRCODE = 'P0002';
    END IF;

    IF NOT public.user_can_engage_library(v_library_id) THEN
        RAISE EXCEPTION 'forbidden: caller cannot engage library %', v_library_id
            USING ERRCODE = '42501';
    END IF;

    DELETE FROM public.library_partnerships WHERE id = p_partnership_id;
END;
$$;


ALTER FUNCTION "public"."fn_library_partnership_remove"("p_partnership_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."fn_library_partnership_remove"("p_partnership_id" "uuid") IS 'Retire un partenaire de correspondance. Reserve au staff de coordination de la bibliotheque proprietaire de la relation. Doctrine RPC v3.';



CREATE OR REPLACE FUNCTION "public"."fn_library_partnership_update_notes"("p_partnership_id" "uuid", "p_notes" "text") RETURNS "public"."library_partnerships"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'auth', 'pg_temp'
    AS $$
DECLARE
    v_library_id uuid;
    v_row        public.library_partnerships;
BEGIN
    SELECT library_id INTO v_library_id
    FROM public.library_partnerships
    WHERE id = p_partnership_id;

    IF v_library_id IS NULL THEN
        RAISE EXCEPTION 'not_found: partnership % does not exist', p_partnership_id
            USING ERRCODE = 'P0002';
    END IF;

    IF NOT public.user_can_engage_library(v_library_id) THEN
        RAISE EXCEPTION 'forbidden: caller cannot engage library %', v_library_id
            USING ERRCODE = '42501';
    END IF;

    UPDATE public.library_partnerships
    SET notes = NULLIF(btrim(p_notes), '')
    WHERE id = p_partnership_id
    RETURNING * INTO v_row;

    RETURN v_row;
END;
$$;


