CREATE OR REPLACE FUNCTION "public"."fn_library_visible_to_caller"("p_library_id" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  SELECT EXISTS (
    SELECT 1
      FROM public.libraries l
     WHERE l.id = p_library_id
       AND l.is_active = true
       AND (
         -- Branche public : visible anon + auth, MAIS pas si isolated
         (l.visibility_level = 'public'
          AND l.network_mode <> 'isolated')
         OR
         -- Branche network : visible aux auth membres du reseau, MAIS pas si isolated
         (l.visibility_level = 'network'
          AND auth.uid() IS NOT NULL
          AND public.fn_current_user_is_in_network()
          AND l.network_mode <> 'isolated')
         OR
         -- Branche private : INCHANGEE — un membre voit sa biblio meme si isolated
         (l.visibility_level = 'private'
          AND auth.uid() IS NOT NULL
          AND public.fn_current_user_is_member_of(p_library_id))
       )
  );
$$;


ALTER FUNCTION "public"."fn_library_visible_to_caller"("p_library_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."fn_library_visible_to_caller"("p_library_id" "uuid") IS 'Visibilite biblio pour caller (anon/auth/membre). Etendue paquet C.2 : network_mode <> isolated sur branches public/network. Branche private inchangee.';



CREATE OR REPLACE FUNCTION "public"."fn_list_membership_payments_for_user"("p_user_id" "uuid") RETURNS TABLE("id" "uuid", "rule_id" "uuid", "rule_name" "text", "amount_paid" numeric, "currency" "text", "paid_at" timestamp with time zone, "valid_from" "date", "valid_until" "date", "payment_method" "public"."membership_payment_method", "notes" "text", "recorded_by" "uuid", "recorded_by_name" "text", "created_at" timestamp with time zone)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_actor public.my_access%rowtype;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Autenticação obrigatória.';
  END IF;

  SELECT * INTO v_actor FROM public.my_access LIMIT 1;

  IF COALESCE(v_actor.can_access_painel, false) IS false THEN
    RAISE EXCEPTION 'Acesso bibliotecário obrigatório.';
  END IF;

  IF v_actor.library_id IS NULL THEN
    RAISE EXCEPTION 'Biblioteca ativa não identificada.';
  END IF;

  RETURN QUERY
  SELECT
    mp.id,
    mp.rule_id,
    r.name AS rule_name,
    mp.amount_paid,
    mp.currency,
    mp.paid_at,
    mp.valid_from,
    mp.valid_until,
    mp.payment_method,
    mp.notes,
    mp.recorded_by,
    COALESCE(NULLIF(trim(p.first_name || ' ' || COALESCE(p.last_name, '')), ''), p.email) AS recorded_by_name,
    mp.created_at
  FROM public.membership_payments mp
  LEFT JOIN public.library_membership_rules r ON r.id = mp.rule_id
  LEFT JOIN public.profiles p ON p.id = mp.recorded_by
  WHERE mp.user_id = p_user_id
    AND mp.library_id = v_actor.library_id
  ORDER BY mp.paid_at DESC, mp.created_at DESC;
END $$;


ALTER FUNCTION "public"."fn_list_membership_payments_for_user"("p_user_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."fn_list_membership_payments_for_user"("p_user_id" "uuid") IS 'Liste les paiements de cotisation d''un usager pour la bibliothèque active. Réservé aux administrador/coordenador.';



CREATE OR REPLACE FUNCTION "public"."fn_log_cross_library_action"("p_library_id" "uuid", "p_action_type" "text", "p_is_critical" boolean DEFAULT false, "p_target_entity_type" "text" DEFAULT NULL::"text", "p_target_entity_id" "uuid" DEFAULT NULL::"uuid", "p_payload" "jsonb" DEFAULT '{}'::"jsonb") RETURNS bigint
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'auth', 'pg_temp'
    AS $$
DECLARE
    v_caller_id uuid := auth.uid();
    v_is_network_admin boolean;
    v_is_local_staff boolean;
    v_log_id bigint;
BEGIN
    -- Sans appelant authentifié, rien à logger
    IF v_caller_id IS NULL THEN
        RETURN NULL;
    END IF;
    
    -- L'appelant est-il admin réseau actif ?
    SELECT EXISTS (
        SELECT 1 FROM public.network_administrators
        WHERE user_id = v_caller_id AND status = 'active'
    ) INTO v_is_network_admin;
    
    -- Si pas admin réseau, c'est pas une action transverse, on ne logge pas
    IF NOT v_is_network_admin THEN
        RETURN NULL;
    END IF;
    
    -- L'appelant est-il aussi staff local de cette biblio ?
    SELECT EXISTS (
        SELECT 1 FROM public.user_library_memberships m
        WHERE m.user_id = v_caller_id
          AND m.library_id = p_library_id
          AND m.status = 'active'
          AND m.role = ANY (ARRAY['librarian', 'coordenador'])
    ) INTO v_is_local_staff;
    
    -- Si l'admin réseau est aussi staff local, l'action est légitimement
    -- locale, pas transverse. On ne logge pas.
    IF v_is_local_staff THEN
        RETURN NULL;
    END IF;
    
    -- C'est une action transverse : on log
    INSERT INTO public.network_admin_cross_library_actions_log
        (actor_user_id, library_id, action_type, is_critical, 
         target_entity_type, target_entity_id, payload)
    VALUES 
        (v_caller_id, p_library_id, p_action_type, p_is_critical,
         p_target_entity_type, p_target_entity_id, p_payload)
    RETURNING id INTO v_log_id;
    
    RETURN v_log_id;
END;
$$;


ALTER FUNCTION "public"."fn_log_cross_library_action"("p_library_id" "uuid", "p_action_type" "text", "p_is_critical" boolean, "p_target_entity_type" "text", "p_target_entity_id" "uuid", "p_payload" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."fn_log_cross_library_action"("p_library_id" "uuid", "p_action_type" "text", "p_is_critical" boolean, "p_target_entity_type" "text", "p_target_entity_id" "uuid", "p_payload" "jsonb") IS 'Helper d''audit : logge une action si l''appelant est admin réseau ET n''est pas staff local de la biblio cible. NOOP silencieux dans les autres cas (rien à logger). Retourne l''id du log ou NULL. À appeler depuis les RPC concernées. SECURITY DEFINER pour bypass les RLS d''écriture (la table n''accepte pas d''INSERT direct depuis authenticated). Paquet C.5b (11/05/2026).';



CREATE OR REPLACE FUNCTION "public"."fn_mark_notifications_read"("p_ids" bigint[] DEFAULT NULL::bigint[]) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF p_ids IS NULL THEN
    UPDATE user_notifications SET is_read = true, read_at = now() WHERE user_id = auth.uid() AND is_read = false;
  ELSE
    UPDATE user_notifications SET is_read = true, read_at = now() WHERE user_id = auth.uid() AND id = ANY(p_ids) AND is_read = false;
  END IF;
END;
$$;


ALTER FUNCTION "public"."fn_mark_notifications_read"("p_ids" bigint[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_membership_can_engage_circulation"("p_user_id" "uuid", "p_library_id" "uuid") RETURNS "text"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
BEGIN
  IF p_user_id IS NULL OR p_library_id IS NULL THEN
    RETURN NULL;  -- données incomplètes : laisser les autres contraintes décider
  END IF;

  -- 1. appartenance active (≡ condition 2 dans le modèle actuel)
  IF NOT EXISTS (
    SELECT 1 FROM public.user_library_memberships
    WHERE user_id = p_user_id AND library_id = p_library_id AND status = 'active'
  ) THEN
    RETURN 'no_active_membership';
  END IF;

  -- 3. pas de restriction sur une appartenance active à cette biblio
  IF EXISTS (
    SELECT 1 FROM public.user_library_memberships
    WHERE user_id = p_user_id AND library_id = p_library_id
      AND status = 'active' AND is_restricted = true
  ) THEN
    RETURN 'restricted';
  END IF;

  -- 4. cotisation à jour si la biblio l'exige
  IF public.fn_is_loan_blocked_by_dues(p_user_id, p_library_id) THEN
    RETURN 'dues';
  END IF;

  RETURN NULL;
END $$;


ALTER FUNCTION "public"."fn_membership_can_engage_circulation"("p_user_id" "uuid", "p_library_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_my_account_status"() RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_user_id uuid := auth.uid();
  v_profile record;
  v_membership record;
  v_has_profile boolean := false;
  v_has_membership boolean := false;
  v_overdue_count int;
  v_open_loans int;
  v_active_reservations int;
  v_status text;
  v_alerts jsonb := '[]'::jsonb;
  v_dues_status text := NULL;
  v_dues_valid_until date := NULL;
  v_dues_days_until_expiry int := NULL;
  v_membership_required boolean := false;
BEGIN
  IF v_user_id IS NULL THEN
    RETURN jsonb_build_object('status', 'unknown', 'alerts', '[]'::jsonb);
  END IF;

  SELECT * INTO v_profile FROM profiles WHERE id = v_user_id;
  v_has_profile := FOUND;

  -- Membership actif, primaire en priorite sinon le plus ancien (cf. 160000)
  SELECT * INTO v_membership FROM user_library_memberships
   WHERE user_id = v_user_id AND status = 'active'
   ORDER BY is_primary DESC, created_at ASC
   LIMIT 1;
  v_has_membership := FOUND;

  SELECT count(*) INTO v_overdue_count
  FROM emprestimos_v2 e JOIN emprestimo_itens_v2 ei ON ei.emprestimo_id = e.id
  WHERE e.user_id = v_user_id AND ei.item_status = 'aberto'
    AND COALESCE(ei.extended_until, ei.due_at) < CURRENT_DATE;

  SELECT count(*) INTO v_open_loans
  FROM emprestimos_v2 e JOIN emprestimo_itens_v2 ei ON ei.emprestimo_id = e.id
  WHERE e.user_id = v_user_id AND ei.item_status = 'aberto';

  SELECT count(*) INTO v_active_reservations
  FROM reservas_v2 WHERE user_id = v_user_id
    AND status_global IN ('ativa', 'parcialmente_encerrada');

  IF v_has_membership THEN
    SELECT dues_status, last_valid_until, days_until_expiry
      INTO v_dues_status, v_dues_valid_until, v_dues_days_until_expiry
    FROM v_active_memberships
    WHERE user_id = v_user_id AND library_id = v_membership.library_id;

    SELECT EXISTS (
      SELECT 1 FROM library_membership_rules
      WHERE library_id = v_membership.library_id
        AND is_active = true AND is_required = true
    ) INTO v_membership_required;
  END IF;

  -- Determine status (priorite : incomplete > gel global > restriction locale
  -- > overdue > dues > attention > active)
  IF NOT v_has_profile OR NOT v_has_membership THEN
    v_status := 'incomplete';
    v_alerts := v_alerts || jsonb_build_object('level','warn','message_key','account.alert.incomplete');
  ELSIF v_profile.is_restricted THEN
    -- Gel global reseau (priorite : portee la plus large)
    v_status := 'restricted';
    v_alerts := v_alerts || jsonb_build_object('level','danger','message_key','account.alert.restricted','reason', COALESCE(v_profile.restricted_reason, ''),'decided_by', public.fn_user_display_name(v_profile.restricted_by));
  ELSIF COALESCE(v_membership.is_restricted, false) THEN
    -- Restriction locale staff (doctrine MIXTE 28/05)
    v_status := 'restricted';
    v_alerts := v_alerts || jsonb_build_object('level','danger','message_key','account.alert.restricted.local','reason', COALESCE(v_membership.restricted_reason, ''),'decided_by', public.fn_user_display_name(v_membership.restricted_by));
  ELSIF v_overdue_count > 0 THEN
    v_status := 'attention';
    v_alerts := v_alerts || jsonb_build_object('level','danger','message_key','account.alert.overdue','count', v_overdue_count);
  ELSIF v_dues_status = 'expired' AND v_membership_required THEN
    v_status := 'attention';
    v_alerts := v_alerts || jsonb_build_object('level','danger','message_key','membership.alert.expired');
  ELSIF v_dues_status = 'never_paid' AND v_membership_required THEN
    v_status := 'attention';
    v_alerts := v_alerts || jsonb_build_object('level','warn','message_key','membership.alert.neverPaidUser');
  ELSIF v_profile.must_change_password THEN
    v_status := 'attention';
    v_alerts := v_alerts || jsonb_build_object('level','warn','message_key','account.alert.changePassword');
  ELSE
    v_status := 'active';
  END IF;

  IF v_open_loans > 0 AND v_overdue_count = 0 THEN
    v_alerts := v_alerts || jsonb_build_object('level','info','message_key','account.alert.openLoans','count', v_open_loans);
  END IF;
  IF v_active_reservations > 0 THEN
    v_alerts := v_alerts || jsonb_build_object('level','info','message_key','account.alert.activeReservations','count', v_active_reservations);
  END IF;

  IF v_dues_status = 'up_to_date'
     AND v_dues_days_until_expiry IS NOT NULL
     AND v_dues_days_until_expiry <= 30 THEN
    v_alerts := v_alerts || jsonb_build_object(
      'level','warn',
      'message_key','membership.alert.expiringSoon',
      'days', v_dues_days_until_expiry
    );
  END IF;

  RETURN jsonb_build_object(
    'status', v_status,
    'role', COALESCE(v_membership.role, 'reader'),
    'is_restricted', COALESCE(v_profile.is_restricted, false),
    'is_restricted_local', COALESCE(v_membership.is_restricted, false),
    'overdue_count', v_overdue_count,
    'open_loans', v_open_loans,
    'active_reservations', v_active_reservations,
    'dues_status', COALESCE(v_dues_status, 'not_applicable'),
    'dues_valid_until', v_dues_valid_until,
    'dues_days_until_expiry', v_dues_days_until_expiry,
    'alerts', v_alerts
  );
END;
$$;


ALTER FUNCTION "public"."fn_my_account_status"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."fn_my_account_status"() IS 'v2 30/04/2026 : fix du filtre status_global sur reservas_v2 (était comparé à des valeurs inexistantes, comptait tout). Désormais liste positive ativa + parcialmente_encerrada.';



CREATE OR REPLACE FUNCTION "public"."fn_network_admin_cancel_collective_removal"("p_proposal_id" "uuid", "p_reason" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'auth', 'pg_temp'
    AS $$
DECLARE
    v_caller_id uuid := auth.uid();
    v_proposal record;
    v_caller_voted boolean;
BEGIN
    -- Garde 1 : appelant admin réseau actif
    IF NOT fn_caller_is_network_admin() THEN
        RAISE EXCEPTION 'forbidden: only active network administrators can cancel'
            USING ERRCODE = '42501';
    END IF;

    -- Garde 2 : raison ≥ 20 caractères
    IF length(trim(coalesce(p_reason, ''))) < 20 THEN
        RAISE EXCEPTION 'reason_too_short: cancellation reason must be at least 20 characters'
            USING ERRCODE = '22023';
    END IF;

    SELECT * INTO v_proposal
        FROM public.network_admin_collective_removal_proposals
        WHERE id = p_proposal_id
        FOR UPDATE;
    
    IF NOT FOUND THEN
        RAISE EXCEPTION 'proposal_not_found' USING ERRCODE = 'P0002';
    END IF;

    IF v_proposal.status NOT IN ('open', 'unanimous') THEN
        RAISE EXCEPTION 'proposal_not_cancellable: proposal status is %', v_proposal.status
            USING ERRCODE = '22023';
    END IF;

    SELECT EXISTS (
        SELECT 1 FROM public.network_admin_collective_removal_votes
        WHERE proposal_id = p_proposal_id AND voter_user_id = v_caller_id
    ) INTO v_caller_voted;
    
    IF v_caller_id <> v_proposal.proposed_by AND NOT v_caller_voted THEN
        RAISE EXCEPTION 'only_voters_can_cancel: only the proposer or admins who voted can cancel this proposal'
            USING ERRCODE = '42501';
    END IF;

    UPDATE public.network_admin_collective_removal_proposals
        SET status = 'cancelled',
            cancelled_at = now(),
            cancelled_by = v_caller_id,
            cancellation_reason = trim(p_reason),
            pending_removal_until = NULL
        WHERE id = p_proposal_id;

    -- Si proposition unanimous, restaurer target en active
    IF v_proposal.status = 'unanimous' THEN
        UPDATE public.network_administrators
            SET status = 'active',
                removal_requested_at = NULL,
                removal_reason = NULL
            WHERE user_id = v_proposal.proposed_user_id
              AND status = 'pending_removal';
    END IF;

    INSERT INTO public.network_administrator_audit
        (user_id, event_type, actor_user_id, target_user_id, metadata)
    VALUES (
        v_proposal.proposed_user_id,
        'collective_removal_cancelled',
        v_caller_id,
        v_proposal.proposed_user_id,
        jsonb_build_object(
            'proposal_id', p_proposal_id,
            'previous_status', v_proposal.status,
            'cancellation_reason', trim(p_reason)
        )
    );

    -- 1 seul INSERT outbox. L'Edge Function décidera de notifier le target
    -- (uniquement si v_proposal.status était 'unanimous', donc déjà notifié)
    -- via le flag 'was_unanimous' dans le payload.
    PERFORM public.fn_network_notify_event(
        'network.collective_removal_cancelled',
        jsonb_build_object(
            'proposal_id', p_proposal_id,
            'proposed_user_id', v_proposal.proposed_user_id,
            'cancelled_by', v_caller_id,
            'was_unanimous', (v_proposal.status = 'unanimous'),
            'cancellation_reason', trim(p_reason)
        )
    );
END;
$$;


ALTER FUNCTION "public"."fn_network_admin_cancel_collective_removal"("p_proposal_id" "uuid", "p_reason" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."fn_network_admin_cancel_collective_removal"("p_proposal_id" "uuid", "p_reason" "text") IS 'D.6.b — Annule une proposition de retrait collectif (open ou unanimous). Annulation possible par le proposeur ou tout votant. Si proposition était unanimous, restaure target à status=active.';



CREATE OR REPLACE FUNCTION "public"."fn_network_admin_propose_collective_removal"("p_proposed_user_id" "uuid", "p_motivation" "text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'auth', 'pg_temp'
    AS $$
DECLARE
    v_caller_id uuid := auth.uid();
    v_active_count integer;
    v_proposal_id uuid;
    v_existing_open uuid;
BEGIN
    -- Garde 1 : appelant doit être admin réseau actif
    IF NOT fn_caller_is_network_admin() THEN
        RAISE EXCEPTION 'forbidden: only active network administrators can propose collective removal'
            USING ERRCODE = '42501';
    END IF;

    -- Garde 2 : target doit être admin réseau actif
    IF NOT EXISTS (
        SELECT 1 FROM public.network_administrators
        WHERE user_id = p_proposed_user_id AND status = 'active'
    ) THEN
        RAISE EXCEPTION 'target_not_active_admin: target user is not an active network administrator'
            USING ERRCODE = 'P0002';
    END IF;

    -- Garde 3 : appelant ≠ target
    IF p_proposed_user_id = v_caller_id THEN
        RAISE EXCEPTION 'use_self_remove: use fn_network_admin_self_remove for self-removal'
            USING ERRCODE = '42501';
    END IF;

    -- Garde 4 : motivation ≥ 50 caractères
    IF length(trim(coalesce(p_motivation, ''))) < 50 THEN
        RAISE EXCEPTION 'motivation_too_short: motivation must be at least 50 characters'
            USING ERRCODE = '22023';
    END IF;

    -- Garde 5 : quorum minimal ≥ 3 admins réseau actifs
    SELECT count(*) INTO v_active_count
        FROM public.network_administrators
        WHERE status = 'active';
    
    IF v_active_count < 3 THEN
        RAISE EXCEPTION 'quorum_too_small: at least 3 active network administrators required for collective removal (currently %)' , v_active_count
            USING ERRCODE = 'P0002';
    END IF;

    -- Garde 6 : pas de proposition déjà ouverte ou unanimous pour ce target
    SELECT id INTO v_existing_open
        FROM public.network_admin_collective_removal_proposals
        WHERE proposed_user_id = p_proposed_user_id
          AND status IN ('open', 'unanimous')
        LIMIT 1;
    
    IF v_existing_open IS NOT NULL THEN
        RAISE EXCEPTION 'proposal_already_open: an active proposal % already exists for this target', v_existing_open
            USING ERRCODE = '23505';
    END IF;

    -- Insertion proposition
    INSERT INTO public.network_admin_collective_removal_proposals
        (proposed_user_id, proposed_by, motivation)
    VALUES
        (p_proposed_user_id, v_caller_id, trim(p_motivation))
    RETURNING id INTO v_proposal_id;

    -- Audit
    INSERT INTO public.network_administrator_audit
        (user_id, event_type, actor_user_id, target_user_id, metadata)
    VALUES (
        p_proposed_user_id,
        'collective_removal_proposed',
        v_caller_id,
        p_proposed_user_id,
        jsonb_build_object(
            'proposal_id', v_proposal_id,
            'motivation_length', length(trim(p_motivation))
        )
    );

    -- Notification : 1 seul INSERT outbox, fan-out résolu côté Edge Function
    PERFORM public.fn_network_notify_event(
        'network.collective_removal_proposed',
        jsonb_build_object(
            'proposal_id', v_proposal_id,
            'proposed_user_id', p_proposed_user_id,
            'proposed_by', v_caller_id,
            'motivation_preview', left(trim(p_motivation), 200),
            'expires_at', (now() + interval '60 days')
        )
    );

    RETURN v_proposal_id;
END;
$$;


ALTER FUNCTION "public"."fn_network_admin_propose_collective_removal"("p_proposed_user_id" "uuid", "p_motivation" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."fn_network_admin_propose_collective_removal"("p_proposed_user_id" "uuid", "p_motivation" "text") IS 'D.6.b — Ouvre une proposition de retrait collectif. Gardes 1-6 (admin réseau actif, target admin actif, pas auto-target, motivation ≥ 50 chars, quorum ≥ 3 actifs, pas de proposition concurrente).';



CREATE OR REPLACE FUNCTION "public"."fn_network_admin_propose_cooptation"("p_user_id" "uuid", "p_motivation" "text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'auth', 'pg_temp'
    AS $$
DECLARE
    v_proposal_id uuid;
    v_caller_id uuid := auth.uid();
    v_expires_at timestamptz;
BEGIN
    -- Garde 1 : l'appelant doit etre admin reseau actif
    IF NOT fn_caller_is_network_admin() THEN
        RAISE EXCEPTION 'forbidden: only active network administrators can propose cooptation'
            USING ERRCODE = '42501';
    END IF;
    
    -- Garde 2 : la personne proposee doit exister dans auth.users
    IF NOT EXISTS (SELECT 1 FROM auth.users WHERE id = p_user_id) THEN
        RAISE EXCEPTION 'user_not_found: target user does not exist'
            USING ERRCODE = 'P0002';
    END IF;
    
    -- Garde 3 : la personne proposee ne doit pas deja etre admin reseau actif
    IF EXISTS (
        SELECT 1 FROM network_administrators 
        WHERE user_id = p_user_id AND status = 'active'
    ) THEN
        RAISE EXCEPTION 'already_admin: this person is already an active network administrator'
            USING ERRCODE = '23505';
    END IF;
    
    -- Garde 4 : pas de proposition en cours pour cette personne
    IF EXISTS (
        SELECT 1 FROM network_administrator_cooptation_proposals
        WHERE proposed_user_id = p_user_id AND status = 'open'
    ) THEN
        RAISE EXCEPTION 'proposal_exists: an open proposal already exists for this person'
            USING ERRCODE = '23505';
    END IF;
    
    -- Garde 5 : motivation suffisante
    IF length(trim(coalesce(p_motivation, ''))) < 20 THEN
        RAISE EXCEPTION 'motivation_too_short: motivation must be at least 20 characters'
            USING ERRCODE = '22023';
    END IF;
    
    -- Garde 6 : ne pas se proposer soi-meme
    IF p_user_id = v_caller_id THEN
        RAISE EXCEPTION 'self_proposal_forbidden: you cannot propose yourself'
            USING ERRCODE = '42501';
    END IF;
    
    -- Creation de la proposition
    INSERT INTO network_administrator_cooptation_proposals
        (proposed_user_id, proposed_by, motivation)
        VALUES (p_user_id, v_caller_id, p_motivation)
        RETURNING id, expires_at INTO v_proposal_id, v_expires_at;
    
    -- Vote automatique favorable du proposeur
    -- E.4.b.bis : ajout disclose_identity=TRUE (colonne NOT NULL).
    -- Le proposeur est de toute facon visible via le champ proposed_by
    -- de la proposition : garder identite disclosee est coherent.
    INSERT INTO network_administrator_cooptation_votes
        (proposal_id, voter_user_id, vote, rationale, disclose_identity)
        VALUES (v_proposal_id, v_caller_id, 'favorable',
                'Proposeur, vote implicite', TRUE);
    
    -- Audit
    INSERT INTO network_administrator_audit 
        (user_id, event_type, actor_user_id, target_user_id, metadata)
        VALUES (
            p_user_id, 
            'cooptation_proposed', 
            v_caller_id, 
            p_user_id, 
            jsonb_build_object('proposal_id', v_proposal_id, 'motivation', p_motivation)
        );
    
    -- Notification outbox (E.1bis : 1 INSERT par event, fan-out cote EF)
    PERFORM public.fn_network_notify_event(
        'network.cooptation_proposed',
        jsonb_build_object(
            'proposal_id', v_proposal_id,
            'proposed_user_id', p_user_id,
            'proposed_by', v_caller_id,
            'motivation_preview', left(trim(p_motivation), 200),
            'expires_at', v_expires_at
        )
    );
    
    RETURN v_proposal_id;
END;
$$;


ALTER FUNCTION "public"."fn_network_admin_propose_cooptation"("p_user_id" "uuid", "p_motivation" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."fn_network_admin_propose_cooptation"("p_user_id" "uuid", "p_motivation" "text") IS 'Propose la cooptation d''une personne comme administrateur réseau. Garde-fous stricts. Crée automatiquement le vote favorable du proposeur. Retourne l''ID de la proposition.';



CREATE OR REPLACE FUNCTION "public"."fn_network_admin_request_removal"("p_target_user_id" "uuid", "p_reason" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'auth', 'pg_temp'
    AS $$
BEGIN
    RAISE EXCEPTION 'deprecated: fn_network_admin_request_removal is deprecated. Use fn_network_admin_propose_collective_removal (D.6) for collective removal with unanimity voting.'
        USING ERRCODE = '0A000';  -- feature_not_supported
END;
$$;


ALTER FUNCTION "public"."fn_network_admin_request_removal"("p_target_user_id" "uuid", "p_reason" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."fn_network_admin_request_removal"("p_target_user_id" "uuid", "p_reason" "text") IS 'D.6.d — DEPRECATED. Remplacée par fn_network_admin_propose_collective_removal (workflow unanimité v0.3 Q5).';



CREATE OR REPLACE FUNCTION "public"."fn_network_admin_self_remove"("p_reason" "text" DEFAULT NULL::"text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'auth', 'pg_temp'
    AS $$
DECLARE
    v_caller_id uuid := auth.uid();
    v_remaining_admins integer;
BEGIN
    -- Garde 1 : l'appelant doit être admin réseau actif
    IF NOT fn_caller_is_network_admin() THEN
        RAISE EXCEPTION 'forbidden: only active network administrators can self-remove'
            USING ERRCODE = '42501';
    END IF;
    
    -- Compte des autres admins actifs (hors appelant)
    SELECT count(*) INTO v_remaining_admins
        FROM network_administrators
        WHERE status = 'active' AND user_id <> v_caller_id;
    
    -- Garde 2 : si l'appelant est le dernier admin, transition pending_removal
    -- avec carence de 30 jours pour permettre un workflow de récupération
    IF v_remaining_admins = 0 THEN
        UPDATE network_administrators
            SET status = 'pending_removal',
                removal_requested_at = now(),
                removal_reason = COALESCE(p_reason, 'Auto-retrait du dernier administrateur réseau')
            WHERE user_id = v_caller_id;
        
        INSERT INTO network_administrator_audit 
            (user_id, event_type, actor_user_id, target_user_id, metadata)
            VALUES (
                v_caller_id, 
                'self_removal_requested', 
                v_caller_id, 
                v_caller_id, 
                jsonb_build_object(
                    'reason', p_reason, 
                    'last_admin', true,
                    'carence_until', (now() + interval '30 days')
                )
            );
        
        RAISE NOTICE 'last_admin_pending_removal: you are the last network administrator. Status set to pending_removal with 30-day grace period.';
        RETURN;
    END IF;
    
    -- Cas normal : retrait immédiat
    UPDATE network_administrators
        SET status = 'removed',
            removed_at = now(),
            removal_reason = COALESCE(p_reason, 'Auto-retrait')
        WHERE user_id = v_caller_id;
    
    INSERT INTO network_administrator_audit 
        (user_id, event_type, actor_user_id, target_user_id, metadata)
        VALUES (
            v_caller_id, 
            'removal_completed', 
            v_caller_id, 
            v_caller_id, 
            jsonb_build_object('reason', p_reason, 'self_initiated', true)
        );
END;
$$;


ALTER FUNCTION "public"."fn_network_admin_self_remove"("p_reason" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."fn_network_admin_self_remove"("p_reason" "text") IS 'Auto-retrait d''un administrateur réseau (acte unilatéral). Si dernier admin actif, passe en pending_removal avec carence de 30 jours pour permettre une récupération du réseau.';



CREATE OR REPLACE FUNCTION "public"."fn_network_admin_vote_collective_removal"("p_proposal_id" "uuid", "p_vote" "text", "p_disclose_identity" boolean, "p_rationale" "text" DEFAULT NULL::"text") RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'auth', 'pg_temp'
    AS $$
DECLARE
    v_caller_id uuid := auth.uid();
    v_proposal record;
    v_active_others_count integer;
    v_favor_count integer;
    v_against_exists boolean;
    v_unanimous_now boolean := false;
BEGIN
    -- Garde 1 : appelant admin réseau actif
    IF NOT fn_caller_is_network_admin() THEN
        RAISE EXCEPTION 'forbidden: only active network administrators can vote'
            USING ERRCODE = '42501';
    END IF;

    -- Garde 2 : vote ∈ {favor, against}
    IF p_vote NOT IN ('favor', 'against') THEN
        RAISE EXCEPTION 'invalid_vote: vote must be favor or against'
            USING ERRCODE = '22023';
    END IF;

    -- Garde 3 : disclose_identity OBLIGATOIRE (doctrine D.5)
    IF p_disclose_identity IS NULL THEN
        RAISE EXCEPTION 'disclose_identity_required: must explicitly declare whether identity is disclosed to target'
            USING ERRCODE = '22023';
    END IF;

    -- Récup proposition
    SELECT * INTO v_proposal
        FROM public.network_admin_collective_removal_proposals
        WHERE id = p_proposal_id
        FOR UPDATE;
    
    IF NOT FOUND THEN
        RAISE EXCEPTION 'proposal_not_found' USING ERRCODE = 'P0002';
    END IF;

    -- Garde 4 : proposition ouverte
    IF v_proposal.status <> 'open' THEN
        RAISE EXCEPTION 'proposal_not_open: proposal status is %', v_proposal.status
            USING ERRCODE = '22023';
    END IF;

    -- Garde 5 : appelant ≠ target
    IF v_caller_id = v_proposal.proposed_user_id THEN
        RAISE EXCEPTION 'target_cannot_vote: the target of a removal proposal cannot vote on it'
            USING ERRCODE = '42501';
    END IF;

    -- Garde 6 : pas déjà voté
    IF EXISTS (
        SELECT 1 FROM public.network_admin_collective_removal_votes
        WHERE proposal_id = p_proposal_id AND voter_user_id = v_caller_id
    ) THEN
        RAISE EXCEPTION 'already_voted: caller has already voted on this proposal'
            USING ERRCODE = '23505';
    END IF;

    -- Garde 7 : rationale ≥ 20 caractères si against
    IF p_vote = 'against' AND length(trim(coalesce(p_rationale, ''))) < 20 THEN
        RAISE EXCEPTION 'rationale_required: rationale of at least 20 characters required when voting against'
            USING ERRCODE = '22023';
    END IF;

    -- Insertion vote
    INSERT INTO public.network_admin_collective_removal_votes
        (proposal_id, voter_user_id, vote, rationale, disclose_identity)
    VALUES
        (p_proposal_id, v_caller_id, p_vote, nullif(trim(coalesce(p_rationale, '')), ''), p_disclose_identity);

    -- Audit
    INSERT INTO public.network_administrator_audit
        (user_id, event_type, actor_user_id, target_user_id, metadata)
    VALUES (
        v_proposal.proposed_user_id,
        'collective_removal_voted',
        v_caller_id,
        v_proposal.proposed_user_id,
        jsonb_build_object(
            'proposal_id', p_proposal_id,
            'vote', p_vote,
            'disclose_identity', p_disclose_identity
        )
    );

    -- Notification : 1 seul INSERT outbox pour le vote
    PERFORM public.fn_network_notify_event(
        'network.collective_removal_vote_cast',
        jsonb_build_object(
            'proposal_id', p_proposal_id,
            'proposed_user_id', v_proposal.proposed_user_id,
            'vote', p_vote,
            'voter_user_id', CASE WHEN p_disclose_identity THEN v_caller_id ELSE NULL END,
            'disclose_identity', p_disclose_identity
        )
    );

    -- Détection unanimité
    SELECT count(*) INTO v_active_others_count
        FROM public.network_administrators
        WHERE status = 'active'
          AND user_id <> v_proposal.proposed_user_id;
    
    SELECT EXISTS (
        SELECT 1 FROM public.network_admin_collective_removal_votes
        WHERE proposal_id = p_proposal_id AND vote = 'against'
    ) INTO v_against_exists;
    
    SELECT count(*) INTO v_favor_count
        FROM public.network_admin_collective_removal_votes
        WHERE proposal_id = p_proposal_id AND vote = 'favor';

    IF NOT v_against_exists 
       AND v_favor_count = v_active_others_count
       AND v_active_others_count >= 2
    THEN
        v_unanimous_now := true;
        
        UPDATE public.network_admin_collective_removal_proposals
            SET status = 'unanimous',
                unanimous_at = now(),
                pending_removal_until = now() + interval '7 days'
            WHERE id = p_proposal_id;
        
        UPDATE public.network_administrators
            SET status = 'pending_removal',
                removal_requested_at = now(),
                removal_reason = 'Collective removal proposal ' || p_proposal_id::text
            WHERE user_id = v_proposal.proposed_user_id;
        
        INSERT INTO public.network_administrator_audit
            (user_id, event_type, actor_user_id, target_user_id, metadata)
        VALUES (
            v_proposal.proposed_user_id,
            'collective_removal_unanimous',
            v_caller_id,
            v_proposal.proposed_user_id,
            jsonb_build_object(
                'proposal_id', p_proposal_id,
                'pending_removal_until', (now() + interval '7 days')
            )
        );
        
        -- 1 seul INSERT outbox pour signaler l'unanimité
        -- L'Edge Function notifiera target ET autres admins
        PERFORM public.fn_network_notify_event(
            'network.collective_removal_unanimous',
            jsonb_build_object(
                'proposal_id', p_proposal_id,
                'proposed_user_id', v_proposal.proposed_user_id,
                'proposed_by', v_proposal.proposed_by,
                'pending_removal_until', (now() + interval '7 days')
            )
        );
    END IF;

    RETURN CASE WHEN v_unanimous_now THEN 'unanimous_carence_started' ELSE 'vote_recorded' END;
END;
$$;


ALTER FUNCTION "public"."fn_network_admin_vote_collective_removal"("p_proposal_id" "uuid", "p_vote" "text", "p_disclose_identity" boolean, "p_rationale" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."fn_network_admin_vote_collective_removal"("p_proposal_id" "uuid", "p_vote" "text", "p_disclose_identity" boolean, "p_rationale" "text") IS 'D.6.b — Vote sur une proposition de retrait collectif. disclose_identity obligatoire (D.5). rationale ≥ 20 chars si against (Garde 7). Détecte l''unanimité, déclenche la carence 7j et notifications.';



CREATE OR REPLACE FUNCTION "public"."fn_network_admin_vote_cooptation"("p_proposal_id" "uuid", "p_vote" "text", "p_disclose_identity" boolean, "p_rationale" "text" DEFAULT NULL::"text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'auth', 'pg_temp'
    AS $$
DECLARE
    v_caller_id uuid := auth.uid();
    v_proposal record;
BEGIN
    -- Garde 1 : l'appelant doit etre admin reseau actif
    IF NOT fn_caller_is_network_admin() THEN
        RAISE EXCEPTION 'forbidden: only active network administrators can vote'
            USING ERRCODE = '42501';
    END IF;
    
    -- Garde 2 : le vote doit etre valide
    IF p_vote IS NULL OR p_vote NOT IN ('favorable', 'opposed', 'abstain') THEN
        RAISE EXCEPTION 'invalid_vote: vote must be favorable, opposed, or abstain'
            USING ERRCODE = '22023';
    END IF;
    
    -- Garde 3 : la proposition doit exister
    SELECT * INTO v_proposal 
    FROM public.network_administrator_cooptation_proposals
    WHERE id = p_proposal_id;
    
    IF NOT FOUND THEN
        RAISE EXCEPTION 'proposal_not_found'
            USING ERRCODE = 'P0002';
    END IF;
    
    -- Garde 4 : la proposition doit etre ouverte
    IF v_proposal.status <> 'open' THEN
        RAISE EXCEPTION 'proposal_closed: proposal is no longer open (status=%)', v_proposal.status
            USING ERRCODE = '22023';
    END IF;
    
    -- Garde 5 : pas expiree
    IF v_proposal.expires_at < now() THEN
        RAISE EXCEPTION 'proposal_expired'
            USING ERRCODE = '22023';
    END IF;
    
    -- Garde 6 : on ne vote pas sur soi-meme
    IF v_proposal.proposed_user_id = v_caller_id THEN
        RAISE EXCEPTION 'self_vote_forbidden: you cannot vote on your own cooptation'
            USING ERRCODE = '42501';
    END IF;
    
    -- Garde 7 (Q4) : rationale obligatoire si vote=opposed
    IF p_vote = 'opposed' AND (p_rationale IS NULL OR length(trim(p_rationale)) = 0) THEN
        RAISE EXCEPTION 'rationale_required_for_opposed: rationale is mandatory when voting opposed (cf. spec v0.3 Q4)'
            USING ERRCODE = '22023';
    END IF;
    
    -- Garde 8 (Q4) : disclose_identity doit etre explicitement defini
    IF p_disclose_identity IS NULL THEN
        RAISE EXCEPTION 'disclose_identity_required: explicit disclosure choice is mandatory at each vote (cf. spec v0.3 Q4)'
            USING ERRCODE = '22023';
    END IF;
    
    -- UPSERT du vote
    INSERT INTO public.network_administrator_cooptation_votes 
        (proposal_id, voter_user_id, vote, rationale, disclose_identity, voted_at)
    VALUES (p_proposal_id, v_caller_id, p_vote, p_rationale, p_disclose_identity, now())
    ON CONFLICT (proposal_id, voter_user_id) 
    DO UPDATE SET 
        vote = EXCLUDED.vote, 
        rationale = EXCLUDED.rationale,
        disclose_identity = EXCLUDED.disclose_identity,
        voted_at = now();
    
    -- Audit
    INSERT INTO public.network_administrator_audit 
        (user_id, event_type, actor_user_id, target_user_id, metadata)
    VALUES (
        v_proposal.proposed_user_id, 
        'cooptation_voted', 
        v_caller_id, 
        v_proposal.proposed_user_id, 
        jsonb_build_object(
            'proposal_id', p_proposal_id, 
            'vote', p_vote,
            'disclose_identity', p_disclose_identity,
            'has_rationale', (p_rationale IS NOT NULL AND length(trim(p_rationale)) > 0)
        )
    );
    
    -- E.1bis : notification outbox du vote intermediaire (Q1 transparence)
    -- Le trigger trg_check_cooptation_completion ajoutera son propre event
    -- rejected/completed en post-processing s'il y a lieu.
    PERFORM public.fn_network_notify_event(
        'network.cooptation_voted',
        jsonb_build_object(
            'proposal_id', p_proposal_id,
            'proposed_user_id', v_proposal.proposed_user_id,
            'proposed_by', v_proposal.proposed_by,
            'vote', p_vote,
            'voter_user_id', CASE WHEN p_disclose_identity THEN v_caller_id ELSE NULL END,
            'disclose_identity', p_disclose_identity
        )
    );
    
    -- Le trigger trg_check_cooptation_completion s'occupe de la suite
END;
$$;


ALTER FUNCTION "public"."fn_network_admin_vote_cooptation"("p_proposal_id" "uuid", "p_vote" "text", "p_disclose_identity" boolean, "p_rationale" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."fn_network_admin_vote_cooptation"("p_proposal_id" "uuid", "p_vote" "text", "p_disclose_identity" boolean, "p_rationale" "text") IS 'Enregistre le vote d''un administrateur réseau sur une proposition de cooptation. Paquet D.5 (11/05/2026, Q4). 
Signature changée (BREAKING) : p_disclose_identity ajouté en 3e position et OBLIGATOIRE (pas de DEFAULT). 
Garde 7 : rationale obligatoire si vote=opposed (acte politique : exposer ses raisons publiquement est indissociable de l''opposition). 
disclose_identity stocké en base mais filtré dans les vues publiques pour le respect du choix politique du votant.';



CREATE OR REPLACE FUNCTION "public"."fn_network_dashboard_summary"() RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_result jsonb;
begin
  if public.fn_current_user_can_access_network_dashboard() is not true then
    raise exception 'Acesso negado ao painel da rede.'
      using errcode = '42501';
  end if;

  with
  libraries_cte as (
    select count(*)::int as total
    from public.libraries l
    where coalesce(l.is_active, true) = true
  ),
  readers_cte as (
    select count(distinct ulm.user_id)::int as total
    from public.user_library_memberships ulm
    where ulm.status = 'active'
      and ulm.role = 'reader'
  ),
  librarians_cte as (
    select count(distinct ulm.user_id)::int as total
    from public.user_library_memberships ulm
    where ulm.status = 'active'
      and ulm.role = 'librarian'
  ),
  profiles_cte as (
    select count(*)::int as total
    from public.profiles p
  ),
  loans_cte as (
    select count(*)::int as total
    from public.emprestimo_itens_v2 ei
    where ei.item_status = 'aberto'
  ),
  reservations_cte as (
    select count(*)::int as total
    from public.reserva_linhas_v2 rl
    where rl.item_status = 'ativa'
  ),
  consultations_cte as (
    select count(*)::int as total
    from public.consulta_linhas_v2 cl
    where cl.item_status = 'ativa'
  ),
  requests_pending_cte as (
    select count(*)::int as total
    from public.library_requests lr
    where lr.request_status = 'pendente'
  ),
  requests_analysis_cte as (
    select count(*)::int as total
    from public.library_requests lr
    where lr.request_status = 'em_analise'
  ),
  requests_approved_cte as (
    select count(*)::int as total
    from public.library_requests lr
    where lr.request_status = 'aprovada'
  ),
  requests_refused_cte as (
    select count(*)::int as total
    from public.library_requests lr
    where lr.request_status = 'recusada'
  )
  select jsonb_build_object(
    'libraries_total', (select total from libraries_cte),
    'profiles_total', (select total from profiles_cte),
    'readers_total', (select total from readers_cte),
    'librarians_total', (select total from librarians_cte),
    'loans_open_total', (select total from loans_cte),
    'reservations_active_total', (select total from reservations_cte),
    'consultations_active_total', (select total from consultations_cte),
    'requests_pending_total', (select total from requests_pending_cte),
    'requests_in_analysis_total', (select total from requests_analysis_cte),
    'requests_approved_total', (select total from requests_approved_cte),
    'requests_refused_total', (select total from requests_refused_cte)
  )
  into v_result;

  return coalesce(v_result, '{}'::jsonb);
end;
$$;


ALTER FUNCTION "public"."fn_network_dashboard_summary"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."fn_network_dashboard_summary"() IS 'Resumo global do AnarBib para o painel de rede.';



CREATE OR REPLACE FUNCTION "public"."fn_network_discard_library_request"("p_request_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_actor uuid := auth.uid();
  v_request public.library_requests%rowtype;
begin
  if p_request_id is null then
    raise exception 'Informe a solicitação a descartar.'
      using errcode = '23514';
  end if;

  if v_actor is not null then
    if public.fn_current_user_can_review_library_requests() is not true
       and public.fn_current_user_can_send_network_responses() is not true then
      raise exception 'Você não tem permissão para descartar solicitações.'
        using errcode = '42501';
    end if;
  end if;

  select *
  into v_request
  from public.library_requests
  where id = p_request_id
  for update;

  if not found then
    raise exception 'Solicitação não encontrada.'
      using errcode = 'P0002';
  end if;

  if coalesce(btrim(v_request.request_status), '') <> 'arquivada' then
    raise exception 'Só é possível descartar solicitações já arquivadas.'
      using errcode = '23514';
  end if;

  if nullif(btrim(coalesce(v_request.approved_library_ref, '')), '') is not null then
    raise exception 'Esta solicitação já serviu para criar uma biblioteca na rede e deve ser preservada.'
      using errcode = '23514';
  end if;

  delete from public.library_requests
  where id = v_request.id;
end;
$$;


ALTER FUNCTION "public"."fn_network_discard_library_request"("p_request_id" "uuid") OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."library_requests" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "request_status" "text" DEFAULT 'pendente'::"text" NOT NULL,
    "submitted_by_user_id" "uuid" NOT NULL,
    "submitted_by_email_snapshot" "text" NOT NULL,
    "library_name" "text" NOT NULL,
    "library_short_name" "text",
    "city" "text" NOT NULL,
    "state_region" "text",
    "country" "text" DEFAULT 'Brasil'::"text" NOT NULL,
    "library_email" "text" NOT NULL,
    "library_phone" "text",
    "library_address" "text",
    "project_stage" "text" NOT NULL,
    "contact_name" "text" NOT NULL,
    "contact_email" "text" NOT NULL,
    "contact_phone" "text",
    "contact_role" "text",
    "first_manager_intent" "text" DEFAULT 'sim'::"text" NOT NULL,
    "summary" "text" NOT NULL,
    "public_profile" "text",
    "collection_profile" "text",
    "needs" "text",
    "confirm_real" boolean DEFAULT false NOT NULL,
    "confirm_contact" boolean DEFAULT false NOT NULL,
    "review_notes" "text",
    "reviewed_at" timestamp with time zone,
    "reviewed_by_user_id" "uuid",
    "approved_library_ref" "text",
    "approved_membership_ref" "text",
    "requested_catalog_mode" "text",
    "requested_circulation_mode" "text",
    "requested_network_mode" "text",
    "requested_governance_mode" "text",
    "profile_template_chosen" "text",
    CONSTRAINT "library_requests_catalog_mode_chk" CHECK ((("requested_catalog_mode" IS NULL) OR ("requested_catalog_mode" = ANY (ARRAY['local_only'::"text", 'network_published'::"text"])))),
    CONSTRAINT "library_requests_catalog_published_requires_network_chk" CHECK ((("requested_catalog_mode" IS NULL) OR ("requested_network_mode" IS NULL) OR ("requested_catalog_mode" <> 'network_published'::"text") OR ("requested_network_mode" = ANY (ARRAY['observer'::"text", 'federated'::"text"])))),
    CONSTRAINT "library_requests_circulation_mode_chk" CHECK ((("requested_circulation_mode" IS NULL) OR ("requested_circulation_mode" = ANY (ARRAY['off'::"text", 'informal'::"text", 'full_sigb'::"text"])))),
    CONSTRAINT "library_requests_confirmations_chk" CHECK ((("confirm_real" = true) AND ("confirm_contact" = true))),
    CONSTRAINT "library_requests_contact_email_chk" CHECK ((POSITION(('@'::"text") IN ("contact_email")) > 1)),
    CONSTRAINT "library_requests_first_manager_intent_check" CHECK (("first_manager_intent" = ANY (ARRAY['sim'::"text", 'nao'::"text", 'a_definir'::"text"]))),
    CONSTRAINT "library_requests_governance_mode_chk" CHECK ((("requested_governance_mode" IS NULL) OR ("requested_governance_mode" = ANY (ARRAY['informal'::"text", 'staff_roles'::"text", 'full_governance'::"text"])))),
    CONSTRAINT "library_requests_library_email_chk" CHECK ((POSITION(('@'::"text") IN ("library_email")) > 1)),
    CONSTRAINT "library_requests_network_mode_chk" CHECK ((("requested_network_mode" IS NULL) OR ("requested_network_mode" = ANY (ARRAY['isolated'::"text", 'observer'::"text", 'federated'::"text"])))),
    CONSTRAINT "library_requests_profile_template_chk" CHECK ((("profile_template_chosen" IS NULL) OR ("profile_template_chosen" = ANY (ARRAY['A'::"text", 'B'::"text", 'C'::"text", 'D'::"text", 'custom'::"text"])))),
    CONSTRAINT "library_requests_project_stage_check" CHECK (("project_stage" = ANY (ARRAY['em_funcionamento'::"text", 'em_montagem'::"text", 'em_planejamento'::"text", 'reativacao'::"text", 'em_formacao'::"text", 'em_organizacao'::"text"]))),
    CONSTRAINT "library_requests_request_status_check" CHECK (("request_status" = ANY (ARRAY['pendente'::"text", 'em_analise'::"text", 'aprovada'::"text", 'recusada'::"text", 'arquivada'::"text"]))),
    CONSTRAINT "library_requests_submitted_email_snapshot_chk" CHECK ((POSITION(('@'::"text") IN ("submitted_by_email_snapshot")) > 1))
);


ALTER TABLE "public"."library_requests" OWNER TO "postgres";


COMMENT ON TABLE "public"."library_requests" IS 'Demandes institutionnelles d’entrée d’une bibliothèque ou d’un collectif dans le réseau AnarBib.';



COMMENT ON COLUMN "public"."library_requests"."request_status" IS 'Statut métier de la demande: pendente, em_analise, aprovada, recusada, arquivada.';



COMMENT ON COLUMN "public"."library_requests"."approved_library_ref" IS 'Référence textuelle vers la bibliothèque validée, gardée souple à ce stade pour éviter un couplage prématuré.';



COMMENT ON COLUMN "public"."library_requests"."approved_membership_ref" IS 'Référence textuelle vers le membership créé après activation, gardée souple à ce stade.';



COMMENT ON COLUMN "public"."library_requests"."requested_catalog_mode" IS 'Profil demande axe 1 (cf. spec-profils-bibliotheque.md §5.4). NULL accepte (demande incomplete). Validation a l''acceptation par admin reseau.';



COMMENT ON COLUMN "public"."library_requests"."requested_circulation_mode" IS 'Profil demande axe 2 (cf. spec-profils-bibliotheque.md §5.4).';



COMMENT ON COLUMN "public"."library_requests"."requested_network_mode" IS 'Profil demande axe 3 (cf. spec-profils-bibliotheque.md §5.4).';



COMMENT ON COLUMN "public"."library_requests"."requested_governance_mode" IS 'Profil demande axe 4 (cf. spec-profils-bibliotheque.md §5.4).';



COMMENT ON COLUMN "public"."library_requests"."profile_template_chosen" IS 'Profil-type auto-designe a l''inscription : A (athenee) / B (souveraine) / C (collectif) / D (complete) / custom. Champ statistique sans portee fonctionnelle. Cf. spec-profils-bibliotheque.md §2.7.';



