    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  select lr
  from public.library_requests lr
  where lr.id = p_request_id
    and public.fn_current_user_can_review_library_requests() is true
  limit 1;
$$;


