CREATE OR REPLACE FUNCTION "public"."fn_network_library_metrics"() RETURNS TABLE("library_id" "uuid", "library_slug" "text", "library_name" "text", "readers_total" integer, "librarians_total" integer, "loans_open_total" integer, "reservations_active_total" integer, "consultations_active_total" integer, "pending_requests_total" integer)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  with reader_counts as (
    select ulm.library_id, count(distinct ulm.user_id)::int as total
    from public.user_library_memberships ulm
    where ulm.status = 'active'
      and ulm.role = 'reader'
    group by ulm.library_id
  ),
  librarian_counts as (
    select ulm.library_id, count(distinct ulm.user_id)::int as total
    from public.user_library_memberships ulm
    where ulm.status = 'active'
      and ulm.role = 'librarian'
    group by ulm.library_id
  ),
  loan_counts as (
    select e.library_id, count(*)::int as total
    from public.emprestimo_itens_v2 ei
    join public.exemplares e
      on e.id = ei.item_id
    where ei.item_status = 'aberto'
    group by e.library_id
  ),
  reservation_counts as (
    select r.library_id, count(*)::int as total
    from public.reserva_linhas_v2 rl
    join public.reservas_v2 r
      on r.id = rl.reserva_id
    where rl.item_status = 'ativa'
    group by r.library_id
  ),
  consultation_counts as (
    select c.library_id, count(*)::int as total
    from public.consulta_linhas_v2 cl
    join public.consultas_locais_v2 c
      on c.id = cl.consulta_id
    where cl.item_status = 'ativa'
    group by c.library_id
  ),
  request_counts as (
    select l.slug, count(*)::int as total
    from public.library_requests lr
    join public.libraries l
      on lower(btrim(l.name)) = lower(btrim(lr.library_name))
       or lower(btrim(coalesce(l.short_name, ''))) = lower(btrim(coalesce(lr.library_short_name, '')))
    where lr.request_status in ('pendente', 'em_analise')
    group by l.slug
  )
  select
    l.id as library_id,
    l.slug as library_slug,
    l.name as library_name,
    coalesce(rc.total, 0) as readers_total,
    coalesce(lc.total, 0) as librarians_total,
    coalesce(loc.total, 0) as loans_open_total,
    coalesce(rsc.total, 0) as reservations_active_total,
    coalesce(cc.total, 0) as consultations_active_total,
    coalesce(rqc.total, 0) as pending_requests_total
  from public.libraries l
  left join reader_counts rc on rc.library_id = l.id
  left join librarian_counts lc on lc.library_id = l.id
  left join loan_counts loc on loc.library_id = l.id
  left join reservation_counts rsc on rsc.library_id = l.id
  left join consultation_counts cc on cc.library_id = l.id
  left join request_counts rqc on rqc.slug = l.slug
  where public.fn_current_user_can_view_network_metrics() is true
  order by lower(l.name);
$$;


ALTER FUNCTION "public"."fn_network_library_metrics"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."fn_network_library_metrics"() IS 'Métricas resumidas por biblioteca para o painel de rede.';



CREATE OR REPLACE FUNCTION "public"."fn_network_list_library_requests"() RETURNS TABLE("id" "uuid", "created_at" timestamp with time zone, "updated_at" timestamp with time zone, "request_status" "text", "library_name" "text", "library_short_name" "text", "city" "text", "state_region" "text", "country" "text", "project_stage" "text", "contact_name" "text", "contact_email" "text", "contact_phone" "text", "contact_role" "text", "submitted_by_email_snapshot" "text", "reviewed_at" timestamp with time zone, "reviewed_by_user_id" "uuid")
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  select
    lr.id,
    lr.created_at,
    lr.updated_at,
    lr.request_status,
    lr.library_name,
    lr.library_short_name,
    lr.city,
    lr.state_region,
    lr.country,
    lr.project_stage,
    lr.contact_name,
    lr.contact_email,
    lr.contact_phone,
    lr.contact_role,
    lr.submitted_by_email_snapshot,
    lr.reviewed_at,
    lr.reviewed_by_user_id
  from public.library_requests lr
  where public.fn_current_user_can_review_library_requests() is true
  order by
    case lr.request_status
      when 'pendente' then 1
      when 'em_analise' then 2
      when 'aprovada' then 3
      when 'recusada' then 4
      when 'arquivada' then 5
      else 99
    end,
    lr.created_at desc;
$$;


