CREATE OR REPLACE FUNCTION "public"."fn_network_notify_event"("p_event" "text", "p_payload" "jsonb") RETURNS bigint
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
    v_outbox_id bigint;
BEGIN
    -- Validation du préfixe : ce helper ne traite que les events 'network.%'.
    -- Pour les events 'team.%', utiliser fn_team_notify_event (symétrie).
    IF p_event IS NULL OR p_event NOT LIKE 'network.%' THEN
        RAISE WARNING 'fn_network_notify_event: event name invalid (must start with "network."): %', p_event;
        RETURN NULL;
    END IF;

    -- Insertion dans la outbox.
    -- Le trigger trg_team_outbox_dispatch déclenchera le POST vers
    -- l'Edge Function notify-event, qui résoudra le fan-out depuis le payload.
    INSERT INTO public.team_notification_outbox (event, payload)
    VALUES (p_event, COALESCE(p_payload, '{}'::jsonb))
    RETURNING id INTO v_outbox_id;

    RETURN v_outbox_id;

EXCEPTION
    WHEN OTHERS THEN
        -- Une erreur d'enregistrement notification ne doit JAMAIS faire
        -- échouer la RPC métier qui appelle ce helper.
        RAISE WARNING 'fn_network_notify_event échec INSERT outbox pour event=% : %', p_event, SQLERRM;
        RETURN NULL;
END;
$$;


ALTER FUNCTION "public"."fn_network_notify_event"("p_event" "text", "p_payload" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."fn_network_notify_event"("p_event" "text", "p_payload" "jsonb") IS 'D.6bis — Helper d''insertion outbox pour events network.%. Pendant symétrique de fn_team_notify_event. Un seul INSERT par event, fan-out résolu côté Edge Function.';



CREATE OR REPLACE FUNCTION "public"."fn_next_tombo"("p_library_id" "uuid") RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $_$
declare
  v_pat         jsonb;
  v_prefix      text;
  v_use_year    boolean;
  v_sep         text;
  v_pad         int;
  v_full_prefix text;
  v_max         bigint;
  v_next        bigint;
  v_num_str     text;
begin
  select tombo_pattern into v_pat
    from public.libraries where id = p_library_id;

  if v_pat is null then
    raise exception 'tombo_pattern_not_configured'
      using errcode = 'P0001',
            hint = format('Nenhum padrão de tombo configurado para a biblioteca %s.', p_library_id);
  end if;

  v_prefix   := coalesce(v_pat->>'prefix', '');
  v_use_year := coalesce((v_pat->>'year')::boolean, false);
  v_sep      := coalesce(v_pat->>'sep', '');
  v_pad      := coalesce((v_pat->>'pad')::int, 0);

  -- Préfixe complet de recherche (avec année courante si séquence annuelle).
  v_full_prefix := v_prefix
    || case when v_use_year then to_char(current_date, 'YYYY') || v_sep else '' end;

  -- Sérialise la génération par biblio pour la durée de la transaction :
  -- deux publications concurrentes ne peuvent pas lire le même max+1.
  perform pg_advisory_xact_lock(hashtext('tombo:' || p_library_id::text));

  -- Plus grand numéro existant sous ce préfixe (séquence à trous tolérée).
  -- NB : les préfixes en prod ne contiennent ni '%' ni '_' → LIKE sûr sans escape.
  select coalesce(max(
           (substring(e.tombo from char_length(v_full_prefix) + 1))::bigint
         ), 0)
    into v_max
    from public.exemplares e
   where e.library_id = p_library_id
     and e.tombo like v_full_prefix || '%'
     and substring(e.tombo from char_length(v_full_prefix) + 1) ~ '^[0-9]+$';

  v_next := v_max + 1;
  v_num_str := case when v_pad > 0
                    then lpad(v_next::text, v_pad, '0')
                    else v_next::text end;

  return v_full_prefix || v_num_str;
end;
$_$;


ALTER FUNCTION "public"."fn_next_tombo"("p_library_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_normalize_name"("p_name" "text") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
  SELECT coalesce(
    array_to_string(
      array(
        SELECT tok
        FROM unnest(
          regexp_split_to_array(
            translate(
              replace(replace(lower(coalesce(p_name, '')), 'œ', 'oe'), 'æ', 'ae'),
              'àáâãäåçèéêëìíîïñòóôõöøùúûüýÿ',
              'aaaaaaceeeeiiiinoooooouuuuyy'
            ),
            '[^a-z0-9]+'
          )
        ) AS tok
        WHERE tok <> ''
        ORDER BY tok
      ),
      ' '
    ),
    ''
  );
$$;


ALTER FUNCTION "public"."fn_normalize_name"("p_name" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."fn_normalize_name"("p_name" "text") IS 'Normalise un nom (minuscules, accents replies, tokens alphanum tries) pour matching d''autorite. Paquet liaison autorites du 05/06/2026.';



CREATE OR REPLACE FUNCTION "public"."fn_notify_document_permission_request_now"("p_request_id" "uuid", "p_event_type" "text", "p_event_key" "text" DEFAULT NULL::"text") RETURNS bigint
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_row public.document_permission_requests%rowtype;
begin
  if auth.uid() is null then
    raise exception 'Autenticação obrigatória.'
      using errcode = '42501';
  end if;

  select *
    into v_row
  from public.document_permission_requests
  where id = p_request_id
  limit 1;

  if v_row.id is null then
    raise exception 'Solicitação interbibliotecas não encontrada.'
      using errcode = 'P0002';
  end if;

  if not (
    public.user_can_manage_library(v_row.requester_library_id)
    or public.user_can_manage_library(v_row.target_library_id)
  ) then
    raise exception 'Você não tem permissão para reenviar notificações desta solicitação.'
      using errcode = '42501';
  end if;

  return public.fn_enqueue_document_permission_request_notification(
    p_request_id := p_request_id,
    p_event_type := p_event_type,
    p_event_key := p_event_key,
    p_triggered_by_user_id := auth.uid()
  );
end;
$$;


ALTER FUNCTION "public"."fn_notify_document_permission_request_now"("p_request_id" "uuid", "p_event_type" "text", "p_event_key" "text") OWNER TO "postgres";


