CREATE OR REPLACE FUNCTION "public"."fn_notify_lph_executed"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_payload jsonb;
BEGIN
  -- Note : library_profile_history n'a pas de proposal_id direct, c'est un
  -- log d'événement. Le mail 'executed' renvoie donc vers la page profil
  -- biblio (et non vers une proposition spécifique).
  v_payload := jsonb_build_object(
    'library_id', NEW.library_id,
    'axis',       NEW.axis,
    'old_value',  NEW.old_value,
    'new_value',  NEW.new_value,
    'actor_id',   NEW.changed_by,
    'changed_by', NEW.changed_by,
    'changed_at', NEW.changed_at,
    'motivation', NEW.motivation,
    'history_id', NEW.id
  );

  PERFORM public.fn_network_notify_event('network.library_profile.executed', v_payload);

  RETURN NEW;

EXCEPTION
  WHEN OTHERS THEN
    RAISE WARNING 'fn_notify_lph_executed échec pour history_id=% : %', NEW.id, SQLERRM;
    RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."fn_notify_lph_executed"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."fn_notify_lph_executed"() IS 'Trigger function (B.5) : publie network.library_profile.executed dans l''outbox sur INSERT history. Notifie staff de la biblio + admins réseau (transition appliquée = info publique).';



CREATE OR REPLACE FUNCTION "public"."fn_notify_lpp_lifecycle"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_payload jsonb;
BEGIN
  -- =====================
  -- Cas A : INSERT
  -- =====================
  IF TG_OP = 'INSERT' THEN

    -- Type 1 (direct) → status créé directement à 'completed', pas de
    -- délibération. On laisse le trigger history s'occuper de 'executed'.
    -- On ne notifie 'proposed' que si la proposition entre réellement en vote.
    IF NEW.status = 'open' THEN
      v_payload := jsonb_build_object(
        'library_id',          NEW.library_id,
        'proposal_id',         NEW.id,
        'axis',                NEW.axis,
        'old_value',           NEW.old_value,
        'new_value',           NEW.new_value,
        'transition_type',     NEW.transition_type,
        'governance_required', NEW.governance_required,
        'motivation',          NEW.motivation,
        'actor_id',            NEW.proposed_by,
        'proposed_by',         NEW.proposed_by,
        'proposed_at',         NEW.proposed_at,
        'expires_at',          NEW.expires_at
      );
      PERFORM public.fn_team_notify_event('team.library_profile.proposed', v_payload);
    END IF;

    RETURN NEW;
  END IF;

  -- =====================
  -- Cas B : UPDATE (status transitions)
  -- =====================
  IF TG_OP = 'UPDATE' AND NEW.status IS DISTINCT FROM OLD.status THEN

    -- B.1 — accepted_unanimous | accepted_majority → network.*
    IF NEW.status IN ('accepted_unanimous', 'accepted_majority') THEN
      v_payload := jsonb_build_object(
        'library_id',          NEW.library_id,
        'proposal_id',         NEW.id,
        'axis',                NEW.axis,
        'old_value',           NEW.old_value,
        'new_value',           NEW.new_value,
        'transition_type',     NEW.transition_type,
        'governance_required', NEW.governance_required,
        'motivation',          NEW.motivation,
        'actor_id',            NEW.proposed_by,
        'proposed_by',         NEW.proposed_by,
        'proposed_at',         NEW.proposed_at,
        'accepted_status',     NEW.status,
        'unanimous_at',        NEW.unanimous_at,
        'majority_at',         NEW.majority_at,
        'grace_period_until',  NEW.grace_period_until
      );
      PERFORM public.fn_network_notify_event('network.library_profile.accepted', v_payload);

    -- B.2 — rejected | expired → team.*
    ELSIF NEW.status IN ('rejected', 'expired') THEN
      v_payload := jsonb_build_object(
        'library_id',      NEW.library_id,
        'proposal_id',     NEW.id,
        'axis',            NEW.axis,
        'old_value',       NEW.old_value,
        'new_value',       NEW.new_value,
        'transition_type', NEW.transition_type,
        'motivation',      NEW.motivation,
        'actor_id',        NEW.proposed_by,
        'proposed_by',     NEW.proposed_by,
        'reason',          NEW.status  -- 'rejected' ou 'expired'
      );
      PERFORM public.fn_team_notify_event('team.library_profile.rejected', v_payload);

    -- B.3 — cancelled → team.*
    ELSIF NEW.status = 'cancelled' THEN
      v_payload := jsonb_build_object(
        'library_id',           NEW.library_id,
        'proposal_id',          NEW.id,
        'axis',                 NEW.axis,
        'old_value',            NEW.old_value,
        'new_value',            NEW.new_value,
        'transition_type',      NEW.transition_type,
        'motivation',           NEW.motivation,
        'actor_id',             NEW.cancelled_by,
        'proposed_by',          NEW.proposed_by,
        'cancelled_by',         NEW.cancelled_by,
        'cancelled_at',         NEW.cancelled_at,
        'cancelled_motivation', NEW.cancelled_motivation
      );
      PERFORM public.fn_team_notify_event('team.library_profile.cancelled', v_payload);

    -- B.4 — 'completed' : pas de notif ici, la notif executed est levée
    -- par le trigger sur library_profile_history (déclenché par fn_execute_*).
    END IF;

    RETURN NEW;
  END IF;

  RETURN NEW;

EXCEPTION
  WHEN OTHERS THEN
    -- Une erreur de notification ne doit JAMAIS faire échouer la RPC métier.
    RAISE WARNING 'fn_notify_lpp_lifecycle échec pour proposal_id=% : %', NEW.id, SQLERRM;
    RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."fn_notify_lpp_lifecycle"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."fn_notify_lpp_lifecycle"() IS 'Trigger function (B.5) : publie team.library_profile.{proposed,rejected,cancelled} et network.library_profile.accepted dans l''outbox. Robuste aux erreurs notification (WARNING + continue).';



CREATE OR REPLACE FUNCTION "public"."fn_notify_lpv_cast"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_proposal record;
  v_vote_count int;
  v_active_staff_count int;
  v_payload jsonb;
BEGIN
  -- On a besoin des infos de la proposition (library_id, axis, proposed_by)
  -- pour construire le payload. Lookup minimal.
  SELECT id, library_id, axis, old_value, new_value, transition_type,
         governance_required, proposed_by, motivation
  INTO v_proposal
  FROM public.library_profile_proposals
  WHERE id = NEW.proposal_id;

  IF NOT FOUND THEN
    RAISE WARNING 'fn_notify_lpv_cast : proposal % introuvable, skip notif', NEW.proposal_id;
    RETURN NEW;
  END IF;

  -- Compteur de votes actuel (utilisé pour la doctrine #21 : le proposeur
  -- n'est notifié QUE sur le 1er vote, puis silencieux jusqu'au résultat).
  SELECT COUNT(*)::int INTO v_vote_count
  FROM public.library_profile_votes
  WHERE proposal_id = NEW.proposal_id;

  -- Staff actif total (pour afficher « N/M voix » dans le mail).
  v_active_staff_count := public.fn_library_active_staff_count(v_proposal.library_id);

  v_payload := jsonb_build_object(
    'library_id',          v_proposal.library_id,
    'proposal_id',         v_proposal.id,
    'axis',                v_proposal.axis,
    'old_value',           v_proposal.old_value,
    'new_value',           v_proposal.new_value,
    'transition_type',     v_proposal.transition_type,
    'governance_required', v_proposal.governance_required,
    'motivation',          v_proposal.motivation,
    'actor_id',            NEW.voter_id,
    'proposed_by',         v_proposal.proposed_by,
    'vote',                NEW.vote,
    'rationale_against',   NEW.rationale_against,
    'voter_id',            NEW.voter_id,
    'voted_at',            NEW.voted_at,
    'vote_count',          v_vote_count,
    'active_staff_count',  v_active_staff_count,
    -- Hint pour l'EF : proposeur notifié uniquement si vote_count = 1
    'is_first_vote',       (v_vote_count = 1)
  );

  PERFORM public.fn_team_notify_event('team.library_profile.voted', v_payload);

  RETURN NEW;

EXCEPTION
  WHEN OTHERS THEN
    RAISE WARNING 'fn_notify_lpv_cast échec pour vote sur proposal=% : %', NEW.proposal_id, SQLERRM;
    RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."fn_notify_lpv_cast"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."fn_notify_lpv_cast"() IS 'Trigger function (B.5) : publie team.library_profile.voted dans l''outbox sur INSERT vote. Inclut vote_count et is_first_vote pour la doctrine proposeur silencieux après 1er vote (mémoire #21).';



CREATE OR REPLACE FUNCTION "public"."fn_notify_users_before_purge"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_lib record;
  v_policy jsonb;
  v_loans_days int;
  v_reservations_days int;
  v_consultations_days int;
  v_notifications_days int;
  v_warn_window_days int := 30;
  v_total_notified int := 0;
  v_total_dispatched int := 0;
  v_count_local int;
  v_dispatched_local int;
  v_inserted_id bigint;
  v_started_at timestamptz := now();
  v_inserted_row record;
BEGIN
  FOR v_lib IN
    SELECT id, slug, name FROM public.libraries WHERE is_active = true
  LOOP
    v_policy := public.fn_get_retention_policy(v_lib.id);
    v_loans_days := (v_policy->>'retention_loans_days')::int;
    v_reservations_days := (v_policy->>'retention_reservations_days')::int;
    v_consultations_days := (v_policy->>'retention_consultations_days')::int;
    v_notifications_days := (v_policy->>'retention_notifications_days')::int;

    -- ─── Emprunts ────────────────────────────────────────────────────────
    IF v_loans_days > 0 THEN
      v_count_local := 0;
      v_dispatched_local := 0;
      FOR v_inserted_row IN
        WITH eligible_users AS (
          SELECT DISTINCT e.user_id
          FROM emprestimos_v2 e
          WHERE e.library_id = v_lib.id
            AND e.status_global = 'encerrado'
            AND NOT EXISTS (
              SELECT 1 FROM emprestimo_itens_v2 ei
              WHERE ei.emprestimo_id = e.id
                AND (
                  ei.item_status = 'aberto'
                  OR COALESCE(ei.return_completed_at, ei.returned_at, ei.updated_at) > (now() - ((v_loans_days - v_warn_window_days) || ' days')::interval)
                )
            )
        )
        INSERT INTO user_notifications (user_id, library_id, category, title, body, is_read)
        SELECT
          eu.user_id,
          v_lib.id,
          'rgpd_retention_loans',
          'notif.rgpd.purgeWarning.loans.title',
          'notif.rgpd.purgeWarning.loans.body',
          false
        FROM eligible_users eu
        WHERE NOT EXISTS (
          SELECT 1 FROM user_notifications n
          WHERE n.user_id = eu.user_id
            AND n.library_id = v_lib.id
            AND n.category = 'rgpd_retention_loans'
            AND n.created_at > (now() - interval '40 days')
        )
        RETURNING id
      LOOP
        v_count_local := v_count_local + 1;
        -- Dispatch e-mail (phase 1 : l'EF ignorera, c'est attendu)
        IF public.fn_dispatch_rgpd_warning(v_inserted_row.id, 'rgpd_purge_warning_loans') IS NOT NULL THEN
          v_dispatched_local := v_dispatched_local + 1;
        END IF;
      END LOOP;
      v_total_notified := v_total_notified + v_count_local;
      v_total_dispatched := v_total_dispatched + v_dispatched_local;
    END IF;

    -- ─── Réservations ───────────────────────────────────────────────────
    IF v_reservations_days > 0 THEN
      v_count_local := 0;
      v_dispatched_local := 0;
      FOR v_inserted_row IN
        WITH eligible_users AS (
          SELECT DISTINCT r.user_id
          FROM reservas_v2 r
          WHERE r.library_id = v_lib.id
            AND r.status_global IN ('encerrada', 'cancelada')
            AND NOT EXISTS (
              SELECT 1 FROM reserva_linhas_v2 rl
              WHERE rl.reserva_id = r.id
                AND COALESCE(rl.cancelled_at, rl.converted_at, rl.expired_at, rl.updated_at) > (now() - ((v_reservations_days - v_warn_window_days) || ' days')::interval)
            )
        )
        INSERT INTO user_notifications (user_id, library_id, category, title, body, is_read)
        SELECT
          eu.user_id,
          v_lib.id,
          'rgpd_retention_reservations',
          'notif.rgpd.purgeWarning.reservations.title',
          'notif.rgpd.purgeWarning.reservations.body',
          false
        FROM eligible_users eu
        WHERE NOT EXISTS (
          SELECT 1 FROM user_notifications n
          WHERE n.user_id = eu.user_id
            AND n.library_id = v_lib.id
            AND n.category = 'rgpd_retention_reservations'
            AND n.created_at > (now() - interval '40 days')
        )
        RETURNING id
      LOOP
        v_count_local := v_count_local + 1;
        IF public.fn_dispatch_rgpd_warning(v_inserted_row.id, 'rgpd_purge_warning_reservations') IS NOT NULL THEN
          v_dispatched_local := v_dispatched_local + 1;
        END IF;
      END LOOP;
      v_total_notified := v_total_notified + v_count_local;
      v_total_dispatched := v_total_dispatched + v_dispatched_local;
    END IF;

    -- ─── Consultations ──────────────────────────────────────────────────
    IF v_consultations_days > 0 THEN
      v_count_local := 0;
      v_dispatched_local := 0;
      FOR v_inserted_row IN
        WITH eligible_users AS (
          SELECT DISTINCT c.user_id
          FROM consultas_locais_v2 c
          WHERE c.library_id = v_lib.id
            AND c.status_global IN ('encerrada', 'cancelada')
            AND NOT EXISTS (
              SELECT 1 FROM consulta_linhas_v2 cl
              WHERE cl.consulta_id = c.id
                AND COALESCE(cl.cancelled_at, cl.consulted_at, cl.expired_at, cl.updated_at) > (now() - ((v_consultations_days - v_warn_window_days) || ' days')::interval)
            )
        )
        INSERT INTO user_notifications (user_id, library_id, category, title, body, is_read)
        SELECT
          eu.user_id,
          v_lib.id,
          'rgpd_retention_consultations',
          'notif.rgpd.purgeWarning.consultations.title',
          'notif.rgpd.purgeWarning.consultations.body',
          false
        FROM eligible_users eu
        WHERE NOT EXISTS (
          SELECT 1 FROM user_notifications n
          WHERE n.user_id = eu.user_id
            AND n.library_id = v_lib.id
            AND n.category = 'rgpd_retention_consultations'
            AND n.created_at > (now() - interval '40 days')
        )
        RETURNING id
      LOOP
        v_count_local := v_count_local + 1;
        IF public.fn_dispatch_rgpd_warning(v_inserted_row.id, 'rgpd_purge_warning_consultations') IS NOT NULL THEN
          v_dispatched_local := v_dispatched_local + 1;
        END IF;
      END LOOP;
      v_total_notified := v_total_notified + v_count_local;
      v_total_dispatched := v_total_dispatched + v_dispatched_local;
    END IF;

    -- Pas de notif pour les notifications elles-mêmes (méta-récursivité préservée).
  END LOOP;

  RETURN jsonb_build_object(
    'mode', 'notify',
    'started_at', v_started_at,
    'finished_at', now(),
    'total_notifications_created', v_total_notified,
    -- Nouveau champ phase 1 : nombre de dispatchs e-mail tentés.
    -- Phase 1 : ce nombre = total_notifications_created si tous les dispatchs
    -- réussissent (HTTP 200 retourné par l'EF, même si elle ignore l'event).
    -- Phase 2 : ce sera le nombre de mails effectivement envoyés.
    'total_dispatches_attempted', v_total_dispatched
  );
END;
$$;


