    SET "search_path" TO 'public'
    AS $$
  select * from public.fn_painel_find_profile_by_lookup(p_email);
$$;


ALTER FUNCTION "public"."fn_painel_find_profile_by_email"("p_email" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_painel_find_profile_by_lookup"("p_lookup" "text") RETURNS "public"."profiles"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_row public.profiles;
  v_lookup text := trim(coalesce(p_lookup, ''));
  v_public_id text := upper(v_lookup);
  v_email text := lower(v_lookup);
  v_profile_found boolean := false;
begin
  if auth.uid() is null then
    raise exception 'authentication required';
  end if;

  if v_lookup = '' then
    raise exception 'Informe um ID público ou e-mail.';
  end if;

  select p.*
    into v_row
  from public.profiles p
  where upper(coalesce(trim(p.public_id), '')) = v_public_id
  limit 1;

  if v_row.id is not null then
    v_profile_found := true;
    if public.can_manage_profile_from_my_libraries(v_row.id) then
      return v_row;
    end if;
    raise exception 'Cadastro encontrado, mas ele não pertence à biblioteca ativa deste painel.';
  end if;

  select p.*
    into v_row
  from public.profiles p
  where lower(coalesce(trim(p.email), '')) = v_email
  limit 1;

  if v_row.id is not null then
    v_profile_found := true;
    if public.can_manage_profile_from_my_libraries(v_row.id) then
      return v_row;
    end if;
    raise exception 'Cadastro encontrado, mas ele não pertence à biblioteca ativa deste painel.';
  end if;

  if not v_profile_found then
    raise exception 'Não encontrei esse ID público ou e-mail no cadastro da biblioteca ativa.';
  end if;

  raise exception 'Não consegui localizar esse cadastro.';
end;
$$;


ALTER FUNCTION "public"."fn_painel_find_profile_by_lookup"("p_lookup" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_painel_get_profile_by_id"("p_profile_id" "uuid") RETURNS "public"."profiles"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_row public.profiles;
begin
  if auth.uid() is null then
    raise exception 'authentication required';
  end if;

  if p_profile_id is null then
    raise exception 'Cadastro sem identificador válido.';
  end if;

  select p.*
    into v_row
  from public.profiles p
  where p.id = p_profile_id
  limit 1;

  if v_row.id is null then
    raise exception 'Cadastro não encontrado.';
  end if;

  if not public.can_manage_profile_from_my_libraries(v_row.id) then
    raise exception 'Este cadastro não pertence à biblioteca ativa deste painel.';
  end if;

  return v_row;
end;
$$;


