CREATE OR REPLACE FUNCTION "public"."fn_painel_reader_other_memberships"("p_user_id" "uuid", "p_viewer_library_id" "uuid") RETURNS TABLE("enriched" boolean, "library_id" "uuid", "library_name" "text", "membership_status" "text", "is_restricted" boolean)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
BEGIN
  IF NOT public.user_can_act_as_staff_on_library(p_viewer_library_id) THEN
    RAISE EXCEPTION 'Acesso restrito ao staff da biblioteca.'
      USING ERRCODE = '42501', HINT = 'error.partnership.forbidden';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM public.user_library_memberships m
                 WHERE m.user_id = p_user_id AND m.library_id = p_viewer_library_id
                   AND m.status = 'active') THEN
    RETURN;
  END IF;
  RETURN QUERY
  WITH others AS (
    SELECT m.library_id AS lib, m.status AS st,
           COALESCE(m.is_restricted, false) AS restr,
           COALESCE(l.short_name, l.name) AS lname,
           public.fn_partnership_transparence_active(p_viewer_library_id, m.library_id, p_user_id) AS ok
    FROM public.user_library_memberships m
    JOIN public.libraries l ON l.id = m.library_id
    WHERE m.user_id = p_user_id AND m.status = 'active'
      AND m.library_id <> p_viewer_library_id
  )
  SELECT o.ok,
         CASE WHEN o.ok THEN o.lib END,
         CASE WHEN o.ok THEN o.lname END,
         CASE WHEN o.ok THEN o.st END,
         CASE WHEN o.ok THEN o.restr END
  FROM others o;
END $$;


ALTER FUNCTION "public"."fn_painel_reader_other_memberships"("p_user_id" "uuid", "p_viewer_library_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_partner_register_deposit_source"("p_display_name" "text", "p_base_url" "text" DEFAULT ''::"text", "p_country_code" "text" DEFAULT NULL::"text", "p_notes" "text" DEFAULT NULL::"text", "p_import_authorized" boolean DEFAULT true) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'ingest', 'auth'
    AS $$
DECLARE
  v_actor           public.my_access%rowtype;
  v_slug            text;
  v_partner_id      bigint;
  v_partner_created boolean := false;
  v_source_id       bigint;
  v_source_created  boolean := false;
  v_partner_status  text;
  v_source_status   text;
BEGIN
  SELECT * INTO v_actor FROM public.my_access LIMIT 1;
  IF v_actor.library_id IS NULL OR NOT coalesce(v_actor.can_access_painel, false) THEN
    RAISE EXCEPTION 'Acesso bibliotecario obrigatorio.';
  END IF;
  IF v_actor.role IS DISTINCT FROM 'coordenador' AND NOT public.fn_caller_is_network_admin() THEN
    RAISE EXCEPTION 'Acesso restrito ao coordenador da biblioteca.';
  END IF;

  IF coalesce(trim(p_display_name), '') = '' THEN
    RAISE EXCEPTION 'Nome do parceiro obrigatorio.';
  END IF;

  v_slug := trim(both '-' from regexp_replace(lower(trim(p_display_name)), '[^a-z0-9]+', '-', 'g'));
  IF v_slug = '' THEN
    RAISE EXCEPTION 'Nome do parceiro invalido (slug vazio).';
  END IF;

  -- Vocabulaires DISTINCTS entre les deux tables :
  v_partner_status := CASE WHEN p_import_authorized THEN 'importacao_autorizada' ELSE 'identificada' END; -- catalog_partners
  v_source_status  := CASE WHEN p_import_authorized THEN 'importacao_autorizada' ELSE 'mapeada' END;       -- partner_catalog_sources

  -- Dédup : entité existante par slug exact -> réutilisée
  SELECT id INTO v_partner_id FROM public.catalog_partners WHERE slug = v_slug LIMIT 1;
  IF v_partner_id IS NULL THEN
    INSERT INTO public.catalog_partners
      (slug, display_name, base_url, country_code, notes,
       integration_mode, relationship_status, is_active)
    VALUES
      (v_slug, trim(p_display_name), coalesce(nullif(trim(p_base_url), ''), ''),
       nullif(trim(p_country_code), ''), nullif(trim(p_notes), ''),
       'file_deposit', v_partner_status, true)
    RETURNING id INTO v_partner_id;
    v_partner_created := true;
  END IF;

  -- Source de dépôt de CETTE biblio, reliée à l'entité
  SELECT id INTO v_source_id
    FROM ingest.partner_catalog_sources
   WHERE library_id = v_actor.library_id
     AND source_kind = 'partner_deposit'
     AND (catalog_partner_id = v_partner_id OR partner_name = trim(p_display_name))
   LIMIT 1;

  IF v_source_id IS NULL THEN
    INSERT INTO ingest.partner_catalog_sources
      (partner_name, library_id, relation_status, source_kind,
       import_enabled, notes, catalog_partner_id)
    VALUES
      (trim(p_display_name), v_actor.library_id, v_source_status, 'partner_deposit',
       p_import_authorized, nullif(trim(p_notes), ''), v_partner_id)
    RETURNING id INTO v_source_id;
    v_source_created := true;
  ELSE
    UPDATE ingest.partner_catalog_sources
       SET catalog_partner_id = coalesce(catalog_partner_id, v_partner_id),
           import_enabled = p_import_authorized
     WHERE id = v_source_id;
  END IF;

  RETURN jsonb_build_object(
    'ok', true,
    'partner_id', v_partner_id,
    'partner_slug', v_slug,
    'partner_created', v_partner_created,
    'source_id', v_source_id,
    'source_created', v_source_created
  );
END;
$$;


ALTER FUNCTION "public"."fn_partner_register_deposit_source"("p_display_name" "text", "p_base_url" "text", "p_country_code" "text", "p_notes" "text", "p_import_authorized" boolean) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."fn_partner_register_deposit_source"("p_display_name" "text", "p_base_url" "text", "p_country_code" "text", "p_notes" "text", "p_import_authorized" boolean) IS 'Crée (ou réutilise par slug) une entité catalog_partners de dépôt + la source ingest.partner_catalog_sources liée pour la biblio appelante (coordenador). p_import_authorized -> relationship_status importacao_autorizada + import_enabled.';



CREATE OR REPLACE FUNCTION "public"."fn_partner_search"("p_query" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'auth'
    AS $$
DECLARE
  v_actor  public.my_access%rowtype;
  v_q      text;
  v_result jsonb;
BEGIN
  SELECT * INTO v_actor FROM public.my_access LIMIT 1;
  IF v_actor.library_id IS NULL OR NOT coalesce(v_actor.can_access_painel, false) THEN
    RAISE EXCEPTION 'Acesso bibliotecario obrigatorio.';
  END IF;

  v_q := '%' || trim(coalesce(p_query, '')) || '%';
  IF length(trim(coalesce(p_query, ''))) < 2 THEN
    RETURN '[]'::jsonb;
  END IF;

  SELECT coalesce(jsonb_agg(to_jsonb(t)), '[]'::jsonb) INTO v_result
  FROM (
    SELECT id, slug, display_name, country_code, relationship_status
    FROM public.catalog_partners
    WHERE is_active AND (display_name ILIKE v_q OR slug ILIKE v_q)
    ORDER BY display_name
    LIMIT 8
  ) t;

  RETURN v_result;
END;
$$;


ALTER FUNCTION "public"."fn_partner_search"("p_query" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."fn_partner_search"("p_query" "text") IS 'Recherche de partenaires catalog_partners (nom/slug, ILIKE) pour la détection de doublon avant création. Staff de bibliothèque uniquement.';



CREATE OR REPLACE FUNCTION "public"."fn_partnership_accept"("p_partnership_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
DECLARE v_a uuid; v_b uuid; v_status text;
BEGIN
  SELECT library_id, partner_library_id, status INTO v_a, v_b, v_status FROM public.library_partnerships WHERE id=p_partnership_id;
  IF v_a IS NULL THEN RAISE EXCEPTION 'Parceria inexistente.' USING HINT='error.partnership.not_found'; END IF;
  IF v_status <> 'proposed' THEN RAISE EXCEPTION 'Esta parceria não está pendente.' USING HINT='error.partnership.not_pending'; END IF;
  IF NOT public.user_can_engage_library(v_b) THEN RAISE EXCEPTION 'Acesso restrito à coordenação da biblioteca parceira.' USING ERRCODE='42501', HINT='error.partnership.forbidden'; END IF;
  IF EXISTS (SELECT 1 FROM public.library_partnerships WHERE library_id=v_b AND partner_library_id=v_a) THEN
    UPDATE public.library_partnerships SET status='active', responded_by=auth.uid(), responded_at=now(), broken_by=NULL, broken_at=NULL, broken_reason=NULL WHERE library_id=v_b AND partner_library_id=v_a;
  ELSE
    INSERT INTO public.library_partnerships (library_id, partner_library_id, status, responded_by, responded_at, created_by) VALUES (v_b, v_a, 'active', auth.uid(), now(), auth.uid());
  END IF;
  UPDATE public.library_partnerships SET status='active', responded_by=auth.uid(), responded_at=now() WHERE id=p_partnership_id;
  PERFORM public.fn_dispatch_notify_event('partnership_accepted', 1, jsonb_build_object('partnership_id', p_partnership_id::text, 'recipient_library_id', v_a::text, 'partner_library_id', v_b::text));
END $$;


ALTER FUNCTION "public"."fn_partnership_accept"("p_partnership_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_partnership_break"("p_partnership_id" "uuid", "p_reason" "text" DEFAULT NULL::"text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
DECLARE v_a uuid; v_b uuid; v_status text;
BEGIN
  SELECT library_id, partner_library_id, status INTO v_a, v_b, v_status FROM public.library_partnerships WHERE id=p_partnership_id;
  IF v_a IS NULL OR v_b IS NULL THEN RAISE EXCEPTION 'Parceria inexistente.' USING HINT='error.partnership.not_found'; END IF;
  IF v_status <> 'active' THEN RAISE EXCEPTION 'Apenas uma parceria ativa pode ser rompida.' USING HINT='error.partnership.not_active'; END IF;
  IF NOT (public.user_can_engage_library(v_a) OR public.user_can_engage_library(v_b)) THEN RAISE EXCEPTION 'Acesso restrito à coordenação de uma das bibliotecas.' USING ERRCODE='42501', HINT='error.partnership.forbidden'; END IF;
  UPDATE public.library_partnerships SET status='broken', broken_by=auth.uid(), broken_at=now(), broken_reason=NULLIF(btrim(p_reason),'') WHERE (library_id=v_a AND partner_library_id=v_b) OR (library_id=v_b AND partner_library_id=v_a);
  DELETE FROM public.partnership_rights pr USING public.library_partnerships lp WHERE pr.partnership_id=lp.id AND ((lp.library_id=v_a AND lp.partner_library_id=v_b) OR (lp.library_id=v_b AND lp.partner_library_id=v_a));
  INSERT INTO public.partnership_break_log (partnership_id, library_id, partner_library_id, broken_by, reason) VALUES (p_partnership_id, v_a, v_b, auth.uid(), NULLIF(btrim(p_reason),''));
  PERFORM public.fn_dispatch_notify_event('partnership_broken', 1, jsonb_build_object('partnership_id', p_partnership_id::text, 'recipient_library_id', v_a::text, 'partner_library_id', v_b::text));
  PERFORM public.fn_dispatch_notify_event('partnership_broken', 1, jsonb_build_object('partnership_id', p_partnership_id::text, 'recipient_library_id', v_b::text, 'partner_library_id', v_a::text));
END $$;


ALTER FUNCTION "public"."fn_partnership_break"("p_partnership_id" "uuid", "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_partnership_canonical_id"("p_partnership_id" "uuid") RETURNS "uuid"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
  SELECT CASE
           WHEN src.library_id < src.partner_library_id THEN src.id
           ELSE recip.id
         END
  FROM public.library_partnerships src
  LEFT JOIN public.library_partnerships recip
    ON recip.library_id = src.partner_library_id
   AND recip.partner_library_id = src.library_id
  WHERE src.id = p_partnership_id
    AND src.partner_library_id IS NOT NULL
  LIMIT 1;
$$;


ALTER FUNCTION "public"."fn_partnership_canonical_id"("p_partnership_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_partnership_consent"("p_partnership_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_canon uuid; v_a uuid; v_b uuid; v_status text; v_cv integer; v_uid uuid;
BEGIN
  v_uid := auth.uid();
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'Autenticação necessária.' USING ERRCODE = '42501';
  END IF;

  v_canon := public.fn_partnership_canonical_id(p_partnership_id);
  IF v_canon IS NULL THEN
    RAISE EXCEPTION 'Parceria inexistente.' USING HINT = 'error.partnership.not_found';
  END IF;

  SELECT library_id, partner_library_id, status, config_version
    INTO v_a, v_b, v_status, v_cv
    FROM public.library_partnerships WHERE id = v_canon;

  IF v_status <> 'active' THEN
    RAISE EXCEPTION 'A parceria não está ativa.' USING HINT = 'error.partnership.not_active';
  END IF;

  -- Lectrice COMMUNE : appartenance active dans les DEUX biblios de la paire.
  IF NOT (EXISTS (SELECT 1 FROM public.user_library_memberships
                  WHERE user_id = v_uid AND library_id = v_a AND status = 'active')
      AND EXISTS (SELECT 1 FROM public.user_library_memberships
                  WHERE user_id = v_uid AND library_id = v_b AND status = 'active')) THEN
    RAISE EXCEPTION 'Apenas leitor(a/e) comum às duas bibliotecas pode consentir.'
      USING HINT = 'error.partnership.not_common_reader';
  END IF;

  INSERT INTO public.reader_partnership_consent
    (user_id, partnership_id, config_version, consented_at, revoked_at, updated_at)
  VALUES (v_uid, v_canon, v_cv, now(), NULL, now())
  ON CONFLICT (user_id, partnership_id) DO UPDATE
    SET config_version = EXCLUDED.config_version,
        consented_at   = now(),
        revoked_at     = NULL,
        updated_at     = now();
END $$;


ALTER FUNCTION "public"."fn_partnership_consent"("p_partnership_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_partnership_list_mine"("p_library_id" "uuid") RETURNS TABLE("partnership_id" "uuid", "direction" "text", "status" "text", "partner_library_id" "uuid", "partner_name" "text", "rights" "text"[])
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
BEGIN
  IF NOT public.user_can_engage_library(p_library_id) THEN
    RAISE EXCEPTION 'Acesso restrito à coordenação da biblioteca.'
      USING ERRCODE = '42501', HINT = 'error.partnership.forbidden';
  END IF;
  RETURN QUERY
  SELECT lp.id, 'incoming'::text, lp.status, lp.library_id, COALESCE(l.short_name, l.name), NULL::text[]
  FROM public.library_partnerships lp JOIN public.libraries l ON l.id = lp.library_id
  WHERE lp.partner_library_id = p_library_id AND lp.status = 'proposed'
  UNION ALL
  SELECT lp.id, CASE lp.status WHEN 'proposed' THEN 'outgoing' ELSE lp.status END, lp.status,
         lp.partner_library_id, COALESCE(l.short_name, l.name),
         CASE WHEN lp.status = 'active'
              THEN (SELECT array_agg(pr.right_key ORDER BY pr.right_key)
                    FROM public.partnership_rights pr WHERE pr.partnership_id = lp.id)
              ELSE NULL END
  FROM public.library_partnerships lp JOIN public.libraries l ON l.id = lp.partner_library_id
  WHERE lp.library_id = p_library_id AND lp.partner_library_id IS NOT NULL
    AND lp.status IN ('proposed', 'active', 'refused', 'broken')
  ORDER BY 2, 5;
END $$;


ALTER FUNCTION "public"."fn_partnership_list_mine"("p_library_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_partnership_propose"("p_library_id" "uuid", "p_partner_library_id" "uuid") RETURNS "public"."library_partnerships"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
DECLARE v_row public.library_partnerships; v_status text;
BEGIN
  IF NOT public.user_can_engage_library(p_library_id) THEN RAISE EXCEPTION 'Acesso restrito à coordenação da biblioteca.' USING ERRCODE='42501', HINT='error.partnership.forbidden'; END IF;
  IF p_partner_library_id IS NULL OR p_partner_library_id = p_library_id THEN RAISE EXCEPTION 'Parceiro inválido.' USING HINT='error.partnership.invalid_target'; END IF;
  IF NOT EXISTS (SELECT 1 FROM public.libraries WHERE id=p_partner_library_id) THEN RAISE EXCEPTION 'Biblioteca parceira inexistente.' USING HINT='error.partnership.partner_not_found'; END IF;
  IF EXISTS (SELECT 1 FROM public.library_partnerships WHERE library_id=p_partner_library_id AND partner_library_id=p_library_id AND status='proposed') THEN RAISE EXCEPTION 'A biblioteca parceira já propôs : utilize aceitar.' USING HINT='error.partnership.use_accept'; END IF;
  SELECT status INTO v_status FROM public.library_partnerships WHERE library_id=p_library_id AND partner_library_id=p_partner_library_id;
  IF v_status IN ('proposed','active') THEN RAISE EXCEPTION 'Parceria já em curso ou ativa.' USING HINT='error.partnership.already';
  ELSIF v_status IS NULL THEN
    INSERT INTO public.library_partnerships (library_id, partner_library_id, status, proposed_by, proposed_at, created_by)
    VALUES (p_library_id, p_partner_library_id, 'proposed', auth.uid(), now(), auth.uid()) RETURNING * INTO v_row;
  ELSE
    UPDATE public.library_partnerships SET status='proposed', proposed_by=auth.uid(), proposed_at=now(), responded_by=NULL, responded_at=NULL, broken_by=NULL, broken_at=NULL, broken_reason=NULL
     WHERE library_id=p_library_id AND partner_library_id=p_partner_library_id RETURNING * INTO v_row;
  END IF;
  PERFORM public.fn_dispatch_notify_event('partnership_proposed', 1, jsonb_build_object('partnership_id', v_row.id::text, 'recipient_library_id', p_partner_library_id::text, 'partner_library_id', p_library_id::text));
  RETURN v_row;
END $$;


ALTER FUNCTION "public"."fn_partnership_propose"("p_library_id" "uuid", "p_partner_library_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_partnership_reciprocal_id"("p_partnership_id" "uuid") RETURNS "uuid"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
  SELECT r.id
  FROM public.library_partnerships src
  JOIN public.library_partnerships r
    ON r.library_id = src.partner_library_id
   AND r.partner_library_id = src.library_id
  WHERE src.id = p_partnership_id
    AND src.partner_library_id IS NOT NULL
  LIMIT 1;
$$;


ALTER FUNCTION "public"."fn_partnership_reciprocal_id"("p_partnership_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_partnership_refuse"("p_partnership_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
DECLARE v_a uuid; v_b uuid; v_status text;
BEGIN
  SELECT library_id, partner_library_id, status INTO v_a, v_b, v_status FROM public.library_partnerships WHERE id=p_partnership_id;
  IF v_b IS NULL THEN RAISE EXCEPTION 'Parceria inexistente.' USING HINT='error.partnership.not_found'; END IF;
  IF v_status <> 'proposed' THEN RAISE EXCEPTION 'Esta parceria não está pendente.' USING HINT='error.partnership.not_pending'; END IF;
  IF NOT public.user_can_engage_library(v_b) THEN RAISE EXCEPTION 'Acesso restrito à coordenação da biblioteca parceira.' USING ERRCODE='42501', HINT='error.partnership.forbidden'; END IF;
  UPDATE public.library_partnerships SET status='refused', responded_by=auth.uid(), responded_at=now() WHERE id=p_partnership_id;
  PERFORM public.fn_dispatch_notify_event('partnership_refused', 1, jsonb_build_object('partnership_id', p_partnership_id::text, 'recipient_library_id', v_a::text, 'partner_library_id', v_b::text));
END $$;


ALTER FUNCTION "public"."fn_partnership_refuse"("p_partnership_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_partnership_revoke_consent"("p_partnership_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_canon uuid; v_uid uuid;
BEGIN
  v_uid := auth.uid();
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'Autenticação necessária.' USING ERRCODE = '42501';
  END IF;
  v_canon := public.fn_partnership_canonical_id(p_partnership_id);
  IF v_canon IS NULL THEN
    RAISE EXCEPTION 'Parceria inexistente.' USING HINT = 'error.partnership.not_found';
  END IF;

  -- Retrait = pose revoked_at (la transparence retombe au minimum immédiatement
  -- via la RLS P4). Idempotent : sans ligne, no-op.
  UPDATE public.reader_partnership_consent
     SET revoked_at = now(), updated_at = now()
   WHERE user_id = v_uid AND partnership_id = v_canon AND revoked_at IS NULL;
END $$;


ALTER FUNCTION "public"."fn_partnership_revoke_consent"("p_partnership_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_partnership_set_right"("p_partnership_id" "uuid", "p_right_key" "text", "p_enabled" boolean) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_a uuid; v_b uuid; v_status text; v_existe boolean;
BEGIN
  SELECT library_id, partner_library_id, status INTO v_a, v_b, v_status
    FROM public.library_partnerships WHERE id = p_partnership_id;
  IF v_a IS NULL OR v_b IS NULL THEN
    RAISE EXCEPTION 'Parceria inexistente.' USING HINT = 'error.partnership.not_found';
  END IF;
  IF v_status <> 'active' THEN
    RAISE EXCEPTION 'Os direitos só podem ser ajustados numa parceria ativa.'
      USING HINT = 'error.partnership.not_active';
  END IF;
  IF p_right_key NOT IN ('transparence','digital_share','mutualisation','peb') THEN
    RAISE EXCEPTION 'Direito desconhecido.' USING HINT = 'error.partnership.unknown_right';
  END IF;
  IF NOT (public.user_can_engage_library(v_a) OR public.user_can_engage_library(v_b)) THEN
    RAISE EXCEPTION 'Acesso restrito à coordenação de uma das bibliotecas.'
      USING ERRCODE = '42501', HINT = 'error.partnership.forbidden';
  END IF;

  IF p_enabled THEN
    v_existe := EXISTS (SELECT 1 FROM public.partnership_rights
                        WHERE partnership_id = p_partnership_id AND right_key = p_right_key);
    -- Insert sur la direction courante ; le trigger réplique sur la réciproque.
    INSERT INTO public.partnership_rights (partnership_id, right_key, granted_by)
      VALUES (p_partnership_id, p_right_key, auth.uid())
    ON CONFLICT (partnership_id, right_key) DO NOTHING;
    -- AJOUT d'un droit = la config s'élargit → bump config_version des deux côtés
    -- (invalide le consentement lectrice, re-sollicitation « vers le haut », D8).
    IF NOT v_existe THEN
      UPDATE public.library_partnerships
         SET config_version = config_version + 1
       WHERE (library_id = v_a AND partner_library_id = v_b)
          OR (library_id = v_b AND partner_library_id = v_a);
      IF p_right_key = 'transparence' THEN
        -- NOTIF-2 : transparence nouvellement activée → inviter les lectrices
        -- communes (membres des deux biblios) à consentir (/conta).
        PERFORM public.fn_dispatch_notify_event('partnership_transparence_enabled', 1, jsonb_build_object(
          'partnership_id', p_partnership_id::text,
          'library_a', v_a::text,
          'library_b', v_b::text));
      ELSE
        -- NOTIF-3 : autre droit ajouté → la config s'élargit → re-solliciter les
        -- lectrices au consentement devenu stale (handler : id canonique requis).
        PERFORM public.fn_dispatch_notify_event('partnership_config_expanded', 1, jsonb_build_object(
          'partnership_id', public.fn_partnership_canonical_id(p_partnership_id)::text,
          'library_a', v_a::text,
          'library_b', v_b::text));
      END IF;
    END IF;
  ELSE
    -- RETRAIT : la config se restreint → consentement maintenu, pas de bump (D8).
    DELETE FROM public.partnership_rights
     WHERE partnership_id = p_partnership_id AND right_key = p_right_key;
  END IF;
END $$;


ALTER FUNCTION "public"."fn_partnership_set_right"("p_partnership_id" "uuid", "p_right_key" "text", "p_enabled" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_partnership_sync_rights"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_recip uuid;
BEGIN
  IF TG_OP = 'INSERT' THEN
    v_recip := public.fn_partnership_reciprocal_id(NEW.partnership_id);
    IF v_recip IS NOT NULL THEN
      -- ON CONFLICT DO NOTHING : si déjà présent, aucune ligne insérée donc
      -- l'AFTER INSERT ne re-déclenche pas → terminaison de la récursion.
      INSERT INTO public.partnership_rights (partnership_id, right_key, granted_by)
        VALUES (v_recip, NEW.right_key, NEW.granted_by)
      ON CONFLICT (partnership_id, right_key) DO NOTHING;
    END IF;
  ELSIF TG_OP = 'DELETE' THEN
    v_recip := public.fn_partnership_reciprocal_id(OLD.partnership_id);
    IF v_recip IS NOT NULL THEN
      -- suppression idempotente : 0 ligne supprimée → pas de re-déclenchement.
      DELETE FROM public.partnership_rights
       WHERE partnership_id = v_recip AND right_key = OLD.right_key;
    END IF;
  END IF;
  RETURN NULL;  -- AFTER trigger
END $$;


ALTER FUNCTION "public"."fn_partnership_sync_rights"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_partnership_sync_status"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
BEGIN
  -- Seuls les partenariats biblio↔biblio sont symétrisés ; on ne propage que les
  -- états bilatéraux (active/broken/refused). 'proposed' reste unilatéral (P2 crée
  -- la réciproque à l'acceptation). Garde anti-récursion : WHERE status DISTINCT.
  IF NEW.partner_library_id IS NOT NULL
     AND NEW.status IS DISTINCT FROM OLD.status
     AND NEW.status IN ('active','broken','refused') THEN
    UPDATE public.library_partnerships r
       SET status = NEW.status
     WHERE r.library_id = NEW.partner_library_id
       AND r.partner_library_id = NEW.library_id
       AND r.status IS DISTINCT FROM NEW.status;
  END IF;
  RETURN NULL;  -- AFTER trigger
END $$;


ALTER FUNCTION "public"."fn_partnership_sync_status"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_partnership_transparence_active"("p_library_a" "uuid", "p_library_b" "uuid", "p_user_id" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
  SELECT EXISTS (
    SELECT 1
    FROM public.library_partnerships lp
    WHERE lp.library_id = p_library_a
      AND lp.partner_library_id = p_library_b
      AND lp.status = 'active'
      AND EXISTS (SELECT 1 FROM public.partnership_rights pr
                  WHERE pr.partnership_id = lp.id AND pr.right_key = 'transparence')
      AND public.fn_reader_consent_valid(p_user_id, lp.id)
  );
$$;


ALTER FUNCTION "public"."fn_partnership_transparence_active"("p_library_a" "uuid", "p_library_b" "uuid", "p_user_id" "uuid") OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."interlibrary_loans_v2" (
    "id" bigint NOT NULL,
    "request_id" "uuid",
    "lender_library_id" "uuid" NOT NULL,
    "borrower_library_id" "uuid" NOT NULL,
    "initiated_by_library_id" "uuid" NOT NULL,
    "status_global" "text" DEFAULT 'preparacao'::"text" NOT NULL,
    "start_date" "date",
    "due_date" "date",
    "dispatched_at" timestamp with time zone,
    "return_started_at" timestamp with time zone,
    "returned_at" timestamp with time zone,
    "coordination_contact_name" "text",
    "coordination_contact_email" "text",
    "coordination_contact_phone" "text",
    "logistics_mode" "text",
    "meeting_point" "text",
    "notes" "text",
    "metadata" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "created_at" timestamp with time zone DEFAULT "timezone"('utc'::"text", "now"()) NOT NULL,
    "created_by" "uuid",
    "updated_at" timestamp with time zone DEFAULT "timezone"('utc'::"text", "now"()) NOT NULL,
    "updated_by" "uuid",
    "archived_at" timestamp with time zone,
    "archive_reason" "text",
    CONSTRAINT "interlibrary_loans_v2_archive_consistency_chk" CHECK ((("archived_at" IS NULL) = ("archive_reason" IS NULL))),
    CONSTRAINT "interlibrary_loans_v2_archive_reason_chk" CHECK ((("archive_reason" IS NULL) OR ("archive_reason" = ANY (ARRAY['profile_transition'::"text", 'admin_manual'::"text", 'system_cleanup'::"text"])))),
    CONSTRAINT "interlibrary_loans_v2_diff_libraries_chk" CHECK (("lender_library_id" <> "borrower_library_id")),
    CONSTRAINT "interlibrary_loans_v2_due_after_start_chk" CHECK ((("start_date" IS NULL) OR ("due_date" IS NULL) OR ("due_date" >= "start_date"))),
    CONSTRAINT "interlibrary_loans_v2_logistics_mode_chk" CHECK ((("logistics_mode" IS NULL) OR ("logistics_mode" = ANY (ARRAY['envio_postal'::"text", 'entrega_em_maos'::"text", 'transporte_militante'::"text", 'a_combinar'::"text"])))),
    CONSTRAINT "interlibrary_loans_v2_no_self_loan_chk" CHECK (("lender_library_id" <> "borrower_library_id")),
    CONSTRAINT "interlibrary_loans_v2_status_chk" CHECK (("status_global" = ANY (ARRAY['preparacao'::"text", 'aguardando_saida'::"text", 'emprestado'::"text", 'parcialmente_devolvido'::"text", 'em_devolucao'::"text", 'devolvido'::"text", 'cancelado'::"text", 'atrasado'::"text"])))
);


ALTER TABLE "public"."interlibrary_loans_v2" OWNER TO "postgres";


COMMENT ON TABLE "public"."interlibrary_loans_v2" IS 'Prêts inter-bibliothèques (en-tête). Anon SELECT révoqué le 2026-04-26 (palier 3). Accès via api.interlibrary_loans_painel_ui.';



CREATE OR REPLACE FUNCTION "public"."fn_peb_archive_loan"("p_loan_id" bigint) RETURNS "public"."interlibrary_loans_v2"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'auth', 'pg_temp'
    AS $$
DECLARE
    v_loan public.interlibrary_loans_v2;
BEGIN
    SELECT * INTO v_loan
    FROM public.interlibrary_loans_v2
    WHERE id = p_loan_id;

    IF v_loan.id IS NULL THEN
        RAISE EXCEPTION 'not_found: PEB % does not exist', p_loan_id
            USING ERRCODE = 'P0002';
    END IF;

    -- Droit : staff de la prêteuse OU de l'emprunteuse
    IF NOT (
        public.user_can_act_as_staff_on_library(v_loan.lender_library_id)
        OR public.user_can_act_as_staff_on_library(v_loan.borrower_library_id)
    ) THEN
        RAISE EXCEPTION 'forbidden: caller is not staff of either library of PEB %', p_loan_id
            USING ERRCODE = '42501';
    END IF;

    -- Seul un PEB en statut terminal est archivable
    IF v_loan.status_global NOT IN ('devolvido', 'cancelado') THEN
        RAISE EXCEPTION 'invalid_state: PEB % is not terminal (status=%)',
            p_loan_id, v_loan.status_global
            USING ERRCODE = '22023';
    END IF;

    IF v_loan.archived_at IS NOT NULL THEN
        RAISE EXCEPTION 'already_archived: PEB % is already archived', p_loan_id
            USING ERRCODE = '22023';
    END IF;

    -- archived_at ET archive_reason posés ENSEMBLE (archive_consistency_chk).
    -- 'admin_manual' = archivage manuel par le staff (archive_reason_chk).
    UPDATE public.interlibrary_loans_v2
    SET archived_at    = timezone('utc', now()),
        archive_reason = 'admin_manual',
        updated_at     = timezone('utc', now()),
        updated_by     = auth.uid()
    WHERE id = p_loan_id
    RETURNING * INTO v_loan;

    RETURN v_loan;
END;
$$;


ALTER FUNCTION "public"."fn_peb_archive_loan"("p_loan_id" bigint) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."fn_peb_archive_loan"("p_loan_id" bigint) IS 'Archive un PEB terminé (devolvido/cancelado) : pose archived_at + archive_reason = ''admin_manual'' (archivage manuel). Réservé au staff de l''une ou l''autre des deux bibliothèques. Doctrine RPC v3.';



CREATE OR REPLACE FUNCTION "public"."fn_peb_authorized"("p_lender_library_id" "uuid", "p_borrower_library_id" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  SELECT
    p_lender_library_id IS DISTINCT FROM p_borrower_library_id
    AND public.fn_library_has_circulation(p_lender_library_id)
    AND public.fn_library_has_circulation(p_borrower_library_id)
    AND public.fn_library_is_federated(p_lender_library_id)
    AND public.fn_library_is_federated(p_borrower_library_id);
$$;


ALTER FUNCTION "public"."fn_peb_authorized"("p_lender_library_id" "uuid", "p_borrower_library_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."fn_peb_authorized"("p_lender_library_id" "uuid", "p_borrower_library_id" "uuid") IS 'Vrai si les 2 bibs peuvent participer a un PEB (circulation actif + federated des deux cotes). Helper composite paquet C.3c.';



CREATE OR REPLACE FUNCTION "public"."fn_peb_consolidate_loan_status"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_loan_id bigint;
  v_current_status text;
  v_total int;
  v_settled int;
  v_outstanding int;
  v_new_status text;
BEGIN
  -- L'id du pret parent selon l'operation.
  IF tg_op = 'DELETE' THEN
    v_loan_id := old.interlibrary_loan_id;
  ELSE
    v_loan_id := new.interlibrary_loan_id;
  END IF;

  -- Statut courant du pret parent.
  SELECT status_global INTO v_current_status
  FROM interlibrary_loans_v2
  WHERE id = v_loan_id;

  IF NOT FOUND THEN
    -- Pret parent absent (ex. CASCADE en cours) : rien a faire.
    RETURN COALESCE(new, old);
  END IF;

  -- GARDE-FOU DE PHASE : on ne consolide que si le pret est dans une phase
  -- ou un retour d'exemplaire a un sens. En 'preparacao' ou 'aguardando_saida'
  -- (pas encore parti), ou en 'devolvido'/'cancelado' (deja clos), on ne
  -- touche a rien.
  IF v_current_status NOT IN ('emprestado', 'em_devolucao', 'atrasado', 'parcialmente_devolvido') THEN
    RETURN COALESCE(new, old);
  END IF;

  -- Comptage des exemplaires du pret.
  --   regle    = devolvido | perdido | danificado | cancelado
  --   dehors   = emprestado | reservado_para_saida
  SELECT
    count(*),
    count(*) FILTER (WHERE item_status IN ('devolvido','perdido','danificado','cancelado')),
    count(*) FILTER (WHERE item_status IN ('emprestado','reservado_para_saida'))
  INTO v_total, v_settled, v_outstanding
  FROM interlibrary_loan_items_v2
  WHERE interlibrary_loan_id = v_loan_id;

  -- Pret sans aucun exemplaire : rien a consolider.
  IF v_total = 0 THEN
    RETURN COALESCE(new, old);
  END IF;

  -- Regle de consolidation.
  IF v_settled = v_total THEN
    -- Tous les exemplaires sont regles -> pret entierement devolu.
    v_new_status := 'devolvido';
  ELSIF v_settled > 0 AND v_outstanding > 0 THEN
    -- Une partie reglee, une partie encore dehors -> retour partiel.
    v_new_status := 'parcialmente_devolvido';
  ELSE
    -- Aucun exemplaire regle (tout est encore dehors) : on ne touche pas.
    RETURN COALESCE(new, old);
  END IF;

  -- N'ecrit QUE si la valeur change reellement, pour ne pas reveiller
  -- le trigger de notification pour rien.
  IF v_new_status IS DISTINCT FROM v_current_status THEN
    UPDATE interlibrary_loans_v2
    SET status_global = v_new_status,
        updated_at = timezone('utc'::text, now())
    WHERE id = v_loan_id;
  END IF;

  RETURN COALESCE(new, old);
END;
$$;


ALTER FUNCTION "public"."fn_peb_consolidate_loan_status"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_peb_create_loan_with_items"("p_loan" "jsonb", "p_items" "jsonb" DEFAULT '[]'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_new_loan interlibrary_loans_v2%ROWTYPE;
  v_new_items jsonb;
  v_item jsonb;
  v_item_id bigint;
  v_holding_id bigint;
  v_unavailable boolean;
BEGIN
  -- Validation minimale : les champs obligatoires doivent être présents
  IF (p_loan->>'lender_library_id') IS NULL
     OR (p_loan->>'borrower_library_id') IS NULL
     OR (p_loan->>'initiated_by_library_id') IS NULL
  THEN
    RAISE EXCEPTION 'fn_peb_create_loan_with_items: champs obligatoires manquants (lender, borrower, initiated_by)';
  END IF;

  -- INSERT du loan. La RLS interlibrary_loans_v2_insert vérifie automatiquement :
  --   - user_can_manage_library(lender OR borrower)
  --   - fn_peb_authorized(lender, borrower)  [inclut lender <> borrower]
  INSERT INTO interlibrary_loans_v2 (
    request_id,
    lender_library_id,
    borrower_library_id,
    initiated_by_library_id,
    status_global,
    start_date,
    due_date,
    coordination_contact_name,
    coordination_contact_email,
    coordination_contact_phone,
    logistics_mode,
    meeting_point,
    notes,
    metadata,
    created_by
  )
  VALUES (
    NULLIF(p_loan->>'request_id', '')::uuid,
    (p_loan->>'lender_library_id')::uuid,
    (p_loan->>'borrower_library_id')::uuid,
    (p_loan->>'initiated_by_library_id')::uuid,
    COALESCE(p_loan->>'status_global', 'preparacao'),
    NULLIF(p_loan->>'start_date', '')::date,
    NULLIF(p_loan->>'due_date', '')::date,
    p_loan->>'coordination_contact_name',
    p_loan->>'coordination_contact_email',
    p_loan->>'coordination_contact_phone',
    p_loan->>'logistics_mode',
    p_loan->>'meeting_point',
    p_loan->>'notes',
    COALESCE(p_loan->'metadata', '{}'::jsonb),
    auth.uid()
  )
  RETURNING * INTO v_new_loan;

  -- INSERT des items (si fournis)
  IF jsonb_array_length(p_items) > 0 THEN
    FOR v_item IN SELECT * FROM jsonb_array_elements(p_items) LOOP
      -- Validation minimale par item
      IF (v_item->>'line_no') IS NULL
         OR (v_item->>'holding_id') IS NULL
         OR (v_item->>'item_id') IS NULL
         OR (v_item->>'bib_ref') IS NULL
      THEN
        RAISE EXCEPTION 'fn_peb_create_loan_with_items: item invalide (line_no, holding_id, item_id, bib_ref obligatoires) — item: %', v_item;
      END IF;

      v_item_id := (v_item->>'item_id')::bigint;
      v_holding_id := (v_item->>'holding_id')::bigint;

      -- #ILL-availability — garde dure : l'exemplaire doit etre disponible
      -- AU MOMENT de la creation. Couvre le cas ou il a ete pris (emprunt,
      -- reservation, consultation, autre PEB) entre la recherche et la
      -- validation. Memes 4 circuits que fn_peb_search_exemplares.
      SELECT (
           EXISTS (SELECT 1 FROM emprestimo_itens_v2 ei
                   WHERE ei.item_id = v_item_id AND ei.item_status = 'aberto')
        OR EXISTS (SELECT 1 FROM reserva_linhas_v2 rl
                   WHERE rl.item_id = v_item_id AND rl.item_status = 'ativa')
        OR EXISTS (SELECT 1 FROM interlibrary_loan_items_v2 ili
                   WHERE ili.item_id = v_item_id
                     AND ili.item_status IN ('reservado_para_saida','emprestado'))
        OR EXISTS (SELECT 1 FROM consulta_linhas_v2 cl
                   WHERE cl.holding_id = v_holding_id AND cl.item_status = 'ativa')
      ) INTO v_unavailable;

      IF v_unavailable THEN
        RAISE EXCEPTION 'fn_peb_create_loan_with_items: exemplaire id=% indisponible (deja engage dans un emprunt, une reservation, une consultation ou un autre PEB)', v_item_id;
      END IF;

      INSERT INTO interlibrary_loan_items_v2 (
        interlibrary_loan_id,
        line_no,
        book_id,
        holding_id,
        item_id,
        bib_ref,
        rotulo_cache,
        titulo_cache,
        autor_cache,
        editora_cache,
        ano_cache,
        item_status,
        notes,
        metadata
      )
      VALUES (
        v_new_loan.id,
        (v_item->>'line_no')::integer,
        NULLIF(v_item->>'book_id', '')::bigint,
        v_holding_id,
        v_item_id,
        v_item->>'bib_ref',
        v_item->>'rotulo_cache',
        v_item->>'titulo_cache',
        v_item->>'autor_cache',
        v_item->>'editora_cache',
        v_item->>'ano_cache',
        COALESCE(v_item->>'item_status', 'reservado_para_saida'),
        v_item->>'notes',
        COALESCE(v_item->'metadata', '{}'::jsonb)
      );
    END LOOP;
  END IF;

  -- Récupère les items créés pour les retourner
  SELECT COALESCE(jsonb_agg(to_jsonb(i.*) ORDER BY i.line_no), '[]'::jsonb)
  INTO v_new_items
  FROM interlibrary_loan_items_v2 i
  WHERE i.interlibrary_loan_id = v_new_loan.id;

  -- ─── Emission de l'evenement 'created' via la passerelle SECURITY DEFINER ──
  -- (cf. 20260522060000). Mode tolerant : un echec n'annule pas la creation.
  BEGIN
    PERFORM public.fn_peb_emit_created_notification(v_new_loan.id);
  EXCEPTION WHEN OTHERS THEN
    RAISE WARNING 'fn_peb_create_loan_with_items: pret % cree, mais emission de la notification ''created'' echouee (%). Le pret est conserve.', v_new_loan.id, SQLERRM;
  END;

  RETURN jsonb_build_object(
    'loan', to_jsonb(v_new_loan),
    'items', v_new_items
  );
END;
$$;


ALTER FUNCTION "public"."fn_peb_create_loan_with_items"("p_loan" "jsonb", "p_items" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."fn_peb_create_loan_with_items"("p_loan" "jsonb", "p_items" "jsonb") IS 'Crée un PEB et ses items en transaction atomique. Sécurité par RLS héritée (INVOKER). EA-12 phase 1.';



CREATE OR REPLACE FUNCTION "public"."fn_peb_delete_loan"("p_loan_id" bigint) RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_items_deleted integer;
  v_loan_exists boolean;
BEGIN
  IF p_loan_id IS NULL THEN
    RAISE EXCEPTION 'fn_peb_delete_loan: p_loan_id obligatoire';
  END IF;

  -- Vérifier que le loan existe ET est visible à l'utilisateur (via RLS SELECT)
  SELECT EXISTS(SELECT 1 FROM interlibrary_loans_v2 WHERE id = p_loan_id)
  INTO v_loan_exists;

  IF NOT v_loan_exists THEN
    RAISE EXCEPTION 'fn_peb_delete_loan: PEB id=% introuvable ou accès refusé', p_loan_id;
  END IF;

  -- DELETE des items d'abord. Si la table interlibrary_loan_items_v2 a une FK
  -- ON DELETE CASCADE vers interlibrary_loans_v2, le DELETE du loan suffirait,
  -- mais on fait explicitement pour compter et pour ne pas dépendre de la FK.
  WITH deleted AS (
    DELETE FROM interlibrary_loan_items_v2 
    WHERE interlibrary_loan_id = p_loan_id 
    RETURNING 1
  )
  SELECT COUNT(*) INTO v_items_deleted FROM deleted;

  -- DELETE du loan. RLS l'autorise si user_can_manage_library + fn_peb_authorized.
  -- Note : pas de RLS explicite DELETE listée — la table dépend probablement
  -- du USING de la policy SELECT (par défaut). À vérifier en test fumée.
  DELETE FROM interlibrary_loans_v2 WHERE id = p_loan_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'fn_peb_delete_loan: DELETE du loan id=% refusé par RLS', p_loan_id;
  END IF;

  RETURN jsonb_build_object(
    'deleted_loan_id', p_loan_id,
    'deleted_items_count', v_items_deleted
  );
END;
$$;


ALTER FUNCTION "public"."fn_peb_delete_loan"("p_loan_id" bigint) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."fn_peb_delete_loan"("p_loan_id" bigint) IS 'Supprime un PEB et ses items en cascade atomique. Sécurité par RLS héritée (INVOKER). EA-12 phase 1.';



CREATE OR REPLACE FUNCTION "public"."fn_peb_emit_created_notification"("p_loan_id" bigint) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_event_id bigint;
  v_lender uuid;
  v_borrower uuid;
BEGIN
  IF p_loan_id IS NULL THEN
    RAISE EXCEPTION 'fn_peb_emit_created_notification: p_loan_id obligatoire';
  END IF;

  -- Le pret doit exister ; on recupere ses deux bibliotheques.
  SELECT lender_library_id, borrower_library_id
  INTO v_lender, v_borrower
  FROM interlibrary_loans_v2
  WHERE id = p_loan_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'fn_peb_emit_created_notification: PEB id=% introuvable', p_loan_id;
  END IF;

  -- Controle d'autorisation : la fonction est SECURITY DEFINER, donc la RLS
  -- ne protege pas l'appel. On verifie explicitement que l'appelant gere
  -- l'une des deux bibliotheques du pret — meme exigence que la RLS
  -- interlibrary_loans_v2. Empeche un client authentifie de declencher
  -- l'emission pour un pret qui ne le concerne pas.
  IF NOT (public.user_can_manage_library(v_lender)
          OR public.user_can_manage_library(v_borrower)) THEN
    RAISE EXCEPTION 'fn_peb_emit_created_notification: acces refuse pour le PEB %', p_loan_id;
  END IF;

  -- Emission de l'evenement 'created'. fn_enqueue_... et fn_notify_... sont
  -- accessibles ici : cette fonction-passerelle appartient a postgres.
  v_event_id := public.fn_enqueue_emprestimo_interbibliotecas_notification(
    p_loan_id,
    'interlibrary_loan_created',
    'created'
  );
  PERFORM public.fn_notify_emprestimo_interbibliotecas_webhook(v_event_id);
END;
$$;


ALTER FUNCTION "public"."fn_peb_emit_created_notification"("p_loan_id" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_peb_propagate_status"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
BEGIN
  -- Ne fait rien si le statut n'a pas change.
  IF NEW.status_global IS NOT DISTINCT FROM OLD.status_global THEN
    RETURN NEW;
  END IF;

  -- Transition vers 'emprestado' : le PEB est expedie.
  --   - poser dispatched_at si pas deja pose ;
  --   - passer les exemplaires encore 'reservado_para_saida' a 'emprestado'.
  IF NEW.status_global = 'emprestado' THEN
    IF NEW.dispatched_at IS NULL THEN
      UPDATE interlibrary_loans_v2
        SET dispatched_at = timezone('utc', now())
        WHERE id = NEW.id AND dispatched_at IS NULL;
    END IF;
    UPDATE interlibrary_loan_items_v2
      SET item_status = 'emprestado'
      WHERE interlibrary_loan_id = NEW.id
        AND item_status = 'reservado_para_saida';
  END IF;

  -- Transition vers 'devolvido' : le PEB est clos. Poser returned_at.
  IF NEW.status_global = 'devolvido' AND NEW.returned_at IS NULL THEN
    UPDATE interlibrary_loans_v2
      SET returned_at = timezone('utc', now())
      WHERE id = NEW.id AND returned_at IS NULL;
  END IF;

  -- Marche arriere parcialmente_devolvido -> emprestado (spec sec. 3.2) :
  -- on NE de-pointe PAS les exemplaires deja regles. La marche arriere
  -- rouvre l'en-tete, elle n'efface pas le travail de pointage. Donc
  -- aucune action sur les items ici — comportement deliberement vide.

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."fn_peb_propagate_status"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_peb_search_exemplares"("p_query" "text", "p_lender_library_id" "uuid") RETURNS TABLE("exemplar_id" bigint, "holding_id" bigint, "book_id" bigint, "titulo" "text", "autor" "text", "bib_ref" "text", "tombo" "text", "library_id" "uuid")
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public'
    AS $$
  SELECT
    e.id          AS exemplar_id,
    e.holding_id  AS holding_id,
    h.book_id     AS book_id,
    b.titulo      AS titulo,
    b.autor       AS autor,
    COALESCE(NULLIF(btrim(h.local_bib_ref), ''), b.bib_ref, e.bib_ref) AS bib_ref,
    e.tombo       AS tombo,
    e.library_id  AS library_id
  FROM public.exemplares e
  JOIN public.book_holdings h ON h.id = e.holding_id
  JOIN public.books b         ON b.id = h.book_id
  WHERE e.holding_id IS NOT NULL
    -- #ILL-search-scope : uniquement les exemplaires de la prêteuse.
    AND e.library_id = p_lender_library_id
    -- ── mini-PEB / matrice §6.2 (branche prêt) ────────────────────────────
    --     Seuls les exemplaires publics ET empruntables peuvent sortir en PEB.
    AND e.visibility = 'public'
    AND e.circulation_policy IN ('emprestavel', 'ambos')
    -- ──────────────────────────────────────────────────────────────────────
    AND (
         b.titulo ILIKE '%' || btrim(p_query) || '%'
      OR b.autor  ILIKE '%' || btrim(p_query) || '%'
      OR e.tombo  ILIKE '%' || btrim(p_query) || '%'
      OR b.bib_ref ILIKE '%' || btrim(p_query) || '%'
    )
    -- #ILL-availability : exemplaire non engagé dans un autre circuit.
    -- (1) pas d'emprunt ordinaire en cours
    AND NOT EXISTS (
      SELECT 1 FROM public.emprestimo_itens_v2 ei
      WHERE ei.item_id = e.id AND ei.item_status = 'aberto'
    )
    -- (2) pas de réservation active
    AND NOT EXISTS (
      SELECT 1 FROM public.reserva_linhas_v2 rl
      WHERE rl.item_id = e.id AND rl.item_status = 'ativa'
    )
    -- (3) pas déjà engagé dans un autre PEB
    AND NOT EXISTS (
      SELECT 1 FROM public.interlibrary_loan_items_v2 ili
      WHERE ili.item_id = e.id
        AND ili.item_status IN ('reservado_para_saida', 'emprestado')
    )
    -- (4) pas de consultation active sur CET exemplaire (#MODEL-item-grain :
    --     jointure à l'item_id, règle resserrée vs jointure au holding).
    AND NOT EXISTS (
      SELECT 1 FROM public.consulta_linhas_v2 cl
      WHERE cl.item_id = e.id AND cl.item_status = 'ativa'
    )
  ORDER BY b.titulo, e.tombo
  LIMIT 20;
$$;


ALTER FUNCTION "public"."fn_peb_search_exemplares"("p_query" "text", "p_lender_library_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."fn_peb_search_exemplares"("p_query" "text", "p_lender_library_id" "uuid") IS 'Recherche d''exemplaires éligibles au PEB pour la prêteuse. Branche PRÊT de la matrice §6.2 (PEB-CIRC-1) : visibility=public ET circulation_policy IN (emprestavel,ambos). Un PEB sort physiquement l''exemplaire → copies consulta-sur-place et staff_only exclues.';



CREATE OR REPLACE FUNCTION "public"."fn_peb_unarchive_loan"("p_loan_id" bigint) RETURNS "public"."interlibrary_loans_v2"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'auth', 'pg_temp'
    AS $$
DECLARE
    v_loan public.interlibrary_loans_v2;
BEGIN
    SELECT * INTO v_loan
    FROM public.interlibrary_loans_v2
    WHERE id = p_loan_id;

    IF v_loan.id IS NULL THEN
        RAISE EXCEPTION 'not_found: PEB % does not exist', p_loan_id
            USING ERRCODE = 'P0002';
    END IF;

    IF NOT (
        public.user_can_act_as_staff_on_library(v_loan.lender_library_id)
        OR public.user_can_act_as_staff_on_library(v_loan.borrower_library_id)
    ) THEN
        RAISE EXCEPTION 'forbidden: caller is not staff of either library of PEB %', p_loan_id
            USING ERRCODE = '42501';
    END IF;

    IF v_loan.archived_at IS NULL THEN
        RAISE EXCEPTION 'not_archived: PEB % is not archived', p_loan_id
            USING ERRCODE = '22023';
    END IF;

    -- archived_at ET archive_reason remis à NULL ENSEMBLE (archive_consistency_chk)
    UPDATE public.interlibrary_loans_v2
    SET archived_at    = NULL,
        archive_reason = NULL,
        updated_at     = timezone('utc', now()),
        updated_by     = auth.uid()
    WHERE id = p_loan_id
    RETURNING * INTO v_loan;

    RETURN v_loan;
END;
$$;


ALTER FUNCTION "public"."fn_peb_unarchive_loan"("p_loan_id" bigint) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."fn_peb_unarchive_loan"("p_loan_id" bigint) IS 'Désarchive un PEB : remet archived_at et archive_reason à NULL ensemble, le PEB réintègre la file active. Réservé au staff de l''une ou l''autre bibliothèque.';



CREATE OR REPLACE FUNCTION "public"."fn_peb_update_item_status"("p_loan_id" bigint, "p_items" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_item jsonb;
  v_item_id bigint;
  v_new_status text;
  v_loan interlibrary_loans_v2%ROWTYPE;
  v_items jsonb;
BEGIN
  IF p_loan_id IS NULL THEN
    RAISE EXCEPTION 'fn_peb_update_item_status: p_loan_id obligatoire';
  END IF;
  IF p_items IS NULL OR jsonb_array_length(p_items) = 0 THEN
    RAISE EXCEPTION 'fn_peb_update_item_status: p_items vide';
  END IF;

  FOR v_item IN SELECT * FROM jsonb_array_elements(p_items) LOOP
    v_item_id := NULLIF(v_item->>'id', '')::bigint;
    v_new_status := v_item->>'new_status';

    -- Validation : id et new_status presents.
    IF v_item_id IS NULL OR v_new_status IS NULL OR v_new_status = '' THEN
      RAISE EXCEPTION 'fn_peb_update_item_status: item invalide (id et new_status obligatoires) — item: %', v_item;
    END IF;

    -- Garde-fou metier : seuls les statuts de RETOUR sont autorises via
    -- cette RPC. Les statuts d'amont (reservado_para_saida, emprestado)
    -- sont poses par les operations du pret, jamais par le pointage de
    -- retour. On peut en revanche corriger librement entre statuts de
    -- retour (ex. perdido -> devolvido).
    IF v_new_status NOT IN ('devolvido', 'perdido', 'danificado', 'cancelado') THEN
      RAISE EXCEPTION 'fn_peb_update_item_status: statut de retour invalide "%" (attendu : devolvido, perdido, danificado, cancelado)', v_new_status;
    END IF;

    -- UPDATE. Double critere interlibrary_loan_id = p_loan_id AND id = v_item_id :
    -- garantit que l'exemplaire appartient bien au pret annonce (anti-usurpation).
    -- returned_at : pose si devolvido, efface sinon (un exemplaire perdu /
    -- endommage / annule n'a pas de date de retour).
    -- La RLS interlibrary_loan_items_v2_update verifie l'autorisation
    -- (gestionnaire de la bibliotheque prêteuse OU emprunteuse).
    UPDATE interlibrary_loan_items_v2
    SET
      item_status    = v_new_status,
      returned_at    = CASE WHEN v_new_status = 'devolvido'
                            THEN timezone('utc'::text, now())
                            ELSE NULL END,
      condition_back = COALESCE(v_item->>'condition_back', condition_back),
      notes          = COALESCE(v_item->>'notes', notes),
      updated_at     = timezone('utc'::text, now())
    WHERE interlibrary_loan_id = p_loan_id
      AND id = v_item_id;

    IF NOT FOUND THEN
      RAISE EXCEPTION 'fn_peb_update_item_status: exemplaire id=% introuvable dans le PEB %, ou accès refusé', v_item_id, p_loan_id;
    END IF;
  END LOOP;

  -- Le trigger de consolidation a (potentiellement) deja mis a jour
  -- status_global. On relit le pret et ses items pour les retourner a jour.
  SELECT * INTO v_loan FROM interlibrary_loans_v2 WHERE id = p_loan_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'fn_peb_update_item_status: PEB id=% introuvable', p_loan_id;
  END IF;

  SELECT COALESCE(jsonb_agg(to_jsonb(i.*) ORDER BY i.line_no), '[]'::jsonb)
  INTO v_items
  FROM interlibrary_loan_items_v2 i
  WHERE i.interlibrary_loan_id = p_loan_id;

  RETURN jsonb_build_object(
    'loan', to_jsonb(v_loan),
    'items', v_items
  );
END;
$$;


ALTER FUNCTION "public"."fn_peb_update_item_status"("p_loan_id" bigint, "p_items" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_peb_update_status"("p_loan_id" bigint, "p_new_status" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_updated interlibrary_loans_v2%ROWTYPE;
BEGIN
  IF p_loan_id IS NULL OR p_new_status IS NULL OR p_new_status = '' THEN
    RAISE EXCEPTION 'fn_peb_update_status: p_loan_id et p_new_status obligatoires';
  END IF;

  -- La RLS interlibrary_loans_v2_update vérifie automatiquement
  -- user_can_manage_library + fn_peb_authorized.
  UPDATE interlibrary_loans_v2
  SET 
    status_global = p_new_status,
    updated_at = timezone('utc'::text, now()),
    updated_by = auth.uid()
  WHERE id = p_loan_id
  RETURNING * INTO v_updated;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'fn_peb_update_status: PEB id=% introuvable ou accès refusé', p_loan_id;
  END IF;

  RETURN to_jsonb(v_updated);
END;
$$;


ALTER FUNCTION "public"."fn_peb_update_status"("p_loan_id" bigint, "p_new_status" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."fn_peb_update_status"("p_loan_id" bigint, "p_new_status" "text") IS 'Change le status_global d''un PEB. Sécurité par RLS héritée (INVOKER). EA-12 phase 1.';



CREATE OR REPLACE FUNCTION "public"."fn_peb_validate_status_transition"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_ok boolean;
BEGIN
  -- Transition immobile (statut inchange) : toujours toleree — un UPDATE peut
  -- ne modifier que d'autres colonnes.
  IF NEW.status_global IS NOT DISTINCT FROM OLD.status_global THEN
    RETURN NEW;
  END IF;

  SELECT EXISTS (
    SELECT 1 FROM public.interlibrary_loan_status_transitions
    WHERE from_status = OLD.status_global
      AND to_status   = NEW.status_global
  ) INTO v_ok;

  IF NOT v_ok THEN
    RAISE EXCEPTION
      'PEB #%: transition de statut interdite (% -> %). Cibles licites depuis "%": %.',
      OLD.id, OLD.status_global, NEW.status_global, OLD.status_global,
      COALESCE(
        (SELECT string_agg(to_status, ', ' ORDER BY to_status)
         FROM public.interlibrary_loan_status_transitions
         WHERE from_status = OLD.status_global),
        '(aucune — etat terminal)'
      );
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."fn_peb_validate_status_transition"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_propagate_circulation_default_on_publish"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
BEGIN
  IF NEW.published_book_id IS NOT NULL THEN
    UPDATE public.books
    SET circulation_default = NEW.circulation_default,
        loanable = (NEW.circulation_default IS DISTINCT FROM 'consulta'),
        distribuidora = NEW.distribuidora,
        -- Tese
        tese_university = NEW.tese_university,
        tese_advisor = NEW.tese_advisor,
        -- Artigo
        artigo_source = NEW.artigo_source,
        artigo_volume = NEW.artigo_volume,
        artigo_issue = NEW.artigo_issue,
        artigo_pages = NEW.artigo_pages,
        -- Relatorio
        relatorio_org = NEW.relatorio_org,
        relatorio_recipient = NEW.relatorio_recipient,
        relatorio_internal_notes = NEW.relatorio_internal_notes,
        -- Zine
        zine_print_run = NEW.zine_print_run,
        zine_technique = NEW.zine_technique,
        zine_format = NEW.zine_format,
        -- Subjects (les identifiants d'autorite viaf/isni/wikidata ont migre
        -- vers authors.structured_meta : plus de propagation livre par livre)
        subjects = NEW.subjects
    WHERE id = NEW.published_book_id;
  END IF;
  RETURN NULL;
END;
$$;


