COMMENT ON FUNCTION "public"."fn_propagate_circulation_default_on_publish"() IS 'Propage book_drafts.circulation_default vers books (+ derive loanable) a la publication. Catalogacao 5.6, 06/06/2026.';



CREATE OR REPLACE FUNCTION "public"."fn_propose_library_profile_change"("p_library_id" "uuid", "p_axis" "text", "p_new_value" "text", "p_motivation" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_caller_id        uuid := auth.uid();
  v_old_value        text;
  v_classification   jsonb;
  v_transition_type  int;
  v_governance       text;
  v_active_staff     int;
  v_min_quorum       int;
  v_proposal_id      uuid;
  v_expires_at       timestamptz;
  v_votes_required   int;
  v_executed_now     boolean := false;
BEGIN
  IF v_caller_id IS NULL THEN
    RAISE EXCEPTION 'PROPOSE_AUTH_REQUIRED : authentification requise'
      USING ERRCODE = 'insufficient_privilege',
            HINT    = 'error.profile_change.auth_required';
  END IF;

  IF NOT EXISTS (
    SELECT 1 FROM public.user_library_memberships
    WHERE library_id = p_library_id
      AND user_id    = v_caller_id
      AND status     = 'active'
      AND role IN ('librarian', 'coordenador')
  ) THEN
    RAISE EXCEPTION 'PROPOSE_NOT_STAFF : caller n''est pas staff actif de la biblio (%)' , p_library_id
      USING ERRCODE = 'insufficient_privilege',
            HINT    = 'error.profile_change.not_staff';
  END IF;

  IF p_motivation IS NULL OR length(trim(p_motivation)) < 5 THEN
    RAISE EXCEPTION 'PROPOSE_MOTIVATION_TOO_SHORT : la motivation doit faire au moins 5 caracteres'
      USING ERRCODE = 'check_violation',
            HINT    = 'error.profile_change.motivation_too_short';
  END IF;

  IF EXISTS (
    SELECT 1 FROM public.library_profile_proposals
    WHERE library_id = p_library_id
      AND axis       = p_axis
      AND status     = 'open'
  ) THEN
    RAISE EXCEPTION 'PROPOSE_AXIS_LOCKED : une proposition est deja ouverte sur cet axe pour cette biblio'
      USING ERRCODE = 'unique_violation',
            HINT    = 'error.profile_change.axis_already_open';
  END IF;

  IF    p_axis = 'catalog_mode'     THEN v_old_value := public.fn_library_catalog_mode(p_library_id);
  ELSIF p_axis = 'circulation_mode' THEN v_old_value := public.fn_library_circulation_mode(p_library_id);
  ELSIF p_axis = 'network_mode'     THEN v_old_value := public.fn_library_network_mode(p_library_id);
  ELSIF p_axis = 'governance_mode'  THEN v_old_value := public.fn_library_governance_mode(p_library_id);
  ELSE
    RAISE EXCEPTION 'PROPOSE_UNKNOWN_AXIS : axe inconnu (%)', p_axis
      USING ERRCODE = 'check_violation',
            HINT    = 'error.profile_change.unknown_axis';
  END IF;

  IF v_old_value IS NULL THEN
    RAISE EXCEPTION 'PROPOSE_LIBRARY_NOT_FOUND : biblio invisible ou inexistante (%)', p_library_id
      USING ERRCODE = 'no_data_found',
            HINT    = 'error.profile_change.library_not_found';
  END IF;

  v_classification  := public.fn_classify_transition(p_axis, v_old_value, p_new_value);
  v_transition_type := (v_classification->>'transition_type')::int;
  v_governance      := v_classification->>'governance_required';

  v_active_staff := public.fn_library_active_staff_count(p_library_id);
  v_min_quorum := CASE v_transition_type
    WHEN 1 THEN 1
    WHEN 2 THEN 2
    WHEN 3 THEN 2
    WHEN 4 THEN 3
  END;

  IF v_active_staff < v_min_quorum THEN
    RAISE EXCEPTION 'PROPOSE_QUORUM_NOT_MET : type % requiert >= % staff actifs, % presents',
      v_transition_type, v_min_quorum, v_active_staff
      USING ERRCODE = 'check_violation',
            HINT    = 'error.profile_change.quorum_not_met';
  END IF;

  v_votes_required := CASE v_governance
    WHEN 'direct'             THEN 0
    WHEN 'majority'           THEN (v_active_staff / 2) + 1
    WHEN 'unanimous'          THEN v_active_staff
    WHEN 'unanimous_extended' THEN v_active_staff
  END;

  v_expires_at := CASE
    WHEN v_transition_type = 1 THEN now()
    ELSE now() + interval '30 days'
  END;

  INSERT INTO public.library_profile_proposals (
    library_id, axis, old_value, new_value, transition_type, governance_required,
    motivation, proposed_by, status, expires_at, completed_at
  )
  VALUES (
    p_library_id, p_axis, v_old_value, p_new_value, v_transition_type, v_governance,
    trim(p_motivation), v_caller_id,
    CASE WHEN v_transition_type = 1 THEN 'completed' ELSE 'open' END,
    v_expires_at,
    CASE WHEN v_transition_type = 1 THEN now() ELSE NULL END
  )
  RETURNING id INTO v_proposal_id;

  IF v_transition_type = 1 THEN
    INSERT INTO public.library_profile_history (
      library_id, axis, old_value, new_value, changed_by, changed_at, motivation
    )
    VALUES (
      p_library_id, p_axis, v_old_value, p_new_value, v_caller_id, now(),
      'Transition directe type 1 (' || p_motivation || ')'
    );

    IF    p_axis = 'catalog_mode'     THEN UPDATE public.libraries SET catalog_mode     = p_new_value WHERE id = p_library_id;
    ELSIF p_axis = 'circulation_mode' THEN UPDATE public.libraries SET circulation_mode = p_new_value WHERE id = p_library_id;
    ELSIF p_axis = 'network_mode'     THEN UPDATE public.libraries SET network_mode     = p_new_value WHERE id = p_library_id;
    ELSIF p_axis = 'governance_mode'  THEN UPDATE public.libraries SET governance_mode  = p_new_value WHERE id = p_library_id;
    END IF;

    v_executed_now := true;
  END IF;

  RETURN jsonb_build_object(
    'proposal_id',          v_proposal_id,
    'library_id',           p_library_id,
    'axis',                 p_axis,
    'old_value',            v_old_value,
    'new_value',            p_new_value,
    'transition_type',      v_transition_type,
    'governance_required',  v_governance,
    'expires_at',           v_expires_at,
    'active_staff_count',   v_active_staff,
    'votes_required',       v_votes_required,
    'status',               CASE WHEN v_executed_now THEN 'completed' ELSE 'open' END,
    'executed_immediately', v_executed_now
  );
END;
$$;


ALTER FUNCTION "public"."fn_propose_library_profile_change"("p_library_id" "uuid", "p_axis" "text", "p_new_value" "text", "p_motivation" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."fn_propose_library_profile_change"("p_library_id" "uuid", "p_axis" "text", "p_new_value" "text", "p_motivation" "text") IS 'B.3 RPC : cree une proposition de transition de profil. Type 1 auto-execute en transaction. Type 4 refuse en amont (paquet D non livre). Verifie staff actif, motivation, quorum, conflit existant.';



CREATE OR REPLACE FUNCTION "public"."fn_purge_expired_data"("p_dry_run" boolean DEFAULT true) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_lib record;
  v_policy jsonb;
  v_loans_days int;
  v_reservations_days int;
  v_consultations_days int;
  v_notifications_days int;
  v_count_loans int := 0;
  v_count_reservations int := 0;
  v_count_consultations int := 0;
  v_count_notifications int := 0;
  v_total_loans int := 0;
  v_total_reservations int := 0;
  v_total_consultations int := 0;
  v_total_notifications int := 0;
  v_per_library jsonb := '{}'::jsonb;
  v_lib_summary jsonb;
  v_started_at timestamptz := now();
BEGIN
  -- Itère sur chaque bibliothèque active
  FOR v_lib IN
    SELECT id, slug, name FROM public.libraries WHERE is_active = true
  LOOP
    -- Récupère la politique effective (override OU défaut AnarBib)
    v_policy := public.fn_get_retention_policy(v_lib.id);
    v_loans_days := (v_policy->>'retention_loans_days')::int;
    v_reservations_days := (v_policy->>'retention_reservations_days')::int;
    v_consultations_days := (v_policy->>'retention_consultations_days')::int;
    v_notifications_days := (v_policy->>'retention_notifications_days')::int;

    -- Reset compteurs locaux
    v_count_loans := 0;
    v_count_reservations := 0;
    v_count_consultations := 0;
    v_count_notifications := 0;

    -- ─── EMPRUNTS ────────────────────────────────────────────────────────────
    -- Granularité : emprunt ENTIER. On supprime un emprunt seulement si TOUS
    -- ses items ont été retournés/finalisés depuis plus de v_loans_days jours.
    -- Une durée de 0 = rétention infinie, on ne purge pas.
    IF v_loans_days > 0 THEN
      IF p_dry_run THEN
        SELECT count(*) INTO v_count_loans
        FROM emprestimos_v2 e
        WHERE e.library_id = v_lib.id
          AND e.status_global = 'encerrado'
          AND NOT EXISTS (
            SELECT 1 FROM emprestimo_itens_v2 ei
            WHERE ei.emprestimo_id = e.id
              AND (
                ei.item_status = 'aberto'
                OR COALESCE(ei.return_completed_at, ei.returned_at, ei.updated_at) > (now() - (v_loans_days || ' days')::interval)
              )
          );
      ELSE
        WITH purged AS (
          DELETE FROM emprestimos_v2 e
          WHERE e.library_id = v_lib.id
            AND e.status_global = 'encerrado'
            AND NOT EXISTS (
              SELECT 1 FROM emprestimo_itens_v2 ei
              WHERE ei.emprestimo_id = e.id
                AND (
                  ei.item_status = 'aberto'
                  OR COALESCE(ei.return_completed_at, ei.returned_at, ei.updated_at) > (now() - (v_loans_days || ' days')::interval)
                )
            )
          RETURNING e.id
        )
        SELECT count(*) INTO v_count_loans FROM purged;
      END IF;
    END IF;

    -- ─── RÉSERVATIONS ────────────────────────────────────────────────────────
    -- Granularité : réservation ENTIÈRE. On supprime si toutes les lignes
    -- sont en état terminal (cancelled/converted/expired) depuis assez longtemps.
    IF v_reservations_days > 0 THEN
      IF p_dry_run THEN
        SELECT count(*) INTO v_count_reservations
        FROM reservas_v2 r
        WHERE r.library_id = v_lib.id
          AND r.status_global IN ('encerrada', 'cancelada')
          AND NOT EXISTS (
            SELECT 1 FROM reserva_linhas_v2 rl
            WHERE rl.reserva_id = r.id
              AND COALESCE(rl.cancelled_at, rl.converted_at, rl.expired_at, rl.updated_at) > (now() - (v_reservations_days || ' days')::interval)
          );
      ELSE
        WITH purged AS (
          DELETE FROM reservas_v2 r
          WHERE r.library_id = v_lib.id
            AND r.status_global IN ('encerrada', 'cancelada')
            AND NOT EXISTS (
              SELECT 1 FROM reserva_linhas_v2 rl
              WHERE rl.reserva_id = r.id
                AND COALESCE(rl.cancelled_at, rl.converted_at, rl.expired_at, rl.updated_at) > (now() - (v_reservations_days || ' days')::interval)
            )
          RETURNING r.id
        )
        SELECT count(*) INTO v_count_reservations FROM purged;
      END IF;
    END IF;

    -- ─── CONSULTATIONS ───────────────────────────────────────────────────────
    IF v_consultations_days > 0 THEN
      IF p_dry_run THEN
        SELECT count(*) INTO v_count_consultations
        FROM consultas_locais_v2 c
        WHERE c.library_id = v_lib.id
          AND c.status_global IN ('encerrada', 'cancelada')
          AND NOT EXISTS (
            SELECT 1 FROM consulta_linhas_v2 cl
            WHERE cl.consulta_id = c.id
              AND COALESCE(cl.cancelled_at, cl.consulted_at, cl.expired_at, cl.updated_at) > (now() - (v_consultations_days || ' days')::interval)
          );
      ELSE
        WITH purged AS (
          DELETE FROM consultas_locais_v2 c
          WHERE c.library_id = v_lib.id
            AND c.status_global IN ('encerrada', 'cancelada')
            AND NOT EXISTS (
              SELECT 1 FROM consulta_linhas_v2 cl
              WHERE cl.consulta_id = c.id
                AND COALESCE(cl.cancelled_at, cl.consulted_at, cl.expired_at, cl.updated_at) > (now() - (v_consultations_days || ' days')::interval)
            )
          RETURNING c.id
        )
        SELECT count(*) INTO v_count_consultations FROM purged;
      END IF;
    END IF;

    -- ─── NOTIFICATIONS LUES ──────────────────────────────────────────────────
    -- Granularité : par notification individuelle.
    IF v_notifications_days > 0 THEN
      IF p_dry_run THEN
        SELECT count(*) INTO v_count_notifications
        FROM user_notifications n
        WHERE n.library_id = v_lib.id
          AND n.is_read = true
          AND n.read_at IS NOT NULL
          AND n.read_at < (now() - (v_notifications_days || ' days')::interval);
      ELSE
        WITH purged AS (
          DELETE FROM user_notifications n
          WHERE n.library_id = v_lib.id
            AND n.is_read = true
            AND n.read_at IS NOT NULL
            AND n.read_at < (now() - (v_notifications_days || ' days')::interval)
          RETURNING n.id
        )
        SELECT count(*) INTO v_count_notifications FROM purged;
      END IF;
    END IF;

    -- Agrégat de la biblio (uniquement si quelque chose a été affecté)
    IF v_count_loans + v_count_reservations + v_count_consultations + v_count_notifications > 0 THEN
      v_lib_summary := jsonb_build_object(
        'library_slug', v_lib.slug,
        'library_name', v_lib.name,
        'loans', v_count_loans,
        'reservations', v_count_reservations,
        'consultations', v_count_consultations,
        'notifications', v_count_notifications,
        'policy_used', v_policy->'overrides'
      );
      v_per_library := v_per_library || jsonb_build_object(v_lib.slug, v_lib_summary);
    END IF;

    v_total_loans := v_total_loans + v_count_loans;
    v_total_reservations := v_total_reservations + v_count_reservations;
    v_total_consultations := v_total_consultations + v_count_consultations;
    v_total_notifications := v_total_notifications + v_count_notifications;
  END LOOP;

  RETURN jsonb_build_object(
    'mode', CASE WHEN p_dry_run THEN 'dry_run' ELSE 'executed' END,
    'started_at', v_started_at,
    'finished_at', now(),
    'duration_ms', extract(milliseconds FROM (now() - v_started_at)),
    'totals', jsonb_build_object(
      'loans', v_total_loans,
      'reservations', v_total_reservations,
      'consultations', v_total_consultations,
      'notifications', v_total_notifications,
      'grand_total', v_total_loans + v_total_reservations + v_total_consultations + v_total_notifications
    ),
    'per_library', v_per_library
  );
END;
$$;


ALTER FUNCTION "public"."fn_purge_expired_data"("p_dry_run" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_reader_consent_valid"("p_user_id" "uuid", "p_partnership_id" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
  SELECT EXISTS (
    SELECT 1
    FROM public.reader_partnership_consent c
    JOIN public.library_partnerships canon ON canon.id = c.partnership_id
    WHERE c.user_id = p_user_id
      AND c.partnership_id = public.fn_partnership_canonical_id(p_partnership_id)
      AND c.revoked_at IS NULL
      AND c.config_version = canon.config_version
  );
$$;


ALTER FUNCTION "public"."fn_reader_consent_valid"("p_user_id" "uuid", "p_partnership_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_reader_message_dispatch"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  PERFORM public.fn_dispatch_notify_event(
    'reader_message_sent',
    NEW.id,
    jsonb_build_object(
      'library_id', NEW.library_id,
      'sender_id',  NEW.sender_id,
      'direction',  NEW.direction
    )
  );
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."fn_reader_message_dispatch"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_reader_my_partnerships"() RETURNS TABLE("partnership_id" "uuid", "library_a_name" "text", "library_b_name" "text", "consent_state" "text")
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
DECLARE v_uid uuid := auth.uid();
BEGIN
  IF v_uid IS NULL THEN RETURN; END IF;
  RETURN QUERY
  WITH canon AS (
    SELECT lp.id, lp.library_id AS la, lp.partner_library_id AS lb, lp.config_version AS cv
    FROM public.library_partnerships lp
    WHERE lp.status='active' AND lp.partner_library_id IS NOT NULL AND lp.library_id < lp.partner_library_id
      AND EXISTS (SELECT 1 FROM public.partnership_rights pr WHERE pr.partnership_id=lp.id AND pr.right_key='transparence')
      AND EXISTS (SELECT 1 FROM public.user_library_memberships m WHERE m.user_id=v_uid AND m.library_id=lp.library_id AND m.status='active')
      AND EXISTS (SELECT 1 FROM public.user_library_memberships m WHERE m.user_id=v_uid AND m.library_id=lp.partner_library_id AND m.status='active')
  )
  SELECT c.id, COALESCE(la.short_name,la.name), COALESCE(lb.short_name,lb.name),
         CASE WHEN cons.partnership_id IS NULL OR cons.revoked_at IS NOT NULL THEN 'none'
              WHEN cons.config_version=c.cv THEN 'valid' ELSE 'stale' END
  FROM canon c JOIN public.libraries la ON la.id=c.la JOIN public.libraries lb ON lb.id=c.lb
  LEFT JOIN public.reader_partnership_consent cons ON cons.partnership_id=c.id AND cons.user_id=v_uid
  ORDER BY 2,3;
END $$;


ALTER FUNCTION "public"."fn_reader_my_partnerships"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_reader_send_message_to_library"("p_library_id" "uuid", "p_subject" "text", "p_body" "text") RETURNS bigint
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_body text := btrim(coalesce(p_body, ''));
  v_recent int;
  v_id bigint;
BEGIN
  IF char_length(v_body) < 1 THEN
    RAISE EXCEPTION 'empty_body' USING errcode = '22023';
  END IF;
  IF char_length(v_body) > 4000 THEN
    RAISE EXCEPTION 'body_too_long' USING errcode = '22023';
  END IF;

  -- Anti-spam : <= 3 messages / 24 h / personne / biblio (lecture des propres
  -- lignes, autorisee par la RLS SELECT en contexte INVOKER).
  SELECT count(*) INTO v_recent
  FROM public.reader_library_messages
  WHERE sender_id = auth.uid()
    AND library_id = p_library_id
    AND direction = 'reader'
    AND created_at > now() - interval '24 hours';

  IF v_recent >= 3 THEN
    RAISE EXCEPTION 'rate_limited' USING errcode = '53400';
  END IF;

  INSERT INTO public.reader_library_messages (library_id, sender_id, direction, subject, body)
  VALUES (p_library_id, auth.uid(), 'reader', NULLIF(btrim(coalesce(p_subject,'')), ''), v_body)
  RETURNING id INTO v_id;

  RETURN v_id;
END;
$$;


ALTER FUNCTION "public"."fn_reader_send_message_to_library"("p_library_id" "uuid", "p_subject" "text", "p_body" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_recompute_holdings_on_exemplar_change"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
BEGIN
  IF TG_OP = 'DELETE' THEN
    IF OLD.holding_id IS NOT NULL THEN
      PERFORM public.fn_v2_recompute_holdings_availability(p_holding_ids := ARRAY[OLD.holding_id]);
    END IF;
    RETURN OLD;
  END IF;

  -- INSERT / UPDATE : recompute le holding courant
  IF NEW.holding_id IS NOT NULL THEN
    PERFORM public.fn_v2_recompute_holdings_availability(p_holding_ids := ARRAY[NEW.holding_id]);
  END IF;

  -- Si l'exemplaire a changé de holding, recompute aussi l'ancien
  IF TG_OP = 'UPDATE'
     AND OLD.holding_id IS DISTINCT FROM NEW.holding_id
     AND OLD.holding_id IS NOT NULL THEN
    PERFORM public.fn_v2_recompute_holdings_availability(p_holding_ids := ARRAY[OLD.holding_id]);
  END IF;

  RETURN NEW;
END $$;


ALTER FUNCTION "public"."fn_recompute_holdings_on_exemplar_change"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_record_membership_payment"("p_user_id" "uuid", "p_rule_id" "uuid", "p_amount_paid" numeric, "p_payment_method" "public"."membership_payment_method" DEFAULT 'cash'::"public"."membership_payment_method", "p_paid_at" timestamp with time zone DEFAULT "now"(), "p_notes" "text" DEFAULT NULL::"text", "p_valid_from" "date" DEFAULT NULL::"date", "p_valid_until" "date" DEFAULT NULL::"date") RETURNS TABLE("ok" boolean, "payment_id" "uuid", "valid_from" "date", "valid_until" "date", "message" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_actor public.my_access%rowtype;
  v_rule public.library_membership_rules%rowtype;
  v_user_belongs boolean;
  v_computed_from date;
  v_computed_until date;
  v_final_from date;
  v_final_until date;
  v_payment_id uuid;
BEGIN
  -- Authentification
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Autenticação obrigatória.';
  END IF;

  -- Droits staff (administrador ou coordenador)
  SELECT * INTO v_actor FROM public.my_access LIMIT 1;

  IF COALESCE(v_actor.can_access_painel, false) IS false THEN
    RAISE EXCEPTION 'Acesso bibliotecário obrigatório.';
  END IF;

  IF v_actor.library_id IS NULL THEN
    RAISE EXCEPTION 'Biblioteca ativa não identificada.';
  END IF;

  -- La règle existe et appartient à la bibliothèque active
  SELECT * INTO v_rule
  FROM public.library_membership_rules
  WHERE id = p_rule_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Regra de contribuição não encontrada.';
  END IF;

  IF v_rule.library_id <> v_actor.library_id THEN
    RAISE EXCEPTION 'Esta regra pertence a outra biblioteca.';
  END IF;

  IF NOT v_rule.is_active THEN
    RAISE EXCEPTION 'Esta regra está desativada.';
  END IF;

  -- Validation : montant >= amount_min (sauf pour exemption et in_kind)
  IF p_payment_method NOT IN ('exemption', 'in_kind')
     AND p_amount_paid < v_rule.amount_min THEN
    RAISE EXCEPTION 'Valor pago (%) inferior ao mínimo da regra (%).',
      p_amount_paid, v_rule.amount_min;
  END IF;

  -- L'usager appartient à cette bibliothèque
  SELECT EXISTS (
    SELECT 1 FROM public.user_library_memberships
    WHERE user_id = p_user_id
      AND library_id = v_actor.library_id
      AND status = 'active'
  ) INTO v_user_belongs;

  IF NOT v_user_belongs THEN
    RAISE EXCEPTION 'Este(a) leitor(a) não está vinculado(a) à biblioteca ativa.';
  END IF;

  -- Calcul de validité (si non fourni)
  SELECT cv.valid_from, cv.valid_until
    INTO v_computed_from, v_computed_until
  FROM public.fn_compute_membership_validity(p_rule_id, p_paid_at) cv;

  v_final_from  := COALESCE(p_valid_from,  v_computed_from);
  v_final_until := COALESCE(p_valid_until, v_computed_until);

  -- Insertion
  INSERT INTO public.membership_payments (
    user_id, library_id, rule_id,
    amount_paid, currency,
    paid_at, valid_from, valid_until,
    payment_method, notes,
    recorded_by
  ) VALUES (
    p_user_id, v_actor.library_id, p_rule_id,
    p_amount_paid, v_rule.currency,
    p_paid_at, v_final_from, v_final_until,
    p_payment_method, p_notes,
    auth.uid()
  )
  RETURNING id INTO v_payment_id;

  -- #NOTIFY-Painel-acts : reçu au membre (best-effort ; fn_dispatch_notify_event
  -- avale ses propres erreurs et ne casse jamais l'enregistrement du paiement).
  PERFORM public.fn_dispatch_notify_event(
    'cotisation_payment_recorded',
    1,
    jsonb_build_object('payment_id', v_payment_id::text)
  );

  RETURN QUERY
  SELECT true,
         v_payment_id,
         v_final_from,
         v_final_until,
         format('Contribuição registrada com sucesso para o período de %s a %s.',
                v_final_from,
                COALESCE(v_final_until::text, '∞'));
END $$;


