CREATE OR REPLACE FUNCTION "public"."fn_replicate_consulta_agendada_to_inapp"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_library_id uuid;
  v_user_id uuid;
  v_local_consultation_enabled boolean := true;
  v_mail_enabled boolean := true;
  v_user_disabled boolean := false;
  v_consulta_ref text;
BEGIN
  -- Détection de la transition cible (UPDATE vers agendada, ou INSERT en agendada)
  IF NOT (
    (TG_OP = 'INSERT' AND NEW.workflow_stage = 'consulta_agendada')
    OR (TG_OP = 'UPDATE' AND NEW.workflow_stage = 'consulta_agendada'
        AND OLD.workflow_stage IS DISTINCT FROM NEW.workflow_stage)
  ) THEN
    RETURN NEW;
  END IF;

  -- Récupérer library_id et user_id depuis consultas_locais_v2
  SELECT cl.library_id, cl.user_id
    INTO v_library_id, v_user_id
  FROM public.consultas_locais_v2 cl
  WHERE cl.id = NEW.consulta_id;

  IF v_user_id IS NULL THEN
    RETURN NEW;
  END IF;

  -- Vérifier le flag macro biblio (local_consultation_enabled)
  IF v_library_id IS NOT NULL THEN
    SELECT lnp.local_consultation_enabled
      INTO v_local_consultation_enabled
    FROM public.library_notification_policies lnp
    WHERE lnp.library_id = v_library_id;
    v_local_consultation_enabled := COALESCE(v_local_consultation_enabled, true);
  END IF;

  IF NOT v_local_consultation_enabled THEN
    RETURN NEW;
  END IF;

  -- Vérifier le flag fin biblio (consulta_mail_agendada_enabled)
  IF v_library_id IS NOT NULL THEN
    SELECT lnp.consulta_mail_agendada_enabled
      INTO v_mail_enabled
    FROM public.library_notification_policies lnp
    WHERE lnp.library_id = v_library_id;
    v_mail_enabled := COALESCE(v_mail_enabled, true);
  END IF;

  IF NOT v_mail_enabled THEN
    RETURN NEW;
  END IF;

  -- Vérifier la préférence lectrice
  SELECT COALESCE(p.disable_consulta_pronta, false)
    INTO v_user_disabled
  FROM public.user_notification_preferences p
  WHERE p.user_id = v_user_id;
  v_user_disabled := COALESCE(v_user_disabled, false);

  IF v_user_disabled THEN
    RETURN NEW;
  END IF;

  -- Construire une référence courte
  v_consulta_ref := COALESCE(NEW.consulta_id::text, '?');

  -- Insertion in-app
  INSERT INTO public.user_notifications (
    user_id, library_id, category, title, body,
    link_type, link_id, is_read
  )
  VALUES (
    v_user_id,
    v_library_id,
    'consulta',
    'notif.consulta.agendada.title',
    'notif.consulta.agendada.body',
    'consulta',
    v_consulta_ref,
    false
  );

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."fn_replicate_consulta_agendada_to_inapp"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."fn_replicate_consulta_agendada_to_inapp"() IS 'Chantier #CL.7 (31/05/2026). Trigger frère du e-mail : réplique in-app sur transition workflow_stage -> consulta_agendada (B2 action lectrice). Respecte les deux flags biblio que le mail + préférence lectrice.';



CREATE OR REPLACE FUNCTION "public"."fn_replicate_reserva_pronta_to_inapp"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_library_id uuid;
  v_user_id uuid;
  v_mail_enabled boolean := true;       -- défaut fail-open (= comportement trigger e-mail)
  v_user_disabled boolean := false;     -- défaut fail-open (= pas de préférence = on insère)
  v_reserva_ref text;
BEGIN
  -- Détection de la transition cible
  IF NOT (TG_OP = 'UPDATE' AND NEW.workflow_stage = 'pronta_para_retirada'
          AND (OLD.workflow_stage IS DISTINCT FROM NEW.workflow_stage)) THEN
    RETURN NEW;
  END IF;

  -- Récupérer library_id et user_id depuis reservas_v2
  SELECT r.library_id, r.user_id
    INTO v_library_id, v_user_id
  FROM public.reservas_v2 r
  WHERE r.id = NEW.reserva_id;

  IF v_user_id IS NULL THEN
    -- Réservation sans user : pas de notification possible. Sort silencieusement.
    RETURN NEW;
  END IF;

  -- Vérifier le flag biblio (même que pour le mail — Architecture α)
  IF v_library_id IS NOT NULL THEN
    SELECT reservation_mail_pronta_para_retirada_enabled
      INTO v_mail_enabled
    FROM public.library_notification_policies
    WHERE library_id = v_library_id;
    v_mail_enabled := COALESCE(v_mail_enabled, true);
  END IF;

  IF NOT v_mail_enabled THEN
    RETURN NEW;  -- biblio a désactivé : ni mail ni in-app
  END IF;

  -- Vérifier la préférence lectrice (réduction seule)
  SELECT COALESCE(p.disable_reserva_pronta, false)
    INTO v_user_disabled
  FROM public.user_notification_preferences p
  WHERE p.user_id = v_user_id;
  v_user_disabled := COALESCE(v_user_disabled, false);

  IF v_user_disabled THEN
    RETURN NEW;  -- la lectrice a désactivé pour elle
  END IF;

  -- Construire une référence courte pour le titre (numéro de réserva)
  v_reserva_ref := COALESCE(NEW.reserva_id::text, '?');

  -- Insertion in-app. Clés i18n côté frontend, body en pt-BR ici par défaut
  -- (cf. paquet RGPD qui utilise déjà ce pattern de clés title/body).
  INSERT INTO public.user_notifications (
    user_id, library_id, category, title, body,
    link_type, link_id, is_read
  )
  VALUES (
    v_user_id,
    v_library_id,
    'reserva',
    'notif.reserva.prontaParaRetirada.title',
    'notif.reserva.prontaParaRetirada.body',
    'reserva',
    v_reserva_ref,
    false
  );

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."fn_replicate_reserva_pronta_to_inapp"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."fn_replicate_reserva_pronta_to_inapp"() IS 'Chantier #CL.7 (31/05/2026). Trigger frère du e-mail : réplique in-app sur transition workflow_stage -> pronta_para_retirada (B2 action lectrice). Respecte le même flag biblio que le mail (Architecture α) + préférence lectrice.';



CREATE OR REPLACE FUNCTION "public"."fn_required_governance_for_transition"("p_library_id" "uuid", "p_axis" "text", "p_new_value" "text") RETURNS "text"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_old_value     text;
  v_classification jsonb;
BEGIN
  -- Lecture de l'etat courant via les helpers du paquet A
  IF    p_axis = 'catalog_mode'     THEN v_old_value := public.fn_library_catalog_mode(p_library_id);
  ELSIF p_axis = 'circulation_mode' THEN v_old_value := public.fn_library_circulation_mode(p_library_id);
  ELSIF p_axis = 'network_mode'     THEN v_old_value := public.fn_library_network_mode(p_library_id);
  ELSIF p_axis = 'governance_mode'  THEN v_old_value := public.fn_library_governance_mode(p_library_id);
  ELSE
    RAISE EXCEPTION 'REQUIRED_GOVERNANCE_UNKNOWN_AXIS : axe inconnu (%)', p_axis
      USING ERRCODE = 'check_violation',
            HINT    = 'error.profile_change.unknown_axis';
  END IF;

  -- Si fn_library_*_mode retourne NULL : la biblio n'existe pas ou n'est pas visible
  IF v_old_value IS NULL THEN
    RAISE EXCEPTION 'REQUIRED_GOVERNANCE_LIBRARY_NOT_FOUND : biblio invisible ou inexistante (%)', p_library_id
      USING ERRCODE = 'no_data_found',
            HINT    = 'error.profile_change.library_not_found';
  END IF;

  -- Classification
  v_classification := public.fn_classify_transition(p_axis, v_old_value, p_new_value);

  RETURN v_classification ->> 'governance_required';
END;
$$;


ALTER FUNCTION "public"."fn_required_governance_for_transition"("p_library_id" "uuid", "p_axis" "text", "p_new_value" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."fn_required_governance_for_transition"("p_library_id" "uuid", "p_axis" "text", "p_new_value" "text") IS 'B.2 : retourne la gouvernance requise pour une transition envisagee sur une biblio donnee. Lit l''etat via fn_library_*_mode + appelle fn_classify_transition. Utilisable en UI avant proposition.';



CREATE OR REPLACE FUNCTION "public"."fn_resolve_caller_role_for_library"("p_library_id" "uuid") RETURNS "text"
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_uid uuid := auth.uid();
BEGIN
    IF v_uid IS NULL THEN
        RETURN NULL;
    END IF;
    
    -- 1. Rôle local prime : coordenador OU administrador
    -- (user_can_manage_library couvre les deux, comportement INCHANGÉ)
    IF user_can_manage_library(p_library_id) THEN
        RETURN 'coordenador';
    END IF;
    
    -- 2. Rôle local : librarian
    IF user_has_library_staff_role(v_uid, p_library_id) THEN
        RETURN 'librarian';
    END IF;
    
    -- 3. Rôle local : leitor (lecteur actif sur cette biblio)
    -- Paquet 20 v2 (11/05/2026, fix critique) : reconnaitre le role lecteur
    -- pour les users ayant une membership active sur la library.
    IF EXISTS (
        SELECT 1 
        FROM public.user_library_memberships
        WHERE user_id = v_uid
          AND library_id = p_library_id
          AND role = 'reader'
          AND status = 'active'
    ) THEN
        RETURN 'leitor';
    END IF;
    
    -- 4. Paquet B (11/05/2026) : si pas de rôle local, vérifier admin réseau.
    -- Permet à un admin réseau visitant une biblio dont il n'est pas membre
    -- d'avoir un rôle reconnu (au lieu de retourner NULL et d'être traité
    -- comme un visiteur anonyme par les RPC qui appellent cette fonction).
    IF fn_caller_is_network_admin() THEN
        RETURN 'network_admin';
    END IF;
    
    -- 5. Aucun rôle local, pas admin réseau
    RETURN NULL;
END;
$$;


ALTER FUNCTION "public"."fn_resolve_caller_role_for_library"("p_library_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."fn_resolve_caller_role_for_library"("p_library_id" "uuid") IS 'Retourne le rôle de l''appelant dans la biblio donnée. Rôle local prime sur le statut admin réseau. Si pas de rôle local mais admin réseau, retourne ''network_admin''. Sinon NULL. Modifié au paquet B (11/05/2026, spec v0.3).';



CREATE OR REPLACE FUNCTION "public"."fn_review_library_request"("p_request_id" "uuid", "p_new_status" "text", "p_review_notes" "text" DEFAULT NULL::"text") RETURNS "public"."library_requests"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_user_id uuid := auth.uid();
  v_current public.library_requests;
  v_row public.library_requests;
begin
  if v_user_id is null then
    raise exception 'Você precisa estar conectado para revisar esta solicitação.'
      using errcode = '42501';
  end if;

  if public.fn_current_user_can_review_library_requests() is not true then
    raise exception 'Você não tem permissão para revisar solicitações institucionais.'
      using errcode = '42501';
  end if;

  if p_request_id is null then
    raise exception 'Informe a solicitação a revisar.'
      using errcode = '23514';
  end if;

  if p_new_status not in ('em_analise', 'aprovada', 'recusada', 'arquivada') then
    raise exception 'Status de revisão inválido.'
      using errcode = '23514';
  end if;

  select *
  into v_current
  from public.library_requests
  where id = p_request_id
  for update;

  if not found then
    raise exception 'Solicitação não encontrada.'
      using errcode = 'P0002';
  end if;

  if v_current.request_status = 'arquivada' then
    raise exception 'Esta solicitação já está arquivada e não pode mais ser alterada por esta função.'
      using errcode = '23514';
  end if;

  if v_current.request_status = 'aprovada'
     and coalesce(v_current.approved_library_ref, '') <> '' then
    raise exception 'Esta solicitação já foi aprovada e vinculada a uma biblioteca. Use a etapa de ativação adequada.'
      using errcode = '23514';
  end if;

  update public.library_requests
  set
    request_status = p_new_status,
    review_notes = nullif(btrim(coalesce(p_review_notes, '')), ''),
    reviewed_at = now(),
    reviewed_by_user_id = v_user_id
  where id = p_request_id
  returning * into v_row;

  return v_row;
end;
$$;


ALTER FUNCTION "public"."fn_review_library_request"("p_request_id" "uuid", "p_new_status" "text", "p_review_notes" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."fn_review_library_request"("p_request_id" "uuid", "p_new_status" "text", "p_review_notes" "text") IS 'Met à jour le statut de revue d’une demande institutionnelle sans encore activer de bibliothèque ni de membership.';



CREATE OR REPLACE FUNCTION "public"."fn_seed_draft_contributors"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
BEGIN
  IF NEW.published_book_id IS NOT NULL
     AND NOT EXISTS (SELECT 1 FROM public.book_draft_contributors dc WHERE dc.draft_id = NEW.id) THEN
    INSERT INTO public.book_draft_contributors (draft_id, position, name, role, is_primary, author_id)
    SELECT NEW.id, bc.position, bc.name, bc.role, bc.is_primary, bc.author_id
    FROM public.book_contributors bc
    WHERE bc.book_id = NEW.published_book_id
    ORDER BY bc.position, bc.id;
  END IF;
  RETURN NULL;
END;
$$;


