CREATE OR REPLACE FUNCTION "public"."fn_send_weekly_report_now"("p_library_id" "uuid") RETURNS bigint
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'vault', 'extensions', 'pg_temp'
    AS $_$
declare
  v_url    text;
  v_secret text;
  v_week   record;
  v_active boolean;
  v_req_id bigint;
begin
  if p_library_id is null then
    raise exception 'library_id_required';
  end if;

  -- Garde-fou d'autorisation (la RPC est exposee au frontend authentifie).
  if not public.user_can_manage_library_notifications(p_library_id) then
    raise exception 'not_authorized' using errcode = '42501';
  end if;

  select l.is_active into v_active
  from public.libraries l
  where l.id = p_library_id;

  if v_active is null then
    raise exception 'library_not_found';
  end if;
  if v_active is not true then
    raise exception 'library_inactive';
  end if;

  v_url := regexp_replace(
    public.fn_internal_get_vault_secret('SUPABASE_URL'),
    '/+$', ''
  ) || '/functions/v1/notify-weekly-report';

  v_secret := public.fn_internal_get_vault_secret('WEBHOOK_SECRET_NOTIFY_WEEKLY_REPORT');

  select * into v_week from public.fn_internal_previous_iso_week();

  v_req_id := net.http_post(
    url := v_url,
    headers := jsonb_build_object(
      'Content-Type', 'application/json',
      'x-webhook-secret', v_secret
    ),
    body := jsonb_build_object(
      'source', 'manual',
      'job', 'fn_send_weekly_report_now',
      'scheduled_at', now(),
      'initiated_by', auth.uid()::text,
      'library_id', p_library_id::text,
      'week_start', to_char(v_week.week_start, 'YYYY-MM-DD'),
      'week_end',   to_char(v_week.week_end,   'YYYY-MM-DD'),
      'tz', 'UTC'
    ),
    timeout_milliseconds := 60000
  );

  return v_req_id;
end;
$_$;


ALTER FUNCTION "public"."fn_send_weekly_report_now"("p_library_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."fn_send_weekly_report_now"("p_library_id" "uuid") IS 'EA-13 (etape 8 Biblioteca, 08/06/2026) : envoi a la demande du rapport hebdomadaire (semaine ISO precedente) d''une bibliotheque via l''Edge Function notify-weekly-report (Resend). Calque sur fn_cron_notify_weekly_report_per_library, restreint a une biblio + garde-fou user_can_manage_library_notifications. Declenchee par le bouton Enviar relatorio du Painel.';



CREATE OR REPLACE FUNCTION "public"."fn_set_circulation_limits"("p_policy_set_id" bigint, "p_max_loans" integer DEFAULT NULL::integer, "p_max_reservations" integer DEFAULT NULL::integer, "p_max_consultations" integer DEFAULT NULL::integer) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_library_id uuid;
BEGIN
  SELECT library_id INTO v_library_id
    FROM public.library_circulation_policy_sets WHERE id = p_policy_set_id;
  IF v_library_id IS NULL THEN
    RAISE EXCEPTION 'Jeu de règles introuvable.' USING HINT = 'error.policy_set.not_found';
  END IF;

  IF NOT public.user_has_library_staff_role(auth.uid(), v_library_id) THEN
    RAISE EXCEPTION 'Acesso restrito ao staff da biblioteca.' USING ERRCODE = '42501';
  END IF;

  IF (p_max_loans         IS NOT NULL AND p_max_loans         < 0)
   OR (p_max_reservations  IS NOT NULL AND p_max_reservations  < 0)
   OR (p_max_consultations IS NOT NULL AND p_max_consultations < 0) THEN
    RAISE EXCEPTION 'Plafond invalide (doit être >= 0).' USING HINT = 'error.circulation.limit_invalid';
  END IF;

  UPDATE public.library_circulation_policy_sets
     SET max_concurrent_loans         = p_max_loans,
         max_concurrent_reservations  = p_max_reservations,
         max_concurrent_consultations = p_max_consultations
   WHERE id = p_policy_set_id;
END $$;


ALTER FUNCTION "public"."fn_set_circulation_limits"("p_policy_set_id" bigint, "p_max_loans" integer, "p_max_reservations" integer, "p_max_consultations" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_set_my_notification_preferences"("p_disable_reserva_pronta" boolean, "p_disable_consulta_pronta" boolean) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_user_id uuid := auth.uid();
BEGIN
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'auth required'
      USING HINT = 'fn_set_my_notification_preferences: no authenticated user';
  END IF;

  INSERT INTO public.user_notification_preferences (
    user_id,
    disable_reserva_pronta,
    disable_consulta_pronta,
    updated_at
  )
  VALUES (
    v_user_id,
    COALESCE(p_disable_reserva_pronta, false),
    COALESCE(p_disable_consulta_pronta, false),
    now()
  )
  ON CONFLICT (user_id) DO UPDATE
    SET disable_reserva_pronta  = EXCLUDED.disable_reserva_pronta,
        disable_consulta_pronta = EXCLUDED.disable_consulta_pronta,
        updated_at              = now();
END;
$$;


