CREATE OR REPLACE FUNCTION "public"."fn_set_retention_policy"("p_library_id" "uuid", "p_loans_days" integer, "p_reservations_days" integer, "p_consultations_days" integer, "p_notifications_days" integer, "p_notes" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_user_id uuid := auth.uid();
  v_can_manage boolean;
BEGIN
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Authentication required.' USING ERRCODE = '42501';
  END IF;

  -- F.2 v0.3 : la politique de retention est reservee aux coordenador
  -- de la biblio (role 'administrador' supprime en F.1).
  SELECT EXISTS (
    SELECT 1 FROM public.user_library_memberships m
    WHERE m.user_id = v_user_id
      AND m.library_id = p_library_id
      AND m.status = 'active'
      AND m.role = 'coordenador'
  ) INTO v_can_manage;

  IF NOT v_can_manage THEN
    RAISE EXCEPTION 'Vous n''avez pas le droit de modifier la politique de retention de cette bibliotheque.'
      USING ERRCODE = '42501';
  END IF;

  IF p_loans_days IS NOT NULL AND p_loans_days < 0 THEN
    RAISE EXCEPTION 'Duree de retention emprunts invalide (doit etre >= 0).' USING ERRCODE = '23514';
  END IF;
  IF p_reservations_days IS NOT NULL AND p_reservations_days < 0 THEN
    RAISE EXCEPTION 'Duree de retention reservations invalide (doit etre >= 0).' USING ERRCODE = '23514';
  END IF;
  IF p_consultations_days IS NOT NULL AND p_consultations_days < 0 THEN
    RAISE EXCEPTION 'Duree de retention consultations invalide (doit etre >= 0).' USING ERRCODE = '23514';
  END IF;
  IF p_notifications_days IS NOT NULL AND p_notifications_days < 0 THEN
    RAISE EXCEPTION 'Duree de retention notifications invalide (doit etre >= 0).' USING ERRCODE = '23514';
  END IF;

  INSERT INTO public.library_retention_policies (
    library_id,
    retention_loans_days,
    retention_reservations_days,
    retention_consultations_days,
    retention_notifications_days,
    notes,
    updated_by
  ) VALUES (
    p_library_id,
    p_loans_days,
    p_reservations_days,
    p_consultations_days,
    p_notifications_days,
    p_notes,
    v_user_id
  )
  ON CONFLICT (library_id) DO UPDATE
    SET
      retention_loans_days = EXCLUDED.retention_loans_days,
      retention_reservations_days = EXCLUDED.retention_reservations_days,
      retention_consultations_days = EXCLUDED.retention_consultations_days,
      retention_notifications_days = EXCLUDED.retention_notifications_days,
      notes = EXCLUDED.notes,
      updated_by = EXCLUDED.updated_by;

  RETURN public.fn_get_retention_policy(p_library_id);
END;
$$;


ALTER FUNCTION "public"."fn_set_retention_policy"("p_library_id" "uuid", "p_loans_days" integer, "p_reservations_days" integer, "p_consultations_days" integer, "p_notifications_days" integer, "p_notes" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_subjects_autoslug"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
DECLARE base text; cand text; i int := 2;
BEGIN
  IF NEW.slug IS NOT NULL AND btrim(NEW.slug) <> '' THEN RETURN NEW; END IF;
  base := btrim(regexp_replace(lower(f_normalize_search(
            COALESCE(NEW.label_i18n->>'pt-BR', NEW.label_i18n->>'en',
                     (SELECT value FROM jsonb_each_text(NEW.label_i18n) LIMIT 1)))),
          '[^a-z0-9]+', '-', 'g'), '-');
  IF base IS NULL OR base = '' THEN base := 'sujet'; END IF;
  cand := base;
  WHILE EXISTS (SELECT 1 FROM public.subjects WHERE slug = cand) LOOP
    cand := base || '-' || i; i := i + 1;
  END LOOP;
  NEW.slug := cand;
  RETURN NEW;
END $$;


ALTER FUNCTION "public"."fn_subjects_autoslug"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_submit_library_request"("p_library_name" "text", "p_library_short_name" "text" DEFAULT NULL::"text", "p_city" "text" DEFAULT NULL::"text", "p_state_region" "text" DEFAULT NULL::"text", "p_country" "text" DEFAULT 'Brasil'::"text", "p_library_email" "text" DEFAULT NULL::"text", "p_library_phone" "text" DEFAULT NULL::"text", "p_library_address" "text" DEFAULT NULL::"text", "p_project_stage" "text" DEFAULT NULL::"text", "p_contact_name" "text" DEFAULT NULL::"text", "p_contact_email" "text" DEFAULT NULL::"text", "p_contact_phone" "text" DEFAULT NULL::"text", "p_contact_role" "text" DEFAULT NULL::"text", "p_first_manager_intent" "text" DEFAULT 'sim'::"text", "p_summary" "text" DEFAULT NULL::"text", "p_public_profile" "text" DEFAULT NULL::"text", "p_collection_profile" "text" DEFAULT NULL::"text", "p_needs" "text" DEFAULT NULL::"text", "p_confirm_real" boolean DEFAULT false, "p_confirm_contact" boolean DEFAULT false, "p_requested_catalog_mode" "text" DEFAULT NULL::"text", "p_requested_circulation_mode" "text" DEFAULT NULL::"text", "p_requested_network_mode" "text" DEFAULT NULL::"text", "p_requested_governance_mode" "text" DEFAULT NULL::"text", "p_profile_template_chosen" "text" DEFAULT NULL::"text") RETURNS "public"."library_requests"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions'
    AS $$
declare
  v_user_id uuid := auth.uid();
  v_email_snapshot text;
  v_row public.library_requests;
begin
  if v_user_id is null then
    raise exception 'Voce precisa estar conectado para enviar esta solicitacao.'
      using errcode = '42501';
  end if;

  -- Validations existantes (preservees)
  if nullif(btrim(coalesce(p_library_name, '')), '') is null then
    raise exception 'Informe o nome da biblioteca.' using errcode = '23514';
  end if;
  if nullif(btrim(coalesce(p_city, '')), '') is null then
    raise exception 'Informe a cidade da biblioteca.' using errcode = '23514';
  end if;
  if nullif(btrim(coalesce(p_country, '')), '') is null then
    raise exception 'Informe o pais da biblioteca.' using errcode = '23514';
  end if;
  if nullif(btrim(coalesce(p_library_email, '')), '') is null then
    raise exception 'Informe o e-mail principal da biblioteca.' using errcode = '23514';
  end if;
  if nullif(btrim(coalesce(p_contact_name, '')), '') is null then
    raise exception 'Informe o nome da pessoa responsavel pelo primeiro contato.' using errcode = '23514';
  end if;
  if nullif(btrim(coalesce(p_contact_email, '')), '') is null then
    raise exception 'Informe o e-mail da pessoa responsavel.' using errcode = '23514';
  end if;
  if nullif(btrim(coalesce(p_summary, '')), '') is null then
    raise exception 'Informe uma breve apresentacao da biblioteca ou coletivo.' using errcode = '23514';
  end if;

  if p_project_stage not in (
    'em_funcionamento', 'em_montagem', 'em_planejamento', 'reativacao',
    'em_formacao', 'em_organizacao'
  ) then
    raise exception 'Situacao atual invalida.' using errcode = '23514';
  end if;

  if coalesce(p_first_manager_intent, 'sim') not in ('sim', 'nao', 'a_definir') then
    raise exception 'Valor invalido para o primeiro perfil responsavel.' using errcode = '23514';
  end if;

  if coalesce(p_confirm_real, false) is not true
     or coalesce(p_confirm_contact, false) is not true then
    raise exception 'As duas confirmacoes obrigatorias precisam estar marcadas.' using errcode = '23514';
  end if;

  -- Paquet F (20/05/2026) : validations sur les 4 axes profil (OBLIGATOIRES)
  if p_requested_catalog_mode is null
     or p_requested_circulation_mode is null
     or p_requested_network_mode is null
     or p_requested_governance_mode is null then
    raise exception 'Informe os 4 modos de funcionamento da biblioteca (catalogo, circulacao, rede, governanca).'
      using errcode = '23514',
            hint = 'error.library_request.profile_axes_required';
  end if;

  if p_requested_catalog_mode not in ('local_only', 'network_published') then
    raise exception 'Modo de catalogo invalido (%)' , p_requested_catalog_mode
      using errcode = '23514', hint = 'error.library_request.invalid_catalog_mode';
  end if;
  if p_requested_circulation_mode not in ('off', 'informal', 'full_sigb') then
    raise exception 'Modo de circulacao invalido (%)' , p_requested_circulation_mode
      using errcode = '23514', hint = 'error.library_request.invalid_circulation_mode';
  end if;
  if p_requested_network_mode not in ('isolated', 'observer', 'federated') then
    raise exception 'Modo de rede invalido (%)' , p_requested_network_mode
      using errcode = '23514', hint = 'error.library_request.invalid_network_mode';
  end if;
  if p_requested_governance_mode not in ('informal', 'staff_roles', 'full_governance') then
    raise exception 'Modo de governanca invalido (%)' , p_requested_governance_mode
      using errcode = '23514', hint = 'error.library_request.invalid_governance_mode';
  end if;

  -- Coherence catalog/network
  if p_requested_catalog_mode = 'network_published'
     and p_requested_network_mode not in ('observer', 'federated') then
    raise exception 'Catalogo publicado na rede requer modo de rede observer ou federated.'
      using errcode = '23514', hint = 'error.library_request.catalog_network_incoherence';
  end if;

  -- profile_template_chosen est optionnel mais s'il est present il doit etre valide
  if p_profile_template_chosen is not null
     and p_profile_template_chosen not in ('A', 'B', 'C', 'D', 'custom') then
    raise exception 'Template de perfil invalido (%)' , p_profile_template_chosen
      using errcode = '23514', hint = 'error.library_request.invalid_profile_template';
  end if;

  v_email_snapshot := lower(
    coalesce(
      nullif(btrim(auth.jwt() ->> 'email'), ''),
      nullif(btrim(p_contact_email), ''),
      nullif(btrim(p_library_email), '')
    )
  );

  insert into public.library_requests (
    submitted_by_user_id,
    submitted_by_email_snapshot,
    library_name,
    library_short_name,
    city,
    state_region,
    country,
    library_email,
    library_phone,
    library_address,
    project_stage,
    contact_name,
    contact_email,
    contact_phone,
    contact_role,
    first_manager_intent,
    summary,
    public_profile,
    collection_profile,
    needs,
    confirm_real,
    confirm_contact,
    -- Paquet F : 4 axes profil + template
    requested_catalog_mode,
    requested_circulation_mode,
    requested_network_mode,
    requested_governance_mode,
    profile_template_chosen
  )
  values (
    v_user_id,
    v_email_snapshot,
    btrim(p_library_name),
    nullif(btrim(coalesce(p_library_short_name, '')), ''),
    btrim(p_city),
    nullif(btrim(coalesce(p_state_region, '')), ''),
    btrim(p_country),
    lower(btrim(p_library_email)),
    nullif(btrim(coalesce(p_library_phone, '')), ''),
    nullif(btrim(coalesce(p_library_address, '')), ''),
    p_project_stage,
    btrim(p_contact_name),
    lower(btrim(p_contact_email)),
    nullif(btrim(coalesce(p_contact_phone, '')), ''),
    nullif(btrim(coalesce(p_contact_role, '')), ''),
    coalesce(p_first_manager_intent, 'sim'),
    btrim(p_summary),
    nullif(btrim(coalesce(p_public_profile, '')), ''),
    nullif(btrim(coalesce(p_collection_profile, '')), ''),
    nullif(btrim(coalesce(p_needs, '')), ''),
    true,
    true,
    p_requested_catalog_mode,
    p_requested_circulation_mode,
    p_requested_network_mode,
    p_requested_governance_mode,
    p_profile_template_chosen
  )
  returning * into v_row;

  return v_row;
end;
$$;


ALTER FUNCTION "public"."fn_submit_library_request"("p_library_name" "text", "p_library_short_name" "text", "p_city" "text", "p_state_region" "text", "p_country" "text", "p_library_email" "text", "p_library_phone" "text", "p_library_address" "text", "p_project_stage" "text", "p_contact_name" "text", "p_contact_email" "text", "p_contact_phone" "text", "p_contact_role" "text", "p_first_manager_intent" "text", "p_summary" "text", "p_public_profile" "text", "p_collection_profile" "text", "p_needs" "text", "p_confirm_real" boolean, "p_confirm_contact" boolean, "p_requested_catalog_mode" "text", "p_requested_circulation_mode" "text", "p_requested_network_mode" "text", "p_requested_governance_mode" "text", "p_profile_template_chosen" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_submit_library_request_via_claim"("p_claim_token" "text", "p_library_name" "text", "p_library_short_name" "text" DEFAULT NULL::"text", "p_city" "text" DEFAULT NULL::"text", "p_state_region" "text" DEFAULT NULL::"text", "p_country" "text" DEFAULT 'Brasil'::"text", "p_library_email" "text" DEFAULT NULL::"text", "p_library_phone" "text" DEFAULT NULL::"text", "p_library_address" "text" DEFAULT NULL::"text", "p_project_stage" "text" DEFAULT NULL::"text", "p_contact_name" "text" DEFAULT NULL::"text", "p_contact_email" "text" DEFAULT NULL::"text", "p_contact_phone" "text" DEFAULT NULL::"text", "p_contact_role" "text" DEFAULT NULL::"text", "p_first_manager_intent" "text" DEFAULT 'sim'::"text", "p_summary" "text" DEFAULT NULL::"text", "p_public_profile" "text" DEFAULT NULL::"text", "p_collection_profile" "text" DEFAULT NULL::"text", "p_needs" "text" DEFAULT NULL::"text", "p_confirm_real" boolean DEFAULT false, "p_confirm_contact" boolean DEFAULT false, "p_requested_catalog_mode" "text" DEFAULT NULL::"text", "p_requested_circulation_mode" "text" DEFAULT NULL::"text", "p_requested_network_mode" "text" DEFAULT NULL::"text", "p_requested_governance_mode" "text" DEFAULT NULL::"text", "p_profile_template_chosen" "text" DEFAULT NULL::"text") RETURNS "public"."library_requests"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions'
    AS $$
declare
  v_claim_context jsonb;
  v_user_id uuid := auth.uid();
  v_email_snapshot text;
  v_row public.library_requests;
begin
  -- Validation du token claim (reuse de la fonction existante)
  v_claim_context := public.fn_get_library_request_claim_context(p_claim_token);

  if v_claim_context is null or v_claim_context->>'valid' <> 'true' then
    raise exception 'Token de convite invalido ou expirado.'
      using errcode = '42501', hint = 'error.library_request.invalid_claim';
  end if;

  -- Validations base (identiques a fn_submit_library_request)
  if nullif(btrim(coalesce(p_library_name, '')), '') is null then
    raise exception 'Informe o nome da biblioteca.' using errcode = '23514';
  end if;
  if nullif(btrim(coalesce(p_city, '')), '') is null then
    raise exception 'Informe a cidade da biblioteca.' using errcode = '23514';
  end if;
  if nullif(btrim(coalesce(p_country, '')), '') is null then
    raise exception 'Informe o pais da biblioteca.' using errcode = '23514';
  end if;
  if nullif(btrim(coalesce(p_library_email, '')), '') is null then
    raise exception 'Informe o e-mail principal da biblioteca.' using errcode = '23514';
  end if;
  if nullif(btrim(coalesce(p_contact_name, '')), '') is null then
    raise exception 'Informe o nome da pessoa responsavel pelo primeiro contato.' using errcode = '23514';
  end if;
  if nullif(btrim(coalesce(p_contact_email, '')), '') is null then
    raise exception 'Informe o e-mail da pessoa responsavel.' using errcode = '23514';
  end if;
  if nullif(btrim(coalesce(p_summary, '')), '') is null then
    raise exception 'Informe uma breve apresentacao da biblioteca ou coletivo.' using errcode = '23514';
  end if;
  if p_project_stage not in (
    'em_funcionamento', 'em_montagem', 'em_planejamento', 'reativacao',
    'em_formacao', 'em_organizacao'
  ) then
    raise exception 'Situacao atual invalida.' using errcode = '23514';
  end if;
  if coalesce(p_first_manager_intent, 'sim') not in ('sim', 'nao', 'a_definir') then
    raise exception 'Valor invalido para o primeiro perfil responsavel.' using errcode = '23514';
  end if;
  if coalesce(p_confirm_real, false) is not true
     or coalesce(p_confirm_contact, false) is not true then
    raise exception 'As duas confirmacoes obrigatorias precisam estar marcadas.' using errcode = '23514';
  end if;

  -- Paquet F : validations des 4 axes (OBLIGATOIRES)
  if p_requested_catalog_mode is null
     or p_requested_circulation_mode is null
     or p_requested_network_mode is null
     or p_requested_governance_mode is null then
    raise exception 'Informe os 4 modos de funcionamento da biblioteca.'
      using errcode = '23514', hint = 'error.library_request.profile_axes_required';
  end if;
  if p_requested_catalog_mode not in ('local_only', 'network_published') then
    raise exception 'Modo de catalogo invalido (%)' , p_requested_catalog_mode
      using errcode = '23514', hint = 'error.library_request.invalid_catalog_mode';
  end if;
  if p_requested_circulation_mode not in ('off', 'informal', 'full_sigb') then
    raise exception 'Modo de circulacao invalido (%)' , p_requested_circulation_mode
      using errcode = '23514', hint = 'error.library_request.invalid_circulation_mode';
  end if;
  if p_requested_network_mode not in ('isolated', 'observer', 'federated') then
    raise exception 'Modo de rede invalido (%)' , p_requested_network_mode
      using errcode = '23514', hint = 'error.library_request.invalid_network_mode';
  end if;
  if p_requested_governance_mode not in ('informal', 'staff_roles', 'full_governance') then
    raise exception 'Modo de governanca invalido (%)' , p_requested_governance_mode
      using errcode = '23514', hint = 'error.library_request.invalid_governance_mode';
  end if;
  if p_requested_catalog_mode = 'network_published'
     and p_requested_network_mode not in ('observer', 'federated') then
    raise exception 'Catalogo publicado na rede requer modo de rede observer ou federated.'
      using errcode = '23514', hint = 'error.library_request.catalog_network_incoherence';
  end if;
  if p_profile_template_chosen is not null
     and p_profile_template_chosen not in ('A', 'B', 'C', 'D', 'custom') then
    raise exception 'Template de perfil invalido (%)' , p_profile_template_chosen
      using errcode = '23514', hint = 'error.library_request.invalid_profile_template';
  end if;

  -- Marquer le claim comme utilise
  perform public.fn_consume_library_request_claim(p_claim_token);

  v_email_snapshot := lower(
    coalesce(
      nullif(btrim(v_claim_context->>'email'), ''),
      nullif(btrim(auth.jwt() ->> 'email'), ''),
      nullif(btrim(p_contact_email), ''),
      nullif(btrim(p_library_email), '')
    )
  );

  insert into public.library_requests (
    submitted_by_user_id,
    submitted_by_email_snapshot,
    library_name,
    library_short_name,
    city,
    state_region,
    country,
    library_email,
    library_phone,
    library_address,
    project_stage,
    contact_name,
    contact_email,
    contact_phone,
    contact_role,
    first_manager_intent,
    summary,
    public_profile,
    collection_profile,
    needs,
    confirm_real,
    confirm_contact,
    requested_catalog_mode,
    requested_circulation_mode,
    requested_network_mode,
    requested_governance_mode,
    profile_template_chosen
  )
  values (
    coalesce(v_user_id, (v_claim_context->>'user_id')::uuid),
    v_email_snapshot,
    btrim(p_library_name),
    nullif(btrim(coalesce(p_library_short_name, '')), ''),
    btrim(p_city),
    nullif(btrim(coalesce(p_state_region, '')), ''),
    btrim(p_country),
    lower(btrim(p_library_email)),
    nullif(btrim(coalesce(p_library_phone, '')), ''),
    nullif(btrim(coalesce(p_library_address, '')), ''),
    p_project_stage,
    btrim(p_contact_name),
    lower(btrim(p_contact_email)),
    nullif(btrim(coalesce(p_contact_phone, '')), ''),
    nullif(btrim(coalesce(p_contact_role, '')), ''),
    coalesce(p_first_manager_intent, 'sim'),
    btrim(p_summary),
    nullif(btrim(coalesce(p_public_profile, '')), ''),
    nullif(btrim(coalesce(p_collection_profile, '')), ''),
    nullif(btrim(coalesce(p_needs, '')), ''),
    true,
    true,
    p_requested_catalog_mode,
    p_requested_circulation_mode,
    p_requested_network_mode,
    p_requested_governance_mode,
    p_profile_template_chosen
  )
  returning * into v_row;

  return v_row;
end;
$$;


ALTER FUNCTION "public"."fn_submit_library_request_via_claim"("p_claim_token" "text", "p_library_name" "text", "p_library_short_name" "text", "p_city" "text", "p_state_region" "text", "p_country" "text", "p_library_email" "text", "p_library_phone" "text", "p_library_address" "text", "p_project_stage" "text", "p_contact_name" "text", "p_contact_email" "text", "p_contact_phone" "text", "p_contact_role" "text", "p_first_manager_intent" "text", "p_summary" "text", "p_public_profile" "text", "p_collection_profile" "text", "p_needs" "text", "p_confirm_real" boolean, "p_confirm_contact" boolean, "p_requested_catalog_mode" "text", "p_requested_circulation_mode" "text", "p_requested_network_mode" "text", "p_requested_governance_mode" "text", "p_profile_template_chosen" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_sync_book_authors_from_contributor"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
BEGIN
  -- Retrait du lien associe a l'ancienne valeur (UPDATE author_id change / DELETE)
  IF (TG_OP = 'DELETE')
     OR (TG_OP = 'UPDATE' AND OLD.author_id IS NOT NULL
         AND OLD.author_id IS DISTINCT FROM NEW.author_id) THEN
    IF OLD.author_id IS NOT NULL THEN
      -- Ne supprimer que si aucun AUTRE contributeur ne porte le meme lien.
      IF NOT EXISTS (
        SELECT 1 FROM public.book_contributors c
        WHERE c.book_id = OLD.book_id AND c.author_id = OLD.author_id
          AND c.role = OLD.role AND c.position = OLD.position
          AND c.id <> OLD.id
      ) THEN
        DELETE FROM public.book_authors ba
        WHERE ba.book_id = OLD.book_id AND ba.author_id = OLD.author_id
          AND ba.role = OLD.role AND ba.ord = OLD.position;
      END IF;
    END IF;
  END IF;

  -- Ajout du lien pour la nouvelle valeur (INSERT / UPDATE)
  IF (TG_OP IN ('INSERT', 'UPDATE')) AND NEW.author_id IS NOT NULL THEN
    INSERT INTO public.book_authors (book_id, author_id, role, ord)
    VALUES (NEW.book_id, NEW.author_id, NEW.role, NEW.position::smallint)
    ON CONFLICT (book_id, author_id, role, ord) DO NOTHING;
  END IF;

  RETURN NULL; -- AFTER trigger
END;
$$;


ALTER FUNCTION "public"."fn_sync_book_authors_from_contributor"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."fn_sync_book_authors_from_contributor"() IS 'Maintient book_authors a partir de book_contributors.author_id (cible, pas de rebuild). Paquet liaison autorites du 05/06/2026.';



CREATE OR REPLACE FUNCTION "public"."fn_sync_book_contributors_on_publish"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_prior jsonb;
BEGIN
  IF NEW.published_book_id IS NULL
     OR NOT EXISTS (SELECT 1 FROM public.book_draft_contributors dc WHERE dc.draft_id = NEW.id) THEN
    RETURN NULL;
  END IF;

  -- Filet : author_id existants par nom normalise (repli quand le brouillon
  -- ne porte pas de lien explicite).
  SELECT jsonb_object_agg(nf, author_id) INTO v_prior
  FROM (
    SELECT public.fn_normalize_name(name) AS nf, max(author_id) AS author_id
    FROM public.book_contributors
    WHERE book_id = NEW.published_book_id AND author_id IS NOT NULL
    GROUP BY public.fn_normalize_name(name)
  ) s;

  DELETE FROM public.book_contributors WHERE book_id = NEW.published_book_id;

  INSERT INTO public.book_contributors (book_id, position, name, role, is_primary, author_id)
  SELECT NEW.published_book_id, dc.position, dc.name, dc.role, dc.is_primary,
         COALESCE(dc.author_id, NULLIF(v_prior ->> public.fn_normalize_name(dc.name), '')::bigint)
  FROM public.book_draft_contributors dc
  WHERE dc.draft_id = NEW.id
  ORDER BY dc.position, dc.id;

  RETURN NULL;
END;
$$;


ALTER FUNCTION "public"."fn_sync_book_contributors_on_publish"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."fn_sync_book_contributors_on_publish"() IS 'Sync book_contributors depuis le brouillon a la publication (preserve author_id). Paquet du 05/06/2026.';



CREATE OR REPLACE FUNCTION "public"."fn_sync_book_subjects_on_publish"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
BEGIN
  IF NEW.published_book_id IS NOT NULL THEN
    DELETE FROM public.book_subjects WHERE book_id = NEW.published_book_id;
    INSERT INTO public.book_subjects (book_id, subject_id, ord)
      SELECT NEW.published_book_id, ds.subject_id, ds.ord
      FROM public.book_draft_subjects ds WHERE ds.book_draft_id = NEW.id
      ON CONFLICT (book_id, subject_id) DO NOTHING;
  END IF;
  RETURN NULL;
END $$;


ALTER FUNCTION "public"."fn_sync_book_subjects_on_publish"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_sync_history_enabled"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_user_id     uuid;
  v_library_id  uuid;
  v_all_disabled boolean;
BEGIN
  IF TG_OP = 'DELETE' THEN
    v_user_id := OLD.user_id;  v_library_id := OLD.library_id;
  ELSE
    v_user_id := NEW.user_id;  v_library_id := NEW.library_id;
  END IF;

  SELECT (COUNT(*) FILTER (WHERE disable_retention = true) = 3)
    INTO v_all_disabled
    FROM public.user_history_retention_preferences
   WHERE user_id = v_user_id AND library_id = v_library_id;

  UPDATE public.user_library_memberships
     SET history_enabled = NOT v_all_disabled
   WHERE user_id = v_user_id AND library_id = v_library_id;

  IF TG_OP = 'DELETE' THEN RETURN OLD; ELSE RETURN NEW; END IF;
END;
$$;


ALTER FUNCTION "public"."fn_sync_history_enabled"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_sync_publisher_id_on_publish"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  -- If publisher_id was not set but editora is populated, try to match
  IF NEW.publisher_id IS NULL AND NEW.editora IS NOT NULL AND trim(NEW.editora) != '' THEN
    SELECT p.id INTO NEW.publisher_id
    FROM public.publishers p
    WHERE lower(p.name) = lower(trim(NEW.editora))
    LIMIT 1;
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."fn_sync_publisher_id_on_publish"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_task_adopt_suggestion"("p_suggestion_code" "text", "p_library_id" "uuid", "p_locale" "text" DEFAULT 'pt-BR'::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_sugg painel_task_suggestion_catalog%ROWTYPE;
  v_new  painel_recurring_task_rules%ROWTYPE;
  v_title text;
  v_desc  text;
BEGIN
  IF p_suggestion_code IS NULL OR p_library_id IS NULL THEN
    RAISE EXCEPTION 'fn_task_adopt_suggestion: p_suggestion_code et p_library_id obligatoires';
  END IF;

  SELECT * INTO v_sugg
  FROM painel_task_suggestion_catalog
  WHERE code = p_suggestion_code AND is_active = true;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'fn_task_adopt_suggestion: suggestion % introuvable ou inactive', p_suggestion_code;
  END IF;

  -- Texte simple dans la locale demandee (repli pt-BR) : conserve pour repli et
  -- compatibilite. L'i18n complet est stocke en parallele (title_i18n).
  v_title := COALESCE(v_sugg.title_i18n ->> p_locale, v_sugg.title_i18n ->> 'pt-BR');
  v_desc  := COALESCE(v_sugg.description_i18n ->> p_locale, v_sugg.description_i18n ->> 'pt-BR');

  INSERT INTO painel_recurring_task_rules (
    library_id, interval_count, interval_unit, label,
    template_title, template_description, template_priority, template_tags,
    adopted_from_suggestion_code, title_i18n, description_i18n
  )
  VALUES (
    p_library_id, v_sugg.suggested_interval_count, v_sugg.suggested_interval_unit, v_title,
    v_title, v_desc, 'media', ARRAY[]::text[],
    v_sugg.code, v_sugg.title_i18n, v_sugg.description_i18n
  )
  RETURNING * INTO v_new;

  RETURN to_jsonb(v_new) || jsonb_build_object('adopted_from_suggestion', v_sugg.code);
END;
$$;


ALTER FUNCTION "public"."fn_task_adopt_suggestion"("p_suggestion_code" "text", "p_library_id" "uuid", "p_locale" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_task_create"("p_library_id" "uuid", "p_title" "text", "p_description" "text" DEFAULT NULL::"text", "p_priority" "text" DEFAULT 'media'::"text", "p_owner" "text" DEFAULT NULL::"text", "p_due_date" "date" DEFAULT NULL::"date", "p_tags" "text"[] DEFAULT ARRAY[]::"text"[]) RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_new painel_internal_tasks%ROWTYPE;
BEGIN
  -- Validation minimale
  IF p_library_id IS NULL OR p_title IS NULL OR btrim(p_title) = '' THEN
    RAISE EXCEPTION 'fn_task_create: p_library_id et p_title obligatoires';
  END IF;

  -- INSERT (la RLS painel_internal_tasks_insert vérifie
  -- user_can_act_as_staff_on_library automatiquement)
  INSERT INTO painel_internal_tasks (
    library_id,
    title,
    description,
    priority,
    status,
    owner,
    due_date,
    tags
  )
  VALUES (
    p_library_id,
    btrim(p_title),
    NULLIF(btrim(COALESCE(p_description, '')), ''),
    COALESCE(p_priority, 'media'),
    'pendente',  -- doctrine 21/05 : statut frontend
    NULLIF(btrim(COALESCE(p_owner, '')), ''),
    p_due_date,
    COALESCE(p_tags, ARRAY[]::text[])
  )
  RETURNING * INTO v_new;

  RETURN to_jsonb(v_new);
END;
$$;


ALTER FUNCTION "public"."fn_task_create"("p_library_id" "uuid", "p_title" "text", "p_description" "text", "p_priority" "text", "p_owner" "text", "p_due_date" "date", "p_tags" "text"[]) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."fn_task_create"("p_library_id" "uuid", "p_title" "text", "p_description" "text", "p_priority" "text", "p_owner" "text", "p_due_date" "date", "p_tags" "text"[]) IS 'Crée une task interne pour une biblio. Sécurité par RLS héritée (INVOKER). EA-15.';



CREATE OR REPLACE FUNCTION "public"."fn_task_delete"("p_task_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_invites_deleted integer;
  v_task_exists boolean;
BEGIN
  IF p_task_id IS NULL THEN
    RAISE EXCEPTION 'fn_task_delete: p_task_id obligatoire';
  END IF;

  -- Vérification d'existence (la RLS SELECT filtre déjà à la biblio de l'user)
  SELECT EXISTS(SELECT 1 FROM painel_internal_tasks WHERE id = p_task_id)
  INTO v_task_exists;

  IF NOT v_task_exists THEN
    RAISE EXCEPTION 'fn_task_delete: task id=% introuvable ou accès refusé', p_task_id;
  END IF;

  -- DELETE explicite des invites associées (sécurité : ne pas dépendre
  -- d'une FK ON DELETE CASCADE qui pourrait être absente)
  WITH deleted_invites AS (
    DELETE FROM painel_internal_task_invites
    WHERE task_id = p_task_id
    RETURNING 1
  )
  SELECT COUNT(*) INTO v_invites_deleted FROM deleted_invites;

  -- DELETE de la task (RLS painel_internal_tasks_delete)
  DELETE FROM painel_internal_tasks WHERE id = p_task_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'fn_task_delete: DELETE de task id=% refusé par RLS', p_task_id;
  END IF;

  RETURN jsonb_build_object(
    'deleted_task_id', p_task_id,
    'deleted_invites_count', v_invites_deleted
  );
END;
$$;


ALTER FUNCTION "public"."fn_task_delete"("p_task_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."fn_task_delete"("p_task_id" "uuid") IS 'Supprime une task et ses invites en cascade. Sécurité par RLS héritée (INVOKER). EA-15.';



CREATE OR REPLACE FUNCTION "public"."fn_task_instantiate_template"("p_template_id" "uuid", "p_due_date" "date" DEFAULT NULL::"date") RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_tpl  painel_recurring_task_rules%ROWTYPE;
  v_new  painel_internal_tasks%ROWTYPE;
  v_is_recurrent boolean;
BEGIN
  IF p_template_id IS NULL THEN
    RAISE EXCEPTION 'fn_task_instantiate_template: p_template_id obligatoire';
  END IF;

  SELECT * INTO v_tpl
  FROM painel_recurring_task_rules
  WHERE id = p_template_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'fn_task_instantiate_template: modele % introuvable ou accès refusé', p_template_id;
  END IF;
  IF NOT v_tpl.is_active THEN
    RAISE EXCEPTION 'fn_task_instantiate_template: le modele % est inactif', p_template_id;
  END IF;
  IF v_tpl.template_title IS NULL OR btrim(v_tpl.template_title) = '' THEN
    RAISE EXCEPTION 'fn_task_instantiate_template: le modele % n''a pas de titre', p_template_id;
  END IF;

  v_is_recurrent := (v_tpl.interval_unit IS NOT NULL AND v_tpl.interval_count IS NOT NULL);

  INSERT INTO painel_internal_tasks (
    library_id, title, description, priority, status,
    due_date, tags, recurrence_rule_id, title_i18n, description_i18n
  )
  VALUES (
    v_tpl.library_id,
    btrim(v_tpl.template_title),
    NULLIF(btrim(COALESCE(v_tpl.template_description, '')), ''),
    COALESCE(v_tpl.template_priority, 'media'),
    'pendente',
    p_due_date,
    COALESCE(v_tpl.template_tags, ARRAY[]::text[]),
    CASE WHEN v_is_recurrent THEN v_tpl.id ELSE NULL END,
    v_tpl.title_i18n,
    v_tpl.description_i18n
  )
  RETURNING * INTO v_new;

  RETURN to_jsonb(v_new) || jsonb_build_object(
    'instantiated_from_template', v_tpl.id,
    'template_is_recurrent', v_is_recurrent
  );
END;
$$;


ALTER FUNCTION "public"."fn_task_instantiate_template"("p_template_id" "uuid", "p_due_date" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_task_invite"("p_task_id" "uuid", "p_invite_email" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $_$
DECLARE
  v_email_clean text;
  v_task_exists boolean;
  v_existing_tags text[];
  v_new_tags text[];
BEGIN
  -- Validation
  IF p_task_id IS NULL THEN
    RAISE EXCEPTION 'fn_task_invite: p_task_id obligatoire';
  END IF;

  v_email_clean := btrim(lower(COALESCE(p_invite_email, '')));

  IF v_email_clean = '' THEN
    RAISE EXCEPTION 'fn_task_invite: p_invite_email obligatoire';
  END IF;

  -- Validation email basique (présence d'un @ et d'un .)
  IF v_email_clean !~ '^[^@\s]+@[^@\s]+\.[^@\s]+$' THEN
    RAISE EXCEPTION 'fn_task_invite: email invalide (%)', v_email_clean;
  END IF;

  -- Vérifier que la task existe et est visible à l'user (RLS SELECT)
  SELECT EXISTS(SELECT 1 FROM painel_internal_tasks WHERE id = p_task_id)
  INTO v_task_exists;

  IF NOT v_task_exists THEN
    RAISE EXCEPTION 'fn_task_invite: task id=% introuvable ou accès refusé', p_task_id;
  END IF;

  -- Récupérer les tags actuels
  SELECT tags INTO v_existing_tags
  FROM painel_internal_tasks
  WHERE id = p_task_id;

  -- Si l'email est déjà dans les tags, ne rien faire (idempotent)
  IF v_email_clean = ANY(v_existing_tags) THEN
    RETURN jsonb_build_object(
      'task_id', p_task_id,
      'invite_email', v_email_clean,
      'tags_updated_count', 0,
      'sync_status', 'already_present'
    );
  END IF;

  -- Ajouter l'email aux tags. Le trigger tg_sync_task_invites_from_task
  -- se déclenchera sur l'UPDATE et créera l'invite proprement.
  v_new_tags := v_existing_tags || ARRAY[v_email_clean];

  UPDATE painel_internal_tasks
  SET tags = v_new_tags
  WHERE id = p_task_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'fn_task_invite: UPDATE de task id=% refusé par RLS', p_task_id;
  END IF;

  RETURN jsonb_build_object(
    'task_id', p_task_id,
    'invite_email', v_email_clean,
    'tags_updated_count', 1,
    'sync_status', 'tag_added_trigger_will_sync'
  );
END;
$_$;


ALTER FUNCTION "public"."fn_task_invite"("p_task_id" "uuid", "p_invite_email" "text") OWNER TO "postgres";


