CREATE OR REPLACE FUNCTION "public"."fn_team_cancel_remove_member"("p_user_id" "uuid", "p_library_id" "uuid", "p_role" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_actor_id uuid := auth.uid();
  v_existing record;
  v_audit_id uuid;
  v_actor_is_target boolean;
BEGIN
  -- 1. Authentification
  IF v_actor_id IS NULL THEN
    RAISE EXCEPTION 'unauthorized: not authenticated';
  END IF;

  -- 2. Validation du rôle cible
  IF p_role NOT IN ('librarian', 'coordenador') THEN
    RAISE EXCEPTION 'invalid_argument: p_role must be librarian or coordenador';
  END IF;

  -- 3. Autorisation : coordenador+ OU la cible elle-même
  v_actor_is_target := (v_actor_id = p_user_id);

  IF NOT v_actor_is_target AND NOT public.user_can_manage_library(p_library_id) THEN
    RAISE EXCEPTION 'unauthorized: only coordenador+ or the target themselves can cancel removal';
  END IF;

  -- 4. Récupérer la membership cible
  SELECT * INTO v_existing
  FROM public.user_library_memberships
  WHERE user_id = p_user_id
    AND library_id = p_library_id
    AND role = p_role;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'not_found: no membership for this user/library/role combination';
  END IF;

  -- 5. Précondition : la membership doit être en pending_removal
  IF v_existing.status <> 'pending_removal' THEN
    RAISE EXCEPTION 'precondition_failed: membership is not in pending_removal (current status: %)', v_existing.status;
  END IF;

  -- 6. UPDATE : retour à active, nettoyage des champs pending_removal
  UPDATE public.user_library_memberships
  SET status = 'active',
      pending_removal_until = NULL,
      pending_removal_requested_by = NULL,
      updated_at = now()
  WHERE user_id = p_user_id
    AND library_id = p_library_id
    AND role = p_role;

  -- 7. Audit log
  INSERT INTO public.library_membership_audit
    (library_id, target_user_id, actor_user_id, action, role, status_before, status_after, reason, metadata)
  VALUES
    (p_library_id, p_user_id, v_actor_id, 'removal_cancelled', p_role,
     'pending_removal', 'active', NULL,
     jsonb_build_object(
       'cancelled_by_target', v_actor_is_target,
       'original_pending_until', v_existing.pending_removal_until,
       'original_requested_by', v_existing.pending_removal_requested_by
     ))
  RETURNING id INTO v_audit_id;

  -- 8. Notification mail
  PERFORM public.fn_team_notify_event(
    'team.removal_cancelled',
    jsonb_build_object(
      'library_id', p_library_id,
      'target_user_id', p_user_id,
      'actor_user_id', v_actor_id,
      'role', p_role,
      'cancelled_by_target', v_actor_is_target,
      'audit_id', v_audit_id
    )
  );

  RETURN jsonb_build_object(
    'ok', true,
    'action', 'removal_cancelled',
    'role', p_role,
    'cancelled_by_target', v_actor_is_target,
    'audit_id', v_audit_id
  );
END;
$$;


ALTER FUNCTION "public"."fn_team_cancel_remove_member"("p_user_id" "uuid", "p_library_id" "uuid", "p_role" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."fn_team_cancel_remove_member"("p_user_id" "uuid", "p_library_id" "uuid", "p_role" "text") IS 'Annule une demande de retrait en cours (pending_removal → active). Tout coordenador+ peut annuler, ainsi que la cible elle-même (auto-protection collégiale). Cf. spec-gouvernance-roles.md §5.9.';



CREATE OR REPLACE FUNCTION "public"."fn_team_list_memberships"("p_scope" "text", "p_library_id" "uuid" DEFAULT NULL::"uuid") RETURNS SETOF "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'auth', 'pg_temp'
    AS $$
DECLARE
    v_caller            uuid := auth.uid();
    v_caller_is_netadmin boolean;
BEGIN
    IF v_caller IS NULL THEN
        RAISE EXCEPTION 'auth_required'
            USING HINT = 'Sign in before calling this function.';
    END IF;

    IF p_scope NOT IN ('library', 'network') THEN
        RAISE EXCEPTION 'invalid_scope'
            USING HINT = 'p_scope must be ''library'' or ''network''.';
    END IF;

    v_caller_is_netadmin := public.fn_caller_is_network_admin();

    IF p_scope = 'library' THEN
        IF p_library_id IS NULL THEN
            RAISE EXCEPTION 'library_id_required'
                USING HINT = 'Scope library requires a non-null p_library_id.';
        END IF;

        IF NOT (
            v_caller_is_netadmin
            OR public.user_has_library_staff_role(v_caller, p_library_id)
        ) THEN
            RAISE EXCEPTION 'forbidden'
                USING HINT = 'Caller is not staff of this library and not a network administrator.';
        END IF;

        -- F.2 v0.3 : retrait 'administrador' (role local supprime).
        -- Le CASE WHEN 'administrador' est aussi retire (devenu mort code).
        RETURN QUERY
            SELECT jsonb_build_object(
                'id',                          ulm.id,
                'user_id',                     ulm.user_id,
                'library_id',                  ulm.library_id,
                'role',                        ulm.role,
                'status',                      ulm.status,
                'is_primary',                  ulm.is_primary,
                'created_at',                  ulm.created_at,
                'updated_at',                  ulm.updated_at,
                'is_restricted',               ulm.is_restricted,
                'restricted_reason',           ulm.restricted_reason,
                'pending_removal_until',       ulm.pending_removal_until,
                'pending_removal_requested_by', ulm.pending_removal_requested_by,
                'profiles', jsonb_build_object(
                    'email',      p.email,
                    'first_name', p.first_name,
                    'last_name',  p.last_name,
                    'public_id',  p.public_id
                ),
                'libraries', jsonb_build_object(
                    'id',         l.id,
                    'name',       l.name,
                    'short_name', l.short_name,
                    'slug',       l.slug
                )
            )
            FROM public.user_library_memberships ulm
            LEFT JOIN public.profiles p  ON p.id = ulm.user_id
            LEFT JOIN public.libraries l ON l.id = ulm.library_id
            WHERE ulm.library_id = p_library_id
              AND ulm.role IN ('librarian', 'coordenador')
            ORDER BY
                CASE ulm.role
                    WHEN 'coordenador'   THEN 1
                    WHEN 'librarian'     THEN 2
                    ELSE 99
                END,
                p.last_name,
                p.first_name,
                ulm.created_at;

        RETURN;
    END IF;

    IF p_scope = 'network' THEN
        IF NOT v_caller_is_netadmin THEN
            RAISE EXCEPTION 'forbidden'
                USING HINT = 'Network scope is reserved to network administrators.';
        END IF;

        RETURN QUERY
            SELECT jsonb_build_object(
                'id',                          ulm.id,
                'user_id',                     ulm.user_id,
                'library_id',                  ulm.library_id,
                'role',                        ulm.role,
                'status',                      ulm.status,
                'is_primary',                  ulm.is_primary,
                'created_at',                  ulm.created_at,
                'updated_at',                  ulm.updated_at,
                'is_restricted',               ulm.is_restricted,
                'restricted_reason',           ulm.restricted_reason,
                'pending_removal_until',       ulm.pending_removal_until,
                'pending_removal_requested_by', ulm.pending_removal_requested_by,
                'profiles', jsonb_build_object(
                    'email',      p.email,
                    'first_name', p.first_name,
                    'last_name',  p.last_name,
                    'public_id',  p.public_id
                ),
                'libraries', jsonb_build_object(
                    'id',         l.id,
                    'name',       l.name,
                    'short_name', l.short_name,
                    'slug',       l.slug
                )
            )
            FROM public.user_library_memberships ulm
            LEFT JOIN public.profiles p  ON p.id = ulm.user_id
            LEFT JOIN public.libraries l ON l.id = ulm.library_id
            WHERE ulm.role IN ('librarian', 'coordenador')
            ORDER BY
                l.short_name NULLS LAST,
                CASE ulm.role
                    WHEN 'coordenador'   THEN 1
                    WHEN 'librarian'     THEN 2
                    ELSE 99
                END,
                p.last_name,
                p.first_name,
                ulm.created_at;

        RETURN;
    END IF;
END;
$$;


ALTER FUNCTION "public"."fn_team_list_memberships"("p_scope" "text", "p_library_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."fn_team_list_memberships"("p_scope" "text", "p_library_id" "uuid") IS 'D.8 — Refactorisée pour utiliser fn_caller_is_network_admin (doctrine v0.3) au lieu de fn_caller_is_administrador (deprecated).';



CREATE OR REPLACE FUNCTION "public"."fn_team_notify_event"("p_event" "text", "p_payload" "jsonb") RETURNS bigint
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_outbox_id bigint;
BEGIN
  -- Validation minimale du nom d'event (le CHECK constraint sur la table
  -- en fera autant, mais autant remonter une erreur claire ici).
  IF p_event IS NULL OR p_event NOT LIKE 'team.%' THEN
    RAISE WARNING 'fn_team_notify_event: event name invalid (must start with "team."): %', p_event;
    RETURN NULL;
  END IF;

  -- Insertion dans la outbox.
  -- Le trigger trg_team_outbox_dispatch (créé en section 3) déclenchera le POST.
  INSERT INTO public.team_notification_outbox (event, payload)
  VALUES (p_event, COALESCE(p_payload, '{}'::jsonb))
  RETURNING id INTO v_outbox_id;

  RETURN v_outbox_id;

EXCEPTION
  WHEN OTHERS THEN
    -- Une erreur d'enregistrement notification ne doit JAMAIS faire échouer
    -- la RPC métier qui appelle ce helper.
    RAISE WARNING 'fn_team_notify_event échec INSERT outbox pour event=% : %', p_event, SQLERRM;
    RETURN NULL;
END;
$$;


ALTER FUNCTION "public"."fn_team_notify_event"("p_event" "text", "p_payload" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."fn_team_notify_event"("p_event" "text", "p_payload" "jsonb") IS 'Helper interne : enregistre un event team.* dans team_notification_outbox. Le trigger trg_team_outbox_dispatch déclenche ensuite un pg_net.http_post vers notify-event Edge Function. Cf. spec-gouvernance-roles.md §11.4 (Option B).';



CREATE OR REPLACE FUNCTION "public"."fn_team_outbox_dispatch_trigger"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_url text;
  v_secret text;
  v_request_id bigint;
  v_outbox_payload jsonb;
BEGIN
  v_url := 'https://uflwmikiyjfnikiphtcp.supabase.co/functions/v1/notify-event';

  -- Lecture du secret depuis vault avec le bon nom (majuscules)
  -- Aligné sur fn_dispatch_notify_event qui marche en prod depuis avril 2026
  SELECT decrypted_secret INTO v_secret
  FROM vault.decrypted_secrets
  WHERE name = 'WEBHOOK_SECRET_NOTIFY_EVENT';

  IF v_secret IS NULL OR v_secret = '' THEN
    UPDATE public.team_notification_outbox
    SET status = 'failed',
        last_error = 'WEBHOOK_SECRET_NOTIFY_EVENT vide ou introuvable dans vault',
        attempts = attempts + 1
    WHERE id = NEW.id;
    RETURN NEW;
  END IF;

  v_outbox_payload := jsonb_build_object(
    'event', NEW.event,
    'record_id', NEW.id
  );

  BEGIN
    SELECT net.http_post(
      url := v_url,
      body := v_outbox_payload,
      headers := jsonb_build_object(
        'content-type', 'application/json',
        'x-webhook-secret', v_secret
      )
    ) INTO v_request_id;

    UPDATE public.team_notification_outbox
    SET pg_net_request_id = v_request_id,
        attempts = attempts + 1
    WHERE id = NEW.id;

  EXCEPTION
    WHEN OTHERS THEN
      UPDATE public.team_notification_outbox
      SET status = 'failed',
          last_error = SQLERRM,
          attempts = attempts + 1
      WHERE id = NEW.id;
  END;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."fn_team_outbox_dispatch_trigger"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."fn_team_outbox_dispatch_trigger"() IS 'Fonction de trigger : déclenchée AFTER INSERT sur team_notification_outbox. POST vers notify-event Edge Function avec event + record_id (id outbox). Le handler team.ts (côté EF) lit la ligne en base pour récupérer le payload complet.';



