CREATE OR REPLACE FUNCTION "public"."fn_unarchive_library_circulation"("p_library_id" "uuid", "p_proposal_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_emp_count int := 0;
  v_res_count int := 0;
  v_con_count int := 0;
  v_ill_count int := 0;
BEGIN
  IF NOT EXISTS (SELECT 1 FROM public.libraries WHERE id = p_library_id) THEN
    RETURN jsonb_build_object(
      'ok', false,
      'reason', 'library_not_found',
      'library_id', p_library_id
    );
  END IF;

  -- Restauration emprestimos_v2
  WITH unarchived AS (
    UPDATE public.emprestimos_v2
       SET archived_at = NULL,
           archive_reason = NULL
     WHERE library_id = p_library_id
       AND archived_at IS NOT NULL
       AND archive_reason = 'profile_transition'
     RETURNING 1
  )
  SELECT count(*) INTO v_emp_count FROM unarchived;

  -- Restauration reservas_v2
  WITH unarchived AS (
    UPDATE public.reservas_v2
       SET archived_at = NULL,
           archive_reason = NULL
     WHERE library_id = p_library_id
       AND archived_at IS NOT NULL
       AND archive_reason = 'profile_transition'
     RETURNING 1
  )
  SELECT count(*) INTO v_res_count FROM unarchived;

  -- Restauration consultas_locais_v2
  WITH unarchived AS (
    UPDATE public.consultas_locais_v2
       SET archived_at = NULL,
           archive_reason = NULL
     WHERE library_id = p_library_id
       AND archived_at IS NOT NULL
       AND archive_reason = 'profile_transition'
     RETURNING 1
  )
  SELECT count(*) INTO v_con_count FROM unarchived;

  -- Restauration interlibrary_loans_v2 (lender OU borrower)
  WITH unarchived AS (
    UPDATE public.interlibrary_loans_v2
       SET archived_at = NULL,
           archive_reason = NULL
     WHERE (lender_library_id = p_library_id OR borrower_library_id = p_library_id)
       AND archived_at IS NOT NULL
       AND archive_reason = 'profile_transition'
     RETURNING 1
  )
  SELECT count(*) INTO v_ill_count FROM unarchived;

  RETURN jsonb_build_object(
    'ok', true,
    'library_id', p_library_id,
    'proposal_id', p_proposal_id,
    'counts', jsonb_build_object(
      'emprestimos', v_emp_count,
      'reservas', v_res_count,
      'consultas', v_con_count,
      'interlibrary_loans', v_ill_count,
      'total', v_emp_count + v_res_count + v_con_count + v_ill_count
    )
  );
END;
$$;


ALTER FUNCTION "public"."fn_unarchive_library_circulation"("p_library_id" "uuid", "p_proposal_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_unarchive_notification"("p_notification_id" bigint) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_user_id uuid := auth.uid();
  v_rows int;
BEGIN
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'auth required' USING HINT = 'fn_unarchive_notification: no authenticated user in context';
  END IF;

  UPDATE public.user_notifications
     SET archived_at = NULL
   WHERE id = p_notification_id
     AND user_id = v_user_id
     AND archived_at IS NOT NULL;

  GET DIAGNOSTICS v_rows = ROW_COUNT;
  IF v_rows = 0 THEN
    RAISE EXCEPTION 'notification % not found, not owned, or not archived for user %',
      p_notification_id, v_user_id
      USING HINT = 'fn_unarchive_notification: vérifier que la notification appartient à auth.uid() et est bien archivée';
  END IF;
END;
$$;


ALTER FUNCTION "public"."fn_unarchive_notification"("p_notification_id" bigint) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."fn_unarchive_notification"("p_notification_id" bigint) IS 'Chantier #CL.6 (31/05/2026). Restaure une notification archivée appartenant à auth.uid(). SECURITY DEFINER + REVOKE/GRANT doctrine v2. Échoue si la notification n''existe pas, n''appartient pas à l''utilisateur courant, ou n''est pas archivée.';



CREATE OR REPLACE FUNCTION "public"."fn_unarchive_transaction"("p_table_name" "text", "p_record_id" "text", "p_motivation" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_caller_id uuid := auth.uid();
  v_eligibility jsonb;
  v_library_id uuid;
  v_archived_at timestamptz;
  v_archive_reason text;
  v_record_bigint bigint;
  v_record_uuid uuid;
BEGIN
  IF v_caller_id IS NULL THEN
    RAISE EXCEPTION 'UNARCHIVE_AUTH_REQUIRED : authentification requise'
      USING ERRCODE = 'insufficient_privilege', HINT = 'error.unarchive.auth_required';
  END IF;

  IF p_motivation IS NULL OR length(trim(p_motivation)) < 5 THEN
    RAISE EXCEPTION 'UNARCHIVE_MOTIVATION_TOO_SHORT : la motivation doit faire au moins 5 caracteres'
      USING ERRCODE = 'check_violation', HINT = 'error.unarchive.motivation_too_short';
  END IF;

  v_eligibility := public.fn_check_unarchive_eligibility(p_table_name, p_record_id);

  IF (v_eligibility->>'ok')::boolean IS NOT TRUE THEN
    CASE v_eligibility->>'reason'
      WHEN 'invalid_table_name' THEN
        RAISE EXCEPTION 'UNARCHIVE_INVALID_TABLE : table % non eligible', p_table_name
          USING ERRCODE = 'check_violation', HINT = 'error.unarchive.invalid_table';
      WHEN 'invalid_record_id_format' THEN
        RAISE EXCEPTION 'UNARCHIVE_INVALID_RECORD_ID : format record_id incorrect pour la table %', p_table_name
          USING ERRCODE = 'invalid_text_representation', HINT = 'error.unarchive.invalid_record_id';
      WHEN 'record_not_found' THEN
        RAISE EXCEPTION 'UNARCHIVE_RECORD_NOT_FOUND : enregistrement % introuvable', p_record_id
          USING ERRCODE = 'no_data_found', HINT = 'error.unarchive.record_not_found';
      WHEN 'not_archived' THEN
        RAISE EXCEPTION 'UNARCHIVE_NOT_ARCHIVED : enregistrement deja actif (non archive)'
          USING ERRCODE = 'check_violation', HINT = 'error.unarchive.not_archived';
      WHEN 'library_still_off' THEN
        RAISE EXCEPTION 'UNARCHIVE_LIBRARY_STILL_OFF : la biblio doit etre revenue en circulation pour reactiver'
          USING ERRCODE = 'check_violation', HINT = 'error.unarchive.library_still_off';
      WHEN 'too_old' THEN
        RAISE EXCEPTION 'UNARCHIVE_TOO_OLD : echeance theorique depassee de % jours (max % jours)',
          v_eligibility->>'age_days', v_eligibility->>'grace_days'
          USING ERRCODE = 'check_violation', HINT = 'error.unarchive.too_old';
      ELSE
        RAISE EXCEPTION 'UNARCHIVE_INELIGIBLE : %', v_eligibility->>'reason'
          USING ERRCODE = 'check_violation', HINT = 'error.unarchive.ineligible';
    END CASE;
  END IF;

  v_library_id     := (v_eligibility->>'library_id')::uuid;
  v_archived_at    := (v_eligibility->>'archived_at')::timestamptz;
  v_archive_reason := v_eligibility->>'archive_reason';

  IF NOT EXISTS (
    SELECT 1 FROM public.user_library_memberships
     WHERE library_id = v_library_id AND user_id = v_caller_id
       AND status = 'active' AND role IN ('librarian', 'coordenador')
  ) THEN
    RAISE EXCEPTION 'UNARCHIVE_NOT_STAFF : caller n''est pas staff actif de la biblio'
      USING ERRCODE = 'insufficient_privilege', HINT = 'error.unarchive.not_staff';
  END IF;

  -- Cast pour l'UPDATE
  IF p_table_name IN ('emprestimos_v2','reservas_v2','consultas_locais_v2','interlibrary_loans_v2') THEN
    v_record_bigint := p_record_id::bigint;
  ELSE
    v_record_uuid := p_record_id::uuid;
  END IF;

  -- Doctrine #141.2.E : audit log AVANT UPDATE etat
  INSERT INTO public.library_unarchive_log (
    library_id, table_name, record_id, unarchived_by, motivation,
    prev_archived_at, prev_archive_reason
  )
  VALUES (
    v_library_id, p_table_name, p_record_id, v_caller_id, trim(p_motivation),
    v_archived_at, v_archive_reason
  );

  IF p_table_name = 'emprestimos_v2' THEN
    UPDATE public.emprestimos_v2 SET archived_at = NULL, archive_reason = NULL WHERE id = v_record_bigint;
  ELSIF p_table_name = 'reservas_v2' THEN
    UPDATE public.reservas_v2 SET archived_at = NULL, archive_reason = NULL WHERE id = v_record_bigint;
  ELSIF p_table_name = 'consultas_locais_v2' THEN
    UPDATE public.consultas_locais_v2 SET archived_at = NULL, archive_reason = NULL WHERE id = v_record_bigint;
  ELSIF p_table_name = 'interlibrary_loans_v2' THEN
    UPDATE public.interlibrary_loans_v2 SET archived_at = NULL, archive_reason = NULL WHERE id = v_record_bigint;
  ELSIF p_table_name = 'membership_payments' THEN
    UPDATE public.membership_payments SET archived_at = NULL, archive_reason = NULL WHERE id = v_record_uuid;
  END IF;

  RETURN jsonb_build_object(
    'ok', true,
    'library_id', v_library_id,
    'table_name', p_table_name,
    'record_id', p_record_id,
    'unarchived_at', now(),
    'prev_archive_reason', v_archive_reason
  );
END;
$$;


ALTER FUNCTION "public"."fn_unarchive_transaction"("p_table_name" "text", "p_record_id" "text", "p_motivation" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_unhide_history_item"("p_domain" "text", "p_record_id" bigint) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_uid   uuid := auth.uid();
  v_count integer;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'not_authenticated' USING HINT = 'history.error.not_authenticated';
  END IF;

  IF p_domain = 'loans' THEN
    UPDATE public.emprestimos_v2
       SET is_hidden_by_user = false, hidden_at = NULL
     WHERE id = p_record_id AND user_id = v_uid;
    GET DIAGNOSTICS v_count = ROW_COUNT;

  ELSIF p_domain = 'reservations' THEN
    UPDATE public.reserva_linhas_v2 rl
       SET is_hidden_by_user = false, hidden_at = NULL
      FROM public.reservas_v2 r
     WHERE rl.id = p_record_id AND rl.reserva_id = r.id AND r.user_id = v_uid;
    GET DIAGNOSTICS v_count = ROW_COUNT;

  ELSIF p_domain = 'consultations' THEN
    UPDATE public.consulta_linhas_v2 cl
       SET is_hidden_by_user = false, hidden_at = NULL
      FROM public.consultas_locais_v2 c
     WHERE cl.id = p_record_id AND cl.consulta_id = c.id AND c.user_id = v_uid;
    GET DIAGNOSTICS v_count = ROW_COUNT;

  ELSE
    RAISE EXCEPTION 'invalid_domain' USING HINT = 'history.error.invalid_domain';
  END IF;

  IF v_count = 0 THEN
    RAISE EXCEPTION 'item_not_found' USING HINT = 'history.error.not_found';
  END IF;
END;
$$;


ALTER FUNCTION "public"."fn_unhide_history_item"("p_domain" "text", "p_record_id" bigint) OWNER TO "postgres";


