    "holding_id" bigint NOT NULL,
    "item_id" bigint NOT NULL,
    "bib_ref" "text" NOT NULL,
    "rotulo_cache" "text",
    "titulo_cache" "text",
    "autor_cache" "text",
    "editora_cache" "text",
    "ano_cache" "text",
    "item_status" "text" DEFAULT 'reservado_para_saida'::"text" NOT NULL,
