    CONSTRAINT "interlibrary_loan_items_v2_status_chk" CHECK (("item_status" = ANY (ARRAY['reservado_para_saida'::"text", 'emprestado'::"text", 'devolvido'::"text", 'cancelado'::"text", 'perdido'::"text", 'danificado'::"text"])))
);


