CREATE OR REPLACE FUNCTION "public"."fn_v2_add_emprestimo_interbibliotecas_itens"("p_loan_id" bigint, "p_item_ids" bigint[], "p_due_date" "date" DEFAULT NULL::"date", "p_notes" "text" DEFAULT NULL::"text") RETURNS SETOF "public"."interlibrary_loan_items_v2"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_header public.interlibrary_loans_v2;
  v_item_id bigint;
  v_row record;
  v_inserted public.interlibrary_loan_items_v2;
  v_line_no integer;
  v_item_ids bigint[];
  v_missing bigint[] := '{}'::bigint[];
  v_wrong_library bigint[] := '{}'::bigint[];
  v_unavailable bigint[] := '{}'::bigint[];
begin
  if auth.uid() is null then
    raise exception 'Autenticação obrigatória.';
  end if;

  select *
    into v_header
  from public.interlibrary_loans_v2
  where id = p_loan_id;

  if v_header.id is null then
    raise exception 'Empréstimo interbibliotecas não encontrado: %', p_loan_id;
  end if;

  if not public.user_can_manage_library(v_header.lender_library_id) then
    raise exception 'Somente a biblioteca emprestadora pode reservar itens para saída.';
  end if;

  if v_header.status_global in ('devolvido', 'cancelado') then
    raise exception 'Este empréstimo interbibliotecas já está encerrado.';
  end if;

  select array_agg(s.item_id order by s.ord)
    into v_item_ids
  from (
    select x.item_id, min(x.ord) as ord
    from unnest(coalesce(p_item_ids, '{}'::bigint[])) with ordinality as x(item_id, ord)
    where x.item_id is not null
    group by x.item_id
  ) s;

  if coalesce(array_length(v_item_ids, 1), 0) = 0 then
    raise exception 'Informe ao menos 1 exemplar.';
  end if;

  foreach v_item_id in array v_item_ids
  loop
    select
      e.id as item_id,
      e.library_id,
      e.holding_id,
      e.bib_ref,
      e.tombo,
      e.notes as exemplar_notes,
      h.book_id,
      h.library_id as holding_library_id,
      h.local_bib_ref,
      coalesce(h.loanable, b.loanable, true) as loanable,
      b.titulo,
      b.autor,
      b.editora,
      b.ano
    into v_row
    from public.exemplares e
    left join public.book_holdings h
      on h.id = e.holding_id
    left join public.books b
      on b.id = h.book_id
    where e.id = v_item_id;

    if not found then
      v_missing := array_append(v_missing, v_item_id);
      continue;
    end if;

    if coalesce(v_row.library_id, v_row.holding_library_id) <> v_header.lender_library_id then
      v_wrong_library := array_append(v_wrong_library, v_item_id);
      continue;
    end if;

    if v_row.holding_id is null then
      raise exception 'O exemplar % não está ligado a um holding.', v_item_id;
    end if;

    if coalesce(v_row.loanable, false) is false then
      raise exception 'O exemplar % não está marcado como emprestável.', v_item_id;
    end if;

    if exists (
      select 1
      from public.emprestimo_itens_v2 i
      where i.item_id = v_item_id
        and i.item_status = 'aberto'
    ) then
      v_unavailable := array_append(v_unavailable, v_item_id);
      continue;
    end if;

    if exists (
      select 1
      from public.reserva_linhas_v2 rl
      join public.reservas_v2 r
        on r.id = rl.reserva_id
      where (
          rl.item_id = v_item_id
          or rl.holding_id = v_row.holding_id
        )
        and rl.item_status = 'ativa'
        and r.library_id = v_header.lender_library_id
    ) then
      v_unavailable := array_append(v_unavailable, v_item_id);
      continue;
    end if;

    if exists (
      select 1
      from public.interlibrary_loan_items_v2 ii
      where ii.item_id = v_item_id
        and ii.item_status in ('reservado_para_saida', 'emprestado')
    ) then
      v_unavailable := array_append(v_unavailable, v_item_id);
      continue;
    end if;
  end loop;

  if cardinality(v_missing) > 0 then
    raise exception 'Exemplar(es) não encontrado(s): %', array_to_string(v_missing, ', ');
  end if;

  if cardinality(v_wrong_library) > 0 then
    raise exception 'Exemplar(es) fora da biblioteca emprestadora: %', array_to_string(v_wrong_library, ', ');
  end if;

  if cardinality(v_unavailable) > 0 then
    raise exception 'Exemplar(es) indisponível(is) para este empréstimo interbibliotecas: %', array_to_string(v_unavailable, ', ');
  end if;

  for v_item_id in
    select x.item_id
    from unnest(v_item_ids) as x(item_id)
  loop
    select
      e.id as item_id,
      e.library_id,
      e.holding_id,
      e.bib_ref,
      e.tombo,
      e.notes as exemplar_notes,
      h.book_id,
      h.local_bib_ref,
      b.titulo,
      b.autor,
      b.editora,
      b.ano
    into v_row
    from public.exemplares e
    left join public.book_holdings h
      on h.id = e.holding_id
    left join public.books b
      on b.id = h.book_id
    where e.id = v_item_id;

    select coalesce(max(i.line_no), 0) + 1
      into v_line_no
    from public.interlibrary_loan_items_v2 i
    where i.interlibrary_loan_id = p_loan_id;

    insert into public.interlibrary_loan_items_v2 (
      interlibrary_loan_id,
      line_no,
      book_id,
      holding_id,
      item_id,
      bib_ref,
      rotulo_cache,
      titulo_cache,
      autor_cache,
      editora_cache,
      ano_cache,
      item_status,
      reserved_at,
      due_date,
      notes,
      metadata,
      created_at,
      updated_at
    )
    values (
      p_loan_id,
      v_line_no,
      v_row.book_id,
      v_row.holding_id,
      v_row.item_id,
      coalesce(nullif(trim(v_row.local_bib_ref), ''), v_row.bib_ref),
      v_row.tombo,
      v_row.titulo,
      v_row.autor,
      v_row.editora,
      v_row.ano,
      'reservado_para_saida',
      timezone('utc', now()),
      coalesce(p_due_date, v_header.due_date),
      coalesce(nullif(trim(coalesce(p_notes, '')), ''), v_row.exemplar_notes),
      '{}'::jsonb,
      timezone('utc', now()),
      timezone('utc', now())
    )
    returning * into v_inserted;

    perform public.fn_v2_log_emprestimo_interbibliotecas_event(
      p_loan_id := p_loan_id,
      p_item_id := v_inserted.id,
      p_event_type := 'item_attached',
      p_event_note := 'Exemplar reservado para saída interbibliotecas.',
      p_payload := jsonb_build_object(
        'line_no', v_inserted.line_no,
        'item_id', v_inserted.item_id,
        'holding_id', v_inserted.holding_id,
        'bib_ref', v_inserted.bib_ref,
        'rotulo', v_inserted.rotulo_cache
      )
    );

    return next v_inserted;
  end loop;

  update public.interlibrary_loans_v2 h
     set updated_at = timezone('utc', now()),
         updated_by = auth.uid()
   where h.id = p_loan_id;

  perform public.fn_v2_refresh_emprestimo_interbibliotecas_status_global(p_loan_id);
  perform public.fn_v2_recompute_from_emprestimo_interbibliotecas_linhas(p_loan_id, null);

  return;
end;
$$;


ALTER FUNCTION "public"."fn_v2_add_emprestimo_interbibliotecas_itens"("p_loan_id" bigint, "p_item_ids" bigint[], "p_due_date" "date", "p_notes" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_v2_book_session_availability_for_current_user"("p_book_ids" bigint[]) RETURNS TABLE("book_id" bigint, "bib_ref" "text", "session_library_id" "uuid", "session_library_slug" "text", "session_library_name" "text", "session_holding_id" bigint, "session_local_bib_ref" "text", "session_loanable" boolean, "session_status_hint" "text", "session_exemplares_total" integer, "session_available_count" integer, "session_next_available_on" "date", "session_due_at" "date", "session_pickup_scheduled_for" timestamp with time zone, "session_has_holding" boolean)
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO 'public', 'api'
    AS $$
  with access_ctx as (
    select *
    from api.my_access
    limit 1
  ),
  input_books as (
    select distinct x.book_id
    from unnest(coalesce(p_book_ids, '{}'::bigint[])) as x(book_id)
    where x.book_id is not null
  ),
  base_books as (
    select
      ib.book_id,
      b.bib_ref
    from input_books ib
    left join public.books b
      on b.id = ib.book_id
  ),
  session_holdings as (
    select
      bb.book_id,
      bb.bib_ref,
      ac.default_library_id as session_library_id,
      ls.slug as session_library_slug,
      ls.name as session_library_name,
      h.id as session_holding_id,
      coalesce(nullif(trim(h.local_bib_ref), ''), bb.bib_ref) as session_local_bib_ref,
      coalesce(h.loanable, b.loanable, true) as session_loanable,
      coalesce(h.exemplares_total, 0) as session_exemplares_total
    from base_books bb
    cross join access_ctx ac
    left join public.books b
      on b.id = bb.book_id
    left join public.libraries ls
      on ls.id = ac.default_library_id
    left join public.book_holdings h
      on h.book_id = bb.book_id
     and h.library_id = ac.default_library_id
  ),
  session_availability as (
    select
      sh.book_id,
      sh.session_holding_id,
      gfa.exemplares_total,
      gfa.available_count,
      gfa.next_due_at,
      gfa.next_pickup_scheduled_for,
      gfa.projected_next_available_on
    from session_holdings sh
    left join lateral api.get_future_availability(
      p_library_id := sh.session_library_id,
      p_book_id := sh.book_id,
      p_holding_id := sh.session_holding_id
    ) gfa
      on sh.session_library_id is not null
     and sh.session_holding_id is not null
  )
  select
    sh.book_id,
    sh.bib_ref,
    sh.session_library_id,
    sh.session_library_slug,
    sh.session_library_name,
    sh.session_holding_id,
    sh.session_local_bib_ref,
    sh.session_loanable,
    case
      when sh.session_library_id is null then 'sem_biblioteca_de_sessao'
      when sh.session_holding_id is null then 'indisponivel_para_voce'
      when coalesce(sh.session_loanable, true) is false then 'consultavel_no_local'
      when coalesce(sa.available_count, greatest(coalesce(sh.session_exemplares_total, 0), 0)) > 0 then 'no_acervo_da_sua_biblioteca'
      else 'indisponivel_no_momento'
    end as session_status_hint,
    coalesce(sa.exemplares_total, sh.session_exemplares_total, 0)::int as session_exemplares_total,
    coalesce(sa.available_count, greatest(coalesce(sh.session_exemplares_total, 0), 0))::int as session_available_count,
    case
      when sh.session_holding_id is null then null::date
      when coalesce(sh.session_loanable, true) is false then null::date
      when coalesce(sa.available_count, greatest(coalesce(sh.session_exemplares_total, 0), 0)) > 0 then null::date
      else sa.projected_next_available_on
    end as session_next_available_on,
    sa.next_due_at as session_due_at,
    sa.next_pickup_scheduled_for as session_pickup_scheduled_for,
    (sh.session_holding_id is not null) as session_has_holding
  from session_holdings sh
  left join session_availability sa
    on sa.book_id = sh.book_id
   and sa.session_holding_id is not distinct from sh.session_holding_id;
$$;


ALTER FUNCTION "public"."fn_v2_book_session_availability_for_current_user"("p_book_ids" bigint[]) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."fn_v2_book_session_availability_for_current_user"("p_book_ids" bigint[]) IS 'Surface session-aware harmonisée avec api.get_future_availability : plus de projection legacy +21 côté conta/session.';



CREATE OR REPLACE FUNCTION "public"."fn_v2_book_session_context_for_current_user"("p_book_id" bigint DEFAULT NULL::bigint, "p_bib_ref" "text" DEFAULT NULL::"text") RETURNS TABLE("book_id" bigint, "bib_ref" "text", "session_library_id" "uuid", "session_library_slug" "text", "session_library_name" "text", "session_holding_id" bigint, "session_local_bib_ref" "text", "session_loanable" boolean, "session_status_hint" "text", "session_exemplares_total" integer, "session_available_count" integer, "session_next_available_on" "date", "session_due_at" "date", "session_pickup_scheduled_for" timestamp with time zone, "session_has_holding" boolean)
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO 'public', 'api'
    AS $$
  with resolved as (
    select coalesce(
      p_book_id,
      (
        select v.book_id
        from public.v_book_detail_public_v2 v
        where trim(coalesce(v.bib_ref, '')) = trim(coalesce(p_bib_ref, ''))
        limit 1
      )
    ) as resolved_book_id
  )
  select f.*
  from resolved r
  join public.fn_v2_book_session_availability_for_current_user(array[r.resolved_book_id]) f
    on f.book_id = r.resolved_book_id
  where r.resolved_book_id is not null
  limit 1;
$$;


