CREATE OR REPLACE FUNCTION "public"."fn_v2_cancel_consulta_linhas_as_leitor"("p_consulta_id" bigint, "p_line_nos" integer[], "p_notes" "text" DEFAULT NULL::"text") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_uid uuid := auth.uid();
  v_updated int := 0;
begin
  if v_uid is null then
    raise exception 'Autenticação obrigatória.';
  end if;

  if not exists (
    select 1
    from public.consultas_locais_v2 c
    where c.id = p_consulta_id
      and c.user_id = v_uid
  ) then
    raise exception 'Você não pode alterar este pedido de consulta local.';
  end if;

  update public.consulta_linhas_v2 cl
     set item_status = 'cancelada_leitor',
         cancelled_at = coalesce(cl.cancelled_at, timezone('utc', now())),
         notes = case
           when p_notes is null or btrim(p_notes) = '' then cl.notes
           when cl.notes is null or btrim(cl.notes) = '' then p_notes
           else cl.notes || E'
' || p_notes
         end,
         updated_at = timezone('utc', now())
   where cl.consulta_id = p_consulta_id
     and cl.line_no = any(p_line_nos)
     and cl.item_status = 'ativa';

  get diagnostics v_updated = row_count;

  insert into public.consulta_item_workflow_v2 (
    consulta_id,
    line_no,
    workflow_stage,
    workflow_note,
    updated_at,
    updated_by
  )
  select
    cl.consulta_id,
    cl.line_no,
    'cancelada_leitor',
    coalesce(nullif(trim(p_notes), ''), 'Cancelamento solicitado pela conta do(a/e) leitor(a/e).'),
    timezone('utc', now()),
    v_uid
  from public.consulta_linhas_v2 cl
  where cl.consulta_id = p_consulta_id
    and cl.line_no = any(p_line_nos)
  on conflict (consulta_id, line_no)
  do update
     set workflow_stage = excluded.workflow_stage,
         workflow_note = excluded.workflow_note,
         updated_at = excluded.updated_at,
         updated_by = excluded.updated_by;

  perform public.fn_v2_refresh_consulta_status_global(p_consulta_id);

  return v_updated;
end;
$$;


ALTER FUNCTION "public"."fn_v2_cancel_consulta_linhas_as_leitor"("p_consulta_id" bigint, "p_line_nos" integer[], "p_notes" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_v2_cancel_emprestimo_interbibliotecas"("p_loan_id" bigint, "p_note" "text" DEFAULT NULL::"text") RETURNS "public"."interlibrary_loans_v2"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_header public.interlibrary_loans_v2;
  v_row public.interlibrary_loans_v2;
begin
  if auth.uid() is null then
    raise exception 'Autenticação obrigatória.';
  end if;

  select *
    into v_header
  from public.interlibrary_loans_v2
  where id = p_loan_id;

  if v_header.id is null then
    raise exception 'Empréstimo interbibliotecas não encontrado: %', p_loan_id;
  end if;

  if not public.user_can_manage_library(v_header.lender_library_id)
     and not public.user_can_manage_library(v_header.borrower_library_id) then
    raise exception 'Sem permissão para cancelar este empréstimo.';
  end if;

  if exists (
    select 1
    from public.interlibrary_loan_items_v2 i
    where i.interlibrary_loan_id = p_loan_id
      and i.item_status = 'emprestado'
  ) then
    raise exception 'Não é possível cancelar um empréstimo já despachado.';
  end if;

  update public.interlibrary_loan_items_v2 i
     set item_status = 'cancelado',
         notes = coalesce(nullif(trim(coalesce(p_note, '')), ''), i.notes),
         updated_at = timezone('utc', now())
   where i.interlibrary_loan_id = p_loan_id
     and i.item_status = 'reservado_para_saida';

  update public.interlibrary_loans_v2 h
     set status_global = 'cancelado',
         notes = coalesce(nullif(trim(coalesce(p_note, '')), ''), h.notes),
         updated_at = timezone('utc', now()),
         updated_by = auth.uid()
   where h.id = p_loan_id
  returning * into v_row;

  perform public.fn_v2_log_emprestimo_interbibliotecas_event(
    p_loan_id := p_loan_id,
    p_item_id := null,
    p_event_type := 'cancelled',
    p_event_note := 'Empréstimo interbibliotecas cancelado.',
    p_payload := jsonb_build_object(
      'status_global', v_row.status_global
    )
  );

  perform public.fn_v2_refresh_emprestimo_interbibliotecas_status_global(p_loan_id);
  perform public.fn_v2_recompute_from_emprestimo_interbibliotecas_linhas(p_loan_id, null);

  select *
    into v_row
  from public.interlibrary_loans_v2
  where id = p_loan_id;

  return v_row;
end;
$$;


ALTER FUNCTION "public"."fn_v2_cancel_emprestimo_interbibliotecas"("p_loan_id" bigint, "p_note" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_v2_cancel_reserva_linhas_as_biblioteca"("p_reserva_id" bigint, "p_line_nos" integer[], "p_notes" "text" DEFAULT NULL::"text") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'api'
    AS $$
declare
  v_uid uuid := auth.uid();
  v_library_id uuid;
  v_updated int := 0;
begin
  if v_uid is null then
    raise exception 'Autenticação obrigatória.';
  end if;

  select r.library_id
    into v_library_id
  from public.reservas_v2 r
  where r.id = p_reserva_id;

  if v_library_id is null then
    raise exception 'Reserva não encontrada.';
  end if;

  if not exists (
    select 1
    from api.my_access a
    where a.user_id = v_uid
      and a.can_access_painel = true
      and a.library_id = v_library_id
  ) then
    raise exception 'Você não pode gerir esta reserva.';
  end if;

  update public.reserva_linhas_v2 rl
     set item_status = 'cancelada_biblioteca',
         cancelled_at = coalesce(rl.cancelled_at, timezone('utc', now())),
         notes = case
           when p_notes is null or btrim(p_notes) = '' then rl.notes
           when rl.notes is null or btrim(rl.notes) = '' then p_notes
           else rl.notes || E'\n' || p_notes
         end,
         updated_at = timezone('utc', now())
   where rl.reserva_id = p_reserva_id
     and rl.line_no = any(p_line_nos)
     and rl.item_status = 'ativa';

  get diagnostics v_updated = row_count;

  insert into public.reserva_item_workflow_v2 (
    reserva_id,
    line_no,
    workflow_stage,
    workflow_note,
    updated_at,
    updated_by
  )
  select
    rl.reserva_id,
    rl.line_no,
    'cancelada_biblioteca',
    coalesce(nullif(trim(p_notes), ''), 'Cancelamento efetuado pela biblioteca.'),
    timezone('utc', now()),
    v_uid
  from public.reserva_linhas_v2 rl
  where rl.reserva_id = p_reserva_id
    and rl.line_no = any(p_line_nos)
  on conflict (reserva_id, line_no)
  do update
     set workflow_stage = excluded.workflow_stage,
         workflow_note = excluded.workflow_note,
         updated_at = excluded.updated_at,
         updated_by = excluded.updated_by;

  perform public.fn_v2_refresh_reserva_status_global(p_reserva_id);
  perform public.fn_v2_recompute_from_reserva_lines(p_reserva_id, p_line_nos);

  return v_updated;
end;
$$;


