CREATE OR REPLACE FUNCTION "public"."fn_v2_extend_emprestimo_item_once"("p_emprestimo_id" bigint, "p_line_no" integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'api'
    AS $$
