CREATE OR REPLACE FUNCTION "public"."fn_v2_log_emprestimo_interbibliotecas_event"("p_loan_id" bigint, "p_item_id" bigint DEFAULT NULL::bigint, "p_event_type" "text" DEFAULT NULL::"text", "p_event_note" "text" DEFAULT NULL::"text", "p_payload" "jsonb" DEFAULT '{}'::"jsonb") RETURNS bigint
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_event_id bigint;
  v_actor_library_id uuid;
begin
  if p_loan_id is null then
    raise exception 'loan_id ausente para log de evento.';
  end if;

  if nullif(trim(coalesce(p_event_type, '')), '') is null then
    raise exception 'event_type ausente para log de evento.';
  end if;

  select ulm.library_id
    into v_actor_library_id
  from public.user_library_memberships ulm
  where ulm.user_id = auth.uid()
    and ulm.status = 'active'
  order by case lower(coalesce(ulm.role, ''))
    when 'owner' then 1
    when 'admin' then 2
    when 'librarian' then 3
    else 9
  end,
  ulm.created_at asc
  limit 1;

  insert into public.interlibrary_loan_events (
    interlibrary_loan_id,
    interlibrary_loan_item_id,
    event_type,
    actor_user_id,
    actor_library_id,
    event_note,
    payload,
    created_at
  )
  values (
    p_loan_id,
    p_item_id,
    trim(p_event_type),
    auth.uid(),
    v_actor_library_id,
    nullif(trim(coalesce(p_event_note, '')), ''),
    coalesce(p_payload, '{}'::jsonb),
    timezone('utc', now())
  )
  returning id into v_event_id;

  return v_event_id;
end;
$$;


ALTER FUNCTION "public"."fn_v2_log_emprestimo_interbibliotecas_event"("p_loan_id" bigint, "p_item_id" bigint, "p_event_type" "text", "p_event_note" "text", "p_payload" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_v2_mark_emprestimo_return_missed"("p_emprestimo_id" bigint, "p_line_nos" integer[], "p_actor_role" "text") RETURNS TABLE("ok" boolean, "message" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_actor public.my_access%rowtype;
  v_header public.emprestimos_v2%rowtype;
begin
  if auth.uid() is null then
    raise exception 'Autenticação obrigatória.';
  end if;

  select * into v_actor from public.my_access limit 1;

  select * into v_header
  from public.emprestimos_v2
  where id = p_emprestimo_id;

  if not found then
    return query select false, 'Empréstimo não encontrado.';
    return;
  end if;

  if p_actor_role <> 'biblioteca' then
    raise exception 'Somente a biblioteca pode marcar devolução como não realizada.';
  end if;

  if not (
    coalesce(v_actor.can_access_painel, false) is true
    and v_actor.library_id = v_header.library_id
  ) then
    raise exception 'Acesso bibliotecário obrigatório.';
  end if;

  update public.emprestimo_itens_v2
     set return_scheduled_for = null,
         return_schedule_status = 'devolucao_nao_realizada',
         return_missed_at = now(),
         updated_at = now()
   where emprestimo_id = p_emprestimo_id
     and line_no = any(p_line_nos)
     and item_status = 'aberto';

  return query
  select true, 'Devolução marcada como não realizada.';
end;
$$;


ALTER FUNCTION "public"."fn_v2_mark_emprestimo_return_missed"("p_emprestimo_id" bigint, "p_line_nos" integer[], "p_actor_role" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_v2_recompute_from_emprestimo_interbibliotecas_linhas"("p_loan_id" bigint, "p_line_nos" integer[] DEFAULT NULL::integer[]) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_holding_ids bigint[] := '{}'::bigint[];
  v_book_ids bigint[] := '{}'::bigint[];
begin
  select
    coalesce(
      array_agg(distinct i.holding_id) filter (where i.holding_id is not null),
      '{}'::bigint[]
    ),
    coalesce(
      array_agg(distinct i.book_id) filter (where i.book_id is not null),
      '{}'::bigint[]
    )
  into v_holding_ids, v_book_ids
  from public.interlibrary_loan_items_v2 i
  where i.interlibrary_loan_id = p_loan_id
    and (
      coalesce(cardinality(p_line_nos), 0) = 0
      or i.line_no = any(p_line_nos)
    );

  if coalesce(cardinality(v_holding_ids), 0) = 0
     and coalesce(cardinality(v_book_ids), 0) = 0 then
    return;
  end if;

  perform *
  from public.fn_v2_recompute_holdings_availability(
    case
      when coalesce(cardinality(v_holding_ids), 0) = 0 then null
      else v_holding_ids
    end,
    case
      when coalesce(cardinality(v_book_ids), 0) = 0 then null
      else v_book_ids
    end
  );

  return;
end;
$$;


