CREATE OR REPLACE FUNCTION "public"."fn_v2_recompute_holdings_availability"("p_holding_ids" bigint[] DEFAULT NULL::bigint[], "p_book_ids" bigint[] DEFAULT NULL::bigint[]) RETURNS TABLE("holdings_recomputed" integer, "holdings_updated" integer, "books_recomputed" integer, "books_updated" integer)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_holdings_recomputed integer := 0;
  v_holdings_updated integer := 0;
  v_books_recomputed integer := 0;
  v_books_updated integer := 0;
begin
  with target_holdings as (
    select h.id, h.book_id
    from public.book_holdings h
    where (
      coalesce(cardinality(p_holding_ids), 0) = 0
      or h.id = any(p_holding_ids)
    )
      and (
        coalesce(cardinality(p_book_ids), 0) = 0
        or h.book_id = any(p_book_ids)
      )
  )
  select count(*)::int
    into v_holdings_recomputed
  from target_holdings;

  with target_books as (
    select distinct h.book_id
    from public.book_holdings h
    where (
      coalesce(cardinality(p_holding_ids), 0) = 0
      or h.id = any(p_holding_ids)
    )
      and (
        coalesce(cardinality(p_book_ids), 0) = 0
        or h.book_id = any(p_book_ids)
      )

    union

    select distinct x.book_id
    from unnest(coalesce(p_book_ids, '{}'::bigint[])) as x(book_id)
  )
  select count(*)::int
    into v_books_recomputed
  from target_books;

  with target_holdings as (
    select h.id, h.book_id
    from public.book_holdings h
    where (
      coalesce(cardinality(p_holding_ids), 0) = 0
      or h.id = any(p_holding_ids)
    )
      and (
        coalesce(cardinality(p_book_ids), 0) = 0
        or h.book_id = any(p_book_ids)
      )
  ),
  exemplar_counts as (
    select
      e.holding_id,
      count(*)::int as exemplares_total_calc
    from public.exemplares e
    where e.holding_id is not null
      and e.visibility = 'public'   -- P1.4a
    group by e.holding_id
  ),
  open_loans as (
    select
      e.holding_id,
      count(*)::int as emprestimos_abertos_calc
    from public.emprestimo_itens_v2 i
    join public.exemplares e
      on e.id = i.item_id
    where i.item_status = 'aberto'
      and e.holding_id is not null
      and e.visibility = 'public'   -- P1.4a
    group by e.holding_id
  ),
  active_reservas as (
    select
      rl.holding_id,
      count(*)::int as reservas_ativas_calc
    from public.reserva_linhas_v2 rl
    where rl.item_status = 'ativa'
      and rl.holding_id is not null
    group by rl.holding_id
  ),
  open_interlibrary_loans as (
    select
      il.holding_id,
      count(*)::int as emprestimos_interbib_abertos_calc
    from public.interlibrary_loan_items_v2 il
    where il.item_status in ('reservado_para_saida', 'emprestado')
      and il.holding_id is not null
    group by il.holding_id
  ),
  stats as (
    select
      th.id as holding_id,
      th.book_id,
      coalesce(ec.exemplares_total_calc, 0)::int as exemplares_total_calc,
      greatest(
        coalesce(ec.exemplares_total_calc, 0)
        - coalesce(ol.emprestimos_abertos_calc, 0)
        - coalesce(ar.reservas_ativas_calc, 0)
        - coalesce(oil.emprestimos_interbib_abertos_calc, 0),
        0
      )::int as available_count_calc
    from target_holdings th
    left join exemplar_counts ec
      on ec.holding_id = th.id
    left join open_loans ol
      on ol.holding_id = th.id
    left join active_reservas ar
      on ar.holding_id = th.id
    left join open_interlibrary_loans oil
      on oil.holding_id = th.id
  ),
  updated as (
    update public.book_holdings h
       set exemplares_total = s.exemplares_total_calc,
           available_count = s.available_count_calc,
           updated_at = timezone('utc', now())
      from stats s
     where h.id = s.holding_id
       and (
         h.exemplares_total is distinct from s.exemplares_total_calc
         or h.available_count is distinct from s.available_count_calc
       )
    returning 1
  )
  select count(*)::int
    into v_holdings_updated
  from updated;

  with target_holdings as (
    select h.id, h.book_id
    from public.book_holdings h
    where (
      coalesce(cardinality(p_holding_ids), 0) = 0
      or h.id = any(p_holding_ids)
    )
      and (
        coalesce(cardinality(p_book_ids), 0) = 0
        or h.book_id = any(p_book_ids)
      )
  ),
  target_books as (
    select distinct th.book_id
    from target_holdings th

    union

    select distinct x.book_id
    from unnest(coalesce(p_book_ids, '{}'::bigint[])) as x(book_id)
  ),
  exemplar_counts as (
    select
      e.holding_id,
      count(*)::int as exemplares_total_calc
    from public.exemplares e
    where e.holding_id is not null
      and e.visibility = 'public'   -- P1.4a
    group by e.holding_id
  ),
  open_loans as (
    select
      e.holding_id,
      count(*)::int as emprestimos_abertos_calc
    from public.emprestimo_itens_v2 i
    join public.exemplares e
      on e.id = i.item_id
    where i.item_status = 'aberto'
      and e.holding_id is not null
      and e.visibility = 'public'   -- P1.4a
    group by e.holding_id
  ),
  active_reservas as (
    select
      rl.holding_id,
      count(*)::int as reservas_ativas_calc
    from public.reserva_linhas_v2 rl
    where rl.item_status = 'ativa'
      and rl.holding_id is not null
    group by rl.holding_id
  ),
  open_interlibrary_loans as (
    select
      il.holding_id,
      count(*)::int as emprestimos_interbib_abertos_calc
    from public.interlibrary_loan_items_v2 il
    where il.item_status in ('reservado_para_saida', 'emprestado')
      and il.holding_id is not null
    group by il.holding_id
  ),
  stats as (
    select
      th.id as holding_id,
      th.book_id,
      greatest(
        coalesce(ec.exemplares_total_calc, 0)
        - coalesce(ol.emprestimos_abertos_calc, 0)
        - coalesce(ar.reservas_ativas_calc, 0)
        - coalesce(oil.emprestimos_interbib_abertos_calc, 0),
        0
      )::int as available_count_calc
    from target_holdings th
    left join exemplar_counts ec
      on ec.holding_id = th.id
    left join open_loans ol
      on ol.holding_id = th.id
    left join active_reservas ar
      on ar.holding_id = th.id
    left join open_interlibrary_loans oil
      on oil.holding_id = th.id
  ),
  book_totals as (
    select
      tb.book_id,
      coalesce(sum(s.available_count_calc), 0)::int as available_count_calc
    from target_books tb
    left join stats s
      on s.book_id = tb.book_id
    group by tb.book_id
  ),
  updated as (
    update public.books b
       set available_count = bt.available_count_calc,
           updated_at = now()
      from book_totals bt
     where b.id = bt.book_id
       and b.available_count is distinct from bt.available_count_calc
    returning 1
  )
  select count(*)::int
    into v_books_updated
  from updated;

  return query
  select
    v_holdings_recomputed,
    v_holdings_updated,
    v_books_recomputed,
    v_books_updated;
end;
$$;


ALTER FUNCTION "public"."fn_v2_recompute_holdings_availability"("p_holding_ids" bigint[], "p_book_ids" bigint[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_v2_refresh_consulta_status_global"("p_consulta_id" bigint) RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_total int := 0;
  v_active int := 0;
  v_new_status text := 'encerrada';
begin
  select count(*),
         count(*) filter (where item_status = 'ativa')
    into v_total, v_active
  from public.consulta_linhas_v2
  where consulta_id = p_consulta_id;

  if v_total = 0 then
    v_new_status := 'encerrada';
  elsif v_active = v_total then
    v_new_status := 'ativa';
  elsif v_active > 0 then
    v_new_status := 'parcialmente_encerrada';
  else
    v_new_status := 'encerrada';
  end if;

  update public.consultas_locais_v2
     set status_global = v_new_status,
         updated_at = timezone('utc', now())
   where id = p_consulta_id;

  return v_new_status;
end;
$$;


ALTER FUNCTION "public"."fn_v2_refresh_consulta_status_global"("p_consulta_id" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_v2_refresh_emprestimo_interbibliotecas_status_global"("p_loan_id" bigint) RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_exists boolean := false;
  v_current_status text := null;
  v_new_status text := null;
  v_start_date date := null;
  v_due_date date := null;
  v_total_items integer := 0;
  v_reserved_items integer := 0;
  v_loaned_items integer := 0;
  v_returned_items integer := 0;
  v_cancelled_items integer := 0;
  v_problem_items integer := 0;
begin
  select
    true,
    h.status_global,
    h.start_date,
    h.due_date
  into
    v_exists,
    v_current_status,
    v_start_date,
    v_due_date
  from public.interlibrary_loans_v2 h
  where h.id = p_loan_id;

  if not coalesce(v_exists, false) then
    raise exception 'Empréstimo interbibliotecas % não encontrado.', p_loan_id;
  end if;

  select
    count(*)::int,
    count(*) filter (where i.item_status = 'reservado_para_saida')::int,
    count(*) filter (where i.item_status = 'emprestado')::int,
    count(*) filter (where i.item_status = 'devolvido')::int,
    count(*) filter (where i.item_status = 'cancelado')::int,
    count(*) filter (where i.item_status in ('perdido', 'danificado'))::int
  into
    v_total_items,
    v_reserved_items,
    v_loaned_items,
    v_returned_items,
    v_cancelled_items,
    v_problem_items
  from public.interlibrary_loan_items_v2 i
  where i.interlibrary_loan_id = p_loan_id;

  if v_total_items = 0 then
    v_new_status := 'preparacao';

  elsif v_returned_items = v_total_items then
    v_new_status := 'devolvido';

  elsif v_cancelled_items = v_total_items then
    v_new_status := 'cancelado';

  elsif (v_returned_items + v_cancelled_items + v_problem_items) = v_total_items
        and v_loaned_items = 0
        and v_reserved_items = 0 then
    v_new_status := 'devolvido';

  elsif v_loaned_items > 0 and v_returned_items > 0 then
    if v_due_date is not null and v_due_date < current_date then
      v_new_status := 'atrasado';
    else
      v_new_status := 'parcialmente_devolvido';
    end if;

  elsif v_loaned_items > 0 then
    if v_due_date is not null and v_due_date < current_date then
      v_new_status := 'atrasado';
    elsif v_current_status = 'em_devolucao' then
      v_new_status := 'em_devolucao';
    else
      v_new_status := 'emprestado';
    end if;

  elsif v_reserved_items > 0 then
    if v_start_date is not null then
      v_new_status := 'aguardando_saida';
    else
      v_new_status := 'preparacao';
    end if;

  else
    v_new_status := coalesce(v_current_status, 'preparacao');
  end if;

  update public.interlibrary_loans_v2 h
     set status_global = v_new_status,
         dispatched_at = case
           when v_new_status in ('emprestado', 'parcialmente_devolvido', 'em_devolucao', 'atrasado')
                and h.dispatched_at is null
             then timezone('utc', now())
           else h.dispatched_at
         end,
         return_started_at = case
           when v_new_status = 'em_devolucao'
                and h.return_started_at is null
             then timezone('utc', now())
           else h.return_started_at
         end,
         returned_at = case
           when v_new_status = 'devolvido'
                and h.returned_at is null
             then timezone('utc', now())
           when v_new_status <> 'devolvido'
             then null
           else h.returned_at
         end,
         updated_at = timezone('utc', now()),
         updated_by = auth.uid()
   where h.id = p_loan_id;

  return v_new_status;
end;
$$;


ALTER FUNCTION "public"."fn_v2_refresh_emprestimo_interbibliotecas_status_global"("p_loan_id" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_v2_refresh_emprestimo_status_global"("p_emprestimo_id" bigint) RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_total int := 0;
  v_open  int := 0;
  v_returned int := 0;
  v_old_status text;
  v_new_status text;
BEGIN
  -- Charger l'ancien statut AVANT le UPDATE
  SELECT status_global INTO v_old_status
    FROM public.emprestimos_v2
   WHERE id = p_emprestimo_id;

  -- Calculer le nouveau statut
  SELECT COUNT(*)::int,
         COUNT(*) FILTER (WHERE item_status = 'aberto')::int,
         COUNT(*) FILTER (WHERE item_status = 'devolvido')::int
    INTO v_total, v_open, v_returned
    FROM public.emprestimo_itens_v2
   WHERE emprestimo_id = p_emprestimo_id;

  IF v_total = 0 THEN
    v_new_status := 'aberto';
  ELSIF v_open = 0 THEN
    v_new_status := 'encerrado';
  ELSIF v_returned > 0 THEN
    v_new_status := 'parcialmente_devolvido';
  ELSE
    v_new_status := 'aberto';
  END IF;

  -- Appliquer le nouveau statut
  UPDATE public.emprestimos_v2
     SET status_global = v_new_status,
         updated_at = now()
   WHERE id = p_emprestimo_id;

  -- ============================================================
  -- Dispatch selon la transition (cf. table de decisions paquet 9)
  -- ============================================================

  -- aberto -> encerrado : retour total direct (ex. emprunt 1-item rendu,
  --                       ou tous les items rendus en bloc en 1 transaction)
  IF v_old_status = 'aberto' AND v_new_status = 'encerrado' THEN
    PERFORM public.fn_dispatch_notify_event(
      'emprestimo_v2_devolvido', p_emprestimo_id, '{}'::jsonb
    );

  -- aberto -> parcialmente_devolvido : 1er retour partiel
  ELSIF v_old_status = 'aberto' AND v_new_status = 'parcialmente_devolvido' THEN
    PERFORM public.fn_dispatch_notify_event(
      'emprestimo_v2_parcialmente_devolvido', p_emprestimo_id, '{}'::jsonb
    );

  -- partial -> partial : retour partiel suivant (le statut ne change pas
  --                      mais on a quand meme un item rendu de plus)
  ELSIF v_old_status = 'parcialmente_devolvido' AND v_new_status = 'parcialmente_devolvido' THEN
    PERFORM public.fn_dispatch_notify_event(
      'emprestimo_v2_parcialmente_devolvido', p_emprestimo_id, '{}'::jsonb
    );

  -- partial -> encerrado : retour du dernier item, cloture l'emprunt
  --                        Event dedie pour wording de cloture chaleureuse
  ELSIF v_old_status = 'parcialmente_devolvido' AND v_new_status = 'encerrado' THEN
    PERFORM public.fn_dispatch_notify_event(
      'emprestimo_v2_devolvido_apos_parcial', p_emprestimo_id, '{}'::jsonb
    );

  -- Tout autre cas (encerrado -> *, aberto -> aberto,
  -- partial -> aberto si on annule un retour, etc.) : pas de mail.
  END IF;

  RETURN v_new_status;
END;
$$;


ALTER FUNCTION "public"."fn_v2_refresh_emprestimo_status_global"("p_emprestimo_id" bigint) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."fn_v2_refresh_emprestimo_status_global"("p_emprestimo_id" bigint) IS 'Paquet 9 (10/05/2026) : centralise la logique de notification au niveau
header. Lit l ancien statut, calcule le nouveau, applique le UPDATE,
puis dispatche un event selon la table de transitions :
- aberto -> encerrado : emprestimo_v2_devolvido (retour total direct)
- aberto -> partial : emprestimo_v2_parcialmente_devolvido (1er partiel)
- partial -> partial : emprestimo_v2_parcialmente_devolvido (partiel suivant)
- partial -> encerrado : emprestimo_v2_devolvido_apos_parcial (cloture)
Remplace l ancien trigger item-level qui dispatchait 1 fois par item.';



CREATE OR REPLACE FUNCTION "public"."fn_v2_refresh_reserva_status_global"("p_reserva_id" bigint) RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_total int := 0;
  v_active int := 0;
  v_new_status text := 'encerrada';
begin
  select count(*),
         count(*) filter (where item_status = 'ativa')
    into v_total, v_active
  from public.reserva_linhas_v2
  where reserva_id = p_reserva_id;

  if v_total = 0 then
    v_new_status := 'encerrada';
  elsif v_active = v_total then
    v_new_status := 'ativa';
  elsif v_active > 0 then
    v_new_status := 'parcialmente_encerrada';
  else
    v_new_status := 'encerrada';
  end if;

  update public.reservas_v2
     set status_global = v_new_status,
         updated_at = timezone('utc', now())
   where id = p_reserva_id;

  return v_new_status;
end;
$$;


