CREATE OR REPLACE FUNCTION "public"."fn_v2_remove_emprestimo_interbibliotecas_item"("p_loan_id" bigint, "p_line_nos" integer[]) RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_header public.interlibrary_loans_v2;
  v_count integer := 0;
  v_payload jsonb := '[]'::jsonb;
begin
  if auth.uid() is null then
    raise exception 'Autenticação obrigatória.';
  end if;

  select *
    into v_header
  from public.interlibrary_loans_v2
  where id = p_loan_id;

  if v_header.id is null then
    raise exception 'Empréstimo interbibliotecas não encontrado: %', p_loan_id;
  end if;

  if not public.user_can_manage_library(v_header.lender_library_id) then
    raise exception 'Somente a biblioteca emprestadora pode retirar itens deste empréstimo.';
  end if;

  if coalesce(cardinality(p_line_nos), 0) = 0 then
    raise exception 'Informe ao menos 1 linha para remover.';
  end if;

  if exists (
    select 1
    from public.interlibrary_loan_items_v2 i
    where i.interlibrary_loan_id = p_loan_id
      and i.line_no = any(p_line_nos)
      and i.item_status <> 'reservado_para_saida'
  ) then
    raise exception 'Só é possível remover linhas ainda reservadas para saída.';
  end if;

  select coalesce(
           jsonb_agg(
             jsonb_build_object(
               'line_no', i.line_no,
               'item_id', i.item_id,
               'holding_id', i.holding_id,
               'bib_ref', i.bib_ref,
               'rotulo', i.rotulo_cache
             )
             order by i.line_no
           ),
           '[]'::jsonb
         )
    into v_payload
  from public.interlibrary_loan_items_v2 i
  where i.interlibrary_loan_id = p_loan_id
    and i.line_no = any(p_line_nos);

  with deleted as (
    delete from public.interlibrary_loan_items_v2 i
    where i.interlibrary_loan_id = p_loan_id
      and i.line_no = any(p_line_nos)
      and i.item_status = 'reservado_para_saida'
    returning 1
  )
  select count(*)::int
    into v_count
  from deleted;

  if v_count = 0 then
    return 0;
  end if;

  update public.interlibrary_loans_v2 h
     set updated_at = timezone('utc', now()),
         updated_by = auth.uid()
   where h.id = p_loan_id;

  perform public.fn_v2_log_emprestimo_interbibliotecas_event(
    p_loan_id := p_loan_id,
    p_item_id := null,
    p_event_type := 'item_removed',
    p_event_note := 'Linha(s) removida(s) antes da saída.',
    p_payload := jsonb_build_object(
      'line_nos', p_line_nos,
      'removed_items', v_payload
    )
  );

  perform public.fn_v2_refresh_emprestimo_interbibliotecas_status_global(p_loan_id);
  perform public.fn_v2_recompute_from_emprestimo_interbibliotecas_linhas(p_loan_id, p_line_nos);

  return v_count;
end;
$$;


ALTER FUNCTION "public"."fn_v2_remove_emprestimo_interbibliotecas_item"("p_loan_id" bigint, "p_line_nos" integer[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_v2_remove_emprestimo_interbibliotecas_itens"("p_loan_id" bigint, "p_item_ids" bigint[], "p_note" "text" DEFAULT NULL::"text") RETURNS TABLE("loan_id" bigint, "removed_count" integer, "remaining_count" integer)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_actor uuid := auth.uid();
  v_header public.interlibrary_loans_v2%rowtype;
  v_clean_item_ids bigint[];
  v_target_count integer := 0;
  v_removed_count integer := 0;
  v_remaining_count integer := 0;
  v_note text := nullif(trim(coalesce(p_note, '')), '');
begin
  if v_actor is null then
    raise exception 'Autenticação obrigatória.';
  end if;

  if p_loan_id is null then
    raise exception 'Empréstimo interbibliotecas ausente.';
  end if;

  select *
    into v_header
  from public.interlibrary_loans_v2
  where id = p_loan_id
  for update;

  if not found then
    raise exception 'Empréstimo interbibliotecas não encontrado.';
  end if;

  if not public.user_can_manage_library(v_header.lender_library_id) then
    raise exception 'Somente a biblioteca emprestadora pode retirar exemplares antes da saída.';
  end if;

  if lower(coalesce(v_header.status_global, '')) not in ('preparacao', 'aguardando_saida') then
    raise exception 'Só é possível retirar exemplares antes da saída.';
  end if;

  select coalesce(array_agg(distinct x), '{}'::bigint[])
    into v_clean_item_ids
  from unnest(coalesce(p_item_ids, '{}'::bigint[])) as x
  where x is not null;

  if coalesce(array_length(v_clean_item_ids, 1), 0) = 0 then
    raise exception 'Nenhum exemplar informado.';
  end if;

  select count(*)
    into v_target_count
  from public.interlibrary_loan_items_v2 i
  where i.interlibrary_loan_id = p_loan_id
    and i.item_id = any(v_clean_item_ids)
    and lower(coalesce(i.item_status, '')) = 'reservado_para_saida';

  if v_target_count = 0 then
    raise exception 'Nenhum exemplar elegível para retirada foi encontrado neste empréstimo.';
  end if;

  select count(*)
    into v_remaining_count
  from public.interlibrary_loan_items_v2 i
  where i.interlibrary_loan_id = p_loan_id
    and lower(coalesce(i.item_status, '')) = 'reservado_para_saida';

  if (v_remaining_count - v_target_count) < 1 then
    raise exception 'Este empréstimo precisa manter ao menos um exemplar. Para encerrar antes da saída, use o cancelamento do empréstimo.';
  end if;

  delete from public.interlibrary_loan_items_v2 i
  where i.interlibrary_loan_id = p_loan_id
    and i.item_id = any(v_clean_item_ids)
    and lower(coalesce(i.item_status, '')) = 'reservado_para_saida';

  get diagnostics v_removed_count = row_count;

  if v_removed_count < 1 then
    raise exception 'Não consegui retirar os exemplares informados.';
  end if;

  with renumbered as (
    select
      i.id,
      row_number() over (order by i.line_no nulls last, i.id) as next_line_no
    from public.interlibrary_loan_items_v2 i
    where i.interlibrary_loan_id = p_loan_id
  )
  update public.interlibrary_loan_items_v2 i
     set line_no = r.next_line_no,
         sub_id = p_loan_id::text || '.' || r.next_line_no::text,
         updated_at = timezone('utc', now())
  from renumbered r
  where i.id = r.id;

  select count(*)
    into v_remaining_count
  from public.interlibrary_loan_items_v2 i
  where i.interlibrary_loan_id = p_loan_id;

  update public.interlibrary_loans_v2
     set status_global = case
                           when v_remaining_count > 0 then 'aguardando_saida'
                           else 'preparacao'
                         end,
         notes = coalesce(v_note, notes),
         updated_at = timezone('utc', now()),
         updated_by = v_actor
   where id = p_loan_id;

  return query
  select p_loan_id, v_removed_count, v_remaining_count;
end;
$$;


ALTER FUNCTION "public"."fn_v2_remove_emprestimo_interbibliotecas_itens"("p_loan_id" bigint, "p_item_ids" bigint[], "p_note" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_v2_resolve_catalog_refs_for_current_user"("p_refs" "text"[]) RETURNS TABLE("input_ref" "text", "ref_trimmed" "text", "matched" boolean, "match_kind" "text", "book_id" bigint, "bib_ref" "text", "session_holding_id" bigint, "session_local_bib_ref" "text", "session_loanable" boolean, "session_status_hint" "text", "session_available_count" integer, "message" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'api'
    AS $_$
declare
  v_uid uuid := auth.uid();
  v_access record;
  v_ref text;
  v_row record;
  v_count integer;
  v_norm_input text;
begin
  if v_uid is null then
    raise exception 'Autenticação obrigatória.';
  end if;

  select *
    into v_access
  from api.my_access
  limit 1;

  if v_access.user_id is null then
    raise exception 'Contexto de sessão indisponível.';
  end if;

  if v_access.default_library_id is null then
    raise exception 'Sua conta ainda não tem biblioteca de vínculo ativa.';
  end if;

  for input_ref, ref_trimmed in
    select x.raw_ref, nullif(btrim(x.raw_ref), '')
    from unnest(coalesce(p_refs, '{}'::text[])) with ordinality as x(raw_ref, ord)
    order by x.ord
  loop
    matched := false;
    match_kind := null;
    book_id := null;
    bib_ref := null;
    session_holding_id := null;
    session_local_bib_ref := null;
    session_loanable := null;
    session_status_hint := null;
    session_available_count := null;
    message := null;

    if ref_trimmed is null then
      message := 'Referência vazia.';
      return next;
      continue;
    end if;

    /*
      1) Match exact prioritaire sur la surface session-aware canonique.
         - session_local_bib_ref exact
         - puis bib_ref exact
    */
    select *
      into v_row
    from (
      select
        s.book_id,
        s.bib_ref,
        s.session_holding_id,
        s.session_local_bib_ref,
        s.session_loanable,
        s.session_status_hint,
        s.session_available_count,
        case
          when btrim(coalesce(s.session_local_bib_ref, '')) = ref_trimmed then 'session_local_bib_ref_exact'
          when btrim(coalesce(s.bib_ref, '')) = ref_trimmed then 'bib_ref_exact'
          else null
        end as resolved_match_kind,
        case
          when btrim(coalesce(s.session_local_bib_ref, '')) = ref_trimmed then 0
          when btrim(coalesce(s.bib_ref, '')) = ref_trimmed then 1
          else 9
        end as match_rank
      from api.catalog_books_public_session_v2 s
      where btrim(coalesce(s.session_local_bib_ref, '')) = ref_trimmed
         or btrim(coalesce(s.bib_ref, '')) = ref_trimmed
      order by match_rank, s.book_id
      limit 1
    ) q;

    if found then
      matched := true;
      match_kind := v_row.resolved_match_kind;
      book_id := v_row.book_id;
      bib_ref := v_row.bib_ref;
      session_holding_id := v_row.session_holding_id;
      session_local_bib_ref := v_row.session_local_bib_ref;
      session_loanable := v_row.session_loanable;
      session_status_hint := v_row.session_status_hint;
      session_available_count := v_row.session_available_count;

      message := case
        when session_holding_id is not null then 'ok'
        when session_status_hint = 'consultavel_no_local' then 'O título existe na sua biblioteca e é consultável no local.'
        when session_status_hint = 'indisponivel_para_voce' then 'Encontrei o título, mas não na sua biblioteca de vínculo.'
        when session_status_hint = 'sem_biblioteca_de_sessao' then 'Sua conta não tem biblioteca de vínculo ativa.'
        else 'Encontrei o título, mas sem holding utilizável na sua biblioteca de vínculo.'
      end;

      return next;
      continue;
    end if;

    /*
      2) Fallback prudente seulement pour les références purement numériques.
         On n'applique jamais cette logique aux références préfixées/alphanumériques.
         Et on n'accepte le fallback que s'il y a un seul match en session.
    */
    if ref_trimmed ~ '^[0-9]+$' then
      v_norm_input := ltrim(ref_trimmed, '0');
      if v_norm_input = '' then
        v_norm_input := '0';
      end if;

      select count(*)::int
        into v_count
      from api.catalog_books_public_session_v2 s
      where s.session_holding_id is not null
        and btrim(coalesce(s.session_local_bib_ref, '')) ~ '^[0-9]+$'
        and coalesce(nullif(ltrim(btrim(s.session_local_bib_ref), '0'), ''), '0') = v_norm_input;

      if coalesce(v_count, 0) = 1 then
        select
          s.book_id,
          s.bib_ref,
          s.session_holding_id,
          s.session_local_bib_ref,
          s.session_loanable,
          s.session_status_hint,
          s.session_available_count
          into v_row
        from api.catalog_books_public_session_v2 s
        where s.session_holding_id is not null
          and btrim(coalesce(s.session_local_bib_ref, '')) ~ '^[0-9]+$'
          and coalesce(nullif(ltrim(btrim(s.session_local_bib_ref), '0'), ''), '0') = v_norm_input
        order by s.book_id
        limit 1;

        matched := true;
        match_kind := 'session_local_bib_ref_numeric_fallback';
        book_id := v_row.book_id;
        bib_ref := v_row.bib_ref;
        session_holding_id := v_row.session_holding_id;
        session_local_bib_ref := v_row.session_local_bib_ref;
        session_loanable := v_row.session_loanable;
        session_status_hint := v_row.session_status_hint;
        session_available_count := v_row.session_available_count;
        message := 'ok';

        return next;
        continue;
      elsif coalesce(v_count, 0) > 1 then
        message := 'Referência numérica ambígua na sua biblioteca de vínculo.';
        return next;
        continue;
      end if;
    end if;

    message := 'Não encontrei essa referência na sua biblioteca de vínculo.';
    return next;
  end loop;

  return;
end;
$_$;


ALTER FUNCTION "public"."fn_v2_resolve_catalog_refs_for_current_user"("p_refs" "text"[]) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."fn_v2_resolve_catalog_refs_for_current_user"("p_refs" "text"[]) IS '2026-04-01: RPC de resolução session-aware des références catalogue pour conta. S''appuie sur api.catalog_books_public_session_v2 au lieu d''interroger public.book_holdings directement. Match exact prioritaire; fallback numérique prudent réservé aux références purement numériques et aux cas non ambigus.';



CREATE OR REPLACE FUNCTION "public"."fn_v2_resolve_consulta_exemplar"("p_holding_id" bigint) RETURNS bigint
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  -- Renvoie l'id d'un exemplaire du holding non engage dans aucun circuit,
  -- ou NULL si aucun n'est libre. Quatre circuits croises, comme
  -- fn_peb_search_exemplares (#ILL-availability).
  SELECT e.id
  FROM public.exemplares e
  WHERE e.holding_id = p_holding_id
    -- (0) consultable per §6.2 (DOC-CIRC-1) : visible au public + autorise a la consultation
    AND e.visibility = 'public'                          -- P1.4b §6.2
    AND e.circulation_policy IN ('consulta', 'ambos')    -- P1.4b §6.2
    -- (1) pas d'emprunt ordinaire en cours
    AND NOT EXISTS (
      SELECT 1 FROM public.emprestimo_itens_v2 ei
      WHERE ei.item_id = e.id AND ei.item_status = 'aberto'
    )
    -- (2) pas de reservation active
    AND NOT EXISTS (
      SELECT 1 FROM public.reserva_linhas_v2 rl
      WHERE rl.item_id = e.id AND rl.item_status = 'ativa'
    )
    -- (3) pas engage dans un PEB
    AND NOT EXISTS (
      SELECT 1 FROM public.interlibrary_loan_items_v2 ili
      WHERE ili.item_id = e.id
        AND ili.item_status IN ('reservado_para_saida', 'emprestado')
    )
    -- (4) pas deja en consultation active (desormais a l'item_id)
    AND NOT EXISTS (
      SELECT 1 FROM public.consulta_linhas_v2 cl
      WHERE cl.item_id = e.id AND cl.item_status = 'ativa'
    )
  ORDER BY e.id
  LIMIT 1;
$$;


