CREATE OR REPLACE FUNCTION "public"."fn_v2_return_emprestimo_interbibliotecas_linhas"("p_loan_id" bigint, "p_line_nos" integer[], "p_condition_back" "text" DEFAULT NULL::"text", "p_note" "text" DEFAULT NULL::"text") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_header public.interlibrary_loans_v2;
  v_count integer := 0;
begin
  if auth.uid() is null then
    raise exception 'Autenticação obrigatória.';
  end if;

  select *
    into v_header
  from public.interlibrary_loans_v2
  where id = p_loan_id;

  if v_header.id is null then
    raise exception 'Empréstimo interbibliotecas não encontrado: %', p_loan_id;
  end if;

  if not public.user_can_manage_library(v_header.lender_library_id) then
    raise exception 'Somente a biblioteca emprestadora pode registrar o retorno real.';
  end if;

  if coalesce(cardinality(p_line_nos), 0) = 0 then
    raise exception 'Informe ao menos 1 linha para registrar retorno.';
  end if;

  with updated as (
    update public.interlibrary_loan_items_v2 i
       set item_status = 'devolvido',
           returned_at = timezone('utc', now()),
           condition_back = coalesce(nullif(trim(coalesce(p_condition_back, '')), ''), i.condition_back),
           notes = coalesce(nullif(trim(coalesce(p_note, '')), ''), i.notes),
           updated_at = timezone('utc', now())
     where i.interlibrary_loan_id = p_loan_id
       and i.line_no = any(p_line_nos)
       and i.item_status = 'emprestado'
     returning 1
  )
  select count(*)::int
    into v_count
  from updated;

  if v_count = 0 then
    return 0;
  end if;

  update public.interlibrary_loans_v2 h
     set updated_at = timezone('utc', now()),
         updated_by = auth.uid()
   where h.id = p_loan_id;

  perform public.fn_v2_log_emprestimo_interbibliotecas_event(
    p_loan_id := p_loan_id,
    p_item_id := null,
    p_event_type := 'item_returned',
    p_event_note := 'Retorno de linha(s) registrado.',
    p_payload := jsonb_build_object(
      'line_nos', p_line_nos,
      'condition_back', nullif(trim(coalesce(p_condition_back, '')), '')
    )
  );

  perform public.fn_v2_refresh_emprestimo_interbibliotecas_status_global(p_loan_id);
  perform public.fn_v2_recompute_from_emprestimo_interbibliotecas_linhas(p_loan_id, p_line_nos);

  return v_count;
end;
$$;


ALTER FUNCTION "public"."fn_v2_return_emprestimo_interbibliotecas_linhas"("p_loan_id" bigint, "p_line_nos" integer[], "p_condition_back" "text", "p_note" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_v2_return_emprestimo_linhas"("p_emprestimo_id" bigint, "p_line_nos" integer[], "p_notes" "text" DEFAULT NULL::"text") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_actor public.my_access%rowtype;
  v_count integer := 0;
begin
  if auth.uid() is null then
    raise exception 'Autenticação obrigatória.';
  end if;

  select * into v_actor from public.my_access limit 1;

  if coalesce(v_actor.can_access_painel, false) is false then
    raise exception 'Acesso bibliotecário obrigatório.';
  end if;

  with updated as (
    update public.emprestimo_itens_v2 i
       set item_status = 'devolvido',
           returned_at = now(),
           return_schedule_status = 'devolucao_realizada',
           return_completed_at = now(),
           notes = coalesce(p_notes, i.notes),
           updated_at = now()
     where i.emprestimo_id = p_emprestimo_id
       and i.line_no = any(p_line_nos)
       and i.item_status = 'aberto'
     returning i.book_id
  )
  select count(*)::int into v_count from updated;

  -- BUG-retour-partiel-faux-succès (28/05/2026) : exception explicite si 0 ligne.
  -- Auparavant : return 0 silencieux → faux positif cote UI.
  if v_count = 0 then
    raise exception 'no_lines_returned'
      using errcode = 'P0001',
            hint = format('Nenhuma linha aberta encontrada para o empréstimo %s nas linhas %s.',
                          p_emprestimo_id, p_line_nos::text);
  end if;

  update public.books b
     set available_count = coalesce(b.available_count, 0) + x.qty
    from (
      select book_id, count(*)::int as qty
      from public.emprestimo_itens_v2
      where emprestimo_id = p_emprestimo_id
        and line_no = any(p_line_nos)
        and returned_at is not null
      group by book_id
    ) x
   where b.id = x.book_id;

  perform public.fn_v2_refresh_emprestimo_status_global(p_emprestimo_id);
  perform public.fn_v2_recompute_from_emprestimo_lines(p_emprestimo_id, p_line_nos);

  return v_count;
end;
$$;


ALTER FUNCTION "public"."fn_v2_return_emprestimo_linhas"("p_emprestimo_id" bigint, "p_line_nos" integer[], "p_notes" "text") OWNER TO "postgres";


