CREATE OR REPLACE FUNCTION "public"."fn_v2_schedule_emprestimo_return"("p_emprestimo_id" bigint, "p_line_nos" integer[], "p_return_scheduled_for" timestamp with time zone, "p_actor_role" "text") RETURNS TABLE("ok" boolean, "message" "text", "return_scheduled_for" timestamp with time zone)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_actor public.my_access%rowtype;
  v_header public.emprestimos_v2%rowtype;
begin
  if auth.uid() is null then
    raise exception 'Autenticação obrigatória.';
  end if;

  if p_return_scheduled_for is null then
    return query select false, 'Informe data e hora para a devolução.', null::timestamptz;
    return;
  end if;

  select * into v_actor from public.my_access limit 1;

  select * into v_header
  from public.emprestimos_v2
  where id = p_emprestimo_id;

  if not found then
    return query select false, 'Empréstimo não encontrado.', null::timestamptz;
    return;
  end if;

  if p_actor_role = 'leitor' then
    if v_header.user_id <> auth.uid() then
      raise exception 'Este empréstimo pertence a outra pessoa.';
    end if;
  elsif p_actor_role = 'biblioteca' then
    if not (
      coalesce(v_actor.can_access_painel, false) is true
      and v_actor.library_id = v_header.library_id
    ) then
      raise exception 'Acesso bibliotecário obrigatório para agendar devolução.';
    end if;
  else
    raise exception 'Papel de atuação inválido: %', p_actor_role;
  end if;

  update public.emprestimo_itens_v2
     set return_scheduled_for = p_return_scheduled_for,
         return_scheduled_by = auth.uid(),
         return_scheduled_at = now(),
         return_schedule_status = 'devolucao_agendada',
         return_completed_at = null,
         return_missed_at = null,
         updated_at = now()
   where emprestimo_id = p_emprestimo_id
     and line_no = any(p_line_nos)
     and item_status = 'aberto';

  return query
  select true, 'Agendamento de devolução registrado.', p_return_scheduled_for;
end;
$$;


ALTER FUNCTION "public"."fn_v2_schedule_emprestimo_return"("p_emprestimo_id" bigint, "p_line_nos" integer[], "p_return_scheduled_for" timestamp with time zone, "p_actor_role" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_v2_set_consulta_linhas_schedule_reply"("p_consulta_id" bigint, "p_line_nos" integer[], "p_reply_status" "text", "p_note" "text" DEFAULT NULL::"text") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_uid uuid := auth.uid();
  v_updated integer := 0;
  v_library_id uuid;
  v_slot record;
begin
  if v_uid is null then
    raise exception 'Autenticação obrigatória.';
  end if;

  if p_reply_status is null or p_reply_status not in ('confirmado_leitor', 'recusado_leitor') then
    raise exception 'Resposta de agendamento inválida.';
  end if;

  select c.library_id
    into v_library_id
  from public.consultas_locais_v2 c
  where c.id = p_consulta_id
    and c.user_id = v_uid;

  if v_library_id is null then
    raise exception 'Você não pode responder por este pedido de consulta local.';
  end if;

  if p_reply_status = 'confirmado_leitor' then
    for v_slot in
      select distinct
        coalesce(w.consultation_starts_at, w.consultation_scheduled_for) as consultation_starts_at,
        coalesce(w.consultation_ends_at, w.consultation_scheduled_for + interval '1 hour') as consultation_ends_at
      from public.consulta_item_workflow_v2 w
      join public.consulta_linhas_v2 cl
        on cl.consulta_id = w.consulta_id
       and cl.line_no = w.line_no
      where w.consulta_id = p_consulta_id
        and cl.line_no = any(p_line_nos)
        and cl.item_status = 'ativa'
        and coalesce(w.workflow_stage, '') = 'consulta_agendada'
    loop
      perform public.fn_validate_consulta_schedule_window(
        v_library_id,
        p_consulta_id,
        v_slot.consultation_starts_at,
        v_slot.consultation_ends_at
      );
    end loop;
  end if;

  insert into public.consulta_item_workflow_v2 (
    consulta_id,
    line_no,
    workflow_stage,
    workflow_note,
    consultation_scheduled_for,
    consultation_starts_at,
    consultation_ends_at,
    schedule_reply_status,
    schedule_reply_note,
    schedule_reply_at,
    updated_at,
    updated_by
  )
  select
    cl.consulta_id,
    cl.line_no,
    coalesce(w.workflow_stage, 'solicitada'),
    w.workflow_note,
    w.consultation_scheduled_for,
    w.consultation_starts_at,
    w.consultation_ends_at,
    p_reply_status,
    nullif(trim(p_note), ''),
    timezone('utc', now()),
    timezone('utc', now()),
    v_uid
  from public.consulta_linhas_v2 cl
  left join public.consulta_item_workflow_v2 w
    on w.consulta_id = cl.consulta_id
   and w.line_no = cl.line_no
  where cl.consulta_id = p_consulta_id
    and cl.line_no = any(p_line_nos)
    and cl.item_status = 'ativa'
    and coalesce(w.workflow_stage, '') = 'consulta_agendada'
  on conflict (consulta_id, line_no)
  do update
     set schedule_reply_status = excluded.schedule_reply_status,
         schedule_reply_note = excluded.schedule_reply_note,
         schedule_reply_at = excluded.schedule_reply_at,
         updated_at = excluded.updated_at,
         updated_by = excluded.updated_by;

  get diagnostics v_updated = row_count;
  return v_updated;
end;
$$;


ALTER FUNCTION "public"."fn_v2_set_consulta_linhas_schedule_reply"("p_consulta_id" bigint, "p_line_nos" integer[], "p_reply_status" "text", "p_note" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_v2_set_consulta_linhas_workflow"("p_consulta_id" bigint, "p_line_nos" integer[], "p_workflow_stage" "text", "p_workflow_note" "text" DEFAULT NULL::"text", "p_consultation_scheduled_for" timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_uid uuid := auth.uid();
  v_stage text := trim(coalesce(p_workflow_stage, ''));
  v_library_id uuid;
  v_updated int := 0;
begin
  if v_uid is null then
    raise exception 'Sessão inválida.';
  end if;

  if coalesce(array_length(p_line_nos, 1), 0) = 0 then
    raise exception 'Selecione ao menos uma linha de consulta.';
  end if;

  if v_stage = '' then
    raise exception 'Etapa de workflow obrigatória.';
  end if;

  if v_stage not in (
    'em_preparacao',
    'consulta_agendada',
    'consulta_realizada',
    'nao_compareceu',
    'cancelada_biblioteca',
    'expirada'
  ) then
    raise exception 'Etapa de workflow inválida para consulta local: %', v_stage;
  end if;

  if v_stage = 'consulta_agendada' and p_consultation_scheduled_for is null then
    raise exception 'Informe a data e hora da consulta agendada.';
  end if;

  select c.library_id
    into v_library_id
  from public.consultas_locais_v2 c
  where c.id = p_consulta_id;

  if v_library_id is null then
    raise exception 'Consulta local não encontrada.';
  end if;

  if not exists (
    select 1
    from api.my_access a
    where a.user_id = v_uid
      and a.can_access_painel = true
      and a.library_id = v_library_id
  ) then
    raise exception 'Você não pode gerir esta consulta local.';
  end if;

  -- ============================================================
  -- ORDRE INVERSE (Fix B6, 16/05/2026) :
  -- AVANT : UPDATE linhas_v2 PUIS INSERT workflow_v2
  --   -> Le trigger lifecycle (AFTER UPDATE linhas_v2) se declenchait
  --      AVANT que workflow_v2.workflow_note soit ecrite.
  --      Il lisait donc l'ancienne note (note de creation initiale).
  --
  -- APRES : INSERT workflow_v2 PUIS UPDATE linhas_v2
  --   -> Le trigger lifecycle (AFTER UPDATE linhas_v2) se declenche
  --      APRES que workflow_v2.workflow_note soit a jour.
  --      Il lit donc la bonne note (motif d'annulation par la biblio).
  -- ============================================================

  -- Etape 1 : INSERT/UPSERT consulta_item_workflow_v2
  insert into public.consulta_item_workflow_v2 (
    consulta_id,
    line_no,
    workflow_stage,
    workflow_note,
    consultation_scheduled_for,
    updated_at,
    updated_by
  )
  select
    cl.consulta_id,
    cl.line_no,
    v_stage,
    nullif(trim(p_workflow_note), ''),
    p_consultation_scheduled_for,
    timezone('utc', now()),
    v_uid
  from public.consulta_linhas_v2 cl
  where cl.consulta_id = p_consulta_id
    and cl.line_no = any(p_line_nos)
  on conflict (consulta_id, line_no)
  do update
     set workflow_stage = excluded.workflow_stage,
         workflow_note = coalesce(excluded.workflow_note, public.consulta_item_workflow_v2.workflow_note),
         consultation_scheduled_for = coalesce(excluded.consultation_scheduled_for, public.consulta_item_workflow_v2.consultation_scheduled_for),
         schedule_reply_status = case
           when excluded.workflow_stage = 'consulta_agendada' then null
           else public.consulta_item_workflow_v2.schedule_reply_status
         end,
         schedule_reply_note = case
           when excluded.workflow_stage = 'consulta_agendada' then null
           else public.consulta_item_workflow_v2.schedule_reply_note
         end,
         schedule_reply_at = case
           when excluded.workflow_stage = 'consulta_agendada' then null
           else public.consulta_item_workflow_v2.schedule_reply_at
         end,
         updated_at = excluded.updated_at,
         updated_by = excluded.updated_by;

  -- Etape 2 : UPDATE consulta_linhas_v2 (declenche trigger lifecycle apres
  -- que workflow_note soit a jour)
  update public.consulta_linhas_v2 cl
     set item_status = case
           when v_stage = 'consulta_realizada' then 'consultada'
           when v_stage = 'cancelada_biblioteca' then 'cancelada_biblioteca'
           when v_stage = 'expirada' then 'expirada'
           else cl.item_status
         end,
         cancelled_at = case
           when v_stage = 'cancelada_biblioteca' then coalesce(cl.cancelled_at, timezone('utc', now()))
           else cl.cancelled_at
         end,
         consulted_at = case
           when v_stage = 'consulta_realizada' then coalesce(cl.consulted_at, timezone('utc', now()))
           else cl.consulted_at
         end,
         expired_at = case
           when v_stage = 'expirada' then coalesce(cl.expired_at, timezone('utc', now()))
           else cl.expired_at
         end,
         updated_at = timezone('utc', now())
   where cl.consulta_id = p_consulta_id
     and cl.line_no = any(p_line_nos)
     and cl.item_status = 'ativa';

  get diagnostics v_updated = row_count;

  perform public.fn_v2_refresh_consulta_status_global(p_consulta_id);

  return v_updated;
end;
$$;


ALTER FUNCTION "public"."fn_v2_set_consulta_linhas_workflow"("p_consulta_id" bigint, "p_line_nos" integer[], "p_workflow_stage" "text", "p_workflow_note" "text", "p_consultation_scheduled_for" timestamp with time zone) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."fn_v2_set_consulta_linhas_workflow"("p_consulta_id" bigint, "p_line_nos" integer[], "p_workflow_stage" "text", "p_workflow_note" "text", "p_consultation_scheduled_for" timestamp with time zone) IS 'Fonction interne workflow consultas v2. v2 (16/05/2026) : ordre des UPDATEs inverse (workflow_v2 avant linhas_v2) pour fix B6 (note d''annulation biblio dans mail lecteur). Cf. doctrine paquet 141.2.E.';



CREATE OR REPLACE FUNCTION "public"."fn_v2_set_consulta_linhas_workflow_slot"("p_consulta_id" bigint, "p_line_nos" integer[], "p_workflow_stage" "text", "p_workflow_note" "text" DEFAULT NULL::"text", "p_consultation_date_local" "text" DEFAULT NULL::"text", "p_consultation_start_local" "text" DEFAULT NULL::"text", "p_consultation_end_local" "text" DEFAULT NULL::"text", "p_consultation_timezone" "text" DEFAULT NULL::"text") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $_$
declare
  v_uid uuid := auth.uid();
  v_stage text := trim(coalesce(p_workflow_stage, ''));
  v_library_id uuid;
  v_timezone text := 'America/Belem';
  v_start_at timestamptz := null;
  v_end_at timestamptz := null;
  v_scheduled_for timestamptz := null;
  v_updated integer := 0;
begin
  if v_uid is null then
    raise exception 'Sessão inválida.';
  end if;

  if coalesce(array_length(p_line_nos, 1), 0) = 0 then
    raise exception 'Selecione ao menos uma linha de consulta.';
  end if;

  if v_stage = '' then
    raise exception 'Etapa de workflow obrigatória.';
  end if;

  if v_stage not in (
    'em_preparacao',
    'consulta_agendada',
    'consulta_realizada',
    'nao_compareceu',
    'cancelada_biblioteca',
    'expirada'
  ) then
    raise exception 'Etapa de workflow inválida para consulta local: %', v_stage;
  end if;

  select c.library_id
    into v_library_id
  from public.consultas_locais_v2 c
  where c.id = p_consulta_id;

  if v_library_id is null then
    raise exception 'Consulta local não encontrada.';
  end if;

  if not exists (
    select 1
    from api.my_access a
    where a.user_id = v_uid
      and a.can_access_painel = true
      and a.library_id = v_library_id
  ) then
    raise exception 'Você não pode gerir esta consulta local.';
  end if;

  select coalesce(nullif(btrim(p_consultation_timezone), ''), nullif(btrim(s.consultation_timezone), ''), 'America/Belem')
    into v_timezone
  from public.library_service_state s
  where s.library_id = v_library_id;

  if v_stage = 'consulta_agendada' then
    if p_consultation_date_local is null
       or p_consultation_start_local is null
       or p_consultation_end_local is null then
      raise exception 'Informe a data, a hora de início e a hora de fim da consulta.';
    end if;

    if p_consultation_date_local !~ '^\d{4}-\d{2}-\d{2}$' then
      raise exception 'Data de consulta inválida. Use o formato ISO YYYY-MM-DD.';
    end if;

    if p_consultation_start_local !~ '^\d{2}:\d{2}$'
       or p_consultation_end_local !~ '^\d{2}:\d{2}$' then
      raise exception 'Horas de consulta inválidas. Use HH:MM.';
    end if;

    v_start_at := ((p_consultation_date_local || ' ' || p_consultation_start_local)::timestamp) at time zone v_timezone;
    v_end_at := ((p_consultation_date_local || ' ' || p_consultation_end_local)::timestamp) at time zone v_timezone;
    v_scheduled_for := v_start_at;

    perform public.fn_validate_consulta_schedule_window(
      v_library_id,
      p_consulta_id,
      v_start_at,
      v_end_at
    );
  end if;

  update public.consulta_linhas_v2 cl
     set item_status = case
           when v_stage = 'consulta_realizada' then 'consultada'
           when v_stage = 'cancelada_biblioteca' then 'cancelada_biblioteca'
           when v_stage = 'expirada' then 'expirada'
           else cl.item_status
         end,
         cancelled_at = case
           when v_stage = 'cancelada_biblioteca' then coalesce(cl.cancelled_at, timezone('utc', now()))
           else cl.cancelled_at
         end,
         consulted_at = case
           when v_stage = 'consulta_realizada' then coalesce(cl.consulted_at, timezone('utc', now()))
           else cl.consulted_at
         end,
         expired_at = case
           when v_stage = 'expirada' then coalesce(cl.expired_at, timezone('utc', now()))
           else cl.expired_at
         end,
         updated_at = timezone('utc', now())
   where cl.consulta_id = p_consulta_id
     and cl.line_no = any(p_line_nos)
     and cl.item_status = 'ativa';

  get diagnostics v_updated = row_count;

  insert into public.consulta_item_workflow_v2 (
    consulta_id,
    line_no,
    workflow_stage,
    workflow_note,
    consultation_scheduled_for,
    consultation_starts_at,
    consultation_ends_at,
    updated_at,
    updated_by
  )
  select
    cl.consulta_id,
    cl.line_no,
    v_stage,
    nullif(trim(p_workflow_note), ''),
    v_scheduled_for,
    v_start_at,
    v_end_at,
    timezone('utc', now()),
    v_uid
  from public.consulta_linhas_v2 cl
  where cl.consulta_id = p_consulta_id
    and cl.line_no = any(p_line_nos)
  on conflict (consulta_id, line_no)
  do update
     set workflow_stage = excluded.workflow_stage,
         workflow_note = coalesce(excluded.workflow_note, public.consulta_item_workflow_v2.workflow_note),
         consultation_scheduled_for = coalesce(excluded.consultation_scheduled_for, public.consulta_item_workflow_v2.consultation_scheduled_for),
         consultation_starts_at = coalesce(excluded.consultation_starts_at, public.consulta_item_workflow_v2.consultation_starts_at),
         consultation_ends_at = coalesce(excluded.consultation_ends_at, public.consulta_item_workflow_v2.consultation_ends_at),
         schedule_reply_status = case
           when excluded.workflow_stage = 'consulta_agendada' then null
           else public.consulta_item_workflow_v2.schedule_reply_status
         end,
         schedule_reply_note = case
           when excluded.workflow_stage = 'consulta_agendada' then null
           else public.consulta_item_workflow_v2.schedule_reply_note
         end,
         schedule_reply_at = case
           when excluded.workflow_stage = 'consulta_agendada' then null
           else public.consulta_item_workflow_v2.schedule_reply_at
         end,
         updated_at = excluded.updated_at,
         updated_by = excluded.updated_by;

  perform public.fn_v2_refresh_consulta_status_global(p_consulta_id);

  return v_updated;
end;
$_$;


ALTER FUNCTION "public"."fn_v2_set_consulta_linhas_workflow_slot"("p_consulta_id" bigint, "p_line_nos" integer[], "p_workflow_stage" "text", "p_workflow_note" "text", "p_consultation_date_local" "text", "p_consultation_start_local" "text", "p_consultation_end_local" "text", "p_consultation_timezone" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_v2_set_reserva_linhas_pickup_reply"("p_reserva_id" bigint, "p_line_nos" integer[], "p_reply_status" "text", "p_note" "text" DEFAULT NULL::"text") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_uid uuid := auth.uid();
  v_updated int := 0;
begin
  if v_uid is null then
    raise exception 'Autenticação obrigatória.';
  end if;

  if p_reply_status is null or p_reply_status not in ('confirmado_leitor', 'recusado_leitor') then
    raise exception 'Resposta de retirada inválida.';
  end if;

  if not exists (
    select 1
    from public.reservas_v2 r
    where r.id = p_reserva_id
      and r.user_id = v_uid
  ) then
    raise exception 'Você não pode responder por esta reserva.';
  end if;

  insert into public.reserva_item_workflow_v2 (
    reserva_id,
    line_no,
    workflow_stage,
    workflow_note,
    pickup_reply_status,
    pickup_reply_note,
    pickup_reply_at,
    updated_at,
    updated_by
  )
  select
    rl.reserva_id,
    rl.line_no,
    coalesce(w.workflow_stage, 'solicitada'),
    coalesce(w.workflow_note, null),
    p_reply_status,
    nullif(trim(p_note), ''),
    timezone('utc', now()),
    timezone('utc', now()),
    v_uid
  from public.reserva_linhas_v2 rl
  left join public.reserva_item_workflow_v2 w
    on w.reserva_id = rl.reserva_id
   and w.line_no = rl.line_no
  where rl.reserva_id = p_reserva_id
    and rl.line_no = any(p_line_nos)
    and rl.item_status = 'ativa'
  on conflict (reserva_id, line_no)
  do update
     set pickup_reply_status = excluded.pickup_reply_status,
         pickup_reply_note = excluded.pickup_reply_note,
         pickup_reply_at = excluded.pickup_reply_at,
         updated_at = excluded.updated_at,
         updated_by = excluded.updated_by;

  get diagnostics v_updated = row_count;
  return v_updated;
end;
$$;


ALTER FUNCTION "public"."fn_v2_set_reserva_linhas_pickup_reply"("p_reserva_id" bigint, "p_line_nos" integer[], "p_reply_status" "text", "p_note" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_v2_set_reserva_linhas_workflow"("p_reserva_id" bigint, "p_line_nos" integer[], "p_workflow_stage" "text", "p_workflow_note" "text" DEFAULT NULL::"text", "p_pickup_scheduled_for" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_pickup_proposed_by" "text" DEFAULT NULL::"text", "p_clear_pickup_reply" boolean DEFAULT false) RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'api'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_library_id uuid;
  v_stage text := trim(coalesce(p_workflow_stage, ''));
  v_updated int := 0;
  -- Résolution du sentinel '__CLEAR__' pour pickup_proposed_by
  v_pb_resolved text;
  v_pb_should_set boolean := (p_pickup_proposed_by IS NOT NULL);
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'Autenticação obrigatória.';
  END IF;

  IF v_stage = '' THEN
    RAISE EXCEPTION 'Etapa de workflow obrigatória.';
  END IF;

  -- Validation valeur p_pickup_proposed_by
  IF v_pb_should_set THEN
    IF p_pickup_proposed_by NOT IN ('biblio', 'leitor', '__CLEAR__') THEN
      RAISE EXCEPTION 'p_pickup_proposed_by deve ser ''biblio'', ''leitor'' ou ''__CLEAR__'' (recebido: %).', p_pickup_proposed_by
        USING ERRCODE = '22023';
    END IF;
    v_pb_resolved := CASE WHEN p_pickup_proposed_by = '__CLEAR__' THEN NULL ELSE p_pickup_proposed_by END;
  END IF;

  SELECT r.library_id INTO v_library_id
  FROM public.reservas_v2 r
  WHERE r.id = p_reserva_id;

  IF v_library_id IS NULL THEN
    RAISE EXCEPTION 'Reserva não encontrada.';
  END IF;

  IF NOT EXISTS (
    SELECT 1
    FROM api.my_access a
    WHERE a.user_id = v_uid
      AND a.can_access_painel = true
      AND a.library_id = v_library_id
  ) THEN
    RAISE EXCEPTION 'Você não pode gerir esta reserva.';
  END IF;

  -- Bloc 1 : mise à jour des reserva_linhas_v2 (statut, dates de cancellation)
  UPDATE public.reserva_linhas_v2 rl
     SET item_status = CASE
           WHEN v_stage = 'cancelada_biblioteca' THEN 'cancelada_biblioteca'
           WHEN v_stage = 'expirada' THEN 'expirada'
           WHEN v_stage = 'liberada_para_circulacao' THEN 'liberada_para_circulacao'
           ELSE rl.item_status
         END,
         cancelled_at = CASE
           WHEN v_stage = 'cancelada_biblioteca' THEN coalesce(rl.cancelled_at, timezone('utc', now()))
           ELSE rl.cancelled_at
         END,
         expired_at = CASE
           WHEN v_stage = 'expirada' THEN coalesce(rl.expired_at, timezone('utc', now()))
           ELSE rl.expired_at
         END,
         updated_at = timezone('utc', now())
   WHERE rl.reserva_id = p_reserva_id
     AND rl.line_no = ANY(p_line_nos)
     AND rl.item_status = 'ativa';

  GET DIAGNOSTICS v_updated = ROW_COUNT;

  -- Bloc 2 : upsert reserva_item_workflow_v2 (UN SEUL UPDATE !)
  -- Toutes les colonnes susceptibles de changer sont passées dans le SET en
  -- une fois, ce qui empêche le déclenchement multiple du trigger AFTER UPDATE.
  --
  -- Convention sur p_pickup_proposed_by :
  --   - NULL  → ne pas toucher (COALESCE classique)
  --   - 'biblio'/'leitor' → set à cette valeur
  --   - '__CLEAR__' → forcer NULL (résolu en v_pb_resolved=NULL ci-dessus,
  --     mais on doit le distinguer du cas "ne pas toucher" via v_pb_should_set)
  INSERT INTO public.reserva_item_workflow_v2 (
    reserva_id,
    line_no,
    workflow_stage,
    workflow_note,
    pickup_scheduled_for,
    pickup_proposed_by,
    pickup_reply_status,
    pickup_reply_note,
    pickup_reply_at,
    updated_at,
    updated_by
  )
  SELECT
    rl.reserva_id,
    rl.line_no,
    v_stage,
    nullif(trim(p_workflow_note), ''),
    p_pickup_scheduled_for,
    -- À l'INSERT : on respecte p_pickup_proposed_by si fourni, NULL sinon
    CASE WHEN v_pb_should_set THEN v_pb_resolved ELSE NULL END,
    -- À l'INSERT : pickup_reply_* toujours NULL (rien encore reçu)
    NULL,
    NULL,
    NULL,
    timezone('utc', now()),
    v_uid
  FROM public.reserva_linhas_v2 rl
  WHERE rl.reserva_id = p_reserva_id
    AND rl.line_no = ANY(p_line_nos)
  ON CONFLICT (reserva_id, line_no)
  DO UPDATE
     SET workflow_stage = excluded.workflow_stage,
         workflow_note = coalesce(excluded.workflow_note, public.reserva_item_workflow_v2.workflow_note),
         pickup_scheduled_for = coalesce(excluded.pickup_scheduled_for, public.reserva_item_workflow_v2.pickup_scheduled_for),
         -- pickup_proposed_by : 3 cas distincts gérés via v_pb_should_set
         pickup_proposed_by = CASE
           WHEN v_pb_should_set THEN v_pb_resolved  -- 'biblio'/'leitor' ou NULL via __CLEAR__
           ELSE public.reserva_item_workflow_v2.pickup_proposed_by  -- ne pas toucher
         END,
         -- pickup_reply_* : nullifiés ssi p_clear_pickup_reply=true
         pickup_reply_status = CASE
           WHEN p_clear_pickup_reply THEN NULL
           ELSE public.reserva_item_workflow_v2.pickup_reply_status
         END,
         pickup_reply_note = CASE
           WHEN p_clear_pickup_reply THEN NULL
           ELSE public.reserva_item_workflow_v2.pickup_reply_note
         END,
         pickup_reply_at = CASE
           WHEN p_clear_pickup_reply THEN NULL
           ELSE public.reserva_item_workflow_v2.pickup_reply_at
         END,
         updated_at = excluded.updated_at,
         updated_by = excluded.updated_by;

  PERFORM public.fn_v2_refresh_reserva_status_global(p_reserva_id);
  PERFORM public.fn_v2_recompute_from_reserva_lines(p_reserva_id, p_line_nos);

  RETURN v_updated;
END;
$$;


ALTER FUNCTION "public"."fn_v2_set_reserva_linhas_workflow"("p_reserva_id" bigint, "p_line_nos" integer[], "p_workflow_stage" "text", "p_workflow_note" "text", "p_pickup_scheduled_for" timestamp with time zone, "p_pickup_proposed_by" "text", "p_clear_pickup_reply" boolean) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."fn_v2_set_reserva_linhas_workflow"("p_reserva_id" bigint, "p_line_nos" integer[], "p_workflow_stage" "text", "p_workflow_note" "text", "p_pickup_scheduled_for" timestamp with time zone, "p_pickup_proposed_by" "text", "p_clear_pickup_reply" boolean) IS 'Helper de mise à jour atomique du workflow d''une réservation v2.
Refactor paquet6 fix-up 2026-05-09 : 2 nouveaux paramètres optionnels 
(p_pickup_proposed_by, p_clear_pickup_reply) consolident les RPC 
fn_propose_pickup_slot_*, fn_confirm_pickup_slot_* et advance_reservation 
en 1 seul UPDATE. Évite le doublon de webhooks notify-event causé par 
"UPDATE OF pickup_reply_status" qui tirait sur le SET=NULL même quand la 
valeur ne changeait pas.

NB : la signature à 5 args coexiste pour rétrocompatibilité (utilisée par 
api.mark_no_show qui n''a pas besoin des 2 nouveaux paramètres). À 
consolider lors d''un prochain cleanup en harmonisant mark_no_show à 7 args 
puis en DROPant la signature 5-args.';



CREATE OR REPLACE FUNCTION "public"."fn_v2_start_devolucao_emprestimo_interbibliotecas"("p_loan_id" bigint, "p_note" "text" DEFAULT NULL::"text") RETURNS "public"."interlibrary_loans_v2"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_header public.interlibrary_loans_v2;
  v_row public.interlibrary_loans_v2;
begin
  if auth.uid() is null then
    raise exception 'Autenticação obrigatória.';
  end if;

  select *
    into v_header
  from public.interlibrary_loans_v2
  where id = p_loan_id;

  if v_header.id is null then
    raise exception 'Empréstimo interbibliotecas não encontrado: %', p_loan_id;
  end if;

  if not public.user_can_manage_library(v_header.lender_library_id)
     and not public.user_can_manage_library(v_header.borrower_library_id) then
    raise exception 'Sem permissão para iniciar a devolução deste empréstimo.';
  end if;

  if v_header.status_global not in ('emprestado', 'parcialmente_devolvido', 'atrasado') then
    raise exception 'O empréstimo precisa estar em circulação para iniciar devolução.';
  end if;

  update public.interlibrary_loans_v2 h
     set status_global = 'em_devolucao',
         return_started_at = coalesce(h.return_started_at, timezone('utc', now())),
         notes = coalesce(nullif(trim(coalesce(p_note, '')), ''), h.notes),
         updated_at = timezone('utc', now()),
         updated_by = auth.uid()
   where h.id = p_loan_id
  returning * into v_row;

  perform public.fn_v2_log_emprestimo_interbibliotecas_event(
    p_loan_id := p_loan_id,
    p_item_id := null,
    p_event_type := 'return_started',
    p_event_note := 'Processo de devolução iniciado.',
    p_payload := jsonb_build_object(
      'status_global', v_row.status_global
    )
  );

  perform public.fn_v2_refresh_emprestimo_interbibliotecas_status_global(p_loan_id);

  select *
    into v_row
  from public.interlibrary_loans_v2
  where id = p_loan_id;

  return v_row;
end;
$$;


ALTER FUNCTION "public"."fn_v2_start_devolucao_emprestimo_interbibliotecas"("p_loan_id" bigint, "p_note" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_validate_acquisition_mode"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF NEW.acquisition_mode IS NOT NULL
     AND NOT EXISTS (
       SELECT 1 FROM public.catalog_ref_acquisition_modes
       WHERE code = NEW.acquisition_mode AND is_active
     ) THEN
    RAISE EXCEPTION 'acquisition_mode % inconnu ou inactif', NEW.acquisition_mode
      USING errcode = 'P0001';
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."fn_validate_acquisition_mode"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_validate_consulta_schedule_window"("p_library_id" "uuid", "p_consulta_id" bigint, "p_consultation_starts_at" timestamp with time zone, "p_consultation_ends_at" timestamp with time zone) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_timezone text := 'America/Belem';
  v_capacity integer := 1;
  v_schedule jsonb := '{}'::jsonb;
  v_day_key text;
  v_day_cfg jsonb := '{}'::jsonb;
  v_local_start timestamp;
  v_local_end timestamp;
  v_local_start_time time;
  v_local_end_time time;
  v_open_time time;
  v_close_time time;
  v_pause_start time;
  v_pause_end time;
  v_overlap_count integer := 0;
  v_duration_seconds numeric;
begin
  if p_library_id is null then
    raise exception 'Biblioteca da consulta local não identificada.';
  end if;

  if p_consultation_starts_at is null or p_consultation_ends_at is null then
    raise exception 'Informe início e fim da consulta.';
  end if;

  if p_consultation_ends_at <= p_consultation_starts_at then
    raise exception 'A hora de fim da consulta deve ser posterior à hora de início.';
  end if;

  select
    coalesce(nullif(btrim(s.consultation_timezone), ''), 'America/Belem'),
    greatest(coalesce(s.max_simultaneous_consultations, 1), 1),
    coalesce(s.consultation_schedule_struct, '{}'::jsonb)
  into
    v_timezone,
    v_capacity,
    v_schedule
  from public.library_service_state s
  where s.library_id = p_library_id;

  v_local_start := p_consultation_starts_at at time zone v_timezone;
  v_local_end := p_consultation_ends_at at time zone v_timezone;

  if v_local_start::date <> v_local_end::date then
    raise exception 'A consulta deve começar e terminar no mesmo dia da biblioteca.';
  end if;

  v_local_start_time := v_local_start::time;
  v_local_end_time := v_local_end::time;

  if extract(minute from v_local_start_time) not in (0, 30)
     or extract(minute from v_local_end_time) not in (0, 30) then
    raise exception 'Só são aceitas horas cheias ou meias-horas cheias para consulta local.';
  end if;

  v_duration_seconds := extract(epoch from (p_consultation_ends_at - p_consultation_starts_at));
  if v_duration_seconds < 3600
     or v_duration_seconds > 14400
     or mod(v_duration_seconds::bigint, 3600) <> 0 then
    raise exception 'A duração da consulta deve ser de 1h, 2h, 3h ou 4h.';
  end if;

  v_day_key := case extract(isodow from v_local_start)
    when 1 then 'monday'
    when 2 then 'tuesday'
    when 3 then 'wednesday'
    when 4 then 'thursday'
    when 5 then 'friday'
    when 6 then 'saturday'
    else 'sunday'
  end;

  v_day_cfg := coalesce(v_schedule -> v_day_key, '{}'::jsonb);

  if coalesce((v_day_cfg ->> 'enabled')::boolean, false) is not true then
    raise exception 'A biblioteca não definiu atendimento estruturado de consulta para este dia.';
  end if;

  if nullif(btrim(v_day_cfg ->> 'open'), '') is null
     or nullif(btrim(v_day_cfg ->> 'close'), '') is null then
    raise exception 'Faltam horários estruturados de abertura/fechamento para este dia.';
  end if;

  v_open_time := (v_day_cfg ->> 'open')::time;
  v_close_time := (v_day_cfg ->> 'close')::time;

  if v_local_start_time < v_open_time or v_local_end_time > v_close_time then
    raise exception 'O horário escolhido fica fora da janela estruturada da biblioteca.';
  end if;

  if nullif(btrim(v_day_cfg ->> 'pause_start'), '') is not null
     and nullif(btrim(v_day_cfg ->> 'pause_end'), '') is not null then
    v_pause_start := (v_day_cfg ->> 'pause_start')::time;
    v_pause_end := (v_day_cfg ->> 'pause_end')::time;
    if v_local_start_time < v_pause_end and v_local_end_time > v_pause_start then
      raise exception 'O horário escolhido invade a pausa estruturada da biblioteca.';
    end if;
  end if;

  select count(*)::integer
  into v_overlap_count
  from (
    select distinct w.consulta_id
    from public.consulta_item_workflow_v2 w
    join public.consultas_locais_v2 c
      on c.id = w.consulta_id
    join public.consulta_linhas_v2 cl
      on cl.consulta_id = w.consulta_id
     and cl.line_no = w.line_no
    where c.library_id = p_library_id
      and cl.item_status = 'ativa'
      and w.workflow_stage = 'consulta_agendada'
      and w.consultation_starts_at is not null
      and w.consultation_ends_at is not null
      and coalesce(w.schedule_reply_status, 'pendente') <> 'recusado_leitor'
      and w.consulta_id <> coalesce(p_consulta_id, -1)
      and tstzrange(w.consultation_starts_at, w.consultation_ends_at, '[)')
          && tstzrange(p_consultation_starts_at, p_consultation_ends_at, '[)')
  ) overlapping_consultas;

  if v_overlap_count >= v_capacity then
    raise exception 'A capacidade máxima de consulta simultânea já foi atingida para este horário.';
  end if;
end;
$$;


ALTER FUNCTION "public"."fn_validate_consulta_schedule_window"("p_library_id" "uuid", "p_consulta_id" bigint, "p_consultation_starts_at" timestamp with time zone, "p_consultation_ends_at" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_vote_library_profile_change"("p_proposal_id" "uuid", "p_vote" "text", "p_rationale_against" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_caller_id         uuid := auth.uid();
  v_proposal          public.library_profile_proposals%ROWTYPE;
  v_vote_id           uuid;
  v_votes_for         int;
  v_votes_against     int;
  v_active_staff      int;
  v_votes_needed      int;
  v_new_status        text;
  v_grace_until       timestamptz;
  v_grace_days        int;
  v_grace_lock_id     uuid;
  v_closed_in_this_tx boolean := false;
BEGIN
  -- ===== Garde-fou 1 : authentification =====
  IF v_caller_id IS NULL THEN
    RAISE EXCEPTION 'VOTE_AUTH_REQUIRED : authentification requise'
      USING ERRCODE = 'insufficient_privilege',
            HINT    = 'error.profile_change.auth_required';
  END IF;

  -- ===== Garde-fou 2 : validation du parametre vote =====
  IF p_vote NOT IN ('for', 'against') THEN
    RAISE EXCEPTION 'VOTE_INVALID_VALUE : vote doit etre for ou against, recu (%)', p_vote
      USING ERRCODE = 'check_violation',
            HINT    = 'error.profile_change.vote_invalid';
  END IF;

  -- ===== Lecture proposal avec lock pour cloture atomique =====
  SELECT * INTO v_proposal
  FROM public.library_profile_proposals
  WHERE id = p_proposal_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'VOTE_PROPOSAL_NOT_FOUND : proposition introuvable (%)', p_proposal_id
      USING ERRCODE = 'no_data_found',
            HINT    = 'error.profile_change.proposal_not_found';
  END IF;

  -- ===== Garde-fou 3 : proposal status='open' =====
  IF v_proposal.status <> 'open' THEN
    RAISE EXCEPTION 'VOTE_PROPOSAL_NOT_OPEN : la proposition n''est pas ouverte au vote (status=%)', v_proposal.status
      USING ERRCODE = 'invalid_parameter_value',
            HINT    = 'error.profile_change.proposal_not_open';
  END IF;

  -- ===== Garde-fou 4 : proposal pas expiree =====
  IF v_proposal.expires_at <= now() THEN
    RAISE EXCEPTION 'VOTE_PROPOSAL_EXPIRED : la proposition a expire le %', v_proposal.expires_at
      USING ERRCODE = 'invalid_parameter_value',
            HINT    = 'error.profile_change.proposal_expired';
  END IF;

  -- ===== Garde-fou 5 : caller est staff actif de la biblio =====
  IF NOT EXISTS (
    SELECT 1 FROM public.user_library_memberships
    WHERE library_id = v_proposal.library_id
      AND user_id    = v_caller_id
      AND status     = 'active'
      AND role IN ('librarian', 'coordenador')
  ) THEN
    RAISE EXCEPTION 'VOTE_NOT_STAFF : caller n''est pas staff actif de la biblio'
      USING ERRCODE = 'insufficient_privilege',
            HINT    = 'error.profile_change.not_staff';
  END IF;

  -- ===== Garde-fou 6 : rationale obligatoire si against (>= 20 chars) =====
  IF p_vote = 'against' THEN
    IF p_rationale_against IS NULL OR length(trim(p_rationale_against)) < 20 THEN
      RAISE EXCEPTION 'VOTE_RATIONALE_REQUIRED : rationale_against >= 20 caracteres obligatoire pour vote against'
        USING ERRCODE = 'check_violation',
              HINT    = 'error.profile_change.rationale_required';
    END IF;
  END IF;

  -- ===== INSERT vote (CHECK unique en B.1 garantit unicite caller/proposal) =====
  BEGIN
    INSERT INTO public.library_profile_votes (
      proposal_id, voter_id, vote, rationale_against
    )
    VALUES (
      p_proposal_id, v_caller_id, p_vote,
      CASE WHEN p_vote = 'against' THEN trim(p_rationale_against) ELSE NULL END
    )
    RETURNING id INTO v_vote_id;
  EXCEPTION WHEN unique_violation THEN
    RAISE EXCEPTION 'VOTE_ALREADY_CAST : vous avez deja vote sur cette proposition'
      USING ERRCODE = 'unique_violation',
            HINT    = 'error.profile_change.vote_already_cast';
  END;

  -- ===== Recalcul votes apres insertion =====
  SELECT
    count(*) FILTER (WHERE vote = 'for'),
    count(*) FILTER (WHERE vote = 'against')
  INTO v_votes_for, v_votes_against
  FROM public.library_profile_votes
  WHERE proposal_id = p_proposal_id;

  v_active_staff := public.fn_library_active_staff_count(v_proposal.library_id);

  -- ===== Tentative de cloture (doctrine D3 : hybride) =====
  -- Si la condition de gouvernance est atteinte, on bascule status + grace_lock dans cette tx
  v_new_status := NULL;

  IF v_proposal.governance_required = 'majority' THEN
    v_votes_needed := (v_active_staff / 2) + 1;
    -- Acceptation majorite : plus de votants 'for' que 'against' ET au moins votes_needed 'for'
    IF v_votes_for >= v_votes_needed THEN
      v_new_status := 'accepted_majority';
    -- Rejet : impossible d'atteindre la majorite meme si tous les staff restants votent for
    ELSIF (v_votes_for + (v_active_staff - v_votes_for - v_votes_against)) < v_votes_needed THEN
      v_new_status := 'rejected';
    END IF;

  ELSIF v_proposal.governance_required = 'unanimous' THEN
    -- Unanime : tous les staff ont vote ET tous 'for'
    IF v_votes_against > 0 THEN
      v_new_status := 'rejected';   -- un seul against = unanimite rompue
    ELSIF v_votes_for = v_active_staff THEN
      v_new_status := 'accepted_unanimous';
    END IF;
  END IF;

  -- ===== Si cloture decide : UPDATE proposal + grace_lock =====
  IF v_new_status IS NOT NULL THEN
    -- Calcul carence selon type
    v_grace_days := CASE v_proposal.governance_required
      WHEN 'majority'  THEN 0   -- pas de carence en majority
      WHEN 'unanimous' THEN 7   -- 7 jours
    END;

    v_grace_until := now() + (v_grace_days || ' days')::interval;

    -- UPDATE proposal status + horodatage selon decision
    IF v_new_status = 'accepted_majority' THEN
      UPDATE public.library_profile_proposals
      SET status             = v_new_status,
          majority_at        = now(),
          grace_period_until = v_grace_until
      WHERE id = p_proposal_id;

    ELSIF v_new_status = 'accepted_unanimous' THEN
      UPDATE public.library_profile_proposals
      SET status             = v_new_status,
          unanimous_at       = now(),
          grace_period_until = v_grace_until
      WHERE id = p_proposal_id;

    ELSIF v_new_status = 'rejected' THEN
      UPDATE public.library_profile_proposals
      SET status = v_new_status
      WHERE id = p_proposal_id;
    END IF;

    -- Si acceptation : creer grace_lock (les jobs cron skip cette biblio pendant carence)
    IF v_new_status IN ('accepted_majority', 'accepted_unanimous') THEN
      INSERT INTO public.library_profile_grace_locks (
        library_id, proposal_id, affected_axis, affected_jobs, grace_until
      )
      VALUES (
        v_proposal.library_id, p_proposal_id, v_proposal.axis,
        -- Jobs affectes : a affiner selon axe. Pour B.3, on liste les jobs cron
        -- pertinents (B.4 les definira concretement). Mettre 'all' par defaut.
        ARRAY['all_profile_jobs']::text[],
        v_grace_until
      )
      RETURNING id INTO v_grace_lock_id;
    END IF;

    v_closed_in_this_tx := true;
  END IF;

  -- ===== Retour riche =====
  RETURN jsonb_build_object(
    'vote_id',           v_vote_id,
    'proposal_id',       p_proposal_id,
    'votes_for',         v_votes_for,
    'votes_against',     v_votes_against,
    'active_staff_count', v_active_staff,
    'proposal_status',   COALESCE(v_new_status, v_proposal.status),
    'closed_in_this_tx', v_closed_in_this_tx,
    'grace_period_until', v_grace_until,
    'grace_lock_id',     v_grace_lock_id
  );
END;
$$;


ALTER FUNCTION "public"."fn_vote_library_profile_change"("p_proposal_id" "uuid", "p_vote" "text", "p_rationale_against" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."fn_vote_library_profile_change"("p_proposal_id" "uuid", "p_vote" "text", "p_rationale_against" "text") IS 'B.3 RPC : pose un vote sur une proposition ouverte et tente la cloture atomique si quorum atteint (doctrine D3 hybride). FOR UPDATE pour serialiser les votes concurrents.';



CREATE OR REPLACE FUNCTION "public"."generate_public_id"() RETURNS "text"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_id text;
begin
  loop
    -- 10 bytes = 20 hex chars
    v_id := lower(encode(gen_random_bytes(10), 'hex'));
    exit when not exists (
      select 1 from public.profiles where public_id = v_id
    );
  end loop;
  return v_id;
end;
$$;


ALTER FUNCTION "public"."generate_public_id"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_accessible_digital_asset_by_id_v2"("p_asset_id" bigint) RETURNS TABLE("asset_id" bigint, "book_id" bigint, "resource_type" "text", "usage_type" "text", "access_scope" "text", "mime_type" "text", "storage_bucket" "text", "storage_path" "text", "language_code" "text", "source_name" "text", "source_url" "text", "attribution_text" "text", "rights_status" "text", "label" "text", "is_primary" boolean, "requires_active_account" boolean, "access_granted" boolean)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  SELECT
    r.id AS asset_id,
    r.book_id,
    r.resource_type,
    r.usage_type,
    r.access_scope,
    r.mime_type,
    r.storage_bucket,
    r.storage_path,
    r.language_code,
    r.source_name,
    r.source_url,
    r.attribution_text,
    r.rights_status,
    r.label,
    r.is_primary,
    (r.access_scope = 'conta_ativa') AS requires_active_account,
    CASE
      WHEN r.access_scope = 'publico' THEN true
      WHEN r.access_scope = 'conta_ativa' THEN public.fn_current_user_conta_ativa()
      ELSE false
    END AS access_granted
  FROM public.book_digital_resources r
  WHERE r.id = p_asset_id
    AND r.status = 'active'
    AND COALESCE(r.is_active, false) = true
    AND (
      r.access_scope = 'publico'
      OR (r.access_scope = 'conta_ativa' AND public.fn_current_user_conta_ativa())
    )
    AND EXISTS (
      SELECT 1
      FROM public.book_holdings h
      WHERE h.book_id = r.book_id
        AND public.fn_library_visible_to_caller(h.library_id)
    )
  LIMIT 1;
$$;


ALTER FUNCTION "public"."get_accessible_digital_asset_by_id_v2"("p_asset_id" bigint) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_accessible_digital_asset_by_id_v2"("p_asset_id" bigint) IS 'AnarBib V3: retourne un actif numérique publié accessible pour l usager courant, public ou conta_ativa, quel que soit le type de ressource.';



CREATE OR REPLACE FUNCTION "public"."get_book_contributors_public"("p_book_id" bigint) RETURNS TABLE("position" integer, "name" "text", "role" "text", "is_primary" boolean, "author_id" bigint)
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
  SELECT bc.position, bc.name, bc.role, bc.is_primary, bc.author_id
  FROM public.book_contributors bc
  WHERE bc.book_id = p_book_id
    -- uniquement pour un livre reellement publie (table books)
    AND EXISTS (SELECT 1 FROM public.books b WHERE b.id = bc.book_id)
  ORDER BY bc.position, bc.id;
$$;


