CREATE OR REPLACE FUNCTION "public"."get_book_primary_accessible_digital_asset_v2"("p_book_id" bigint) RETURNS TABLE("asset_id" bigint, "book_id" bigint, "resource_type" "text", "usage_type" "text", "access_scope" "text", "mime_type" "text", "storage_bucket" "text", "storage_path" "text", "language_code" "text", "source_name" "text", "source_url" "text", "attribution_text" "text", "rights_status" "text", "label" "text", "is_primary" boolean, "requires_active_account" boolean, "access_granted" boolean)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  WITH ranked AS (
    SELECT
      r.id AS asset_id,
      r.book_id,
      r.resource_type,
      r.usage_type,
      r.access_scope,
      r.mime_type,
      r.storage_bucket,
      r.storage_path,
      r.language_code,
      r.source_name,
      r.source_url,
      r.attribution_text,
      r.rights_status,
      r.label,
      r.is_primary,
      (r.access_scope = 'conta_ativa') AS requires_active_account,
      CASE
        WHEN r.access_scope = 'publico' THEN true
        WHEN r.access_scope = 'conta_ativa' THEN public.fn_current_user_conta_ativa()
        ELSE false
      END AS access_granted,
      row_number() OVER (
        ORDER BY
          CASE WHEN r.access_scope = 'publico' THEN 0 ELSE 1 END,
          CASE WHEN COALESCE(r.is_primary, false) THEN 0 ELSE 1 END,
          r.updated_at DESC NULLS LAST,
          r.id DESC
      ) AS rn
    FROM public.book_digital_resources r
    WHERE r.book_id = p_book_id
      AND r.status = 'active'
      AND COALESCE(r.is_active, false) = true
      AND (
        r.access_scope = 'publico'
        OR (r.access_scope = 'conta_ativa' AND public.fn_current_user_conta_ativa())
      )
      AND EXISTS (
        SELECT 1
        FROM public.book_holdings h
        WHERE h.book_id = r.book_id
          AND public.fn_library_visible_to_caller(h.library_id)
      )
  )
  SELECT
    asset_id, book_id, resource_type, usage_type, access_scope, mime_type,
    storage_bucket, storage_path, language_code, source_name, source_url,
    attribution_text, rights_status, label, is_primary,
    requires_active_account, access_granted
  FROM ranked
  WHERE rn = 1;
$$;


ALTER FUNCTION "public"."get_book_primary_accessible_digital_asset_v2"("p_book_id" bigint) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_book_primary_accessible_digital_asset_v2"("p_book_id" bigint) IS 'AnarBib V3: retourne le principal actif numérique accessible pour l usager courant, public ou conta_ativa, quel que soit le type de ressource.';



CREATE OR REPLACE FUNCTION "public"."get_book_primary_public_digital_asset_v2"("p_book_id" bigint) RETURNS TABLE("asset_id" bigint, "book_id" bigint, "resource_type" "text", "usage_type" "text", "access_scope" "text", "mime_type" "text", "storage_bucket" "text", "storage_path" "text", "language_code" "text", "source_name" "text", "source_url" "text", "attribution_text" "text", "rights_status" "text", "label" "text", "is_primary" boolean)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  with caller_context as (
    select 
      auth.uid() as caller_uid,
      auth.uid() is null as is_anon
  )
  select
    r.id as asset_id,
    r.book_id,
    r.resource_type,
    r.usage_type,
    r.access_scope,
    r.mime_type,
    r.storage_bucket,
    r.storage_path,
    r.language_code,
    r.source_name,
    r.source_url,
    r.attribution_text,
    r.rights_status,
    r.label,
    r.is_primary
  from public.book_digital_resources r
  cross join caller_context cc
  where r.book_id = p_book_id
    and r.is_active = true
    and r.status = 'active'
    and r.access_scope = 'publico'
    and coalesce(r.bibliographic_match_validated, false) = true
    and exists (
      select 1
      from public.book_holdings h
      join public.libraries l on l.id = h.library_id
      where h.book_id = r.book_id
        and l.is_active = true
        and (
          l.visibility_level = 'public'
          or (
            l.visibility_level = 'network'
            and not cc.is_anon
            and exists (
              select 1
              from public.user_library_memberships ulm
              where ulm.user_id = cc.caller_uid
                and ulm.status = 'active'
            )
          )
          or (
            l.visibility_level = 'private'
            and not cc.is_anon
            and exists (
              select 1
              from public.user_library_memberships ulm
              where ulm.user_id = cc.caller_uid
                and ulm.library_id = l.id
                and ulm.status = 'active'
            )
          )
        )
    )
  order by
    case when coalesce(r.is_primary, false) then 0 else 1 end,
    coalesce(r.updated_at, r.created_at) desc,
    r.id desc
  limit 1
$$;


ALTER FUNCTION "public"."get_book_primary_public_digital_asset_v2"("p_book_id" bigint) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_book_primary_public_digital_asset_v2"("p_book_id" bigint) IS 'Asset numérique public d''un livre. EXECUTE anon explicite depuis paquet L.5 (2026-05-12). Filtrage par access_scope dans la fonction.';



CREATE OR REPLACE FUNCTION "public"."resolve_library_holding_bridge"("p_library_id" "uuid", "p_ref" "text") RETURNS TABLE("holding_id" bigint, "book_id" bigint, "local_bib_ref" "text", "book_bib_ref" "text", "resolved_bib_ref" "text", "match_kind" "text")
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_ref text := nullif(btrim(p_ref), '');
  v_holding_id bigint;
  v_book_id bigint;
  v_local_bib_ref text;
  v_book_bib_ref text;
  v_match_kind text;
  v_book_match_count integer := 0;
begin
  if p_library_id is null or v_ref is null then
    return;
  end if;

  select
    h.id,
    h.book_id,
    coalesce(nullif(trim(h.local_bib_ref), ''), b.bib_ref) as local_bib_ref,
    b.bib_ref as book_bib_ref,
    'holding_local_bib_ref_exact'::text as match_kind
  into
    v_holding_id,
    v_book_id,
    v_local_bib_ref,
    v_book_bib_ref,
    v_match_kind
  from public.book_holdings h
  join public.books b
    on b.id = h.book_id
  where h.library_id = p_library_id
    and trim(coalesce(h.local_bib_ref, '')) = v_ref
  order by h.id
  limit 1;

  if found then
    return query
    select
      v_holding_id,
      v_book_id,
      v_local_bib_ref,
      v_book_bib_ref,
      coalesce(v_local_bib_ref, v_book_bib_ref, v_ref),
      v_match_kind;
    return;
  end if;

  select count(*)::integer
    into v_book_match_count
  from public.book_holdings h
  join public.books b
    on b.id = h.book_id
  where h.library_id = p_library_id
    and trim(coalesce(b.bib_ref, '')) = v_ref;

  if v_book_match_count > 1 then
    raise exception 'Referência % ambígua na biblioteca %: mais de um holding ativo usa o mesmo bib_ref comum.', v_ref, p_library_id;
  end if;

  select
    h.id,
    h.book_id,
    coalesce(nullif(trim(h.local_bib_ref), ''), b.bib_ref) as local_bib_ref,
    b.bib_ref as book_bib_ref,
    'book_bib_ref_unique_in_library'::text as match_kind
  into
    v_holding_id,
    v_book_id,
    v_local_bib_ref,
    v_book_bib_ref,
    v_match_kind
  from public.book_holdings h
  join public.books b
    on b.id = h.book_id
  where h.library_id = p_library_id
    and trim(coalesce(b.bib_ref, '')) = v_ref
  order by h.id
  limit 1;

  if found then
    return query
    select
      v_holding_id,
      v_book_id,
      v_local_bib_ref,
      v_book_bib_ref,
      coalesce(v_local_bib_ref, v_book_bib_ref, v_ref),
      v_match_kind;
  end if;

  return;
end;
$$;


