CREATE OR REPLACE VIEW "public"."v_exemplar_labels" WITH ("security_invoker"='true') AS
 WITH "resolved_exemplares" AS (
         SELECT "e"."id" AS "exemplar_id",
            "e"."bib_ref" AS "legacy_bib_ref",
            "e"."tombo",
            "e"."label_author_override",
            "e"."label_title_override",
            "e"."label_cdd_override",
            "e"."label_note",
            "e"."shelf_location",
            "e"."notes",
            "e"."library_id",
            "e"."created_at",
            "e"."updated_at",
            COALESCE("e"."holding_id", "rb"."holding_id") AS "holding_id",
            COALESCE("h"."book_id", "rb"."book_id", "b_legacy"."id") AS "book_id",
            COALESCE(NULLIF(TRIM(BOTH FROM "h"."local_bib_ref"), ''::"text"), "rb"."local_bib_ref", "b_legacy"."bib_ref", "e"."bib_ref") AS "local_bib_ref",
            COALESCE("b_holding"."bib_ref", "rb"."book_bib_ref", "b_legacy"."bib_ref", "e"."bib_ref") AS "book_bib_ref",
            COALESCE("rb"."resolved_bib_ref", NULLIF(TRIM(BOTH FROM "h"."local_bib_ref"), ''::"text"), "b_holding"."bib_ref", "b_legacy"."bib_ref", "e"."bib_ref") AS "resolved_bib_ref",
                CASE
                    WHEN ("e"."holding_id" IS NOT NULL) THEN 'holding_id'::"text"
                    WHEN ("rb"."holding_id" IS NOT NULL) THEN "rb"."match_kind"
                    WHEN ("b_legacy"."id" IS NOT NULL) THEN 'legacy_book_bib_ref'::"text"
                    ELSE 'unresolved'::"text"
                END AS "bridge_source",
            COALESCE("b_holding"."autor", "b_bridge"."autor", "b_legacy"."autor", ''::"text") AS "autor_base",
            COALESCE("b_holding"."titulo", "b_bridge"."titulo", "b_legacy"."titulo", ''::"text") AS "titulo_base",
            COALESCE("b_holding"."cdd", "b_bridge"."cdd", "b_legacy"."cdd", ''::"text") AS "cdd_base"
           FROM ((((("public"."exemplares" "e"
             LEFT JOIN "public"."book_holdings" "h" ON (("h"."id" = "e"."holding_id")))
             LEFT JOIN "public"."books" "b_holding" ON (("b_holding"."id" = "h"."book_id")))
             LEFT JOIN LATERAL "public"."resolve_library_holding_bridge"("e"."library_id", "e"."bib_ref") "rb"("holding_id", "book_id", "local_bib_ref", "book_bib_ref", "resolved_bib_ref", "match_kind") ON (("e"."holding_id" IS NULL)))
             LEFT JOIN "public"."books" "b_bridge" ON (("b_bridge"."id" = "rb"."book_id")))
             LEFT JOIN "public"."books" "b_legacy" ON ((("e"."holding_id" IS NULL) AND ("rb"."holding_id" IS NULL) AND ("b_legacy"."bib_ref" = "e"."bib_ref"))))
        )
 SELECT "exemplar_id",
    "legacy_bib_ref" AS "bib_ref",
    "tombo",
    COALESCE(NULLIF("label_author_override", ''::"text"), "autor_base", ''::"text") AS "autor_etiqueta",
    COALESCE(NULLIF("label_title_override", ''::"text"), "titulo_base", ''::"text") AS "titulo_etiqueta",
    COALESCE(NULLIF("label_cdd_override", ''::"text"), "cdd_base", ''::"text") AS "cdd_etiqueta",
    "label_note",
    "shelf_location",
    "notes",
    "library_id",
    "created_at",
    "updated_at",
    "holding_id",
    "book_id",
    "local_bib_ref",
    "book_bib_ref",
    "resolved_bib_ref",
    "bridge_source"
   FROM "resolved_exemplares" "re";


ALTER VIEW "public"."v_exemplar_labels" OWNER TO "postgres";


COMMENT ON VIEW "public"."v_exemplar_labels" IS 'Passe 42 backend phase 1: vue de rótulos holdings-first. bib_ref reste un cache de compatibilité; les libellés se résolvent désormais d abord via holding_id puis via la couche book_holdings locale.';



CREATE OR REPLACE FUNCTION "public"."get_exemplar_labels"("p_library_id" "uuid") RETURNS SETOF "public"."v_exemplar_labels"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
BEGIN
  -- Gate : staff (librarian/coordenador/administrador) de la bibliotheque ciblee
  IF p_library_id IS NULL
     OR NOT public.user_has_library_staff_role(auth.uid(), p_library_id) THEN
    RAISE EXCEPTION 'Acesso restrito ao staff da biblioteca.';
  END IF;

  RETURN QUERY
    SELECT v.*
    FROM public.v_exemplar_labels v
    WHERE v.library_id = p_library_id
    ORDER BY v.exemplar_id DESC;
END;
$$;


