CREATE OR REPLACE FUNCTION "public"."get_library_notification_context"("p_library_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_row public.v_library_notification_context%rowtype;
begin
  if p_library_id is null then
    raise exception 'library_id ausente';
  end if;

  if not public.user_can_manage_library_notifications(p_library_id) then
    raise exception 'Sem permissão para ler notificações desta biblioteca';
  end if;

  select *
    into v_row
  from public.v_library_notification_context
  where library_id = p_library_id;

  return to_jsonb(v_row);
end;
$$;


