CREATE OR REPLACE FUNCTION "public"."get_library_theme_config"("p_library_slug" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  select coalesce(
    (
      select jsonb_build_object(
        'library_slug', c.library_slug,
        'background_url', c.background_url,
        'palette_preset', c.palette_preset,
        'font_pack', c.font_pack,
        'updated_at', c.updated_at
      )
      from public.library_theme_configs c
      where c.library_slug = coalesce(nullif(lower(trim(p_library_slug)), ''), 'default')
    ),
    jsonb_build_object(
      'library_slug', coalesce(nullif(lower(trim(p_library_slug)), ''), 'default'),
      'background_url', null,
      'palette_preset', 'default',
      'font_pack', 'default'
    )
  );
$$;


