CREATE OR REPLACE FUNCTION "public"."handle_auth_user_created_profile"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
begin
  insert into public.profiles (
    id,
    email,
    first_name,
    last_name,
    is_restricted,
    must_change_password,
    preferred_language
  )
  values (
    new.id,
    nullif(btrim(new.email), ''),
    nullif(btrim(coalesce(new.raw_user_meta_data ->> 'first_name', '')), ''),
    nullif(btrim(coalesce(new.raw_user_meta_data ->> 'last_name', '')), ''),
    false,
    false,
    nullif(btrim(coalesce(new.raw_user_meta_data ->> 'preferred_language', 'pt-BR')), '')
  )
  on conflict (id) do update
    set email = coalesce(nullif(btrim(public.profiles.email), ''), excluded.email),
        first_name = coalesce(nullif(btrim(public.profiles.first_name), ''), excluded.first_name),
        last_name = coalesce(nullif(btrim(public.profiles.last_name), ''), excluded.last_name),
        preferred_language = coalesce(nullif(btrim(public.profiles.preferred_language), ''), excluded.preferred_language);

  return new;
end;
$$;


