CREATE OR REPLACE FUNCTION "public"."merge_author"("p_canonical_id" bigint, "p_duplicate_id" bigint) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_dup_name text;
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM public.user_library_memberships m
    WHERE m.user_id = auth.uid()
      AND m.role = ANY (ARRAY['librarian'::text, 'coordenador'::text])
  ) THEN
    RAISE EXCEPTION 'Acesso restrito ao staff de catalogacao.';
  END IF;

  IF p_canonical_id = p_duplicate_id THEN
    RAISE EXCEPTION 'Canonico e duplicado identicos.';
  END IF;
  SELECT preferred_name INTO v_dup_name FROM public.authors WHERE id = p_duplicate_id;
  IF v_dup_name IS NULL THEN
    RAISE EXCEPTION 'Duplicado % inexistente.', p_duplicate_id;
  END IF;
  IF NOT EXISTS (SELECT 1 FROM public.authors WHERE id = p_canonical_id) THEN
    RAISE EXCEPTION 'Canonico % inexistente.', p_canonical_id;
  END IF;

  -- 1. Contributeurs : repoint (le trigger propage book_authors).
  UPDATE public.book_contributors SET author_id = p_canonical_id WHERE author_id = p_duplicate_id;

  -- 2. book_authors restants (liens legacy sans contributeur) : repoint + dedupe.
  INSERT INTO public.book_authors (book_id, author_id, role, ord)
    SELECT book_id, p_canonical_id, role, ord FROM public.book_authors WHERE author_id = p_duplicate_id
  ON CONFLICT (book_id, author_id, role, ord) DO NOTHING;
  DELETE FROM public.book_authors WHERE author_id = p_duplicate_id;

  -- 3. Traductions : deplacer les langues absentes du canonique (Q-A1 : on garde
  --    le canonique sur conflit ; les traductions en conflit partent au DELETE).
  UPDATE public.author_translations t SET author_id = p_canonical_id
    WHERE t.author_id = p_duplicate_id
      AND NOT EXISTS (SELECT 1 FROM public.author_translations c
                      WHERE c.author_id = p_canonical_id AND c.lang = t.lang);

  -- 4. Alias de nom : deplacer vers le canonique (formes variantes preservees).
  UPDATE public.author_name_aliases SET author_id = p_canonical_id WHERE author_id = p_duplicate_id;

  -- 5. Brouillons pointant vers le doublon : repoint.
  UPDATE public.author_drafts SET published_author_id = p_canonical_id WHERE published_author_id = p_duplicate_id;

  -- 5b. Contributeurs de brouillons : repoint (FIX — oublie originel).
  --     Unicite sur (draft_id, position), pas sur author_id -> UPDATE direct sur.
  UPDATE public.book_draft_contributors SET author_id = p_canonical_id WHERE author_id = p_duplicate_id;

  -- 6. Journaliser.
  INSERT INTO public.merge_log (entity_type, canonical_id, duplicate_id, details, merged_by)
  VALUES ('author', p_canonical_id, p_duplicate_id,
          jsonb_build_object('duplicate_preferred_name', v_dup_name), auth.uid());

  -- 7. Supprimer le doublon (cascade : traductions restantes en conflit).
  DELETE FROM public.authors WHERE id = p_duplicate_id;
END;
$$;


ALTER FUNCTION "public"."merge_author"("p_canonical_id" bigint, "p_duplicate_id" bigint) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."merge_author"("p_canonical_id" bigint, "p_duplicate_id" bigint) IS 'Fusionne le doublon dans le canonique (reassigne FK + journalise + supprime). Paquet doublons du 05/06/2026.';



CREATE OR REPLACE FUNCTION "public"."merge_book"("p_canonical_id" bigint, "p_duplicate_id" bigint) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_dup_titulo text;
  dh           record;
  v_ch_id      bigint;
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM public.user_library_memberships m
    WHERE m.user_id = auth.uid()
      AND m.role = ANY (ARRAY['librarian'::text, 'coordenador'::text])
  ) THEN
    RAISE EXCEPTION 'Acesso restrito ao staff de catalogacao.';
  END IF;

  IF p_canonical_id = p_duplicate_id THEN
    RAISE EXCEPTION 'Canonico e duplicado identicos.';
  END IF;
  SELECT titulo INTO v_dup_titulo FROM public.books WHERE id = p_duplicate_id;
  IF v_dup_titulo IS NULL THEN
    RAISE EXCEPTION 'Duplicado % inexistente.', p_duplicate_id;
  END IF;
  IF NOT EXISTS (SELECT 1 FROM public.books WHERE id = p_canonical_id) THEN
    RAISE EXCEPTION 'Canonico % inexistente.', p_canonical_id;
  END IF;

  -- 1. Holdings : fusionner (meme bibliotheque) ou repointer.
  FOR dh IN SELECT * FROM public.book_holdings WHERE book_id = p_duplicate_id LOOP
    SELECT id INTO v_ch_id
      FROM public.book_holdings
      WHERE book_id = p_canonical_id AND library_id = dh.library_id
      LIMIT 1;

    IF v_ch_id IS NOT NULL THEN
      -- Fusion : tout ce qui pointe vers le holding doublon bascule sur le canonique.
      UPDATE public.exemplares               SET holding_id = v_ch_id WHERE holding_id = dh.id;
      UPDATE public.emprestimo_itens_v2       SET holding_id = v_ch_id WHERE holding_id = dh.id;
      UPDATE public.reserva_linhas_v2         SET holding_id = v_ch_id WHERE holding_id = dh.id;
      UPDATE public.interlibrary_loan_items_v2 SET holding_id = v_ch_id WHERE holding_id = dh.id;
      UPDATE public.consulta_linhas_v2        SET holding_id = v_ch_id WHERE holding_id = dh.id;
      UPDATE public.exemplar_drafts           SET target_holding_id = v_ch_id WHERE target_holding_id = dh.id;
      DELETE FROM public.book_holdings WHERE id = dh.id;
    ELSE
      -- Repoint : le holding (avec ses exemplaires et refs) bascule sur le canonique.
      UPDATE public.book_holdings SET book_id = p_canonical_id WHERE id = dh.id;
    END IF;
  END LOOP;

  -- 2. Circulation au niveau livre : repoint book_id (caches/FK).
  UPDATE public.emprestimo_itens_v2        SET book_id = p_canonical_id WHERE book_id = p_duplicate_id;
  UPDATE public.reserva_linhas_v2          SET book_id = p_canonical_id WHERE book_id = p_duplicate_id;
  UPDATE public.interlibrary_loan_items_v2 SET book_id = p_canonical_id WHERE book_id = p_duplicate_id;
  UPDATE public.consulta_linhas_v2         SET book_id = p_canonical_id WHERE book_id = p_duplicate_id;

  -- 3. Ressources numeriques.
  UPDATE public.digital_assets SET book_id = p_canonical_id WHERE book_id = p_duplicate_id;

  -- 4. Wishlist : dedupe (UNIQUE user_id,book_id) puis repoint.
  DELETE FROM public.user_wishlist w
    WHERE w.book_id = p_duplicate_id
      AND EXISTS (SELECT 1 FROM public.user_wishlist w2
                  WHERE w2.user_id = w.user_id AND w2.book_id = p_canonical_id);
  UPDATE public.user_wishlist SET book_id = p_canonical_id WHERE book_id = p_duplicate_id;

  -- 5. Brouillons pointant vers le doublon.
  UPDATE public.book_drafts SET published_book_id = p_canonical_id WHERE published_book_id = p_duplicate_id;

  -- 6. Journaliser.
  INSERT INTO public.merge_log (entity_type, canonical_id, duplicate_id, details, merged_by)
  VALUES ('book', p_canonical_id, p_duplicate_id,
          jsonb_build_object('duplicate_titulo', v_dup_titulo), auth.uid());

  -- 7. Supprimer le doublon (cascade : book_authors/contributors/catalog_context).
  DELETE FROM public.books WHERE id = p_duplicate_id;

  -- 8. Recalcul des compteurs de disponibilite du canonique.
  PERFORM public.fn_v2_recompute_holdings_availability(NULL, ARRAY[p_canonical_id]);
END;
$$;


ALTER FUNCTION "public"."merge_book"("p_canonical_id" bigint, "p_duplicate_id" bigint) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."merge_book"("p_canonical_id" bigint, "p_duplicate_id" bigint) IS 'Fusionne le livre doublon dans le canonique (holdings/exemplaires, circulation, wishlist, journalise, supprime). Paquet doublons P2b du 05/06/2026.';



CREATE OR REPLACE FUNCTION "public"."network_admin_reassign_book_from_to_library"("p_book_id" bigint, "p_source_library_id" "uuid", "p_target_library_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_lib_name        text;
  v_lib_mode        text;
  v_book_loanable   boolean;
  v_target_holding  bigint;
  v_source_holdings bigint[];
  v_moved           integer := 0;
  v_affected        bigint[];
BEGIN
  IF NOT public.fn_caller_is_network_admin() THEN
    RAISE EXCEPTION 'Acesso restrito ao administrador de rede.';
  END IF;
  IF p_source_library_id = p_target_library_id THEN
    RAISE EXCEPTION 'Biblioteca de origem e destino são idênticas.';
  END IF;

  SELECT name, catalog_mode INTO v_lib_name, v_lib_mode
  FROM public.libraries WHERE id = p_target_library_id;
  IF v_lib_name IS NULL THEN
    RAISE EXCEPTION 'Biblioteca alvo inexistente: %', p_target_library_id;
  END IF;
  IF v_lib_mode IS DISTINCT FROM 'network_published' THEN
    RAISE EXCEPTION 'A biblioteca alvo não tem catálogo presente na rede.';
  END IF;

  SELECT loanable INTO v_book_loanable FROM public.books WHERE id = p_book_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Notícia inexistente: %', p_book_id;
  END IF;

  -- Holdings de la notice DANS la biblio source.
  SELECT array_agg(id) INTO v_source_holdings
  FROM public.book_holdings
  WHERE book_id = p_book_id AND library_id = p_source_library_id;
  IF v_source_holdings IS NULL THEN
    RAISE EXCEPTION 'A notícia não tem acervo na biblioteca de origem indicada.';
  END IF;

  -- get-or-create du holding cible.
  SELECT id INTO v_target_holding
  FROM public.book_holdings
  WHERE book_id = p_book_id AND library_id = p_target_library_id
  LIMIT 1;
  IF v_target_holding IS NULL THEN
    INSERT INTO public.book_holdings (book_id, library_id, loanable, exemplares_total, available_count)
    VALUES (p_book_id, p_target_library_id, COALESCE(v_book_loanable, true), 0, 0)
    RETURNING id INTO v_target_holding;
  END IF;

  -- Deplacer UNIQUEMENT les exemplaires de la biblio source.
  UPDATE public.exemplares e
  SET holding_id = v_target_holding,
      library_id = p_target_library_id,
      updated_at = now()
  WHERE e.holding_id = ANY(v_source_holdings)
    AND e.holding_id IS DISTINCT FROM v_target_holding;
  GET DIAGNOSTICS v_moved = ROW_COUNT;

  -- owner_library/holder_library volontairement NON modifies (notice partagee).

  v_affected := v_source_holdings || v_target_holding;
  PERFORM public.fn_v2_recompute_holdings_availability(v_affected, ARRAY[p_book_id]);

  PERFORM public.fn_log_cross_library_action(
    p_target_library_id, 'reassign_book_from_to_library', true, 'book', NULL,
    jsonb_build_object('book_id', p_book_id, 'source_library', p_source_library_id, 'target_library', v_lib_name, 'exemplares_moved', v_moved)
  );

  RETURN jsonb_build_object(
    'ok', true,
    'target_library', v_lib_name,
    'source_library', p_source_library_id,
    'exemplares_moved', v_moved,
    'target_holding', v_target_holding
  );
END;
$$;


ALTER FUNCTION "public"."network_admin_reassign_book_from_to_library"("p_book_id" bigint, "p_source_library_id" "uuid", "p_target_library_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."network_admin_reassign_book_to_library"("p_book_id" bigint, "p_target_library_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_lib_name       text;
  v_lib_mode       text;
  v_book_loanable  boolean;
  v_target_holding bigint;
  v_old_holdings   bigint[];
  v_moved          integer := 0;
  v_affected       bigint[];
  v_distinct_libs  integer;
BEGIN
  IF NOT public.fn_caller_is_network_admin() THEN
    RAISE EXCEPTION 'Acesso restrito ao administrador de rede.';
  END IF;

  SELECT name, catalog_mode INTO v_lib_name, v_lib_mode
  FROM public.libraries WHERE id = p_target_library_id;
  IF v_lib_name IS NULL THEN
    RAISE EXCEPTION 'Biblioteca alvo inexistente: %', p_target_library_id;
  END IF;
  IF v_lib_mode IS DISTINCT FROM 'network_published' THEN
    RAISE EXCEPTION 'A biblioteca alvo nao tem catalogo presente na rede.';
  END IF;

  SELECT loanable INTO v_book_loanable FROM public.books WHERE id = p_book_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Noticia inexistente: %', p_book_id;
  END IF;

  -- GARDE-FOU : ne pas rapatrier en masse une notice partagee.
  SELECT count(DISTINCT e.library_id) INTO v_distinct_libs
  FROM public.exemplares e
  JOIN public.book_holdings h ON h.id = e.holding_id
  WHERE h.book_id = p_book_id;
  IF COALESCE(v_distinct_libs, 0) > 1 THEN
    RAISE EXCEPTION 'Esta noticia tem exemplares em % bibliotecas. Reatribuicao global bloqueada: use network_admin_reassign_book_from_to_library.', v_distinct_libs;
  END IF;

  SELECT array_agg(id) INTO v_old_holdings
  FROM public.book_holdings WHERE book_id = p_book_id;

  SELECT id INTO v_target_holding
  FROM public.book_holdings
  WHERE book_id = p_book_id AND library_id = p_target_library_id
  LIMIT 1;
  IF v_target_holding IS NULL THEN
    INSERT INTO public.book_holdings (book_id, library_id, loanable, exemplares_total, available_count)
    VALUES (p_book_id, p_target_library_id, COALESCE(v_book_loanable, true), 0, 0)
    RETURNING id INTO v_target_holding;
  END IF;

  UPDATE public.exemplares e
  SET holding_id = v_target_holding,
      library_id = p_target_library_id,
      updated_at = now()
  WHERE e.holding_id IN (SELECT id FROM public.book_holdings WHERE book_id = p_book_id)
    AND e.holding_id IS DISTINCT FROM v_target_holding;
  GET DIAGNOSTICS v_moved = ROW_COUNT;

  UPDATE public.books
  SET owner_library = v_lib_name,
      holder_library = v_lib_name,
      owner_library_id = p_target_library_id,
      holder_library_id = p_target_library_id,
      updated_at = now()
  WHERE id = p_book_id;

  v_affected := COALESCE(v_old_holdings, ARRAY[]::bigint[]) || v_target_holding;
  PERFORM public.fn_v2_recompute_holdings_availability(v_affected, ARRAY[p_book_id]);

  PERFORM public.fn_log_cross_library_action(
    p_target_library_id, 'reassign_book_to_library', true, 'book', NULL,
    jsonb_build_object('book_id', p_book_id, 'target_library', v_lib_name, 'exemplares_moved', v_moved)
  );

  RETURN jsonb_build_object(
    'ok', true,
    'target_library', v_lib_name,
    'exemplares_moved', v_moved,
    'target_holding', v_target_holding
  );
END;
$$;


ALTER FUNCTION "public"."network_admin_reassign_book_to_library"("p_book_id" bigint, "p_target_library_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."network_admin_reassign_book_to_library"("p_book_id" bigint, "p_target_library_id" "uuid") IS 'Admin réseau : attribue une notice + ses exemplaires à une bibliothèque (transfert complet, journalisé). 06/06/2026.';



CREATE OR REPLACE FUNCTION "public"."next_bib_ref"("p_library_id" "uuid") RETURNS "text"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $_$
DECLARE
  v_prefix text;
  v_pad    int;
  v_auto   boolean;
  v_max    bigint;
BEGIN
  IF NOT public.user_has_library_staff_role(auth.uid(), p_library_id) THEN
    RAISE EXCEPTION 'Acesso restrito ao staff da biblioteca.' USING errcode = '42501';
  END IF;

  SELECT bib_ref_prefix, bib_ref_pad, bib_ref_auto
    INTO v_prefix, v_pad, v_auto
    FROM public.libraries WHERE id = p_library_id;

  IF NOT COALESCE(v_auto, false) THEN
    RETURN NULL;   -- pas de convention active -> rien a suggerer
  END IF;
  v_prefix := COALESCE(v_prefix, '');
  v_pad := GREATEST(COALESCE(v_pad, 1), 1);

  -- Max de la partie numerique des references existantes de la biblio
  -- (local_bib_ref du holding sinon bib_ref de la notice).
  -- Largeur >= pad : exclut les refs courtes hors-convention (ex. l'intrus
  -- "2453" a 4 chiffres ne pollue pas le max BLMF qui est sur 7 chiffres).
  SELECT max((substring(ref FROM ('^' || v_prefix || '([0-9]{' || v_pad || ',})$')))::bigint)
    INTO v_max
  FROM (
    SELECT COALESCE(NULLIF(h.local_bib_ref, ''), b.bib_ref) AS ref
    FROM public.book_holdings h
    JOIN public.books b ON b.id = h.book_id
    WHERE h.library_id = p_library_id
  ) x
  WHERE ref ~ ('^' || v_prefix || '[0-9]{' || v_pad || ',}$');

  RETURN v_prefix || lpad((COALESCE(v_max, 0) + 1)::text, v_pad, '0');
END;
$_$;


ALTER FUNCTION "public"."next_bib_ref"("p_library_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."norm_match_text"("p_text" "text") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
  select nullif(
    regexp_replace(
      lower(
        translate(
          coalesce(p_text, ''),
          'áàâãäåāăąçćčďéèêëēėęíìîïīłñńóòôõöōřŕśšșťúùûüūýÿžźżÁÀÂÃÄÅĀĂĄÇĆČĎÉÈÊËĒĖĘÍÌÎÏĪŁÑŃÓÒÔÕÖŌŘŔŚŠȘŤÚÙÛÜŪÝŸŽŹŻ',
          'aaaaaaaaacccdeeeeeeeiiiiilnnoooooorrssstuuuuuyyzzzAAAAAAAAACCCDEEEEEEEIIIIILNNOOOOOORRSSSTUUUUUYYZZZ'
        )
      ),
      '[^a-z0-9]+',
      '',
      'g'
    ),
    ''
  );
$$;


ALTER FUNCTION "public"."norm_match_text"("p_text" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."normalize_author_alias"("p_text" "text") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
  select regexp_replace(
    translate(lower(trim(coalesce(p_text,''))),
      'àáâãäåçèéêëìíîïñòóôõöùúûüýÿ´`’''"',
      'aaaaaaceeeeiiiinooooouuuuyy     '
    ),
    '[^a-z0-9]+',
    ' ',
    'g'
  );
$$;


