CREATE OR REPLACE FUNCTION "public"."resolve_managed_library_id"("p_library_id" "uuid" DEFAULT NULL::"uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'api', 'auth', 'pg_temp'
    AS $$
declare
  v_library_id uuid;
begin
  if auth.uid() is null then
    raise exception 'authentication required';
  end if;

  if p_library_id is not null then
    if not public.user_can_manage_library(p_library_id) then
      raise exception 'permission denied for library %', p_library_id;
    end if;
    return p_library_id;
  end if;

  select coalesce(a.library_id, a.default_library_id)
    into v_library_id
  from api.my_access a
  limit 1;

  if v_library_id is null then
    raise exception 'Biblioteca ativa não identificada.';
  end if;

  if not public.user_can_manage_library(v_library_id) then
    raise exception 'permission denied for current library %', v_library_id;
  end if;

  return v_library_id;
end;
$$;


