COMMENT ON FUNCTION "public"."resolve_managed_library_id"("p_library_id" "uuid") IS 'Resolve a biblioteca gerida pelo usuário atual. Se library_id vier nulo, tenta a biblioteca efetiva da sessão do painel.';



CREATE OR REPLACE FUNCTION "public"."rls_auto_enable"() RETURNS "event_trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$
DECLARE
  cmd record;
BEGIN
  FOR cmd IN
    SELECT *
    FROM pg_event_trigger_ddl_commands()
    WHERE command_tag IN ('CREATE TABLE', 'CREATE TABLE AS', 'SELECT INTO')
      AND object_type IN ('table','partitioned table')
  LOOP
     IF cmd.schema_name IS NOT NULL AND cmd.schema_name IN ('public') AND cmd.schema_name NOT IN ('pg_catalog','information_schema') AND cmd.schema_name NOT LIKE 'pg_toast%' AND cmd.schema_name NOT LIKE 'pg_temp%' THEN
      BEGIN
        EXECUTE format('alter table if exists %s enable row level security', cmd.object_identity);
        RAISE LOG 'rls_auto_enable: enabled RLS on %', cmd.object_identity;
      EXCEPTION
        WHEN OTHERS THEN
          RAISE LOG 'rls_auto_enable: failed to enable RLS on %', cmd.object_identity;
      END;
     ELSE
        RAISE LOG 'rls_auto_enable: skip % (either system schema or not in enforced list: %.)', cmd.object_identity, cmd.schema_name;
     END IF;
  END LOOP;
END;
$$;


ALTER FUNCTION "public"."rls_auto_enable"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."search_authors_by_name"("p_query" "text", "p_limit" integer DEFAULT 10) RETURNS TABLE("id" bigint, "preferred_name" "text", "sort_name" "text", "birth_year" integer, "death_year" integer, "country" "text", "match_kind" "text", "score" real)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions', 'pg_catalog'
    AS $$
DECLARE
  v_nq   text;
  v_lim  int := least(greatest(coalesce(p_limit, 10), 1), 25);
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM public.user_library_memberships m
    WHERE m.user_id = auth.uid()
      AND m.role = ANY (ARRAY['librarian'::text, 'coordenador'::text])
  ) THEN
    RAISE EXCEPTION 'Acesso restrito ao staff de catalogacao.';
  END IF;

  v_nq := public.fn_normalize_name(p_query);
  IF v_nq = '' THEN
    RETURN;
  END IF;

  RETURN QUERY
  WITH base AS (
    SELECT a.id, a.preferred_name, a.sort_name,
           a.birth_year, a.death_year, a.country,
           public.fn_normalize_name(a.preferred_name) AS np,
           public.fn_normalize_name(a.sort_name)      AS ns
    FROM public.authors a
  ),
  scored AS (
    SELECT b.id, b.preferred_name, b.sort_name, b.birth_year, b.death_year, b.country,
           CASE
             WHEN b.np = v_nq OR b.ns = v_nq THEN 'exact'
             WHEN b.np LIKE v_nq || '%' OR b.ns LIKE v_nq || '%' THEN 'prefix'
             WHEN b.np LIKE '%' || v_nq || '%' OR b.ns LIKE '%' || v_nq || '%' THEN 'substring'
             ELSE 'approx'
           END AS match_kind,
           CASE
             WHEN b.np = v_nq OR b.ns = v_nq THEN 1.0::real
             WHEN b.np LIKE v_nq || '%' OR b.ns LIKE v_nq || '%' THEN 0.9::real
             WHEN b.np LIKE '%' || v_nq || '%' OR b.ns LIKE '%' || v_nq || '%' THEN 0.7::real
             ELSE greatest(similarity(b.np, v_nq), similarity(b.ns, v_nq))
           END AS score
    FROM base b
    WHERE b.np <> ''
      AND ( b.np LIKE '%' || v_nq || '%'
            OR b.ns LIKE '%' || v_nq || '%'
            OR similarity(b.np, v_nq) >= 0.30
            OR similarity(b.ns, v_nq) >= 0.30 )
  )
  SELECT s.id, s.preferred_name, s.sort_name, s.birth_year, s.death_year,
         s.country, s.match_kind, s.score
  FROM scored s
  ORDER BY s.score DESC, s.preferred_name
  LIMIT v_lim;
END;
$$;


ALTER FUNCTION "public"."search_authors_by_name"("p_query" "text", "p_limit" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."search_authors_by_name"("p_query" "text", "p_limit" integer) IS 'Recherche d''autorites locales par nom (exact/prefixe/substring/trigramme) pour le selecteur preventif du form livre. Volet preventif liaison autorites, 05/06/2026.';



CREATE OR REPLACE FUNCTION "public"."search_publishers_by_name"("p_query" "text", "p_limit" integer DEFAULT 10) RETURNS TABLE("id" bigint, "name" "text", "city" "text", "country" "text", "match_kind" "text", "score" real)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions', 'pg_catalog'
    AS $$
DECLARE
  v_nq  text;
  v_lim int := least(greatest(coalesce(p_limit, 10), 1), 25);
BEGIN
  -- Staff-only
  IF NOT EXISTS (
    SELECT 1 FROM public.user_library_memberships m
    WHERE m.user_id = auth.uid()
      AND m.role = ANY (ARRAY['librarian'::text, 'coordenador'::text])
  ) THEN
    RAISE EXCEPTION 'Acesso restrito ao staff de catalogacao.';
  END IF;

  v_nq := public.fn_normalize_name(p_query);
  IF v_nq = '' THEN RETURN; END IF;

  RETURN QUERY
  WITH scored AS (
    SELECT
      pub.id, pub.name, pub.city, pub.country,
      public.fn_normalize_name(pub.name) AS np,
      CASE
        WHEN public.fn_normalize_name(pub.name) = v_nq THEN 'exact'
        WHEN public.fn_normalize_name(pub.name) LIKE v_nq || '%' THEN 'prefix'
        WHEN public.fn_normalize_name(pub.name) LIKE '%' || v_nq || '%' THEN 'substring'
        ELSE 'approx'
      END AS match_kind,
      CASE
        WHEN public.fn_normalize_name(pub.name) = v_nq THEN 1.0::real
        WHEN public.fn_normalize_name(pub.name) LIKE v_nq || '%' THEN 0.9::real
        WHEN public.fn_normalize_name(pub.name) LIKE '%' || v_nq || '%' THEN 0.7::real
        ELSE similarity(public.fn_normalize_name(pub.name), v_nq)
      END AS score
    FROM public.publishers pub
    WHERE public.fn_normalize_name(pub.name) <> ''
      AND (
        public.fn_normalize_name(pub.name) LIKE '%' || v_nq || '%'
        OR similarity(public.fn_normalize_name(pub.name), v_nq) >= 0.30
      )
  )
  SELECT s.id, s.name, s.city, s.country, s.match_kind, s.score
  FROM scored s
  ORDER BY s.score DESC, s.name
  LIMIT v_lim;
END;
$$;


ALTER FUNCTION "public"."search_publishers_by_name"("p_query" "text", "p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."set_author_translation_review"("p_author_id" bigint, "p_lang" "text", "p_reviewed" boolean) RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_found boolean;
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM public.user_library_memberships m
    WHERE m.user_id = auth.uid()
      AND m.role = ANY (ARRAY['librarian'::text, 'coordenador'::text])
  ) THEN
    RAISE EXCEPTION 'Acesso restrito ao staff de catalogacao.';
  END IF;

  IF p_reviewed THEN
    UPDATE public.author_translations
    SET status = 'reviewed', reviewed_by = auth.uid(), reviewed_at = now(), updated_at = now()
    WHERE author_id = p_author_id AND lang = p_lang;
  ELSE
    UPDATE public.author_translations
    SET status = 'draft', reviewed_by = NULL, reviewed_at = NULL, updated_at = now()
    WHERE author_id = p_author_id AND lang = p_lang;
  END IF;

  GET DIAGNOSTICS v_found = ROW_COUNT;
  RETURN v_found > 0;
END;
$$;


