CREATE TABLE IF NOT EXISTS "public"."library_circulation_policy_sets" (
    "id" bigint NOT NULL,
    "library_id" "uuid" NOT NULL,
    "regulation_document_id" bigint,
    "label" "text" NOT NULL,
    "status" "text" DEFAULT 'draft'::"text" NOT NULL,
    "is_active" boolean DEFAULT false NOT NULL,
    "config_version" integer DEFAULT 1 NOT NULL,
    "effective_from" "date",
    "effective_until" "date",
    "activation_note" "text",
    "scope_note" "text",
    "metadata" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "created_by" "uuid",
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_by" "uuid",
    "activated_at" timestamp with time zone,
    "activated_by" "uuid",
    "system_seed_key" "text",
    "max_concurrent_loans" integer,
    "max_concurrent_reservations" integer,
    "max_concurrent_consultations" integer,
    CONSTRAINT "chk_max_concurrent_consultations" CHECK ((("max_concurrent_consultations" IS NULL) OR ("max_concurrent_consultations" >= 0))),
    CONSTRAINT "chk_max_concurrent_loans" CHECK ((("max_concurrent_loans" IS NULL) OR ("max_concurrent_loans" >= 0))),
    CONSTRAINT "chk_max_concurrent_reservations" CHECK ((("max_concurrent_reservations" IS NULL) OR ("max_concurrent_reservations" >= 0))),
    CONSTRAINT "library_circulation_policy_sets_config_version_chk" CHECK (("config_version" >= 1)),
    CONSTRAINT "library_circulation_policy_sets_effective_dates_chk" CHECK ((("effective_until" IS NULL) OR ("effective_from" IS NULL) OR ("effective_until" >= "effective_from"))),
    CONSTRAINT "library_circulation_policy_sets_label_chk" CHECK (("length"(TRIM(BOTH FROM "label")) > 0)),
    CONSTRAINT "library_circulation_policy_sets_status_chk" CHECK (("status" = ANY (ARRAY['draft'::"text", 'active'::"text", 'archived'::"text"])))
);


