CREATE OR REPLACE FUNCTION "public"."set_library_circulation_policy_set_active"("p_policy_set_id" bigint) RETURNS "public"."library_circulation_policy_sets"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'auth', 'pg_temp'
    AS $$
declare
  v_set public.library_circulation_policy_sets%rowtype;
  v_row public.library_circulation_policy_sets;
begin
  if auth.uid() is null then
    raise exception 'authentication required';
  end if;

  select *
    into v_set
  from public.library_circulation_policy_sets s
  where s.id = p_policy_set_id;

  if v_set.id is null then
    raise exception 'Conjunto de regras não encontrado: %', p_policy_set_id;
  end if;

  if not public.can_manage_library_circulation_policies(v_set.library_id) then
    raise exception 'permission denied for library_circulation_policy_sets';
  end if;

  update public.library_circulation_policy_sets s
     set is_active = false,
         status = case when s.status = 'active' then 'draft' else s.status end,
         updated_at = now(),
         updated_by = auth.uid()
   where s.library_id = v_set.library_id
     and s.id <> v_set.id
     and s.is_active = true;

  update public.library_circulation_policy_sets s
     set is_active = true,
         status = 'active',
         activated_at = now(),
         activated_by = auth.uid(),
         updated_at = now(),
         updated_by = auth.uid()
   where s.id = v_set.id
   returning * into v_row;

  return v_row;
end;
$$;


