CREATE OR REPLACE FUNCTION "public"."set_library_regulation_document_active"("p_document_id" bigint, "p_make_active" boolean DEFAULT true) RETURNS "public"."library_regulation_documents"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'auth', 'pg_temp'
    AS $$
declare
  v_doc public.library_regulation_documents%rowtype;
  v_row public.library_regulation_documents;
begin
  if auth.uid() is null then
    raise exception 'authentication required';
  end if;

  select *
    into v_doc
  from public.library_regulation_documents d
  where d.id = p_document_id;

  if v_doc.id is null then
    raise exception 'Documento institucional não encontrado: %', p_document_id;
  end if;

  if not public.can_manage_library_regulation_documents(v_doc.library_id) then
    raise exception 'permission denied for library_regulation_documents';
  end if;

  if p_make_active then
    update public.library_regulation_documents d
       set is_active = false,
           updated_at = now(),
           updated_by = auth.uid()
     where d.library_id = v_doc.library_id
       and d.doc_kind = v_doc.doc_kind
       and d.id <> v_doc.id
       and d.is_active = true;
  end if;

  update public.library_regulation_documents d
     set is_active = p_make_active,
         updated_at = now(),
         updated_by = auth.uid()
   where d.id = v_doc.id
   returning * into v_row;

  return v_row;
end;
$$;


