CREATE TABLE IF NOT EXISTS "public"."library_theme_configs" (
    "library_slug" "text" NOT NULL,
    "background_url" "text",
    "palette_preset" "text" DEFAULT 'default'::"text" NOT NULL,
    "font_pack" "text" DEFAULT 'default'::"text" NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_by" "uuid"
);


ALTER TABLE "public"."library_theme_configs" OWNER TO "postgres";


COMMENT ON TABLE "public"."library_theme_configs" IS 'Configuração visual leve por biblioteca para sobrepor o manifest do tema.';



CREATE OR REPLACE FUNCTION "public"."set_library_theme_config"("p_library_slug" "text", "p_background_url" "text" DEFAULT NULL::"text", "p_palette_preset" "text" DEFAULT 'default'::"text", "p_font_pack" "text" DEFAULT 'default'::"text") RETURNS "public"."library_theme_configs"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_slug text := coalesce(nullif(lower(trim(p_library_slug)), ''), 'default');
  v_uid uuid := auth.uid();
  v_allowed boolean := false;
  v_row public.library_theme_configs;
begin
  if v_uid is null then
    raise exception 'auth required';
  end if;

  -- version prudente : on n'autorise pas ici l'édition du thème global "default"
  if v_slug = 'default' then
    raise exception 'forbidden';
  end if;

  select exists (
    select 1
    from public.user_library_memberships m
    join public.libraries l on l.id = m.library_id
    where m.user_id = v_uid
      and m.status = 'active'
      and m.role = 'librarian'
      and l.is_active = true
      and l.slug = v_slug
  )
  into v_allowed;

  if not v_allowed then
    raise exception 'forbidden';
  end if;

  insert into public.library_theme_configs as c (
    library_slug,
    background_url,
    palette_preset,
    font_pack,
    updated_at,
    updated_by
  ) values (
    v_slug,
    nullif(trim(p_background_url), ''),
    coalesce(nullif(trim(p_palette_preset), ''), 'default'),
    coalesce(nullif(trim(p_font_pack), ''), 'default'),
    now(),
    v_uid
  )
  on conflict (library_slug) do update
    set background_url = excluded.background_url,
        palette_preset = excluded.palette_preset,
        font_pack = excluded.font_pack,
        updated_at = now(),
        updated_by = v_uid
  returning * into v_row;

  return v_row;
end;
$$;


ALTER FUNCTION "public"."set_library_theme_config"("p_library_slug" "text", "p_background_url" "text", "p_palette_preset" "text", "p_font_pack" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."set_library_theme_config"("p_library_slug" "text", "p_background_url" "text", "p_palette_preset" "text", "p_font_pack" "text") IS 'Salva a configuração visual da biblioteca. Requer utilizador autenticado com is_librarian = true.';



CREATE OR REPLACE FUNCTION "public"."set_library_theme_config_by_library_id"("p_library_id" "uuid", "p_theme" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "public"."library_theme_configs"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_library_id uuid;
  v_slug text;
  v_theme jsonb := coalesce(p_theme, '{}'::jsonb);
  v_row public.library_theme_configs;
begin
  v_library_id := public.resolve_managed_library_id(p_library_id);

  select l.slug
    into v_slug
  from public.libraries l
  where l.id = v_library_id;

  select *
    into v_row
  from public.set_library_theme_config(
    v_slug,
    nullif(trim(coalesce(v_theme->>'background_url', '')), ''),
    coalesce(nullif(trim(coalesce(v_theme->>'palette_preset', '')), ''), 'default'),
    coalesce(nullif(trim(coalesce(v_theme->>'font_pack', '')), ''), 'default')
  );

  return v_row;
end;
$$;


