CREATE OR REPLACE FUNCTION "public"."suggest_author_book_matches"("p_author_id" bigint) RETURNS TABLE("contributor_id" bigint, "book_id" bigint, "book_title" "text", "contributor_name" "text", "role" "text", "match_kind" "text", "score" real)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions', 'pg_catalog'
    AS $$
DECLARE
  v_forms text[];
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM public.user_library_memberships m
    WHERE m.user_id = auth.uid()
      AND m.role = ANY (ARRAY['librarian'::text, 'coordenador'::text])
  ) THEN
    RAISE EXCEPTION 'Acesso restrito ao staff de catalogacao.';
  END IF;

  SELECT array_agg(DISTINCT nf) INTO v_forms
  FROM (
    SELECT public.fn_normalize_name(a.preferred_name) AS nf FROM public.authors a WHERE a.id = p_author_id
    UNION
    SELECT public.fn_normalize_name(a.sort_name) FROM public.authors a WHERE a.id = p_author_id
    UNION
    SELECT public.fn_normalize_name(vf)
    FROM public.authors a
    CROSS JOIN LATERAL (
      SELECT jsonb_array_elements_text(a.variant_forms) AS vf
      WHERE a.variant_forms IS NOT NULL AND jsonb_typeof(a.variant_forms) = 'array'
    ) v
    WHERE a.id = p_author_id
  ) s
  WHERE s.nf <> '';

  IF v_forms IS NULL OR array_length(v_forms, 1) IS NULL THEN
    RETURN;
  END IF;

  RETURN QUERY
  WITH cand AS (
    SELECT bc.id AS cid, bc.book_id AS bid, bc.name AS cname, bc.role AS crole,
           public.fn_normalize_name(bc.name) AS cn
    FROM public.book_contributors bc
    WHERE bc.author_id IS NULL
  )
  SELECT c.cid, c.bid, b.titulo, c.cname, c.crole,
         CASE WHEN c.cn = ANY (v_forms) THEN 'exact' ELSE 'approx' END,
         CASE WHEN c.cn = ANY (v_forms) THEN 1.0::real
              ELSE (SELECT max(similarity(c.cn, f)) FROM unnest(v_forms) f) END
  FROM cand c
  JOIN public.books b ON b.id = c.bid
  WHERE c.cn <> ''
    AND ( c.cn = ANY (v_forms)
          OR (SELECT max(similarity(c.cn, f)) FROM unnest(v_forms) f) >= 0.45 )
  ORDER BY 7 DESC, b.titulo;
END;
$$;


ALTER FUNCTION "public"."suggest_author_book_matches"("p_author_id" bigint) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."suggest_author_book_matches"("p_author_id" bigint) IS 'Candidats book_contributors non lies matchant l''autorite (exact/trigramme). Paquet liaison autorites du 05/06/2026.';



CREATE OR REPLACE FUNCTION "public"."suggest_author_duplicates"("p_author_id" bigint) RETURNS TABLE("author_id" bigint, "preferred_name" "text", "sort_name" "text", "linked_books" integer, "match_kind" "text", "score" real)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions', 'pg_catalog'
    AS $$
DECLARE
  v_forms text[];
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM public.user_library_memberships m
    WHERE m.user_id = auth.uid()
      AND m.role = ANY (ARRAY['librarian'::text, 'coordenador'::text])
  ) THEN
    RAISE EXCEPTION 'Acesso restrito ao staff de catalogacao.';
  END IF;

  SELECT array_agg(DISTINCT nf) INTO v_forms
  FROM (
    SELECT public.fn_normalize_name(a.preferred_name) AS nf FROM public.authors a WHERE a.id = p_author_id
    UNION
    SELECT public.fn_normalize_name(a.sort_name) FROM public.authors a WHERE a.id = p_author_id
    UNION
    SELECT al.alias_norm FROM public.author_name_aliases al WHERE al.author_id = p_author_id AND al.is_active
  ) s
  WHERE s.nf <> '';

  IF v_forms IS NULL OR array_length(v_forms, 1) IS NULL THEN
    RETURN;
  END IF;

  RETURN QUERY
  WITH other AS (
    SELECT a.id, a.preferred_name, a.sort_name,
           public.fn_normalize_name(a.preferred_name) AS np
    FROM public.authors a
    WHERE a.id <> p_author_id
  )
  SELECT o.id, o.preferred_name, o.sort_name,
         (SELECT count(DISTINCT ba.book_id)::integer FROM public.book_authors ba WHERE ba.author_id = o.id),
         CASE WHEN o.np = ANY (v_forms) THEN 'exact' ELSE 'approx' END,
         CASE WHEN o.np = ANY (v_forms) THEN 1.0::real
              ELSE (SELECT max(similarity(o.np, f)) FROM unnest(v_forms) f) END
  FROM other o
  WHERE o.np <> ''
    AND ( o.np = ANY (v_forms)
          OR (SELECT max(similarity(o.np, f)) FROM unnest(v_forms) f) >= 0.45 )
  ORDER BY 6 DESC, o.preferred_name;
END;
$$;


ALTER FUNCTION "public"."suggest_author_duplicates"("p_author_id" bigint) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."suggest_author_duplicates"("p_author_id" bigint) IS 'Autorites candidates doublons (exact-normalise + trigramme). Paquet doublons du 05/06/2026.';



CREATE OR REPLACE FUNCTION "public"."suggest_book_duplicates"("p_book_id" bigint) RETURNS TABLE("book_id" bigint, "titulo" "text", "autor" "text", "ano" "text", "editora" "text", "isbn" "text", "exemplares" integer, "match_kind" "text", "score" real)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions', 'pg_catalog'
    AS $$
DECLARE
  v_isbn   text;
  v_title  text;
  v_author text;
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM public.user_library_memberships m
    WHERE m.user_id = auth.uid()
      AND m.role = ANY (ARRAY['librarian'::text, 'coordenador'::text])
  ) THEN
    RAISE EXCEPTION 'Acesso restrito ao staff de catalogacao.';
  END IF;

  SELECT regexp_replace(upper(coalesce(b.isbn, '')), '[^0-9X]', '', 'g'),
         public.fn_normalize_name(b.titulo),
         public.fn_normalize_name(b.autor)
    INTO v_isbn, v_title, v_author
    FROM public.books b WHERE b.id = p_book_id;

  IF v_title IS NULL THEN
    RETURN;
  END IF;

  RETURN QUERY
  WITH other AS (
    SELECT b.id, b.titulo, b.autor, b.ano, b.editora, b.isbn,
           regexp_replace(upper(coalesce(b.isbn, '')), '[^0-9X]', '', 'g') AS ni,
           public.fn_normalize_name(b.titulo) AS nt,
           public.fn_normalize_name(b.autor) AS na
    FROM public.books b
    WHERE b.id <> p_book_id
  )
  SELECT o.id, o.titulo, o.autor, o.ano, o.editora, o.isbn,
         (SELECT coalesce(sum(h.exemplares_total), 0)::integer
            FROM public.book_holdings h WHERE h.book_id = o.id),
         CASE WHEN v_isbn <> '' AND o.ni = v_isbn THEN 'isbn' ELSE 'approx' END,
         CASE WHEN v_isbn <> '' AND o.ni = v_isbn THEN 1.0::real
              ELSE similarity(o.nt, v_title)::real END
  FROM other o
  WHERE (v_isbn <> '' AND o.ni = v_isbn)
     OR (o.nt <> ''
         AND similarity(o.nt, v_title) >= 0.5
         AND (v_author = '' OR o.na = '' OR similarity(o.na, v_author) >= 0.4))
  ORDER BY 9 DESC, o.titulo
  LIMIT 50;
END;
$$;


ALTER FUNCTION "public"."suggest_book_duplicates"("p_book_id" bigint) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."suggest_book_duplicates"("p_book_id" bigint) IS 'Livres candidats doublons (ISBN exact + titre/auteur trigramme). Lecture seule. Paquet doublons P2a du 05/06/2026.';



CREATE OR REPLACE FUNCTION "public"."sync_book_native_provenance_bridge"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_doc jsonb := coalesce(new.marc_json, '{}'::jsonb);
  v_acq_in jsonb := coalesce(v_doc -> 'anarbib_acquisition', '{}'::jsonb);
  v_prov_in jsonb := coalesce(v_doc -> 'anarbib_provenance', '{}'::jsonb);
  v_net_in jsonb := coalesce(v_doc -> 'anarbib_network', '{}'::jsonb);

  v_acquisition_mode text;
  v_acquisition_date date;
  v_owner_library text;
  v_holder_library text;
  v_partner_source text;
  v_source_record_id text;
  v_source_record_url text;
  v_import_format text;
  v_import_method text;
  v_provenance_note text;
  v_mutualization_status text;

  v_acq_out jsonb;
  v_prov_out jsonb;
  v_net_out jsonb;
begin
  v_acquisition_mode := coalesce(
    public._anarbib_trim_or_null(new.acquisition_mode),
    public._anarbib_trim_or_null(v_acq_in ->> 'acquisition_mode')
  );

  v_acquisition_date := coalesce(
    new.acquisition_date,
    public._anarbib_safe_date(v_acq_in ->> 'acquisition_date')
  );

  v_owner_library := coalesce(
    public._anarbib_trim_or_null(new.owner_library),
    public._anarbib_trim_or_null(v_acq_in ->> 'owner_library')
  );

  v_holder_library := coalesce(
    public._anarbib_trim_or_null(new.holder_library),
    public._anarbib_trim_or_null(v_acq_in ->> 'holder_library')
  );

  v_partner_source := coalesce(
    public._anarbib_trim_or_null(new.partner_source),
    public._anarbib_trim_or_null(v_prov_in ->> 'partner_source')
  );

  v_source_record_id := coalesce(
    public._anarbib_trim_or_null(new.source_record_id),
    public._anarbib_trim_or_null(v_prov_in ->> 'source_record_id')
  );

  v_source_record_url := coalesce(
    public._anarbib_trim_or_null(new.source_record_url),
    public._anarbib_trim_or_null(v_prov_in ->> 'source_record_url')
  );

  v_import_format := coalesce(
    public._anarbib_trim_or_null(new.import_format),
    public._anarbib_trim_or_null(v_prov_in ->> 'import_format')
  );

  v_import_method := coalesce(
    public._anarbib_trim_or_null(new.import_method),
    public._anarbib_trim_or_null(v_prov_in ->> 'import_method')
  );

  v_provenance_note := coalesce(
    public._anarbib_trim_or_null(new.provenance_note),
    public._anarbib_trim_or_null(v_prov_in ->> 'provenance_note')
  );

  v_mutualization_status := coalesce(
    public._anarbib_trim_or_null(new.mutualization_status),
    public._anarbib_trim_or_null(v_net_in ->> 'mutualization_status')
  );

  new.acquisition_mode := v_acquisition_mode;
  new.acquisition_date := v_acquisition_date;
  new.owner_library := v_owner_library;
  new.holder_library := v_holder_library;
  new.partner_source := v_partner_source;
  new.source_record_id := v_source_record_id;
  new.source_record_url := v_source_record_url;
  new.import_format := v_import_format;
  new.import_method := v_import_method;
  new.provenance_note := v_provenance_note;
  new.mutualization_status := v_mutualization_status;

  v_acq_out := jsonb_strip_nulls(jsonb_build_object(
    'acquisition_mode', v_acquisition_mode,
    'acquisition_date', case when v_acquisition_date is null then null else to_char(v_acquisition_date, 'YYYY-MM-DD') end,
    'owner_library', v_owner_library,
    'holder_library', v_holder_library
  ));

  v_prov_out := jsonb_strip_nulls(jsonb_build_object(
    'partner_source', v_partner_source,
    'source_record_id', v_source_record_id,
    'source_record_url', v_source_record_url,
    'import_format', v_import_format,
    'import_method', v_import_method,
    'provenance_note', v_provenance_note
  ));

  v_net_out := jsonb_strip_nulls(jsonb_build_object(
    'mutualization_status', v_mutualization_status
  ));

  v_doc := v_doc - 'anarbib_acquisition' - 'anarbib_provenance' - 'anarbib_network';

  if v_acq_out <> '{}'::jsonb then
    v_doc := jsonb_set(v_doc, '{anarbib_acquisition}', v_acq_out, true);
  end if;

  if v_prov_out <> '{}'::jsonb then
    v_doc := jsonb_set(v_doc, '{anarbib_provenance}', v_prov_out, true);
  end if;

  if v_net_out <> '{}'::jsonb then
    v_doc := jsonb_set(v_doc, '{anarbib_network}', v_net_out, true);
  end if;

  new.marc_json := v_doc;
  return new;
end;
$$;


ALTER FUNCTION "public"."sync_book_native_provenance_bridge"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sync_exemplar_draft_holdings_bridge"("p_draft_id" bigint) RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_target_bib_ref text;
  v_published_exemplar_id bigint;
  v_target_library_id uuid;
  v_target_holding_id bigint;

  v_resolved_library_id uuid := null;
  v_resolved_holding_id bigint := null;
  v_resolved_reference_code text := null;

  v_exemplar_library_id uuid := null;
  v_exemplar_holding_id bigint := null;
  v_bridge record;
  v_holding record;
begin
  select
    d.target_bib_ref,
    d.published_exemplar_id,
    d.target_library_id,
    d.target_holding_id
  into
    v_target_bib_ref,
    v_published_exemplar_id,
    v_target_library_id,
    v_target_holding_id
  from public.exemplar_drafts d
  where d.id = p_draft_id;

  if not found then
    raise exception 'Rascunho de exemplar não encontrado: %', p_draft_id;
  end if;

  if v_published_exemplar_id is not null then
    select e.library_id, e.holding_id
      into v_exemplar_library_id, v_exemplar_holding_id
    from public.exemplares e
    where e.id = v_published_exemplar_id
    limit 1;
  end if;

  v_resolved_library_id := coalesce(v_target_library_id, v_exemplar_library_id);
  v_resolved_holding_id := coalesce(v_target_holding_id, v_exemplar_holding_id);

  if v_resolved_holding_id is not null then
    select
      h.id,
      h.library_id,
      coalesce(nullif(trim(h.local_bib_ref), ''), b.bib_ref) as reference_code
    into v_holding
    from public.book_holdings h
    left join public.books b
      on b.id = h.book_id
    where h.id = v_resolved_holding_id
      and (v_resolved_library_id is null or h.library_id = v_resolved_library_id)
    limit 1;

    if found then
      v_resolved_holding_id := v_holding.id;
      v_resolved_library_id := coalesce(v_holding.library_id, v_resolved_library_id);
      v_resolved_reference_code := v_holding.reference_code;
    end if;
  end if;

  if v_resolved_holding_id is null
     and v_resolved_library_id is not null
     and nullif(trim(v_target_bib_ref), '') is not null then
    select *
      into v_bridge
    from public.resolve_library_holding_bridge(v_resolved_library_id, v_target_bib_ref)
    limit 1;

    if found then
      v_resolved_holding_id := v_bridge.holding_id;
      v_resolved_reference_code := coalesce(v_bridge.local_bib_ref, v_bridge.resolved_bib_ref, v_target_bib_ref);
    end if;
  end if;

  update public.exemplar_drafts d
     set target_library_id = coalesce(v_resolved_library_id, d.target_library_id),
         target_holding_id = coalesce(v_resolved_holding_id, d.target_holding_id),
         target_bib_ref = coalesce(v_resolved_reference_code, d.target_bib_ref),
         updated_at = now()
   where d.id = p_draft_id;

  return true;
end;
$$;


ALTER FUNCTION "public"."sync_exemplar_draft_holdings_bridge"("p_draft_id" bigint) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."sync_exemplar_draft_holdings_bridge"("p_draft_id" bigint) IS 'Passe 42 backend phase 3: synchronise un brouillon d exemplaire vers la couche canonique target_library_id/target_holding_id tout en gardant target_bib_ref comme cache de compatibilité.';



CREATE OR REPLACE FUNCTION "public"."sync_primary_membership_role_from_profile_flag"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_target_role text;
  v_active_primary_count integer;
begin
  if tg_op <> 'UPDATE' then
    return new;
  end if;

  if coalesce(new.is_librarian, false) is not distinct from coalesce(old.is_librarian, false) then
    return new;
  end if;

  select count(*)
  into v_active_primary_count
  from public.user_library_memberships ulm
  where ulm.user_id = new.id
    and ulm.status = 'active'
    and ulm.is_primary = true;

  if v_active_primary_count = 1 then
    v_target_role := case
      when coalesce(new.is_librarian, false) then 'librarian'
      else 'reader'
    end;

    update public.user_library_memberships ulm
    set role = v_target_role
    where ulm.user_id = new.id
      and ulm.status = 'active'
      and ulm.is_primary = true
      and ulm.role is distinct from v_target_role;
  end if;

  return new;
end;
$$;


