CREATE OR REPLACE FUNCTION "public"."sync_profile_is_librarian_from_memberships"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_user_id uuid;
  v_is_librarian boolean;
begin
  v_user_id := coalesce(new.user_id, old.user_id);

  select exists (
    select 1
    from public.user_library_memberships ulm
    where ulm.user_id = v_user_id
      and ulm.status = 'active'
      and ulm.role = 'librarian'
  )
  into v_is_librarian;

  update public.profiles p
  set is_librarian = v_is_librarian
  where p.id = v_user_id
    and coalesce(p.is_librarian, false) is distinct from v_is_librarian;

  return coalesce(new, old);
end;
$$;


