CREATE OR REPLACE FUNCTION "public"."sync_task_invites_from_task"("p_task_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'auth', 'pg_temp'
    AS $$
declare
  v_task public.painel_internal_tasks%rowtype;
  v_emails text[];
  v_email text;
  v_invite_id bigint;
  v_queued_count integer := 0;
  v_cancelled_count integer := 0;
begin
  select *
    into v_task
  from public.painel_internal_tasks
  where id = p_task_id;

  if not found then
    raise exception 'Tarefa não encontrada: %', p_task_id;
  end if;

  v_emails := public.task_invite_emails_from_tags(v_task.tags);

  foreach v_email in array coalesce(v_emails, '{}'::text[])
  loop
    insert into public.painel_internal_task_invites (
      task_id,
      library_id,
      invite_email,
      invite_status,
      first_queued_at,
      last_queued_at,
      created_by,
      updated_by
    )
    values (
      v_task.id,
      v_task.library_id,
      v_email,
      'pending',
      now(),
      now(),
      auth.uid(),
      auth.uid()
    )
    on conflict (task_id, invite_email)
    do update
      set library_id = excluded.library_id,
          invite_status = case
            when public.painel_internal_task_invites.invite_status = 'cancelled' then 'pending'
            else public.painel_internal_task_invites.invite_status
          end,
          last_queued_at = now(),
          updated_at = now(),
          updated_by = auth.uid()
    returning id into v_invite_id;

    if not exists (
      select 1
      from public.painel_internal_task_invitation_outbox o
      where o.invite_id = v_invite_id
        and o.event_kind = 'task_invitation'
        and o.dispatch_status in ('queued','sent')
    ) then
      insert into public.painel_internal_task_invitation_outbox (
        invite_id,
        task_id,
        library_id,
        recipient_email,
        event_kind,
        request_body,
        dispatch_status
      )
      values (
        v_invite_id,
        v_task.id,
        v_task.library_id,
        v_email,
        'task_invitation',
        jsonb_build_object(
          'kind', 'task_invitation',
          'task_id', v_task.id,
          'invite_email', v_email
        ),
        'queued'
      );
      v_queued_count := v_queued_count + 1;
    end if;
  end loop;

  update public.painel_internal_task_invites i
     set invite_status = 'cancelled',
         updated_at = now(),
         updated_by = auth.uid()
   where i.task_id = v_task.id
     and i.invite_status <> 'cancelled'
     and (
       coalesce(array_length(v_emails, 1), 0) = 0
       or not (i.invite_email = any(v_emails))
     );

  get diagnostics v_cancelled_count = row_count;

  return jsonb_build_object(
    'ok', true,
    'task_id', v_task.id,
    'queued', v_queued_count,
    'cancelled', v_cancelled_count,
    'invitees', coalesce(v_emails, '{}'::text[])
  );
end;
$$;


ALTER FUNCTION "public"."sync_task_invites_from_task"("p_task_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."sync_task_invites_from_task"("p_task_id" "uuid") IS 'Synchronise as invitations de uma tarefa à partir de tags convite: e enqueue os envios.';



CREATE OR REPLACE FUNCTION "public"."task_invite_emails_from_tags"("p_tags" "text"[]) RETURNS "text"[]
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  select coalesce(
    array_agg(distinct lower(trim(substring(tag from 9)))) filter (
      where tag is not null
        and lower(tag) like 'convite:%'
        and nullif(trim(substring(tag from 9)), '') is not null
    ),
    '{}'::text[]
  )
  from unnest(coalesce(p_tags, '{}'::text[])) as tag;
$$;


