CREATE OR REPLACE FUNCTION "public"."test_library_mail_channel"("p_library_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_ctx public.v_library_notification_context%rowtype;
  v_state text;
begin
  if p_library_id is null then
    raise exception 'library_id ausente';
  end if;

  if not public.user_can_manage_library_notifications(p_library_id) then
    raise exception 'Sem permissão para testar notificações desta biblioteca';
  end if;

  select *
    into v_ctx
  from public.v_library_notification_context
  where library_id = p_library_id;

  v_state := case
    when coalesce(v_ctx.channel_active, true) = false then 'disabled'
    when coalesce(v_ctx.delivery_mode, 'platform_shared') = 'disabled' then 'disabled'
    when coalesce(v_ctx.delivery_mode, 'platform_shared') = 'library_own_transport'
      and nullif(v_ctx.admin_notification_email, '') is null
      then 'missing_local_channel'
    else 'ok'
  end;

  update public.library_mail_channels
  set transport_state = v_state,
      transport_channel = coalesce(v_ctx.delivery_mode, 'platform_shared'),
      last_tested_at = now(),
      updated_at = now(),
      updated_by = auth.uid()
  where library_id = p_library_id;

  return jsonb_build_object(
    'ok', v_state = 'ok',
    'transport_state', v_state,
    'transport_channel', coalesce(v_ctx.delivery_mode, 'platform_shared'),
    'last_tested_at', now(),
    'message', case
      when v_state = 'ok' then 'Configuração válida.'
      when v_state = 'disabled' then 'O envio está desativado para esta biblioteca.'
      when v_state = 'missing_local_channel' then 'Falta configurar um canal local mínimo para o modo de envio próprio.'
      else 'Configuração incompleta.'
    end
  );
end;
$$;


