CREATE OR REPLACE FUNCTION "public"."tg_enqueue_task_level_notifications_from_task"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_changed_fields text[] := '{}';
begin
  if tg_op = 'INSERT' then
    perform public.enqueue_task_level_notifications_from_task(new.id, 'task_created', null);
    return new;
  end if;

  if new.due_date is distinct from old.due_date then
    v_changed_fields := array_append(v_changed_fields, 'due_date');
  end if;

  if new.priority is distinct from old.priority then
    v_changed_fields := array_append(v_changed_fields, 'priority');
  end if;

  if new.status is distinct from old.status then
    v_changed_fields := array_append(v_changed_fields, 'status');
  end if;

  if new.owner is distinct from old.owner or new.owner_user_id is distinct from old.owner_user_id then
    v_changed_fields := array_append(v_changed_fields, 'owner');
  end if;

  if coalesce(array_length(v_changed_fields, 1), 0) > 0 then
    perform public.enqueue_task_level_notifications_from_task(new.id, 'task_updated', v_changed_fields);
  end if;

  return new;
end;
$$;


