CREATE OR REPLACE FUNCTION "public"."tg_library_requests_notify"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_is_more_info boolean := false;
  v_more_info_prefix text := 'pedido de complemento:';
begin
  if tg_op = 'INSERT' then
    begin
      perform public.fn_enqueue_library_request_notification(
        p_request_id := new.id,
        p_event_type := 'library_request_created',
        p_event_key := 'created',
        p_triggered_by_user_id := new.submitted_by_user_id
      );
    exception
      when others then
        raise warning 'library_request notification enqueue failed on insert: %', sqlerrm;
    end;
    return new;
  end if;

  v_is_more_info :=
    new.request_status = 'em_analise'
    and coalesce(new.review_notes, '') <> coalesce(old.review_notes, '')
    and nullif(btrim(coalesce(new.review_notes, '')), '') is not null
    and lower(btrim(new.review_notes)) like v_more_info_prefix || '%';

  if v_is_more_info then
    begin
      perform public.fn_enqueue_library_request_notification(
        p_request_id := new.id,
        p_event_type := 'library_request_more_info',
        p_event_key := 'more_info:' || md5(coalesce(new.review_notes, '')),
        p_triggered_by_user_id := coalesce(new.reviewed_by_user_id, auth.uid())
      );
    exception
      when others then
        raise warning 'library_request notification enqueue failed for more_info: %', sqlerrm;
    end;
    return new;
  end if;

  if coalesce(old.request_status, '') is distinct from coalesce(new.request_status, '') then
    if new.request_status = 'em_analise' then
      begin
        perform public.fn_enqueue_library_request_notification(
          p_request_id := new.id,
          p_event_type := 'library_request_in_analysis',
          p_event_key := 'status:em_analise',
          p_triggered_by_user_id := coalesce(new.reviewed_by_user_id, auth.uid())
        );
      exception
        when others then
          raise warning 'library_request notification enqueue failed for in_analysis: %', sqlerrm;
      end;
    elsif new.request_status = 'aprovada' then
      begin
        perform public.fn_enqueue_library_request_notification(
          p_request_id := new.id,
          p_event_type := 'library_request_approved',
          p_event_key := 'status:aprovada',
          p_triggered_by_user_id := coalesce(new.reviewed_by_user_id, auth.uid())
        );
      exception
        when others then
          raise warning 'library_request notification enqueue failed for approved: %', sqlerrm;
      end;
    elsif new.request_status = 'recusada' then
      begin
        perform public.fn_enqueue_library_request_notification(
          p_request_id := new.id,
          p_event_type := 'library_request_refused',
          p_event_key := 'status:recusada',
          p_triggered_by_user_id := coalesce(new.reviewed_by_user_id, auth.uid())
        );
      exception
        when others then
          raise warning 'library_request notification enqueue failed for refused: %', sqlerrm;
      end;
    end if;
  end if;

  return new;
end;
$$;


