CREATE OR REPLACE FUNCTION "public"."trg_auto_liberate_after_no_show_change"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_reason text;
BEGIN
  v_reason := CASE
    WHEN NEW.workflow_stage IN ('retirada_no_show', 'nao_retirada')
      THEN 'no_show'
    WHEN NEW.workflow_stage = 'cancelada_biblioteca'
      THEN 'cancelled_by_library'
    ELSE NULL
  END;

  IF v_reason IS NULL THEN
    RETURN NEW;
  END IF;

  -- Bascule du workflow vers l'etat de liberation (inchange).
  UPDATE public.reserva_item_workflow_v2
  SET workflow_stage = 'liberada_para_circulacao',
      final_reason = v_reason,
      updated_at = now()
  WHERE id = NEW.id;

  -- CORRECTION 26/05/2026 : propagation de l'etat terminal a la ligne de
  -- reservation. Conditionnee par item_status = 'ativa' :
  --  - no-show           : la ligne est encore 'ativa' -> on inscrit la
  --                        liberation, la resa cesse d'etre comptee active.
  --  - annulation biblio : cancel_reservation_as_library a deja pose
  --                        item_status = 'cancelada_biblioteca' AVANT cette
  --                        bascule -> le WHERE exclut la ligne, l'issue
  --                        terminale (annulation) est preservee.
  -- Le workflow_stage decrit l'etat physique de l'exemplaire ; item_status
  -- decrit l'issue de la reservation. Les deux dimensions restent distinctes.
  UPDATE public.reserva_linhas_v2
  SET item_status = 'liberada_para_circulacao',
      updated_at = timezone('utc', now())
  WHERE reserva_id = NEW.reserva_id
    AND line_no = NEW.line_no
    AND item_status = 'ativa';

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."trg_auto_liberate_after_no_show_change"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."trg_catalog_partner_capabilities_sync_last_probe"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
declare
  v_partner_id public.catalog_partners.id%TYPE;
begin
  v_partner_id := coalesce(new.partner_id, old.partner_id);

  if v_partner_id is null then
    return coalesce(new, old);
  end if;

  update public.catalog_partners p
  set technical_probe_last_at = src.last_checked_at
  from (
    select max(c.last_checked_at) as last_checked_at
    from public.catalog_partner_capabilities c
    where c.partner_id = v_partner_id
      and c.last_checked_at is not null
  ) src
  where p.id = v_partner_id
    and (
      p.technical_probe_last_at is distinct from src.last_checked_at
      or (p.technical_probe_last_at is null and src.last_checked_at is not null)
    );

  return coalesce(new, old);
end
$$;


ALTER FUNCTION "public"."trg_catalog_partner_capabilities_sync_last_probe"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."trg_catalog_partner_capabilities_touch_partner_probe_last_at"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
      BEGIN
        UPDATE public.catalog_partners
        SET technical_probe_last_at = greatest(
          coalesce(technical_probe_last_at, '-infinity'::timestamptz),
          coalesce(NEW.last_checked_at, now())
        )
        WHERE id = NEW.partner_id;
        RETURN NEW;
      END;
      $$;


