CREATE OR REPLACE FUNCTION "public"."trg_interlibrary_loan_enqueue_notifications"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_event_id bigint;
begin
  -- NOTE 20260522050000 (#ILL-partial) : la gestion de l'evenement de
  -- creation a ete retiree de ce trigger. L'evenement est desormais emis
  -- explicitement par fn_peb_create_loan_with_items, APRES insertion des
  -- exemplaires, pour que la payload compte correctement les documents.
  -- Ce trigger ne gere plus que les changements de status_global (UPDATE).

  if tg_op = 'UPDATE' then
    if old.status_global is distinct from new.status_global then
      if new.status_global = 'aguardando_saida' then
        v_event_id := public.fn_enqueue_emprestimo_interbibliotecas_notification(
          new.id,
          'interlibrary_loan_prepared',
          'prepared'
        );
        perform public.fn_notify_emprestimo_interbibliotecas_webhook(v_event_id);

      elsif new.status_global = 'emprestado' then
        v_event_id := public.fn_enqueue_emprestimo_interbibliotecas_notification(
          new.id,
          'interlibrary_loan_dispatched',
          'dispatched'
        );
        perform public.fn_notify_emprestimo_interbibliotecas_webhook(v_event_id);

      elsif new.status_global = 'em_devolucao' then
        v_event_id := public.fn_enqueue_emprestimo_interbibliotecas_notification(
          new.id,
          'interlibrary_loan_return_started',
          'return_started'
        );
        perform public.fn_notify_emprestimo_interbibliotecas_webhook(v_event_id);

      elsif new.status_global = 'devolvido' then
        v_event_id := public.fn_enqueue_emprestimo_interbibliotecas_notification(
          new.id,
          'interlibrary_loan_returned',
          'returned'
        );
        perform public.fn_notify_emprestimo_interbibliotecas_webhook(v_event_id);

      elsif new.status_global = 'parcialmente_devolvido' then
        v_event_id := public.fn_enqueue_emprestimo_interbibliotecas_notification(
          new.id,
          'interlibrary_loan_partially_returned',
          'partially_returned'
        );
        perform public.fn_notify_emprestimo_interbibliotecas_webhook(v_event_id);

      elsif new.status_global = 'cancelado' then
        v_event_id := public.fn_enqueue_emprestimo_interbibliotecas_notification(
          new.id,
          'interlibrary_loan_cancelled',
          'cancelled'
        );
        perform public.fn_notify_emprestimo_interbibliotecas_webhook(v_event_id);

      elsif new.status_global = 'atrasado' then
        v_event_id := public.fn_enqueue_emprestimo_interbibliotecas_notification(
          new.id,
          'interlibrary_loan_overdue',
          'overdue'
        );
        perform public.fn_notify_emprestimo_interbibliotecas_webhook(v_event_id);
      end if;
    end if;

    return new;
  end if;

  return new;
end;
$$;


ALTER FUNCTION "public"."trg_interlibrary_loan_enqueue_notifications"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."trg_notify_consulta_lifecycle"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $_$
DECLARE
  v_event text;
  v_flag_column text;
  v_enabled boolean;
  v_library_id uuid;
  v_local_consultation_enabled boolean;
  v_cancelled_by text;
  v_payload jsonb;
  v_workflow_note text;
BEGIN
  v_event := NULL;
  v_flag_column := NULL;
  v_cancelled_by := NULL;

  IF TG_OP = 'INSERT' AND NEW.item_status = 'ativa' THEN
    v_event := 'consulta_v2_criada';
    v_flag_column := 'consulta_mail_criada_enabled';

  ELSIF TG_OP = 'UPDATE'
        AND OLD.item_status IS DISTINCT FROM NEW.item_status
        AND OLD.item_status = 'ativa' THEN

    IF NEW.item_status = 'consultada' THEN
      v_event := 'consulta_v2_realizada';
      v_flag_column := 'consulta_mail_realizada_enabled';

    ELSIF NEW.item_status = 'cancelada_leitor' THEN
      v_event := 'consulta_v2_cancelada';
      v_flag_column := 'consulta_mail_cancelada_enabled';
      v_cancelled_by := 'leitor';

    ELSIF NEW.item_status = 'cancelada_biblioteca' THEN
      v_event := 'consulta_v2_cancelada';
      v_flag_column := 'consulta_mail_cancelada_enabled';
      v_cancelled_by := 'biblioteca';

    ELSIF NEW.item_status = 'expirada' THEN
      v_event := 'consulta_v2_expirada';
      v_flag_column := 'consulta_mail_expirada_enabled';
    END IF;
  END IF;

  IF v_event IS NULL THEN
    RETURN NEW;
  END IF;

  SELECT cl.library_id INTO v_library_id
  FROM public.consultas_locais_v2 cl
  WHERE cl.id = NEW.consulta_id;

  v_local_consultation_enabled := true;
  IF v_library_id IS NOT NULL THEN
    SELECT local_consultation_enabled INTO v_local_consultation_enabled
    FROM public.library_notification_policies
    WHERE library_id = v_library_id;
    v_local_consultation_enabled := COALESCE(v_local_consultation_enabled, true);
  END IF;

  IF NOT v_local_consultation_enabled THEN
    RETURN NEW;
  END IF;

  v_enabled := true;
  IF v_library_id IS NOT NULL AND v_flag_column IS NOT NULL THEN
    EXECUTE format(
      'SELECT %I FROM public.library_notification_policies WHERE library_id = $1',
      v_flag_column
    ) INTO v_enabled USING v_library_id;
    v_enabled := COALESCE(v_enabled, true);
  END IF;

  IF NOT v_enabled THEN
    RETURN NEW;
  END IF;

  -- B3 généralisé : récupérer workflow_note via JOIN
  SELECT workflow_note INTO v_workflow_note
  FROM public.consulta_item_workflow_v2
  WHERE consulta_id = NEW.consulta_id AND line_no = NEW.line_no;

  v_payload := jsonb_build_object('line_nos', jsonb_build_array(NEW.line_no));
  IF v_cancelled_by IS NOT NULL THEN
    v_payload := v_payload || jsonb_build_object('cancelled_by', v_cancelled_by);
  END IF;
  IF v_workflow_note IS NOT NULL AND trim(v_workflow_note) <> '' THEN
    v_payload := v_payload || jsonb_build_object('workflow_note', v_workflow_note);
  END IF;

  PERFORM public.fn_dispatch_notify_event(
    v_event,
    NEW.consulta_id,
    v_payload
  );

  RETURN NEW;
END;
$_$;


ALTER FUNCTION "public"."trg_notify_consulta_lifecycle"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."trg_notify_consulta_lifecycle"() IS 'Trigger émet events lifecycle consulta_v2_* sur changements item_status de consulta_linhas_v2. v2 (15/05/2026) : propagation workflow_note via JOIN sur consulta_item_workflow_v2 (fix B3 généralisé). Cf. spec consultas v2.1 §11.2.';



CREATE OR REPLACE FUNCTION "public"."trg_notify_consulta_workflow"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $_$
DECLARE
  v_event text;
  v_flag_column text;
  v_enabled boolean;
  v_library_id uuid;
  v_local_consultation_enabled boolean;
  v_payload jsonb;
  v_emit_em_preparacao boolean := false;
  v_emit_agendada boolean := false;
  v_emit_resposta boolean := false;
  v_emit_nao_compareceu boolean := false;
BEGIN
  -- B2 : Transition workflow_stage -> em_preparacao
  IF TG_OP = 'UPDATE'
     AND NEW.workflow_stage = 'em_preparacao'
     AND OLD.workflow_stage IS DISTINCT FROM NEW.workflow_stage
  THEN
    v_emit_em_preparacao := true;
  END IF;

  -- Transition workflow_stage -> consulta_agendada
  IF (TG_OP = 'INSERT' AND NEW.workflow_stage = 'consulta_agendada')
     OR (TG_OP = 'UPDATE'
         AND NEW.workflow_stage = 'consulta_agendada'
         AND (OLD.workflow_stage IS DISTINCT FROM NEW.workflow_stage
              OR OLD.consultation_starts_at IS DISTINCT FROM NEW.consultation_starts_at
              OR OLD.consultation_ends_at IS DISTINCT FROM NEW.consultation_ends_at))
  THEN
    v_emit_agendada := true;
  END IF;

  -- B5 : Transition workflow_stage -> nao_compareceu
  IF TG_OP = 'UPDATE'
     AND NEW.workflow_stage = 'nao_compareceu'
     AND OLD.workflow_stage IS DISTINCT FROM NEW.workflow_stage
  THEN
    v_emit_nao_compareceu := true;
  END IF;

  -- Transition schedule_reply_status -> confirmado / recusado
  IF TG_OP = 'UPDATE'
     AND OLD.schedule_reply_status IS DISTINCT FROM NEW.schedule_reply_status
     AND NEW.schedule_reply_status IN ('confirmado_leitor', 'recusado_leitor')
  THEN
    v_emit_resposta := true;
  END IF;

  IF NOT v_emit_em_preparacao AND NOT v_emit_agendada 
     AND NOT v_emit_resposta AND NOT v_emit_nao_compareceu THEN
    RETURN NEW;
  END IF;

  SELECT cl.library_id INTO v_library_id
  FROM public.consultas_locais_v2 cl
  WHERE cl.id = NEW.consulta_id;

  v_local_consultation_enabled := true;
  IF v_library_id IS NOT NULL THEN
    SELECT local_consultation_enabled INTO v_local_consultation_enabled
    FROM public.library_notification_policies
    WHERE library_id = v_library_id;
    v_local_consultation_enabled := COALESCE(v_local_consultation_enabled, true);
  END IF;

  IF NOT v_local_consultation_enabled THEN
    RETURN NEW;
  END IF;

  -- Emission 1 : consulta_v2_em_preparacao (B2)
  IF v_emit_em_preparacao THEN
    v_flag_column := 'consulta_mail_em_preparacao_enabled';
    v_event := 'consulta_v2_em_preparacao';
    v_enabled := true;
    IF v_library_id IS NOT NULL THEN
      EXECUTE format('SELECT %I FROM public.library_notification_policies WHERE library_id = $1', v_flag_column) 
        INTO v_enabled USING v_library_id;
      v_enabled := COALESCE(v_enabled, true);
    END IF;
    IF v_enabled THEN
      v_payload := jsonb_build_object('line_nos', jsonb_build_array(NEW.line_no));
      IF NEW.workflow_note IS NOT NULL AND trim(NEW.workflow_note) <> '' THEN
        v_payload := v_payload || jsonb_build_object('workflow_note', NEW.workflow_note);
      END IF;
      PERFORM public.fn_dispatch_notify_event(v_event, NEW.consulta_id, v_payload);
    END IF;
  END IF;

  -- Emission 2 : consulta_v2_agendada
  IF v_emit_agendada THEN
    v_flag_column := 'consulta_mail_agendada_enabled';
    v_event := 'consulta_v2_agendada';
    v_enabled := true;
    IF v_library_id IS NOT NULL THEN
      EXECUTE format('SELECT %I FROM public.library_notification_policies WHERE library_id = $1', v_flag_column)
        INTO v_enabled USING v_library_id;
      v_enabled := COALESCE(v_enabled, true);
    END IF;
    IF v_enabled THEN
      v_payload := jsonb_build_object(
        'line_nos', jsonb_build_array(NEW.line_no),
        'consultation_starts_at', NEW.consultation_starts_at,
        'consultation_ends_at',   NEW.consultation_ends_at
      );
      IF NEW.workflow_note IS NOT NULL AND trim(NEW.workflow_note) <> '' THEN
        v_payload := v_payload || jsonb_build_object('workflow_note', NEW.workflow_note);
      END IF;
      PERFORM public.fn_dispatch_notify_event(v_event, NEW.consulta_id, v_payload);
    END IF;
  END IF;

  -- Emission 3 : consulta_v2_nao_compareceu (B5)
  IF v_emit_nao_compareceu THEN
    v_flag_column := 'consulta_mail_nao_compareceu_enabled';
    v_event := 'consulta_v2_nao_compareceu';
    v_enabled := true;
    IF v_library_id IS NOT NULL THEN
      EXECUTE format('SELECT %I FROM public.library_notification_policies WHERE library_id = $1', v_flag_column)
        INTO v_enabled USING v_library_id;
      v_enabled := COALESCE(v_enabled, true);
    END IF;
    IF v_enabled THEN
      v_payload := jsonb_build_object(
        'line_nos', jsonb_build_array(NEW.line_no),
        'consultation_starts_at', NEW.consultation_starts_at
      );
      IF NEW.workflow_note IS NOT NULL AND trim(NEW.workflow_note) <> '' THEN
        v_payload := v_payload || jsonb_build_object('workflow_note', NEW.workflow_note);
      END IF;
      PERFORM public.fn_dispatch_notify_event(v_event, NEW.consulta_id, v_payload);
    END IF;
  END IF;

  -- Emission 4 : consulta_v2_resposta_creneau (fix B3 : propage schedule_reply_note)
  IF v_emit_resposta THEN
    v_flag_column := 'consulta_mail_resposta_creneau_enabled';
    v_event := 'consulta_v2_resposta_creneau';
    v_enabled := true;
    IF v_library_id IS NOT NULL THEN
      EXECUTE format('SELECT %I FROM public.library_notification_policies WHERE library_id = $1', v_flag_column)
        INTO v_enabled USING v_library_id;
      v_enabled := COALESCE(v_enabled, true);
    END IF;
    IF v_enabled THEN
      v_payload := jsonb_build_object(
        'line_nos', jsonb_build_array(NEW.line_no),
        'schedule_reply_status', NEW.schedule_reply_status
      );
      -- Paquet 141.2.E (16/05/2026) : Fix B3.
      -- Le motif du refus par le lecteur est dans NEW.schedule_reply_note,
      -- pas dans NEW.workflow_note. On propage les 2 (workflow_note pour
      -- compatibilite avec doctrine generale, schedule_reply_note pour
      -- le motif specifique du refus).
      IF NEW.workflow_note IS NOT NULL AND trim(NEW.workflow_note) <> '' THEN
        v_payload := v_payload || jsonb_build_object('workflow_note', NEW.workflow_note);
      END IF;
      IF NEW.schedule_reply_note IS NOT NULL AND trim(NEW.schedule_reply_note) <> '' THEN
        v_payload := v_payload || jsonb_build_object('schedule_reply_note', NEW.schedule_reply_note);
      END IF;
      PERFORM public.fn_dispatch_notify_event(v_event, NEW.consulta_id, v_payload);
    END IF;
  END IF;

  RETURN NEW;
END;
$_$;


ALTER FUNCTION "public"."trg_notify_consulta_workflow"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."trg_notify_consulta_workflow"() IS 'Trigger workflow consultas v2. v3 (16/05/2026) : propage schedule_reply_note dans payload consulta_v2_resposta_creneau (Fix B3 motif refus lecteur).';



CREATE OR REPLACE FUNCTION "public"."trg_notify_emprestimo_lifecycle"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF TG_OP = 'INSERT' THEN
    PERFORM fn_dispatch_notify_event('emprestimo_v2_criado', NEW.emprestimo_id);
  ELSIF TG_OP = 'UPDATE' AND OLD.item_status = 'aberto' AND NEW.item_status = 'devolvido' THEN
    PERFORM fn_dispatch_notify_event('emprestimo_v2_devolvido', NEW.emprestimo_id);
  END IF;
  RETURN NEW;
END;
$$;


