CREATE OR REPLACE FUNCTION "public"."update_exemplar_labels"("p_exemplar_id" "uuid", "p_label_author" "text" DEFAULT NULL::"text", "p_label_title" "text" DEFAULT NULL::"text", "p_label_cdd" "text" DEFAULT NULL::"text", "p_label_note" "text" DEFAULT NULL::"text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_library_id uuid;
BEGIN
  -- Recuperer la bibliotheque de l'exemplaire
  SELECT e.library_id INTO v_library_id
    FROM public.exemplares e
   WHERE e.id = p_exemplar_id;

  IF v_library_id IS NULL THEN
    RAISE EXCEPTION 'Exemplaire introuvable.'
      USING HINT = 'error.exemplar.not_found';
  END IF;

  -- Garde-fou staff
  IF NOT public.user_has_library_staff_role(auth.uid(), v_library_id) THEN
    RAISE EXCEPTION 'Acesso restrito ao staff da biblioteca.'
      USING ERRCODE = '42501';
  END IF;

  -- Mise a jour SELECTIVE : seuls les parametres non-NULL sont ecrits.
  -- NULL = « ne pas toucher » ; '' = « effacer l'override → retour au
  -- libelle automatique » (la vue v_exemplar_labels fait NULLIF(override,'')
  -- → fallback sur la valeur de base du livre).
  UPDATE public.exemplares
     SET label_author_override = CASE WHEN p_label_author IS NOT NULL THEN p_label_author ELSE label_author_override END,
         label_title_override  = CASE WHEN p_label_title  IS NOT NULL THEN p_label_title  ELSE label_title_override  END,
         label_cdd_override    = CASE WHEN p_label_cdd    IS NOT NULL THEN p_label_cdd    ELSE label_cdd_override    END,
         label_note            = CASE WHEN p_label_note   IS NOT NULL THEN p_label_note   ELSE label_note            END,
         updated_at            = now()
   WHERE id = p_exemplar_id;
END;
$$;


ALTER FUNCTION "public"."update_exemplar_labels"("p_exemplar_id" "uuid", "p_label_author" "text", "p_label_title" "text", "p_label_cdd" "text", "p_label_note" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."upsert_book_catalog_context_from_marc_json"("p_book_id" bigint) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_marc jsonb;
  v_acq jsonb;
  v_prov jsonb;
  v_net jsonb;
  v_source_draft_id bigint;
begin
  select coalesce(b.marc_json, '{}'::jsonb)
    into v_marc
  from public.books b
  where b.id = p_book_id;

  if not found then
    delete from public.book_catalog_context
    where book_id = p_book_id;
    return;
  end if;

  select bd.id
    into v_source_draft_id
  from public.book_drafts bd
  where bd.published_book_id = p_book_id
  order by bd.id desc
  limit 1;

  v_acq := public.catalog_bridge_block(v_marc, 'anarbib_acquisition');
  v_prov := public.catalog_bridge_block(v_marc, 'anarbib_provenance');
  v_net := public.catalog_bridge_block(v_marc, 'anarbib_network');

  insert into public.book_catalog_context (
    book_id,
    source_draft_id,
    acquisition_mode_code,
    acquisition_date,
    acquisition_source_label,
    acquisition_batch_label,
    owner_library_id,
    owner_library_label,
    holder_library_id,
    holder_library_label,
    mutualization_status_code,
    source_partner_code,
    source_system_code,
    source_record_id,
    source_record_url,
    source_format_code,
    import_method_code,
    imported_at,
    last_synced_at,
    provenance_note,
    review_status_code,
    confidence_level_code
  )
  values (
    p_book_id,
    v_source_draft_id,
    coalesce(
      public.catalog_bridge_text(v_acq, 'acquisition_mode'),
      public.catalog_bridge_text(v_acq, 'entry_mode')
    ),
    public.catalog_bridge_date(v_acq, 'acquisition_date'),
    public.catalog_bridge_text(v_acq, 'source_label'),
    coalesce(
      public.catalog_bridge_text(v_acq, 'acquisition_batch_label'),
      public.catalog_bridge_text(v_acq, 'entry_batch_label')
    ),
    null,
    public.catalog_bridge_text(v_acq, 'owner_library'),
    null,
    public.catalog_bridge_text(v_acq, 'holder_library'),
    public.catalog_bridge_text(v_net, 'mutualization_status'),
    coalesce(
      public.catalog_bridge_text(v_prov, 'source_partner'),
      public.catalog_bridge_text(v_prov, 'partner_source')
    ),
    public.catalog_bridge_text(v_prov, 'source_system'),
    public.catalog_bridge_text(v_prov, 'source_record_id'),
    public.catalog_bridge_text(v_prov, 'source_record_url'),
    coalesce(
      public.catalog_bridge_text(v_prov, 'source_format'),
      public.catalog_bridge_text(v_prov, 'import_format')
    ),
    public.catalog_bridge_text(v_prov, 'import_method'),
    public.catalog_bridge_timestamptz(v_prov, 'imported_at'),
    public.catalog_bridge_timestamptz(v_prov, 'last_synced_at'),
    public.catalog_bridge_text(v_prov, 'provenance_note'),
    public.catalog_bridge_text(v_prov, 'review_status'),
    public.catalog_bridge_text(v_prov, 'confidence_level')
  )
  on conflict (book_id) do update
  set source_draft_id           = excluded.source_draft_id,
      acquisition_mode_code     = excluded.acquisition_mode_code,
      acquisition_date          = excluded.acquisition_date,
      acquisition_source_label  = excluded.acquisition_source_label,
      acquisition_batch_label   = excluded.acquisition_batch_label,
      owner_library_label       = excluded.owner_library_label,
      holder_library_label      = excluded.holder_library_label,
      mutualization_status_code = excluded.mutualization_status_code,
      source_partner_code       = excluded.source_partner_code,
      source_system_code        = excluded.source_system_code,
      source_record_id          = excluded.source_record_id,
      source_record_url         = excluded.source_record_url,
      source_format_code        = excluded.source_format_code,
      import_method_code        = excluded.import_method_code,
      imported_at               = excluded.imported_at,
      last_synced_at            = excluded.last_synced_at,
      provenance_note           = excluded.provenance_note,
      review_status_code        = excluded.review_status_code,
      confidence_level_code     = excluded.confidence_level_code,
      updated_at                = now();
end;
$$;


ALTER FUNCTION "public"."upsert_book_catalog_context_from_marc_json"("p_book_id" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."upsert_book_draft_catalog_context_from_marc_json"("p_book_draft_id" bigint) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_marc jsonb;
  v_acq jsonb;
  v_prov jsonb;
  v_net jsonb;
begin
  select coalesce(bd.marc_json, '{}'::jsonb)
    into v_marc
  from public.book_drafts bd
