  end if;

  v_acq := public.catalog_bridge_block(v_marc, 'anarbib_acquisition');
  v_prov := public.catalog_bridge_block(v_marc, 'anarbib_provenance');
  v_net := public.catalog_bridge_block(v_marc, 'anarbib_network');

  insert into public.book_draft_catalog_context (
    book_draft_id,
    acquisition_mode_code,
    acquisition_date,
    acquisition_source_label,
    acquisition_batch_label,
    owner_library_id,
    owner_library_label,
    holder_library_id,
    holder_library_label,
    mutualization_status_code,
    source_partner_code,
    source_system_code,
    source_record_id,
    source_record_url,
    source_format_code,
    import_method_code,
    imported_at,
    last_synced_at,
    provenance_note,
    review_status_code,
    confidence_level_code
  )
  values (
    p_book_draft_id,
    coalesce(
      public.catalog_bridge_text(v_acq, 'acquisition_mode'),
      public.catalog_bridge_text(v_acq, 'entry_mode')
    ),
    public.catalog_bridge_date(v_acq, 'acquisition_date'),
    public.catalog_bridge_text(v_acq, 'source_label'),
    coalesce(
      public.catalog_bridge_text(v_acq, 'acquisition_batch_label'),
      public.catalog_bridge_text(v_acq, 'entry_batch_label')
    ),
    null,
    public.catalog_bridge_text(v_acq, 'owner_library'),
    null,
    public.catalog_bridge_text(v_acq, 'holder_library'),
    public.catalog_bridge_text(v_net, 'mutualization_status'),
    coalesce(
      public.catalog_bridge_text(v_prov, 'source_partner'),
      public.catalog_bridge_text(v_prov, 'partner_source')
    ),
    public.catalog_bridge_text(v_prov, 'source_system'),
    public.catalog_bridge_text(v_prov, 'source_record_id'),
    public.catalog_bridge_text(v_prov, 'source_record_url'),
    coalesce(
      public.catalog_bridge_text(v_prov, 'source_format'),
      public.catalog_bridge_text(v_prov, 'import_format')
    ),
    public.catalog_bridge_text(v_prov, 'import_method'),
    public.catalog_bridge_timestamptz(v_prov, 'imported_at'),
    public.catalog_bridge_timestamptz(v_prov, 'last_synced_at'),
    public.catalog_bridge_text(v_prov, 'provenance_note'),
    public.catalog_bridge_text(v_prov, 'review_status'),
    public.catalog_bridge_text(v_prov, 'confidence_level')
  )
  on conflict (book_draft_id) do update
  set acquisition_mode_code     = excluded.acquisition_mode_code,
      acquisition_date          = excluded.acquisition_date,
      acquisition_source_label  = excluded.acquisition_source_label,
      acquisition_batch_label   = excluded.acquisition_batch_label,
      owner_library_label       = excluded.owner_library_label,
      holder_library_label      = excluded.holder_library_label,
      mutualization_status_code = excluded.mutualization_status_code,
      source_partner_code       = excluded.source_partner_code,
      source_system_code        = excluded.source_system_code,
      source_record_id          = excluded.source_record_id,
      source_record_url         = excluded.source_record_url,
      source_format_code        = excluded.source_format_code,
      import_method_code        = excluded.import_method_code,
      imported_at               = excluded.imported_at,
      last_synced_at            = excluded.last_synced_at,
      provenance_note           = excluded.provenance_note,
      review_status_code        = excluded.review_status_code,
      confidence_level_code     = excluded.confidence_level_code,
      updated_at                = now();
end;
$$;


ALTER FUNCTION "public"."upsert_book_draft_catalog_context_from_marc_json"("p_book_draft_id" bigint) OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."library_circulation_policy_rules" (
    "id" bigint NOT NULL,
    "policy_set_id" bigint NOT NULL,
    "priority" integer DEFAULT 100 NOT NULL,
    "is_active" boolean DEFAULT true NOT NULL,
    "rule_label" "text" NOT NULL,
    "circulation_mode" "text" NOT NULL,
    "material_scope" "text" DEFAULT 'any'::"text" NOT NULL,
    "reader_scope" "text" DEFAULT 'any'::"text" NOT NULL,
    "quantity_min" integer DEFAULT 1 NOT NULL,
    "quantity_max" integer,
    "loan_allowed" boolean DEFAULT true NOT NULL,
    "reservation_allowed" boolean DEFAULT true NOT NULL,
    "consultation_allowed" boolean DEFAULT true NOT NULL,
    "consultation_only" boolean DEFAULT false NOT NULL,
    "renewable" boolean DEFAULT true NOT NULL,
    "renewal_max_count" integer,
    "renewal_days" integer,
    "loan_days" integer,
    "manual_review_required" boolean DEFAULT false NOT NULL,
    "non_extendable_reason" "text",
    "exception_code" "text",
    "public_note" "text",
    "internal_note" "text",
    "applies_when" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "metadata" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "created_by" "uuid",
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_by" "uuid",
    "system_seed_key" "text",
    CONSTRAINT "library_circulation_policy_rules_circulation_mode_chk" CHECK (("circulation_mode" = ANY (ARRAY['loan'::"text", 'renewal'::"text", 'reservation'::"text", 'local_consultation'::"text"]))),
    CONSTRAINT "library_circulation_policy_rules_loan_days_chk" CHECK ((("loan_days" IS NULL) OR ("loan_days" >= 0))),
    CONSTRAINT "library_circulation_policy_rules_material_scope_chk" CHECK (("material_scope" = ANY (ARRAY['any'::"text", 'book'::"text", 'periodical'::"text", 'zine'::"text", 'pamphlet'::"text", 'archive'::"text", 'audio'::"text", 'audiovisual'::"text", 'digital_native'::"text", 'other'::"text"]))),
    CONSTRAINT "library_circulation_policy_rules_priority_chk" CHECK (("priority" >= 0)),
    CONSTRAINT "library_circulation_policy_rules_quantity_max_chk" CHECK ((("quantity_max" IS NULL) OR ("quantity_max" >= "quantity_min"))),
    CONSTRAINT "library_circulation_policy_rules_quantity_min_chk" CHECK (("quantity_min" >= 1)),
    CONSTRAINT "library_circulation_policy_rules_reader_scope_chk" CHECK (("reader_scope" = ANY (ARRAY['any'::"text", 'local_member'::"text", 'network_member'::"text", 'non_member'::"text", 'restricted'::"text", 'librarian'::"text", 'internal'::"text"]))),
    CONSTRAINT "library_circulation_policy_rules_renewal_days_chk" CHECK ((("renewal_days" IS NULL) OR ("renewal_days" >= 0))),
    CONSTRAINT "library_circulation_policy_rules_renewal_max_count_chk" CHECK ((("renewal_max_count" IS NULL) OR ("renewal_max_count" >= 0))),
    CONSTRAINT "library_circulation_policy_rules_rule_label_chk" CHECK (("length"(TRIM(BOTH FROM "rule_label")) > 0))
);


ALTER TABLE "public"."library_circulation_policy_rules" OWNER TO "postgres";


COMMENT ON TABLE "public"."library_circulation_policy_rules" IS 'Règles de circulation (durée, max prêts). Lecture publique des règles actives sur sets actifs (restauré le 2026-04-27 après palier 4 erroné).';



COMMENT ON COLUMN "public"."library_circulation_policy_rules"."priority" IS 'Ordre de résolution : plus petit = plus prioritaire. Permet des exceptions avant les règles générales.';



COMMENT ON COLUMN "public"."library_circulation_policy_rules"."material_scope" IS 'Portée documentaire minimale de la règle. any pour la règle générale, puis déclinaisons par type de document.';



COMMENT ON COLUMN "public"."library_circulation_policy_rules"."reader_scope" IS 'Portée du lectorat : inscrit local, membre du réseau, non-inscrit, etc.';



COMMENT ON COLUMN "public"."library_circulation_policy_rules"."quantity_min" IS 'Borne basse de quantité dans le lot ou la demande.';



COMMENT ON COLUMN "public"."library_circulation_policy_rules"."quantity_max" IS 'Borne haute optionnelle de quantité dans le lot ou la demande. NULL = sans borne supérieure.';



COMMENT ON COLUMN "public"."library_circulation_policy_rules"."consultation_only" IS 'Si vrai, la règle autorise seulement la consultation locale et bloque le prêt externe.';



COMMENT ON COLUMN "public"."library_circulation_policy_rules"."applies_when" IS 'Conditions complémentaires futures en JSONB : catégories, holdings spécifiques, cas militants, exceptions locales, etc.';



COMMENT ON COLUMN "public"."library_circulation_policy_rules"."system_seed_key" IS 'Identifiant système d''une règle seed (ex: "base_legada_loan_1_item"). Quand non-NULL, le frontend traduit rule_label/public_note via i18n applicative.';



CREATE OR REPLACE FUNCTION "public"."upsert_library_circulation_policy_rule"("p_policy_set_id" bigint, "p_rule" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "public"."library_circulation_policy_rules"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'auth', 'pg_temp'
    AS $$
declare
  v_policy_set public.library_circulation_policy_sets%rowtype;
  v_rule jsonb := coalesce(p_rule, '{}'::jsonb);
  v_id bigint := nullif(trim(coalesce(v_rule->>'id', '')), '')::bigint;
  v_existing public.library_circulation_policy_rules%rowtype;
  v_row public.library_circulation_policy_rules;
begin
  if auth.uid() is null then
    raise exception 'authentication required';
  end if;

  select *
    into v_policy_set
  from public.library_circulation_policy_sets s
  where s.id = p_policy_set_id;

  if v_policy_set.id is null then
    raise exception 'Conjunto de regras não encontrado: %', p_policy_set_id;
  end if;

  if not public.can_manage_library_circulation_policies(v_policy_set.library_id) then
    raise exception 'permission denied for library_circulation_policy_rules';
  end if;

  if v_id is not null then
    select *
      into v_existing
    from public.library_circulation_policy_rules r
    where r.id = v_id;

    if v_existing.id is null then
      raise exception 'Regra de circulação não encontrada: %', v_id;
    end if;

    if v_existing.policy_set_id <> p_policy_set_id then
      raise exception 'A regra informada pertence a outro conjunto.';
    end if;
  end if;

  if v_existing.id is null then
    insert into public.library_circulation_policy_rules (
      policy_set_id,
      priority,
      is_active,
      rule_label,
      circulation_mode,
      material_scope,
      reader_scope,
      quantity_min,
      quantity_max,
      loan_allowed,
      reservation_allowed,
      consultation_allowed,
      consultation_only,
      renewable,
      renewal_max_count,
      renewal_days,
      loan_days,
      manual_review_required,
      non_extendable_reason,
      exception_code,
      public_note,
      internal_note,
      applies_when,
      metadata,
      created_by,
      updated_by
    )
    values (
      p_policy_set_id,
      greatest(coalesce((v_rule->>'priority')::integer, 100), 0),
      coalesce((v_rule->>'is_active')::boolean, true),
      coalesce(nullif(trim(coalesce(v_rule->>'rule_label', '')), ''), 'Nova regra'),
      coalesce(nullif(trim(coalesce(v_rule->>'circulation_mode', '')), ''), 'loan'),
      coalesce(nullif(trim(coalesce(v_rule->>'material_scope', '')), ''), 'any'),
      coalesce(nullif(trim(coalesce(v_rule->>'reader_scope', '')), ''), 'any'),
      greatest(coalesce((v_rule->>'quantity_min')::integer, 1), 1),
      case when nullif(trim(coalesce(v_rule->>'quantity_max', '')), '') is null then null else (v_rule->>'quantity_max')::integer end,
      coalesce((v_rule->>'loan_allowed')::boolean, true),
      coalesce((v_rule->>'reservation_allowed')::boolean, true),
      coalesce((v_rule->>'consultation_allowed')::boolean, true),
      coalesce((v_rule->>'consultation_only')::boolean, false),
      coalesce((v_rule->>'renewable')::boolean, true),
      case when nullif(trim(coalesce(v_rule->>'renewal_max_count', '')), '') is null then null else (v_rule->>'renewal_max_count')::integer end,
      case when nullif(trim(coalesce(v_rule->>'renewal_days', '')), '') is null then null else (v_rule->>'renewal_days')::integer end,
      case when nullif(trim(coalesce(v_rule->>'loan_days', '')), '') is null then null else (v_rule->>'loan_days')::integer end,
      coalesce((v_rule->>'manual_review_required')::boolean, false),
      nullif(trim(coalesce(v_rule->>'non_extendable_reason', '')), ''),
      nullif(trim(coalesce(v_rule->>'exception_code', '')), ''),
      nullif(trim(coalesce(v_rule->>'public_note', '')), ''),
      nullif(trim(coalesce(v_rule->>'internal_note', '')), ''),
      coalesce(v_rule->'applies_when', '{}'::jsonb),
      coalesce(v_rule->'metadata', '{}'::jsonb),
      auth.uid(),
      auth.uid()
    )
    returning * into v_row;
  else
    update public.library_circulation_policy_rules r
       set priority = greatest(coalesce((v_rule->>'priority')::integer, r.priority), 0),
           is_active = coalesce((v_rule->>'is_active')::boolean, r.is_active),
           rule_label = coalesce(nullif(trim(coalesce(v_rule->>'rule_label', '')), ''), r.rule_label),
           circulation_mode = coalesce(nullif(trim(coalesce(v_rule->>'circulation_mode', '')), ''), r.circulation_mode),
           material_scope = coalesce(nullif(trim(coalesce(v_rule->>'material_scope', '')), ''), r.material_scope),
           reader_scope = coalesce(nullif(trim(coalesce(v_rule->>'reader_scope', '')), ''), r.reader_scope),
           quantity_min = greatest(coalesce((v_rule->>'quantity_min')::integer, r.quantity_min), 1),
           quantity_max = case
             when v_rule ? 'quantity_max' then case when nullif(trim(coalesce(v_rule->>'quantity_max', '')), '') is null then null else (v_rule->>'quantity_max')::integer end
             else r.quantity_max
           end,
           loan_allowed = coalesce((v_rule->>'loan_allowed')::boolean, r.loan_allowed),
           reservation_allowed = coalesce((v_rule->>'reservation_allowed')::boolean, r.reservation_allowed),
           consultation_allowed = coalesce((v_rule->>'consultation_allowed')::boolean, r.consultation_allowed),
           consultation_only = coalesce((v_rule->>'consultation_only')::boolean, r.consultation_only),
           renewable = coalesce((v_rule->>'renewable')::boolean, r.renewable),
           renewal_max_count = case
             when v_rule ? 'renewal_max_count' then case when nullif(trim(coalesce(v_rule->>'renewal_max_count', '')), '') is null then null else (v_rule->>'renewal_max_count')::integer end
             else r.renewal_max_count
           end,
           renewal_days = case
             when v_rule ? 'renewal_days' then case when nullif(trim(coalesce(v_rule->>'renewal_days', '')), '') is null then null else (v_rule->>'renewal_days')::integer end
             else r.renewal_days
           end,
           loan_days = case
             when v_rule ? 'loan_days' then case when nullif(trim(coalesce(v_rule->>'loan_days', '')), '') is null then null else (v_rule->>'loan_days')::integer end
             else r.loan_days
           end,
           manual_review_required = coalesce((v_rule->>'manual_review_required')::boolean, r.manual_review_required),
           non_extendable_reason = case
             when v_rule ? 'non_extendable_reason' then nullif(trim(coalesce(v_rule->>'non_extendable_reason', '')), '')
             else r.non_extendable_reason
           end,
           exception_code = case
             when v_rule ? 'exception_code' then nullif(trim(coalesce(v_rule->>'exception_code', '')), '')
             else r.exception_code
           end,
           public_note = case
             when v_rule ? 'public_note' then nullif(trim(coalesce(v_rule->>'public_note', '')), '')
             else r.public_note
           end,
           internal_note = case
             when v_rule ? 'internal_note' then nullif(trim(coalesce(v_rule->>'internal_note', '')), '')
             else r.internal_note
           end,
           applies_when = case
             when v_rule ? 'applies_when' then coalesce(v_rule->'applies_when', '{}'::jsonb)
             else r.applies_when
           end,
           metadata = case
             when v_rule ? 'metadata' then coalesce(v_rule->'metadata', '{}'::jsonb)
             else r.metadata
           end,
           updated_at = now(),
           updated_by = auth.uid()
     where r.id = v_existing.id
     returning * into v_row;
  end if;

  return v_row;
end;
$$;


ALTER FUNCTION "public"."upsert_library_circulation_policy_rule"("p_policy_set_id" bigint, "p_rule" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."upsert_library_circulation_policy_rule"("p_policy_set_id" bigint, "p_rule" "jsonb") IS 'Cria ou atualiza uma regra atomique de circulação dans un format JSONB front-friendly.';



CREATE OR REPLACE FUNCTION "public"."upsert_library_circulation_policy_set"("p_library_id" "uuid", "p_payload" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "public"."library_circulation_policy_sets"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'auth', 'pg_temp'
    AS $$
declare
  v_library_id uuid;
  v_payload jsonb := coalesce(p_payload, '{}'::jsonb);
  v_id bigint := nullif(trim(coalesce(v_payload->>'id', '')), '')::bigint;
  v_existing public.library_circulation_policy_sets%rowtype;
  v_status text;
  v_row public.library_circulation_policy_sets;
begin
  v_library_id := public.resolve_managed_library_id(p_library_id);

  if not public.can_manage_library_circulation_policies(v_library_id) then
    raise exception 'permission denied for library_circulation_policy_sets';
  end if;

  if v_id is not null then
    select *
      into v_existing
    from public.library_circulation_policy_sets s
    where s.id = v_id;

    if v_existing.id is null then
      raise exception 'Conjunto de regras não encontrado: %', v_id;
    end if;

    if v_existing.library_id <> v_library_id then
      raise exception 'Este conjunto de regras pertence a outra biblioteca.';
    end if;
  end if;

  v_status := coalesce(nullif(trim(coalesce(v_payload->>'status', '')), ''), coalesce(v_existing.status, 'draft'));
  if v_status not in ('draft', 'active', 'archived') then
    v_status := coalesce(v_existing.status, 'draft');
  end if;

  if v_existing.id is null then
    insert into public.library_circulation_policy_sets (
      library_id,
      regulation_document_id,
      label,
      status,
      is_active,
      config_version,
      effective_from,
      effective_until,
      activation_note,
      scope_note,
      metadata,
      created_by,
      updated_by,
      activated_at,
      activated_by
    )
    values (
      v_library_id,
      nullif(trim(coalesce(v_payload->>'regulation_document_id', '')), '')::bigint,
      coalesce(nullif(trim(coalesce(v_payload->>'label', '')), ''), 'Novo conjunto de regras'),
      v_status,
      false,
      greatest(coalesce((v_payload->>'config_version')::integer, 1), 1),
      case when nullif(trim(coalesce(v_payload->>'effective_from', '')), '') is null then null else (v_payload->>'effective_from')::date end,
      case when nullif(trim(coalesce(v_payload->>'effective_until', '')), '') is null then null else (v_payload->>'effective_until')::date end,
      nullif(trim(coalesce(v_payload->>'activation_note', '')), ''),
      nullif(trim(coalesce(v_payload->>'scope_note', '')), ''),
      coalesce(v_payload->'metadata', '{}'::jsonb),
      auth.uid(),
      auth.uid(),
      null,
      null
    )
    returning * into v_row;
  else
    update public.library_circulation_policy_sets s
       set regulation_document_id = case
             when v_payload ? 'regulation_document_id' then nullif(trim(coalesce(v_payload->>'regulation_document_id', '')), '')::bigint
             else s.regulation_document_id
           end,
           label = coalesce(nullif(trim(coalesce(v_payload->>'label', '')), ''), s.label),
           status = v_status,
           config_version = greatest(coalesce((v_payload->>'config_version')::integer, s.config_version), 1),
           effective_from = case
             when v_payload ? 'effective_from' then case when nullif(trim(coalesce(v_payload->>'effective_from', '')), '') is null then null else (v_payload->>'effective_from')::date end
             else s.effective_from
           end,
           effective_until = case
             when v_payload ? 'effective_until' then case when nullif(trim(coalesce(v_payload->>'effective_until', '')), '') is null then null else (v_payload->>'effective_until')::date end
             else s.effective_until
           end,
           activation_note = case
             when v_payload ? 'activation_note' then nullif(trim(coalesce(v_payload->>'activation_note', '')), '')
             else s.activation_note
           end,
           scope_note = case
             when v_payload ? 'scope_note' then nullif(trim(coalesce(v_payload->>'scope_note', '')), '')
             else s.scope_note
           end,
           metadata = case
             when v_payload ? 'metadata' then coalesce(v_payload->'metadata', '{}'::jsonb)
             else s.metadata
           end,
           updated_at = now(),
           updated_by = auth.uid()
     where s.id = v_existing.id
     returning * into v_row;
  end if;

  return v_row;
end;
$$;


