    "contact_name" "text",
    "contact_role" "text",
    "contact_email" "text",
    "contact_phone" "text",
    "contact_whatsapp" "text",
    "contact_alternate" "text",
    "postal_address" "text",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
