COMMENT ON TABLE "public"."library_contact_profiles" IS 'Profils de contact (Genoss·innen, partenaires). Anon SELECT révoqué le 2026-04-26 (palier 4).';



COMMENT ON COLUMN "public"."library_contact_profiles"."contact_name" IS 'Pessoa, equipe ou coletivo a procurar para contato institucional ou cooperação entre bibliotecas.';



COMMENT ON COLUMN "public"."library_contact_profiles"."contact_role" IS 'Função ou responsabilidade do contato principal (coordenação, circulação, biblioteca etc.).';



CREATE OR REPLACE FUNCTION "public"."upsert_library_contact_profile"("p_library_id" "uuid", "p_profile" "jsonb") RETURNS "public"."library_contact_profiles"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'auth', 'pg_temp'
    AS $$
declare
  v_row public.library_contact_profiles;
  v_profile jsonb := coalesce(p_profile, '{}'::jsonb);
begin
  if auth.uid() is null then
    raise exception 'authentication required';
  end if;

  if p_library_id is null then
    raise exception 'library_id is required';
  end if;

  if not public.can_manage_library_contact_profile(p_library_id) then
    raise exception 'permission denied for library_contact_profiles';
  end if;

  insert into public.library_contact_profiles as c (
    library_id,
    contact_name,
    contact_role,
    contact_email,
    contact_phone,
    contact_whatsapp,
    contact_alternate,
    postal_address
  )
  values (
    p_library_id,
    nullif(trim(v_profile ->> 'contact_name'), ''),
    nullif(trim(v_profile ->> 'contact_role'), ''),
    nullif(trim(v_profile ->> 'contact_email'), ''),
    nullif(trim(v_profile ->> 'contact_phone'), ''),
    nullif(trim(v_profile ->> 'contact_whatsapp'), ''),
    nullif(trim(v_profile ->> 'contact_alternate'), ''),
    nullif(trim(v_profile ->> 'postal_address'), '')
  )
  on conflict (library_id) do update
    set contact_name = excluded.contact_name,
        contact_role = excluded.contact_role,
        contact_email = excluded.contact_email,
        contact_phone = excluded.contact_phone,
        contact_whatsapp = excluded.contact_whatsapp,
        contact_alternate = excluded.contact_alternate,
        postal_address = excluded.postal_address,
        updated_at = now(),
        updated_by = auth.uid()
  returning * into v_row;

  return v_row;
end;
$$;


ALTER FUNCTION "public"."upsert_library_contact_profile"("p_library_id" "uuid", "p_profile" "jsonb") OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."library_document_governance" (
    "library_id" "uuid" NOT NULL,
    "config" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "created_by" "uuid",
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_by" "uuid"
);


ALTER TABLE "public"."library_document_governance" OWNER TO "postgres";


COMMENT ON TABLE "public"."library_document_governance" IS 'Gouvernance des documents par bibliothèque. Lecture publique (restauré le 2026-04-27 après palier 4 erroné).';



COMMENT ON COLUMN "public"."library_document_governance"."config" IS 'JSONB com as regras efetivas de governança documental da biblioteca.';



CREATE OR REPLACE FUNCTION "public"."upsert_library_document_governance"("p_library_id" "uuid", "p_config" "jsonb") RETURNS "public"."library_document_governance"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'auth', 'pg_temp'
    AS $$
declare
  v_row public.library_document_governance;
begin
  if auth.uid() is null then
    raise exception 'authentication required';
  end if;

  if p_library_id is null then
    raise exception 'library_id is required';
  end if;

  if not public.can_manage_library_document_governance(p_library_id) then
    raise exception 'permission denied for library_document_governance';
  end if;

  insert into public.library_document_governance as g (
    library_id,
    config,
    created_by,
    updated_by
  )
  values (
    p_library_id,
    coalesce(p_config, '{}'::jsonb),
    auth.uid(),
    auth.uid()
  )
  on conflict (library_id) do update
    set config = excluded.config,
        updated_at = now(),
        updated_by = auth.uid()
  returning * into v_row;

  return v_row;
end;
$$;


ALTER FUNCTION "public"."upsert_library_document_governance"("p_library_id" "uuid", "p_config" "jsonb") OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."library_mail_channels" (
    "library_id" "uuid" NOT NULL,
    "delivery_mode" "text" DEFAULT 'platform_shared'::"text" NOT NULL,
    "admin_notification_email" "text",
    "weekly_report_email" "text",
    "severe_alert_email" "text",
    "transport_state" "text" DEFAULT 'not_tested'::"text" NOT NULL,
    "transport_channel" "text",
    "last_tested_at" timestamp with time zone,
    "active" boolean DEFAULT true NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "created_by" "uuid",
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_by" "uuid",
    CONSTRAINT "library_mail_channels_delivery_mode_check" CHECK (("delivery_mode" = ANY (ARRAY['platform_shared'::"text", 'platform_shared_local_reply'::"text", 'library_own_transport'::"text", 'disabled'::"text"])))
);


ALTER TABLE "public"."library_mail_channels" OWNER TO "postgres";


COMMENT ON TABLE "public"."library_mail_channels" IS 'Canaux d''envoi email configurés. Anon SELECT révoqué le 2026-04-26 (palier 4).';



CREATE OR REPLACE FUNCTION "public"."upsert_library_mail_channel"("p_library_id" "uuid", "p_channel" "jsonb") RETURNS "public"."library_mail_channels"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_delivery_mode text;
  v_row public.library_mail_channels;
begin
  if p_library_id is null then
    raise exception 'library_id ausente';
  end if;

  if not public.user_can_manage_library_notifications(p_library_id) then
    raise exception 'Sem permissão para gerir notificações desta biblioteca';
  end if;

  v_delivery_mode := coalesce(nullif(trim(coalesce(p_channel->>'delivery_mode','')), ''), 'platform_shared');
  if v_delivery_mode not in ('platform_shared','platform_shared_local_reply','library_own_transport','disabled') then
    v_delivery_mode := 'platform_shared';
  end if;

  insert into public.library_mail_channels (
    library_id,
    delivery_mode,
    admin_notification_email,
    weekly_report_email,
    severe_alert_email,
    transport_state,
    transport_channel,
    last_tested_at,
    active,
    created_by,
    updated_by
  )
  values (
    p_library_id,
    v_delivery_mode,
    nullif(trim(coalesce(p_channel->>'admin_notification_email','')), ''),
    nullif(trim(coalesce(p_channel->>'weekly_report_email','')), ''),
    nullif(trim(coalesce(p_channel->>'severe_alert_email','')), ''),
    coalesce(nullif(trim(coalesce(p_channel->>'transport_state','')), ''), 'not_tested'),
    nullif(trim(coalesce(p_channel->>'transport_channel','')), ''),
    case
      when nullif(trim(coalesce(p_channel->>'last_tested_at','')), '') is null then null
      else (p_channel->>'last_tested_at')::timestamptz
    end,
    coalesce((p_channel->>'active')::boolean, true),
    auth.uid(),
    auth.uid()
  )
  on conflict (library_id) do update
  set delivery_mode = excluded.delivery_mode,
      admin_notification_email = excluded.admin_notification_email,
      weekly_report_email = excluded.weekly_report_email,
      severe_alert_email = excluded.severe_alert_email,
      transport_state = excluded.transport_state,
      transport_channel = excluded.transport_channel,
      last_tested_at = excluded.last_tested_at,
      active = excluded.active,
      updated_at = now(),
      updated_by = auth.uid()
  returning * into v_row;

  return v_row;
end;
$$;


ALTER FUNCTION "public"."upsert_library_mail_channel"("p_library_id" "uuid", "p_channel" "jsonb") OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."library_notification_policies" (
    "library_id" "uuid" NOT NULL,
    "reservation_created_enabled" boolean DEFAULT true NOT NULL,
    "reservation_status_enabled" boolean DEFAULT true NOT NULL,
    "reservation_workflow_enabled" boolean DEFAULT true NOT NULL,
    "local_consultation_enabled" boolean DEFAULT true NOT NULL,
    "loan_lifecycle_enabled" boolean DEFAULT true NOT NULL,
    "loan_reminders_enabled" boolean DEFAULT true NOT NULL,
    "loan_overdue_enabled" boolean DEFAULT true NOT NULL,
    "profile_restriction_enabled" boolean DEFAULT true NOT NULL,
    "mid_loan_message_enabled" boolean DEFAULT false NOT NULL,
    "reading_recommendations_enabled" boolean DEFAULT false NOT NULL,
    "admin_copy_reservations_enabled" boolean DEFAULT true NOT NULL,
    "admin_copy_loans_enabled" boolean DEFAULT true NOT NULL,
    "tech_alerts_enabled" boolean DEFAULT true NOT NULL,
    "task_alerts_enabled" boolean DEFAULT true NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "created_by" "uuid",
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_by" "uuid",
    "reservation_solicitada_timeout_days" integer DEFAULT 14 NOT NULL,
    "reservation_no_show_timeout_hours" integer DEFAULT 24 NOT NULL,
    "reservation_mail_solicitada_enabled" boolean DEFAULT true NOT NULL,
    "reservation_mail_em_preparacao_enabled" boolean DEFAULT true NOT NULL,
    "reservation_mail_retirada_agendada_enabled" boolean DEFAULT true NOT NULL,
    "reservation_mail_retirada_a_combinar_enabled" boolean DEFAULT true NOT NULL,
    "reservation_mail_pronta_para_retirada_enabled" boolean DEFAULT true NOT NULL,
    "reservation_mail_retirada_reagendada_enabled" boolean DEFAULT true NOT NULL,
    "reservation_mail_retirada_no_show_enabled" boolean DEFAULT true NOT NULL,
    "reservation_mail_expirada_enabled" boolean DEFAULT true NOT NULL,
    "reservation_mail_cancelada_leitor_enabled" boolean DEFAULT true NOT NULL,
    "reservation_mail_cancelada_biblioteca_enabled" boolean DEFAULT true NOT NULL,
    "reservation_mail_liberada_para_circulacao_enabled" boolean DEFAULT false NOT NULL,
    "reservation_mail_retirada_efetivada_enabled" boolean DEFAULT true NOT NULL,
    "reservation_allow_reader_counter_proposal" boolean DEFAULT true NOT NULL,
    "reservation_negotiation_timeout_days" integer DEFAULT 21 NOT NULL,
    "consulta_mail_criada_enabled" boolean DEFAULT true NOT NULL,
    "consulta_mail_agendada_enabled" boolean DEFAULT true NOT NULL,
    "consulta_mail_resposta_creneau_enabled" boolean DEFAULT true NOT NULL,
    "consulta_mail_realizada_enabled" boolean DEFAULT false NOT NULL,
    "consulta_mail_cancelada_enabled" boolean DEFAULT true NOT NULL,
    "consulta_mail_expirada_enabled" boolean DEFAULT true NOT NULL,
    "consulta_reminders_enabled" boolean DEFAULT true NOT NULL,
    "admin_copy_consultas_enabled" boolean DEFAULT true NOT NULL,
    "consulta_mail_em_preparacao_enabled" boolean DEFAULT true NOT NULL,
    "consulta_mail_nao_compareceu_enabled" boolean DEFAULT true NOT NULL,
    "cotisation_payment_mail_enabled" boolean DEFAULT true NOT NULL,
    CONSTRAINT "chk_negotiation_timeout" CHECK ((("reservation_negotiation_timeout_days" >= 7) AND ("reservation_negotiation_timeout_days" <= 60))),
    CONSTRAINT "chk_no_show_timeout" CHECK ((("reservation_no_show_timeout_hours" >= 12) AND ("reservation_no_show_timeout_hours" <= 168))),
    CONSTRAINT "chk_solicitada_timeout" CHECK ((("reservation_solicitada_timeout_days" >= 7) AND ("reservation_solicitada_timeout_days" <= 60)))
);


ALTER TABLE "public"."library_notification_policies" OWNER TO "postgres";


COMMENT ON TABLE "public"."library_notification_policies" IS 'Politiques de notification (qui est notifié quand). Anon SELECT révoqué le 2026-04-26 (palier 4).';



COMMENT ON COLUMN "public"."library_notification_policies"."reservation_solicitada_timeout_days" IS 'Nombre de jours après lequel une réservation reste ''solicitada'' avant expiration automatique par cron (default 14, range 7-60).';



COMMENT ON COLUMN "public"."library_notification_policies"."reservation_no_show_timeout_hours" IS 'Nombre d''heures après pickup_scheduled_for au bout desquelles une réservation est marquée retirada_no_show par cron (default 24, range 12-168).';



COMMENT ON COLUMN "public"."library_notification_policies"."reservation_allow_reader_counter_proposal" IS 'Si true (default, éthique anarchiste), le lecteur peut contre-proposer un créneau quand la biblio en propose un. Si false, le lecteur ne peut que confirmer ou annuler (pour structures à créneaux fixes). Spec v2 § 3.2.';



COMMENT ON COLUMN "public"."library_notification_policies"."reservation_negotiation_timeout_days" IS 'Délai global après création de la résa au-delà duquel une négociation non aboutie est expirée par cron (passe en stage expirada). Range raisonnable 7-60 jours, default 21 (validé CCLA). Indépendant du compteur d''itérations qui plafonne à 3. Spec v2 § 3.1.';



COMMENT ON COLUMN "public"."library_notification_policies"."consulta_mail_criada_enabled" IS 'Paquet 26 — Notification de création de consultation locale (event consulta_v2_criada). Lecteur + copie biblio.';



COMMENT ON COLUMN "public"."library_notification_policies"."consulta_mail_agendada_enabled" IS 'Paquet 26 — Notification de créneau proposé/reproposé (event consulta_v2_agendada). Lecteur uniquement, avec date+heure+timezone.';



COMMENT ON COLUMN "public"."library_notification_policies"."consulta_mail_resposta_creneau_enabled" IS 'Paquet 26 — Notification de réponse lecteur au créneau (event consulta_v2_resposta_creneau). Biblio uniquement, confirmé ou refusé.';



COMMENT ON COLUMN "public"."library_notification_policies"."consulta_mail_realizada_enabled" IS 'Paquet 26 — Notification de consultation réalisée (event consulta_v2_realizada). Log biblio uniquement (le lecteur sait, il était sur place). Default false par cohérence anti-spam avec reservation_mail_liberada_para_circulacao_enabled.';



COMMENT ON COLUMN "public"."library_notification_policies"."consulta_mail_cancelada_enabled" IS 'Paquet 26 — Notification d''annulation (event consulta_v2_cancelada). Payload discriminant cancelled_by ∈ {leitor, biblioteca} pour routing.';



COMMENT ON COLUMN "public"."library_notification_policies"."consulta_mail_expirada_enabled" IS 'Paquet 26 — Notification d''expiration automatique (event consulta_v2_expirada). Lecteur + copie biblio.';



COMMENT ON COLUMN "public"."library_notification_policies"."consulta_reminders_enabled" IS 'Paquet 26 — Placeholder pour rappels consultations (§7.5 future de spec-flux-consultations.md, non implémentés au paquet 26).';



COMMENT ON COLUMN "public"."library_notification_policies"."admin_copy_consultas_enabled" IS 'Paquet 26 — Active les copies admin biblio pour TOUS les events consulta_v2_*. Calque admin_copy_reservations_enabled.';



COMMENT ON COLUMN "public"."library_notification_policies"."consulta_mail_em_preparacao_enabled" IS 'Toggle granulaire pour le mail consulta_v2_em_preparacao (lecteur·rice prévenu·e que sa demande est en préparation). Cf. spec consultas v2.1 §11.2.';



COMMENT ON COLUMN "public"."library_notification_policies"."consulta_mail_nao_compareceu_enabled" IS 'Toggle granulaire pour le mail consulta_v2_nao_compareceu (lecteur·rice prévenu·e qu''iel est marqué·e absent·e). Doctrine : rappel d''engagement réciproque, pas punition.';



COMMENT ON COLUMN "public"."library_notification_policies"."cotisation_payment_mail_enabled" IS '#NOTIFY-Painel-acts : envoyer au membre le reçu e-mail au paiement de contribution (NOTIF-PA2, défaut ON, configurable par la biblio).';



CREATE OR REPLACE FUNCTION "public"."upsert_library_notification_policies"("p_library_id" "uuid", "p_policies" "jsonb") RETURNS "public"."library_notification_policies"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_row public.library_notification_policies;
begin
  if p_library_id is null then
    raise exception 'library_id ausente';
  end if;

  if not public.user_can_manage_library_notifications(p_library_id) then
    raise exception 'Sem permissão para gerir notificações desta biblioteca';
  end if;

  insert into public.library_notification_policies (
    library_id,
    reservation_created_enabled,
    reservation_status_enabled,
    reservation_workflow_enabled,
    local_consultation_enabled,
    loan_lifecycle_enabled,
    loan_reminders_enabled,
    loan_overdue_enabled,
    profile_restriction_enabled,
    mid_loan_message_enabled,
    reading_recommendations_enabled,
    admin_copy_reservations_enabled,
    admin_copy_loans_enabled,
    tech_alerts_enabled,
    task_alerts_enabled,
    created_by,
    updated_by
  )
  values (
    p_library_id,
    coalesce((p_policies->>'reservation_created_enabled')::boolean, true),
    coalesce((p_policies->>'reservation_status_enabled')::boolean, true),
    coalesce((p_policies->>'reservation_workflow_enabled')::boolean, true),
    coalesce((p_policies->>'local_consultation_enabled')::boolean, true),
    coalesce((p_policies->>'loan_lifecycle_enabled')::boolean, true),
    coalesce((p_policies->>'loan_reminders_enabled')::boolean, true),
    coalesce((p_policies->>'loan_overdue_enabled')::boolean, true),
    coalesce((p_policies->>'profile_restriction_enabled')::boolean, true),
    coalesce((p_policies->>'mid_loan_message_enabled')::boolean, false),
    coalesce((p_policies->>'reading_recommendations_enabled')::boolean, false),
    coalesce((p_policies->>'admin_copy_reservations_enabled')::boolean, true),
    coalesce((p_policies->>'admin_copy_loans_enabled')::boolean, true),
    coalesce((p_policies->>'tech_alerts_enabled')::boolean, true),
    coalesce((p_policies->>'task_alerts_enabled')::boolean, true),
    auth.uid(),
    auth.uid()
  )
  on conflict (library_id) do update
  set reservation_created_enabled = excluded.reservation_created_enabled,
      reservation_status_enabled = excluded.reservation_status_enabled,
      reservation_workflow_enabled = excluded.reservation_workflow_enabled,
      local_consultation_enabled = excluded.local_consultation_enabled,
      loan_lifecycle_enabled = excluded.loan_lifecycle_enabled,
      loan_reminders_enabled = excluded.loan_reminders_enabled,
      loan_overdue_enabled = excluded.loan_overdue_enabled,
      profile_restriction_enabled = excluded.profile_restriction_enabled,
      mid_loan_message_enabled = excluded.mid_loan_message_enabled,
      reading_recommendations_enabled = excluded.reading_recommendations_enabled,
      admin_copy_reservations_enabled = excluded.admin_copy_reservations_enabled,
      admin_copy_loans_enabled = excluded.admin_copy_loans_enabled,
      tech_alerts_enabled = excluded.tech_alerts_enabled,
      task_alerts_enabled = excluded.task_alerts_enabled,
      updated_at = now(),
      updated_by = auth.uid()
  returning * into v_row;

  return v_row;
end;
$$;


