ALTER TABLE "public"."library_public_contact" OWNER TO "postgres";


COMMENT ON TABLE "public"."library_public_contact" IS 'Coordonnees publiques opt-in d''une bibliotheque, montrees a ses lecteur-rices. Distinct de library_contact_profiles (contact confidentiel cooperation inter-biblios).';



CREATE OR REPLACE FUNCTION "public"."upsert_library_public_contact"("p_library_id" "uuid", "p_profile" "jsonb") RETURNS "public"."library_public_contact"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_row public.library_public_contact;
BEGIN
  -- Garde de droit (defense en profondeur ; la RLS WITH CHECK gate aussi).
  IF NOT public.user_can_manage_library(p_library_id) THEN
    RAISE EXCEPTION 'not_authorized' USING errcode = '42501';
  END IF;

  INSERT INTO public.library_public_contact AS t (
    library_id, public_email, public_phone, public_whatsapp,
    public_address, public_note, updated_at, updated_by
  ) VALUES (
    p_library_id,
    NULLIF(p_profile->>'public_email',    ''),
    NULLIF(p_profile->>'public_phone',    ''),
    NULLIF(p_profile->>'public_whatsapp', ''),
    NULLIF(p_profile->>'public_address',  ''),
    NULLIF(p_profile->>'public_note',     ''),
    now(), auth.uid()
  )
  ON CONFLICT (library_id) DO UPDATE SET
    public_email    = NULLIF(p_profile->>'public_email',    ''),
    public_phone    = NULLIF(p_profile->>'public_phone',    ''),
    public_whatsapp = NULLIF(p_profile->>'public_whatsapp', ''),
    public_address  = NULLIF(p_profile->>'public_address',  ''),
    public_note     = NULLIF(p_profile->>'public_note',     ''),
    updated_at      = now(),
    updated_by      = auth.uid()
  RETURNING t.* INTO v_row;

  RETURN v_row;
END;
$$;


ALTER FUNCTION "public"."upsert_library_public_contact"("p_library_id" "uuid", "p_profile" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."upsert_library_regulation_document"("p_library_id" "uuid", "p_document" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "public"."library_regulation_documents"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'auth', 'pg_temp'
    AS $$
declare
  v_library_id uuid;
  v_document jsonb := coalesce(p_document, '{}'::jsonb);
  v_id bigint := nullif(trim(coalesce(v_document->>'id', '')), '')::bigint;
  v_existing public.library_regulation_documents%rowtype;
  v_doc_kind text;
  v_version_label text;
  v_storage_bucket text;
  v_publication_status text;
  v_row public.library_regulation_documents;
begin
  v_library_id := public.resolve_managed_library_id(p_library_id);

  if not public.can_manage_library_regulation_documents(v_library_id) then
    raise exception 'permission denied for library_regulation_documents';
  end if;

  if v_id is not null then
    select *
      into v_existing
    from public.library_regulation_documents d
    where d.id = v_id;

    if v_existing.id is null then
      raise exception 'Documento institucional não encontrado: %', v_id;
    end if;

    if v_existing.library_id <> v_library_id then
      raise exception 'Este documento pertence a outra biblioteca.';
    end if;
  end if;

  v_doc_kind := coalesce(nullif(trim(coalesce(v_document->>'doc_kind', '')), ''), coalesce(v_existing.doc_kind, 'regimento'));
  if v_doc_kind not in ('regimento', 'circulation_appendix', 'other') then
    v_doc_kind := 'regimento';
  end if;

  v_version_label := coalesce(nullif(trim(coalesce(v_document->>'version_label', '')), ''), nullif(trim(coalesce(v_existing.version_label, '')), ''));
  if v_version_label is null then
    raise exception 'version_label obrigatório para documento institucional.';
  end if;

  v_storage_bucket := coalesce(nullif(trim(coalesce(v_document->>'storage_bucket', '')), ''), coalesce(v_existing.storage_bucket, 'library-regimentos'));

  v_publication_status := coalesce(nullif(trim(coalesce(v_document->>'publication_status', '')), ''), coalesce(v_existing.publication_status, 'draft_only'));
  if v_publication_status not in ('draft_only', 'published', 'archived') then
    v_publication_status := coalesce(v_existing.publication_status, 'draft_only');
  end if;

  if v_existing.id is null then
    insert into public.library_regulation_documents (
      library_id,
      doc_kind,
      version_label,
      storage_bucket,
      storage_path_draft,
      storage_path_public,
      publication_status,
      is_active,
      drafted_at,
      published_at,
      archived_at,
      source_note,
      metadata,
      created_by,
      updated_by
    )
    values (
      v_library_id,
      v_doc_kind,
      v_version_label,
      v_storage_bucket,
      nullif(trim(coalesce(v_document->>'storage_path_draft', '')), ''),
      nullif(trim(coalesce(v_document->>'storage_path_public', '')), ''),
      v_publication_status,
      false,
      coalesce(
        case when nullif(trim(coalesce(v_document->>'drafted_at', '')), '') is null then null else (v_document->>'drafted_at')::timestamptz end,
        now()
      ),
      case when nullif(trim(coalesce(v_document->>'published_at', '')), '') is null then null else (v_document->>'published_at')::timestamptz end,
      case when nullif(trim(coalesce(v_document->>'archived_at', '')), '') is null then null else (v_document->>'archived_at')::timestamptz end,
      nullif(trim(coalesce(v_document->>'source_note', '')), ''),
      coalesce(v_document->'metadata', '{}'::jsonb),
      auth.uid(),
      auth.uid()
    )
    returning * into v_row;
  else
    update public.library_regulation_documents d
       set doc_kind = v_doc_kind,
           version_label = v_version_label,
           storage_bucket = v_storage_bucket,
           storage_path_draft = coalesce(nullif(trim(coalesce(v_document->>'storage_path_draft', '')), ''), d.storage_path_draft),
           storage_path_public = case
             when v_document ? 'storage_path_public' then nullif(trim(coalesce(v_document->>'storage_path_public', '')), '')
             else d.storage_path_public
           end,
           publication_status = v_publication_status,
           drafted_at = coalesce(
             case when nullif(trim(coalesce(v_document->>'drafted_at', '')), '') is null then null else (v_document->>'drafted_at')::timestamptz end,
             d.drafted_at
           ),
           published_at = case
             when v_document ? 'published_at' then case when nullif(trim(coalesce(v_document->>'published_at', '')), '') is null then null else (v_document->>'published_at')::timestamptz end
             else d.published_at
           end,
           archived_at = case
             when v_document ? 'archived_at' then case when nullif(trim(coalesce(v_document->>'archived_at', '')), '') is null then null else (v_document->>'archived_at')::timestamptz end
             else d.archived_at
           end,
           source_note = case
             when v_document ? 'source_note' then nullif(trim(coalesce(v_document->>'source_note', '')), '')
             else d.source_note
           end,
           metadata = case
             when v_document ? 'metadata' then coalesce(v_document->'metadata', '{}'::jsonb)
             else d.metadata
           end,
           updated_at = now(),
           updated_by = auth.uid()
     where d.id = v_existing.id
     returning * into v_row;
  end if;

  return v_row;
end;
$$;


ALTER FUNCTION "public"."upsert_library_regulation_document"("p_library_id" "uuid", "p_document" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."upsert_library_regulation_document"("p_library_id" "uuid", "p_document" "jsonb") IS 'Cria ou atualiza um documento institucional da biblioteca (regimento, anexo etc.) em formato front-friendly JSONB.';



CREATE OR REPLACE FUNCTION "public"."user_can_act_as_staff_on_library"("p_library_id" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'auth', 'pg_temp'
    AS $$
    SELECT 
        -- Soit administrateur réseau (droit transverse)
        EXISTS (
            SELECT 1 FROM public.network_administrators
            WHERE user_id = auth.uid() AND status = 'active'
        )
        OR
        -- Soit staff local actif sur cette biblio
        EXISTS (
            SELECT 1 FROM public.user_library_memberships m
            WHERE m.user_id = auth.uid()
              AND m.library_id = p_library_id
              AND m.status = 'active'
              AND m.role = ANY (ARRAY['librarian', 'coordenador'])
        );
$$;


ALTER FUNCTION "public"."user_can_act_as_staff_on_library"("p_library_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."user_can_act_as_staff_on_library"("p_library_id" "uuid") IS 'Retourne TRUE si l''appelant peut agir comme membre du staff sur la biblio donnée. Inclut les administrateurs réseau (droit transverse) et le staff local actif (librarian + coordenador). Utilisé par les RLS catégorie A (15 policies).';



CREATE OR REPLACE FUNCTION "public"."user_can_engage_library"("p_library_id" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'auth', 'pg_temp'
    AS $$
    SELECT 
        -- Soit administrateur réseau
        EXISTS (
            SELECT 1 FROM public.network_administrators
            WHERE user_id = auth.uid() AND status = 'active'
        )
        OR
        -- Soit coordenador local actif (les librarian ne peuvent pas engager politiquement)
        EXISTS (
            SELECT 1 FROM public.user_library_memberships m
            WHERE m.user_id = auth.uid()
              AND m.library_id = p_library_id
              AND m.status = 'active'
              AND m.role = 'coordenador'
        );
$$;


ALTER FUNCTION "public"."user_can_engage_library"("p_library_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."user_can_engage_library"("p_library_id" "uuid") IS 'Retourne TRUE si l''appelant peut engager politiquement la biblio (modifications structurelles, règlement, politique de circulation). Inclut administrateurs réseau et coordenadores locaux. Utilisé par les RLS catégorie B (4 policies).';



CREATE OR REPLACE FUNCTION "public"."user_can_manage_library"("p_library_id" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
    -- Délégué à user_can_engage_library (paquet A) qui inclut les admins réseau.
    -- Préserve la sémantique "coord+ local" tout en ajoutant la dimension transverse.
    SELECT public.user_can_engage_library(p_library_id);
$$;


ALTER FUNCTION "public"."user_can_manage_library"("p_library_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."user_can_manage_library"("p_library_id" "uuid") IS 'Délégué à user_can_engage_library (paquet A). Reconnaît désormais les admins réseau en plus du staff local coordenador/administrador. Réécrit au paquet D.2 (11/05/2026). Wrapper léger : à supprimer au paquet F après migration explicite des appelants vers user_can_engage_library directement.';



CREATE OR REPLACE FUNCTION "public"."user_can_manage_library_notifications"("p_library_id" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public'
    AS $$
  SELECT EXISTS (
    SELECT 1
    FROM public.user_library_memberships ulm
    WHERE ulm.user_id = auth.uid()
      AND ulm.library_id = p_library_id
      AND ulm.status = 'active'
      AND lower(coalesce(ulm.role, '')) IN ('librarian', 'coordenador')
  );
$$;


ALTER FUNCTION "public"."user_can_manage_library_notifications"("p_library_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."user_has_library_staff_role"("p_user_id" "uuid", "p_library_id" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'auth', 'pg_temp'
    AS $$
  -- F.2 v0.3 : retrait 'administrador' (role local supprime)
  select exists (
    select 1
    from public.user_library_memberships ulm
    where ulm.user_id = p_user_id
      and ulm.library_id = p_library_id
      and ulm.status = 'active'
      and lower(coalesce(ulm.role, '')) in (
        'librarian',
        'coordenador'
        -- TODO: harmoniser ces valeurs en anglais lors d'une migration
        -- de nommage des roles (voir dette technique audit famille D, point 2).
      )
  );
$$;


ALTER FUNCTION "public"."user_has_library_staff_role"("p_user_id" "uuid", "p_library_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."user_has_library_staff_role"("p_user_id" "uuid", "p_library_id" "uuid") IS 'DEPRECATED v0.3 : ne reconnaît PAS les admins réseau (paquet A). Conservé tel quel au paquet D.2 (11/05/2026) car les 3 callers connus s''accommodent de cette limite : fn_team_list_memberships (qui passe d''abord par fn_caller_is_administrador → fn_caller_is_network_admin au paquet D.8), fn_resolve_caller_role_for_library (qui fait fallback vers branche network_admin au paquet B), et api.resolve_circulation_rule (impact marginal : un admin réseau ne peut pas faire d''emprunts au nom d''autres lecteurs sur des biblios externes, cas d''usage rare). Refacto reportée au paquet F. À ce moment, soit le réécrire en wrapper de user_can_act_as_staff_on_library_for(uuid, uuid) (à créer), soit le DROP et migrer les callers vers user_can_act_as_staff_on_library + sous-requête.';



