CREATE OR REPLACE VIEW "public"."author_books_public" WITH ("security_invoker"='true') AS
 SELECT "ba"."book_id",
    "b"."bib_ref",
    "ba"."author_id",
    "a"."preferred_name",
    "a"."sort_name",
    COALESCE("a"."sort_name", "a"."preferred_name") AS "author_name",
    "ba"."role",
    "ba"."ord",
    "b"."titulo",
    "b"."subtitulo",
    "b"."ano",
    "b"."editora",
    "b"."cover_object_path"
   FROM (("public"."book_authors" "ba"
     JOIN "public"."books" "b" ON (("b"."id" = "ba"."book_id")))
     JOIN "public"."authors" "a" ON (("a"."id" = "ba"."author_id")));


