    "admin_notes" "text",
    "default_locale" "text" DEFAULT 'pt-BR'::"text" NOT NULL,
    "accepts_public_signup" boolean DEFAULT false NOT NULL,
    "catalog_mode" "text" DEFAULT 'network_published'::"text" NOT NULL,
    "circulation_mode" "text" DEFAULT 'full_sigb'::"text" NOT NULL,
    "network_mode" "text" DEFAULT 'federated'::"text" NOT NULL,
    "governance_mode" "text" DEFAULT 'full_governance'::"text" NOT NULL,
    "profile_template_chosen" "text",
    "logo_url" "text",
    "reader_cards_enabled" boolean DEFAULT false NOT NULL,
    "theme_slug" "text",
    "bib_ref_prefix" "text",
    "bib_ref_pad" smallint,
    "bib_ref_auto" boolean DEFAULT false NOT NULL,
