    "reader_identity_model" "text" DEFAULT 'free_number'::"text" NOT NULL,
    "reader_validation_mode" "text" DEFAULT 'presential'::"text" NOT NULL,
    CONSTRAINT "chk_catalog_published_requires_network" CHECK ((("catalog_mode" <> 'network_published'::"text") OR ("network_mode" = ANY (ARRAY['observer'::"text", 'federated'::"text"])))),
    CONSTRAINT "chk_full_sigb_requires_roles" CHECK ((("circulation_mode" <> 'full_sigb'::"text") OR ("governance_mode" = ANY (ARRAY['staff_roles'::"text", 'full_governance'::"text"])))),
    CONSTRAINT "chk_libraries_profile_template_chosen" CHECK ((("profile_template_chosen" IS NULL) OR ("profile_template_chosen" = ANY (ARRAY['A'::"text", 'B'::"text", 'C'::"text", 'D'::"text", 'custom'::"text"])))),
    CONSTRAINT "chk_regimento_draft_path_no_url" CHECK ((("regimento_draft_object_path" IS NULL) OR ("regimento_draft_object_path" !~~ 'http%'::"text"))),
    CONSTRAINT "chk_regimento_published_path_no_url" CHECK ((("regimento_published_object_path" IS NULL) OR ("regimento_published_object_path" !~~ 'http%'::"text"))),
    CONSTRAINT "libraries_catalog_mode_check" CHECK (("catalog_mode" = ANY (ARRAY['local_only'::"text", 'network_published'::"text"]))),
    CONSTRAINT "libraries_circulation_mode_check" CHECK (("circulation_mode" = ANY (ARRAY['off'::"text", 'informal'::"text", 'full_sigb'::"text"]))),
    CONSTRAINT "libraries_governance_mode_check" CHECK (("governance_mode" = ANY (ARRAY['informal'::"text", 'staff_roles'::"text", 'full_governance'::"text"]))),
    CONSTRAINT "libraries_name_not_blank" CHECK (("btrim"("name") <> ''::"text")),
    CONSTRAINT "libraries_network_mode_check" CHECK (("network_mode" = ANY (ARRAY['isolated'::"text", 'observer'::"text", 'federated'::"text"]))),
    CONSTRAINT "libraries_reader_identity_model_check" CHECK (("reader_identity_model" = ANY (ARRAY['free_number'::"text", 'sequenced_number'::"text", 'name'::"text", 'none'::"text"]))),
    CONSTRAINT "libraries_reader_validation_mode_check" CHECK (("reader_validation_mode" = ANY (ARRAY['presential'::"text", 'remote'::"text", 'none'::"text"]))),
    CONSTRAINT "libraries_slug_not_blank" CHECK (("btrim"("slug") <> ''::"text")),
    CONSTRAINT "libraries_visibility_level_check" CHECK (("visibility_level" = ANY (ARRAY['public'::"text", 'network'::"text", 'private'::"text"])))
);


ALTER TABLE "public"."libraries" OWNER TO "postgres";


COMMENT ON COLUMN "public"."libraries"."document_governance_config" IS 'Configuração de governança documental por biblioteca: edição direta, propostas de correção, criação de cópia local, recursos digitais, mutualização padrão e parceiras autorizadas.';



COMMENT ON COLUMN "public"."libraries"."visibility_level" IS 'Niveau de visibilité de la bibliothèque, à 3 valeurs : public (visible à tous, anon inclus), network (visible aux membres du réseau ayant au moins un membership actif), private (visible uniquement aux membres directs de cette bibliothèque). Indépendant de is_active. Par défaut private : chaque collectif décide explicitement de son ouverture.';



COMMENT ON COLUMN "public"."libraries"."membership_enabled" IS 'Si true, la bibliothèque utilise des règles de cotisation. Si false, l''emprunt est libre pour tous les membres actifs.';



COMMENT ON COLUMN "public"."libraries"."admin_notes" IS 'Notes administratives internes sur la biblio (statut transitoire, particularités d''onboarding, etc.). Non exposé via les API publiques. Lecture restreinte via RLS.';



COMMENT ON COLUMN "public"."libraries"."default_locale" IS 'Langue par défaut de la biblio (BCP 47 short code). Détermine la langue
   des mails côté coordination, des notifications staff, et potentiellement
   d''autres contextes futurs (page publique, exports). Configurable depuis
   l''onglet Identité et fonctionnement → section Identité de BibliotecaPage.
   Valeurs supportées au paquet 6 : pt-BR, fr, es, en, it, de. Validation
   côté UI (dropdown), pas de CHECK constraint pour permettre l''ajout
   facile de nouvelles locales.';



COMMENT ON COLUMN "public"."libraries"."accepts_public_signup" IS 'Indique si la bibliothèque accepte des inscriptions publiques via le formulaire signup (criar-conta). Indépendant de visibility_level qui concerne uniquement la visibilité dans le catalogue/annuaire. Une biblio network peut rester discrète tout en acceptant des adhésions par signup. Modification réservée aux staff (coordenador, administrador) via la policy libraries_staff_update existante. Ajouté par paquet L.1.1 (2026-05-12) suite au design problem révélé par la bascule de v_libraries_for_signup en security_invoker.';



COMMENT ON COLUMN "public"."libraries"."catalog_mode" IS 'Profil d''adoption axe 1 : catalogue local_only ou network_published. Cf. spec-profils-bibliotheque.md §2.3.';



COMMENT ON COLUMN "public"."libraries"."circulation_mode" IS 'Profil d''adoption axe 2 : circulation off (aucune) / informal (light) / full_sigb (complet). Cf. spec-profils-bibliotheque.md §2.4.';



COMMENT ON COLUMN "public"."libraries"."network_mode" IS 'Profil d''adoption axe 3 : place dans le reseau isolated / observer / federated. Cf. spec-profils-bibliotheque.md §2.5.';



COMMENT ON COLUMN "public"."libraries"."governance_mode" IS 'Profil d''adoption axe 4 : gouvernance interne informal / staff_roles / full_governance. Cf. spec-profils-bibliotheque.md §2.6.';



COMMENT ON COLUMN "public"."libraries"."profile_template_chosen" IS 'Paquet G/F (20/05/2026) : profil-type choisi consciemment a la creation
   ou via transition. NULL = biblio en profil par defaut (banner G visible).
   A/B/C/D = profil-type pur. custom = configuration personnalisee.';



COMMENT ON COLUMN "public"."libraries"."logo_url" IS 'URL du logo de la bibliothèque, affiché dans ses mails. NULL = pas de logo (repli : cellule omise). Introduit par le chantier C de l''audit #153 pour résoudre les logos depuis le contexte plutôt qu''en dur dans le code.';



COMMENT ON COLUMN "public"."libraries"."reader_cards_enabled" IS 'Capacite carte-lecteur (chantier mobile, decision 28/05/2026). Si true, les lecteur·ices membres peuvent generer une carte-laissez-passer detachable pour cette bibliotheque. Si false, identification nominale en permanence.';



COMMENT ON COLUMN "public"."libraries"."theme_slug" IS 'Slug de theme custom si themes/<slug>/manifest.json existe dans le bucket library-ui-assets ; NULL = theme par defaut. Maintenu par api.fn_set_library_theme_active (upload/suppression du manifeste cote frontend).';



COMMENT ON COLUMN "public"."libraries"."bib_ref_prefix" IS 'Prefixe de la convention bib_ref (ex. '''' pour BLMF, ''BTL-TL-'' pour BTL).';



COMMENT ON COLUMN "public"."libraries"."bib_ref_pad" IS 'Largeur de zero-padding de la partie numerique (ex. 7 pour BLMF, 6 pour BTL).';



COMMENT ON COLUMN "public"."libraries"."bib_ref_auto" IS 'Si vrai : next_bib_ref suggere une reference selon la convention.';



COMMENT ON COLUMN "public"."libraries"."tombo_pattern" IS 'Motif de numérotation des tombos : {prefix, year:bool, sep, pad:int}. fn_next_tombo génère le prochain tombo selon ce motif. NULL = pas de génération auto (le tombo doit alors être saisi manuellement).';



COMMENT ON COLUMN "public"."libraries"."reader_identity_model" IS 'Modèle d''identité lecteur·rice de la biblio (CARD-LOCAL-2). Pilote l''unicité : free_number/sequenced_number = unique ; name = homonymes tolérés ; none = pas de schéma. Défaut free_number (rétro-compatible avec l''ancien index unique).';



COMMENT ON COLUMN "public"."libraries"."reader_validation_mode" IS 'Mode de validation de la biblio (CARD-LOCAL-3) : presential (1er passage) / remote (identité envoyée par e-mail) / none (accès direct). Pilote le message à la lectrice.';



CREATE OR REPLACE VIEW "public"."v_book_authors_canonical" WITH ("security_invoker"='true') AS
 WITH "canon_source" AS (
         SELECT "bc"."book_id",
            "bc"."author_id",
            "bc"."position" AS "ord",
            COALESCE(NULLIF("btrim"("a"."sort_name"), ''::"text"), NULLIF("btrim"("a"."preferred_name"), ''::"text"), NULLIF("btrim"("bc"."name"), ''::"text")) AS "base_name"
           FROM ("public"."book_contributors" "bc"
             LEFT JOIN "public"."authors" "a" ON (("a"."id" = "bc"."author_id")))
          WHERE ("bc"."role" = 'autor'::"text")
        ), "canon" AS (
         SELECT "canon_source"."book_id",
            "canon_source"."author_id",
            "canon_source"."ord",
                CASE
                    WHEN ("canon_source"."base_name" IS NULL) THEN NULL::"text"
                    WHEN (POSITION((','::"text") IN ("canon_source"."base_name")) > 0) THEN ("upper"(TRIM(BOTH FROM "split_part"("canon_source"."base_name", ','::"text", 1))) ||
                    CASE
                        WHEN (NULLIF(TRIM(BOTH FROM SUBSTRING("canon_source"."base_name" FROM (POSITION((','::"text") IN ("canon_source"."base_name")) + 1))), ''::"text") IS NOT NULL) THEN (', '::"text" || TRIM(BOTH FROM SUBSTRING("canon_source"."base_name" FROM (POSITION((','::"text") IN ("canon_source"."base_name")) + 1))))
                        ELSE ''::"text"
                    END)
                    ELSE "canon_source"."base_name"
                END AS "display_name"
           FROM "canon_source"
        )
 SELECT "book_id",
    "string_agg"("display_name", ' ; '::"text" ORDER BY "ord", "display_name") AS "author_display",
    "jsonb_agg"("jsonb_build_object"('author_id', "author_id", 'label', "display_name", 'ord', "ord") ORDER BY "ord", "display_name") AS "author_chips"
   FROM "canon"
  GROUP BY "book_id";


ALTER VIEW "public"."v_book_authors_canonical" OWNER TO "postgres";


COMMENT ON VIEW "public"."v_book_authors_canonical" IS 'REVIEW 2026-03-30: possibly useful normalization/support view. Verify role before any cleanup.';



CREATE OR REPLACE VIEW "public"."v_book_detail_public_v2" WITH ("security_invoker"='true') AS
 WITH "first_author" AS (
         SELECT DISTINCT ON ("ba"."book_id") "ba"."book_id",
            "ba"."author_id"
           FROM "public"."book_authors" "ba"
          WHERE ("ba"."author_id" IS NOT NULL)
          ORDER BY "ba"."book_id", "ba"."ord", "ba"."author_id"
        ), "authors_json_by_book" AS (
         SELECT "abp"."book_id",
            "jsonb_agg"("jsonb_build_object"('author_id', "abp"."author_id", 'display_name', COALESCE("abp"."author_name", "abp"."sort_name", "abp"."preferred_name"), 'preferred_name', "abp"."preferred_name", 'sort_name', "abp"."sort_name", 'role', "abp"."role", 'ord', "abp"."ord") ORDER BY "abp"."ord", "abp"."author_id") AS "authors_json"
           FROM "public"."author_books_public" "abp"
          GROUP BY "abp"."book_id"
        ), "digital_flags" AS (
         SELECT "r"."book_id",
            "bool_or"((("r"."resource_type" = 'pdf_restrito'::"text") AND ("r"."usage_type" = 'leitura_online'::"text") AND ("r"."access_scope" = 'conta_ativa'::"text") AND ("r"."status" = 'active'::"text") AND (COALESCE("r"."is_active", false) = true))) AS "has_online_reading"
           FROM "public"."book_digital_resources" "r"
          GROUP BY "r"."book_id"
        ), "holdings_source" AS (
         SELECT "h"."id" AS "holding_id",
            "h"."book_id",
            "b1"."bib_ref" AS "book_bib_ref",
            COALESCE(NULLIF(TRIM(BOTH FROM "h"."local_bib_ref"), ''::"text"), "b1"."bib_ref") AS "local_bib_ref",
            "h"."library_id",
            "l"."slug" AS "library_slug",
            "l"."name" AS "library_name",
            "l"."short_name",
            "l"."city",
            "l"."state",
            COALESCE("h"."loanable", "b1"."loanable", true) AS "holding_loanable",
            COALESCE("h"."exemplares_total", 0) AS "holding_exemplares_total",
            COALESCE("h"."available_count", 0) AS "holding_available_count"
           FROM (("public"."book_holdings" "h"
             JOIN "public"."books" "b1" ON (("b1"."id" = "h"."book_id")))
             JOIN "public"."libraries" "l" ON (("l"."id" = "h"."library_id")))
        ), "exemplares_by_holding" AS (
         SELECT "e"."holding_id",
            ("count"(*))::integer AS "exemplares_total_real",
            "jsonb_agg"("e"."tombo" ORDER BY "e"."tombo") FILTER (WHERE (NULLIF(TRIM(BOTH FROM COALESCE("e"."tombo", ''::"text")), ''::"text") IS NOT NULL)) AS "tombos_json"
           FROM "public"."exemplares" "e"
          WHERE ("e"."holding_id" IS NOT NULL)
          GROUP BY "e"."holding_id"
        ), "earliest_due_by_book" AS (
         SELECT "ei"."book_id",
            "min"(COALESCE("ei"."extended_until", "ei"."due_at")) AS "earliest_due_back_at"
           FROM "public"."emprestimo_itens_v2" "ei"
          WHERE ("ei"."item_status" = 'aberto'::"text")
          GROUP BY "ei"."book_id"
        ), "earliest_due_by_holding" AS (
         SELECT "ei"."book_id",
            "e"."holding_id",
            "min"(COALESCE("ei"."extended_until", "ei"."due_at")) AS "earliest_due_back_at"
           FROM ("public"."emprestimo_itens_v2" "ei"
             JOIN "public"."exemplares" "e" ON (("e"."id" = "ei"."item_id")))
          WHERE (("ei"."item_status" = 'aberto'::"text") AND ("e"."holding_id" IS NOT NULL))
          GROUP BY "ei"."book_id", "e"."holding_id"
        ), "holdings_enriched" AS (
         SELECT "hs"."holding_id",
            "hs"."book_id",
            "hs"."book_bib_ref",
            "hs"."local_bib_ref",
            "hs"."library_id",
            "hs"."library_slug",
            "hs"."library_name",
            "hs"."short_name",
            "hs"."city",
            "hs"."state",
            "hs"."holding_loanable",
            COALESCE("hs"."holding_exemplares_total", "exh"."exemplares_total_real", 0) AS "holding_exemplares_total",
            "hs"."holding_available_count",
            COALESCE("exh"."tombos_json", '[]'::"jsonb") AS "tombos_json",
            "edh"."earliest_due_back_at" AS "holding_earliest_due_back_at"
           FROM (("holdings_source" "hs"
             LEFT JOIN "exemplares_by_holding" "exh" ON (("exh"."holding_id" = "hs"."holding_id")))
             LEFT JOIN "earliest_due_by_holding" "edh" ON (("edh"."holding_id" = "hs"."holding_id")))
        ), "holdings_rollup_by_book" AS (
         SELECT "he"."book_id",
            (COALESCE("sum"("he"."holding_exemplares_total"), (0)::bigint))::integer AS "exemplares_total",
            ("count"(*))::integer AS "bibliotecas_count",
            (COALESCE("sum"("he"."holding_available_count"), (0)::bigint))::integer AS "global_available_count",
            "jsonb_agg"("jsonb_build_object"('holding_id', "he"."holding_id", 'library_id', "he"."library_id", 'library_slug', "he"."library_slug", 'library_name', "he"."library_name", 'short_name', "he"."short_name", 'city', "he"."city", 'state', "he"."state", 'local_bib_ref', "he"."local_bib_ref", 'loanable', "he"."holding_loanable", 'available_count', "he"."holding_available_count", 'exemplares_total', "he"."holding_exemplares_total", 'tombos_json', "he"."tombos_json", 'earliest_due_back_at', "he"."holding_earliest_due_back_at") ORDER BY "he"."library_name", "he"."library_slug", "he"."holding_id") AS "holding_libraries_json"
           FROM "holdings_enriched" "he"
          GROUP BY "he"."book_id"
        ), "single_library" AS (
         SELECT "he"."book_id",
            "he"."library_id",
            "he"."library_slug",
            "he"."library_name"
           FROM ("holdings_enriched" "he"
             JOIN ( SELECT "holdings_enriched"."book_id"
                   FROM "holdings_enriched"
                  GROUP BY "holdings_enriched"."book_id"
                 HAVING ("count"(*) = 1)) "one" ON (("one"."book_id" = "he"."book_id")))
        ), "tombos_all" AS (
         SELECT "x"."book_id",
            "jsonb_agg"("x"."tombo" ORDER BY "x"."tombo") AS "tombos_json"
           FROM ( SELECT "he"."book_id",
                    "jsonb_array_elements_text"("he"."tombos_json") AS "tombo"
                   FROM "holdings_enriched" "he") "x"
          GROUP BY "x"."book_id"
        )
 SELECT "b"."id",
    "b"."id" AS "book_id",
    "b"."bib_ref",
    "b"."autor",
    "b"."titulo",
    "b"."ano",
    "b"."editora",
    "b"."cdd",
    COALESCE("b"."loanable", true) AS "loanable",
    COALESCE("hr"."global_available_count", 0) AS "available_count",
    "b"."created_at",
    "b"."cover_object_path",
    "b"."subtitulo",
    "b"."edicao",
    "b"."local_publicacao",
    "b"."isbn",
    "b"."issn",
    "b"."idioma",
    "b"."paginas",
    "b"."notas",
    "b"."tipo_material",
    "b"."autores_secundarios",
    "b"."colecao",
    "b"."volume",
    "b"."assuntos",
    "b"."tradutor",
    "b"."organizador",
    "fa"."author_id",
    "b"."catalog_source",
        CASE
            WHEN ("hr"."bibliotecas_count" = 1) THEN "sl"."library_id"
            ELSE NULL::"uuid"
        END AS "library_id",
        CASE
            WHEN ("hr"."bibliotecas_count" = 1) THEN "sl"."library_slug"
            ELSE NULL::"text"
        END AS "library_slug",
        CASE
            WHEN ("hr"."bibliotecas_count" = 1) THEN "sl"."library_name"
            ELSE NULL::"text"
        END AS "library_name",
        CASE
            WHEN ("hr"."bibliotecas_count" = 1) THEN "sl"."library_name"
            WHEN ("hr"."bibliotecas_count" > 1) THEN (("hr"."bibliotecas_count")::"text" || ' bibliotecas'::"text")
            ELSE NULL::"text"
        END AS "biblioteca",
    COALESCE("df"."has_online_reading", false) AS "has_online_reading",
    COALESCE("c"."author_display", "b"."autor") AS "author_display",
    COALESCE("c"."author_chips", '[]'::"jsonb") AS "author_chips",
    COALESCE("aj"."authors_json", '[]'::"jsonb") AS "authors_json",
    COALESCE("hr"."exemplares_total", 0) AS "exemplares_total",
    COALESCE("hr"."bibliotecas_count", 0) AS "bibliotecas_count",
    COALESCE("hr"."holding_libraries_json", '[]'::"jsonb") AS "holding_libraries_json",
    COALESCE("ta"."tombos_json", '[]'::"jsonb") AS "tombos_json",
    COALESCE("hr"."global_available_count", 0) AS "global_available_count",
    COALESCE("b"."available_count", 0) AS "legacy_available_count_global",
    COALESCE("hr"."exemplares_total", 0) AS "global_exemplares_total",
    "edb"."earliest_due_back_at"
   FROM (((((((("public"."books" "b"
     LEFT JOIN "first_author" "fa" ON (("fa"."book_id" = "b"."id")))
     LEFT JOIN "public"."v_book_authors_canonical" "c" ON (("c"."book_id" = "b"."id")))
     LEFT JOIN "authors_json_by_book" "aj" ON (("aj"."book_id" = "b"."id")))
     LEFT JOIN "holdings_rollup_by_book" "hr" ON (("hr"."book_id" = "b"."id")))
     LEFT JOIN "single_library" "sl" ON (("sl"."book_id" = "b"."id")))
     LEFT JOIN "tombos_all" "ta" ON (("ta"."book_id" = "b"."id")))
     LEFT JOIN "digital_flags" "df" ON (("df"."book_id" = "b"."id")))
     LEFT JOIN "earliest_due_by_book" "edb" ON (("edb"."book_id" = "b"."id")));


