CREATE TABLE IF NOT EXISTS "public"."user_library_memberships" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "user_id" "uuid" NOT NULL,
    "library_id" "uuid" NOT NULL,
    "role" "text" NOT NULL,
    "is_primary" boolean DEFAULT false NOT NULL,
    "status" "text" DEFAULT 'active'::"text" NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "history_enabled" boolean DEFAULT true NOT NULL,
    "is_restricted" boolean DEFAULT false,
    "restricted_reason" "text",
    "pending_removal_until" timestamp with time zone,
    "pending_removal_requested_by" "uuid",
    "restricted_by" "uuid",
    "restricted_at" timestamp with time zone,
    "physically_validated_at" timestamp with time zone,
    "physically_validated_by_user_id" "uuid",
    "physical_validation_note" "text",
    "local_reader_number" "text",
    "imported_from_legacy" boolean DEFAULT false NOT NULL,
    CONSTRAINT "user_library_memberships_role_check" CHECK (("role" = ANY (ARRAY['reader'::"text", 'librarian'::"text", 'coordenador'::"text"]))),
    CONSTRAINT "user_library_memberships_status_check" CHECK (("status" = ANY (ARRAY['active'::"text", 'inactive'::"text", 'pending_removal'::"text", 'removed'::"text", 'suspended'::"text", 'left_with_pending_circulation'::"text", 'terminated'::"text", 'pending_validation'::"text"])))
);


ALTER TABLE "public"."user_library_memberships" OWNER TO "postgres";


COMMENT ON COLUMN "public"."user_library_memberships"."history_enabled" IS 'When false, history tab shows nothing. User controls this in their preferences.';



COMMENT ON COLUMN "public"."user_library_memberships"."is_restricted" IS 'True if the reader account is restricted (e.g., non-return of loan).';



COMMENT ON COLUMN "public"."user_library_memberships"."restricted_reason" IS 'Reason for the restriction, set by librarian.';



COMMENT ON COLUMN "public"."user_library_memberships"."pending_removal_until" IS 'Date à laquelle le passage automatique en inactive aura lieu. NULL si pas en cours.';



COMMENT ON COLUMN "public"."user_library_memberships"."pending_removal_requested_by" IS 'User qui a demandé le retrait, pour traçabilité audit.';



COMMENT ON COLUMN "public"."user_library_memberships"."restricted_by" IS 'EA-10 (28/05/2026) : staff (uuid) ayant pose la restriction LOCALE. Horizontalite.';



COMMENT ON COLUMN "public"."user_library_memberships"."restricted_at" IS 'EA-10 (28/05/2026) : date de pose de la restriction locale.';



COMMENT ON COLUMN "public"."user_library_memberships"."imported_from_legacy" IS 'true = appartenance issue d''un registre papier antérieur à AnarBib (CARD-LOCAL-5). Posé à l''attribution/import par le staff ; distingue legacy vs AnarBib dans le roster (N3).';



CREATE OR REPLACE VIEW "api"."my_session_context" WITH ("security_invoker"='true') AS
 WITH "me" AS (
         SELECT "auth"."uid"() AS "user_id"
        ), "profile_row" AS (
         SELECT "p"."id",
            "p"."email",
            "p"."first_name",
            "p"."last_name"
           FROM ("public"."profiles" "p"
             JOIN "me" "me_1" ON (("me_1"."user_id" = "p"."id")))
        ), "default_library" AS (
         SELECT "l"."id",
            "l"."slug",
            "l"."name"
           FROM "public"."libraries" "l"
          WHERE (("l"."is_active" = true) AND ("l"."is_default" = true))
          ORDER BY "l"."created_at", "l"."slug"
         LIMIT 1
        ), "active_memberships" AS (
         SELECT "m"."user_id",
            "m"."library_id",
            "l"."slug" AS "library_slug",
            "l"."name" AS "library_name",
            "m"."role",
            "m"."is_primary",
            "m"."created_at"
           FROM (("public"."user_library_memberships" "m"
             JOIN "public"."libraries" "l" ON (("l"."id" = "m"."library_id")))
             JOIN "me" "me_1" ON (("me_1"."user_id" = "m"."user_id")))
          WHERE (("m"."status" = 'active'::"text") AND ("l"."is_active" = true))
        ), "effective_membership" AS (
         SELECT "am"."user_id",
            "am"."library_id",
            "am"."library_slug",
            "am"."library_name",
            "am"."role"
           FROM "active_memberships" "am"
          ORDER BY "am"."is_primary" DESC, "am"."created_at", "am"."library_slug"
         LIMIT 1
        )
 SELECT "me"."user_id",
    COALESCE("pr"."email", NULLIF(("auth"."jwt"() ->> 'email'::"text"), ''::"text")) AS "email",
    "pr"."first_name",
    "pr"."last_name",
    NULLIF("btrim"("concat_ws"(' '::"text", COALESCE("pr"."first_name", ''::"text"), COALESCE("pr"."last_name", ''::"text"))), ''::"text") AS "full_name",
    ("me"."user_id" IS NOT NULL) AS "is_authenticated",
    COALESCE(("em"."role" = 'librarian'::"text"), false) AS "is_librarian",
        CASE
            WHEN (("me"."user_id" IS NOT NULL) AND ("em"."library_id" IS NULL)) THEN NULL::"uuid"
            ELSE COALESCE("em"."library_id", "dl"."id")
        END AS "default_library_id",
        CASE
            WHEN (("me"."user_id" IS NOT NULL) AND ("em"."library_slug" IS NULL)) THEN NULL::"text"
            ELSE COALESCE("em"."library_slug", "dl"."slug")
        END AS "default_library_slug",
        CASE
            WHEN (("me"."user_id" IS NOT NULL) AND ("em"."library_name" IS NULL)) THEN NULL::"text"
            ELSE COALESCE("em"."library_name", "dl"."name")
        END AS "default_library_name",
    ("me"."user_id" IS NOT NULL) AS "can_access_conta",
    (("me"."user_id" IS NOT NULL) AND COALESCE(("em"."role" = 'librarian'::"text"), false)) AS "can_access_painel",
    (("me"."user_id" IS NOT NULL) AND COALESCE(("em"."role" = 'librarian'::"text"), false)) AS "can_access_catalogacao"
   FROM ((("me"
     LEFT JOIN "profile_row" "pr" ON (true))
     LEFT JOIN "effective_membership" "em" ON (("em"."user_id" = "me"."user_id")))
     LEFT JOIN "default_library" "dl" ON (true));


ALTER VIEW "api"."my_session_context" OWNER TO "postgres";


CREATE OR REPLACE VIEW "public"."v_books_public_catalog_v2" WITH ("security_invoker"='true') AS
 WITH "holding_library_names" AS (
         SELECT "d1"."book_id",
            COALESCE("jsonb_agg"("x"."display_name" ORDER BY "x"."ord") FILTER (WHERE ("x"."display_name" IS NOT NULL)), '[]'::"jsonb") AS "holding_library_names_json"
           FROM ("public"."v_book_detail_public_v2" "d1"
             LEFT JOIN LATERAL ( SELECT "e"."ordinality" AS "ord",
                    COALESCE(NULLIF(TRIM(BOTH FROM ("e"."value" ->> 'library_name'::"text")), ''::"text"), NULLIF(TRIM(BOTH FROM ("e"."value" ->> 'short_name'::"text")), ''::"text"), NULLIF(TRIM(BOTH FROM ("e"."value" ->> 'library_slug'::"text")), ''::"text")) AS "display_name"
                   FROM "jsonb_array_elements"(COALESCE("d1"."holding_libraries_json", '[]'::"jsonb")) WITH ORDINALITY "e"("value", "ordinality")) "x" ON (true))
          GROUP BY "d1"."book_id"
        )
 SELECT "d"."id",
    "d"."book_id",
    "d"."bib_ref",
    "d"."autor",
    "d"."titulo",
    "d"."ano",
    "d"."editora",
    "d"."cdd",
    "d"."loanable",
    "d"."available_count",
    "d"."created_at",
    "d"."cover_object_path",
    "d"."subtitulo",
    "d"."edicao",
    "d"."local_publicacao",
    "d"."isbn",
    "d"."issn",
    "d"."idioma",
    "d"."paginas",
    "d"."notas",
    "d"."tipo_material",
    "d"."autores_secundarios",
    "d"."colecao",
    "d"."volume",
    "d"."assuntos",
    "d"."tradutor",
    "d"."organizador",
    "d"."author_id",
    "d"."catalog_source",
    "d"."library_id",
    "d"."library_slug",
    "d"."library_name",
    "d"."has_online_reading",
    "d"."biblioteca",
    "d"."author_display",
    "d"."author_chips",
    "d"."exemplares_total",
    "d"."bibliotecas_count",
    "d"."holding_libraries_json",
    COALESCE("n"."holding_library_names_json", '[]'::"jsonb") AS "holding_library_names_json",
    "d"."global_available_count",
    "d"."legacy_available_count_global",
    "d"."global_exemplares_total"
   FROM ("public"."v_book_detail_public_v2" "d"
     LEFT JOIN "holding_library_names" "n" ON (("n"."book_id" = "d"."book_id")));


ALTER VIEW "public"."v_books_public_catalog_v2" OWNER TO "postgres";


COMMENT ON VIEW "public"."v_books_public_catalog_v2" IS 'Catalogue public léger AnarBib v2: une ligne par livre, sans duplication par exemplaire. Contrat moderne: exemplares_total = total global des exemplaires agrégés; global_available_count = disponibilité globale anonyme; holding_libraries_json expose les compteurs par holding.';



CREATE OR REPLACE VIEW "api"."catalog_books_public_session_v2" WITH ("security_invoker"='true') AS
 WITH "session_ctx" AS (
         SELECT "msc"."default_library_id"
           FROM "api"."my_session_context" "msc"
         LIMIT 1
        ), "session_holdings" AS (
         SELECT "h"."book_id",
            "h"."id" AS "holding_id",
            "h"."library_id",
            COALESCE(NULLIF(TRIM(BOTH FROM "h"."local_bib_ref"), ''::"text"), "b1"."bib_ref") AS "local_bib_ref",
            COALESCE("h"."loanable", "b1"."loanable", true) AS "loanable",
            COALESCE("h"."available_count", 0) AS "available_count",
            COALESCE("h"."exemplares_total", 0) AS "exemplares_total",
            "jsonb_agg"("e"."tombo" ORDER BY "e"."tombo") FILTER (WHERE (NULLIF(TRIM(BOTH FROM COALESCE("e"."tombo", ''::"text")), ''::"text") IS NOT NULL)) AS "tombos_json"
           FROM (("public"."book_holdings" "h"
             JOIN "public"."books" "b1" ON (("b1"."id" = "h"."book_id")))
             LEFT JOIN "public"."exemplares" "e" ON (("e"."holding_id" = "h"."id")))
          GROUP BY "h"."book_id", "h"."id", "h"."library_id", COALESCE(NULLIF(TRIM(BOTH FROM "h"."local_bib_ref"), ''::"text"), "b1"."bib_ref"), COALESCE("h"."loanable", "b1"."loanable", true), COALESCE("h"."available_count", 0), COALESCE("h"."exemplares_total", 0)
        )
 SELECT "b"."id",
    "b"."book_id",
    "b"."bib_ref",
    "b"."autor",
    "b"."titulo",
    "b"."ano",
    "b"."editora",
    "b"."cdd",
    "b"."loanable",
    "b"."created_at",
    "b"."cover_object_path",
    "b"."subtitulo",
    "b"."edicao",
    "b"."local_publicacao",
    "b"."isbn",
    "b"."issn",
    "b"."idioma",
    "b"."paginas",
    "b"."notas",
    "b"."tipo_material",
    "b"."autores_secundarios",
    "b"."colecao",
    "b"."volume",
    "b"."assuntos",
    "b"."tradutor",
    "b"."organizador",
    "b"."author_id",
    "b"."catalog_source",
    "b"."library_id",
    "b"."library_slug",
    "b"."library_name",
    "b"."biblioteca",
    "b"."has_online_reading",
    "b"."author_display",
    "b"."author_chips",
    "b"."exemplares_total",
    "b"."bibliotecas_count",
    "b"."holding_libraries_json",
    "b"."holding_library_names_json",
    'holdings_session_v2'::"text" AS "availability_source",
    COALESCE("b"."legacy_available_count_global", "bk"."available_count", 0) AS "legacy_available_count_global",
    "sc"."default_library_id" AS "session_library_id",
    "ls"."slug" AS "session_library_slug",
    "ls"."name" AS "session_library_name",
    COALESCE("sh"."exemplares_total", 0) AS "session_exemplares_total",
    COALESCE("sh"."tombos_json", '[]'::"jsonb") AS "session_tombos_json",
    ("sh"."holding_id" IS NOT NULL) AS "session_has_holding",
        CASE
            WHEN ("sc"."default_library_id" IS NULL) THEN 'sem_biblioteca_de_sessao'::"text"
            WHEN ("sh"."holding_id" IS NULL) THEN 'indisponivel_para_voce'::"text"
            WHEN (COALESCE("sh"."loanable", "b"."loanable", true) IS FALSE) THEN 'consultavel_no_local'::"text"
            ELSE 'no_acervo_da_sua_biblioteca'::"text"
        END AS "session_status_hint",
    "sh"."holding_id" AS "session_holding_id",
    "sh"."local_bib_ref" AS "session_local_bib_ref",
    COALESCE("sh"."available_count", 0) AS "session_available_count",
    COALESCE("sh"."loanable", "b"."loanable", true) AS "session_loanable",
    "b"."global_available_count",
    "b"."global_exemplares_total"
   FROM (((("public"."v_books_public_catalog_v2" "b"
     LEFT JOIN "public"."books" "bk" ON (("bk"."id" = "b"."book_id")))
     LEFT JOIN "session_ctx" "sc" ON (true))
     LEFT JOIN "public"."libraries" "ls" ON (("ls"."id" = "sc"."default_library_id")))
     LEFT JOIN "session_holdings" "sh" ON ((("sh"."book_id" = "b"."book_id") AND ("sh"."library_id" = "sc"."default_library_id"))));


ALTER VIEW "api"."catalog_books_public_session_v2" OWNER TO "postgres";


