CREATE OR REPLACE VIEW "api"."catalog_list_session_v1" WITH ("security_invoker"='true') AS
 WITH "session_ctx" AS (
         SELECT "msc"."default_library_id"
           FROM "api"."my_session_context" "msc"
         LIMIT 1
        ), "is_network_member" AS (
         SELECT (EXISTS ( SELECT 1
                   FROM "public"."user_library_memberships" "ulm"
                  WHERE (("ulm"."user_id" = "auth"."uid"()) AND ("ulm"."status" = 'active'::"text")))) AS "is_member"
        ), "session_holdings" AS (
         SELECT "h"."book_id",
            "h"."id" AS "holding_id",
            "h"."library_id",
            "h"."local_bib_ref",
            "h"."loanable" AS "holding_loanable",
            COALESCE("h"."available_count", 0) AS "available_count",
            COALESCE("h"."exemplares_total", 0) AS "exemplares_total"
           FROM "public"."book_holdings" "h"
          WHERE ("h"."library_id" = ( SELECT "session_ctx"."default_library_id"
                   FROM "session_ctx"))
        )
 SELECT "m"."book_id",
    "m"."bib_ref",
    "m"."autor",
    "m"."titulo",
    "m"."ano",
    "m"."editora",
    "m"."cdd",
    "m"."loanable",
    "m"."available_count",
    "m"."created_at",
    "m"."cover_object_path",
    "m"."subtitulo",
    "m"."edicao",
    "m"."local_publicacao",
    "m"."isbn",
    "m"."issn",
    "m"."idioma",
    "m"."tipo_material",
    "m"."colecao",
    "m"."assuntos",
    "m"."author_id",
    "m"."catalog_source",
    "m"."library_id",
    "m"."library_slug",
    "m"."library_name",
    "m"."biblioteca",
    "m"."has_online_reading",
    "m"."author_display",
    "m"."author_chips",
    "m"."exemplares_total",
    "m"."bibliotecas_count",
    "m"."global_available_count",
    "m"."global_exemplares_total",
    "m"."holding_library_names_json",
    "sc"."default_library_id" AS "session_library_id",
    "ls"."slug" AS "session_library_slug",
    "ls"."name" AS "session_library_name",
    COALESCE("sh"."exemplares_total", 0) AS "session_exemplares_total",
    ("sh"."holding_id" IS NOT NULL) AS "session_has_holding",
        CASE
            WHEN ("sc"."default_library_id" IS NULL) THEN 'sem_biblioteca_de_sessao'::"text"
            WHEN ("sh"."holding_id" IS NULL) THEN 'indisponivel_para_voce'::"text"
            WHEN (COALESCE("sh"."holding_loanable", "m"."loanable", true) IS FALSE) THEN 'consultavel_no_local'::"text"
            ELSE 'no_acervo_da_sua_biblioteca'::"text"
        END AS "session_status_hint",
    COALESCE("sh"."available_count", 0) AS "session_available_count",
    COALESCE("sh"."holding_loanable", "m"."loanable", true) AS "session_loanable"
   FROM ((("public"."mv_books_catalog_list_network_v1" "m"
     LEFT JOIN "session_ctx" "sc" ON (true))
     LEFT JOIN "public"."libraries" "ls" ON (("ls"."id" = "sc"."default_library_id")))
     LEFT JOIN "session_holdings" "sh" ON (("sh"."book_id" = "m"."book_id")))
  WHERE (( SELECT "is_network_member"."is_member"
           FROM "is_network_member") OR (EXISTS ( SELECT 1
           FROM ("public"."book_holdings" "h2"
             JOIN "public"."libraries" "l2" ON (("l2"."id" = "h2"."library_id")))
          WHERE (("h2"."book_id" = "m"."book_id") AND ("l2"."is_active" = true) AND ("l2"."visibility_level" = 'public'::"text")))));


ALTER VIEW "api"."catalog_list_session_v1" OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."network_admin_collective_removal_proposals" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "proposed_user_id" "uuid" NOT NULL,
    "proposed_by" "uuid" NOT NULL,
    "motivation" "text" NOT NULL,
    "status" "text" DEFAULT 'open'::"text" NOT NULL,
    "proposed_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "expires_at" timestamp with time zone DEFAULT ("now"() + '60 days'::interval) NOT NULL,
    "unanimous_at" timestamp with time zone,
    "pending_removal_until" timestamp with time zone,
    "cancelled_at" timestamp with time zone,
    "cancelled_by" "uuid",
    "cancellation_reason" "text",
    "executed_at" timestamp with time zone,
    CONSTRAINT "crp_motivation_length" CHECK (("length"(TRIM(BOTH FROM "motivation")) >= 50)),
    CONSTRAINT "crp_no_self_target" CHECK (("proposed_user_id" <> "proposed_by")),
    CONSTRAINT "crp_pending_implies_unanimous" CHECK ((("pending_removal_until" IS NULL) OR ("unanimous_at" IS NOT NULL))),
    CONSTRAINT "crp_status_check" CHECK (("status" = ANY (ARRAY['open'::"text", 'unanimous'::"text", 'cancelled'::"text", 'executed'::"text", 'expired'::"text"])))
);


ALTER TABLE "public"."network_admin_collective_removal_proposals" OWNER TO "postgres";


COMMENT ON TABLE "public"."network_admin_collective_removal_proposals" IS 'Propositions de retrait collectif admin réseau (Q5 v0.3). Workflow : open → unanimous (carence 7j) → executed | cancelled | expired.';



COMMENT ON COLUMN "public"."network_admin_collective_removal_proposals"."unanimous_at" IS 'Moment où le dernier vote favorable requis a été recueilli. Déclenche la carence de 7 jours.';



COMMENT ON COLUMN "public"."network_admin_collective_removal_proposals"."pending_removal_until" IS 'unanimous_at + 7 jours. Au-delà, le cron exécute le retrait (status active → removed).';



CREATE TABLE IF NOT EXISTS "public"."network_admin_collective_removal_votes" (
    "proposal_id" "uuid" NOT NULL,
    "voter_user_id" "uuid" NOT NULL,
    "vote" "text" NOT NULL,
    "rationale" "text",
    "disclose_identity" boolean NOT NULL,
    "voted_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "crv_rationale_if_against" CHECK ((("vote" = 'favor'::"text") OR (("vote" = 'against'::"text") AND ("length"(TRIM(BOTH FROM COALESCE("rationale", ''::"text"))) >= 20)))),
    CONSTRAINT "crv_vote_check" CHECK (("vote" = ANY (ARRAY['favor'::"text", 'against'::"text"])))
);


ALTER TABLE "public"."network_admin_collective_removal_votes" OWNER TO "postgres";


COMMENT ON TABLE "public"."network_admin_collective_removal_votes" IS 'Votes sur propositions de retrait collectif. Garde 7 : rationale ≥ 20 chars obligatoire si vote = against.';



COMMENT ON COLUMN "public"."network_admin_collective_removal_votes"."disclose_identity" IS 'Obligatoire (doctrine D.5). Si false, votant anonyme pour le target. Toujours visible pour les autres admins.';



CREATE TABLE IF NOT EXISTS "public"."network_administrators" (
    "user_id" "uuid" NOT NULL,
    "status" "text" DEFAULT 'active'::"text" NOT NULL,
    "coopted_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "coopted_by_unanimity_of" "uuid"[] DEFAULT ARRAY[]::"uuid"[] NOT NULL,
    "removal_requested_at" timestamp with time zone,
    "removal_reason" "text",
    "removed_at" timestamp with time zone,
    "last_seen_at" timestamp with time zone,
    "notes" "text",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "network_administrators_status_check" CHECK (("status" = ANY (ARRAY['active'::"text", 'pending_removal'::"text", 'removed'::"text", 'inactive'::"text"])))
);


ALTER TABLE "public"."network_administrators" OWNER TO "postgres";


COMMENT ON TABLE "public"."network_administrators" IS 'Personnes qui animent la coordination du réseau AnarBib. Cooptation à l''unanimité des administrateurs en place. Aucune library_id : leur autorité est transverse au réseau, jamais située dans une biblio particulière. Réf spec-administrateur-reseau.md.';



COMMENT ON COLUMN "public"."network_administrators"."coopted_by_unanimity_of" IS 'Liste des user_id des administrateurs qui ont voté favorablement à la cooptation. Doit être égal à l''ensemble des administrateurs actifs au moment de la cooptation.';



COMMENT ON COLUMN "public"."network_administrators"."last_seen_at" IS 'Dernière activité de l''administrateur. Utilisé pour la détection d''inactivité longue (>6 mois → passage auto à status=inactive).';



CREATE OR REPLACE VIEW "api"."collective_removal_proposals_current_v1" WITH ("security_invoker"='on') AS
 WITH "active_admin_count" AS (
         SELECT ("count"(*))::integer AS "total"
           FROM "public"."network_administrators"
          WHERE ("network_administrators"."status" = 'active'::"text")
        )
 SELECT "p"."id" AS "proposal_id",
    "p"."proposed_user_id",
    "p"."proposed_by",
    "p"."proposed_at",
    "p"."expires_at",
    "p"."motivation",
    "p"."status",
    "p"."unanimous_at",
    "p"."pending_removal_until",
    "target_profile"."public_id" AS "proposed_public_id",
    "target_profile"."first_name" AS "proposed_first_name",
    "target_profile"."last_name" AS "proposed_last_name",
    "target_profile"."email" AS "proposed_email",
    "proposer_profile"."public_id" AS "proposer_public_id",
    "proposer_profile"."first_name" AS "proposer_first_name",
    "proposer_profile"."last_name" AS "proposer_last_name",
    "proposer_profile"."email" AS "proposer_email",
    (( SELECT "count"(*) AS "count"
           FROM "public"."network_admin_collective_removal_votes" "v"
          WHERE (("v"."proposal_id" = "p"."id") AND ("v"."vote" = 'favor'::"text"))))::integer AS "favor_count",
    (( SELECT "count"(*) AS "count"
           FROM "public"."network_admin_collective_removal_votes" "v"
          WHERE (("v"."proposal_id" = "p"."id") AND ("v"."vote" = 'against'::"text"))))::integer AS "against_count",
    (( SELECT "active_admin_count"."total"
           FROM "active_admin_count") -
        CASE
            WHEN (EXISTS ( SELECT 1
               FROM "public"."network_administrators" "na"
              WHERE (("na"."user_id" = "p"."proposed_user_id") AND ("na"."status" = 'active'::"text")))) THEN 1
            ELSE 0
        END) AS "required_votes",
    (EXISTS ( SELECT 1
           FROM "public"."network_admin_collective_removal_votes" "v"
          WHERE (("v"."proposal_id" = "p"."id") AND ("v"."voter_user_id" = "auth"."uid"())))) AS "caller_has_voted",
    ("p"."proposed_user_id" = "auth"."uid"()) AS "caller_is_target",
    ("p"."proposed_by" = "auth"."uid"()) AS "caller_is_proposer"
   FROM (("public"."network_admin_collective_removal_proposals" "p"
     LEFT JOIN "public"."profiles" "target_profile" ON (("target_profile"."id" = "p"."proposed_user_id")))
     LEFT JOIN "public"."profiles" "proposer_profile" ON (("proposer_profile"."id" = "p"."proposed_by")))
  WHERE ("p"."status" = ANY (ARRAY['open'::"text", 'unanimous'::"text"]));


ALTER VIEW "api"."collective_removal_proposals_current_v1" OWNER TO "postgres";


COMMENT ON VIEW "api"."collective_removal_proposals_current_v1" IS 'E.4.c v0.3 - Vue listing propositions de retrait collectif ouvertes (status=''open'' ou ''unanimous'') avec identites resolves, comptes de votes (favor/against), denominateur unanimite, flags caller. SECURITY INVOKER. Frontend : AdminsPanel section "Propostas de retirada coletiva".';



CREATE TABLE IF NOT EXISTS "public"."consulta_item_workflow_v2" (
