    CONSTRAINT "consulta_item_workflow_v2_schedule_reply_status_chk" CHECK ((("schedule_reply_status" IS NULL) OR ("schedule_reply_status" = ANY (ARRAY['confirmado_leitor'::"text", 'recusado_leitor'::"text"])))),
    CONSTRAINT "consulta_item_workflow_v2_stage_chk" CHECK (("workflow_stage" = ANY (ARRAY['solicitada'::"text", 'em_preparacao'::"text", 'consulta_agendada'::"text", 'consulta_realizada'::"text", 'nao_compareceu'::"text", 'cancelada_leitor'::"text", 'cancelada_biblioteca'::"text", 'expirada'::"text"])))
);


