CREATE TABLE IF NOT EXISTS "public"."consulta_linhas_v2" (
    "id" bigint NOT NULL,
    "consulta_id" bigint NOT NULL,
    "line_no" integer NOT NULL,
    "sub_id" "text" GENERATED ALWAYS AS (((("consulta_id")::"text" || '.'::"text") || ("line_no")::"text")) STORED,
    "book_id" bigint,
    "holding_id" bigint NOT NULL,
    "bib_ref" "text" NOT NULL,
    "titulo_cache" "text",
    "autor_cache" "text",
    "editora_cache" "text",
    "ano_cache" "text",
    "item_status" "text" DEFAULT 'ativa'::"text" NOT NULL,
    "expires_at" timestamp with time zone,
    "cancelled_at" timestamp with time zone,
    "consulted_at" timestamp with time zone,
    "expired_at" timestamp with time zone,
    "notes" "text",
    "created_at" timestamp with time zone DEFAULT "timezone"('utc'::"text", "now"()) NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "timezone"('utc'::"text", "now"()) NOT NULL,
    "dismissed_by_reader_at" timestamp with time zone,
    "item_id" bigint NOT NULL,
    "is_hidden_by_user" boolean DEFAULT false NOT NULL,
    "hidden_at" timestamp with time zone,
    CONSTRAINT "consulta_linhas_v2_cancelled_consistency_chk" CHECK (((("item_status" = ANY (ARRAY['cancelada_leitor'::"text", 'cancelada_biblioteca'::"text"])) AND ("cancelled_at" IS NOT NULL)) OR ("item_status" <> ALL (ARRAY['cancelada_leitor'::"text", 'cancelada_biblioteca'::"text"])))),
    CONSTRAINT "consulta_linhas_v2_consulted_consistency_chk" CHECK (((("item_status" = 'consultada'::"text") AND ("consulted_at" IS NOT NULL)) OR ("item_status" <> 'consultada'::"text"))),
    CONSTRAINT "consulta_linhas_v2_expired_consistency_chk" CHECK (((("item_status" = 'expirada'::"text") AND ("expired_at" IS NOT NULL)) OR ("item_status" <> 'expirada'::"text"))),
    CONSTRAINT "consulta_linhas_v2_item_status_chk" CHECK (("item_status" = ANY (ARRAY['ativa'::"text", 'consultada'::"text", 'cancelada_leitor'::"text", 'cancelada_biblioteca'::"text", 'expirada'::"text"]))),
    CONSTRAINT "consulta_linhas_v2_line_no_chk" CHECK (("line_no" > 0))
);


