COMMENT ON COLUMN "public"."consulta_linhas_v2"."item_id" IS 'Exemplaire precis vise par la ligne de consultation (#MODEL-item-grain). Reference forte. holding_id est conserve comme reference de confort.';



CREATE TABLE IF NOT EXISTS "public"."consultas_locais_v2" (
    "id" bigint NOT NULL,
    "user_id" "uuid" NOT NULL,
    "library_id" "uuid" NOT NULL,
    "notes" "text",
