    CONSTRAINT "motivation_not_too_short" CHECK (("length"(TRIM(BOTH FROM "motivation")) >= 20)),
    CONSTRAINT "network_administrator_cooptation_proposals_status_check" CHECK (("status" = ANY (ARRAY['open'::"text", 'completed'::"text", 'rejected'::"text", 'cancelled'::"text", 'expired'::"text"])))
);


ALTER TABLE "public"."network_administrator_cooptation_proposals" OWNER TO "postgres";


