CREATE TABLE IF NOT EXISTS "public"."network_administrator_cooptation_votes" (
    "proposal_id" "uuid" NOT NULL,
    "voter_user_id" "uuid" NOT NULL,
    "vote" "text" NOT NULL,
    "voted_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "rationale" "text",
    "disclose_identity" boolean NOT NULL,
    CONSTRAINT "network_administrator_cooptation_votes_vote_check" CHECK (("vote" = ANY (ARRAY['favorable'::"text", 'opposed'::"text", 'abstain'::"text"])))
