   user_public_id/user_email/user_name via LEFT JOIN profiles.';



CREATE OR REPLACE VIEW "api"."emprestimo_lotes_painel_ui" WITH ("security_invoker"='true') AS
 WITH "itens" AS (
         SELECT "emprestimo_itens_painel_ui"."emprestimo_id",
            "emprestimo_itens_painel_ui"."emprestimo_item_id",
            "emprestimo_itens_painel_ui"."line_no",
            "emprestimo_itens_painel_ui"."sub_id",
            "emprestimo_itens_painel_ui"."user_id",
            "emprestimo_itens_painel_ui"."user_public_id",
            "emprestimo_itens_painel_ui"."user_email",
            "emprestimo_itens_painel_ui"."user_name",
            "emprestimo_itens_painel_ui"."emprestimo_created_at",
            "emprestimo_itens_painel_ui"."due_at",
            "emprestimo_itens_painel_ui"."emprestimo_status",
            "emprestimo_itens_painel_ui"."item_status",
            "emprestimo_itens_painel_ui"."returned_at",
            "emprestimo_itens_painel_ui"."book_id",
            "emprestimo_itens_painel_ui"."item_id",
            "emprestimo_itens_painel_ui"."bib_ref",
            "emprestimo_itens_painel_ui"."rotulo",
            "emprestimo_itens_painel_ui"."autor",
            "emprestimo_itens_painel_ui"."titulo",
            "emprestimo_itens_painel_ui"."editora",
            "emprestimo_itens_painel_ui"."ano",
            "emprestimo_itens_painel_ui"."return_scheduled_for",
            "emprestimo_itens_painel_ui"."return_scheduled_by",
            "emprestimo_itens_painel_ui"."return_scheduled_at",
            "emprestimo_itens_painel_ui"."return_schedule_status",
            "emprestimo_itens_painel_ui"."return_completed_at",
            "emprestimo_itens_painel_ui"."return_missed_at",
            "emprestimo_itens_painel_ui"."extended_until",
            "emprestimo_itens_painel_ui"."extension_note",
            "emprestimo_itens_painel_ui"."extended_once"
           FROM "api"."emprestimo_itens_painel_ui"
          WHERE ("emprestimo_itens_painel_ui"."item_status" = 'aberto'::"text")
        )
 SELECT "emprestimo_id",
    "user_id",
    "max"("user_public_id") AS "user_public_id",
    "max"("user_email") AS "user_email",
    "max"("user_name") AS "user_name",
    "min"("emprestimo_created_at") AS "emprestimo_created_at",
    ("count"(*))::integer AS "quantity",
    "array_agg"("sub_id" ORDER BY "line_no") AS "sub_ids",
    "array_agg"("line_no" ORDER BY "line_no") AS "line_nos",
    "array_agg"("bib_ref" ORDER BY "line_no") AS "bib_refs",
    "min"("due_at") AS "first_due_at",
    "max"(COALESCE("extended_until", "due_at")) AS "due_at_effective",
        CASE
            WHEN "bool_or"((COALESCE("extended_until", "due_at") < CURRENT_DATE)) THEN 'bad'::"text"
            WHEN ("bool_or"(("extended_until" IS NOT NULL)) OR "bool_or"("extended_once")) THEN 'warn'::"text"
            ELSE 'ok'::"text"
        END AS "status_class",
        CASE
            WHEN "bool_or"((COALESCE("extended_until", "due_at") < CURRENT_DATE)) THEN 'Com atraso'::"text"
            WHEN ("bool_or"(("extended_until" IS NOT NULL)) OR "bool_or"("extended_once")) THEN 'Renovado'::"text"
            ELSE 'Em curso'::"text"
        END AS "status_text",
        CASE
            WHEN ("count"(DISTINCT "return_schedule_status") = 1) THEN "min"("return_schedule_status")
            ELSE NULL::"text"
        END AS "return_schedule_status",
        CASE
            WHEN ("count"(DISTINCT "return_scheduled_for") = 1) THEN "min"("return_scheduled_for")
            ELSE NULL::timestamp with time zone
        END AS "return_scheduled_for",
    "bool_or"("extended_once") AS "extended_once"
   FROM "itens"
  GROUP BY "emprestimo_id", "user_id";


