CREATE OR REPLACE VIEW "api"."interlibrary_loan_items_ui" WITH ("security_invoker"='true') AS
 SELECT "h"."id" AS "interlibrary_loan_id",
    "i"."id" AS "interlibrary_loan_item_id",
    "i"."line_no",
    "i"."sub_id",
    "h"."request_id",
    "h"."lender_library_id",
    "ll"."slug" AS "lender_library_slug",
    "ll"."name" AS "lender_library_name",
    "ll"."short_name" AS "lender_library_short_name",
    "h"."borrower_library_id",
    "bl"."slug" AS "borrower_library_slug",
    "bl"."name" AS "borrower_library_name",
    "bl"."short_name" AS "borrower_library_short_name",
        CASE
            WHEN ("public"."user_can_manage_library"("h"."lender_library_id") AND "public"."user_can_manage_library"("h"."borrower_library_id")) THEN 'ambas'::"text"
            WHEN "public"."user_can_manage_library"("h"."lender_library_id") THEN 'emprestadora'::"text"
            WHEN "public"."user_can_manage_library"("h"."borrower_library_id") THEN 'tomadora'::"text"
            ELSE NULL::"text"
        END AS "local_role",
        CASE
            WHEN ("public"."user_can_manage_library"("h"."lender_library_id") AND (NOT "public"."user_can_manage_library"("h"."borrower_library_id"))) THEN "h"."borrower_library_id"
            WHEN ("public"."user_can_manage_library"("h"."borrower_library_id") AND (NOT "public"."user_can_manage_library"("h"."lender_library_id"))) THEN "h"."lender_library_id"
            ELSE NULL::"uuid"
        END AS "partner_library_id",
        CASE
            WHEN ("public"."user_can_manage_library"("h"."lender_library_id") AND (NOT "public"."user_can_manage_library"("h"."borrower_library_id"))) THEN "bl"."name"
            WHEN ("public"."user_can_manage_library"("h"."borrower_library_id") AND (NOT "public"."user_can_manage_library"("h"."lender_library_id"))) THEN "ll"."name"
            ELSE NULL::"text"
        END AS "partner_library_name",
    COALESCE("i"."book_id", "bh"."book_id") AS "book_id",
    "i"."holding_id",
    "i"."item_id",
    COALESCE("i"."bib_ref", "bh"."local_bib_ref", "e"."bib_ref") AS "bib_ref",
    COALESCE("i"."rotulo_cache", "e"."tombo") AS "tombo",
    "i"."titulo_cache" AS "titulo",
    "i"."autor_cache" AS "autor",
    "i"."editora_cache" AS "editora",
    "i"."ano_cache" AS "ano",
    "h"."status_global",
    "i"."item_status",
    "h"."start_date",
    COALESCE("i"."due_date", "h"."due_date") AS "due_date",
    "i"."reserved_at",
    "i"."dispatched_at",
    "i"."returned_at",
        CASE
            WHEN (("i"."item_status" = 'emprestado'::"text") AND (COALESCE("i"."due_date", "h"."due_date") IS NOT NULL) AND (COALESCE("i"."due_date", "h"."due_date") < CURRENT_DATE)) THEN true
            ELSE false
        END AS "is_overdue",
        CASE
            WHEN ("i"."returned_at" IS NOT NULL) THEN 0
            WHEN (COALESCE("i"."due_date", "h"."due_date") IS NULL) THEN NULL::integer
            ELSE GREATEST((COALESCE("i"."due_date", "h"."due_date") - CURRENT_DATE), 0)
        END AS "days_until_due",
        CASE
            WHEN ("i"."returned_at" IS NOT NULL) THEN 0
            WHEN (COALESCE("i"."due_date", "h"."due_date") IS NULL) THEN NULL::integer
            WHEN (COALESCE("i"."due_date", "h"."due_date") < CURRENT_DATE) THEN (CURRENT_DATE - COALESCE("i"."due_date", "h"."due_date"))
            ELSE 0
        END AS "days_overdue",
    "h"."coordination_contact_name",
    "h"."coordination_contact_email",
    "h"."coordination_contact_phone",
    "h"."logistics_mode",
    "h"."meeting_point",
    "h"."notes" AS "loan_notes",
    "i"."notes" AS "item_notes",
    "h"."created_at",
    "h"."updated_at"
   FROM ((((("public"."interlibrary_loans_v2" "h"
     JOIN "public"."interlibrary_loan_items_v2" "i" ON (("i"."interlibrary_loan_id" = "h"."id")))
     LEFT JOIN "public"."book_holdings" "bh" ON (("bh"."id" = "i"."holding_id")))
     LEFT JOIN "public"."exemplares" "e" ON (("e"."id" = "i"."item_id")))
     LEFT JOIN "public"."libraries" "ll" ON (("ll"."id" = "h"."lender_library_id")))
     LEFT JOIN "public"."libraries" "bl" ON (("bl"."id" = "h"."borrower_library_id")))
  WHERE (("h"."archived_at" IS NULL) AND ("public"."user_can_manage_library"("h"."lender_library_id") OR "public"."user_can_manage_library"("h"."borrower_library_id")));


