    CONSTRAINT "reservas_v2_status_global_chk" CHECK (("status_global" = ANY (ARRAY['ativa'::"text", 'parcialmente_encerrada'::"text", 'encerrada'::"text"])))
);


ALTER TABLE "public"."reservas_v2" OWNER TO "postgres";


COMMENT ON TABLE "public"."reservas_v2" IS 'Réservations (en-tête). Données utilisateur·ice. Anon SELECT révoqué le 2026-04-26 (palier 3). Accès via api.my_reservations_active_v2 / api.my_reservations_history_v2.';



CREATE OR REPLACE VIEW "api"."library_archived_transactions" WITH ("security_invoker"='true') AS
 SELECT 'emprestimos_v2'::"text" AS "table_name",
    ("e"."id")::"text" AS "record_id",
    "e"."library_id",
    "e"."archived_at",
    "e"."archive_reason",
    ("e"."due_at")::"text" AS "due_reference",
    "e"."status_global" AS "original_status",
    "e"."created_at" AS "originally_created_at",
    "e"."user_id" AS "related_user_id"
   FROM "public"."emprestimos_v2" "e"
  WHERE ("e"."archived_at" IS NOT NULL)
UNION ALL
 SELECT 'reservas_v2'::"text" AS "table_name",
    ("r"."id")::"text" AS "record_id",
    "r"."library_id",
    "r"."archived_at",
    "r"."archive_reason",
    NULL::"text" AS "due_reference",
    "r"."status_global" AS "original_status",
    "r"."created_at" AS "originally_created_at",
    "r"."user_id" AS "related_user_id"
   FROM "public"."reservas_v2" "r"
  WHERE ("r"."archived_at" IS NOT NULL)
UNION ALL
 SELECT 'consultas_locais_v2'::"text" AS "table_name",
    ("c"."id")::"text" AS "record_id",
    "c"."library_id",
    "c"."archived_at",
    "c"."archive_reason",
    NULL::"text" AS "due_reference",
    "c"."status_global" AS "original_status",
    "c"."created_at" AS "originally_created_at",
    "c"."user_id" AS "related_user_id"
   FROM "public"."consultas_locais_v2" "c"
  WHERE ("c"."archived_at" IS NOT NULL)
UNION ALL
 SELECT 'interlibrary_loans_v2'::"text" AS "table_name",
    ("h"."id")::"text" AS "record_id",
    "h"."lender_library_id" AS "library_id",
    "h"."archived_at",
    "h"."archive_reason",
    ("h"."due_date")::"text" AS "due_reference",
    "h"."status_global" AS "original_status",
    "h"."created_at" AS "originally_created_at",
    NULL::"uuid" AS "related_user_id"
   FROM "public"."interlibrary_loans_v2" "h"
  WHERE ("h"."archived_at" IS NOT NULL)
UNION ALL
 SELECT 'membership_payments'::"text" AS "table_name",
    ("mp"."id")::"text" AS "record_id",
    "mp"."library_id",
    "mp"."archived_at",
    "mp"."archive_reason",
    ("mp"."valid_until")::"text" AS "due_reference",
    'cotisation_archived'::"text" AS "original_status",
    "mp"."created_at" AS "originally_created_at",
    "mp"."user_id" AS "related_user_id"
   FROM "public"."membership_payments" "mp"
  WHERE ("mp"."archived_at" IS NOT NULL);


