CREATE OR REPLACE VIEW "api"."library_partnerships_ui" WITH ("security_invoker"='true') AS
 SELECT "lp"."id",
    "lp"."library_id",
        CASE
            WHEN ("lp"."partner_library_id" IS NOT NULL) THEN 'library'::"text"
            ELSE 'catalog_partner'::"text"
        END AS "partner_kind",
    "lp"."partner_library_id",
    "lp"."partner_catalog_id",
    COALESCE("pl"."short_name", "pl"."name", "cp"."display_name") AS "partner_display_name",
    "pl"."slug" AS "partner_library_slug",
    "pl"."network_mode" AS "partner_library_network_mode",
    "cp"."slug" AS "partner_catalog_slug",
    "cp"."base_url" AS "partner_catalog_base_url",
    "cp"."country_code" AS "partner_catalog_country_code",
        CASE
            WHEN ("lp"."partner_library_id" IS NOT NULL) THEN (EXISTS ( SELECT 1
               FROM "public"."library_partnerships" "rev"
              WHERE (("rev"."library_id" = "lp"."partner_library_id") AND ("rev"."partner_library_id" = "lp"."library_id"))))
            ELSE NULL::boolean
        END AS "is_reciprocal",
    "lp"."notes",
    "lp"."created_at",
    "lp"."created_by"
   FROM (("public"."library_partnerships" "lp"
     LEFT JOIN "public"."libraries" "pl" ON (("pl"."id" = "lp"."partner_library_id")))
     LEFT JOIN "public"."catalog_partners" "cp" ON (("cp"."id" = "lp"."partner_catalog_id")));


ALTER VIEW "api"."library_partnerships_ui" OWNER TO "postgres";


COMMENT ON VIEW "api"."library_partnerships_ui" IS 'Vue UI des partenaires de correspondance par bibliotheque. security_invoker : la RLS de library_partnerships s''applique. Resout le nom et les metadonnees du partenaire selon son type, et calcule la reciprocite pour les partenaires-biblio.';



