CREATE OR REPLACE VIEW "api"."my_access" WITH ("security_invoker"='true') AS
 WITH "base" AS (
         SELECT "sc"."user_id",
            "sc"."email",
            "sc"."first_name",
            "sc"."last_name",
            "sc"."full_name",
            "sc"."is_authenticated",
            "sc"."is_librarian",
            "sc"."default_library_id",
            "sc"."default_library_slug",
            "sc"."default_library_name",
            "sc"."can_access_conta"
           FROM "api"."my_session_context" "sc"
        ), "active_memberships" AS (
         SELECT "m"."user_id",
            "l"."id" AS "library_id",
            "l"."slug" AS "library_slug",
            "l"."name" AS "library_name",
            "m"."role",
            "m"."status",
            "m"."is_primary",
            "m"."created_at"
           FROM ("public"."user_library_memberships" "m"
             JOIN "public"."libraries" "l" ON (("l"."id" = "m"."library_id")))
          WHERE (("m"."status" = 'active'::"text") AND ("l"."is_active" = true) AND ("m"."user_id" = "auth"."uid"()))
        ), "effective_membership" AS (
         SELECT "active_memberships"."user_id",
            "active_memberships"."library_id",
            "active_memberships"."library_slug",
            "active_memberships"."library_name",
            "active_memberships"."role",
            "active_memberships"."status",
            "active_memberships"."is_primary",
            "active_memberships"."created_at"
           FROM "active_memberships"
          ORDER BY "active_memberships"."is_primary" DESC, "active_memberships"."created_at", "active_memberships"."library_slug"
         LIMIT 1
        ), "network_admin_status" AS (
         SELECT (EXISTS ( SELECT 1
                   FROM "public"."network_administrators"
                  WHERE (("network_administrators"."user_id" = "auth"."uid"()) AND ("network_administrators"."status" = 'active'::"text")))) AS "is_network_admin"
        ), "has_any_staff_membership" AS (
         SELECT (EXISTS ( SELECT 1
                   FROM "active_memberships" "am"
                  WHERE ("am"."role" = ANY (ARRAY['librarian'::"text", 'coordenador'::"text"])))) AS "has_staff"
        )
 SELECT "b"."user_id" AS "id",
    "b"."email",
    "b"."is_librarian",
    COALESCE("p"."is_restricted", false) AS "is_restricted",
    "b"."default_library_id",
    "b"."default_library_slug",
    "b"."default_library_name",
    "b"."can_access_conta",
    (("has_staff"."has_staff" OR "na"."is_network_admin") AND (COALESCE("p"."is_restricted", false) = false)) AS "can_access_painel",
    (("has_staff"."has_staff" OR "na"."is_network_admin") AND (COALESCE("p"."is_restricted", false) = false)) AS "can_access_catalogacao",
    "b"."user_id",
    "p"."public_id",
    "p"."first_name",
    "p"."last_name",
    "em"."library_id",
    "em"."library_slug",
    "em"."library_name",
    "em"."role",
    "em"."status",
    "em"."is_primary"
   FROM (((("base" "b"
     LEFT JOIN "public"."profiles" "p" ON (("p"."id" = "b"."user_id")))
     LEFT JOIN "effective_membership" "em" ON (("em"."user_id" = "b"."user_id")))
     CROSS JOIN "network_admin_status" "na")
     CROSS JOIN "has_any_staff_membership" "has_staff");


ALTER VIEW "api"."my_access" OWNER TO "postgres";


COMMENT ON VIEW "api"."my_access" IS 'Contexte de l''utilisateur·rice connecté·e : identité, biblio par défaut, statuts staff et admin réseau, droits d''accès UI (can_access_painel, can_access_catalogacao). security_invoker=true depuis paquet L.11 (12/05/2026). Filtrage interne par auth.uid() sur user_library_memberships et network_administrators, donc la vue ne retourne jamais que les données du caller. Accessible à authenticated uniquement, pas à anon.';



CREATE OR REPLACE VIEW "api"."my_profile" WITH ("security_invoker"='true') AS
 WITH "session_ctx" AS (
         SELECT "my_session_context"."user_id",
            "my_session_context"."email",
            "my_session_context"."first_name",
            "my_session_context"."last_name",
            "my_session_context"."full_name",
            "my_session_context"."is_authenticated",
            "my_session_context"."is_librarian",
            "my_session_context"."default_library_id",
            "my_session_context"."default_library_slug",
            "my_session_context"."default_library_name",
            "my_session_context"."can_access_conta",
            "my_session_context"."can_access_painel",
            "my_session_context"."can_access_catalogacao"
           FROM "api"."my_session_context"
        ), "profile_row" AS (
         SELECT "p"."id",
            "p"."email",
            "p"."first_name",
            "p"."last_name",
            "p"."phone",
            "p"."address",
            "p"."gender",
            "p"."is_librarian",
            "p"."must_change_password",
            "p"."password_changed_at",
            "p"."is_restricted",
            "p"."restricted_since",
            "p"."restricted_reason",
            "p"."consent_email",
            "p"."created_at",
            "p"."updated_at"
           FROM ("public"."profiles" "p"
             JOIN "session_ctx" "s_1" ON (("s_1"."user_id" = "p"."id")))
        )
 SELECT "s"."user_id" AS "id",
    "s"."is_authenticated",
    ("pr"."id" IS NOT NULL) AS "has_profile_row",
    COALESCE("pr"."email", "s"."email") AS "email",
    COALESCE("pr"."first_name", "s"."first_name") AS "first_name",
    COALESCE("pr"."last_name", "s"."last_name") AS "last_name",
    COALESCE(NULLIF("btrim"("concat_ws"(' '::"text", COALESCE("pr"."first_name", ''::"text"), COALESCE("pr"."last_name", ''::"text"))), ''::"text"), "s"."full_name") AS "full_name",
    "pr"."phone",
    "pr"."address",
    "pr"."gender",
    COALESCE("pr"."consent_email", false) AS "consent_email",
    COALESCE("s"."is_librarian", "pr"."is_librarian", false) AS "is_librarian",
    COALESCE("pr"."must_change_password", false) AS "must_change_password",
    "pr"."password_changed_at",
    COALESCE("pr"."is_restricted", false) AS "is_restricted",
    "pr"."restricted_since",
    "pr"."restricted_reason",
    "s"."default_library_id",
    "s"."default_library_slug",
    "s"."default_library_name",
    "s"."can_access_conta",
    "s"."can_access_painel",
    "s"."can_access_catalogacao",
    "pr"."created_at",
    "pr"."updated_at"
   FROM ("session_ctx" "s"
     LEFT JOIN "profile_row" "pr" ON (("pr"."id" = "s"."user_id")));


