CREATE OR REPLACE VIEW "api"."my_loans_history_v1" WITH ("security_invoker"='true') AS
 WITH "me" AS (
         SELECT "mp"."id",
            "mp"."is_authenticated",
            "mp"."default_library_id"
           FROM "api"."my_profile" "mp"
        ), "items_aggreg" AS (
         SELECT "i"."emprestimo_id",
            ("count"(*))::integer AS "items_count",
            "string_agg"(COALESCE("i"."titulo_cache", (('['::"text" || COALESCE("i"."bib_ref", ''::"text")) || ']'::"text")), ' ; '::"text" ORDER BY "i"."line_no") AS "titulos",
            "string_agg"(DISTINCT COALESCE("i"."autor_cache", ''::"text"), ' ; '::"text") FILTER (WHERE (COALESCE("i"."autor_cache", ''::"text") <> ''::"text")) AS "autores",
            "string_agg"("i"."bib_ref", ' ; '::"text" ORDER BY "i"."line_no") AS "bib_refs",
            "max"("i"."returned_at") AS "last_returned_at",
            "min"("i"."book_id") AS "first_book_id"
           FROM "public"."emprestimo_itens_v2" "i"
          GROUP BY "i"."emprestimo_id"
        )
 SELECT "e"."id" AS "emprestimo_id",
    "e"."id",
    "e"."user_id",
    "e"."library_id",
    "l"."library_slug",
    "l"."display_name" AS "library_name",
    ("e"."library_id" = "m"."default_library_id") AS "is_default_library",
    "e"."status_global",
    "e"."notes",
    "e"."created_at" AS "emprestimo_created_at",
    "e"."created_at",
    "e"."updated_at",
    "e"."due_at",
    "e"."extended_once",
    "e"."extended_at",
    "e"."renewals_used",
    "ia"."items_count",
    "ia"."titulos",
    "ia"."autores",
    "ia"."bib_refs",
    "ia"."last_returned_at" AS "returned_at",
    "ia"."first_book_id" AS "book_id",
    COALESCE("ia"."last_returned_at", "e"."updated_at") AS "closed_at",
    "e"."is_hidden_by_user"
   FROM ((("public"."emprestimos_v2" "e"
     JOIN "me" "m" ON (("e"."user_id" = "m"."id")))
     LEFT JOIN "items_aggreg" "ia" ON (("ia"."emprestimo_id" = "e"."id")))
     LEFT JOIN "public"."library_commons" "l" ON (("l"."library_id" = "e"."library_id")))
  WHERE (("m"."is_authenticated" = true) AND ("e"."status_global" = 'encerrado'::"text") AND (EXISTS ( SELECT 1
           FROM "public"."libraries" "lib"
          WHERE (("lib"."id" = "e"."library_id") AND ("lib"."circulation_mode" <> 'off'::"text")))))
  ORDER BY COALESCE("ia"."last_returned_at", "e"."updated_at") DESC, "e"."id" DESC;


ALTER VIEW "api"."my_loans_history_v1" OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."reserva_linhas_v2" (
    "id" bigint NOT NULL,
    "reserva_id" bigint NOT NULL,
    "line_no" integer NOT NULL,
    "sub_id" "text" GENERATED ALWAYS AS (((("reserva_id")::"text" || '.'::"text") || ("line_no")::"text")) STORED,
    "book_id" bigint,
    "bib_ref" "text" NOT NULL,
    "item_id" bigint,
    "titulo_cache" "text",
    "autor_cache" "text",
    "rotulo_cache" "text",
    "editora_cache" "text",
    "ano_cache" "text",
    "item_status" "text" DEFAULT 'ativa'::"text" NOT NULL,
    "expires_at" timestamp with time zone,
    "cancelled_at" timestamp with time zone,
    "converted_at" timestamp with time zone,
    "expired_at" timestamp with time zone,
    "emprestimo_item_id" bigint,
    "notes" "text",
    "created_at" timestamp with time zone DEFAULT "timezone"('utc'::"text", "now"()) NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "timezone"('utc'::"text", "now"()) NOT NULL,
    "holding_id" bigint,
    "is_hidden_by_user" boolean DEFAULT false NOT NULL,
    "hidden_at" timestamp with time zone,
    CONSTRAINT "reserva_linhas_v2_cancelled_consistency_chk" CHECK (((("item_status" = ANY (ARRAY['cancelada_leitor'::"text", 'cancelada_biblioteca'::"text"])) AND ("cancelled_at" IS NOT NULL)) OR ("item_status" <> ALL (ARRAY['cancelada_leitor'::"text", 'cancelada_biblioteca'::"text"])))),
    CONSTRAINT "reserva_linhas_v2_converted_consistency_chk" CHECK (((("item_status" = 'convertida_em_emprestimo'::"text") AND ("converted_at" IS NOT NULL)) OR ("item_status" <> 'convertida_em_emprestimo'::"text"))),
    CONSTRAINT "reserva_linhas_v2_expired_consistency_chk" CHECK (((("item_status" = 'expirada'::"text") AND ("expired_at" IS NOT NULL)) OR ("item_status" <> 'expirada'::"text"))),
    CONSTRAINT "reserva_linhas_v2_item_status_chk" CHECK (("item_status" = ANY (ARRAY['ativa'::"text", 'convertida_em_emprestimo'::"text", 'cancelada_leitor'::"text", 'cancelada_biblioteca'::"text", 'expirada'::"text", 'liberada_para_circulacao'::"text"]))),
    CONSTRAINT "reserva_linhas_v2_line_no_chk" CHECK (("line_no" > 0))
);


ALTER TABLE "public"."reserva_linhas_v2" OWNER TO "postgres";


COMMENT ON TABLE "public"."reserva_linhas_v2" IS 'Lignes de réservations. Données utilisateur·ice. Anon SELECT révoqué le 2026-04-26 (palier 3).';



CREATE OR REPLACE VIEW "api"."my_loans_renewal_status_by_item_v1" WITH ("security_invoker"='true') AS
 WITH "my_open_items" AS (
         SELECT "e"."id" AS "emprestimo_id",
            "i"."line_no",
            "i"."sub_id",
            "i"."book_id",
            "i"."holding_id",
            "e"."user_id",
            "e"."library_id",
            COALESCE("i"."renewals_used", 0) AS "renewals_used",
            COALESCE("i"."extended_until", "i"."due_at") AS "effective_due_at"
           FROM ("public"."emprestimos_v2" "e"
             JOIN "public"."emprestimo_itens_v2" "i" ON (("i"."emprestimo_id" = "e"."id")))
          WHERE (("e"."user_id" = "auth"."uid"()) AND ("e"."archived_at" IS NULL) AND ("i"."item_status" = 'aberto'::"text"))
        ), "with_dues" AS (
         SELECT "l"."emprestimo_id",
            "l"."line_no",
            "l"."sub_id",
            "l"."book_id",
            "l"."holding_id",
            "l"."user_id",
            "l"."library_id",
            "l"."renewals_used",
            "l"."effective_due_at",
            "public"."fn_is_loan_blocked_by_dues"("l"."user_id", "l"."library_id") AS "dues_blocked",
            (EXISTS ( SELECT 1
                   FROM ("public"."reserva_linhas_v2" "rl"
                     JOIN "public"."reservas_v2" "r" ON (("r"."id" = "rl"."reserva_id")))
                  WHERE (("rl"."book_id" = "l"."book_id") AND ("r"."library_id" = "l"."library_id") AND ("r"."user_id" <> "l"."user_id") AND ("r"."status_global" = ANY (ARRAY['ativa'::"text", 'parcialmente_encerrada'::"text"])) AND ("rl"."item_status" = 'ativa'::"text") AND ("r"."archived_at" IS NULL)))) AS "reserved_by_other"
           FROM "my_open_items" "l"
        ), "with_rule" AS (
         SELECT "w"."emprestimo_id",
            "w"."line_no",
            "w"."sub_id",
            "w"."book_id",
            "w"."holding_id",
            "w"."user_id",
            "w"."library_id",
            "w"."renewals_used",
            "w"."effective_due_at",
            "w"."dues_blocked",
            "w"."reserved_by_other",
            "rr"."renewable",
            "rr"."renewals_remaining",
            "rr"."renewal_days",
            "rr"."rule_label"
           FROM ("with_dues" "w"
             LEFT JOIN LATERAL "api"."get_remaining_renewals"("p_library_id" => "w"."library_id", "p_user_id" => "w"."user_id", "p_book_id" => "w"."book_id", "p_holding_id" => "w"."holding_id", "p_quantity" => 1, "p_renewals_used" => "w"."renewals_used", "p_as_of_date" => CURRENT_DATE) "rr"("renewable", "renewals_remaining", "renewal_days", "policy_set_id", "rule_id", "rule_label", "explanation") ON (true))
        )
 SELECT "emprestimo_id",
    "line_no",
    "sub_id",
    "library_id",
    "book_id",
    "effective_due_at",
    "renewals_used",
    COALESCE("renewable", false) AS "renewable",
    COALESCE("renewals_remaining", 0) AS "renewals_remaining",
    "rule_label",
        CASE
            WHEN "dues_blocked" THEN 'dues_blocked'::"text"
            WHEN (COALESCE("effective_due_at", CURRENT_DATE) < CURRENT_DATE) THEN 'overdue'::"text"
            WHEN "reserved_by_other" THEN 'reserved_by_other'::"text"
            WHEN ((COALESCE("renewable", false) IS FALSE) AND (COALESCE("renewals_remaining", 0) <= 0) AND (COALESCE("renewals_used", 0) > 0)) THEN 'quota_exceeded'::"text"
            WHEN (COALESCE("renewable", false) IS FALSE) THEN 'not_renewable'::"text"
            WHEN ((COALESCE("renewals_used", 0) >= 1) AND (COALESCE("renewals_remaining", 0) <= 0)) THEN 'already_extended'::"text"
            ELSE NULL::"text"
        END AS "blocking_reason",
    ((COALESCE("renewable", false) IS TRUE) AND (NOT "dues_blocked") AND (COALESCE("effective_due_at", CURRENT_DATE) >= CURRENT_DATE) AND (NOT "reserved_by_other") AND (COALESCE("renewals_remaining", 0) > 0)) AS "can_renew"
   FROM "with_rule";


ALTER VIEW "api"."my_loans_renewal_status_by_item_v1" OWNER TO "postgres";


CREATE OR REPLACE VIEW "api"."my_loans_renewal_status_v1" WITH ("security_invoker"='true') AS
 WITH "my_open_loans" AS (
         SELECT "e"."id" AS "emprestimo_id",
            "e"."user_id",
            "e"."library_id",
            "e"."renewals_used",
            "e"."extended_once",
            ( SELECT ("count"(*))::integer AS "count"
                   FROM "public"."emprestimo_itens_v2" "i"
                  WHERE (("i"."emprestimo_id" = "e"."id") AND ("i"."item_status" = 'aberto'::"text"))) AS "open_items_count",
            ( SELECT "min"("i"."book_id") AS "min"
                   FROM "public"."emprestimo_itens_v2" "i"
                  WHERE (("i"."emprestimo_id" = "e"."id") AND ("i"."item_status" = 'aberto'::"text"))) AS "first_book_id",
            ( SELECT "min"("i"."holding_id") AS "min"
                   FROM "public"."emprestimo_itens_v2" "i"
                  WHERE (("i"."emprestimo_id" = "e"."id") AND ("i"."item_status" = 'aberto'::"text"))) AS "first_holding_id",
            ( SELECT "max"(COALESCE("i"."extended_until", "i"."due_at")) AS "max"
                   FROM "public"."emprestimo_itens_v2" "i"
                  WHERE (("i"."emprestimo_id" = "e"."id") AND ("i"."item_status" = 'aberto'::"text"))) AS "effective_due_at"
           FROM "public"."emprestimos_v2" "e"
          WHERE (("e"."user_id" = "auth"."uid"()) AND ("e"."archived_at" IS NULL) AND (EXISTS ( SELECT 1
                   FROM "public"."emprestimo_itens_v2" "i"
                  WHERE (("i"."emprestimo_id" = "e"."id") AND ("i"."item_status" = 'aberto'::"text")))))
        ), "with_dues" AS (
         SELECT "l"."emprestimo_id",
            "l"."user_id",
            "l"."library_id",
            "l"."renewals_used",
            "l"."extended_once",
            "l"."open_items_count",
            "l"."first_book_id",
            "l"."first_holding_id",
            "l"."effective_due_at",
            "public"."fn_is_loan_blocked_by_dues"("l"."user_id", "l"."library_id") AS "dues_blocked",
            (EXISTS ( SELECT 1
                   FROM ("public"."reserva_linhas_v2" "rl"
                     JOIN "public"."reservas_v2" "r" ON (("r"."id" = "rl"."reserva_id")))
                  WHERE (("rl"."book_id" = "l"."first_book_id") AND ("r"."library_id" = "l"."library_id") AND ("r"."user_id" <> "l"."user_id") AND ("r"."status_global" = ANY (ARRAY['ativa'::"text", 'parcialmente_encerrada'::"text"])) AND ("rl"."item_status" = 'ativa'::"text") AND ("r"."archived_at" IS NULL)))) AS "reserved_by_other"
           FROM "my_open_loans" "l"
        ), "with_rule" AS (
         SELECT "w"."emprestimo_id",
            "w"."user_id",
            "w"."library_id",
            "w"."renewals_used",
            "w"."extended_once",
            "w"."open_items_count",
            "w"."first_book_id",
            "w"."first_holding_id",
            "w"."effective_due_at",
            "w"."dues_blocked",
            "w"."reserved_by_other",
            "rr"."renewable",
            "rr"."renewals_remaining",
            "rr"."renewal_days",
            "rr"."rule_label"
           FROM ("with_dues" "w"
             LEFT JOIN LATERAL "api"."get_remaining_renewals"("p_library_id" => "w"."library_id", "p_user_id" => "w"."user_id", "p_book_id" => "w"."first_book_id", "p_holding_id" => "w"."first_holding_id", "p_quantity" => "w"."open_items_count", "p_renewals_used" => COALESCE("w"."renewals_used", 0), "p_as_of_date" => CURRENT_DATE) "rr"("renewable", "renewals_remaining", "renewal_days", "policy_set_id", "rule_id", "rule_label", "explanation") ON (true))
        )
 SELECT "emprestimo_id",
    "library_id",
    "effective_due_at",
    "open_items_count",
    "renewals_used",
    COALESCE("renewable", false) AS "renewable",
    COALESCE("renewals_remaining", 0) AS "renewals_remaining",
    "rule_label",
        CASE
            WHEN "dues_blocked" THEN 'dues_blocked'::"text"
            WHEN (COALESCE("effective_due_at", CURRENT_DATE) < CURRENT_DATE) THEN 'overdue'::"text"
            WHEN "reserved_by_other" THEN 'reserved_by_other'::"text"
            WHEN ((COALESCE("renewable", false) IS FALSE) AND (COALESCE("renewals_remaining", 0) <= 0) AND (COALESCE("renewals_used", 0) > 0)) THEN 'quota_exceeded'::"text"
            WHEN (COALESCE("renewable", false) IS FALSE) THEN 'not_renewable'::"text"
            WHEN ((COALESCE("renewals_used", 0) >= 1) AND (COALESCE("renewals_remaining", 0) <= 0)) THEN 'already_extended'::"text"
            ELSE NULL::"text"
        END AS "blocking_reason",
    ((COALESCE("renewable", false) IS TRUE) AND (NOT "dues_blocked") AND (COALESCE("effective_due_at", CURRENT_DATE) >= CURRENT_DATE) AND (NOT "reserved_by_other") AND (COALESCE("renewals_remaining", 0) > 0)) AS "can_renew"
   FROM "with_rule";


