CREATE TABLE IF NOT EXISTS "public"."reserva_item_workflow_v2" (
    "id" bigint NOT NULL,
    "reserva_id" bigint NOT NULL,
    "line_no" integer NOT NULL,
    "workflow_stage" "text" DEFAULT 'solicitada'::"text" NOT NULL,
    "workflow_note" "text",
    "pickup_scheduled_for" timestamp with time zone,
    "pickup_reply_status" "text",
    "pickup_reply_note" "text",
    "pickup_reply_at" timestamp with time zone,
    "updated_at" timestamp with time zone DEFAULT "timezone"('utc'::"text", "now"()) NOT NULL,
    "updated_by" "uuid",
    "final_reason" "text",
    "pickup_proposed_by" "text",
    "negotiation_iteration_count" integer DEFAULT 0 NOT NULL,
    CONSTRAINT "chk_final_reason" CHECK ((("final_reason" IS NULL) OR ("final_reason" = ANY (ARRAY['no_show'::"text", 'cancelled_by_library'::"text"])))),
    CONSTRAINT "chk_negotiation_iteration_max" CHECK ((("negotiation_iteration_count" >= 0) AND ("negotiation_iteration_count" <= 3))),
    CONSTRAINT "chk_pickup_proposed_by" CHECK ((("pickup_proposed_by" = ANY (ARRAY['biblio'::"text", 'leitor'::"text"])) OR ("pickup_proposed_by" IS NULL))),
    CONSTRAINT "chk_pickup_scheduled_for_required" CHECK ((("workflow_stage" <> ALL (ARRAY['retirada_agendada'::"text", 're-retirada_agendada'::"text", 'retirada_a_combinar'::"text"])) OR ("pickup_scheduled_for" IS NOT NULL))),
    CONSTRAINT "reserva_item_workflow_v2_pickup_reply_chk" CHECK ((("pickup_reply_status" IS NULL) OR ("pickup_reply_status" = ANY (ARRAY['confirmado_leitor'::"text", 'recusado_leitor'::"text"])))),
    CONSTRAINT "reserva_item_workflow_v2_stage_chk" CHECK (("workflow_stage" = ANY (ARRAY['solicitada'::"text", 'em_preparacao'::"text", 'pronta_para_retirada'::"text", 'retirada_a_combinar'::"text", 'retirada_agendada'::"text", 're-retirada_agendada'::"text", 'nao_retirada'::"text", 'retirada_no_show'::"text", 'liberada_para_circulacao'::"text", 'retirada_efetivada'::"text", 'cancelada_leitor'::"text", 'cancelada_biblioteca'::"text", 'expirada'::"text"])))
);


ALTER TABLE "public"."reserva_item_workflow_v2" OWNER TO "postgres";


COMMENT ON TABLE "public"."reserva_item_workflow_v2" IS 'Workflow de traitement des items réservés. Anon SELECT révoqué le 2026-04-26 (palier 3).';



COMMENT ON COLUMN "public"."reserva_item_workflow_v2"."final_reason" IS 'Cause de la bascule automatique en liberada_para_circulacao. ''no_show'' = lecteur·rice n''est pas venu·e ; ''cancelled_by_library'' = annulation par biblio. NULL = libération non causale (historique pré-2026-05-07 ou cas futurs non liés).';



COMMENT ON COLUMN "public"."reserva_item_workflow_v2"."pickup_proposed_by" IS 'Qui a fait la dernière proposition de créneau de retrait. ''biblio'' = en attente de réponse du lecteur. ''leitor'' = en attente de réponse de la biblio. NULL = créneau confirmé ou pas de proposition en cours. Spec v2 négociation symétrique.';



COMMENT ON COLUMN "public"."reserva_item_workflow_v2"."negotiation_iteration_count" IS 'Nombre de contre-propositions échangées dans la négociation du créneau de retrait. Plafonné à 3 (validation politique CCLA). Au-delà, la spec recommande de poursuivre par téléphone/mail/de visu. Incrementé par trigger lors de chaque proposition (paquet 2).';



CREATE OR REPLACE VIEW "api"."reserva_itens_followup_ui" WITH ("security_invoker"='true') AS
 SELECT "r"."id" AS "reserva_id",
    "rl"."id" AS "reserva_item_id",
    "rl"."line_no",
    "rl"."sub_id",
    "r"."user_id",
    "r"."library_id",
    "l"."slug" AS "library_slug",
    "l"."name" AS "library_name",
    "r"."created_at" AS "reserva_created_at",
    "r"."updated_at" AS "reserva_updated_at",
    "r"."status_global" AS "reserva_status",
    "rl"."book_id",
    "rl"."item_id",
    "rl"."bib_ref",
    "rl"."rotulo_cache" AS "rotulo",
    COALESCE("rl"."autor_cache", "b"."autor") AS "autor",
    COALESCE("rl"."titulo_cache", "b"."titulo") AS "titulo",
    COALESCE("rl"."editora_cache", "b"."editora") AS "editora",
    COALESCE("rl"."ano_cache", "b"."ano") AS "ano",
    "rl"."item_status",
    "rl"."expires_at",
    "rl"."cancelled_at",
    "rl"."converted_at",
    "rl"."expired_at",
    "rl"."emprestimo_item_id",
    "rl"."notes" AS "item_notes",
    COALESCE("w"."workflow_stage",
        CASE
            WHEN ("rl"."item_status" = 'ativa'::"text") THEN 'solicitada'::"text"
            WHEN ("rl"."item_status" = 'cancelada_leitor'::"text") THEN 'cancelada_leitor'::"text"
            WHEN ("rl"."item_status" = 'cancelada_biblioteca'::"text") THEN 'cancelada_biblioteca'::"text"
            WHEN ("rl"."item_status" = 'expirada'::"text") THEN 'expirada'::"text"
            WHEN ("rl"."item_status" = 'convertida_em_emprestimo'::"text") THEN 'retirada_efetivada'::"text"
            WHEN ("rl"."item_status" = 'liberada_para_circulacao'::"text") THEN 'liberada_para_circulacao'::"text"
            ELSE 'solicitada'::"text"
        END) AS "workflow_stage_effective",
    "w"."workflow_note",
    "w"."pickup_scheduled_for",
    "w"."updated_at" AS "workflow_stage_updated_at_effective",
    "w"."pickup_reply_status",
    "w"."pickup_reply_note",
    "w"."pickup_reply_at",
    "w"."pickup_proposed_by",
    COALESCE("w"."negotiation_iteration_count", 0) AS "negotiation_iteration_count",
    "p"."public_id" AS "user_public_id",
    "p"."email" AS "user_email",
    NULLIF(TRIM(BOTH FROM "concat_ws"(' '::"text", "p"."first_name", "p"."last_name")), ''::"text") AS "user_name",
    "rl"."is_hidden_by_user"
   FROM ((((("public"."reservas_v2" "r"
     JOIN "public"."reserva_linhas_v2" "rl" ON (("rl"."reserva_id" = "r"."id")))
     JOIN "public"."libraries" "l" ON (("l"."id" = "r"."library_id")))
     LEFT JOIN "public"."books" "b" ON (("b"."id" = "rl"."book_id")))
     LEFT JOIN "public"."reserva_item_workflow_v2" "w" ON ((("w"."reserva_id" = "rl"."reserva_id") AND ("w"."line_no" = "rl"."line_no"))))
     LEFT JOIN "public"."profiles" "p" ON (("p"."id" = "r"."user_id")))
  WHERE ("r"."archived_at" IS NULL);


ALTER VIEW "api"."reserva_itens_followup_ui" OWNER TO "postgres";


COMMENT ON VIEW "api"."reserva_itens_followup_ui" IS 'Vue de suivi des items de réservation pour le painel staff. Paquet 5e
   (2026-05-09) : ajout user_public_id/user_email/user_name via LEFT JOIN
   profiles pour identifier le·la lecteur·rice côté painel sans tomber
   sur un fragment d''UUID brut.';



CREATE OR REPLACE VIEW "api"."my_reservations_active_v2" WITH ("security_invoker"='true') AS
 WITH "me" AS (
         SELECT "mp"."id",
            "mp"."is_authenticated",
            "mp"."default_library_id"
           FROM "api"."my_profile" "mp"
        )
 SELECT "r"."reserva_id" AS "id",
    "r"."reserva_id",
    "r"."reserva_item_id",
    "r"."line_no",
    "r"."sub_id",
    "r"."user_id",
    "r"."book_id",
    "r"."item_id",
    "r"."library_id",
    "r"."library_slug",
    "r"."library_name",
    ("r"."library_id" = "m"."default_library_id") AS "is_default_library",
    "r"."bib_ref",
    "r"."titulo",
    "r"."autor",
    "r"."ano",
    "r"."editora",
    NULL::"text" AS "cover_object_path",
    "r"."item_status" AS "status",
    "r"."item_notes" AS "notes",
    "r"."reserva_created_at" AS "reserved_at",
    "r"."reserva_created_at" AS "created_at",
    "r"."reserva_updated_at" AS "updated_at",
    "r"."cancelled_at",
    "r"."converted_at" AS "fulfilled_at",
    "r"."expired_at",
    "r"."reserva_status",
    "r"."workflow_stage_effective",
    "r"."workflow_note",
    "r"."pickup_scheduled_for",
    "r"."workflow_stage_updated_at_effective",
    "r"."pickup_reply_status",
    "r"."pickup_reply_note",
    "r"."pickup_reply_at",
    "r"."emprestimo_item_id",
    "r"."rotulo",
    "r"."pickup_proposed_by",
    COALESCE("r"."negotiation_iteration_count", 0) AS "negotiation_iteration_count"
   FROM ("me" "m"
     JOIN "api"."reserva_itens_followup_ui" "r" ON (("r"."user_id" = "m"."id")))
  WHERE (("m"."is_authenticated" = true) AND ("r"."item_status" = 'ativa'::"text"))
  ORDER BY "r"."reserva_created_at" DESC, "r"."reserva_id" DESC, "r"."line_no";


