CREATE TABLE IF NOT EXISTS "ingest"."partner_catalog_import_runs" (
    "id" bigint NOT NULL,
    "source_id" bigint NOT NULL,
    "requested_by" "uuid",
    "bucket_id" "text" DEFAULT 'catalogos_parceiros_raw'::"text" NOT NULL,
    "storage_path" "text" NOT NULL,
    "original_filename" "text" NOT NULL,
    "mime_type" "text",
    "size_bytes" bigint,
    "sha256" "text",
    "detected_format" "text",
    "run_status" "text" DEFAULT 'uploaded'::"text" NOT NULL,
    "parser_version" "text" DEFAULT 'v1'::"text" NOT NULL,
    "imported_rows" integer DEFAULT 0 NOT NULL,
    "selected_rows" integer DEFAULT 0 NOT NULL,
    "created_drafts" integer DEFAULT 0 NOT NULL,
    "summary" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "error_log" "jsonb" DEFAULT '[]'::"jsonb" NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "started_at" timestamp with time zone,
    "finished_at" timestamp with time zone,
    "library_id" "uuid",
    CONSTRAINT "partner_catalog_import_runs_detected_format_check" CHECK (("detected_format" = ANY (ARRAY['csv'::"text", 'tsv'::"text", 'xlsx'::"text", 'xls'::"text", 'ods'::"text", 'json'::"text", 'csl_json'::"text", 'ris'::"text", 'bibtex'::"text", 'biblatex'::"text", 'mods'::"text", 'marcxml'::"text", 'xml'::"text", 'pdf'::"text", 'zip'::"text", 'unknown'::"text"]))),
    CONSTRAINT "partner_catalog_import_runs_run_status_check" CHECK (("run_status" = ANY (ARRAY['uploaded'::"text", 'queued'::"text", 'processing'::"text", 'parsed'::"text", 'matching'::"text", 'ready_for_review'::"text", 'partially_failed'::"text", 'failed'::"text", 'drafts_created'::"text"])))
);


ALTER TABLE "ingest"."partner_catalog_import_runs" OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "ingest"."partner_catalog_sources" (
    "id" bigint NOT NULL,
    "partner_name" "text" NOT NULL,
    "library_id" "uuid",
    "relation_status" "text" NOT NULL,
    "source_kind" "text" DEFAULT 'manual_upload'::"text" NOT NULL,
    "import_enabled" boolean DEFAULT false NOT NULL,
    "zotero_library_scope" "text",
    "zotero_library_key" "text",
    "zotero_api_key_secret_name" "text",
    "notes" "text",
    "meta" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "oai_endpoint_url" "text",
    "oai_metadata_prefix" "text" DEFAULT 'marcxml'::"text",
    "oai_set" "text",
    "catalog_partner_id" bigint,
    CONSTRAINT "partner_catalog_sources_relation_status_check" CHECK (("relation_status" = ANY (ARRAY['mapeada'::"text", 'contatada'::"text", 'em_discussao'::"text", 'acordo_parcial'::"text", 'acordo_tecnico'::"text", 'importacao_autorizada'::"text", 'mutualizacao_autorizada'::"text"]))),
    CONSTRAINT "partner_catalog_sources_source_kind_check" CHECK (("source_kind" = ANY (ARRAY['manual_upload'::"text", 'zotero_file_export'::"text", 'zotero_api'::"text", 'partner_deposit'::"text"]))),
    CONSTRAINT "partner_catalog_sources_zotero_library_scope_check" CHECK (("zotero_library_scope" = ANY (ARRAY['user'::"text", 'group'::"text"])))
);


ALTER TABLE "ingest"."partner_catalog_sources" OWNER TO "postgres";


COMMENT ON COLUMN "ingest"."partner_catalog_sources"."oai_endpoint_url" IS 'URL de l''endpoint OAI-PMH (ex: https://example.org/oai). Null si la source n''est pas OAI.';



COMMENT ON COLUMN "ingest"."partner_catalog_sources"."oai_metadata_prefix" IS 'Préfixe de métadonnées OAI (marcxml, oai_dc). Fallback auto-négocié par l''EF.';



COMMENT ON COLUMN "ingest"."partner_catalog_sources"."oai_set" IS 'Set OAI optionnel pour filtrer le moissonnage.';



COMMENT ON COLUMN "ingest"."partner_catalog_sources"."catalog_partner_id" IS 'Entité partenaire (public.catalog_partners) dont cette source de dépôt provient. NULL pour les sources legacy créées en texte libre.';



CREATE TABLE IF NOT EXISTS "ingest"."partner_catalog_staging_rows" (
    "id" bigint NOT NULL,
    "run_id" bigint NOT NULL,
    "source_file_id" bigint,
    "row_no" integer NOT NULL,
    "external_key" "text",
    "item_type" "text",
    "title" "text",
    "subtitle" "text",
    "responsibility_statement" "text",
    "authors" "jsonb" DEFAULT '[]'::"jsonb" NOT NULL,
    "publisher" "text",
    "place_of_publication" "text",
    "publication_year" "text",
    "edition_statement" "text",
    "language" "text",
    "isbn" "text",
    "issn" "text",
    "subjects" "jsonb" DEFAULT '[]'::"jsonb" NOT NULL,
    "raw_payload" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "normalized_payload" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "parse_status" "text" DEFAULT 'parsed'::"text" NOT NULL,
    "match_status" "text" DEFAULT 'unreviewed'::"text" NOT NULL,
    "review_status" "text" DEFAULT 'pending'::"text" NOT NULL,
    "confidence" numeric(5,2) DEFAULT 0 NOT NULL,
    "warnings" "jsonb" DEFAULT '[]'::"jsonb" NOT NULL,
    "proposed_book_id" bigint,
    "proposed_book_draft_id" bigint,
    "created_book_draft_id" bigint,
    "selected_for_draft" boolean DEFAULT false NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "editorial_decision" "text" DEFAULT 'pending'::"text" NOT NULL,
    "editorial_note" "text",
    "editorial_decided_at" timestamp with time zone,
    "editorial_decided_by" "uuid",
    CONSTRAINT "partner_catalog_staging_rows_editorial_decision_check" CHECK (("editorial_decision" = ANY (ARRAY['pending'::"text", 'accept_new'::"text", 'accept_duplicate'::"text", 'reject'::"text"]))),
    CONSTRAINT "partner_catalog_staging_rows_match_status_check" CHECK (("match_status" = ANY (ARRAY['unreviewed'::"text", 'new_record'::"text", 'possible_duplicate'::"text", 'matched_book'::"text", 'matched_draft'::"text", 'manual_decision'::"text"]))),
    CONSTRAINT "partner_catalog_staging_rows_parse_status_check" CHECK (("parse_status" = ANY (ARRAY['parsed'::"text", 'warning'::"text", 'error'::"text"]))),
    CONSTRAINT "partner_catalog_staging_rows_review_status_check" CHECK (("review_status" = ANY (ARRAY['pending'::"text", 'approved'::"text", 'rejected'::"text", 'draft_created'::"text"])))
);


ALTER TABLE "ingest"."partner_catalog_staging_rows" OWNER TO "postgres";


CREATE OR REPLACE VIEW "api"."partner_catalog_import_rows_ui" WITH ("security_invoker"='true') AS
 SELECT "sr"."id" AS "staging_row_id",
    "sr"."id" AS "row_id",
    "sr"."run_id" AS "import_run_id",
    "sr"."run_id",
    "r"."source_id",
    COALESCE(NULLIF("btrim"("l"."name"), ''::"text"), NULLIF("btrim"("s"."partner_name"), ''::"text"), "format"('Fonte #%s'::"text", "r"."source_id")) AS "source_display_name",
    COALESCE(NULLIF("btrim"("l"."name"), ''::"text"), NULLIF("btrim"("s"."partner_name"), ''::"text"), "format"('Fonte #%s'::"text", "r"."source_id")) AS "source_name",
    "s"."partner_name",
    "s"."library_id",
    "l"."name" AS "library_name",
    "l"."slug" AS "library_slug",
    "r"."original_filename",
    "r"."detected_format",
    "r"."run_status",
    "sr"."row_no",
    "sr"."row_no" AS "row_number",
    "sr"."external_key",
    "sr"."item_type",
    "sr"."title",
    "sr"."subtitle",
    "sr"."responsibility_statement",
    "sr"."publisher",
    "sr"."place_of_publication",
    "sr"."publication_year",
    "sr"."edition_statement",
    "sr"."language",
    "sr"."isbn",
    "sr"."issn",
    "sr"."parse_status",
    "sr"."match_status",
    "sr"."review_status",
    "sr"."confidence",
    "sr"."selected_for_draft",
    "sr"."proposed_book_id",
    "sr"."proposed_book_draft_id",
    "sr"."created_book_draft_id",
    "sr"."warnings",
    "sr"."authors",
    "sr"."subjects",
    "sr"."created_at",
    "ingest"."fn_partner_catalog_extract_collection_hint"("sr"."normalized_payload", "sr"."raw_payload") AS "collection_hint",
    "ingest"."fn_partner_catalog_extract_local_classification_hint"("sr"."normalized_payload", "sr"."raw_payload") AS "local_classification_hint"
   FROM ((("ingest"."partner_catalog_staging_rows" "sr"
     JOIN "ingest"."partner_catalog_import_runs" "r" ON (("r"."id" = "sr"."run_id")))
     JOIN "ingest"."partner_catalog_sources" "s" ON (("s"."id" = "r"."source_id")))
     LEFT JOIN "public"."libraries" "l" ON (("l"."id" = "s"."library_id")));


ALTER VIEW "api"."partner_catalog_import_rows_ui" OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "ingest"."partner_catalog_match_candidates" (
    "id" bigint NOT NULL,
    "staging_row_id" bigint NOT NULL,
    "candidate_type" "text" NOT NULL,
    "candidate_id" bigint NOT NULL,
    "match_method" "text" NOT NULL,
    "match_score" numeric(5,2) NOT NULL,
    "details" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "partner_catalog_match_candidates_candidate_type_check" CHECK (("candidate_type" = ANY (ARRAY['book'::"text", 'book_draft'::"text", 'author'::"text"]))),
    CONSTRAINT "partner_catalog_match_candidates_match_method_check" CHECK (("match_method" = ANY (ARRAY['isbn_exact'::"text", 'issn_exact'::"text", 'title_author_year'::"text", 'title_author'::"text", 'manual'::"text"])))
);


ALTER TABLE "ingest"."partner_catalog_match_candidates" OWNER TO "postgres";


CREATE OR REPLACE VIEW "api"."partner_catalog_import_rows_match_ui" WITH ("security_invoker"='true') AS
 SELECT "ui"."staging_row_id",
    "ui"."row_id",
    "ui"."import_run_id",
    "ui"."run_id",
    "ui"."source_id",
    "ui"."source_display_name",
    "ui"."source_name",
    "ui"."partner_name",
    "ui"."library_id",
    "ui"."library_name",
    "ui"."library_slug",
    "ui"."original_filename",
    "ui"."detected_format",
    "ui"."run_status",
    "ui"."row_no",
    "ui"."row_number",
    "ui"."external_key",
    "ui"."item_type",
    "ui"."title",
    "ui"."subtitle",
    "ui"."responsibility_statement",
    "ui"."publisher",
    "ui"."place_of_publication",
    "ui"."publication_year",
    "ui"."edition_statement",
    "ui"."language",
    "ui"."isbn",
    "ui"."issn",
    "ui"."parse_status",
    "ui"."match_status",
    "ui"."review_status",
    "ui"."confidence",
    "ui"."selected_for_draft",
    "ui"."proposed_book_id",
    "ui"."proposed_book_draft_id",
    "ui"."created_book_draft_id",
    "ui"."warnings",
    "ui"."authors",
    "ui"."subjects",
    "ui"."created_at",
    "best"."candidate_type" AS "top_candidate_type",
    "best"."candidate_id" AS "top_candidate_id",
    "best"."match_method" AS "top_match_method",
    "best"."match_score" AS "top_match_score",
    "best"."details" AS "top_match_details",
    "ui"."collection_hint",
    "ui"."local_classification_hint"
   FROM ("api"."partner_catalog_import_rows_ui" "ui"
     LEFT JOIN LATERAL ( SELECT "mc"."candidate_type",
            "mc"."candidate_id",
            "mc"."match_method",
            "mc"."match_score",
            "mc"."details"
           FROM "ingest"."partner_catalog_match_candidates" "mc"
          WHERE ("mc"."staging_row_id" = "ui"."staging_row_id")
          ORDER BY "mc"."match_score" DESC,
                CASE "mc"."candidate_type"
                    WHEN 'book'::"text" THEN 0
                    WHEN 'book_draft'::"text" THEN 1
                    ELSE 9
                END, "mc"."id"
         LIMIT 1) "best" ON (true));


ALTER VIEW "api"."partner_catalog_import_rows_match_ui" OWNER TO "postgres";


CREATE OR REPLACE VIEW "api"."partner_catalog_import_rows_workflow_ui" WITH ("security_invoker"='true') AS
 SELECT "staging_row_id",
    "row_id",
    "import_run_id",
    "run_id",
    "source_id",
    "source_display_name",
    "source_name",
    "partner_name",
    "library_id",
    "library_name",
    "library_slug",
    "original_filename",
    "detected_format",
    "run_status",
    "row_no",
    "row_number",
    "external_key",
    "item_type",
    "title",
    "subtitle",
    "responsibility_statement",
    "publisher",
    "place_of_publication",
    "publication_year",
    "edition_statement",
    "language",
    "isbn",
    "issn",
    "parse_status",
    "match_status",
    "review_status",
    "confidence",
    "selected_for_draft",
    "proposed_book_id",
    "proposed_book_draft_id",
    "created_book_draft_id",
    "warnings",
    "authors",
    "subjects",
    "created_at",
    "editorial_decision",
    "editorial_note",
    "editorial_decided_at",
    "editorial_decided_by",
    "top_candidate_type",
    "top_candidate_id",
    "top_match_method",
    "top_match_score",
    "top_match_details",
        CASE
            WHEN ("match_status" = 'matched_book'::"text") THEN 'já publicado'::"text"
            WHEN ("match_status" = 'matched_draft'::"text") THEN 'rascunho existente'::"text"
            WHEN ("match_status" = 'possible_duplicate'::"text") THEN 'possível duplicado'::"text"
            WHEN ("match_status" = 'new_record'::"text") THEN 'novo'::"text"
            WHEN ("match_status" = 'manual_decision'::"text") THEN 'decisão manual'::"text"
            ELSE 'sem classificação'::"text"
        END AS "status_label",
        CASE
            WHEN ("top_candidate_type" = 'book'::"text") THEN 'book'::"text"
            WHEN ("top_candidate_type" = 'book_draft'::"text") THEN 'book_draft'::"text"
            ELSE NULL::"text"
        END AS "existing_target_kind",
    "top_candidate_id" AS "existing_target_id",
        CASE
            WHEN (("match_status" = ANY (ARRAY['matched_book'::"text", 'matched_draft'::"text", 'possible_duplicate'::"text", 'manual_decision'::"text"])) AND ("editorial_decision" = 'pending'::"text")) THEN true
            ELSE false
        END AS "needs_manual_review",
        CASE
            WHEN ("created_book_draft_id" IS NOT NULL) THEN false
            WHEN ("editorial_decision" = 'reject'::"text") THEN false
            WHEN (("match_status" = 'new_record'::"text") AND ("editorial_decision" = 'accept_new'::"text")) THEN true
            WHEN (("match_status" = ANY (ARRAY['matched_book'::"text", 'matched_draft'::"text", 'possible_duplicate'::"text", 'manual_decision'::"text"])) AND ("editorial_decision" = 'accept_duplicate'::"text")) THEN true
            ELSE false
        END AS "can_create_draft",
    "collection_hint",
    "local_classification_hint"
   FROM ( SELECT "ui"."staging_row_id",
            "ui"."row_id",
            "ui"."import_run_id",
            "ui"."run_id",
            "ui"."source_id",
            "ui"."source_display_name",
            "ui"."source_name",
            "ui"."partner_name",
            "ui"."library_id",
            "ui"."library_name",
            "ui"."library_slug",
            "ui"."original_filename",
            "ui"."detected_format",
            "ui"."run_status",
            "ui"."row_no",
            "ui"."row_number",
            "ui"."external_key",
            "ui"."item_type",
            "ui"."title",
            "ui"."subtitle",
            "ui"."responsibility_statement",
            "ui"."publisher",
            "ui"."place_of_publication",
            "ui"."publication_year",
            "ui"."edition_statement",
            "ui"."language",
            "ui"."isbn",
            "ui"."issn",
            "ui"."parse_status",
            "ui"."match_status",
            "ui"."review_status",
            "ui"."confidence",
            "ui"."selected_for_draft",
            "ui"."proposed_book_id",
            "ui"."proposed_book_draft_id",
            "ui"."created_book_draft_id",
            "ui"."warnings",
            "ui"."authors",
            "ui"."subjects",
            "ui"."created_at",
            "sr"."editorial_decision",
            "sr"."editorial_note",
            "sr"."editorial_decided_at",
            "sr"."editorial_decided_by",
            "best"."candidate_type" AS "top_candidate_type",
            "best"."candidate_id" AS "top_candidate_id",
            "best"."match_method" AS "top_match_method",
            "best"."match_score" AS "top_match_score",
            "best"."details" AS "top_match_details",
            "ui"."collection_hint",
            "ui"."local_classification_hint"
           FROM (("api"."partner_catalog_import_rows_ui" "ui"
             JOIN "ingest"."partner_catalog_staging_rows" "sr" ON (("sr"."id" = "ui"."staging_row_id")))
             LEFT JOIN LATERAL ( SELECT "mc"."candidate_type",
                    "mc"."candidate_id",
                    "mc"."match_method",
                    "mc"."match_score",
                    "mc"."details"
                   FROM "ingest"."partner_catalog_match_candidates" "mc"
                  WHERE ("mc"."staging_row_id" = "ui"."staging_row_id")
                  ORDER BY "mc"."match_score" DESC,
                        CASE "mc"."candidate_type"
                            WHEN 'book'::"text" THEN 0
                            WHEN 'book_draft'::"text" THEN 1
                            ELSE 9
                        END, "mc"."id"
                 LIMIT 1) "best" ON (true))) "m";


ALTER VIEW "api"."partner_catalog_import_rows_workflow_ui" OWNER TO "postgres";


CREATE OR REPLACE VIEW "api"."partner_catalog_import_run_bulk_summary_ui" WITH ("security_invoker"='true') AS
 SELECT "r"."id" AS "import_run_id",
    "r"."id" AS "run_id",
    "r"."source_id",
    COALESCE(NULLIF("btrim"("l"."name"), ''::"text"), NULLIF("btrim"("s"."partner_name"), ''::"text"), "format"('Fonte #%s'::"text", "r"."source_id")) AS "source_display_name",
    COALESCE(NULLIF("btrim"("l"."name"), ''::"text"), NULLIF("btrim"("s"."partner_name"), ''::"text"), "format"('Fonte #%s'::"text", "r"."source_id")) AS "source_name",
    "s"."partner_name",
    "s"."library_id",
    "l"."name" AS "library_name",
    "l"."slug" AS "library_slug",
    "r"."original_filename",
    "r"."detected_format",
    "r"."run_status",
    "r"."imported_rows",
    "r"."selected_rows",
    "r"."created_drafts",
    "r"."created_at" AS "requested_at",
    "r"."created_at",
    "r"."started_at",
    "r"."finished_at",
    ("count"("sr"."id"))::integer AS "row_count",
    ("count"(*) FILTER (WHERE ("sr"."review_status" = 'pending'::"text")))::integer AS "pending_count",
    ("count"(*) FILTER (WHERE ("sr"."review_status" = 'approved'::"text")))::integer AS "approved_count",
    ("count"(*) FILTER (WHERE ("sr"."review_status" = 'rejected'::"text")))::integer AS "rejected_count",
    ("count"(*) FILTER (WHERE ("sr"."review_status" = 'draft_created'::"text")))::integer AS "draft_created_count",
    ("count"(*) FILTER (WHERE ("sr"."editorial_decision" = 'pending'::"text")))::integer AS "editorial_pending_count",
    ("count"(*) FILTER (WHERE ("sr"."editorial_decision" = 'accept_new'::"text")))::integer AS "editorial_accept_new_count",
    ("count"(*) FILTER (WHERE ("sr"."editorial_decision" = 'accept_duplicate'::"text")))::integer AS "editorial_accept_duplicate_count",
    ("count"(*) FILTER (WHERE ("sr"."editorial_decision" = 'reject'::"text")))::integer AS "editorial_reject_count",
    ("count"(*) FILTER (WHERE ("sr"."created_book_draft_id" IS NULL)))::integer AS "unconverted_count",
    ("count"(*) FILTER (WHERE ("sr"."created_book_draft_id" IS NOT NULL)))::integer AS "converted_count",
    ("count"(*) FILTER (WHERE (("sr"."created_book_draft_id" IS NULL) AND "ingest"."fn_is_editorial_decision_compatible"("sr"."match_status", 'accept_new'::"text"))))::integer AS "compatible_accept_new_count",
    ("count"(*) FILTER (WHERE (("sr"."created_book_draft_id" IS NULL) AND "ingest"."fn_is_editorial_decision_compatible"("sr"."match_status", 'accept_duplicate'::"text"))))::integer AS "compatible_accept_duplicate_count",
    ("count"(*) FILTER (WHERE ("ingest"."fn_partner_catalog_extract_collection_hint"("sr"."normalized_payload", "sr"."raw_payload") IS NOT NULL)))::integer AS "collection_hint_count",
    ("count"(*) FILTER (WHERE ("ingest"."fn_partner_catalog_extract_local_classification_hint"("sr"."normalized_payload", "sr"."raw_payload") IS NOT NULL)))::integer AS "local_classification_hint_count"
   FROM ((("ingest"."partner_catalog_import_runs" "r"
     JOIN "ingest"."partner_catalog_sources" "s" ON (("s"."id" = "r"."source_id")))
     LEFT JOIN "public"."libraries" "l" ON (("l"."id" = "s"."library_id")))
     LEFT JOIN "ingest"."partner_catalog_staging_rows" "sr" ON (("sr"."run_id" = "r"."id")))
  GROUP BY "r"."id", "r"."source_id", "s"."partner_name", "s"."library_id", "l"."name", "l"."slug", "r"."original_filename", "r"."detected_format", "r"."run_status", "r"."imported_rows", "r"."selected_rows", "r"."created_drafts", "r"."created_at", "r"."started_at", "r"."finished_at";


ALTER VIEW "api"."partner_catalog_import_run_bulk_summary_ui" OWNER TO "postgres";


CREATE OR REPLACE VIEW "api"."partner_catalog_import_runs_ui" WITH ("security_invoker"='true') AS
 SELECT "r"."id" AS "import_run_id",
    "r"."id" AS "run_id",
    "r"."source_id",
    COALESCE(NULLIF("btrim"("l"."name"), ''::"text"), NULLIF("btrim"("s"."partner_name"), ''::"text"), "format"('Fonte #%s'::"text", "r"."source_id")) AS "source_display_name",
    COALESCE(NULLIF("btrim"("l"."name"), ''::"text"), NULLIF("btrim"("s"."partner_name"), ''::"text"), "format"('Fonte #%s'::"text", "r"."source_id")) AS "source_name",
    "s"."partner_name",
    "s"."library_id",
    "l"."name" AS "library_name",
    "l"."slug" AS "library_slug",
    "s"."relation_status",
    "s"."source_kind",
    "s"."import_enabled",
    "r"."bucket_id",
    "r"."storage_path",
    "r"."original_filename",
    "r"."mime_type",
    "r"."size_bytes",
    "r"."sha256",
    "r"."detected_format",
    "r"."run_status",
    "r"."run_status" AS "status",
    "r"."parser_version",
    "r"."imported_rows",
    "r"."selected_rows",
    "r"."created_drafts",
    "r"."imported_rows" AS "row_count",
    "r"."summary",
    "r"."error_log",
    "r"."requested_by",
    "r"."created_at" AS "requested_at",
    "r"."created_at",
    "r"."started_at",
    "r"."finished_at",
    (COALESCE("hints"."rows_with_collection_hint", (0)::bigint))::integer AS "rows_with_collection_hint",
    (COALESCE("hints"."rows_with_local_classification_hint", (0)::bigint))::integer AS "rows_with_local_classification_hint",
    "hints"."sample_collection_hint",
    "hints"."sample_local_classification_hint"
   FROM ((("ingest"."partner_catalog_import_runs" "r"
     JOIN "ingest"."partner_catalog_sources" "s" ON (("s"."id" = "r"."source_id")))
     LEFT JOIN "public"."libraries" "l" ON (("l"."id" = "s"."library_id")))
     LEFT JOIN LATERAL ( SELECT "count"(*) FILTER (WHERE ("ingest"."fn_partner_catalog_extract_collection_hint"("sr"."normalized_payload", "sr"."raw_payload") IS NOT NULL)) AS "rows_with_collection_hint",
            "count"(*) FILTER (WHERE ("ingest"."fn_partner_catalog_extract_local_classification_hint"("sr"."normalized_payload", "sr"."raw_payload") IS NOT NULL)) AS "rows_with_local_classification_hint",
            "min"("ingest"."fn_partner_catalog_extract_collection_hint"("sr"."normalized_payload", "sr"."raw_payload")) FILTER (WHERE ("ingest"."fn_partner_catalog_extract_collection_hint"("sr"."normalized_payload", "sr"."raw_payload") IS NOT NULL)) AS "sample_collection_hint",
            "min"("ingest"."fn_partner_catalog_extract_local_classification_hint"("sr"."normalized_payload", "sr"."raw_payload")) FILTER (WHERE ("ingest"."fn_partner_catalog_extract_local_classification_hint"("sr"."normalized_payload", "sr"."raw_payload") IS NOT NULL)) AS "sample_local_classification_hint"
           FROM "ingest"."partner_catalog_staging_rows" "sr"
          WHERE ("sr"."run_id" = "r"."id")) "hints" ON (true));


ALTER VIEW "api"."partner_catalog_import_runs_ui" OWNER TO "postgres";


CREATE OR REPLACE VIEW "api"."partner_catalog_import_run_policy_ui" WITH ("security_invoker"='true') AS
 SELECT "import_run_id",
    "source_id",
    "partner_name",
    "library_id",
    "relation_status",
    "source_kind",
    "import_enabled",
    "detected_format",
    "run_status",
    "imported_rows",
    "selected_rows",
    "created_drafts",
    "created_at",
    "started_at",
    "finished_at",
        CASE
            WHEN ("run_status" = ANY (ARRAY['uploaded'::"text", 'queued'::"text"])) THEN 'dispatch_pending'::"text"
            WHEN ("run_status" = ANY (ARRAY['processing'::"text", 'parsed'::"text", 'matching'::"text"])) THEN 'processing'::"text"
            WHEN ("run_status" = 'ready_for_review'::"text") THEN 'review_ready'::"text"
            WHEN ("run_status" = 'drafts_created'::"text") THEN 'drafts_done'::"text"
            WHEN ("run_status" = 'partially_failed'::"text") THEN 'attention_required'::"text"
            WHEN ("run_status" = 'failed'::"text") THEN 'failed'::"text"
            ELSE 'unknown'::"text"
        END AS "policy_stage",
        CASE
            WHEN ("run_status" = ANY (ARRAY['uploaded'::"text", 'queued'::"text"])) THEN 'à lancer ou relancer explicitement'::"text"
            WHEN ("run_status" = ANY (ARRAY['processing'::"text", 'parsed'::"text", 'matching'::"text"])) THEN 'traitement en cours'::"text"
            WHEN ("run_status" = 'ready_for_review'::"text") THEN 'révision éditoriale possible'::"text"
            WHEN ("run_status" = 'drafts_created'::"text") THEN 'rascunhos déjà créés'::"text"
            WHEN ("run_status" = 'partially_failed'::"text") THEN 'vérification humaine requise'::"text"
            WHEN ("run_status" = 'failed'::"text") THEN 'échec à relancer / diagnostiquer'::"text"
            ELSE 'état non classé'::"text"
        END AS "policy_stage_label",
    ("run_status" = ANY (ARRAY['uploaded'::"text", 'queued'::"text", 'failed'::"text", 'partially_failed'::"text"])) AS "can_dispatch",
    ("run_status" = ANY (ARRAY['parsed'::"text", 'matching'::"text", 'ready_for_review'::"text", 'drafts_created'::"text", 'failed'::"text", 'partially_failed'::"text"])) AS "can_force_reparse",
    ("run_status" = ANY (ARRAY['ready_for_review'::"text", 'drafts_created'::"text", 'partially_failed'::"text"])) AS "can_open_review",
    (("run_status" = ANY (ARRAY['ready_for_review'::"text", 'partially_failed'::"text"])) AND (COALESCE("imported_rows", 0) > 0)) AS "can_create_drafts",
    ("run_status" = ANY (ARRAY['failed'::"text", 'drafts_created'::"text"])) AS "is_terminal_like",
    ("run_status" = ANY (ARRAY['failed'::"text", 'partially_failed'::"text"])) AS "needs_manual_attention",
    false AS "introduces_new_persistent_status",
    false AS "auto_dispatch_after_create",
        CASE
            WHEN ("run_status" = ANY (ARRAY['uploaded'::"text", 'queued'::"text"])) THEN 'dispatch_run'::"text"
            WHEN ("run_status" = ANY (ARRAY['processing'::"text", 'parsed'::"text", 'matching'::"text"])) THEN 'wait_or_refresh'::"text"
            WHEN ("run_status" = 'ready_for_review'::"text") THEN 'review_then_create_drafts'::"text"
            WHEN ("run_status" = 'partially_failed'::"text") THEN 'inspect_then_reparse_or_review'::"text"
            WHEN ("run_status" = 'failed'::"text") THEN 'diagnose_then_dispatch_or_reparse'::"text"
            WHEN ("run_status" = 'drafts_created'::"text") THEN 'open_queue_or_batches'::"text"
            ELSE 'inspect'::"text"
        END AS "suggested_next_action",
        CASE
            WHEN ("run_status" = ANY (ARRAY['uploaded'::"text", 'queued'::"text"])) THEN 'S4 maintient un flux en deux temps : création du run puis dispatch explicite.'::"text"
            WHEN ("run_status" = ANY (ARRAY['processing'::"text", 'parsed'::"text", 'matching'::"text"])) THEN 'Aucun statut métier supplémentaire n''est ajouté : cet état reste purement opératoire.'::"text"
            WHEN ("run_status" = 'ready_for_review'::"text") THEN 'Le run est suffisamment mûr pour la revue front sans ajouter un niveau métier persistant.'::"text"
            WHEN ("run_status" = 'partially_failed'::"text") THEN 'Le run demande une lecture humaine, mais sans créer un nouveau statut persistant dédié.'::"text"
            WHEN ("run_status" = 'failed'::"text") THEN 'Échec terminal de traitement ; la reprise reste explicite et manuelle.'::"text"
            WHEN ("run_status" = 'drafts_created'::"text") THEN 'Après création des rascunhos, on ouvre les flux normaux du catalogue sans automatisme supplémentaire.'::"text"
            ELSE 'Décision S4 conservatrice : pas d''extension métier automatique à ce stade.'::"text"
        END AS "policy_note"
   FROM "api"."partner_catalog_import_runs_ui" "r";


ALTER VIEW "api"."partner_catalog_import_run_policy_ui" OWNER TO "postgres";


COMMENT ON VIEW "api"."partner_catalog_import_run_policy_ui" IS 'Derived policy flags for partner import runs. S4 decision: no new persistent métier status and no automatic dispatch after run creation.';



CREATE OR REPLACE VIEW "api"."partner_catalog_sources_ui" WITH ("security_invoker"='true') AS
 SELECT "s"."id",
    "s"."id" AS "source_id",
    "s"."partner_name",
    "s"."library_id",
    "l"."slug" AS "library_slug",
    "l"."name" AS "library_name",
    "l"."short_name" AS "library_short_name",
    COALESCE(NULLIF("btrim"("l"."name"), ''::"text"), NULLIF("btrim"("s"."partner_name"), ''::"text"), "format"('Fonte #%s'::"text", "s"."id")) AS "display_name",
    COALESCE(NULLIF("btrim"("l"."name"), ''::"text"), NULLIF("btrim"("s"."partner_name"), ''::"text"), "format"('Fonte #%s'::"text", "s"."id")) AS "source_display_name",
    COALESCE(NULLIF("btrim"("l"."name"), ''::"text"), NULLIF("btrim"("s"."partner_name"), ''::"text"), "format"('Fonte #%s'::"text", "s"."id")) AS "source_label",
    COALESCE(NULLIF("btrim"("l"."name"), ''::"text"), NULLIF("btrim"("s"."partner_name"), ''::"text"), "format"('Fonte #%s'::"text", "s"."id")) AS "source_name",
    COALESCE(NULLIF("btrim"("l"."short_name"), ''::"text"), NULLIF("btrim"(("s"."meta" ->> 'short_name'::"text")), ''::"text"), NULLIF("btrim"(("s"."meta" ->> 'acronym'::"text")), ''::"text")) AS "short_name",
    COALESCE(NULLIF("btrim"(("s"."meta" ->> 'acronym'::"text")), ''::"text"), NULLIF("btrim"("l"."short_name"), ''::"text")) AS "acronym",
    COALESCE(NULLIF("btrim"("l"."slug"), ''::"text"), NULLIF("btrim"(("s"."meta" ->> 'slug'::"text")), ''::"text")) AS "slug",
    COALESCE(NULLIF("btrim"("l"."slug"), ''::"text"), NULLIF("btrim"(("s"."meta" ->> 'slug'::"text")), ''::"text")) AS "source_slug",
    COALESCE(NULLIF("btrim"(("s"."meta" ->> 'territory'::"text")), ''::"text"), NULLIF("btrim"("concat_ws"(', '::"text", NULLIF("btrim"("l"."city"), ''::"text"), NULLIF("btrim"("l"."state"), ''::"text"))), ''::"text"), NULLIF("btrim"("l"."country"), ''::"text")) AS "territory",
    "l"."city",
    "l"."state" AS "region",
    "l"."country",
    COALESCE(NULLIF("btrim"(("s"."meta" ->> 'family'::"text")), ''::"text"), NULLIF("btrim"(("s"."meta" ->> 'software_family'::"text")), ''::"text"), NULLIF("btrim"(("s"."meta" ->> 'catalog_family'::"text")), ''::"text")) AS "family",
    COALESCE(NULLIF("btrim"(("s"."meta" ->> 'software_family'::"text")), ''::"text"), NULLIF("btrim"(("s"."meta" ->> 'family'::"text")), ''::"text"), NULLIF("btrim"(("s"."meta" ->> 'catalog_family'::"text")), ''::"text")) AS "software_family",
    COALESCE(NULLIF("btrim"(("s"."meta" ->> 'catalog_family'::"text")), ''::"text"), NULLIF("btrim"(("s"."meta" ->> 'family'::"text")), ''::"text"), NULLIF("btrim"(("s"."meta" ->> 'software_family'::"text")), ''::"text")) AS "catalog_family",
    "s"."relation_status",
    "s"."source_kind",
    "s"."import_enabled",
    "s"."notes",
    "s"."meta",
    "s"."created_at",
    "s"."updated_at"
   FROM ("ingest"."partner_catalog_sources" "s"
     LEFT JOIN "public"."libraries" "l" ON (("l"."id" = "s"."library_id")));


ALTER VIEW "api"."partner_catalog_sources_ui" OWNER TO "postgres";


CREATE OR REPLACE VIEW "api"."peb_history_v1" WITH ("security_invoker"='true') AS
 WITH "items_agg" AS (
         SELECT "it"."interlibrary_loan_id",
            ("count"(*))::integer AS "items_count",
            "string_agg"("it"."bib_ref", ' ; '::"text" ORDER BY "it"."id") AS "bib_refs",
            ("count"(*) FILTER (WHERE ("it"."item_status" = ANY (ARRAY['devolvido'::"text", 'perdido'::"text", 'danificado'::"text", 'cancelado'::"text"]))))::integer AS "items_settled"
           FROM "public"."interlibrary_loan_items_v2" "it"
          GROUP BY "it"."interlibrary_loan_id"
        )
 SELECT "ll"."id",
    "ll"."request_id",
    "ll"."lender_library_id",
    "lend"."slug" AS "lender_slug",
    "lend"."name" AS "lender_name",
    "ll"."borrower_library_id",
    "borr"."slug" AS "borrower_slug",
    "borr"."name" AS "borrower_name",
    "ll"."initiated_by_library_id",
    "ll"."status_global",
    COALESCE("ia"."items_count", 0) AS "items_count",
    COALESCE("ia"."items_settled", 0) AS "items_settled",
    "ia"."bib_refs",
    "ll"."start_date",
    "ll"."due_date",
    "ll"."dispatched_at",
    "ll"."returned_at",
    "ll"."notes",
    "ll"."created_at",
    "ll"."updated_at",
    COALESCE("ll"."returned_at", "ll"."updated_at") AS "closed_at",
    "ll"."archived_at",
    "ll"."archive_reason"
   FROM ((("public"."interlibrary_loans_v2" "ll"
     JOIN "public"."libraries" "lend" ON (("lend"."id" = "ll"."lender_library_id")))
     JOIN "public"."libraries" "borr" ON (("borr"."id" = "ll"."borrower_library_id")))
     LEFT JOIN "items_agg" "ia" ON (("ia"."interlibrary_loan_id" = "ll"."id")))
  WHERE ("ll"."archived_at" IS NOT NULL)
  ORDER BY "ll"."archived_at" DESC, "ll"."id" DESC;


ALTER VIEW "api"."peb_history_v1" OWNER TO "postgres";


COMMENT ON VIEW "api"."peb_history_v1" IS 'Historique des PEB archivés, par bibliothèque. security_invoker : la RLS de interlibrary_loans_v2 s''applique. Ne liste que archived_at IS NOT NULL ; la file active lit la table directement avec le filtre inverse.';



CREATE OR REPLACE VIEW "api"."public_libraries" WITH ("security_invoker"='true') AS
 SELECT "l"."id",
    "l"."slug",
    "l"."name",
    "l"."short_name",
    "l"."city",
    "l"."state",
    "l"."country",
    "lc"."affiliation_label",
    "lc"."website_url",
    "lc"."logo_url",
    "l"."catalog_mode",
    "l"."circulation_mode",
    ( SELECT "count"(DISTINCT "bh"."book_id") AS "count"
           FROM "public"."book_holdings" "bh"
          WHERE ("bh"."library_id" = "l"."id")) AS "notices_count",
        CASE
            WHEN (("l"."catalog_mode" = 'network_published'::"text") AND ("l"."circulation_mode" = 'full_sigb'::"text")) THEN 'automatizado'::"text"
            ELSE 'em_construcao'::"text"
        END AS "catalog_status"
   FROM ("public"."libraries" "l"
     LEFT JOIN "public"."library_commons" "lc" ON (("lc"."library_id" = "l"."id")))
  WHERE (("l"."is_active" = true) AND ("l"."visibility_level" = 'public'::"text"));


ALTER VIEW "api"."public_libraries" OWNER TO "postgres";


COMMENT ON VIEW "api"."public_libraries" IS 'Galerie publique des bibliothèques du réseau AnarBib (chantier #K2). N''expose que les biblios actives dont le catalogue est public (visibility_level = ''public''). Lecture anonyme autorisée. Aucune donnée sensible : ni membres, ni emails internes, ni adresse postale.';



CREATE OR REPLACE VIEW "api"."staff_loans_renewal_status_by_item_v1" WITH ("security_invoker"='true') AS
 WITH "staff_open_items" AS (
         SELECT "e"."id" AS "emprestimo_id",
            "i"."line_no",
            "i"."sub_id",
            "i"."book_id",
            "i"."holding_id",
            "e"."user_id",
            "e"."library_id",
            COALESCE("i"."renewals_used", 0) AS "renewals_used",
            COALESCE("i"."extended_until", "i"."due_at") AS "effective_due_at"
           FROM ("public"."emprestimos_v2" "e"
             JOIN "public"."emprestimo_itens_v2" "i" ON (("i"."emprestimo_id" = "e"."id")))
          WHERE (("e"."archived_at" IS NULL) AND ("i"."item_status" = 'aberto'::"text"))
        ), "with_dues" AS (
         SELECT "l"."emprestimo_id",
            "l"."line_no",
            "l"."sub_id",
            "l"."book_id",
            "l"."holding_id",
            "l"."user_id",
            "l"."library_id",
            "l"."renewals_used",
            "l"."effective_due_at",
            "public"."fn_is_loan_blocked_by_dues"("l"."user_id", "l"."library_id") AS "dues_blocked",
            (EXISTS ( SELECT 1
                   FROM ("public"."reserva_linhas_v2" "rl"
                     JOIN "public"."reservas_v2" "r" ON (("r"."id" = "rl"."reserva_id")))
                  WHERE (("rl"."book_id" = "l"."book_id") AND ("r"."library_id" = "l"."library_id") AND ("r"."user_id" <> "l"."user_id") AND ("r"."status_global" = ANY (ARRAY['ativa'::"text", 'parcialmente_encerrada'::"text"])) AND ("rl"."item_status" = 'ativa'::"text") AND ("r"."archived_at" IS NULL)))) AS "reserved_by_other"
           FROM "staff_open_items" "l"
        ), "with_rule" AS (
         SELECT "w"."emprestimo_id",
            "w"."line_no",
            "w"."sub_id",
            "w"."book_id",
            "w"."holding_id",
            "w"."user_id",
            "w"."library_id",
            "w"."renewals_used",
            "w"."effective_due_at",
            "w"."dues_blocked",
            "w"."reserved_by_other",
            "rr"."renewable",
            "rr"."renewals_remaining",
            "rr"."renewal_days",
            "rr"."rule_label"
           FROM ("with_dues" "w"
             LEFT JOIN LATERAL "api"."get_remaining_renewals"("p_library_id" => "w"."library_id", "p_user_id" => "w"."user_id", "p_book_id" => "w"."book_id", "p_holding_id" => "w"."holding_id", "p_quantity" => 1, "p_renewals_used" => "w"."renewals_used", "p_as_of_date" => CURRENT_DATE) "rr"("renewable", "renewals_remaining", "renewal_days", "policy_set_id", "rule_id", "rule_label", "explanation") ON (true))
        )
 SELECT "emprestimo_id",
    "line_no",
    "sub_id",
    "user_id",
    "library_id",
    "book_id",
    "effective_due_at",
    "renewals_used",
    COALESCE("renewable", false) AS "renewable",
    COALESCE("renewals_remaining", 0) AS "renewals_remaining",
    "rule_label",
        CASE
            WHEN "dues_blocked" THEN 'dues_blocked'::"text"
            WHEN (COALESCE("effective_due_at", CURRENT_DATE) < CURRENT_DATE) THEN 'overdue'::"text"
            WHEN "reserved_by_other" THEN 'reserved_by_other'::"text"
            WHEN ((COALESCE("renewable", false) IS FALSE) AND (COALESCE("renewals_remaining", 0) <= 0) AND (COALESCE("renewals_used", 0) > 0)) THEN 'quota_exceeded'::"text"
            WHEN (COALESCE("renewable", false) IS FALSE) THEN 'not_renewable'::"text"
            WHEN ((COALESCE("renewals_used", 0) >= 1) AND (COALESCE("renewals_remaining", 0) <= 0)) THEN 'already_extended'::"text"
            ELSE NULL::"text"
        END AS "blocking_reason",
    ((COALESCE("renewable", false) IS TRUE) AND (NOT "dues_blocked") AND (COALESCE("effective_due_at", CURRENT_DATE) >= CURRENT_DATE) AND (NOT "reserved_by_other") AND (COALESCE("renewals_remaining", 0) > 0)) AS "can_renew"
   FROM "with_rule";


ALTER VIEW "api"."staff_loans_renewal_status_by_item_v1" OWNER TO "postgres";


CREATE OR REPLACE VIEW "api"."staff_loans_renewal_status_v1" WITH ("security_invoker"='true') AS
 WITH "staff_open_loans" AS (
         SELECT "e"."id" AS "emprestimo_id",
            "e"."user_id",
            "e"."library_id",
            "e"."renewals_used",
            "e"."extended_once",
            ( SELECT ("count"(*))::integer AS "count"
                   FROM "public"."emprestimo_itens_v2" "i"
                  WHERE (("i"."emprestimo_id" = "e"."id") AND ("i"."item_status" = 'aberto'::"text"))) AS "open_items_count",
            ( SELECT "min"("i"."book_id") AS "min"
                   FROM "public"."emprestimo_itens_v2" "i"
                  WHERE (("i"."emprestimo_id" = "e"."id") AND ("i"."item_status" = 'aberto'::"text"))) AS "first_book_id",
            ( SELECT "min"("i"."holding_id") AS "min"
                   FROM "public"."emprestimo_itens_v2" "i"
                  WHERE (("i"."emprestimo_id" = "e"."id") AND ("i"."item_status" = 'aberto'::"text"))) AS "first_holding_id",
            ( SELECT "max"(COALESCE("i"."extended_until", "i"."due_at")) AS "max"
                   FROM "public"."emprestimo_itens_v2" "i"
                  WHERE (("i"."emprestimo_id" = "e"."id") AND ("i"."item_status" = 'aberto'::"text"))) AS "effective_due_at"
           FROM "public"."emprestimos_v2" "e"
          WHERE (("e"."archived_at" IS NULL) AND (EXISTS ( SELECT 1
                   FROM "public"."emprestimo_itens_v2" "i"
                  WHERE (("i"."emprestimo_id" = "e"."id") AND ("i"."item_status" = 'aberto'::"text")))))
        ), "with_dues" AS (
         SELECT "l"."emprestimo_id",
            "l"."user_id",
            "l"."library_id",
            "l"."renewals_used",
            "l"."extended_once",
            "l"."open_items_count",
            "l"."first_book_id",
            "l"."first_holding_id",
            "l"."effective_due_at",
            "public"."fn_is_loan_blocked_by_dues"("l"."user_id", "l"."library_id") AS "dues_blocked",
            (EXISTS ( SELECT 1
                   FROM ("public"."reserva_linhas_v2" "rl"
                     JOIN "public"."reservas_v2" "r" ON (("r"."id" = "rl"."reserva_id")))
                  WHERE (("rl"."book_id" = "l"."first_book_id") AND ("r"."library_id" = "l"."library_id") AND ("r"."user_id" <> "l"."user_id") AND ("r"."status_global" = ANY (ARRAY['ativa'::"text", 'parcialmente_encerrada'::"text"])) AND ("rl"."item_status" = 'ativa'::"text") AND ("r"."archived_at" IS NULL)))) AS "reserved_by_other"
           FROM "staff_open_loans" "l"
        ), "with_rule" AS (
         SELECT "w"."emprestimo_id",
            "w"."user_id",
            "w"."library_id",
            "w"."renewals_used",
            "w"."extended_once",
            "w"."open_items_count",
            "w"."first_book_id",
            "w"."first_holding_id",
            "w"."effective_due_at",
            "w"."dues_blocked",
            "w"."reserved_by_other",
            "rr"."renewable",
            "rr"."renewals_remaining",
            "rr"."renewal_days",
            "rr"."rule_label"
           FROM ("with_dues" "w"
             LEFT JOIN LATERAL "api"."get_remaining_renewals"("p_library_id" => "w"."library_id", "p_user_id" => "w"."user_id", "p_book_id" => "w"."first_book_id", "p_holding_id" => "w"."first_holding_id", "p_quantity" => "w"."open_items_count", "p_renewals_used" => COALESCE("w"."renewals_used", 0), "p_as_of_date" => CURRENT_DATE) "rr"("renewable", "renewals_remaining", "renewal_days", "policy_set_id", "rule_id", "rule_label", "explanation") ON (true))
        )
 SELECT "emprestimo_id",
    "user_id",
    "library_id",
    "effective_due_at",
    "open_items_count",
    "renewals_used",
    COALESCE("renewable", false) AS "renewable",
    COALESCE("renewals_remaining", 0) AS "renewals_remaining",
    "rule_label",
        CASE
            WHEN "dues_blocked" THEN 'dues_blocked'::"text"
            WHEN (COALESCE("effective_due_at", CURRENT_DATE) < CURRENT_DATE) THEN 'overdue'::"text"
            WHEN "reserved_by_other" THEN 'reserved_by_other'::"text"
            WHEN ((COALESCE("renewable", false) IS FALSE) AND (COALESCE("renewals_remaining", 0) <= 0) AND (COALESCE("renewals_used", 0) > 0)) THEN 'quota_exceeded'::"text"
            WHEN (COALESCE("renewable", false) IS FALSE) THEN 'not_renewable'::"text"
            WHEN ((COALESCE("renewals_used", 0) >= 1) AND (COALESCE("renewals_remaining", 0) <= 0)) THEN 'already_extended'::"text"
            ELSE NULL::"text"
        END AS "blocking_reason",
    ((COALESCE("renewable", false) IS TRUE) AND (NOT "dues_blocked") AND (COALESCE("effective_due_at", CURRENT_DATE) >= CURRENT_DATE) AND (NOT "reserved_by_other") AND (COALESCE("renewals_remaining", 0) > 0)) AS "can_renew"
   FROM "with_rule";


ALTER VIEW "api"."staff_loans_renewal_status_v1" OWNER TO "postgres";


COMMENT ON VIEW "api"."staff_loans_renewal_status_v1" IS 'Paquet 11 (10/05/2026) : pre-evaluation des renouvellements pour PanelPage
(staff biblio). Symetrique à api.my_loans_renewal_status_v1 sans filtre
auth.uid() explicite : la policy RLS emprestimos_v2_select_policy applique
