CREATE TABLE IF NOT EXISTS "public"."digital_assets" (
    "id" bigint NOT NULL,
    "asset_kind" "text" DEFAULT 'pdf'::"text" NOT NULL,
    "title" "text" NOT NULL,
    "author" "text",
    "published_year" integer,
    "language_code" "text",
    "book_id" bigint,
    "bib_ref" "text",
    "source_name" "text" NOT NULL,
    "source_url" "text",
    "source_license_name" "text",
    "source_license_url" "text",
    "rights_status" "text" DEFAULT 'to_review'::"text" NOT NULL,
    "attribution_text" "text",
    "modified_from_source" boolean DEFAULT false NOT NULL,
    "bucket_name" "text" NOT NULL,
    "object_path" "text" NOT NULL,
    "is_public" boolean DEFAULT false NOT NULL,
    "mime_type" "text" DEFAULT 'application/pdf'::"text" NOT NULL,
    "file_size_bytes" bigint,
    "page_count" integer,
    "checksum_sha256" "text",
    "verified_at" timestamp with time zone,
    "verified_by" "uuid",
    "notes" "text",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "chk_object_path_no_url" CHECK ((("object_path" IS NULL) OR ("object_path" !~~ 'http%'::"text"))),
    CONSTRAINT "digital_assets_asset_kind_check" CHECK (("asset_kind" = ANY (ARRAY['pdf'::"text", 'audio'::"text", 'video'::"text", 'image'::"text", 'epub'::"text", 'archive'::"text", 'external_link'::"text", 'generic'::"text"]))),
    CONSTRAINT "digital_assets_bucket_name_check" CHECK ((("bucket_name" IS NULL) OR ("bucket_name" = ANY (ARRAY['pdf-restrito'::"text", 'anarbib-pdf-public'::"text", 'anarbib-media-restricted'::"text", 'anarbib-media-public'::"text"])))),
    CONSTRAINT "digital_assets_kind_bucket_chk" CHECK (((("bucket_name" IS NULL) AND ("asset_kind" = ANY (ARRAY['external_link'::"text", 'generic'::"text"]))) OR (("bucket_name" = ANY (ARRAY['pdf-restrito'::"text", 'anarbib-pdf-public'::"text"])) AND ("asset_kind" = 'pdf'::"text")) OR (("bucket_name" = ANY (ARRAY['anarbib-media-restricted'::"text", 'anarbib-media-public'::"text"])) AND ("asset_kind" = ANY (ARRAY['audio'::"text", 'video'::"text", 'image'::"text"]))))),
    CONSTRAINT "digital_assets_public_bucket_chk" CHECK ((("is_public" = false) OR ("bucket_name" IS NULL) OR ("bucket_name" = ANY (ARRAY['anarbib-pdf-public'::"text", 'anarbib-media-public'::"text"])))),
    CONSTRAINT "digital_assets_rights_status_check" CHECK (("rights_status" = ANY (ARRAY['to_review'::"text", 'public_domain_confirmed'::"text", 'source_reuse_allowed'::"text", 'restricted'::"text", 'do_not_publish'::"text"])))
);


