CREATE TABLE IF NOT EXISTS "public"."library_membership_audit" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "library_id" "uuid" NOT NULL,
    "target_user_id" "uuid" NOT NULL,
    "actor_user_id" "uuid",
    "action" "text" NOT NULL,
    "role" "text" NOT NULL,
    "status_before" "text",
    "status_after" "text" NOT NULL,
    "reason" "text",
    "metadata" "jsonb" DEFAULT '{}'::"jsonb",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "library_membership_audit_action_check" CHECK (("action" = ANY (ARRAY['promoted_to_librarian'::"text", 'promoted_to_coordenador'::"text", 'promoted_to_administrador'::"text", 'self_demoted'::"text", 'removal_requested'::"text", 'removal_cancelled'::"text", 'removal_completed'::"text", 'suspended'::"text", 'unsuspended'::"text", 'inactive_warning_30d'::"text", 'inactive_warning_7d'::"text", 'inactive_auto'::"text"]))),
    CONSTRAINT "library_membership_audit_role_check" CHECK (("role" = ANY (ARRAY['reader'::"text", 'librarian'::"text", 'coordenador'::"text", 'administrador'::"text"])))
);


ALTER TABLE "public"."library_membership_audit" OWNER TO "postgres";


COMMENT ON TABLE "public"."library_membership_audit" IS 'Journal des changements de rôle/status dans les équipes de biblio. Lecture pour le staff actif (transparence P5). Écriture uniquement via RPC SECURITY DEFINER. Cf. spec-gouvernance-roles.md §7 et §10.2.';



CREATE TABLE IF NOT EXISTS "public"."library_membership_rules" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "library_id" "uuid" NOT NULL,
    "name" "text" NOT NULL,
    "description" "text",
    "amount_min" numeric(10,2) DEFAULT 0 NOT NULL,
    "amount_suggested" numeric(10,2),
    "currency" "text" DEFAULT 'EUR'::"text" NOT NULL,
    "period_type" "public"."membership_period_type" DEFAULT 'annual'::"public"."membership_period_type" NOT NULL,
    "period_anchor" "public"."membership_period_anchor" DEFAULT 'rolling'::"public"."membership_period_anchor" NOT NULL,
    "is_required" boolean DEFAULT true NOT NULL,
    "is_active" boolean DEFAULT true NOT NULL,
    "display_order" integer DEFAULT 0 NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "created_by" "uuid",
    CONSTRAINT "library_membership_rules_amount_min_check" CHECK (("amount_min" >= (0)::numeric)),
    CONSTRAINT "library_membership_rules_check" CHECK ((("amount_suggested" IS NULL) OR ("amount_suggested" >= "amount_min"))),
    CONSTRAINT "library_membership_rules_currency_check" CHECK ((("length"("currency") = 3) AND ("currency" = "upper"("currency"))))
);


ALTER TABLE "public"."library_membership_rules" OWNER TO "postgres";


COMMENT ON TABLE "public"."library_membership_rules" IS 'Règles de cotisation propres à chaque bibliothèque. Plusieurs règles actives possibles (ex. tarif standard + tarif réduit).';



COMMENT ON COLUMN "public"."library_membership_rules"."amount_min" IS 'Montant minimum requis dans la devise locale. 0 = prix libre (don accepté).';



COMMENT ON COLUMN "public"."library_membership_rules"."amount_suggested" IS 'Montant conseillé pour l''affichage. Doit être ≥ amount_min.';



COMMENT ON COLUMN "public"."library_membership_rules"."period_anchor" IS '''rolling'' = valable N temps à partir du paiement ; ''calendar'' = jusqu''à la fin de l''année civile.';



COMMENT ON COLUMN "public"."library_membership_rules"."is_required" IS 'Si true, l''absence de cotisation à jour bloque l''emprunt. Si false, simple rappel non bloquant.';



