    "grace_until" timestamp with time zone NOT NULL,
    "released_at" timestamp with time zone,
    CONSTRAINT "chk_lpgl_grace_after_lock" CHECK (("grace_until" > "locked_at")),
    CONSTRAINT "library_profile_grace_locks_affected_axis_check" CHECK (("affected_axis" = ANY (ARRAY['catalog_mode'::"text", 'circulation_mode'::"text", 'network_mode'::"text", 'governance_mode'::"text"])))
);


