CREATE TABLE IF NOT EXISTS "public"."library_profile_history" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "library_id" "uuid" NOT NULL,
    "axis" "text" NOT NULL,
    "old_value" "text" NOT NULL,
    "new_value" "text" NOT NULL,
    "changed_by" "uuid",
    "changed_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "motivation" "text",
    CONSTRAINT "chk_distinct_values" CHECK (("old_value" <> "new_value")),
    CONSTRAINT "library_profile_history_axis_check" CHECK (("axis" = ANY (ARRAY['catalog_mode'::"text", 'circulation_mode'::"text", 'network_mode'::"text", 'governance_mode'::"text"])))
);


ALTER TABLE "public"."library_profile_history" OWNER TO "postgres";


