CREATE TABLE IF NOT EXISTS "public"."library_profile_proposals" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "library_id" "uuid" NOT NULL,
    "axis" "text" NOT NULL,
    "old_value" "text" NOT NULL,
    "new_value" "text" NOT NULL,
    "transition_type" integer NOT NULL,
    "governance_required" "text" NOT NULL,
    "motivation" "text" NOT NULL,
    "proposed_by" "uuid" NOT NULL,
    "proposed_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "status" "text" DEFAULT 'open'::"text" NOT NULL,
    "unanimous_at" timestamp with time zone,
    "majority_at" timestamp with time zone,
    "expires_at" timestamp with time zone NOT NULL,
    "grace_period_until" timestamp with time zone,
    "completed_at" timestamp with time zone,
    "cancelled_at" timestamp with time zone,
    "cancelled_by" "uuid",
    "cancelled_motivation" "text",
    CONSTRAINT "chk_lpp_cancelled_triplet" CHECK (((("cancelled_at" IS NULL) AND ("cancelled_by" IS NULL) AND ("cancelled_motivation" IS NULL)) OR (("cancelled_at" IS NOT NULL) AND ("cancelled_by" IS NOT NULL) AND ("cancelled_motivation" IS NOT NULL) AND ("length"("cancelled_motivation") >= 5)))),
    CONSTRAINT "chk_lpp_status_dates" CHECK (((("status" = 'open'::"text") AND ("completed_at" IS NULL)) OR (("status" = ANY (ARRAY['rejected'::"text", 'expired'::"text", 'cancelled'::"text"])) AND ("completed_at" IS NULL)) OR (("status" = ANY (ARRAY['accepted_unanimous'::"text", 'accepted_majority'::"text"])) AND ("completed_at" IS NULL)) OR (("status" = 'completed'::"text") AND ("completed_at" IS NOT NULL)))),
    CONSTRAINT "chk_lpp_values_differ" CHECK (("old_value" <> "new_value")),
    CONSTRAINT "library_profile_proposals_axis_check" CHECK (("axis" = ANY (ARRAY['catalog_mode'::"text", 'circulation_mode'::"text", 'network_mode'::"text", 'governance_mode'::"text"]))),
    CONSTRAINT "library_profile_proposals_governance_required_check" CHECK (("governance_required" = ANY (ARRAY['direct'::"text", 'majority'::"text", 'unanimous'::"text", 'unanimous_extended'::"text"]))),
    CONSTRAINT "library_profile_proposals_motivation_check" CHECK (("length"("motivation") >= 5)),
    CONSTRAINT "library_profile_proposals_status_check" CHECK (("status" = ANY (ARRAY['open'::"text", 'accepted_unanimous'::"text", 'accepted_majority'::"text", 'rejected'::"text", 'expired'::"text", 'cancelled'::"text", 'completed'::"text"]))),
    CONSTRAINT "library_profile_proposals_transition_type_check" CHECK (("transition_type" = ANY (ARRAY[1, 2, 3, 4])))
);


ALTER TABLE "public"."library_profile_proposals" OWNER TO "postgres";


COMMENT ON TABLE "public"."library_profile_proposals" IS 'Audit des propositions de transition de profil (B.1). Une ligne = une demande de changement de *_mode sur une biblio. Immutable sauf colonnes de cycle de vie.';



