CREATE TABLE IF NOT EXISTS "public"."painel_internal_tasks" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "library_id" "uuid" NOT NULL,
    "title" "text" NOT NULL,
    "description" "text",
    "priority" "text" DEFAULT 'media'::"text" NOT NULL,
    "status" "text" DEFAULT 'pendente'::"text" NOT NULL,
    "owner" "text",
    "owner_user_id" "uuid",
    "due_date" "date",
    "tags" "text"[] DEFAULT '{}'::"text"[] NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "created_by" "uuid" DEFAULT "auth"."uid"(),
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_by" "uuid" DEFAULT "auth"."uid"(),
    "recurrence_rule_id" "uuid",
    "recurrence_stale_flagged_at" timestamp with time zone,
    "title_i18n" "jsonb",
    "description_i18n" "jsonb"
);


ALTER TABLE "public"."painel_internal_tasks" OWNER TO "postgres";


COMMENT ON TABLE "public"."painel_internal_tasks" IS 'Tâches internes du panel admin. Anon SELECT révoqué le 2026-04-26 (palier 4).';



COMMENT ON COLUMN "public"."painel_internal_tasks"."library_id" IS 'Biblioteca à qual a tarefa pertence.';



COMMENT ON COLUMN "public"."painel_internal_tasks"."priority" IS 'Prioridade livre, ex.: baixa, media, alta, urgente.';



COMMENT ON COLUMN "public"."painel_internal_tasks"."status" IS 'Situação livre, ex.: aberta, em_andamento, bloqueada, concluida, arquivada.';



COMMENT ON COLUMN "public"."painel_internal_tasks"."owner" IS 'Nome curto da pessoa responsável, pronto para exibição no front.';



COMMENT ON COLUMN "public"."painel_internal_tasks"."owner_user_id" IS 'Vínculo opcional com a pessoa responsável em profiles.';



COMMENT ON COLUMN "public"."painel_internal_tasks"."tags" IS 'Lista simples de marcadores internos.';



COMMENT ON COLUMN "public"."painel_internal_tasks"."recurrence_rule_id" IS 'Rattache la tache a une serie recurrente (#TASKS, etape 2). NULL = tache ponctuelle. Renseigne = occurrence d''une serie ; voir painel_recurring_task_rules.';



COMMENT ON COLUMN "public"."painel_internal_tasks"."recurrence_stale_flagged_at" IS 'Marqueur du cron de securite #TASKS 3-bis : pose quand une occurrence recurrente est en souffrance (chaine interrompue — pendente/em_andamento et due_date depassee de plus de 7 jours). NULL = pas en souffrance. Le Painel met ces taches en evidence.';



COMMENT ON COLUMN "public"."painel_internal_tasks"."title_i18n" IS 'Titre multilingue (jsonb {locale: texte}) herite du modele a l''instanciation. NULL = tache manuelle (texte simple title).';



CREATE TABLE IF NOT EXISTS "public"."painel_recurring_task_rules" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "library_id" "uuid" NOT NULL,
    "interval_count" integer,
    "interval_unit" "text",
    "label" "text",
    "is_active" boolean DEFAULT true NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "created_by" "uuid" DEFAULT "auth"."uid"(),
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_by" "uuid" DEFAULT "auth"."uid"(),
    "template_title" "text",
    "template_description" "text",
    "template_priority" "text" DEFAULT 'media'::"text" NOT NULL,
    "template_tags" "text"[] DEFAULT '{}'::"text"[] NOT NULL,
    "adopted_from_suggestion_code" "text",
    "title_i18n" "jsonb",
    "description_i18n" "jsonb",
    CONSTRAINT "painel_recurring_task_rules_cadence_coherence_chk" CHECK (((("interval_count" IS NULL) AND ("interval_unit" IS NULL)) OR (("interval_count" IS NOT NULL) AND ("interval_unit" IS NOT NULL)))),
    CONSTRAINT "painel_recurring_task_rules_interval_count_chk" CHECK (("interval_count" > 0)),
    CONSTRAINT "painel_recurring_task_rules_interval_unit_chk" CHECK (("interval_unit" = ANY (ARRAY['dia'::"text", 'semana'::"text", 'mes'::"text"]))),
    CONSTRAINT "painel_recurring_task_rules_template_priority_chk" CHECK (("template_priority" = ANY (ARRAY['baixa'::"text", 'media'::"text", 'alta'::"text"])))
);


ALTER TABLE "public"."painel_recurring_task_rules" OWNER TO "postgres";


COMMENT ON TABLE "public"."painel_recurring_task_rules" IS 'Tache-type locale d''une bibliotheque (#TASKS, etape 4). Porte le contenu du modele (template_title, template_description, template_priority, template_tags) ET, optionnellement, sa cadence de recurrence (interval_count x interval_unit). Cadence renseignee = modele recurrent ; cadence NULL = modele ponctuel. Le nom historique « recurring_task_rules » est conserve ; la table couvre desormais aussi les modeles ponctuels.';



COMMENT ON COLUMN "public"."painel_recurring_task_rules"."adopted_from_suggestion_code" IS 'Code de la suggestion (painel_task_suggestion_catalog.code) dont cette tache-type est issue, ou NULL si creee a la main. Sert a masquer la suggestion du catalogue cote UI.';



COMMENT ON COLUMN "public"."painel_recurring_task_rules"."title_i18n" IS 'Titre multilingue (jsonb {locale: texte}) herite du catalogue a l''adoption. NULL = modele manuel (texte simple template_title).';



CREATE TABLE IF NOT EXISTS "public"."painel_task_suggestion_catalog" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "code" "text" NOT NULL,
    "category" "text" NOT NULL,
    "title_i18n" "jsonb" NOT NULL,
    "description_i18n" "jsonb" NOT NULL,
    "suggested_interval_count" integer,
    "suggested_interval_unit" "text",
    "display_order" integer DEFAULT 0 NOT NULL,
    "is_active" boolean DEFAULT true NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "painel_task_suggestion_catalog_cadence_coherence_chk" CHECK (((("suggested_interval_count" IS NULL) AND ("suggested_interval_unit" IS NULL)) OR (("suggested_interval_count" IS NOT NULL) AND ("suggested_interval_unit" IS NOT NULL)))),
    CONSTRAINT "painel_task_suggestion_catalog_interval_count_chk" CHECK ((("suggested_interval_count" IS NULL) OR ("suggested_interval_count" > 0))),
    CONSTRAINT "painel_task_suggestion_catalog_interval_unit_chk" CHECK ((("suggested_interval_unit" IS NULL) OR ("suggested_interval_unit" = ANY (ARRAY['dia'::"text", 'semana'::"text", 'mes'::"text"]))))
);


ALTER TABLE "public"."painel_task_suggestion_catalog" OWNER TO "postgres";


COMMENT ON TABLE "public"."painel_task_suggestion_catalog" IS 'Catalogue GLOBAL de suggestions de taches (#TASKS, etape 5). Banque d''idees non imposee, commune au reseau, alimentee par migration. Chaque bibliotheque y pioche pour constituer ses taches-types locales via fn_task_adopt_suggestion. title_i18n / description_i18n : texte porte par la donnee, 8 langues. Cadence suggeree optionnelle (NULL = idee de tache ponctuelle).';



