CREATE TABLE IF NOT EXISTS "public"."team_notification_outbox" (
    "id" bigint NOT NULL,
    "event" "text" NOT NULL,
    "payload" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "status" "text" DEFAULT 'pending'::"text" NOT NULL,
    "pg_net_request_id" bigint,
    "attempts" integer DEFAULT 0 NOT NULL,
    "last_error" "text",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "sent_at" timestamp with time zone,
    CONSTRAINT "team_notification_outbox_event_check" CHECK ((("event" ~~ 'team.%'::"text") OR ("event" ~~ 'network.%'::"text"))),
    CONSTRAINT "team_notification_outbox_status_check" CHECK (("status" = ANY (ARRAY['pending'::"text", 'sent'::"text", 'failed'::"text", 'skipped'::"text"])))
);


ALTER TABLE "public"."team_notification_outbox" OWNER TO "postgres";


COMMENT ON TABLE "public"."team_notification_outbox" IS 'File d''attente des notifications team.*. Chaque ligne représente un event à envoyer à notify-event Edge Function. Cf. spec-gouvernance-roles.md §11.4 (Option B).';



COMMENT ON COLUMN "public"."team_notification_outbox"."event" IS 'Nom de l''event team.* (ex: team.promoted_to_librarian, team.removal_requested...).';



COMMENT ON COLUMN "public"."team_notification_outbox"."payload" IS 'Données métier de l''event en jsonb (library_id, target_user_id, role, etc.).';



COMMENT ON COLUMN "public"."team_notification_outbox"."status" IS 'pending : créé, en attente d''envoi par le trigger. sent : traité avec au moins un destinataire. skipped : traité mais fan-out vide (aucun destinataire, aucun mail émis). failed : envoi en erreur (4xx, 5xx, timeout).';



COMMENT ON COLUMN "public"."team_notification_outbox"."pg_net_request_id" IS 'ID retourné par net.http_post, utile pour debug via net._http_response.';



COMMENT ON CONSTRAINT "team_notification_outbox_event_check" ON "public"."team_notification_outbox" IS 'Whitelist des préfixes d''events autorisés dans cette file outbox : team.* (notifications de gestion du staff) ou network.* (notifications d''actions transverses des admins réseau). Élargi au paquet C.5c-bis (11/05/2026).';



CREATE SEQUENCE IF NOT EXISTS "public"."team_notification_outbox_id_seq"
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1;


ALTER SEQUENCE "public"."team_notification_outbox_id_seq" OWNER TO "postgres";


