CREATE OR REPLACE VIEW "public"."v_active_memberships" WITH ("security_invoker"='true') AS
 WITH "last_payment" AS (
         SELECT DISTINCT ON ("mp"."user_id", "mp"."library_id") "mp"."id",
            "mp"."user_id",
            "mp"."library_id",
            "mp"."rule_id",
            "mp"."amount_paid",
            "mp"."currency",
            "mp"."paid_at",
            "mp"."valid_from",
            "mp"."valid_until",
            "mp"."payment_method"
           FROM "public"."membership_payments" "mp"
          WHERE ("mp"."archived_at" IS NULL)
          ORDER BY "mp"."user_id", "mp"."library_id", "mp"."valid_until" DESC, "mp"."paid_at" DESC
        )
 SELECT "ulm"."user_id",
    "ulm"."library_id",
    "ulm"."role",
    "ulm"."is_primary",
    "ulm"."status" AS "membership_status",
    "l"."membership_enabled",
    "lp"."id" AS "last_payment_id",
    "lp"."rule_id" AS "last_rule_id",
    "lp"."amount_paid" AS "last_amount_paid",
    "lp"."currency" AS "last_currency",
    "lp"."paid_at" AS "last_paid_at",
    "lp"."valid_from" AS "last_valid_from",
    "lp"."valid_until" AS "last_valid_until",
    "lp"."payment_method" AS "last_payment_method",
        CASE
            WHEN (NOT "l"."membership_enabled") THEN 'not_applicable'::"text"
            WHEN ("lp"."id" IS NULL) THEN 'never_paid'::"text"
            WHEN ("lp"."valid_until" IS NULL) THEN 'lifetime'::"text"
            WHEN ("lp"."valid_until" >= CURRENT_DATE) THEN 'up_to_date'::"text"
            ELSE 'expired'::"text"
        END AS "dues_status",
        CASE
            WHEN ("lp"."valid_until" IS NULL) THEN NULL::integer
            ELSE ("lp"."valid_until" - CURRENT_DATE)
        END AS "days_until_expiry"
   FROM (("public"."user_library_memberships" "ulm"
     JOIN "public"."libraries" "l" ON (("l"."id" = "ulm"."library_id")))
     LEFT JOIN "last_payment" "lp" ON ((("lp"."user_id" = "ulm"."user_id") AND ("lp"."library_id" = "ulm"."library_id"))))
  WHERE ("ulm"."status" <> 'removed'::"text");


ALTER VIEW "public"."v_active_memberships" OWNER TO "postgres";


COMMENT ON VIEW "public"."v_active_memberships" IS 'État courant des adhésions par (user, library). dues_status ∈ {not_applicable, never_paid, lifetime, up_to_date, expired}.';



CREATE OR REPLACE VIEW "public"."v_author_alias_candidates_unique" AS
 WITH "remaining" AS (
         SELECT "b"."id" AS "book_id",
            TRIM(BOTH FROM "b"."autor") AS "autor",
            "public"."normalize_author_alias"("b"."autor") AS "autor_norm"
           FROM ("public"."books" "b"
             LEFT JOIN ( SELECT DISTINCT "author_books_public"."book_id"
                   FROM "public"."author_books_public") "abp" ON (("abp"."book_id" = "b"."id")))
          WHERE ((COALESCE(NULLIF(TRIM(BOTH FROM "b"."autor"), ''::"text"), ''::"text") <> ''::"text") AND ("abp"."book_id" IS NULL) AND ("b"."autor" !~~ '%;%'::"text"))
        ), "candidate_rows" AS (
         SELECT DISTINCT "r"."autor",
            "r"."autor_norm",
            "a"."id" AS "author_id",
            "a"."preferred_name",
            "a"."sort_name"
           FROM ("remaining" "r"
             JOIN "public"."authors" "a" ON ((("public"."normalize_author_alias"("a"."preferred_name") = "r"."autor_norm") OR ("public"."normalize_author_alias"("a"."sort_name") = "r"."autor_norm"))))
        ), "candidate_counts" AS (
         SELECT "candidate_rows"."autor_norm",
            "count"(DISTINCT "candidate_rows"."author_id") AS "n"
           FROM "candidate_rows"
          GROUP BY "candidate_rows"."autor_norm"
        )
 SELECT "cr"."autor",
    "cr"."autor_norm",
    "cr"."author_id",
    "cr"."preferred_name",
    "cr"."sort_name"
   FROM ("candidate_rows" "cr"
     JOIN "candidate_counts" "cc" ON (("cc"."autor_norm" = "cr"."autor_norm")))
  WHERE (("cc"."n" = 1) AND (NOT (EXISTS ( SELECT 1
           FROM "public"."author_name_aliases" "ana"
          WHERE (("ana"."alias_norm" = "cr"."autor_norm") AND ("ana"."author_id" = "cr"."author_id") AND ("ana"."is_active" = true))))));


ALTER VIEW "public"."v_author_alias_candidates_unique" OWNER TO "postgres";


COMMENT ON VIEW "public"."v_author_alias_candidates_unique" IS 'REVIEW 2026-03-30: author work view. Verify continued usefulness before any cleanup.';



CREATE OR REPLACE VIEW "public"."v_author_alias_worklist" AS
 WITH "remaining" AS (
         SELECT "b"."id" AS "book_id",
            "b"."bib_ref",
            "b"."titulo",
            TRIM(BOTH FROM "b"."autor") AS "autor",
            "public"."normalize_author_alias"("b"."autor") AS "autor_norm"
           FROM ("public"."books" "b"
             LEFT JOIN ( SELECT DISTINCT "author_books_public"."book_id"
                   FROM "public"."author_books_public") "abp" ON (("abp"."book_id" = "b"."id")))
          WHERE ((COALESCE(NULLIF(TRIM(BOTH FROM "b"."autor"), ''::"text"), ''::"text") <> ''::"text") AND ("abp"."book_id" IS NULL) AND ("b"."autor" !~~ '%;%'::"text"))
        ), "alias_hits" AS (
         SELECT "ana"."alias_norm",
            "count"(DISTINCT "ana"."author_id") AS "alias_matches",
            "string_agg"(DISTINCT ("ana"."author_id")::"text", ', '::"text" ORDER BY ("ana"."author_id")::"text") AS "alias_author_ids"
           FROM "public"."author_name_aliases" "ana"
          WHERE ("ana"."is_active" = true)
          GROUP BY "ana"."alias_norm"
        ), "candidate_hits" AS (
         SELECT "r_1"."autor_norm",
            "count"(DISTINCT "a"."id") AS "candidate_matches",
            "string_agg"(DISTINCT ("a"."id")::"text", ', '::"text" ORDER BY ("a"."id")::"text") AS "candidate_author_ids"
           FROM (( SELECT DISTINCT "remaining"."autor_norm"
                   FROM "remaining") "r_1"
             JOIN "public"."authors" "a" ON ((("public"."normalize_author_alias"("a"."preferred_name") = "r_1"."autor_norm") OR ("public"."normalize_author_alias"("a"."sort_name") = "r_1"."autor_norm"))))
          GROUP BY "r_1"."autor_norm"
        )
 SELECT "r"."autor",
    "r"."autor_norm",
    "count"(*) AS "books_count",
    "min"("r"."bib_ref") AS "sample_bib_ref",
    "min"("r"."titulo") AS "sample_title",
    COALESCE("ah"."alias_matches", (0)::bigint) AS "alias_matches",
    "ah"."alias_author_ids",
    COALESCE("ch"."candidate_matches", (0)::bigint) AS "candidate_matches",
    "ch"."candidate_author_ids",
        CASE
            WHEN (COALESCE("ah"."alias_matches", (0)::bigint) > 0) THEN 'alias_exists'::"text"
            WHEN (COALESCE("ch"."candidate_matches", (0)::bigint) = 1) THEN 'candidate_existing_author'::"text"
            WHEN (COALESCE("ch"."candidate_matches", (0)::bigint) > 1) THEN 'ambiguous_existing_author'::"text"
            ELSE 'needs_new_author'::"text"
        END AS "status"
   FROM (("remaining" "r"
     LEFT JOIN "alias_hits" "ah" ON (("ah"."alias_norm" = "r"."autor_norm")))
     LEFT JOIN "candidate_hits" "ch" ON (("ch"."autor_norm" = "r"."autor_norm")))
  GROUP BY "r"."autor", "r"."autor_norm", "ah"."alias_matches", "ah"."alias_author_ids", "ch"."candidate_matches", "ch"."candidate_author_ids";


ALTER VIEW "public"."v_author_alias_worklist" OWNER TO "postgres";


COMMENT ON VIEW "public"."v_author_alias_worklist" IS 'REVIEW 2026-03-30: author work view. Verify continued usefulness before any cleanup.';



CREATE OR REPLACE VIEW "public"."v_author_seed_candidates" AS
 WITH "unresolved" AS (
         SELECT TRIM(BOTH FROM "book_contributors"."name") AS "raw_name",
            "lower"(TRIM(BOTH FROM "book_contributors"."name")) AS "unresolved_name",
            "public"."norm_match_text"(TRIM(BOTH FROM "book_contributors"."name")) AS "unresolved_norm",
            "count"(*) AS "uses",
            "min"("book_contributors"."book_id") AS "sample_book_id"
           FROM "public"."book_contributors"
          WHERE (("book_contributors"."author_id" IS NULL) AND (TRIM(BOTH FROM COALESCE("book_contributors"."name", ''::"text")) <> ''::"text"))
          GROUP BY (TRIM(BOTH FROM "book_contributors"."name")), ("lower"(TRIM(BOTH FROM "book_contributors"."name"))), ("public"."norm_match_text"(TRIM(BOTH FROM "book_contributors"."name")))
        ), "filtered" AS (
         SELECT "unresolved"."raw_name",
            "unresolved"."unresolved_name",
            "unresolved"."unresolved_norm",
            "unresolved"."uses",
            "unresolved"."sample_book_id"
           FROM "unresolved"
          WHERE (("unresolved"."uses" >= 3) AND ("unresolved"."raw_name" !~ '^[ /0-9]'::"text") AND ("lower"("unresolved"."raw_name") <> ALL (ARRAY['aa. vv'::"text", 'anônimo'::"text", 'c.n.t.'::"text", 'cnt'::"text", 'coletivo'::"text"])) AND ("unresolved"."raw_name" !~~* '%grupo%'::"text") AND ("unresolved"."raw_name" !~~* '%rivista%'::"text") AND ("unresolved"."raw_name" !~~* '%taller%'::"text") AND ("unresolved"."raw_name" !~~* '%escuela%'::"text") AND ("unresolved"."raw_name" !~~* '%confederación%'::"text"))
        )
 SELECT "raw_name",
    "unresolved_name",
    "unresolved_norm",
    "uses",
    "sample_book_id"
   FROM "filtered"
  ORDER BY "uses" DESC, "unresolved_name";


ALTER VIEW "public"."v_author_seed_candidates" OWNER TO "postgres";


COMMENT ON VIEW "public"."v_author_seed_candidates" IS 'REVIEW 2026-03-30: author work view. Verify continued usefulness before any cleanup.';



CREATE OR REPLACE VIEW "public"."v_books_catalog_list_v1" WITH ("security_invoker"='true') AS
 WITH "first_author" AS (
         SELECT DISTINCT ON ("ba"."book_id") "ba"."book_id",
            "ba"."author_id"
           FROM "public"."book_authors" "ba"
          WHERE ("ba"."author_id" IS NOT NULL)
          ORDER BY "ba"."book_id", "ba"."ord", "ba"."author_id"
        ), "digital_flags" AS (
         SELECT "r"."book_id",
            "bool_or"((("r"."resource_type" = 'pdf_restrito'::"text") AND ("r"."usage_type" = 'leitura_online'::"text") AND ("r"."access_scope" = 'conta_ativa'::"text") AND ("r"."status" = 'active'::"text") AND (COALESCE("r"."is_active", false) = true))) AS "has_online_reading"
           FROM "public"."book_digital_resources" "r"
          GROUP BY "r"."book_id"
        ), "holdings_summary" AS (
         SELECT "h"."book_id",
            ("count"(*))::integer AS "bibliotecas_count",
            (COALESCE("sum"("h"."exemplares_total"), (0)::bigint))::integer AS "exemplares_total",
            (COALESCE("sum"("h"."available_count"), (0)::bigint))::integer AS "global_available_count"
           FROM "public"."book_holdings" "h"
          GROUP BY "h"."book_id"
        ), "single_library" AS (
         SELECT "h"."book_id",
            "h"."library_id",
            "l"."slug" AS "library_slug",
            "l"."name" AS "library_name"
           FROM ("public"."book_holdings" "h"
             JOIN "public"."libraries" "l" ON (("l"."id" = "h"."library_id")))
          WHERE (EXISTS ( SELECT 1
                   FROM "holdings_summary" "hs_1"
                  WHERE (("hs_1"."book_id" = "h"."book_id") AND ("hs_1"."bibliotecas_count" = 1))))
        ), "holding_library_names" AS (
         SELECT "h"."book_id",
            "jsonb_agg"(COALESCE("l"."short_name", "l"."name", "l"."slug") ORDER BY "l"."name") AS "holding_library_names_json"
           FROM ("public"."book_holdings" "h"
             JOIN "public"."libraries" "l" ON (("l"."id" = "h"."library_id")))
          GROUP BY "h"."book_id"
        )
 SELECT "b"."id",
    "b"."id" AS "book_id",
    "b"."bib_ref",
    "b"."autor",
    "b"."titulo",
    "b"."ano",
    "b"."editora",
    "b"."cdd",
    COALESCE("b"."loanable", true) AS "loanable",
    COALESCE("hs"."global_available_count", 0) AS "available_count",
    "b"."created_at",
    "b"."cover_object_path",
    "b"."subtitulo",
    "b"."edicao",
    "b"."local_publicacao",
    "b"."isbn",
    "b"."issn",
    "b"."idioma",
    "b"."tipo_material",
    "b"."colecao",
    "b"."assuntos",
    "fa"."author_id",
    "b"."catalog_source",
        CASE
            WHEN ("hs"."bibliotecas_count" = 1) THEN "sl"."library_id"
            ELSE NULL::"uuid"
        END AS "library_id",
        CASE
            WHEN ("hs"."bibliotecas_count" = 1) THEN "sl"."library_slug"
            ELSE NULL::"text"
        END AS "library_slug",
        CASE
            WHEN ("hs"."bibliotecas_count" = 1) THEN "sl"."library_name"
            ELSE NULL::"text"
        END AS "library_name",
        CASE
            WHEN ("hs"."bibliotecas_count" = 1) THEN "sl"."library_name"
            WHEN ("hs"."bibliotecas_count" > 1) THEN (("hs"."bibliotecas_count")::"text" || ' bibliotecas'::"text")
            ELSE NULL::"text"
        END AS "biblioteca",
    COALESCE("df"."has_online_reading", false) AS "has_online_reading",
    COALESCE("c"."author_display", "b"."autor") AS "author_display",
    COALESCE("c"."author_chips", '[]'::"jsonb") AS "author_chips",
    COALESCE("hs"."exemplares_total", 0) AS "exemplares_total",
    COALESCE("hs"."bibliotecas_count", 0) AS "bibliotecas_count",
    COALESCE("hs"."global_available_count", 0) AS "global_available_count",
    COALESCE("hs"."exemplares_total", 0) AS "global_exemplares_total",
    COALESCE("hln"."holding_library_names_json", '[]'::"jsonb") AS "holding_library_names_json"
   FROM (((((("public"."books" "b"
     LEFT JOIN "first_author" "fa" ON (("fa"."book_id" = "b"."id")))
     LEFT JOIN "public"."v_book_authors_canonical" "c" ON (("c"."book_id" = "b"."id")))
     LEFT JOIN "holdings_summary" "hs" ON (("hs"."book_id" = "b"."id")))
     LEFT JOIN "single_library" "sl" ON (("sl"."book_id" = "b"."id")))
     LEFT JOIN "holding_library_names" "hln" ON (("hln"."book_id" = "b"."id")))
     LEFT JOIN "digital_flags" "df" ON (("df"."book_id" = "b"."id")));


ALTER VIEW "public"."v_books_catalog_list_v1" OWNER TO "postgres";


COMMENT ON VIEW "public"."v_books_catalog_list_v1" IS 'Vue allégée pour la grille catalogue (Phase B.5). Pas de holding_libraries_json détaillé, pas de tombos, pas d''earliest_due_back_at, pas d''authors_json complet. Utiliser v_book_detail_public_v2 pour la page détail.';



CREATE OR REPLACE VIEW "public"."v_catalog_books_editable" WITH ("security_invoker"='true') AS
 WITH "holdings_source" AS (
         SELECT "h"."id" AS "holding_id",
            "h"."book_id",
            "b_1"."bib_ref" AS "book_bib_ref",
            COALESCE(NULLIF(TRIM(BOTH FROM "h"."local_bib_ref"), ''::"text"), "b_1"."bib_ref") AS "local_bib_ref",
            "h"."library_id",
            "l"."slug" AS "library_slug",
            "l"."name" AS "library_name",
            "l"."short_name",
            "l"."city",
            "l"."state",
            COALESCE("h"."loanable", "b_1"."loanable", true) AS "holding_loanable",
            COALESCE("h"."exemplares_total", 0) AS "holding_exemplares_total",
            COALESCE("h"."available_count", 0) AS "holding_available_count"
           FROM (("public"."book_holdings" "h"
             JOIN "public"."books" "b_1" ON (("b_1"."id" = "h"."book_id")))
             JOIN "public"."libraries" "l" ON (("l"."id" = "h"."library_id")))
        ), "exemplares_by_holding" AS (
         SELECT "e"."holding_id",
            ("count"(*))::integer AS "exemplares_total_real",
            "jsonb_agg"("e"."tombo" ORDER BY "e"."tombo") FILTER (WHERE (NULLIF(TRIM(BOTH FROM COALESCE("e"."tombo", ''::"text")), ''::"text") IS NOT NULL)) AS "tombos_json"
           FROM "public"."exemplares" "e"
          WHERE ("e"."holding_id" IS NOT NULL)
          GROUP BY "e"."holding_id"
        ), "holdings_enriched" AS (
         SELECT "hs"."holding_id",
            "hs"."book_id",
            "hs"."book_bib_ref",
            "hs"."local_bib_ref",
            "hs"."library_id",
            "hs"."library_slug",
            "hs"."library_name",
            "hs"."short_name",
            "hs"."city",
            "hs"."state",
            "hs"."holding_loanable",
            "hs"."holding_exemplares_total",
            "hs"."holding_available_count",
            COALESCE("hs"."holding_exemplares_total", "exh"."exemplares_total_real", 0) AS "holding_exemplares_total_final",
            COALESCE("exh"."tombos_json", '[]'::"jsonb") AS "tombos_json"
           FROM ("holdings_source" "hs"
             LEFT JOIN "exemplares_by_holding" "exh" ON (("exh"."holding_id" = "hs"."holding_id")))
        ), "holdings_rollup_by_book" AS (
         SELECT "he"."book_id",
            (COALESCE("sum"("he"."holding_exemplares_total_final"), (0)::bigint))::integer AS "total_exemplares",
            ("count"(*))::integer AS "bibliotecas_count",
            (COALESCE("sum"("he"."holding_available_count"), (0)::bigint))::integer AS "total_available_count_local",
            "jsonb_agg"("jsonb_build_object"('holding_id', "he"."holding_id", 'library_id', "he"."library_id", 'library_slug', "he"."library_slug", 'library_name', "he"."library_name", 'short_name', "he"."short_name", 'city', "he"."city", 'state', "he"."state", 'local_bib_ref', "he"."local_bib_ref", 'loanable', "he"."holding_loanable", 'available_count', "he"."holding_available_count", 'exemplares_total', "he"."holding_exemplares_total_final", 'tombos_json', "he"."tombos_json") ORDER BY "he"."library_name", "he"."library_slug", "he"."holding_id") AS "holding_libraries_json",
            "jsonb_agg"(COALESCE(NULLIF(TRIM(BOTH FROM "he"."library_name"), ''::"text"), NULLIF(TRIM(BOTH FROM "he"."short_name"), ''::"text"), "upper"("he"."library_slug")) ORDER BY "he"."library_name", "he"."library_slug", "he"."holding_id") FILTER (WHERE (COALESCE(NULLIF(TRIM(BOTH FROM "he"."library_name"), ''::"text"), NULLIF(TRIM(BOTH FROM "he"."short_name"), ''::"text"), NULLIF(TRIM(BOTH FROM "he"."library_slug"), ''::"text")) IS NOT NULL)) AS "holding_library_names_json"
           FROM "holdings_enriched" "he"
          GROUP BY "he"."book_id"
        )
 SELECT "b"."id",
    "b"."cdd",
    "b"."autor",
    "b"."titulo",
    "b"."ano",
    "b"."editora",
    "b"."available_count",
    "b"."created_at",
    "b"."bib_ref",
    "b"."loanable",
    "b"."subtitulo",
    "b"."edicao",
    "b"."local_publicacao",
    "b"."isbn",
    "b"."issn",
    "b"."idioma",
    "b"."paginas",
    "b"."notas",
    "b"."tipo_material",
    "b"."cover_object_path",
    "b"."marc_json",
    "b"."catalog_source",
    "b"."created_by",
    "b"."updated_by",
    "b"."updated_at",
    "b"."last_cataloged_at",
    "b"."titulo_periodico",
    "b"."volume",
    "b"."numero",
    "b"."fasciculo",
    "b"."data_edicao",
    "b"."periodicidade",
    "b"."autores_secundarios",
    "b"."colecao",
    "b"."assuntos",
    "b"."tradutor",
    "b"."organizador",
    COALESCE("hr"."total_exemplares", 0) AS "total_exemplares",
    "b"."acquisition_mode",
    "b"."acquisition_date",
    "b"."owner_library",
    "b"."holder_library",
    "b"."owner_library_id",
    "b"."holder_library_id",
    "b"."partner_source",
    "b"."source_record_id",
    "b"."source_record_url",
    "b"."import_format",
    "b"."import_method",
    "b"."provenance_note",
    "b"."mutualization_status",
    "b"."source_label",
    "b"."tract_campaign",
    "b"."emitter_org",
    "b"."approximate_date",
    "b"."diffusion_place",
    "b"."recto_verso",
    "b"."physical_format",
    "b"."print_technique",
    "b"."physical_state",
    "b"."audio_duration",
    "b"."audio_support",
    "b"."audio_format",
    "b"."audio_language",
    "b"."audio_participants",
    "b"."audio_recording_type",
    "b"."audiovisual_duration",
    "b"."audiovisual_support",
    "b"."audiovisual_language",
    "b"."audiovisual_director",
    "b"."audiovisual_participants",
    "b"."audiovisual_subtitles",
    "b"."audiovisual_access_note",
    "b"."digital_native_url",
    "b"."digital_native_access",
    "b"."digital_native_restriction",
    "b"."digital_native_usage",
    "b"."digital_native_file_note",
    "b"."dossier_scope",
    "b"."dossier_period",
    "b"."dossier_organizations",
    "b"."dossier_context",
    COALESCE("hr"."bibliotecas_count", 0) AS "bibliotecas_count",
    COALESCE("hr"."holding_libraries_json", '[]'::"jsonb") AS "holding_libraries_json",
    COALESCE("hr"."holding_library_names_json", '[]'::"jsonb") AS "holding_library_names_json",
    COALESCE("hr"."total_available_count_local", 0) AS "total_available_count_local"
   FROM ("public"."books" "b"
     LEFT JOIN "holdings_rollup_by_book" "hr" ON (("hr"."book_id" = "b"."id")));


