CREATE OR REPLACE VIEW "public"."v_exemplar_drafts_resolved" WITH ("security_invoker"='true') AS
 WITH "base" AS (
         SELECT "d"."id",
            "d"."published_exemplar_id",
            "d"."batch_id",
            "d"."action",
            "d"."status",
            "d"."label_status",
            "d"."target_bib_ref",
            "d"."tombo",
            "d"."shelf_location",
            "d"."label_title_override",
            "d"."label_author_override",
            "d"."label_cdd_override",
            "d"."label_note",
            "d"."notes",
            "d"."created_at",
            "d"."updated_at",
            "d"."created_by",
            "d"."updated_by",
            "d"."target_library_id",
            "d"."target_holding_id",
            "e"."library_id" AS "exemplar_library_id",
            "e"."holding_id" AS "exemplar_holding_id"
           FROM ("public"."exemplar_drafts" "d"
             LEFT JOIN "public"."exemplares" "e" ON (("e"."id" = "d"."published_exemplar_id")))
        )
 SELECT "b"."id",
    "b"."published_exemplar_id",
    "b"."batch_id",
    "b"."action",
    "b"."status",
    "b"."label_status",
    "b"."target_bib_ref",
    "b"."target_library_id",
    "b"."target_holding_id",
    "b"."tombo",
    "b"."shelf_location",
    "b"."label_title_override",
    "b"."label_author_override",
    "b"."label_cdd_override",
    "b"."label_note",
    "b"."notes",
    "b"."created_at",
    "b"."updated_at",
    "b"."created_by",
    "b"."updated_by",
    COALESCE("b"."target_library_id", "b"."exemplar_library_id") AS "resolved_library_id",
    COALESCE("b"."target_holding_id", "b"."exemplar_holding_id", "rb"."holding_id") AS "resolved_holding_id",
    COALESCE(NULLIF(TRIM(BOTH FROM "h"."local_bib_ref"), ''::"text"), "rb"."local_bib_ref", "b"."target_bib_ref") AS "resolved_reference_code",
    COALESCE("book_h"."bib_ref", "rb"."book_bib_ref", "b"."target_bib_ref") AS "resolved_book_bib_ref",
        CASE
            WHEN ("b"."target_holding_id" IS NOT NULL) THEN 'draft_target_holding_id'::"text"
            WHEN ("b"."exemplar_holding_id" IS NOT NULL) THEN 'published_exemplar_holding_id'::"text"
            WHEN ("rb"."holding_id" IS NOT NULL) THEN "rb"."match_kind"
            ELSE 'unresolved'::"text"
        END AS "bridge_source"
   FROM ((("base" "b"
     LEFT JOIN "public"."book_holdings" "h" ON (("h"."id" = COALESCE("b"."target_holding_id", "b"."exemplar_holding_id"))))
     LEFT JOIN "public"."books" "book_h" ON (("book_h"."id" = "h"."book_id")))
     LEFT JOIN LATERAL "public"."resolve_library_holding_bridge"(COALESCE("b"."target_library_id", "b"."exemplar_library_id"), "b"."target_bib_ref") "rb"("holding_id", "book_id", "local_bib_ref", "book_bib_ref", "resolved_bib_ref", "match_kind") ON (((COALESCE("b"."target_holding_id", "b"."exemplar_holding_id") IS NULL) AND (COALESCE("b"."target_library_id", "b"."exemplar_library_id") IS NOT NULL))));


ALTER VIEW "public"."v_exemplar_drafts_resolved" OWNER TO "postgres";


COMMENT ON VIEW "public"."v_exemplar_drafts_resolved" IS 'Passe 42 backend phase 3: surface résolue des brouillons d exemplaires. Le pivot métier devient target_holding_id/target_library_id, target_bib_ref restant un cache de compatibilité.';



CREATE OR REPLACE VIEW "public"."v_catalog_queue" WITH ("security_invoker"='true') AS
 SELECT 'book'::"text" AS "item_type",
    "d"."id" AS "draft_id",
    "d"."batch_id",
    "d"."status",
    "d"."action",
    "d"."bib_ref" AS "reference_code",
    "d"."titulo" AS "display_title",
    COALESCE("d"."autor", "d"."subtitulo", ''::"text") AS "display_subtitle",
    "d"."updated_at"
   FROM "public"."book_drafts" "d"
UNION ALL
 SELECT 'author'::"text" AS "item_type",
    "d"."id" AS "draft_id",
    "d"."batch_id",
    "d"."status",
    "d"."action",
    COALESCE("d"."sort_name", "d"."preferred_name", ("d"."id")::"text") AS "reference_code",
    "d"."preferred_name" AS "display_title",
    COALESCE("d"."country", "d"."source_label", "d"."source_kind", ''::"text") AS "display_subtitle",
    "d"."updated_at"
   FROM "public"."author_drafts" "d"
UNION ALL
 SELECT 'exemplar'::"text" AS "item_type",
    "d"."id" AS "draft_id",
    "d"."batch_id",
    "d"."status",
    "d"."action",
    "d"."resolved_reference_code" AS "reference_code",
    "d"."tombo" AS "display_title",
    COALESCE("d"."label_title_override", "d"."label_author_override", "d"."resolved_book_bib_ref", ''::"text") AS "display_subtitle",
    "d"."updated_at"
   FROM "public"."v_exemplar_drafts_resolved" "d";


ALTER VIEW "public"."v_catalog_queue" OWNER TO "postgres";


COMMENT ON VIEW "public"."v_catalog_queue" IS 'Passe 42 backend phase 3: a fila editorial relit désormais les exemplaires via v_exemplar_drafts_resolved. target_bib_ref ne sert plus de pont principal dans la vue.';



