    "vam"."last_payment_method",
    "vam"."days_until_expiry",
    "p"."email",
    "p"."first_name",
    "p"."last_name",
    "p"."public_id",
    COALESCE(NULLIF(TRIM(BOTH FROM (("p"."first_name" || ' '::"text") || COALESCE("p"."last_name", ''::"text"))), ''::"text"), "p"."email") AS "display_name",
    "p"."is_restricted"
