CREATE OR REPLACE VIEW "public"."v_terra_livre_books_ready" AS
 SELECT "id" AS "staging_id",
    "source_seq",
    "source_pdf",
    "source_item_type",
    NULLIF("btrim"("titulo"), ''::"text") AS "titulo",
    NULLIF("btrim"("subtitulo"), ''::"text") AS "subtitulo",
    NULLIF("btrim"("autores_raw"), ''::"text") AS "autores_raw",
    NULLIF("btrim"("responsabilidades_secundarias_raw"), ''::"text") AS "responsabilidades_secundarias_raw",
    NULLIF("btrim"("editora"), ''::"text") AS "editora",
    NULLIF("btrim"("local_publicacao"), ''::"text") AS "local_publicacao",
    NULLIF("btrim"("ano_publicacao"), ''::"text") AS "ano_publicacao",
    NULLIF("btrim"("idioma"), ''::"text") AS "idioma",
    NULLIF("btrim"("isbn"), ''::"text") AS "isbn",
        CASE
            WHEN (NULLIF("regexp_replace"(COALESCE("paginas_raw", ''::"text"), '[^0-9]+'::"text", ''::"text", 'g'::"text"), ''::"text") ~ '^[0-9]+$'::"text") THEN ("regexp_replace"(COALESCE("paginas_raw", ''::"text"), '[^0-9]+'::"text", ''::"text", 'g'::"text"))::integer
            ELSE NULL::integer
        END AS "paginas",
    NULLIF("btrim"("colecao_raw"), ''::"text") AS "colecao",
    NULLIF("btrim"("edicao_raw"), ''::"text") AS "edicao",
    NULLIF("btrim"("assuntos_raw"), ''::"text") AS "assuntos",
    NULLIF("btrim"("resumo"), ''::"text") AS "resumo",
    NULLIF("btrim"("nota_raw"), ''::"text") AS "nota_raw",
    NULLIF("btrim"("url_raw"), ''::"text") AS "url_raw",
    ('BTL-TL-'::"text" || "lpad"(("source_seq")::"text", 6, '0'::"text")) AS "bib_ref",
    ('BTL-TL-EX-'::"text" || "lpad"(("source_seq")::"text", 6, '0'::"text")) AS "tombo",
    "public"."norm_match_text"(NULLIF("btrim"("titulo"), ''::"text")) AS "titulo_norm",
    "public"."norm_match_text"("split_part"(NULLIF("btrim"("autores_raw"), ''::"text"), ';'::"text", 1)) AS "primeiro_autor_norm",
    ((NULLIF("btrim"("titulo"), ''::"text") IS NOT NULL) AND (NULLIF("btrim"("autores_raw"), ''::"text") IS NOT NULL)) AS "elegivel_catalogo_publico"
   FROM "public"."import_terra_livre_zotero_staging" "s";


ALTER VIEW "public"."v_terra_livre_books_ready" OWNER TO "postgres";


CREATE OR REPLACE VIEW "public"."v_terra_livre_books_ready_stats" AS
 SELECT "count"(*) AS "staging_total",
    "count"(*) FILTER (WHERE "elegivel_catalogo_publico") AS "elegiveis_catalogo_publico",
    "count"(*) FILTER (WHERE (NOT "elegivel_catalogo_publico")) AS "inelegiveis_catalogo_publico",
    "count"(*) FILTER (WHERE ("isbn" IS NOT NULL)) AS "com_isbn",
    "count"(*) FILTER (WHERE ("idioma" IS NOT NULL)) AS "com_idioma",
    "count"(*) FILTER (WHERE ("ano_publicacao" IS NOT NULL)) AS "com_ano",
    "count"(*) FILTER (WHERE ("editora" IS NOT NULL)) AS "com_editora"
   FROM "public"."v_terra_livre_books_ready";


ALTER VIEW "public"."v_terra_livre_books_ready_stats" OWNER TO "postgres";


