CREATE OR REPLACE VIEW "public"."authors_with_translations" WITH ("security_invoker"='true') AS
 SELECT "a"."id",
    "a"."preferred_name",
    "a"."sort_name",
    "a"."biography",
    "a"."birth_year",
    "a"."death_year",
    "a"."country",
    "a"."source_kind",
    "a"."source_label",
    "a"."source_url",
    "a"."viaf_id",
    "a"."isni",
    "a"."wikidata_id",
    "a"."photo_object_path",
    "a"."notes",
    "a"."created_at",
    "a"."updated_at",
    "a"."created_by",
    "a"."updated_by",
    COALESCE("jsonb_object_agg"("t"."lang", "t"."biography") FILTER (WHERE ("t"."lang" IS NOT NULL)), '{}'::"jsonb") AS "biography_i18n"
   FROM ("public"."authors" "a"
     LEFT JOIN "public"."author_translations" "t" ON (("t"."author_id" = "a"."id")))
  GROUP BY "a"."id";



